import{bU as s}from"./index-Do5jXPq-.js";const z={"confidence-1":{kind:"compare",title:"Etiketten durum tarifine",left:{label:"Etiket",items:["Ben yetersizim.","Ben hep başarısızım.","Ben böyle bir insanım."]},right:{label:"Durum tarifi",items:["Konuşurken heyecanlanıyorum.","Bu konuşmada gerildim.","Toplantıda fikir söylerken çekiniyorum."]},note:"Sağdaki cümleler duyguyu inkâr etmez; değiştirilebilir bir sonraki adıma yer açar."},"confidence-2":{kind:"table",title:"Aynı işin üç sürümü",columns:["Sürüm","Örnek deneme"],rows:[["Kolay","Bir soruyu önceden hazırlamak"],["Orta","Güvendiğin bir kişiye fikrini anlatmak"],["Zor","Herkesin önünde konuşmak"],["Senin işin","Kolay: … / Orta: … / Zor: …"]],note:"Bugün güvenle deneyebileceğin en küçük sürümü seç. Rahatsızlık fazla yükselirse durabilir veya adımı küçültebilirsin."},"confidence-3":{kind:"compare",title:"Kamera ne görürdü?",left:{label:"Tahmin",items:["Herkes benimle alay etti.","Herkes gerildiğimi fark etti.","Ben böyle bir insanım."]},right:{label:"Gözlem",items:["Sorumu sordum.","Bir kişi yanıt verdi.","Sesim titredi ama sorumu sordum."]},note:"Kimin ne düşündüğünü varsaymak yerine görülen ve duyulanı kaydet. Bu kayıt bir performans notu değildir."},"confidence-4":{kind:"steps",title:"Sert iç sesten destek cümlesine",steps:[{label:"Fark et",text:"Sert cümleyi gör; tekrar tekrar okumak zorunda değilsin."},{label:"Kabul et",text:"“Bu benim için zordu.”"},{label:"Adil konuş",text:"“Hata yaptım; düzeltilecek kısmı belirleyebilirim.”"},{label:"Tek adım",text:"Özür dile, bilgiyi kontrol et veya not hazırla."}],note:"Kendine iyi davranmak sorumluluktan vazgeçmek değildir; abartılı olumlamaya da gerek yok."},"confidence-5":{kind:"table",title:"Cesaret planı şablonu",columns:["Plan parçası","Senin yanıtın"],rows:[["Deneme","Tek güvenli davranış ve zamanı: …"],["Başlangıç planı","“Ertelemek istersem, önce … yapacağım.”"],["Değerlendirme","Denemeden sonra iki dakika: ne oldu?"],["Destek","Gerektiğinde ulaşabileceğin kişi: …"],["Dinlenme","Mola vereceğin an: …"]],note:"Bir gün deneme yapmaman ilerlemeyi silmez. İşe yaramayan adımı değiştirebilirsin."},"adhd-1":{kind:"steps",title:"Zihinden tek bir dış kayda",steps:[{label:"Yer seç",text:"Kâğıt, telefon notu veya ODA defteri: yalnızca biri."},{label:"Aktar",text:"Aklındaki en fazla beş işi yaz; hepsi bugün bitmeyecek."},{label:"Saatliler",text:"Randevu gibi saatli işleri takvime ekle."},{label:"Kontrol",text:"Listeye ne zaman bakacağını belirle."}],note:"Dış kayıt, hafızanın yükünü azaltmak için bir araçtır; tanı veya tedavi değildir."},"adhd-2":{kind:"compare",title:"Belirsiz görev ve görünen hareket",left:{label:"Belirsiz görev",items:["Dosyaları hallet.","Hayatımı düzene sokmak.","Daha disiplinli olmak."]},right:{label:"İlk görünen hareket",items:["Mavi klasörü aç, ilk belgenin adını yaz.","Ödeme belgesini aç, son tarihi kontrol et."]},note:"Açık bir fiil ve nesne, elinin ilk ne yapacağını gösterir. Takılırsan hareketi daha da küçült."},"adhd-3":{kind:"table",title:"Tahmin ve gerçek süre",columns:["Deneme","Tahmin","Gerçek süre","Sonraki aralık"],rows:[["1. aralık","… dk","… dk","… dk"],["2. aralık","… dk","… dk","… dk"],["3. aralık","… dk","… dk","… dk"]],note:"İki, beş veya on dakika gibi rahat bir başlangıç seçebilirsin. Bu ideal odak süresi değil, bir denemedir."},"adhd-4":{kind:"steps",title:"Dikkat dağıldığında geri dönüş",steps:[{label:"Fark et",text:"Aklına başka bir iş geldi."},{label:"Acil mi?",text:"Acil veya güvenlikle ilgiliyse bekletme."},{label:"Not al",text:"Değilse birkaç kelimeyle “sonra” alanına yaz."},{label:"İzi bul",text:"Kaldığın yeri parmağınla veya bir işaretle bul."},{label:"Dön",text:"Önündeki işte bir hareket daha dene."}],note:"Kaç kez dağıldığını saymak zorunda değilsin; önemli olan geri dönüş için bir iz bırakmak."},"adhd-5":{kind:"table",title:"Aracı sana uydur",columns:["Zorlanan nokta","Tek değişiklik"],rows:[["Liste görünür değildi","Daha görünür bir kayıt yeri seç"],["Liste çok uzundu","Daha kısa bir liste dene"],["Kontrol saati uymadı","Başka bir saat dene"]],note:"Gelecek üç denemede yalnızca bir şeyi değiştir. Güçlükler günlük yaşamını belirgin etkiliyorsa bir sağlık uzmanıyla konuşabilirsin."},"motivation-1":{kind:"compare",title:"Hedefi netleştiren sorular",left:{label:"Dışarıya bakan soru",items:["Herkes beni nasıl görür?","En iddialı hedef hangisi?"]},right:{label:"Sana ait soru",items:["Bunu yapınca günümde ne değişsin istiyorum?","Kimse görmese de bunu ister miydim?"]},note:"Önemini kaybetmiş bir hedefi küçültmek veya bırakmak da bir seçimdir."},"motivation-2":{kind:"table",title:"Başlangıcı küçült",columns:["Hedef davranış","Kısa sürüm","Hazırlık"],rows:[["Her akşam bir bölüm okumak","Bir sayfa okumak veya kitabı açmak","Kitabı görünür yere koymak"],["Senin hedefin: …","Kısa sürüm: …","Tek malzeme: …"]],note:"Kısa sürüm bir alt sınırdır, tavan değil; istersen devam edebilirsin. Sonuç garantisi değil, bir başlangıç tasarımıdır."},"motivation-3":{kind:"steps",title:"Niyetine bir başlangıç anı ver",steps:[{label:"İşaret",text:"Gününde zaten olan bir an: “Akşam çayını koyunca…”"},{label:"Davranış",text:"“…kitabı açacağım.”"},{label:"Deneme",text:"İşaretin geldiği ilk uygun anda kısa sürümü dene."},{label:"Gözlem",text:"İşaret işe yaradı mı? Gerekirse başka bir an seç."}],note:"Alışkanlığın oluşma süresi herkes için aynı değildir. Bugün yalnızca başlangıç işaretini sınıyorsun."},"motivation-4":{kind:"bars",title:"Engel + eğer/o zaman planı: ortalama etki",bars:[{label:"Wang ve ark. 2021 · 21 çalışma",value:.336,display:"g = 0,336"}],note:"Hedefi gerçek engelle karşılaştırıp eğer/o zaman planı kurmanın ortalama etkisi küçük–orta düzeydeydi. Yayın yanlılığı olası; bu bir ortalamadır, kişisel garanti değildir.",sourceId:"mcii"},"motivation-5":{kind:"table",title:"Haftalık kısa kontrol",columns:["Hafta","Yaptım / kısmen / yapamadım","Yardımcı olan","Tek değişiklik"],rows:[["1. hafta","…","…","…"],["2. hafta","…","…","…"],["3. hafta","…","…","…"]],note:"Kaçırılan günleri iki katıyla telafi etmen gerekmez. Bir sonraki uygun işarette küçük sürümle dönebilirsin."},"faith-1":{kind:"steps",title:"Niyetten küçük bir emeğe",steps:[{label:"İş",text:"Bugün yapacağın sıradan bir işi seç."},{label:"Niyet",text:"Bu iş kime ve nasıl fayda sağlasın istiyorsun?"},{label:"Hazırlık",text:"Niyetini davranışa bağlayan küçük bir adım at."}],note:"Kaynak: Sahîh-i Buhârî 1, niyet hadisi. Bu adımlar hadisin sözleri değil, ODA’nın günlük uygulama uyarlamasıdır."},"faith-2":{kind:"compare",title:"Hazırlık ve tevekkül",left:{label:"Elimden gelen hazırlık",items:["Konuyu çalışmak","Anlamadığım yeri sormak","Güvendiğim birinden görüş almak"]},right:{label:"Kontrolümün dışında",items:["Sınavın sonucu","Sonucun istediğim gibi olması"]},note:"Âl-i İmrân 3:159’un istişare, karar ve tevekkül vurgusundan hareketle ODA yorumudur; sonuç vaat etmez."},"faith-3":{kind:"table",title:"Teşekkür notu şablonu",columns:["Parça","Senin notun"],rows:[["Kime?","Güvenli bir kişi veya küçük bir iyilik: …"],["Ne yaptı?","“Şunu yaptığında…”"],["Nasıl yardımcı oldu?","“…bana şu konuda yardımcı oldun.”"],["Seçimin","Kendine sakla veya uygunsa ilet."]],note:"Şükretmek sıkıntıyı inkâr etmek değildir; hem yorgun hem minnettar olabilirsin."},"faith-4":{kind:"steps",title:"Bugün için bir dayanak",steps:[{label:"Kabul et",text:"Zorlandığını fark et; bu bir kusur değildir."},{label:"Adlandır",text:"“Bugün … desteğine ihtiyacım var.”"},{label:"Seç",text:"Dua, güvendiğin biri, dinlenme veya uzman desteği."},{label:"Yaklaş",text:"Bu desteğe doğru küçük bir adım at."}],note:"İnşirâh 94:5–6 üzerine düşünmekten hareketle ODA uygulamasıdır; sıkıntının ne zaman biteceğine dair vaat içermez."},"faith-5":{kind:"table",title:"Küçük iyilik planı",columns:["Küçük iyilik","Ne zaman / nerede?","Sonra ne fark ettin?"],rows:[["Birini dikkatle dinlemek","…","…"],["Ortak alanı düzenlemek","…","…"],["Verilen sözü takip etmek","…","…"]],note:"Sınırlarına uygun, ücretsiz ve gönüllü bir davranış seç; karşılık beklemeyi şart koşma."},"manifest-1":{kind:"compare",title:"Dilekten davranışa",left:{label:"Sonuç isteği",items:["Daha iyi bir iş istiyorum.","İşverenin beni kesin seçmesi","Hiç aksilik yaşanmaması"]},right:{label:"Davranış hedefi",items:["Bu hafta özgeçmişimin ilk bölümünü düzenlemek","Yarın üç satır taslak yazmak"]},note:"Başkalarının kararını garanti edemezsin; kendi hazırlığını somutlaştırabilirsin."},"manifest-2":{kind:"steps",title:"Sonuçtan ilk harekete prova",steps:[{label:"Anlam",text:"Sonuca ulaşmak senin için ne ifade ederdi?"},{label:"Yer",text:"Bugün nerede oturuyorsun?"},{label:"Araç",text:"Hangi dosyayı açıyorsun?"},{label:"İlk satır",text:"İlk satırda ne yazıyorsun?"},{label:"Gerçek adım",text:"Provadan sonra bir hazırlığı gerçekten yap."}],note:"Görüntü oluşmuyorsa adımları kelimelerle tarif etmen yeterli. Prova, gerçek denemenin yerini almaz."},"manifest-3":{kind:"table",title:"Engeli dürüstçe ayrıştır",columns:["Engel","Türü","Olası yanıt"],rows:[["Başlamakta çekinmek","İçsel","Adımı küçültmek"],["Plan çok büyük","Plan","Hedefin boyutunu küçültmek"],["Gereken bilgiye erişememek","Erişim","Destek istemek"],["Zaman, para, bakım sorumluluğu","Dış koşul","Zamanlamayı veya boyutu değiştirmek"]],note:"Dış koşullar gerçektir; kişiliğinin kusuru değildir. Sonuçlar yalnızca düşüncelerinle belirlenmez."},"manifest-4":{kind:"steps",title:"İstek → sonuç → engel → plan",steps:[{label:"İstek",text:"Ne istiyorsun? Örn. özgeçmişimin ilk taslağı."},{label:"Sonuç",text:"Olunca senin için ne değişirdi?"},{label:"Engel",text:"“Dosyayı açınca nereden başlayacağımı bilemem.”"},{label:"Plan",text:"“Eğer takılırsam, o zaman yalnızca başlığı yazarım.”"}],note:"Olumlama kullanacaksan gerçekçi olsun: “İlk taslağı deneyebilirim.” Planın değeri, seçtiğin davranışı hatırlatmasında."},"manifest-5":{kind:"bars",title:"İlerlemeyi izlemek: ortalama etki",bars:[{label:"Harkin ve ark. 2016 · 138 çalışma",value:.4,display:"d = 0,40"}],note:"İlerlemeyi izlemeyi artıran müdahalelerin hedefe ulaşmadaki ortalama etkisidir; farklı hedef ve yöntemler birleştirildi. Bu tek alıştırma için etki veya sonuç garantisi anlamına gelmez.",sourceId:"monitoring"}},S=[{id:"fresh-start-effect",title:"Dai, Milkman & Riis · 2014 · The fresh-start effect",url:"https://faculty.wharton.upenn.edu/wp-content/uploads/2014/06/Dai_Fresh_Start_2014_Mgmt_Sci.pdf",type:"research",finding:"Across three sets of field data, goal-directed behavior rose at the start of new time periods: Google searches for “diet” rose 14.4% at the start of a week and 82.1% at the start of a year; gym visits by 11,912 university students rose 33.4% at the start of a week and 47.1% at the start of a semester; new goal commitments on the stickK website rose 62.9% at the start of a week and 145.3% at the start of a year.",limitation:"Observational field data that do not test the mechanism directly; they mostly look at shared calendar landmarks and do not show how long the extra drive lasts. The authors note that the rise after public holidays faded quickly."},{id:"fresh-start-framing",title:"Dai, Milkman & Riis · 2015 · Temporal landmarks and goal initiation experiments",url:"https://anderson-review.ucla.edu/wp-content/uploads/2021/03/Dai-Milkman-Riis_2015_TemporalLandmarks_APS_0956797615605818.pdf",type:"research",finding:"In five experiments, framing a day as a fresh start increased the wish to begin on a goal: among 165 participants, 25.6% chose a goal reminder for March 20 when it was presented as “the first day of spring,” versus 7.2% when it was called “the third Thursday in March.” The effect was explained by feeling psychologically distant from one’s past, imperfect self.",limitation:"Short experiments with online participants; the measures are mostly intentions, reminder choices and hypothetical scenarios. They do not show real, lasting behavior change."},{id:"bandura-self-efficacy",title:"Bandura · 1977 · The theory of self-efficacy",url:"https://eric.ed.gov/?id=EJ161632",type:"research",finding:"Bandura proposes that psychological change works through self-efficacy, the expectation that you can carry out a behavior, and names four sources of that expectation: mastery experiences, watching others (vicarious experience), verbal persuasion and physiological state. He treats mastery experiences as the most powerful source because they rest on personal accomplishment, and writes that a belief strengthened by repeated success is less shaken by occasional failure.",limitation:"A theoretical article in Psychological Review; it reports no new experiment or effect size and draws largely on fear-treatment studies of its time."},{id:"self-efficacy-work-meta",title:"Stajkovic & Luthans · 1998 · Meta-analysis of self-efficacy and work performance",url:"https://doi.org/10.1037/0033-2909.124.2.240",type:"research",finding:"A meta-analysis pooling 114 studies (157 effect sizes, 21,616 people) found a significant, moderate relationship between self-efficacy and work performance (weighted average r = 0.38).",limitation:"Abstract only. A correlational finding; on its own it does not show how far self-efficacy causes performance, and it comes from work tasks."},{id:"todo-list-bedtime",title:"Scullin et al. · 2018 · Writing a to-do list before bed and falling asleep",url:"https://pmc.ncbi.nlm.nih.gov/articles/PMC5758411/",type:"research",finding:"In a sleep lab, 57 healthy young adults aged 18–30 spent 5 minutes before bed writing either the tasks they needed to do in the coming days or the tasks they had completed in recent days. Those who wrote a to-do list fell asleep faster, and the more specific the list, the faster they fell asleep.",limitation:"A single lab night with a small, young sample; it does not show whether the same happens for people with insomnia or over the long term. Abstract only."},{id:"franklin-daily-questions",title:"Benjamin Franklin · Autobiography · Morning and evening questions",url:"https://www.gutenberg.org/ebooks/20203",type:"technique",finding:"As part of his plan for tracking his virtues, Franklin describes a schedule that organizes his day hour by hour: on rising and planning the day’s business he asks, “What good shall I do this day?”, and when reviewing the day in the evening, “What good have I done today?”",limitation:"A public-domain, historical first-person account; not a scientifically tested method."},{id:"oettingen-woop-method",title:"Gabriele Oettingen · WOOP · Rethinking Positive Thinking (2014)",url:"https://woopmylife.org/en/home",type:"technique",finding:"Oettingen’s WOOP method has four steps: Wish, Outcome, Obstacle, Plan. Instead of only dreaming positively, it asks you to contrast the outcome you want with the real obstacle in your way and to make an if–then plan for that obstacle.",limitation:"The mental contrasting and if–then planning the method rests on showed small-to-medium average effects in research; the official site belongs to the method’s developers and is not an independent evaluation."},{id:"clear-two-minute-rule",title:"James Clear · The two-minute rule · Atomic Habits (2018)",url:"https://jamesclear.com/how-to-stop-procrastinating",type:"technique",finding:"The rule has two parts: David Allen’s advice to do at once anything that takes less than two minutes, and Clear’s adaptation that a new habit should start with a first step that takes less than two minutes, for example reading one page instead of reading for an hour.",limitation:"A practical suggestion; the rule itself has not been tested directly in controlled studies."},{id:"fogg-anchor-recipe",title:"BJ Fogg · Tiny Habits (2019)",url:"https://tinyhabits.com/",type:"technique",finding:"Fogg, who directs the Behavior Design Lab at Stanford, suggests making a new behavior very small, attaching it right after an “anchor” you already do every day, and celebrating briefly as soon as you have done it.",limitation:"Consistent with findings that repetition in the same context strengthens habits, but the method itself, especially the celebration step, has had limited testing in independent randomized studies."},{id:"seinfeld-chain-story",title:"“Don’t break the chain,” attributed to Jerry Seinfeld · as told by James Clear",url:"https://jamesclear.com/stop-procrastinating-seinfeld-strategy",type:"technique",finding:"In the story, you put a big X on a wall calendar for each day you do the work, and the goal is not to break the chain that forms, shifting attention from any single day’s result to consistency.",limitation:"An anecdote the comedian Brad Isaac told Lifehacker; according to Clear’s note, Seinfeld has said the idea was not his and that he did not claim to use it. The method has not been tested directly."},{id:"habits",title:"Lally et al. · 2010 · Habit formation in everyday life",url:"https://onlinelibrary.wiley.com/doi/10.1002/ejsp.674",type:"research",finding:"Following 96 volunteers for 12 weeks, the study tracked repetition in the same context and growing automaticity; the time it took varied widely between people, and missing a behavior once did not noticeably affect the habit-forming process.",limitation:"An observational study based on self-report; it gives no fixed number of days that holds for everyone. The publisher’s abstract was read."},{id:"turning-day-commitment-contract",title:"Giné, Karlan & Zinman · 2010 · A commitment contract for quitting smoking",url:"https://www.aeaweb.org/articles?id=10.1257%2Fapp.2.4.213",type:"research",finding:"Smokers were offered a savings account: they deposited money for six months and then took a urine test for nicotine and cotinine. If they passed, the money was returned; if not, it went to charity. 11% of those offered the account signed up. Smokers randomly offered it were 3 percentage points more likely to pass the six-month test, and the difference held in surprise tests at 12 months.",limitation:"Abstract only. One field experiment on one behavior (smoking); take-up was low and the average effect small. It shows that a commitment device can help some people, not that it suits everyone."}],B={id:"turning-day",title:"Turning Point Day",subtitle:"One day, the first evidence.",description:"Turn a single day into a real beginning in five short sessions: choose a direction, plan for the obstacle, take the first small step, and turn it into evidence over the next 7 days. Confidence grows from small proof like this.",scope:"Personal growth training for adults. It is not therapy, diagnosis or treatment, and it does not promise that your life will change in a single day. Do not stop any treatment or medication without talking to your doctor. If you are dealing with intense anxiety, low mood or distress that makes daily life hard, please see a health professional; if you have thoughts of harming yourself or are in immediate danger, call your local emergency number.",outcome:"An area you chose and your reason for it, an if–then plan, a first small step taken today, a prepared environment, one supporter, a written evidence note and a 7-day follow-up plan.",photo:{id:"1570821805833-1103c43f9c1d",alt:"Sunbeams falling across a path between trees"},lessons:[{id:"turning-day-1",title:"Morning · Direction: mark today as a beginning",minutes:7,goal:"This morning, mark today as a fresh start and choose one area of life plus a reason that matters to you.",reading:["In 2014, Dai, Milkman and Riis showed that people turn toward their goals more at the start of a new period. Google searches for “diet” rose 14.4% at the start of a week and 82.1% at the start of a year; university gym visits rose 33.4% at the start of a week and 47.1% at the start of a semester. The researchers called this the fresh-start effect. But these are observational data and do not show how long the new drive lasts; the rise after public holidays faded quickly.","In 2015 the same team found that the way a day is named matters too. When March 20 was presented as “the first day of spring,” 25.6% of participants chose a goal reminder for that day; when it was called “the third Thursday in March,” only 7.2% did. So you do not have to wait for the calendar to hand you a special day; you can mark today yourself. These experiments mostly measured intention, though. One day does not change a life; small steps repeated over the next days turn it into evidence. So the morning’s job is not a big promise, but one area and a strong reason."],practice:["Write today’s date and next to it the words “My starting day.”","From areas like health, relationships, work or learning, choose only one for today.","Write why this area matters in one sentence, “Because … matters to me,” and add it to the Today screen in the app as the day’s one decision."],reflection:"When you marked today as a beginning, what changed inside you, and what stayed the same?",question:"What does research on the fresh-start effect show?",options:["The wish to work on a goal can rise at the start of a new period; whether it lasts depends on the steps that follow.","A Monday or a new year guarantees that you reach your goal on its own.","You must wait for a special day on the calendar before you can begin."],correct:0,feedback:"Time landmarks can raise the wish to begin, and you can mark today as a landmark yourself. But that wish was also seen to fade fast; what makes it last is small repetition over the following days.",takeaway:"Today can be a beginning; the following days bring the proof.",sources:["fresh-start-effect","fresh-start-framing","franklin-daily-questions","dispenza-breaking-habit","mental-practice"],visual:{kind:"bars",title:"Same day, different name: who chose a reminder",bars:[{label:"Presented as “the first day of spring”",value:25.61,display:"25.6%"},{label:"Presented as “the third Thursday in March”",value:7.23,display:"7.2%"}],note:"Share of 165 online participants who chose a goal reminder for March 20 (Dai, Milkman and Riis 2015, study 1a). It measures intention and reminder choice, not lasting behavior change.",sourceId:"fresh-start-framing"},deeper:[{heading:"Why a fresh start works",paragraphs:["Dai, Milkman and Riis explain the effect this way: a time landmark, such as a new week, a new year or a day you choose to mark, draws a line between the past and the present. The mistakes of the “old you” feel a little further away, so trying again feels less like repeating a failure and more like opening a new chapter. In their experiments, the very same date drew more goal reminders when it was framed as a beginning.","The same research also shows the weak point: the lift is real but short. Think of it as a wave that helps you push off, not as a current that carries you. That is why this course asks you to use today’s energy for something small and concrete, and then to repeat it tomorrow."],visual:{kind:"compare",title:"Waiting for a landmark or making one",left:{label:"Waiting for Monday",items:["“I’ll start properly next week.”","The drive builds up, then fades before it is used.","A missed day means waiting for the next Monday."]},right:{label:"Marking today",items:["“Today is my starting day.”","The drive is spent on one small, real step.","A missed day means starting again tomorrow morning."]},note:"Framing a day as a fresh start raised the wish to begin in experiments; how long it lasts depends on what you do next."}},{heading:"Common mistakes on a starting day",paragraphs:["The first is choosing everything at once: a new diet, a new exercise plan and a new work routine on the same morning. Several changes compete for the same limited energy, and when one slips, all of them can feel lost. One area is enough for one day.","The second is picking an area because it sounds impressive rather than because it matters to you. A reason that is truly yours (“because I want to keep up with my kids on a walk”) tends to hold up better on a tired afternoon than a borrowed one (“because everyone says I should”). If your reason feels flat when you say it out loud, keep looking for a moment longer."]}],example:{title:"Dana, 34, nurse on rotating shifts",text:"Dana had been “starting on Monday” for months, but her shifts meant Monday was often a night shift. On a Wednesday off, she wrote the date in her notebook with the words “My starting day” next to it. She felt a bit silly. From the long list in her head (sleep, cooking, money, calling her sister) she picked just one: movement. Her reason took a few tries: “Because I want my back to stop aching after a twelve-hour shift.” That one felt true. She added it to her phone as the day’s one decision and did nothing else dramatic. The day did not feel like a turning point yet. But when a colleague asked about her plans, she could name one area and a reason in a single sentence, and that was new."},technique:{name:"The morning question and a “who am I choosing to be today?” rehearsal",origin:"Dr. Joe Dispenza · Breaking the Habit of Being Yourself (2012); morning question: Benjamin Franklin’s daily scheme",steps:["When you wake up, before looking at your phone, sit quietly for 3–5 minutes and take a few slow breaths.","Ask yourself Franklin’s morning question: “What good shall I do this day?”","Notice one old reaction you want to leave behind today and give it a name, such as “the me who puts things off.”","Ask, “Who am I choosing to be today?” and answer with a single quality: calm, brave or organized.","Picture one moment of the day in that state: where you are, what you are doing and how it feels.","When you open your eyes, choose one small action from this rehearsal that you will do today, and write it down."],evidence:"Mental rehearsal can help you prepare for a behavior, especially when it is combined with a real plan. The book’s claims of changing reality through quantum physics or healing illness with thought are not supported by science; place the rehearsal before action, not in place of it.",sourceId:"dispenza-breaking-habit"},photo:{id:"1676475382103-54041209cf6c",alt:"Woman writing notes in a notebook beside a coffee cup"}},{id:"turning-day-2",title:"Midday · See the obstacle, build an if–then plan",minutes:8,goal:"At midday, find a realistic inner obstacle for the area you chose this morning and write an if–then plan for it.",reading:["Psychologist Gabriele Oettingen argues that only picturing the happy outcome can relax you and drain the energy you need to act. Her suggestion is to look, right after imagining the outcome you want, at the real obstacle in your way; this is called mental contrasting. In a meta-analysis by Wang, Wang and Gai covering 21 studies and 15,907 participants, this contrasting, combined with an if–then plan, showed a small-to-medium average effect on reaching goals. Publication bias is possible, and results vary from person to person.","An if–then plan means writing down in advance when and where the obstacle will show up, together with your answer: “If I feel tired in the afternoon, then I will do just the two-minute part.” In Gollwitzer and Sheeran’s meta-analysis of 94 tests, plans like this showed a medium-to-large effect on reaching goals (d = 0.65); analyses that correct for publication bias may shrink that number. The obstacle is often inside rather than outside: tiredness, embarrassment or the thought “I’ll do it later.” Naming it in advance means the moment will not catch you unprepared."],practice:["On a short walk or during your lunch break, say your wish for this morning’s area in one sentence.","Name the inner obstacle most likely to stop you today, such as tiredness, embarrassment or the thought of putting it off.","Complete the sentence “If … happens, then I will …” and save it somewhere on your phone you can find easily."],reflection:"Which inner voice is most likely to stop you today, and what is your ready answer to it?",question:"In WOOP, which step comes after imagining the best outcome?",options:["Imagining the outcome in even more detail and never thinking about obstacles.","Finding the real inner obstacle in your way and writing a plan for it.","Telling no one about the goal so that no obstacle appears."],correct:1,feedback:"In WOOP, the imagined outcome is followed by finding the main inner obstacle and writing an if–then plan for it. Together they showed a small-to-medium average effect in a meta-analysis; not a guarantee, but a way of being prepared.",takeaway:"The dream gives direction; the obstacle plan clears the way.",sources:["mcii","if-then-plans","oettingen-woop-method","turning-day-commitment-contract","fresh-start-effect"],visual:{kind:"compare",title:"Only a dream, or a dream and a plan?",left:{label:"Only a positive dream",items:["Everything will fall into place by itself.","Tomorrow I will be a completely different person.","Obstacles? No need to think about them."]},right:{label:"Dream + obstacle + plan",items:["My wish: a short walk every day this week.","My obstacle: evening tiredness and the thought “I’ll do it tomorrow.”","If I am tired, then I will walk for just 10 minutes."]},note:"Mental contrasting and if–then planning together showed a small-to-medium average effect; this short lesson has not been tested separately."},deeper:[{heading:"Why a plan works better than willpower in the moment",paragraphs:["An if–then plan hands a decision to your past self. At noon, calm and clear-headed, you decide what you will do at six o’clock when you are tired. When six o’clock comes, you do not have to negotiate with yourself; the cue (“I feel tired”) is already linked to a small action (“ten minutes only”). This is why the “if” part works best when it is specific: a time, a place or a feeling you can recognize.","A good plan is also small enough to survive a bad day. “If I’m tired, I’ll do the whole workout anyway” is a promise to a version of you who is not tired. “If I’m tired, I’ll do the two-minute version” is a plan for the person who will actually be there."]},{heading:"Commitment devices: making your plan harder to drop",paragraphs:["A commitment device is a choice you make now that makes it harder for your future self to back out. It can be soft, like telling a friend, or firm, like putting money on the line. In one field experiment, smokers were offered a savings account: they deposited money for six months and then took a nicotine test. If they passed, the money came back; if not, it went to charity. Only 11% of those offered it signed up, but the group offered the account was 3 percentage points more likely to pass the test, and the difference held at surprise tests a year later.","That is a small effect with low take-up, which is an honest picture: commitment devices help some people, some of the time. The fresh-start study found that new commitments on stickK, a website where people sign such contracts, rose at the start of each week and even more at the start of a year. If you like the idea, start with the softest version that still feels real to you."],visual:{kind:"table",title:"Commitment devices, from soft to firm",columns:["Type","Example","What it costs to back out"],rows:[["Word","Tell one supportive person what you will do and when","A slightly awkward conversation"],["Friction","Put the tempting app in a folder on your last phone screen for a week","A few extra taps"],["Pre-payment","Book and pay for a class in advance","Losing the fee"],["Contract","Money you lose if you do not follow through","Losing the deposit"]],note:"Firmer is not always better: choose a device you would be glad to have chosen, and never one that could harm you or someone else."}}],example:{title:"Marcus, 41, warehouse supervisor",text:"Marcus chose health that morning: a short walk after work. At lunch, walking to the sandwich shop, he asked himself what would actually stop him. The honest answer was not rain or time. It was the couch, and the thought “I’ve earned a rest.” He typed into his phone: “If I sit down on the couch before walking, then I’ll stand up and walk just to the corner and back.” It felt almost too small to count. At 6:15 he did sit down, and the thought came right on cue. He remembered the note, grumbled, and walked to the corner. Then he kept going for twelve minutes. The next day he did not go past the corner, and he let that count too."},technique:{name:"WOOP",origin:"Gabriele Oettingen · Rethinking Positive Thinking (2014)",steps:["Set aside a few calm minutes and silence your phone.","Wish: in a few words, write a wish for today or this week that is challenging but reachable.","Outcome: picture vividly the best outcome you will experience when this wish comes true.","Obstacle: find the main obstacle inside you that could stop you, and picture it just as vividly.","Plan: write the sentence “If [obstacle] happens, then I will [action].”","Read the plan once more shortly before the time the obstacle is likely to appear."],evidence:"Using mental contrasting and if–then planning together showed a small-to-medium average effect on reaching goals in a meta-analysis. The effect varies by person and goal; WOOP is not a guarantee of results but a thinking tool that makes it easier to see the obstacle in advance.",sourceId:"oettingen-woop-method"},photo:{id:"1740815897057-a93a8cf98a70",alt:"Woman walking along a tree-lined path in a park"}},{id:"turning-day-3",title:"Afternoon · First evidence: confidence follows the step",minutes:8,goal:"This afternoon, take a two-minute first step in the area you chose and record it as the first evidence for your confidence.",reading:["In 1977 psychologist Albert Bandura introduced the idea of self-efficacy: your belief that you can do a particular thing. According to Bandura, this belief has four sources: your own experiences of success, watching others, encouraging words, and the state of your body. The most powerful is your own success, because it rests directly on what you lived through. So instead of waiting for confidence to arrive, you can produce a small success yourself today.","In Stajkovic and Luthans’s meta-analysis of 114 studies and 21,616 people, self-efficacy and work performance showed a moderate relationship (r = 0.38). This is a relationship; on its own it does not show which causes which, or by how much, and it comes from workplaces. Bandura also writes that a belief strengthened by repeated success is shaken less by occasional setbacks. So today’s goal is not a big achievement but a small, real piece of “I did it” evidence."],practice:["Decide on the smallest first step in your area that can be finished in two minutes.","Set a timer for two minutes and do the step now, without waiting for it to be perfect.","When you finish, write “Today I …” and keep it as evidence for your confidence."],reflection:"After taking the first step, what changed in how you see yourself, even a little?",question:"According to Bandura, what feeds self-efficacy most strongly?",options:["Waiting until you feel completely ready.","Small experiences of success that you lived yourself.","Only hearing praise from others."],correct:1,feedback:"Bandura sees mastery experiences as the most powerful source. Praise and watching others can help too, but the small thing you did yourself is the firmest evidence.",takeaway:"Confidence follows the step you have taken.",sources:["bandura-self-efficacy","self-efficacy-work-meta","clear-two-minute-rule"],visual:{kind:"table",title:"The four sources of self-efficacy and how to use them today",columns:["Source","How you can use it today"],rows:[["Mastery experience","Take the two-minute first step and write it down"],["Watching others","Look at the story of someone like you who has walked this path"],["Encouraging words","A short supportive sentence from someone you trust, or from yourself"],["Body state","Take a few slow breaths before you begin; notice nerves as a normal reaction"]],note:"Bandura treats mastery experience as the most powerful source. This table is not a treatment plan."},deeper:[{heading:"Why small wins count",paragraphs:["It is tempting to wave a two-minute step away: “That doesn’t count, anyone could do that.” But self-efficacy is not built on how impressive a step looks; it is built on the experience of deciding to do something and then doing it. Each time that happens, you collect a small, specific piece of evidence against the story “I never follow through.”","Writing the step down matters because memory is unfair. On a hard evening you will easily recall what went wrong and forget what went right. A written “Today I…” is harder to argue with. Over days, the notes form a record that your belief can lean on."],visual:{kind:"cycle",title:"The small-evidence loop",center:"Self-efficacy",nodes:[{label:"Small step",text:"A two-minute action you can finish."},{label:"Evidence",text:"You write down what you did."},{label:"Belief",text:"“I can do this kind of thing” grows a little."},{label:"Next step",text:"Tomorrow’s step feels slightly less heavy."}],note:"An illustration of Bandura’s idea of mastery experience, not a measured effect."}},{heading:"Common mistakes",paragraphs:["Making the first step too big is the most common one. If the step needs a good mood, a free hour or perfect conditions, it is not a first step yet. Shrink it until it would be hard to say no to it.","Another mistake is treating the two-minute limit as a rule you must stop at, or as a target you must exceed. Both are fine: if you want to keep going, keep going; if you want to stop, stop. The only job is to start, and to notice that you did."]}],example:{title:"Priya, 27, junior graphic designer",text:"Priya had chosen learning: she wanted to get better at hand lettering, but every time she thought about it she pictured a finished poster and felt behind. At 3 p.m., between client files, she set a two-minute timer and wrote one line of letters on a scrap of paper. They were wobbly. When the timer went off she stopped, and wrote in her notes app: “Today I practiced lettering for two minutes.” It looked a bit ridiculous on the screen. But that evening, when her usual thought came (“you never stick with hobbies”), she had a small, specific answer to it. The next afternoon, starting felt a little easier, and she did five minutes."},technique:{name:"The two-minute rule",origin:"David Allen · Getting Things Done; James Clear · Atomic Habits (2018)",steps:["Write down the behavior you want in your chosen area, for example walking regularly.","Shrink it to a start that takes two minutes, such as putting on your shoes and stepping out the door.","Set a timer for two minutes and do only this small start.","When the time is up, continue if you want to; stopping also follows the rule.","Note what you did as evidence; what matters is not the amount but that you started."],evidence:"The two-minute rule itself is a practical suggestion rather than a directly tested method. The idea that small, achievable steps can feed self-efficacy fits Bandura’s view of mastery experience, but on its own it does not guarantee reaching a big goal.",sourceId:"clear-two-minute-rule"},photo:{id:"1758854486305-eb7621f1e2e4",alt:"Person working at a table beside a large arched window"}},{id:"turning-day-4",title:"Late afternoon · Set up your space, tell one person",minutes:7,goal:"In the late afternoon, make tomorrow’s step easier through your surroundings and tell one supportive person about your decision.",reading:["In a study where Lally and colleagues followed 96 volunteers for 12 weeks, repeating a behavior every day in the same context made it steadily more automatic. Context means the same time, the same place or the same action just before. So to remember tomorrow’s step, you can rely on your surroundings instead of your willpower: put your sneakers by the door, leave the book on your pillow. The more visible and easy the step is, the less effort it takes to begin on a tired day.","In Harkin and colleagues’ meta-analysis of 138 experimental studies, monitoring progress showed an average benefit for reaching goals (d = 0.40). The benefit was larger when results were reported to someone else or made public, and when they were physically recorded. That does not mean you have to announce it to everyone; telling one supportive person who will not judge you may be enough. You do not have to share private notes, and because this result pools very different goals, it may be different for you."],practice:["Put one item you need for tomorrow’s first step somewhere visible right now.","Attach your new step to something you already do every day and write it as one sentence.","Tell one supportive person about your decision and say you will let them know how it went in a week."],reflection:"What is the smallest change to your surroundings that would make this step easier tomorrow?",question:"In Harkin’s 2016 meta-analysis, when was the effect of monitoring progress larger?",options:["When results were only kept in mind without telling anyone.","When results were reported or shared and physically recorded.","When no monitoring was done and only a goal was set."],correct:1,feedback:"The effect was larger when results were reported or made public and physically recorded. Sharing is still optional; one person who supports you can be enough.",takeaway:"An easy environment and one supporter take weight off your willpower.",sources:["habits","monitoring","fogg-anchor-recipe"],visual:{kind:"compare",title:"A hard environment or an easy one?",left:{label:"Makes the step harder",items:["Sneakers at the back of the closet","Book on the shelf, phone next to the pillow","No one knows about your decision"]},right:{label:"Makes the step easier",items:["Sneakers ready by the door","Book on the pillow, phone in another room","A supportive person will ask in a week"]},note:"Sharing is optional; you do not have to tell anyone you think would judge you."},deeper:[{heading:"Why your surroundings do some of the work",paragraphs:["Willpower is least available exactly when you need it: at the end of a long day, when you are hungry, tired or low. Your surroundings, on the other hand, are there all the time. A cue you can see (shoes by the door) reminds you without effort, and a step that is already half set up asks for less of the energy you do not have.","The same logic runs in reverse. Most of us do not choose to scroll for an hour; the phone is simply closer than the book. You do not need to become a different person to change that. Moving one object tonight is often easier than making one big decision tomorrow."],visual:{kind:"steps",title:"Set up tomorrow’s step tonight",steps:[{label:"Pick the moment",text:"When exactly will tomorrow’s step happen? After coffee, after work, before bed."},{label:"Place the cue",text:"Put the item you need where your eyes will fall at that moment."},{label:"Remove one hurdle",text:"Lay out the clothes, open the file, fill the water bottle."},{label:"Move one temptation",text:"Put the thing that usually pulls you away one room further."}],note:"Four small moves, a few minutes tonight. None of them requires motivation tomorrow."}},{heading:"Choosing the right person to tell",paragraphs:["The research finding is about reporting progress, not about seeking applause. The most useful person is someone who will simply ask, “So how did it go?” and listen to either answer. A friend who would tease you, compete with you or turn your plan into their project is not a good fit for this step.","Keep the message short and specific: what you are doing, when, and when you will report back. “I’m walking ten minutes after work this week; can I tell you on Sunday how it went?” is enough. If there is truly no one right now, a written weekly note to yourself still counts as a physical record."]}],example:{title:"Tomás, 52, high-school teacher",text:"Tomás wanted to read before bed instead of scrolling. At 5 p.m., before grading, he took the novel from the living-room shelf and put it on his pillow. He moved his phone charger to the kitchen, which felt oddly dramatic. Then he wrote his recipe on a sticky note: “After I brush my teeth, I’ll read one page.” Finally he texted his brother, who had once read the same book: “Trying to read a page every night this week. I’ll tell you Sunday how far I got.” His brother answered with a thumbs-up and nothing else, which was exactly right. That night, the book was simply there, and the phone was not."},technique:{name:"The anchor and tiny-behavior recipe",origin:"BJ Fogg · Tiny Habits (2019)",steps:["Choose something you already do reliably every day; this will be your anchor.","Shrink your new behavior until it takes 30 seconds.","Write your recipe: “After I [anchor], I will [tiny behavior].”","As soon as you do the tiny behavior, give yourself a short, sincere celebration, like a smile or a quiet “Nice!”","Repeat the recipe tomorrow with the same anchor; if it does not stick, change the anchor or the size of the behavior."],evidence:"The idea that repeating a behavior in the same context increases automaticity fits the findings of Lally and colleagues. The Tiny Habits method itself, especially the celebration step, has had limited testing in independent studies; try it as a suggestion.",sourceId:"fogg-anchor-recipe"},photo:{id:"1756312177615-e153c9db507d",alt:"Woman talking on the phone in a kitchen"}},{id:"turning-day-5",title:"Night · Write down the evidence, prepare tomorrow",minutes:8,goal:"At night, write down the day’s evidence, look kindly at what went wrong, and make tomorrow’s first step clear.",reading:["In the daily scheme described in his autobiography, Benjamin Franklin opens the morning with the question “What good shall I do this day?” and closes the evening with “What good have I done today?” The evening question is a simple way to end the day with evidence rather than flaws. Writing down the small step you took, the space you set up or the person you talked to becomes a concrete record your confidence can rest on. If something went wrong, you can note that too, without judgment, as information.","In a study of 119 students by Wohl and colleagues, those who forgave themselves more for procrastinating on the first exam procrastinated less before the second; this finding is correlational, not experimental. Self-compassion interventions also showed small-to-medium reductions in stress and anxiety symptoms across 56 randomized trials. In a lab study by Scullin and colleagues with 57 young adults, those who spent 5 minutes before bed writing a specific to-do list fell asleep faster than those who wrote about completed tasks. So the night’s order is: a kind review, tomorrow’s one first step, then rest."],practice:["Answer Franklin’s evening question and write today’s evidence as “Today I …”.","If something went wrong, write yourself the kind sentence you would say to a friend in the same situation.","Write tomorrow’s first step in one line with a time and a place, and add it to your evidence page in the app."],reflection:"What small piece of evidence about yourself did you collect today?",question:"After a setback, which inner voice fits this lesson better?",options:["“I messed up again; this is just how I am.”","“Today didn’t go to plan; I saw what made it hard, and tomorrow I’ll shrink the step and try again.”","“I’ll act as if nothing happened and not think about it.”"],correct:1,feedback:"Forgiving yourself does not mean ignoring the setback; it means seeing it without judgment and trying again. The correlational finding by Wohl and colleagues suggests this attitude goes together with less procrastination on the next attempt.",takeaway:"Close the day with evidence; open tomorrow with one step.",sources:["franklin-daily-questions","self-forgiveness","self-compassion","todo-list-bedtime","murphy-subconscious"],visual:{kind:"table",title:"Closing the night: four short questions",columns:["Question","Sample answer"],rows:[["What good have I done today?","I walked for two minutes and put my sneakers by the door."],["What made it hard?","Afternoon tiredness; my if–then plan worked."],["My kind sentence to myself","I started; it is a small but real step."],["Tomorrow’s first step","In the morning after coffee, a 10-minute walk from my front door."]],note:"In one small lab study, a specific to-do list was linked to falling asleep faster. If your thoughts start racing, stop writing and return to rest."},deeper:[{heading:"Designing tomorrow as a realistic ideal day",paragraphs:["Franklin did not only ask his two questions; he laid out his whole day hour by hour, with time for work, meals, reading and rest. You do not need a schedule that detailed. But spending a minute tonight picturing a realistic ideal day (not a perfect one) helps you see where tomorrow’s step fits and what might crowd it out.","A useful ideal day has only a few fixed points: the one step for your chosen area, one moment of rest, and one moment of connection with another person. Everything else can stay flexible. If you design a day that only works when nothing goes wrong, you have designed a day that will not happen; leave space for the unexpected."],visual:{kind:"table",title:"A realistic ideal day: three anchors",columns:["Anchor","When","Example"],rows:[["Your one step","Tied to something you already do","After morning coffee: a 10-minute walk"],["Rest","A protected pause","Lunch away from the screen"],["Connection","A short, real contact","Text or call one person in the evening"]],note:"Three fixed points and plenty of slack. This is a planning aid, not a rule for how your day must go."}},{heading:"Kindness is not letting yourself off the hook",paragraphs:["Some people fear that being kind to themselves will make them lazy. The research in this lesson points the other way, though cautiously: in the Wohl study, students who forgave themselves more procrastinated less the next time, and the link was explained by less negative feeling about the task. Self-criticism makes the task feel worse, and a task that feels worse is easier to avoid.","A kind review still names what happened. “I skipped the walk because I stayed late at work” is honest. Adding “and that makes sense; tomorrow I’ll do the corner-and-back version” is kind. Leaving out the first half would be avoidance; leaving out the second half would be harshness."]}],example:{title:"Aisha, 38, accountant and parent of two",text:"Aisha had planned a ten-minute stretch after lunch, but a client call ran long and she forgot until bedtime. Her first thought, brushing her teeth, was “Day one and I already failed.” She sat on the edge of the bed with her notebook instead. Under “What good have I done today?” she wrote: “Put the yoga mat by the desk. Told Sam about my plan.” Under “What made it hard?”: “The call ran over; stretching after lunch depends on the calendar.” Her kind sentence: “Of course it slipped on a busy day; I still set things up.” Tomorrow’s step: “7:30 a.m., before the kids wake up, three minutes on the mat.” She closed the notebook and turned off the light."},technique:{name:"A calm suggestion before sleep",origin:"Joseph Murphy · The Power of Your Subconscious Mind (1963)",steps:["Lie down, dim the lights and relax your body with a few slow breaths.","Turn a single intention for tomorrow into a short, positive, doable sentence, such as “Tomorrow after coffee, I go for a walk.”","As sleep grows heavier, repeat this sentence slowly to yourself a few times, without forcing it, like a lullaby.","See yourself doing the step as a short scene and notice the calm.","If your mind drifts into worry, let the sentence go and simply return to your breath."],evidence:"Putting tomorrow’s step into a clear sentence before bed and rehearsing it calmly may help you prepare; writing a specific to-do list was linked to falling asleep faster in one small study. The claim that the subconscious will bring the desired outcome, money or healing on its own is not supported by science; what decides the outcome is the step you take the next day.",sourceId:"murphy-subconscious"},photo:{id:"1768219565623-501f93ae384b",alt:"Desk lit by a lamp in the evening"}},{id:"turning-day-6",title:"The next 7 days · Turn the beginning into evidence",minutes:9,goal:"For the next 7 days, repeat the same small step daily, track it, return right away after a missed day, and look back on day 7.",reading:["A single day does not change your life, but it can turn a beginning into a repeated behavior. In the study by Lally and colleagues, the time it took for a behavior to reach a high level of automaticity ranged from 18 to 254 days, depending on the person. So 7 days is a reasonable span not for a habit, but for a first run of evidence. In the same study, missing a single opportunity did not noticeably disrupt habit formation. If you miss a day, nothing is over.","In Harkin and colleagues’ meta-analysis, monitoring progress showed an average benefit for reaching goals, and the effect was larger when the information was physically recorded. This week, do the same small step every day and mark it; you can write it on the Today screen in the app as the day’s one decision. If you miss a day, do only the smallest version the next day: the rule is “never miss twice in a row.” On day 7, in a weekly look back, choose what worked and what you will shrink."],practice:["Draw seven boxes on a calendar or a sheet of paper and tick one each day you take the step.","Write now, in one sentence, the smallest version you will do if you miss a day.","Put a ten-minute look-back on day 7 into your calendar now."],reflection:"After 7 days, what sentence about yourself would you like to be able to say with evidence?",question:"According to this lesson, what should you do when you miss a day?",options:["The chain is broken; I should start over with a bigger goal.","Do the smallest version of the step the next day and focus on never missing twice in a row.","Wait for the next Monday or the first of the month to start again."],correct:1,feedback:"In the study by Lally and colleagues, missing a single opportunity did not noticeably disrupt habit formation. What matters is coming back quickly; you do not need a special day on the calendar to start again, and tomorrow can be a beginning too.",takeaway:"One day starts it; repeated days prove it.",sources:["habits","monitoring","seinfeld-chain-story","fresh-start-framing"],visual:{kind:"steps",title:"A one-week evidence loop",steps:[{label:"Do",text:"Take the same small step with the same anchor or at the same time."},{label:"Mark",text:"Tick that day’s box on the calendar or in the app."},{label:"If it gets hard",text:"Go back to your if–then plan or shrink the step."},{label:"If you miss",text:"Do the smallest version the next day; never miss twice in a row."},{label:"Day 7",text:"Look back: what worked, what will you change, will you continue?"}],note:"Seven days is a span for a first run of evidence, not for a habit to settle; in the study by Lally and colleagues that took from 18 to 254 days depending on the person."},deeper:[{heading:"Fresh starts are renewable",paragraphs:["The fresh-start research carries a quiet lesson for the week ahead: a beginning does not have to come from the calendar. In the 2015 experiments, simply calling an ordinary day a beginning raised people’s wish to start. You can use that on purpose. After a missed day, tomorrow morning is a perfectly good landmark; so is the start of the next week, or the day you finish a hard project.","What does not help is using the next landmark as a reason to wait. “I’ll restart on Monday” on a Wednesday gives away four days. A better use is “Tomorrow is day one of the second half of my week.” The line between old and new can be drawn wherever you need it."]},{heading:"Your day-7 look back",paragraphs:["On day 7, look at the boxes without grading yourself. A week with four ticks and three gaps is not a failed week; it is data about when the step fits your life and when it does not. The questions below take about ten minutes. Answer them in writing if you can, because a physical record was linked to a larger benefit in the monitoring research.","Then choose one of three paths: keep the step as it is, shrink it, or change the anchor or time. Adding more is also an option, but only if the current step has started to feel easy. The aim for the second week is the same as for the first: small enough to repeat."],visual:{kind:"table",title:"Day-7 questions",columns:["Question","What it tells you"],rows:[["On which days did it happen easily?","The conditions that support your step"],["On which days did it slip, and why?","The obstacle your next if–then plan should target"],["Did I come back after a missed day?","Whether your smallest version is small enough"],["Keep, shrink or change?","Your plan for the next seven days"]],note:"A look back is for learning, not for grading. Gaps are information."}}],example:{title:"Jonah, 23, delivery driver studying part time",text:"Jonah’s step was twenty minutes of accounting review after dinner. He drew seven boxes on the back of an envelope and stuck it on the fridge. Monday and Tuesday got ticks. On Wednesday he worked late and the envelope stayed empty, and he felt the familiar urge to “start fresh next week.” Instead he looked at the sentence he had written on day one: “If I miss, I do five flashcards.” On Thursday he did five flashcards, then eight. By Sunday he had five ticks out of seven. In his look back he noticed that both gaps were late-shift days, so for week two he moved the step to his lunch break on those days."},technique:{name:"Don’t break the chain, never miss twice",origin:"Story attributed to Jerry Seinfeld (as told by Brad Isaac) · retold by James Clear and in Atomic Habits (2018)",steps:["Hang a calendar you will see every day on the wall or desk, or draw seven boxes on paper.","On each day you take your small step, put a big X or a tick over that day.","After a few days, notice the chain forming and make keeping it going your daily goal.","If you miss a day, do not punish yourself; do the smallest version of the step the next day.","Set your rule as “never miss two days in a row,” and on day 7 look at the chain and update your plan."],evidence:"The story is an anecdote; according to James Clear’s note, Seinfeld has said the idea was not his and that he did not claim to use it. Tracking progress in writing showed an average benefit in a meta-analysis, and missing a single day did not noticeably disrupt habit formation; the chain is a tool, not a demand for perfection.",sourceId:"seinfeld-chain-story"},photo:{id:"1529651737248-dad5e287768e",alt:"Pen resting on a planner calendar"}}]},T=Object.freeze(Object.defineProperty({__proto__:null,COURSE:B,SOURCES:S},Symbol.toStringTag,{value:"Module"})),x=[{id:"procrastination-interventions",title:"van Eerde & Klingsieck · 2018 · Meta-analysis of procrastination interventions",url:"https://www.sciencedirect.com/science/article/abs/pii/S1747938X18300472",type:"research",finding:"A meta-analysis pooling 24 studies (N = 1,173) found a large reduction in procrastination after interventions (average pre–post effect −1.07); the reduction held at follow-up measurements, and the strongest results came from cognitive behavioral therapy.",limitation:"Because the value was calculated from before–after differences rather than against a control group, the effect may look larger than it is; only the abstract was read, and this ODA course has not been tested."},{id:"task-aversiveness",title:"Steel · 2007 · Meta-analysis of the causes of procrastination",url:"https://studypedia.au.dk/fileadmin/www.studiemetro.au.dk/Procrastination_2.pdf",type:"research",finding:"In a meta-analysis based on 691 correlations, procrastination was related to finding a task aversive (r = 0.40), low self-control (r = −0.58), low self-efficacy (r = −0.38) and impulsiveness (r = 0.41), but hardly at all to the intention to work (r = 0.03). Steel estimates that procrastination chronically affects some 15–20% of adults and that 80–95% of college students procrastinate to some degree. He proposes temporal motivation theory: the pull of a task grows with how likely success feels (expectancy) and how rewarding it is (value), and shrinks the further away the reward is (delay) and the more sensitive a person is to delay.",limitation:"The findings are correlational and do not show cause and effect; in the PDF that was read, the minus signs were lost, so the direction of the relationships was inferred from the wording of the text. Temporal motivation theory is a model that fits these findings, not a tested treatment."},{id:"mood-repair",title:"Sirois & Pychyl · 2013 · Procrastination and mood repair",url:"https://eprints.whiterose.ac.uk/91793/1/Compass%20Paper%20revision%20FINAL.pdf",type:"research",finding:"This theoretical review explains procrastination as an attempt to ease, in the moment, the bad feeling an aversive task creates, and argues that the cost is passed on to the future self; a small analysis it reports found procrastination linked to low self-compassion (r = −0.31).",limitation:"A narrative review with no new data, and the r = −0.31 value comes from a study not yet published at the time; the accepted author version was read."},{id:"self-forgiveness",title:"Wohl, Pychyl & Bennett · 2010 · Self-forgiveness and procrastination",url:"https://www.sciencedirect.com/science/article/abs/pii/S0191886910000474",type:"research",finding:"Among 119 first-year students followed across two midterm exams, those who forgave themselves more for procrastinating on the first exam procrastinated less when preparing for the second, and a reduction in negative feelings explained this link.",limitation:"The study is correlational, not experimental; it was run in a single course and student group, and of the 312 people at the first measurement only 119 remained in the analysis."},{id:"mcii-procrastination",title:"Zhou et al. · 2026 · An experiment on WOOP (MCII) and procrastination",url:"https://www.sciencedirect.com/science/article/pii/S0001691825014829",type:"research",finding:"In a randomized study with 81 university students, the group that used WOOP (Wish, Outcome, Obstacle, Plan) found their tasks less aversive and started their task on 58.8% of days; in the control group, which only thought positively, the figure was 47.3%.",limitation:"A small study run at a single university, with one week of follow-up and no preregistration (dropout rate 19.8%); this ODA course has not been tested."},{id:"if-then-plans",title:"Gollwitzer & Sheeran · 2006 · Meta-analysis of if–then plans",url:"https://www.sciencedirect.com/science/chapter/bookseries/abs/pii/S0065260106380021",type:"research",finding:"Across 94 independent tests, “If … happens, then I will …” plans that answer in advance when, where and how to act showed a medium-to-large positive effect on reaching goals (d = 0.65).",limitation:"Only the abstract was read; newer analyses that correct for publication bias were not checked, so the true effect may be smaller, and the work is not specific to procrastination."},{id:"procrastination-pychyl-start",title:"Timothy A. Pychyl · 2008 · “Just get started” (Psychology Today, Don’t Delay blog)",url:"https://www.psychologytoday.com/us/blog/dont-delay/200803/just-get-started",type:"guidance",finding:"Procrastination researcher Tim Pychyl describes experience-sampling data from his lab: tasks that people rated as very stressful and unpleasant while avoiding them felt much less aversive once they actually started, and people who made even a partial start felt more in control and more optimistic the next day. He also notes that the belief “I’ll feel more like it tomorrow” rarely comes true.",limitation:"A blog post summarizing the author’s own research for a general audience, not a peer-reviewed paper; Pychyl himself presents starting as a first step, not a complete solution."},{id:"procrastination-pomodoro",title:"Francesco Cirillo · The Pomodoro Technique (official site)",url:"https://www.pomodorotechnique.com/francesco-cirillo/",type:"technique",finding:"Cirillo created the technique in the 1980s while struggling to focus on his university studies, using a tomato-shaped kitchen timer (“pomodoro” is Italian for tomato); his first experiment was to see whether he could study for just two minutes without interruption. The technique is widely taught as 25-minute focused blocks separated by short breaks. Cirillo stresses that the aim is not to collect pomodoros but to become aware of what happens in your mind while you work.",limitation:"The creator’s own site, not an independent evaluation; the technique itself has not been tested as a whole in controlled trials. The exact block and break lengths are conventions, not research findings."},{id:"procrastination-pomodoro-breaks",title:"Biwer et al. · 2023 · “Pomodoro” breaks versus self-regulated breaks",url:"https://cris.maastrichtuniversity.nl/en/publications/understanding-effort-regulation-comparing-pomodoro-breaks-and-sel/",type:"research",finding:"87 Dutch university students studied with either self-chosen breaks (n = 35), 6-minute breaks after every 24 minutes (“Pomodoro”, n = 25) or 3-minute breaks after every 12 minutes (n = 27). Students taking self-chosen breaks studied and rested in longer stretches but reported more fatigue and distraction and less concentration and motivation. Task completion and mental effort did not differ meaningfully; the authors conclude that fixed breaks had mood benefits and seemed more efficient.",limitation:"Abstract only. One small study of self-study in a single session with university students; it tested break schedules, not procrastination directly, and the groups were small."}],A={id:"procrastination",title:"Procrastination",subtitle:"Not laziness, a feeling.",description:"Notice the feeling behind putting things off, shrink the task, attach a plan to your real obstacle, and come back after procrastinating without beating yourself up.",scope:"Skills training for everyday procrastination; it is not therapy. If procrastination comes with intense anxiety, long-lasting low mood or attention difficulties and clearly affects your life, you can get support from a professional.",outcome:"A shrunken task, an if–then plan and a sentence for coming back after you have procrastinated.",photo:{id:"1758598304525-c2bc7aada66d",alt:"Woman working on a laptop at a desk surrounded by plants"},lessons:[{id:"procrastination-1",title:"The feeling behind putting things off",minutes:7,goal:"Name the feeling that a task you have been putting off brings up in you.",reading:["Putting things off is usually not laziness. In a large review of the research, people who procrastinated did not intend to work any less than others; where they struggled was turning the intention into action. According to the same review, 80–95% of university students procrastinate to some degree, and for an estimated 15–20% of adults it is a chronic problem. You are not the only one living with this, and it says little about your character.","The more boring, unclear or worrying a task feels, the more we tend to put it off. One explanation, developed by researchers Fuschia Sirois and Tim Pychyl, is that when we procrastinate, what we are escaping is not the task itself but the feeling it brings up in us: we feel relief in the moment, and our later self pays the price. Today we will try to notice that feeling without judging it. Naming it is the first step toward handling it differently."],practice:["Choose one task you have been putting off for a while.","When you think of the task, name what you feel in a word or two: dread, worry, uncertainty or something else.","Consider which part of the task brings up this feeling; do not try to solve it, just note it."],reflection:"What is the feeling that really makes this task hard for you?",question:"According to this lesson, which explains procrastination better?",options:["People who procrastinate do not actually want to work.","Moving away, in the moment, from an unpleasant feeling the task brings up.","Procrastination is a character trait that never changes."],correct:1,feedback:"Finding a task aversive was linked to procrastination, while a lack of intention was hardly linked at all. These are not proof of cause and effect, but they can soften the way you see yourself.",takeaway:"What you put off is often a feeling, not proof that you are lazy.",sources:["task-aversiveness","mood-repair","procrastination-pychyl-start"],visual:{kind:"bars",title:"How strongly each factor relates to procrastination",sourceId:"task-aversiveness",bars:[{label:"Self-control (inverse)",value:.58,display:"r = −0.58"},{label:"Finding the task aversive",value:.4,display:"r = 0.40"},{label:"Self-efficacy (inverse)",value:.38,display:"r = −0.38"},{label:"Intention to work",value:.03,display:"r = 0.03"}],note:"The bars show the strength of each relationship with procrastination; a minus sign means procrastination rises as self-control or self-efficacy falls. These are correlations and do not show cause and effect."},deeper:[{heading:"Tim Pychyl’s view: a problem of feelings, not of time",paragraphs:["Psychologist Tim Pychyl, a long-time procrastination researcher, describes it as a way of regulating emotions that backfires. A task makes us feel anxious, bored, frustrated or unsure. Putting it off brings quick relief, so avoiding starts to feel like a solution. But the task does not go away; it comes back later, often bigger, with extra stress and self-blame attached.","In a review with Fuschia Sirois, Pychyl describes this as a trade between two versions of you: the present self gets the relief, the future self gets the bill. Seen this way, a to-do app or a stricter schedule will only help so much. What helps more is learning to notice the feeling, tolerate it for a little while, and take one small action anyway."],visual:{kind:"cycle",title:"The procrastination loop",center:"Short-term relief, long-term cost",nodes:[{label:"Task",text:"A task that feels unclear, boring or threatening."},{label:"Feeling",text:"Dread, worry or frustration rises."},{label:"Avoidance",text:"You switch to something easier."},{label:"Relief",text:"The bad feeling eases for now."},{label:"Return",text:"The task comes back, now with extra pressure and self-blame."}],note:"A description of the mood-repair view (Sirois and Pychyl), not a measured model. Breaking the loop usually starts with noticing the feeling."}},{heading:"What the numbers say, and what they do not",paragraphs:["In Piers Steel’s large review, procrastination was strongly linked to finding a task aversive and to impulsiveness, and hardly linked at all to how much people intended to work. Steel estimates that procrastination is a chronic problem for about 15–20% of adults. These are correlations: they do not prove that aversive tasks cause procrastination, but they point to where it is worth looking.","The encouraging part is what the numbers leave out. Wanting to work is not the missing piece, so you do not need to “want it more.” The feeling around the task, the size of the first step and the plan for the hard moment can all be changed, and the next lessons work on exactly those."]}],example:{title:"Sofia, 31, marketing coordinator",text:"Sofia had been avoiding her expense report for three weeks. She usually told herself she was “just bad at admin.” During a coffee break she tried the exercise instead: she opened the email with the report template and paused to notice what happened. The word that came was “dread,” and underneath it, “embarrassment.” The part that triggered it was not the spreadsheet; it was the crumpled receipts in her bag, some of them probably lost. She wrote on a sticky note: “Dread + embarrassment, about missing receipts.” She did not start the report that day. But “bad at admin” had turned into a specific feeling about a specific part, and that felt like something she could work with."},photo:{id:"1552360708-ebcdf76845ac",alt:"Woman sitting by a window, deep in thought"}},{id:"procrastination-2",title:"Shrink the task, find the first move",minutes:6,goal:"Turn the task you are putting off into a first move so small and concrete that it does not feel heavy.",reading:["“Prepare the presentation” or “clean the house” does not tell you where to start. Uncertainty can make a task feel heavier than it is, because your mind tries to hold the whole thing at once without knowing which part comes first. “Open the document and write three headings,” on the other hand, is a beginning you can see. Being small does not make it unimportant. A first move concrete enough to picture is often the difference between thinking about a task and doing it.","The feeling “I can do this,” which psychologists call self-efficacy, was found to be inversely related to procrastination: the lower it was, the more people tended to put things off. We think small, achievable first steps may feed that feeling; this is an inference, not a direct finding. After you make the first move, you do not have to continue; stopping is also an option. The aim today is simply to discover that the task has a doorway, and to walk through it once."],practice:["Write or say the task you chose in the previous lesson in one sentence.","Break the task into three small parts; start the first with a clear verb such as open, write, call or choose.","If the first part still feels heavy, shrink it to a two-minute version and try it now."],reflection:"What was the smallest first move for your task?",question:"Which is a concrete first move?",options:["Being more disciplined this week.","Getting the project done as soon as possible.","Opening the report file and writing the first heading."],correct:2,feedback:"A concrete verb and object show you where to begin. You do not need to solve the big task in one go.",takeaway:"To start, you do not need to see the whole task, only its first move.",sources:["task-aversiveness","procrastination-pychyl-start","procrastination-pomodoro","procrastination-pomodoro-breaks"],visual:{kind:"steps",title:"From big task to first move",steps:[{label:"Big task",text:"Prepare the presentation."},{label:"Parts",text:"Choose a topic, find sources, write the slides."},{label:"First part",text:"Choose the topic of the presentation."},{label:"First move",text:"Open a blank document and write three possible topics."}],note:"If the first move still feels heavy, shrink it by one more step."},deeper:[{heading:"Why starting changes the feeling",paragraphs:["Tim Pychyl describes a pattern from his lab’s research: tasks that people rated as very stressful and unpleasant while they were avoiding them felt much less unpleasant once they had actually started. People who made even a partial start also felt more in control and more hopeful the next day. The dread lives mostly in the waiting.","He also points to a common trap: “I’ll feel more like doing it tomorrow.” Tomorrow’s mood rarely turns out to be better. A tiny first move does not wait for the right mood; it changes the mood by giving you a different experience of the task."]},{heading:"Working in short, timed blocks",paragraphs:["Francesco Cirillo developed the Pomodoro Technique in the 1980s, as a student who could not concentrate. His very first experiment was modest: could he study for just two minutes without interruption? The technique grew from there into timed blocks of focused work, usually taught as 25 minutes, separated by short breaks.","One small study compared break schedules in 87 university students. Students who took fixed breaks (6 minutes after every 24, or 3 after every 12) reported less fatigue and distraction and more concentration and motivation than students who chose their own breaks, and they got through a similar amount of work. It was a single session with a small sample, so treat it as a hint, not a rule. The block length that suits you may be much shorter to begin with."],visual:{kind:"table",title:"Three ways to take breaks (Biwer et al. 2023)",columns:["Break schedule","Students","What they reported"],rows:[["Self-chosen breaks","35","Longer stretches; more fatigue and distraction, less concentration and motivation"],["6 min after every 24 min","25","Better mood measures; similar task completion"],["3 min after every 12 min","27","Better mood measures; similar task completion"]],note:"One small study of a single self-study session. It tested break schedules, not procrastination directly."}}],example:{title:"Kevin, 45, freelance translator",text:"Kevin had a 20-page contract to translate and had spent two mornings “getting ready” by answering email. On the third morning he wrote the task as “translate the contract,” then broke it into parts: read it through, build a glossary, translate section one. Even “read it through” felt heavy, so he shrank it: open the file and read the first page. He set a kitchen timer for ten minutes, because 25 felt like too much. When it rang he had read three pages and noted four tricky terms. He took a five-minute break, made tea, and set the timer again. The contract was still long, but it was no longer a wall; it was a pile of pages, and he had moved some of them."},technique:{name:"The Pomodoro Technique",origin:"Francesco Cirillo · The Pomodoro Technique (developed in the 1980s)",steps:["Pick one task, or the first move of a bigger task, and write it down.","Set a timer for one focused block; 25 minutes is the classic length, but start with 10 or even 2 if that feels safer.","Work only on that task until the timer rings; if another thought pops up, jot it on paper and return.","When the timer rings, take a short break of about five minutes away from the screen.","After a few blocks, take a longer break, and notice what pulled your attention away so you can plan for it next time."],evidence:"The Pomodoro Technique as a whole has not been tested in controlled trials. One small study found that fixed, Pomodoro-style breaks went with better mood and similar output compared with self-chosen breaks, but it did not measure procrastination. Treat the timings as a starting point to adjust, not as a rule.",sourceId:"procrastination-pomodoro"},photo:{id:"1448387473223-5c37445527e7",alt:"A foot stepping onto the first stair"}},{id:"procrastination-3",title:"Attach a plan to your real obstacle",minutes:8,goal:"Apply wish, obstacle and an if–then plan to the task you are putting off.",reading:["Only picturing a happy outcome may not be enough to get you started; it can even feel so pleasant that the urge to act fades. In a method called WOOP, developed by psychologist Gabriele Oettingen, you first think about what you want and what it would bring you, then look at the real obstacle that stops you from the inside. In the last step you attach a response to the obstacle: “If … happens, then I will ….” The plan links a moment you can recognize to a small action.","In a small experiment with 81 students, those who used WOOP found their tasks less aversive and got started on a larger share of days than students who only thought positively. This was a one-week study at a single university, not a final answer. A larger body of research on if–then plans in general points in the same direction, with medium-to-large average effects that may shrink once publication bias is taken into account. Still, the method is easy to try and costs little: a few minutes and one sentence."],practice:["Wish and outcome: think about what you want this week regarding the task you are putting off, and what it would give you if it happened.","Obstacle: name the inner obstacle that stops you most, for example “picking up my phone” or “feeling not good enough.”","Plan: complete the sentence “If [obstacle] happens, then I will [small action]” and rehearse it once in your mind."],reflection:"What is your if–then sentence?",question:"What sets WOOP apart from just thinking positively?",options:["Seeing the real obstacle and attaching a concrete response to it.","Picturing success as vividly as possible.","Trying never to think about obstacles."],correct:0,feedback:"In this approach, the obstacle is not ignored; it is turned into a plan. Effects in research are averages and can vary from person to person.",takeaway:"See your obstacle and prepare a small response to it.",sources:["mcii-procrastination","if-then-plans","mcii","task-aversiveness","oettingen-woop-method"],visual:{kind:"bars",title:"Share of days on which people started their task",sourceId:"mcii-procrastination",bars:[{label:"WOOP (wish, outcome, obstacle, plan)",value:58.8,display:"58.8%"},{label:"Positive thinking only",value:47.3,display:"47.3%"}],note:"81 university students, one week of follow-up. A single small study; it does not guarantee the same result for you."},deeper:[{heading:"Piers Steel’s temporal motivation theory",paragraphs:["Piers Steel pulls the procrastination research together into one idea, temporal motivation theory. A task pulls you more when you expect to succeed at it (expectancy) and when it matters or rewards you (value). It pulls you less when the reward is far away (delay) and when you are more easily swayed by what is close at hand (impulsiveness). A report due in three weeks competes badly with a video that rewards you right now.","The useful part is that each piece suggests a lever. You can raise expectancy by shrinking the task, raise value by linking it to what you care about, shorten the delay with nearer checkpoints and small rewards, and reduce impulsiveness by putting distractions out of reach. WOOP and if–then plans work mainly on the last one: they decide in advance what you will do when the pull comes."],visual:{kind:"table",title:"Four levers from temporal motivation theory",columns:["Factor","What it means","One thing to try"],rows:[["Expectancy","How sure you feel you can do it","Shrink the task until success feels likely"],["Value","How much it matters or rewards you","Write one line on why it matters to you"],["Delay","How far away the payoff is","Set a nearer checkpoint with a small reward"],["Impulsiveness","How strongly nearby temptations pull","Make an if–then plan and move the distraction away"]],note:"Based on Steel’s model, which fits correlational findings; it is a way of thinking, not a tested treatment."}},{heading:"Common mistakes with if–then plans",paragraphs:["The “if” is often too vague. “If I don’t feel like it” is true almost all the time, so it cannot act as a clear cue. “If I pick up my phone after sitting down at my desk” is a moment you will recognize when it happens.","The “then” is often too big. “Then I’ll work for two hours” asks for the very effort the obstacle is blocking. “Then I’ll write one sentence first” is small enough to happen even when the feeling is strong. One plan for your most common obstacle is better than five plans you will not remember."]}],example:{title:"Grace, 26, graduate student",text:"Grace wanted to finish the literature review for her thesis this week; if she did, she could stop feeling guilty every weekend. When she looked for the obstacle, it was not time. It was the moment after opening the document, when she felt she did not know enough, and reached for her phone. Her plan: “If I reach for my phone after opening the document, then I’ll put it in the drawer and write one sentence about the first paper.” She rehearsed it once on the bus. On Tuesday she caught herself with the phone already in her hand, laughed a little, and put it in the drawer. The sentence she wrote was clumsy. She wrote a second one anyway."},photo:{id:"1553044020-8c90843adf96",alt:"Yellow sticky notes and a pen"}},{id:"procrastination-4",title:"After procrastinating: forgive yourself",minutes:7,goal:"After putting something off, form a sentence that is both forgiving and responsible instead of attacking yourself.",reading:["After procrastinating, it is easy to tell yourself, “You did it again; you’ll never change.” That harsh voice may feel like it is keeping you in line, but it may not make the next start any easier. It can make the task feel even more aversive, and an aversive task is exactly the kind we avoid. In a study with first-year university students, those who forgave themselves more for procrastinating before the first exam procrastinated less when preparing for the second.","That study was not experimental; it does not prove that forgiveness reduces procrastination. The link was explained by a reduction in negative feelings: students who forgave themselves felt less bad about the course, and that seemed to make it easier to approach. Forgiving yourself does not mean ignoring what happened. It means saying: “I put it off; that is human. Next time I will do this differently.” Both halves matter: the kindness and the next step."],practice:["Briefly recall a recent moment when you put something off, and notice what you said to yourself.","Say to yourself the understanding sentence you would say to a friend in the same situation.","Then decide on one concrete thing you will do differently next time."],reflection:"What forgiving but responsible sentence would you like to say to yourself?",question:"What does forgiving yourself mean in this lesson?",options:["Treating what happened as unimportant and changing nothing.","Giving yourself permission to keep procrastinating.","Accepting what happened and choosing the next step."],correct:2,feedback:"Forgiving is not dropping responsibility. Instead of beating yourself up, it can make it easier to turn to the part you can fix.",takeaway:"You procrastinated; that does not define you. The next step is still yours.",sources:["self-forgiveness","mood-repair","self-compassion"],visual:{kind:"compare",title:"Your inner voice after procrastinating",left:{label:"Attacking yourself",items:["“I’m just lazy.”","Turns one moment into your whole identity.","Can make the task feel even more aversive."]},right:{label:"Forgiving yourself",items:["“I put it off; that’s human.”","Accepts what happened and keeps responsibility.","Makes room for the next small step."]},note:"Forgiving does not mean ignoring what happened or carrying on the same way."},deeper:[{heading:"What the self-forgiveness study found",paragraphs:["Michael Wohl, Tim Pychyl and Shannon Bennett followed first-year students across two midterm exams. After the first exam, students reported how much they had procrastinated and how much they had forgiven themselves for it. Those who forgave themselves more procrastinated less before the second exam, and the link ran through feeling less negative about the course.","The study has real limits: it was correlational, it took place in one course, and only 119 of the 312 students who started were in the final analysis. So it cannot prove that forgiveness causes less procrastination. But it fits the mood-repair view: if procrastination is a way of escaping bad feelings, piling more bad feelings on top is unlikely to help. Self-compassion research more broadly shows small-to-medium short-term benefits for stress and anxiety."]},{heading:"A three-part forgiveness script",paragraphs:["Self-forgiveness can feel vague, so it helps to have words ready. The three parts below keep honesty and kindness together. Say them silently or write them down; the exact wording is yours.","If the harsh voice comes back while you do this, that is normal. You do not need to argue with it or silence it. Simply notice it (“there’s the critic again”) and go back to the script."],visual:{kind:"steps",title:"Forgive, then return",steps:[{label:"Name it",text:"“I put off the report again this week.”"},{label:"Make it human",text:"“It felt unclear and stressful; many people avoid tasks like that.”"},{label:"Take responsibility",text:"“It still matters to me, and I can fix part of it.”"},{label:"Choose the next step",text:"“Tomorrow at 9 I’ll open the file and write the first heading.”"}],note:"Forgiveness here means dropping the attack, not dropping the task."}}],example:{title:"Daniel, 36, project manager",text:"Daniel had promised his team a budget draft by Friday, and on Friday afternoon it was still a blank page. On the drive home he heard the usual voice: “You always do this. Everyone will see you can’t manage anything.” By the time he parked, he felt too heavy to open the laptop at all. Sitting in the car, he tried the script. “I didn’t do the draft. It felt vague and I kept avoiding it; that happens to people. It still matters, and I can fix some of it.” Then the step: an email to his team saying the draft would come Monday at noon, and a note to open the file at 8:30. On Monday, starting felt less like facing a verdict."},photo:{id:"1778958619388-b529cc4e78e8",alt:"Young woman drinking tea by a window"}},{id:"procrastination-5",title:"Your own procrastination plan",minutes:8,goal:"Set up a one-week experiment with a first move, a plan, a review and, if you like, interim deadlines.",reading:["In studies of procrastination interventions, procrastination fell clearly after the intervention, and the drop held at follow-up measurements. This value was calculated from before–after differences rather than against a control group, so the effect may look bigger than it is. The strongest results came from cognitive behavioral therapy delivered by professionals, and this course is not therapy. What it can offer is a small, personal experiment built from the tools you have practiced: a first move, a plan and a review.","Splitting a big task into several interim deadlines on your calendar, setting yourself gentle checkpoints, is an idea worth trying. But a frequently cited study on this was retracted, and we have not reviewed strong evidence to take its place. So think of interim deadlines not as a proven method but as an experiment you observe on yourself. If a checkpoint helps you start, keep it; if it only adds pressure and guilt, drop it without drama."],practice:["Write out your task following the rows of the table: first move, time and place, if–then plan.","If you like, add a few interim dates to the big task; think of them not as strict rules but as gentle reminders to yourself.","At the end of the week, spend two minutes reviewing what worked and what you will change."],reflection:"Which part of your plan will you keep, and which will you change?",question:"What is the most honest approach to deadlines you set for yourself?",options:["It is a proven method that definitely works.","Worth trying but with limited evidence; watch how it works for you.","It never works and should never be tried."],correct:1,feedback:"Trying a method with limited evidence is fine; what matters is honestly observing how it works for you. If procrastination clearly affects your life, you can get support from a professional.",takeaway:"Keep your plan small, try it, review it, and ask for support when you need it.",sources:["procrastination-interventions","if-then-plans","monitoring","task-aversiveness"],visual:{kind:"table",title:"Weekly procrastination plan",columns:["Step","Example","Your plan"],rows:[["First move","Open the document and write three headings","…"],["Time and place","Tuesday 9:00, kitchen table","…"],["If–then","If I pick up my phone, I’ll write one sentence first","…"],["Interim deadline (experiment)","Thursday: first draft","…"],["Review","Sunday evening, two minutes","…"]],note:"Interim deadlines are an experiment with limited evidence; change or drop them if they do not help."},deeper:[{heading:"Matching tools to your kind of stuck",paragraphs:["Procrastination does not look the same every time, and the tools in this course fit different versions of it. When a task feels shapeless, shrinking it helps most. When a particular moment keeps derailing you, an if–then plan fits. When the payoff is far away, a nearer checkpoint shortens the delay, which is exactly what Steel’s model predicts should help.","You do not need all of them at once. Pick the one or two that match the way you tend to get stuck, try them for a week, and look at what happened. Tracking what you did, even with a simple tick, was linked to better goal progress in a large meta-analysis, and it gives your weekly review something real to look at."],visual:{kind:"table",title:"Which tool for which kind of stuck?",columns:["If the task feels…","Try","From lesson"],rows:[["Heavy and dreadful","Name the feeling, then a two-minute first move","1 and 2"],["Shapeless or huge","Break it into parts and a concrete verb","2"],["Fine until a certain moment","An if–then plan for that moment","3"],["Far off and easy to ignore","A nearer checkpoint with a small reward","5"],["Ruined because you already put it off","The forgiveness script, then one step","4"]],note:"A menu, not a checklist. One or two tools that fit you are enough for a week."}},{heading:"When to look for more support",paragraphs:["The strongest results in the intervention research came from cognitive behavioral therapy with a trained professional. That is worth knowing, because some procrastination is tangled up with things a short course cannot address, such as ongoing anxiety, depression or attention difficulties like ADHD.","Signs that it may be time to talk to a doctor or therapist include: putting things off is costing you jobs, grades, relationships or health; the feelings around tasks are intense or constant; or you have tried several approaches and nothing shifts. Asking for help at that point is not a failure of willpower. It is choosing a stronger tool for a harder problem."]}],example:{title:"Nadia, 29, veterinary technician applying to school",text:"Nadia’s application essay was due in three weeks, and she knew herself: she would start the night before. On Sunday she filled in the plan. First move: open a document and list three moments that made her want this career. Time and place: Tuesday 7 p.m., kitchen table, after dinner. If–then: “If I start rereading old emails, I’ll write one sentence first.” As an experiment, she set two interim dates: rough draft by next Sunday, and a friend reading it the Wednesday after. Tuesday went fine. Thursday she skipped entirely. On Sunday’s two-minute review she noted that the friend’s date had pushed her more than her own, so she moved the friend’s reading up by three days."},photo:{id:"1506784983877-45594efa4cbe",alt:"Coffee cup resting on an open planner"}}]},I=Object.freeze(Object.defineProperty({__proto__:null,COURSE:A,SOURCES:x},Symbol.toStringTag,{value:"Module"})),D=[{id:"mcii",title:"Wang, Wang & Gai · 2021 · Meta-analysis on reaching goals",url:"https://www.frontiersin.org/journals/psychology/articles/10.3389/fpsyg.2021.565202/full",type:"research",finding:"21 studies, 15,907 participants: contrasting a goal with the real obstacle together with an if–then plan showed a small-to-medium average effect (g = 0.336).",limitation:"Publication bias is possible; results vary by person and situation. The effectiveness of this ODA course has not been tested."},{id:"self-compassion",title:"Han & Kim · 2023 · Meta-analysis of self-compassion interventions",url:"https://pubmed.ncbi.nlm.nih.gov/37362192/",type:"research",finding:"Across 56 randomized trials, self-compassion interventions showed small-to-medium short-term average effects on stress, anxiety and depressive symptoms.",limitation:"The overall risk of bias was high; data on active comparisons and online delivery are more limited. The abstract that was reviewed does not prove a treatment effect for this exercise."},{id:"monitoring",title:"Harkin et al. · 2016 · Meta-analysis of progress monitoring",url:"https://pubmed.ncbi.nlm.nih.gov/26479070/",type:"research",finding:"138 experimental studies, 19,951 people: interventions that increased progress monitoring showed an average benefit for reaching goals (d = 0.40). The benefit was larger when progress was reported to others or made public and when it was physically recorded.",limitation:"Very different goals and monitoring methods were pooled. You do not need to share your private notes; the tracking screen used here has not been tested separately. The abstract was reviewed."},{id:"confidence-fear-ladder",title:"Psychology Tools · Fear ladder (exposure hierarchy)",url:"https://www.psychologytools.com/resource/fear-ladder",type:"guidance",finding:"A clinician resource describing the fear ladder used in cognitive behavioral therapy for anxiety: identify the fear, list feared situations, give each a predicted fear rating, rank them from least to most frightening, and begin gradual exposure with the lower steps, moving up over time. It notes that the pace should be adjusted if a person becomes overwhelmed and that therapists usually guide the process.",limitation:"A practical guide for clinicians, not a study; it describes how exposure is done in therapy rather than testing a self-help version. This course uses the idea only for everyday, safe challenges."},{id:"confidence-five-second-rule",title:"Mel Robbins · The 5 Second Rule (2017) · “Motivation is garbage” podcast episode",url:"https://www.melrobbins.com/episode/episode-3/",type:"technique",finding:"Robbins describes counting backward “5, 4, 3, 2, 1” and then moving, so that you act in the short window between an impulse and the moment when fear, excuses and self-doubt talk you out of it. She argues that action comes first and motivation follows.",limitation:"The author’s own podcast page. We found no controlled study of the 5 second rule itself; the evidence is mostly personal stories. Its useful core, a clear cue that starts a small, planned action, overlaps with if–then planning."}],C={id:"confidence",title:"Confidence",subtitle:"One step, even when you are scared.",description:"Notice your inner critic, choose a safe experiment, and move forward on the strength of your own effort.",scope:"Everyday courage and self-compassion practice. It is not exposure therapy for dangerous situations, trauma or intense anxiety; for those, please work with a trained professional.",outcome:"A courage step that fits you and a plan for trying again.",photo:{id:"1756244834590-b1a32e94df40",alt:"Woman looking out over a mountain lake at sunrise"},lessons:[{id:"confidence-1",title:"Name the fear, not yourself",minutes:6,goal:"Separate a feeling from the verdict you pass on yourself.",reading:["“I get nervous when I speak” describes an experience. “I’m not good enough” is a verdict that spreads across your whole life. Today, without trying to prove or disprove the second sentence, we will describe what happens to you more concretely: where you are, what you are doing and what you feel. A description gives you something to work with; a verdict only gives you something to carry around. You can change a situation step by step, but it is hard to change a verdict.","Choose a safe, small situation, such as sharing an idea in a meeting. The fear does not need to disappear for this lesson to work; you are only practicing a more accurate way of describing it. If a situation is genuinely dangerous, setting a boundary and asking for help are brave decisions too. Courage does not mean walking into harm; it means choosing a step that is right for you, at a pace you can manage, with support when you need it."],practice:["Describe in one sentence a safe situation you have held back from recently.","Notice the label you have stuck on yourself and restate it as “In this situation, I feel …”.","Say to yourself, out loud or silently, the understanding response you would give a close friend."],reflection:"What was your fairer sentence about yourself?",question:"Which one separates the situation from your identity?",options:["I always fail.","I got tense in this conversation; I can prepare a short sentence.","I should never get tense again."],correct:1,feedback:"Naming a specific situation makes room for a next step that can change. A feeling is not a summary of who you are.",takeaway:"Fear is an experience, not the whole of you.",sources:["self-compassion","bandura-self-efficacy"],visual:{kind:"compare",title:"From a label to a description",left:{label:"Label",items:["I’m not good enough.","I always fail.","That’s just the kind of person I am."]},right:{label:"Description of the situation",items:["I get nervous when I speak.","I got tense in this conversation.","I hold back when sharing ideas in meetings."]},note:"The sentences on the right do not deny the feeling; they make room for a next step that can change."},deeper:[{heading:"Why labels are so sticky",paragraphs:["A label is efficient. “I’m bad at speaking up” saves you the effort of looking at each situation, and it also seems to protect you: if you already expect to fail, nothing can surprise you. The cost is that a label has no handle. You cannot practice “not being useless,” but you can practice “saying one sentence in the Monday meeting.”","Talking to yourself the way you would talk to a friend is not a trick to feel good. Self-compassion interventions showed small-to-medium short-term reductions in stress and anxiety across 56 randomized trials, although the studies had a high overall risk of bias. A calmer, fairer inner voice leaves more room to see what actually happened."],visual:{kind:"table",title:"Rewriting a label as a situation",columns:["Label","Situation + feeling","Possible next step"],rows:[["I’m awkward.","At parties with strangers, I feel on edge.","Prepare one question to ask someone"],["I’m a coward.","I held back when my manager disagreed with me.","Write down the point I wanted to make"],["I’m hopeless at this.","On my first try at the presentation, I lost my place.","Practice the opening twice out loud"]],note:"The middle column is honest about the feeling; the right-hand column gives it somewhere to go."}},{heading:"Your body’s part in it",paragraphs:["Albert Bandura listed the state of the body among the four sources of self-efficacy, your belief that you can do something. A racing heart, a dry mouth or a shaky voice can easily be read as proof: “See, I can’t do this.” But a pounding heart can also simply mean that something matters to you. It is information about the moment, not a verdict about your ability.","So when you describe the situation, you can include the body without letting it decide: “My heart was pounding, and I still said my sentence.” Both parts are true, and together they tell a very different story from “I was a nervous wreck.”"]}],example:{title:"Olivia, 33, lab technician",text:"In team meetings Olivia rarely spoke, and afterward she would think, “I’m just not a confident person.” On Tuesday evening she tried the exercise. The safe situation: the weekly lab meeting, when her supervisor asks for comments. The label: “I’m hopeless in groups.” She rewrote it: “In the weekly meeting, when everyone looks at me, I feel my face go hot and I freeze.” Then she asked what she would tell her friend Mei in the same spot, and wrote: “Lots of people freeze when all eyes are on them. You know your work.” Nothing changed at the next meeting. But when her face went hot, she thought “there’s the heat” instead of “there’s proof,” and that felt slightly lighter."},photo:{id:"1579017308347-e53e0d2fc5e9",alt:"Person writing by hand in an open notebook"}},{id:"confidence-2",title:"The smallest form of courage",minutes:7,goal:"Turn a goal that feels hard into a safe, doable experiment.",reading:["“I’ll speak comfortably in front of everyone” can be a big, vague expectation. Today’s experiment might be just preparing one question, or telling one person you trust about your idea. Being small does not make it unimportant. Small experiments are how you collect evidence that the larger version might be possible too, and each one teaches you something about what helps you and what gets in the way. The step only has to be real, not impressive.","Keep control of the step you choose. If the discomfort climbs too high, you can stop, choose a smaller step or ask for support. You do not need to compete with this course to push yourself. The point is not to prove that you can endure anything, but to learn that you can act while some fear is still present. A step that is slightly uncomfortable but clearly doable is usually the right size to begin with."],practice:["Think of an easy, a medium and a hard version of the thing you hold back from.","Choose the smallest version you can safely try today, and decide where you will do it.","Do the experiment you chose, or finish the concrete preparation for a suitable time."],reflection:"Which small experiment suits you right now?",question:"Which choice is more useful for a first step?",options:["I have to do the hardest one.","Waiting vaguely until the fear is completely gone.","Choosing a small, concrete experiment within my own limits."],correct:2,feedback:"The aim is not to defeat your biggest fear, but to be able to choose a behavior that suits you. You do not need to put yourself in danger.",takeaway:"Sometimes courage is a single sentence.",sources:["mcii","self-compassion","confidence-fear-ladder","bandura-self-efficacy"],visual:{kind:"table",title:"Three versions of the same task",columns:["Version","Example experiment"],rows:[["Easy","Preparing one question in advance"],["Medium","Telling one person you trust about your idea"],["Hard","Speaking in front of everyone"],["Your task","Easy: … / Medium: … / Hard: …"]],note:"Choose the smallest version you can safely try today. If the discomfort climbs too high, you can stop or make the step smaller."},deeper:[{heading:"From three versions to a ladder",paragraphs:["The easy–medium–hard exercise is a small version of a tool therapists use called a fear ladder, or exposure hierarchy. You list situations connected to one fear, guess how frightening each would feel, and order them from least to most. Then you start near the bottom and move up only when a step starts to feel manageable. In cognitive behavioral therapy for anxiety, this gradual approach is a core tool.","For everyday confidence, the same shape works on a smaller scale. A rating from 0 (no fear) to 10 (the most you can imagine) is enough. Aim your first experiments at the rungs that feel like a 3 or a 4: uncomfortable but doable. If a step turns out to be a 9, that is not failure; it tells you to add a rung below it."],visual:{kind:"steps",title:"A sample confidence ladder: speaking up at work",steps:[{label:"Fear 2",text:"Write down one comment before the meeting."},{label:"Fear 4",text:"Share the comment with one colleague afterward."},{label:"Fear 5",text:"Ask one question in a small meeting."},{label:"Fear 7",text:"Give your opinion in the full team meeting."},{label:"Fear 9",text:"Present a short update to the whole department."}],note:"Move up only when the current rung feels manageable. For anxiety that is intense or rooted in trauma, build and climb a ladder with a trained therapist."}},{heading:"Why doing beats waiting",paragraphs:["Albert Bandura considered mastery experiences, things you have actually done, the strongest source of the belief that you can do something. Watching others, encouraging words and a calm body help too, but none of them carries the weight of your own experience. Waiting until the fear is gone skips the very thing that would reduce it.","That is also why the step should be yours. An experiment someone pushes you into, or one that goes far beyond what you can manage, is more likely to end in escape than in learning. A step you chose, at a level you can finish, leaves you with evidence you can trust."]}],example:{title:"Ben, 24, retail assistant",text:"Ben wanted to ask his manager for more hours but kept freezing. He drew three boxes. Hard: ask in person on the shop floor. Medium: send a short message asking for five minutes to talk. Easy: write down exactly what he wanted and why. Easy felt almost like cheating, but he did it on his lunch break, sitting in the staff room: “I’d like four more hours a week, ideally Saturdays; I’ve covered twice this month.” He rated the medium step at a 6 and decided to wait a day. On Thursday he sent the message. His hands were cold as he pressed send. The manager replied, “Sure, Friday after close.” The conversation itself was still ahead, but now he had two steps behind him."},photo:{id:"1635895752485-99ba511c07e1",alt:"Stepping stones across water at sunset"}},{id:"confidence-3",title:"Separate the prediction from what happened",minutes:8,goal:"Evaluate an experiment through observation rather than judgment.",reading:["Before a conversation, the mind can produce many scenarios, most of them unpleasant. After an experiment, it is also easy to remember only the moment you felt embarrassed. In this lesson, think about what a camera would have seen: the sentence you said, the reply you got, the help you asked for. A camera does not know what people were thinking; it only records what happened. That limitation is exactly what makes it useful here.","For example, “My voice shook, but I asked my question” holds two facts at once. Confidence becomes fragile when it depends on every experiment being flawless; here, your measure of success is trying the behavior you chose. Keeping a short record of what you actually did gives you something more reliable than the memory of how it felt. Over time, those records add up to evidence that your inner critic cannot easily dismiss."],practice:["Recall the prediction you had before your small experiment.","Write down or name silently two observations of what actually happened; separate mind reading from observation.","If you did not try, record that honestly and make your next experiment smaller."],reflection:"What was different from your prediction?",question:"Which one is observable information?",options:["Everyone thought I was ridiculous.","I asked my question and one person answered.","That’s just the kind of person I am."],correct:1,feedback:"Instead of assuming what others thought, record what was seen and heard. This record is not a performance grade.",takeaway:"Take one piece of information from today’s experiment.",sources:["monitoring","bandura-self-efficacy"],visual:{kind:"compare",title:"What would a camera have seen?",left:{label:"Prediction",items:["Everyone laughed at me.","Everyone noticed I was tense.","That’s just the kind of person I am."]},right:{label:"Observation",items:["I asked my question.","One person answered.","My voice shook, but I asked my question."]},note:"Instead of assuming what others thought, record what was seen and heard. This record is not a performance grade."},deeper:[{heading:"Bandura’s four sources, applied to your experiment",paragraphs:["Bandura described four sources that feed self-efficacy: mastery experiences, watching others, encouraging words from others, and the state of your body. Each experiment you try can draw on all four, but only if you notice them. A camera-style record helps with the first and the most powerful: it turns a blurry memory into a clear “I did this.”","Bandura also wrote that a belief built up through repeated success is shaken less by the occasional setback. That is why recording matters more than any single result. One awkward conversation, set against five recorded ones that went fine, looks like what it is: one data point."],visual:{kind:"table",title:"Four sources of self-efficacy in a courage experiment",columns:["Source","What to look for after your experiment"],rows:[["Mastery experience","What did I actually do? Write the behavior, not the grade."],["Watching others","Did I see someone else do something similar, imperfectly, and survive?"],["Encouraging words","Did anyone respond kindly, or can I say one fair sentence to myself?"],["Body state","Did the nervousness peak and then settle? When?"]],note:"Bandura considered mastery experience the most powerful source. This table is a reflection aid, not a treatment plan."}},{heading:"The replay trap",paragraphs:["After a social moment, many people replay it again and again, zooming in on one awkward second. Each replay feels like learning, but it mostly strengthens the prediction you started with. The camera question interrupts this: it asks for two observations and then lets you stop.","Tracking progress in writing was linked to better goal attainment in a large meta-analysis, and physically recording it was linked to a larger benefit. A replay is not a record. A record is short, factual and finished; you can close the notebook."]}],example:{title:"Lucas, 30, software developer",text:"Lucas had asked a question at a conference Q&A, his experiment for the week. Walking out, his mind was already replaying it: his voice had cracked, and surely everyone had noticed. That night he opened his notes and wrote his prediction from before: “I’ll stumble, the speaker will be dismissive, people will stare.” Then two camera observations: “I asked about the migration timeline. The speaker said it was a good question and answered for about a minute.” He added: “My voice cracked on the first word.” Reading the three lines together, the crack looked small next to the rest. He wrote one more line for next time: “Same kind of question, in a smaller session.”"},photo:{id:"1572020487535-31e268b25e21",alt:"Man taking notes in a notebook"}},{id:"confidence-4",title:"A supportive sentence for your inner voice",minutes:6,goal:"After a mistake, talk to yourself in a way that is both honest and helpful.",reading:["Saying “Nothing happened” may not convince you. “That was hard; I still tried to say a sentence” may be more realistic. Being kind to yourself does not mean giving up responsibility. You can be warm and honest at the same time, the way a good coach is with a player after a rough game: clear about what went wrong, and clearly on the player’s side. That combination is what makes the next attempt feel possible.","If there was a mistake, pick the part that can be fixed. Apologizing to someone, checking the information again or preparing a note for the next meeting are concrete options. Putting yourself down does not replace these steps; it usually just makes them harder to take, because it adds shame to a situation that already feels uncomfortable. A repair, even a small one, turns the mistake into something you have dealt with rather than something you keep carrying."],practice:["Notice the harsh sentence in your mind; you do not have to keep rereading it.","Acknowledge the situation by saying, “This was hard for me.”","Then add one support or repair step."],reflection:"What sentence would you like to say to yourself in your next hard moment?",question:"What might a supportive inner voice sound like?",options:["I made a mistake; I can figure out the part to fix.","If I made a mistake, I’m worthless.","I’m perfect in every situation."],correct:0,feedback:"The first sentence protects both your responsibility and your humanity. Realistic support does not need exaggerated affirmations.",takeaway:"Being fair to yourself can make it easier to try again.",sources:["self-compassion","bandura-self-efficacy","self-forgiveness"],visual:{kind:"steps",title:"From a harsh inner voice to a supportive sentence",steps:[{label:"Notice",text:"See the harsh sentence; you do not have to keep rereading it."},{label:"Acknowledge",text:"“This was hard for me.”"},{label:"Speak fairly",text:"“I made a mistake; I can figure out the part to fix.”"},{label:"One step",text:"Apologize, check the information or prepare a note."}],note:"Being kind to yourself is not giving up responsibility; there is no need for exaggerated affirmations either."},deeper:[{heading:"What the research on self-compassion shows",paragraphs:["Across 56 randomized trials, self-compassion interventions showed small-to-medium short-term reductions in stress, anxiety and depressive symptoms. That is a real but modest effect, and the studies had a high overall risk of bias, so it is fair to hold the finding lightly. It also fits a study on procrastination, in which students who forgave themselves more for putting off one exam procrastinated less before the next.","A useful way to think of it is that harshness and kindness both aim at the same thing, doing better next time, but harshness adds fear on top, and fear tends to make the next attempt feel riskier. A fair, warm sentence leaves the lesson in place and takes the extra threat away."]},{heading:"Why overblown affirmations can backfire",paragraphs:["Bandura counted encouraging words among the sources of self-efficacy but saw them as weaker than your own experience. Telling yourself “I’m amazing at everything” right after a stumble clashes with what you just lived through, which can make it hard to believe.","Realistic support works with the evidence rather than against it. It names what happened, recognizes the effort, and points to a next step. Compare the two columns below and notice which ones you could actually believe on a bad day."],visual:{kind:"compare",title:"Hype or realistic support?",left:{label:"Hype",items:["“I’m perfect and nothing went wrong.”","“I’ll never make that mistake again.”","“Everyone loved it.”"]},right:{label:"Realistic support",items:["“That was hard, and I still did it.”","“I know which part to fix next time.”","“One person seemed interested; that’s a start.”"]},note:"Encouragement is most believable when it matches what actually happened."}}],example:{title:"Fatima, 42, school administrator",text:"Fatima sent a parent email with the wrong date for the school trip. When a parent replied pointing it out, her stomach dropped and the familiar voice started: “How could you be so careless? Everyone will think you can’t do your job.” She noticed the sentence and did not argue with it. She said quietly, “This was hard. I made a mistake with the date.” Then the fair part: “I can fix it within the hour.” She sent a short correction to all parents, thanked the one who had noticed, and added a date check to her email template. The embarrassment lingered for the afternoon. But she had spent her energy on the repair, not on the verdict."},photo:{id:"1573497491208-6b1acb260507",alt:"Two women sitting at a table talking"}},{id:"confidence-5",title:"Your own courage plan",minutes:8,goal:"Choose one experiment, one source of support and one review for the week ahead.",reading:["Finishing this course does not mean your fears will end. You can now use naming the feeling, shrinking the step and gathering information from an experiment together. These three tools work best as a routine: name, shrink, try, record, and then choose the next step based on what you learned. Fear may still come along each time; the difference is that you now have a way of moving with it rather than waiting for it to leave.","Build rest and support into your plan. A day without an experiment does not erase all your progress. Changing a step that does not work for you is taking your own life seriously. A plan that fits your real week, with its tired evenings and busy days, will carry you further than an ideal plan you cannot keep. Decide in advance who you could talk to if a step turns out harder than expected."],practice:["Decide on one safe behavior you will try in the coming days, and when.","Set up a starting plan: “If I want to hold back and put it off, first I will …”.","Choose a two-minute review after your experiment and a source of support you can reach if needed."],reflection:"What step are you choosing to take, even if you are scared?",question:"What if the plan does not work?",options:["I should criticize myself more harshly.","I should review the step and the conditions, and ask for support if needed.","It shows that I can never change."],correct:1,feedback:"Whether a plan works depends on conditions. Reviewing it is a normal part of the process.",takeaway:"Even when you are scared, you can choose a step that fits you.",sources:["mcii","monitoring","self-compassion","confidence-five-second-rule","confidence-fear-ladder"],visual:{kind:"table",title:"Courage plan template",columns:["Part of the plan","Your answer"],rows:[["Experiment","One safe behavior and when: …"],["Starting plan","“If I want to put it off, first I will ….”"],["Review","Two minutes after the experiment: what happened?"],["Support","Someone you can reach if needed: …"],["Rest","When you will take a break: …"]],note:"A day without an experiment does not erase your progress. You can change a step that is not working."},deeper:[{heading:"The 5 second rule, honestly",paragraphs:["Mel Robbins popularized a simple move for the moment of hesitation: count backward from five and, at one, physically move toward the action. Her idea is that there is a short window between an impulse and the flood of reasons not to act, and the countdown helps you use it. Many people find it a helpful nudge.","It is worth being clear about the evidence: we could not find a controlled study of the 5 second rule itself, and the support for it comes mainly from personal stories. Its useful core looks a lot like an if–then plan with a built-in cue: “If I notice myself hesitating, then I count down and take the first small action.” Used that way, for a step you have already chosen and that is safe, it is a low-cost experiment."]},{heading:"Keeping the ladder going",paragraphs:["Confidence tends to grow unevenly. Some weeks you will climb a rung; some weeks you will stay put or step down because life got heavy. A short weekly review keeps you honest without turning it into a grade. Written records were linked to a larger benefit in the progress-monitoring research, so a few lines on paper are worth the two minutes.","Use the review to pick the next rung, not to judge the last one. If a step felt like a 3 twice in a row, it may be time to move up. If it felt like an 8, add a smaller step below it. Either way, you are learning how your courage works."],visual:{kind:"table",title:"Two-minute weekly review",columns:["Question","Example answer"],rows:[["What did I try?","Asked one question in the small meeting."],["How scary was it, 0–10?","Before: 6. After: 3."],["What did a camera see?","I asked; my manager wrote it down."],["Next rung?","Same step once more, then a comment in the full meeting."]],note:"Ratings are for choosing the next step, not for grading yourself."}}],example:{title:"Rosa, 57, returning to work after years at home",text:"Rosa wanted to introduce herself to the other volunteers at the library, but each week she would slip in, sort books and leave. Her plan: on Saturday, say hello and her name to one volunteer. Starting plan: “If I want to slip away, first I will count down from five and say ‘Hi, I’m Rosa.’” Support: her daughter, who would call on Saturday evening. On Saturday she caught herself heading for the back room. She counted, turned around and said it to the woman at the returns desk. The woman smiled, said her own name, and went back to work. That was all. In her two-minute review Rosa wrote: “Fear before: 7. After: 3. Next: ask someone how long they have volunteered.”"},technique:{name:"The 5 second rule",origin:"Mel Robbins · The 5 Second Rule (2017)",steps:["Choose in advance one safe, small action you want to take, such as asking your question in the meeting.","Notice the moment you start to hesitate: a pause, an excuse, a sudden urge to do something else.","Count backward silently: 5, 4, 3, 2, 1.","At “1,” make the first physical move toward the action: raise your hand, stand up, press call.","Afterward, write one line about what you did, and choose whether to use the countdown again."],evidence:"We found no controlled research on the 5 second rule itself; the support is mostly personal stories. Its working core, a clear cue linked to a small, pre-chosen action, resembles if–then planning, which has research support. Use it only for steps that are safe and that you have chosen, not to push through real danger or intense anxiety.",sourceId:"confidence-five-second-rule"},photo:{id:"1748609422318-7301636fb625",alt:"Hand writing a plan in a notebook with checkboxes"}}]},H=Object.freeze(Object.defineProperty({__proto__:null,COURSE:C,SOURCES:D},Symbol.toStringTag,{value:"Module"})),O=[{id:"adhd-cbt",title:"Safren et al. · 2010 · Randomized trial of CBT for adult ADHD",url:"https://jamanetwork.com/journals/jama/fullarticle/186469",type:"research",finding:"In 86 adults whose ADHD symptoms continued despite medication, 12 individual sessions of therapist-led CBT (organizing and planning, reducing distractibility, adaptive thinking) did better than an attention-matched comparison of relaxation with educational support. 67% of the CBT group had at least a 30% drop in symptoms, against 33% in the comparison group; gains held at the 6- and 12-month follow-ups.",limitation:"This short course is not the therapy used in the trial. The results cannot be carried over to people not taking medication or to children, and extra treatments during follow-up limit interpretation. The article page and summary were read."},{id:"nimh",title:"NIMH · ADHD in adults: what you need to know",url:"https://www.nimh.nih.gov/health/publications/adhd-what-you-need-to-know",type:"guidance",finding:"ADHD is a persistent pattern of inattention and/or hyperactivity and impulsivity that makes it hard to function in at least two areas of life. Assessment and treatment are carried out with a health care provider; the most common treatments for adults are medication (usually stimulants) and behavioral or cognitive behavioral therapy, and some adults also use an ADHD coach or workplace accommodations.",limitation:"A course or a short quiz cannot diagnose anything. If difficulties are lasting and affect your daily life, you can seek an assessment. US guidance; services and rights differ by country."},{id:"adhd-cbt-meta",title:"Young, Moghaddam & Tickle · 2020 · Meta-analysis of CBT for adult ADHD",url:"https://journals.sagepub.com/doi/abs/10.1177/1087054716664413",type:"research",finding:"Nine randomized trials were found and eight pooled. Compared with waitlist controls (4 trials, 160 people), CBT reduced ADHD symptoms with a moderate-to-large effect (SMD = 0.76). Compared with active control groups (3 trials, 191 people), the effect was small-to-moderate (SMD = 0.43).",limitation:"Few trials with modest samples, so the conclusions are tentative. These are therapist-led programs, not self-help reading. Only the abstract was read."},{id:"adhd-cbt-program",title:"Sprich, Knouse, Cooper-Vince, Burbridge & Safren · Description and demonstration of CBT for ADHD in adults (Cognitive and Behavioral Practice)",url:"https://pmc.ncbi.nlm.nih.gov/articles/PMC3874265",type:"guidance",finding:"Describes the modular CBT program: one calendar and one task list checked every day, priority ratings, problem solving and breaking tasks into manageable steps; a “distractibility delay” (work for about your measured attention span, write distractions down, deal with them when the timer ends); a distraction-free workspace with materials at hand; and adaptive thinking that addresses both overly negative and overly optimistic thoughts.",limitation:"A clinical description written by the program’s developers, meant for therapists; it does not test each technique separately. The full text on PubMed Central was read."},{id:"adhd-safren-workbook",title:"Steven A. Safren, Susan E. Sprich, Carol A. Perlman & Michael W. Otto · Mastering Your Adult ADHD, Client Workbook (2nd ed., 2017)",url:"https://global.oup.com/academic/product/mastering-your-adult-adhd-9780190235567",type:"technique",finding:"The client workbook of the CBT program for adults who need skills beyond medication: organizing and planning (systems for appointments and tasks, problem solving), reducing distractibility (assessing attention span, changing the environment), adaptive thinking, and optional modules on procrastination and relapse prevention.",limitation:"The workbook is designed to be used with a therapist. The publisher’s description was read; techniques are retold here in ODA’s own words."},{id:"adhd-barkley",title:"Russell A. Barkley · The important role of executive functioning and self-regulation in ADHD (fact sheet)",url:"https://www.russellbarkley.org/factsheets/ADHD_EF_and_SR.pdf",type:"technique",finding:"Barkley describes ADHD as mainly a disorder of performance rather than knowledge: people often know what to do but struggle to do it. He recommends help at the “point of performance” (the place and moment where the problem happens), making information physical and visible there, breaking long projects into daily steps with quick feedback, and adding external motivation such as rewards and accountability.",limitation:"A clinician’s theory-based fact sheet, not a trial; the specific tips have not been tested one by one. It also covers children and schools; the adult applications here are ODA’s adaptation."},{id:"adhd-body-doubling",title:"Eagle, Baltaxe-Admony & Ringland · 2024 · Body doubling with neurodivergent participants (ACM TACCESS)",url:"https://leyabreanna.com/papers/body_double_taccess.pdf",type:"research",finding:"Online survey of 220 people (193 neurodivergent, most with ADHD). 75% said they use body doubling — having someone present in the room, online or through media while starting or doing a task — mostly with friends, family or coworkers, and mostly for chores, schoolwork and work tasks. People used it to start tasks, stay focused, feel less anxious and find motivation.",limitation:"A self-selected online survey of experiences, not a controlled trial: it shows how people use body doubling, not how well it works. Mostly US/EU and female-identifying participants."}],P={id:"adhd",title:"Everyday life with ADHD",subtitle:"Structure that fits your mind.",description:"Try small tools for getting started, making time visible and finding your way back when your attention drifts.",scope:"Skills training for adults. It is not a diagnosis or treatment and not a substitute for care. If difficulties are lasting and get in the way of daily life, talk to a health professional. Never start, stop or change medication without talking to your doctor.",outcome:"One task list, a tested work interval and a plan for getting back on track.",photo:{id:"1759984782055-defe1abc0394",alt:"Young woman wearing headphones, working at a desk"},lessons:[{id:"adhd-1",title:"Move the load from your head to paper",minutes:7,goal:"Gather the tasks you are trying to remember into one place.",reading:["Living with ADHD, knowing a plan and carrying it out in the moment can be two very different challenges. The psychologist Russell Barkley describes ADHD as mainly a problem of doing what you know, rather than of knowing what to do. That gap is not laziness, and it is not a lack of faith or willpower. When tasks are kept in several places at once — in your head, on sticky notes, in three different apps — they tend to vanish during the day and then reappear at the worst moment.","Today you will not build a perfect system. Choose one place: a sheet of paper, a phone note or your ODA notebook. The experiment in this lesson is simple. Anything with a fixed time, like an appointment, goes into your calendar; everything else you need to do goes onto one single list. A well-studied CBT program for adults with ADHD starts in the same spot: one calendar and one task list come first, before any other skill."],deeper:[{heading:"Why it works: put the reminder where the work happens",paragraphs:["Barkley’s central idea is the “point of performance”: the place and moment where you need to act. Reminders kept only in your head are weak at that moment, so he suggests making information physical and visible exactly there. A list on the fridge, a note on the laptop lid or an alarm with a clear label does the remembering so your working memory does not have to.","This is why the goal is one list rather than a better memory. The list does not need to be beautiful. It needs to be in sight when you need it."],visual:{kind:"compare",title:"Kept in your head or kept in the world",left:{label:"Kept in your head",items:["Remembered at 2 a.m., forgotten at 2 p.m.","Competes with everything else you are thinking","Invisible when you actually need it"]},right:{label:"Kept in the world",items:["Written in one place you check","Placed where the task happens","Frees attention for the task itself"]},note:"Based on Barkley’s point-of-performance idea: move the information into your surroundings."}},{heading:"How the CBT program does it",paragraphs:["In the program developed by Steven Safren and colleagues, the first sessions set up two tools: a single calendar for everything with a date or time, and a single task list for everything else, both checked every day. Tasks get a simple priority rating, and big ones are broken into manageable steps.","One point from the program is worth remembering: looking at your list does not mean you must do everything on it right now. The list gives you a clear view of your options. Avoiding it tends to turn tasks into surprises, which feel more stressful than a list ever does."],visual:{kind:"table",title:"Two tools, two jobs",columns:["Tool","What goes there","When you look"],rows:[["Calendar","Appointments, deadlines, anything with a time","Once a day, at a fixed moment"],["Task list","Everything else you need to do","At the same daily moment"],["Nowhere else","Sticky notes and loose reminders get moved in","When you find one"]],note:"Adapted from the organizing module of the CBT program for adult ADHD. The full program is delivered with a therapist."}}],example:{title:"Maya, 34, dental hygienist",text:"Maya kept tasks in four places: two apps, a notebook and the back of her hand. On Sunday evening she chose one: a plain note on her phone’s home screen. She moved five things onto it — renew car registration, call the landlord, buy a birthday card for her sister, return a library book, book an eye exam. The eye exam and the landlord call went into her calendar with times. She decided to glance at the note while her coffee brewed each morning. On Monday she only managed the birthday card. That was fine; the other four were still there on Tuesday instead of floating around in her head. By Friday three were done, and the note had survived a whole week, which was a first."},practice:["Choose one single place where you will collect your tasks.","Move up to five tasks from your head into it; do not promise to finish them all today.","If a task has a fixed time, add it to your calendar, and decide when you will check your list."],reflection:"Where will you be able to see your list during the day?",question:"What is the goal of this lesson?",options:["Memorizing every task.","Diagnosing ADHD.","Creating one external record that supports your memory."],correct:2,feedback:"An external record is a tool that takes weight off your memory. These questions are not a diagnostic assessment.",takeaway:"You do not have to carry everything in your head.",sources:["adhd-cbt","nimh","adhd-barkley","adhd-cbt-program","adhd-safren-workbook"],visual:{kind:"steps",title:"From your head to one external record",steps:[{label:"Pick a place",text:"Paper, a phone note or your ODA notebook: just one."},{label:"Move tasks",text:"Write down up to five tasks; they will not all be finished today."},{label:"Timed tasks",text:"Put appointments and other timed tasks in your calendar."},{label:"Check-in",text:"Decide when you will look at the list."}],note:"An external record is a tool that takes weight off your memory. It is not a diagnosis or a treatment."},technique:{name:"One calendar, one task list",origin:"Steven A. Safren and colleagues · Mastering Your Adult ADHD, Client Workbook (2nd ed., 2017)",steps:["Pick one calendar for everything that has a date or a time, and stop using the others.","Pick one task list for everything else you need to do.","Move every sticky note and loose reminder into one of the two.","Look at both once a day at a fixed moment, such as while your coffee brews.","Give tasks a simple priority rating; treat the list as a menu of options, not an order to do everything today."],evidence:"This is the first module of a CBT program that, delivered by therapists over 12 sessions, did better than an active comparison in adults whose symptoms continued on medication. The calendar-and-list step on its own has not been tested separately.",sourceId:"adhd-safren-workbook"},photo:{id:"1488190211105-8b0e65b80b4e",alt:"A hand writing a list in a notebook with a pen"}},{id:"adhd-2",title:"The first visible move",minutes:6,goal:"Turn a big task into a physical movement you can start with.",reading:["“Deal with the paperwork” does not tell you where to begin. “Open the blue folder and write down the name of the first document” is a step someone could watch you do. When you describe a task, ask what your hands will do first. A vague task asks your brain to plan, prioritize and start all at once, and that is exactly the load that ADHD can make heavy. A concrete verb and a concrete object quietly do some of the planning for you.","You can keep the time short in this lesson. The few minutes suggested here are not a treatment dose or an ideal focus span; they are an experiment to find a start that fits you. If even the first move feels like too much, make it smaller: open the folder rather than sort it, put on your shoes rather than go for the run. Starting is its own skill, and it gets a little practice every time you try."],deeper:[{heading:"Why smaller steps help",paragraphs:["Barkley points out that ADHD makes the distant future feel faint, while whatever is right in front of you feels loud. A project due in a month barely registers until it is urgent. His advice is to break long tasks into short steps, each with quick feedback, so that progress is visible today rather than someday.","The CBT program for adult ADHD teaches the same move from another angle: tasks that feel overwhelming are broken into manageable steps, and each step goes on the list in its own right."],visual:{kind:"steps",title:"From vague to visible",steps:[{label:"Name it",text:"Write the task as you usually think of it: “sort taxes.”"},{label:"Ask",text:"What would my hands do first?"},{label:"Verb + object",text:"“Open the tax folder and find last year’s return.”"},{label:"Shrink",text:"Still stuck? Make it smaller: “Take the folder off the shelf.”"}],note:"A first move is small enough when you could start it in the next minute."}},{heading:"Make the start more inviting, on purpose",paragraphs:["Barkley also argues that reminders alone are often not enough, because the pull of a distant reward is weak. He suggests adding motivation at the point of performance: a small reward right after the step, someone who expects to hear from you, or a deadline you share with another person.","You can test your own versions: a favorite playlist only for paperwork, a coffee once the first email is sent, or a friend who gets a two-word text when you have started. Treat these as personal experiments rather than proven methods, and keep the ones that work for you."]},{heading:"Common mistakes",paragraphs:["The most common one is making a step shorter but not clearer. “Work on the report a little” is still vague; “open the report and read the last paragraph” is not. Another is judging the step as too small to count. A tiny start that happens beats a big plan that does not."]}],example:{title:"Luis, 41, warehouse supervisor",text:"For three weeks, “sort out the insurance claim” sat at the top of Luis’s list and he kept skipping it. On Thursday he looked at it and asked what his hands would do first. The answer was almost silly: find the email from the insurer. He rewrote the task as “search inbox for ‘claim number’ and star the email.” It took forty seconds. Since the email was already open, he downloaded the form. He stopped there, and that felt fine. On Friday the next move was clear: fill in page one. He texted his brother “started the claim,” and the reply — a thumbs-up — was a surprisingly good reward. The claim was sent the following Tuesday."},practice:["Pick one task from your list that matters today.","Split it into three small movements, starting the first one with a clear verb.","Try the first movement now; if you get stuck, make it even smaller."],reflection:"What is the first visible move in your task?",question:"Which one is a clearer starting point?",options:["Getting my life in order.","Opening the payment notice and checking the due date.","Being more disciplined."],correct:1,feedback:"A concrete verb and object show you where to start. You do not have to solve the whole goal at once.",takeaway:"You can start a task from its first movement, not as a whole.",sources:["adhd-cbt","adhd-cbt-program","adhd-barkley"],visual:{kind:"compare",title:"Vague task or visible move",left:{label:"Vague task",items:["Deal with the paperwork.","Get my life in order.","Be more disciplined."]},right:{label:"First visible move",items:["Open the blue folder, write down the name of the first document.","Open the payment notice, check the due date."]},note:"A clear verb and object show what your hands do first. If you get stuck, make the move even smaller."},photo:{id:"1754548930574-6a995e5eb5a7",alt:"A hand checking off a to-do list on a tablet"}},{id:"adhd-3",title:"Make time visible",minutes:8,goal:"Try a short work-and-break interval that suits you.",reading:["Estimating how long a task will take can be hard, and with ADHD time often slips by unnoticed — or drags. Today your goal is not to last as long as possible. It is to compare your guess with how long things really take. If you like, pick an easy starting length of two, five or ten minutes. Write down your estimate first, then start a timer you can see or hear, so time becomes something outside your head.","When the timer goes off, you do not have to keep going. Mark where you are, take a short break, and decide whether you want to start another round. There is no single method that fits everyone, and a fixed interval that suits a colleague may not suit you. Over a few rounds you will learn something useful: how long your real start takes, and how much you tend to over- or underestimate."],deeper:[{heading:"Why time slips away",paragraphs:["Barkley describes a kind of “time nearsightedness” in ADHD: behavior is steered mostly by what is happening now, and less by consequences that are still far away. The deadline next Friday feels unreal until Thursday night. This is not a character flaw; it is a pattern you can design around.","The design answer is to bring time closer. Make it physical, visible and near the task, and cut long gaps into short stretches with quick feedback. A visible countdown turns “later” into “in eight minutes.”"],visual:{kind:"table",title:"Ways to make time visible",columns:["Tool","What it does","Try it when"],rows:[["Clock in your line of sight","Keeps the time in view without checking your phone","You lose track of the afternoon"],["Visible countdown timer","Shows time running out as a shape or number","You start tasks late or overrun"],["Labeled alarm","Names the action: “Leave for pickup now”","You miss transitions"],["Estimate-and-check log","Compares your guess with the real time","Your plans are always too full"]],note:"Practical applications of externalizing time. No single tool is proven best; keep what works for you."}},{heading:"What the research says about skills programs",paragraphs:["Structured CBT for adults with ADHD, which includes planning and time skills, has been tested in randomized trials. A 2020 meta-analysis found a moderate-to-large effect on symptoms compared with waiting lists, and a small-to-moderate effect compared with active control groups.","These programs are delivered by trained therapists over several weeks. A short course like this one can introduce the skills, but it is not the same thing, and it has not been tested itself."],visual:{kind:"bars",title:"CBT for adult ADHD: average effect on symptoms",bars:[{label:"vs waitlist (4 trials)",value:.76,display:"SMD 0.76"},{label:"vs active control (3 trials)",value:.43,display:"SMD 0.43"}],note:"Young, Moghaddam & Tickle 2020: few trials with modest samples. Therapist-led programs, not self-help reading; this course was not tested.",sourceId:"adhd-cbt-meta"}}],example:{title:"Aisha, 27, graduate student",text:"Aisha believed answering her advisor’s email would take “two minutes,” so she kept postponing it to squeeze in later. On Wednesday she wrote her guess on a sticky note — 5 minutes — and started a phone timer she could see. When it rang, she was only halfway through. The real total was 17 minutes. She was not upset; it was useful. Her next round was reading a paper section: she guessed 20 minutes, it took 26. By Friday she noticed a pattern — her guesses were about a third too short — and began adding that margin to her calendar. Her afternoons felt less rushed, not because she worked faster, but because her plans finally fit the clock."},practice:["Estimate how long a small task will take and set a timer.","Work for the interval that suits you; if you need to stop early, count that as an observation too.","When you finish, check how far you got and adjust your next interval."],reflection:"Which interval seemed to suit you better?",question:"What is a good approach when the timer goes off?",options:["Checking how things are going and deciding on a break or another round.","Forcing myself to keep working no matter what.","Blaming myself if the interval felt short."],correct:0,feedback:"The timer is a tool for observation. Your work interval can change with your needs.",takeaway:"Estimate the time, try it, and adjust it to yourself.",sources:["adhd-cbt","monitoring","adhd-barkley","adhd-cbt-meta"],visual:{kind:"table",title:"Estimate and real time",columns:["Round","Estimate","Real time","Next interval"],rows:[["Round 1","… min","… min","… min"],["Round 2","… min","… min","… min"],["Round 3","… min","… min","… min"]],note:"You can choose an easy start of two, five or ten minutes. This is not an ideal focus span; it is an experiment."},technique:{name:"Bring time to the point of performance",origin:"Russell A. Barkley · Executive functioning and self-regulation in ADHD (fact sheet, russellbarkley.org)",steps:["Notice the exact moment where time usually gets away from you, such as starting work or leaving the house.","Put a visible time cue right there: a clock, a countdown or a labeled alarm.","Cut longer deadlines into daily steps, each one small enough to finish and check today.","Add a reason to act now at that moment, such as a small reward or someone expecting an update.","After a few days, keep the cues that helped and move or drop the rest."],evidence:"These suggestions come from Barkley’s clinical model of ADHD as a difficulty with self-regulation and fit what tested CBT programs teach. The individual tips have not been tested one by one.",sourceId:"adhd-barkley"},photo:{id:"1604344797006-2e4e8b39b79d",alt:"An hourglass on a wooden table"}},{id:"adhd-4",title:"Come back when your attention drifts",minutes:7,goal:"Try a way to postpone a distracting thought without losing it.",reading:["In the middle of a task, another task may pop into your head. Chasing it right away, out of fear you will forget it, can make it much harder to return to the first one. And once you return, you may have to find your place and warm up all over again. So put a small space next to you, a sheet or a note titled “Later,” where passing thoughts can wait safely instead of pulling you away.","Urgent needs and anything to do with safety should, of course, never wait. For everything else, jot the thought down in a few words, then go back to the next movement in front of you. There is no need to turn the number of times you drifted into a list of failures. Each time you notice and come back, you are practicing the very skill this lesson is about. The trail back matters more than a perfect streak."],deeper:[{heading:"How the “distractibility delay” works",paragraphs:["The CBT program for adult ADHD includes a technique called distractibility delay. First you find out how long you can usually stay with a less appealing task before your mind wanders. Then you work in chunks of about that length, with a notepad beside you. When a distraction arrives, you write it down instead of acting on it. When the timer ends, you look at the notes and decide what, if anything, needs doing.","The note is what makes this bearable. You are not ignoring the thought; you are giving it an appointment."],visual:{kind:"cycle",title:"The distractibility delay loop",center:"One work chunk",nodes:[{label:"Work",text:"Start a chunk about as long as your usual attention span."},{label:"Thought pops up",text:"Something else asks for your attention."},{label:"Write it down",text:"A few words on the “Later” sheet."},{label:"Return",text:"Find your place and do one more movement."},{label:"Timer ends",text:"Look at the sheet and decide what needs doing."}],note:"Adapted from the distractibility module of the CBT program for adult ADHD."}},{heading:"Body doubling: working alongside someone",paragraphs:["Many people with ADHD describe “body doubling”: having someone present — in the room, on a video call, or even in a “study with me” video — while they start or do a task. In a 2024 survey of 220 people, mostly with ADHD, three in four said they use it, mainly for chores, schoolwork and work tasks, to get started, stay focused and feel less anxious.","That survey describes experiences; it does not prove body doubling works for everyone. It is easy to test, though. Ask a friend to answer emails next to you for 25 minutes, or join a quiet online co-working room."]},{heading:"Shape the space around you",paragraphs:["The same program also changes the environment: a work spot without the usual distractions, the materials you need within reach, the phone out of sight, and planned breaks. Every distraction you remove in advance is one you do not have to resist in the moment."]}],example:{title:"Jordan, 38, freelance designer",text:"Jordan sat down to finish an invoice and, within a minute, remembered the dentist, a client’s font question and the dishwasher. Normally each thought became a detour. This time he had an index card labeled “Later” next to the keyboard and a 12-minute timer — roughly how long he usually lasted on admin. He wrote “dentist,” “font Q,” “dishwasher” in a few words each and put a finger back on the invoice line he was on. When the timer rang, the invoice was done. He looked at the card: the font question needed a reply, the other two could wait until evening. The next day he tried the same thing with a friend on a video call, both working in silence. It helped more than he expected."},practice:["Choose one distraction you can remove from your workspace.","Write down any non-urgent task that comes to mind in your “Later” space.","Find where you left off in the task you started — with your finger or a marker — and try one more movement."],reflection:"Which cue helped you get back?",question:"What if a non-urgent task comes to mind?",options:["I must switch to it right away.","I can write a short note and try to return to the task I chose.","I should give up on the experiment because my attention drifted."],correct:1,feedback:"A note can hold the thought and help you return to your priority. When something is truly urgent, changing the plan is the right call.",takeaway:"Even if your attention drifts, you can leave a trail back.",sources:["adhd-cbt","adhd-cbt-program","adhd-safren-workbook","adhd-body-doubling"],visual:{kind:"steps",title:"Getting back when your attention drifts",steps:[{label:"Notice",text:"Another task came to mind."},{label:"Urgent?",text:"If it is urgent or about safety, do not wait."},{label:"Note it",text:"If not, write it in a few words in your “Later” space."},{label:"Find your place",text:"Locate where you stopped with a finger or a marker."},{label:"Return",text:"Try one more movement on the task in front of you."}],note:"You do not need to count how often you drifted; what matters is leaving a trail to come back to."},technique:{name:"Distractibility delay",origin:"Steven A. Safren and colleagues · Mastering Your Adult ADHD, Client Workbook (2nd ed., 2017)",steps:["On a less appealing task, notice roughly how many minutes you can work before your mind wanders.","Set a timer for a chunk of about that length.","Keep a notepad or “Later” sheet next to you.","When a distracting thought arrives, write it down in a few words and return to the task.","When the timer ends, read the notes and decide what needs doing now, later or never.","Take a short break, then start the next chunk."],evidence:"Distractibility delay is part of a CBT program that did better than an active comparison in a randomized trial with 86 adults on medication. The technique has not been tested on its own, and the trial program was delivered by therapists.",sourceId:"adhd-safren-workbook"},photo:{id:"1624207616909-8bc0ca58743b",alt:"Yellow sticky notes stuck to a laptop"}},{id:"adhd-5",title:"Fit the system to yourself",minutes:8,goal:"Choose the tools that work and decide what support you need.",reading:["Not using a list does not mean you cannot use lists. Maybe the list was out of sight, too long, or checked at a time that did not suit your day. Instead of concluding that you are bad at systems, look at the exact point where the tool struggled. A system is something you design and adjust, like a pair of glasses. When it stops fitting, you change the prescription — you do not decide you are incapable of seeing.","If lasting problems with attention, impulsivity or organization affect your daily life, you can describe them to a health professional using concrete examples. Finishing this course does not mean you no longer need professional support; for many adults, skills work best alongside an assessment and treatment. And if you already take medication, any change should always be discussed with your doctor first. Asking for help is part of a good system, not a sign that yours has failed."],deeper:[{heading:"Troubleshoot the tool, not yourself",paragraphs:["The CBT program for adult ADHD pays special attention to two thinking traps. One is overly negative: “I will never manage this, so why try.” The other is overly optimistic: “I will do all ten things today,” followed by disappointment and self-criticism when the day runs out. Both can lead to avoiding the list altogether.","The program’s answer is to catch these thoughts and replace them with realistic ones based on what actually happened. That is exactly what reviewing your tool does: it turns a verdict about yourself into a question about the system."],visual:{kind:"compare",title:"Two thinking traps and a realistic answer",left:{label:"Trap",items:["“I am hopeless with lists.” (too negative)","“I will finish all ten tasks today.” (too optimistic)","“It failed once, so it does not work.”"]},right:{label:"Realistic answer",items:["“The list was out of sight; I will put it on the fridge.”","“I will pick two and see how the day goes.”","“I will change one thing and try three more times.”"]},note:"Adapted from the adaptive thinking module of the CBT program for adult ADHD."}},{heading:"When and how to seek professional help",paragraphs:["According to the US National Institute of Mental Health, ADHD is diagnosed by a health care provider, and in adults this includes looking at whether symptoms began in childhood. The most common treatments for adults are medication, usually stimulants, and behavioral or cognitive behavioral therapy. Some adults also work with an ADHD coach or ask for reasonable accommodations at work.","You do not need a perfect story to book an appointment. Bring a few concrete examples, what you have already tried, and your questions. If you take medication, never stop or change it on your own; talk to the doctor who prescribed it."],visual:{kind:"steps",title:"Preparing for an appointment",steps:[{label:"Examples",text:"Write down three recent situations where attention or organization caused real problems."},{label:"Where and when",text:"Note whether it happens at work, at home, in relationships — and since when."},{label:"What you tried",text:"List the tools from this course and what helped or did not."},{label:"Questions",text:"Bring your questions about assessment and treatment options."}],note:"Preparation helps the conversation; the assessment itself is done by a professional."}}],example:{title:"Hannah, 45, school administrator",text:"Hannah’s list had worked for two weeks and then quietly disappeared under a pile of mail. Her first thought was “I always ruin systems.” She tried looking at it the other way: what exactly went wrong? The list lived on her desk, but her mornings started in the kitchen. She changed one thing — a whiteboard next to the coffee maker — and kept it for the next three tries. It held. At the same time, she admitted that her struggles went well beyond lists: missed bills, unfinished projects, a lifetime of “not trying hard enough.” She wrote down three concrete examples and brought them to her doctor. She did not expect a quick answer, but for the first time she felt she was describing the problem accurately."},practice:["Pick one tool from the past lessons that helped you and one point where you struggled.","For your next three tries, change just one thing: a shorter list, another time or a more visible place.","If needed, choose one example from daily life you would share when talking with a trusted person or a health professional."],reflection:"Which tool will you keep, and which will you change?",question:"What if my difficulties clearly affect my life?",options:["Repeating the course always replaces treatment.","It is just a willpower problem.","I can talk with a health professional about assessment and support options."],correct:2,feedback:"Everyday tools can help, but diagnosis and treatment need an individual assessment.",takeaway:"Let the system serve you, and ask for help when you need it.",sources:["nimh","adhd-cbt","monitoring","adhd-cbt-program"],visual:{kind:"table",title:"Fit the tool to yourself",columns:["Where it struggled","One change"],rows:[["The list was not visible","Choose a more visible place"],["The list was too long","Try a shorter list"],["The check-in time did not fit","Try another time"]],note:"Change only one thing for the next three tries. If difficulties clearly affect your daily life, you can talk to a health professional."},photo:{id:"1549582100-d67ab35b3507",alt:"A planner and colorful pens on a white desk"}}]},W=Object.freeze(Object.defineProperty({__proto__:null,COURSE:P,SOURCES:O},Symbol.toStringTag,{value:"Module"})),E=[{id:"motivation-lally",title:"University of Surrey · “Does it really take 66 days to form a habit?” Interview with Dr Pippa Lally",url:"https://www.surrey.ac.uk/news/does-it-really-take-66-days-form-habit-we-asked-expert-dr-pippa-lally",type:"guidance",finding:"Lally explains that in her 2010 study the average time to form a daily habit was 66 days, but the range was 18 to 254 days: how long habit formation takes is highly variable. She notes that knowledge alone does not change behavior and recommends a clear plan of when and where you will do something.",limitation:"A university news interview summarizing the study, not the paper itself. The figures describe one sample and daily behaviors; your own time may differ."},{id:"motivation-sdt",title:"Center for Self-Determination Theory · The theory",url:"https://selfdeterminationtheory.org/theory/",type:"guidance",finding:"Self-determination theory, developed by Edward Deci and Richard Ryan, proposes three basic psychological needs — autonomy (acting with a sense of choice), competence (feeling capable) and relatedness (connection with others). Conditions that support these needs are argued to foster the most volitional, high-quality motivation; autonomous motivation comes from interest and values, controlled motivation from rewards, pressure or others’ expectations.",limitation:"An overview page by the theory’s own research center. It explains the theory; it does not by itself show how much any single exercise helps."},{id:"motivation-sdt-meta",title:"Ntoumanis et al. · 2021 · Meta-analysis of self-determination theory-based health interventions",url:"https://eprints.whiterose.ac.uk/id/eprint/155741/",type:"research",finding:"73 intervention studies in the health domain were pooled. Interventions based on self-determination theory produced small-to-medium changes in most of the theory’s measures, such as autonomous motivation, and small positive changes in physical and psychological health; gains in autonomous motivation and need support went together with positive changes in health behavior.",limitation:"Effects on health were modest and varied a lot between studies. The studies were about health behaviors, not all life goals. Only the abstract was read."},{id:"motivation-fogg",title:"BJ Fogg · Tiny Habits (2020) — interview in Forbes, “Stanford behavior scientist says this is the key to change”",url:"https://www.forbes.com/sites/alisacohn/2020/02/25/stanford-behavior-scientist-says-this-one-thing-is-the-key-to-change/",type:"technique",finding:"Fogg’s method has three parts: an anchor (an existing daily event, such as brushing your teeth, that reminds you of the new behavior), a tiny behavior (for example one minute of meditation instead of twenty, or flossing one tooth) and an immediate celebration, because in his view it is the positive emotion connected with the behavior that creates the habit.",limitation:"An interview summary of the book, which draws on Fogg’s own work and coaching. As far as we found, the full method and the celebration step have little independent controlled research behind them."},{id:"motivation-fogg-model",title:"BJ Fogg · Fogg Behavior Model (behaviormodel.org)",url:"https://behaviormodel.org/",type:"guidance",finding:"The model states B = MAP: a behavior happens when motivation, ability and a prompt come together at the same moment. When a behavior does not happen, at least one of the three is missing.",limitation:"A descriptive model presented on the author’s own site, not an experiment. It is a useful way to diagnose a stalled habit, not a measured prediction."},{id:"motivation-woop",title:"Gabriele Oettingen · WOOP: Wish, Outcome, Obstacle, Plan (woopmylife.org)",url:"https://woopmylife.org/",type:"technique",finding:"WOOP, developed by psychologist Gabriele Oettingen, has four steps: name a wish, imagine the best outcome, identify the inner obstacle that stands in the way, and make an if-then plan for meeting that obstacle. The site describes it as a science-based mental strategy for fulfilling wishes and changing habits.",limitation:"The official site of the method. Research on combining mental contrasting with if-then plans shows small-to-medium average effects (see the Wang et al. meta-analysis); the site itself was read, not each study."},{id:"motivation-milkman",title:"Katy Milkman · Temptation bundling (Character Lab tip; see also How to Change, 2021)",url:"https://characterlab.org/tips-of-the-week/temptation-bundling/",type:"technique",finding:"Milkman, a Wharton professor, describes temptation bundling as linking something you enjoy with a worthwhile activity that feels like a chore — for example, only reading a gripping novel while exercising, or only watching a favorite show while doing housework — so that pursuing the goal becomes more pleasurable.",limitation:"A short practice tip by the researcher. Field studies show modest average gains for exercise; the effect in other areas of life is less studied."},{id:"motivation-bundling-gym",title:"Milkman, Minson & Volpp · 2014 · Temptation bundling at the gym (Knowledge at Wharton summary)",url:"https://knowledge.wharton.upenn.edu/article/researchers-used-hunger-games-encourage-healthier-choices/",type:"research",finding:"In a nine-week experiment with 226 university gym members, people who could listen to tempting audiobooks only at the gym attended 51% more than a control group at first; the effect faded after the Thanksgiving break. At the end, 61% of participants chose to pay to keep their audiobooks restricted to the gym.",limitation:"One university sample and a short study, and the effect wore off. A university news summary of the paper was read, not the full paper."},{id:"motivation-bundling-teaching",title:"Kirgios et al. · 2020 · Teaching temptation bundling to boost exercise: a field experiment",url:"https://www.sciencedirect.com/science/article/pii/S074959782030385X",type:"research",finding:"In a large field experiment with 6,792 gym members, those given an audiobook plus encouragement to bundle it with exercise were 10–14% more likely to work out in a given week, with 10–12% more weekly workouts than the control group; benefits were still seen up to 17 weeks later.",limitation:"A modest average effect for exercise in gym members; not tested for other goals. Only the abstract was read."}],K={id:"motivation",title:"Motivation",subtitle:"Make starting easier.",description:"Link what you want to a small behavior, prepare for obstacles and find your way back when your rhythm breaks.",scope:"Training for everyday goals. Constant lack of drive, exhaustion or losing the ability to function may not be only a motivation problem; it is a good idea to get support, and a health professional can help you look at the cause.",outcome:"A starting cue, an obstacle plan and a weekly check-in.",photo:{id:"1790004245013-b347139d5591",alt:"A man running along a sunlit forest path"},lessons:[{id:"motivation-1",title:"Why is this goal yours?",minutes:6,goal:"Separate your own wish from other people’s expectations.",reading:["A goal can sound good and still have nothing to do with your actual life. Today, try this question: “If I did this, what would I like to change in my day?” Reading more books, for example, could serve your curiosity, your wish to learn, or simply a calm hour that belongs to you. The answer matters, because it tells you what kind of reading, and how much, would actually be worth it.","To tell whether a wish is really yours, ask whether you would still want it if nobody ever saw it. Goals that come from your own interests and values tend to feel lighter to carry than goals pushed by guilt or by someone else’s approval. And if a goal has lost its meaning for you right now, shrinking it or letting it go is also a choice — not a failure."],deeper:[{heading:"Three needs behind lasting motivation",paragraphs:["Self-determination theory, developed by the psychologists Edward Deci and Richard Ryan, suggests that motivation lasts better when three basic needs are met. Autonomy is the sense that you are choosing, not being pushed. Competence is the feeling that you can actually do it. Relatedness is feeling connected to other people along the way.","The theory also separates two kinds of motivation. Autonomous motivation comes from interest or from values you hold. Controlled motivation comes from pressure, rewards or other people’s expectations. Both can get you moving, but the first tends to be steadier."],visual:{kind:"table",title:"Three needs, three questions",columns:["Need","What it means","Ask yourself"],rows:[["Autonomy","Acting with a sense of choice","Am I choosing this, or just obeying a “should”?"],["Competence","Feeling capable of doing it","Is the first step small enough that I can succeed?"],["Relatedness","Feeling connected to others","Who could share this with me or cheer me on?"]],note:"Based on self-determination theory (Deci and Ryan). The questions are ODA’s adaptation."}},{heading:"What the research says",paragraphs:["A 2021 meta-analysis pooled 73 health intervention studies built on self-determination theory. On average, they produced small-to-medium increases in autonomous motivation and related measures, and small improvements in physical and psychological health. Where autonomous motivation grew, health behaviors tended to improve too.","The effects were modest and varied between studies, and they were about health habits rather than every kind of goal. Still, the direction is useful: a goal you genuinely endorse is a better starting point than one you feel you ought to have."]}],example:{title:"Sam, 31, customer service rep",text:"Sam had “run a marathon” on his goals list for three years, mostly because two coworkers talked about theirs. When he asked himself what he wanted to change in his day, the honest answer was different: he wanted to feel less stiff after work and have some time outside before dark. A marathon was not required for either. He rewrote the goal as “a 20-minute walk in the park after my shift, three days a week.” He also asked his neighbor, who walks her dog at the same time, if he could join her on Tuesdays. The first week he walked twice. It was smaller than a marathon, but it was his, and he actually looked forward to it."},practice:["Choose one goal that is on your mind.","Name what you would like this goal to serve in your daily life.","Pick one behavior you think is worth trying in the coming week."],reflection:"What will this behavior make room for in your life?",question:"Which question helps clarify a goal?",options:["How will everyone see me?","What would I like to change in my day if I did this?","Which is the most ambitious goal?"],correct:1,feedback:"A concrete difference in your own life is a more useful starting point than the size of the goal.",takeaway:"First, find what it means to you.",sources:["mcii","motivation-sdt","motivation-sdt-meta"],visual:{kind:"compare",title:"Questions that clarify a goal",left:{label:"Outward-looking question",items:["How will everyone see me?","Which is the most ambitious goal?"]},right:{label:"A question of your own",items:["What would I like to change in my day if I did this?","Would I still want this if nobody saw it?"]},note:"Shrinking or letting go of a goal that has lost its meaning is also a choice."},photo:{id:"1517971129774-8a2b38fa128e",alt:"A woman writing in a notebook by a window"}},{id:"motivation-2",title:"Shrink the start",minutes:6,goal:"Prepare a low-effort first version of your behavior.",reading:["“I will read a chapter every evening” can feel heavy on a busy day. One page, opening the book, or choosing the passage you will read first all make starting easier. This smaller version is a floor, not a ceiling: once you have started, you are free to keep going. On a good day you may read twenty pages; on a hard day, one page still keeps the thread alive, and that thread is what you are building.","Where your materials are is part of starting too. Putting your book somewhere visible, opening your file in advance, or leaving your shoes by the door are small arrangements you can make today. Each one removes a bit of friction between you and the first move. When the first move is easy, you need far less motivation to make it, which is exactly what you want on the days motivation is low."],deeper:[{heading:"Behavior needs motivation, ability and a prompt",paragraphs:["Stanford behavior scientist BJ Fogg sums up his model as B = MAP: a behavior happens when motivation, ability and a prompt come together at the same moment. If a behavior does not happen, at least one of the three is missing.","Motivation goes up and down on its own, so it is the least reliable lever. Ability — how easy the behavior is — is something you can design. That is why shrinking the start works: it lowers the bar so that even a low-motivation moment is enough."],visual:{kind:"table",title:"B = MAP: find the missing piece",columns:["Element","Question","Example fix"],rows:[["Motivation","Do I actually want this?","Reconnect with why it matters (lesson 1)"],["Ability","Is it easy enough right now?","One page instead of a chapter"],["Prompt","What reminds me at the right moment?","Book on the pillow (lesson 3)"]],note:"Based on the Fogg Behavior Model. When a behavior stalls, check which piece is missing."}},{heading:"Why Fogg adds a small celebration",paragraphs:["In Tiny Habits, Fogg adds a step many people skip: celebrate right after the tiny behavior, for example with a quiet “Yes!” or a smile. His view is that the positive feeling connected with the behavior is what helps the habit take root.","This part of the method rests mostly on Fogg’s own experience and coaching rather than on controlled trials, so treat it as an experiment. If a small moment of satisfaction makes you more likely to return tomorrow, keep it. If it feels forced, a simple check mark can do the same job."]}],example:{title:"Priya, 52, pharmacist",text:"Priya wanted to stretch in the evenings, but by the time dinner was cleaned up, a 20-minute routine felt impossible. She shrank it to one stretch: touching her toes for three breaths. She rolled her yoga mat out by the couch and left it there. On Monday she did the one stretch and, to her surprise, added two more. On Tuesday she was exhausted and did only the one — then said “done” out loud, which made her laugh. By the weekend the mat had become part of the living room, and the one stretch had quietly turned into five or six on most nights. Some evenings it was still just one, and she decided that counted."},practice:["Write down or say a very short version of your target behavior.","Put the one item you need somewhere easy to reach.","Try the short version once; decide afterward whether to keep going."],reflection:"Which bit of friction in front of your start did you remove?",question:"What is a small start for?",options:["It guarantees you will definitely reach your goal.","It rules out the big goal forever.","It is a way to reduce the effort the first move takes."],correct:2,feedback:"This is a design for starting, not a guarantee of results. Choose the size that fits your circumstances.",takeaway:"You do not need to finish the whole road in order to start.",sources:["mcii","habits","motivation-fogg","motivation-fogg-model"],visual:{kind:"table",title:"Shrink the start",columns:["Target behavior","Short version","Preparation"],rows:[["Reading a chapter every evening","Reading one page or opening the book","Putting the book where you can see it"],["Your goal: …","Short version: …","One item: …"]],note:"The short version is a floor, not a ceiling; you can keep going if you like. It is a design for starting, not a guarantee of results."},technique:{name:"Tiny Habits",origin:"BJ Fogg · Tiny Habits: The Small Changes That Change Everything (2020)",steps:["Choose a behavior you want and shrink it until it takes less than a minute, like one page or one push-up.","Pick an anchor: something you already do every day, such as brushing your teeth or pouring your coffee.","Write the recipe: “After I [anchor], I will [tiny behavior].”","Do the tiny behavior right after the anchor.","Celebrate immediately with a small gesture or word that feels good to you.","If you want to do more, go ahead — but the tiny version always counts."],evidence:"Small starting steps and a stable cue fit habit research, where repetition in the same context goes with growing automaticity. The full Tiny Habits method, and the celebration step in particular, has little independent controlled research behind it as far as we found.",sourceId:"motivation-fogg"},photo:{id:"1581578731509-8ae9c5a3e7d3",alt:"A pair of shoes waiting by the door"}},{id:"motivation-3",title:"Link it to a cue",minutes:7,goal:"Decide on the time or situation where your behavior will start.",reading:["“I will do it later” can easily vanish during the day. “When I put my evening tea on the table, I will open the book” shows exactly where the start is. Choose a moment that already exists in your life and happens fairly regularly: making coffee, sitting down on the bus, closing your laptop at the end of the workday. A good cue is specific enough that you would notice it, and it comes at a time when the behavior is actually possible.","Repeating a behavior in the same context is one of the main things habit research looks at, and how long a habit takes to form is not the same for everyone. So today’s task is not to complete a habit. It is only to test your own starting cue: does it happen reliably, do you notice it, and does the behavior fit right after it? If not, you simply pick another moment."],deeper:[{heading:"The anchor recipe",paragraphs:["BJ Fogg calls the cue an anchor and writes it as a short recipe: “After I [anchor], I will [tiny behavior].” The anchor should be something you already do every day without thinking, and the new behavior should fit naturally in that place — flossing after brushing, not after the morning commute.","Over many repetitions in the same context, the cue starts to bring the behavior to mind with less effort. That growing automaticity is what researchers mean by a habit."],visual:{kind:"cycle",title:"How a cue turns into a habit",center:"Same context, again and again",nodes:[{label:"Cue",text:"An anchor you already do: “After I pour my tea…”"},{label:"Tiny behavior",text:"“…I will open my book.”"},{label:"Good feeling",text:"A small moment of satisfaction."},{label:"Repeat",text:"The same cue, the same place, day after day."}],note:"A simplified picture based on habit research and Fogg’s recipe; it describes a direction, not a timetable."}},{heading:"How long does it take?",paragraphs:["You may have heard that a habit takes 21 or 66 days. In Pippa Lally’s 2010 study, the average for a daily habit was 66 days, but the range ran from 18 to 254 days. Lally herself stresses that the real finding is how variable habit formation is.","So there is no deadline to hit. If your habit still takes effort after a month, that is normal, not a sign that you are doing it wrong."],visual:{kind:"bars",title:"Days until a daily habit felt automatic",bars:[{label:"Fastest",value:18,display:"18 days"},{label:"Average",value:66,display:"66 days"},{label:"Slowest",value:254,display:"254 days"}],note:"Lally 2010, as explained by Lally in a University of Surrey interview: one sample and daily behaviors only; your own time may differ.",sourceId:"motivation-lally"}},{heading:"Common mistakes",paragraphs:["The most common cue is also the weakest: “when I have time.” It never arrives on schedule. Another mistake is choosing an anchor that happens at different times or places every day. Pick something steady, and if it does not work after a few tries, change the cue before you blame yourself."]}],example:{title:"Ben, 24, delivery driver",text:"Ben wanted to study Spanish but kept “finding time later,” which never came. He looked for something that happened every day at about the same time. The answer was lunch: he always ate in the van at around noon. His recipe became “After I open my lunch, I will do one lesson in my language app.” The first two days he forgot, because his phone was in the glove box. He moved it to the cup holder. On Wednesday it worked, and on Thursday too. On Friday he skipped lunch entirely, so there was no cue — he did the lesson at home and did not worry about it. Three weeks later, opening his lunch still reminded him, even on days he did not feel like it."},practice:["Choose a time or event that already exists in your day.","Complete the sentence: “When …, I will ….”","At the first suitable moment your cue happens, try the short behavior or get its place ready."],reflection:"What is your starting cue?",question:"Which plan is more concrete?",options:["I will study at some point.","I will start when inspiration comes.","After breakfast I will look at my notes at the table for two minutes."],correct:2,feedback:"Once the time, place and behavior are clear, you can actually try the plan and evaluate it.",takeaway:"Give your intention a moment to begin.",sources:["mcii","habits","motivation-fogg","motivation-lally"],visual:{kind:"steps",title:"Give your intention a starting moment",steps:[{label:"Cue",text:"A moment already in your day: “When I pour my evening tea…”"},{label:"Behavior",text:"“…I will open the book.”"},{label:"Try",text:"At the first suitable cue, try the short version."},{label:"Observe",text:"Did the cue work? If not, choose another moment."}],note:"How long a habit takes to form is not the same for everyone. Today you are only testing your starting cue."},photo:{id:"1499933374294-4584851497cc",alt:"A black alarm clock on a table"}},{id:"motivation-4",title:"Plan for the obstacle",minutes:8,goal:"Build a workable backup plan for an obstacle you can foresee.",reading:["Wanting a goal does not make the obstacles disappear. Coming home tired, not finding what you need, or getting pulled into your phone are different obstacles, and they do not all call for the same fix. Picturing the happy ending can feel great, but on its own it does not prepare you for the moment the obstacle shows up. Research on goal pursuit points to a more useful combination: picture the goal, then look honestly at what stands in the way, and decide in advance what you will do when it appears.","Do not blame yourself for conditions outside your control. Pick the small part you can change. “If I am very tired, I will read one paragraph instead of one page,” or “If I am ill, I will rest and come back when I can,” are both valid plans. A plan that fits your real life, including its bad days, is worth more than a perfect plan that only works on good ones."],deeper:[{heading:"Why dreaming alone is not enough",paragraphs:["Psychologist Gabriele Oettingen developed an approach called mental contrasting: you pair the wish you care about with a clear look at the obstacle standing in its way. Combined with an if-then plan, it became the four-step method WOOP: Wish, Outcome, Obstacle, Plan.","A meta-analysis of 21 studies found that combining mental contrasting with if-then plans had a small-to-medium average effect on reaching goals. That is a real but modest effect — a helpful tool, not a guarantee."],visual:{kind:"compare",title:"Positive fantasy or mental contrasting",left:{label:"Only the happy ending",items:["Imagine the goal already reached","Feel good now","Meet the obstacle unprepared"]},right:{label:"Mental contrasting (WOOP)",items:["Imagine the best outcome","Name the obstacle inside you","Link it to an if-then plan"]},note:"Based on Gabriele Oettingen’s WOOP. Dreaming is welcome; it simply works better alongside an honest look at the obstacle."}},{heading:"Inside obstacles and outside conditions",paragraphs:["WOOP focuses on the obstacle inside you — a habit, a feeling, a thought — because that is the part you can plan for. Outside conditions like a sick child, a night shift or a tight budget are real too, but they call for a different answer: changing the size, timing or shape of the goal, or asking for help.","Telling these apart protects you from two traps: blaming yourself for things you cannot control, and ignoring the things you can."]}],example:{title:"Grace, 36, bank teller",text:"Grace wanted to practice guitar three evenings a week. She tried WOOP on the bus home. Wish: play three songs well by summer. Best outcome: playing at her niece’s birthday. Obstacle — the honest one: when she got home, she sat on the couch “for a minute” and the evening was gone. Plan: “If I feel the pull of the couch, I will take the guitar out of its case before I sit down.” The first evening she forgot the plan. The second evening she remembered, took out the guitar and played for ten minutes on the couch itself. On Thursday her shift ran late — an outside condition — so she let it go without guilt and played on Saturday instead."},practice:["Name the situation that most often derails your plan.","Choose the part you can change; if there is a real need, put it first.","Create a small backup response: “If …, then I will ….”"],reflection:"What is your obstacle, and what is your backup response?",question:"What does a good obstacle plan look like?",options:["It assumes no obstacles will come up.","It links a doable response to a specific situation.","It demands the same pace in every condition."],correct:1,feedback:"Your plan should adapt to your real life. When needed, resting or changing the goal is also a workable response.",takeaway:"Seeing the obstacle is not the same as giving up.",sources:["mcii","motivation-woop"],visual:{kind:"bars",title:"Obstacle plus if-then plan: average effect",bars:[{label:"Wang et al. 2021 · 21 studies",value:.336,display:"g = 0.336"}],note:"Comparing a goal with the real obstacle and making an if-then plan had a small-to-medium average effect. Publication bias is possible; this is an average, not a personal guarantee.",sourceId:"mcii"},technique:{name:"WOOP (Wish, Outcome, Obstacle, Plan)",origin:"Gabriele Oettingen · WOOP (woopmylife.org), based on her research on mental contrasting",steps:["Wish: name one wish that is challenging but possible for you.","Outcome: imagine the best result of fulfilling it and let yourself feel it for a moment.","Obstacle: ask what inside you — a habit, feeling or thought — most gets in the way.","Plan: write an if-then sentence: “If [obstacle], then I will [action].”","Repeat the plan once to yourself so it is ready when the moment comes."],evidence:"In a meta-analysis of 21 studies, combining mental contrasting with if-then plans had a small-to-medium average effect on goal attainment (g = 0.336). Publication bias is possible and results vary between people and settings.",sourceId:"motivation-woop"},photo:{id:"1575478004055-999ebe26dab7",alt:"A woman walking in the rain with an umbrella"}},{id:"motivation-5",title:"Come back after a miss",minutes:7,goal:"Use information, not guilt, to set up your next attempt.",reading:["Breaking your rhythm for a day does not make your earlier efforts worthless. You do not have to double your workload to make up for the days you missed; that usually makes the next attempt harder, not easier. You can simply go back at the next suitable starting cue, with the small version of your behavior. Coming back is not a detour from the process. It is a normal, expected part of it.","In your short weekly check-in, think not only about how many times you did it, but also about what helped. Was it the cue, the time of day, the size of the step, someone doing it with you? If a goal no longer matters to you, or simply does not fit your life right now, change it. Adjusting a plan based on what you learned is progress, not quitting. Keep the check-in short enough that you will actually do it."],deeper:[{heading:"One missed day does not erase a habit",paragraphs:["In Lally’s habit study, missing the behavior once did not noticeably set back the process of it becoming automatic. What seems to matter more is returning. The danger of a missed day is less the day itself than the story that follows: “I have broken my streak, so why bother.”","A kinder and more useful rule is to treat the next cue as a fresh chance and to go back to the tiny version, not the heroic one."]},{heading:"Make coming back more attractive",paragraphs:["Wharton professor Katy Milkman studies a trick called temptation bundling: pair something you enjoy with something you tend to avoid. In her first study, people who could hear gripping audiobooks only at the gym went 51% more often than a control group at first, although the effect faded after a holiday break.","A later field experiment with 6,792 gym members found a smaller but lasting effect: simply teaching people to bundle an audiobook with exercise made them 10–14% more likely to work out in a given week, with benefits still visible up to 17 weeks later. It is a modest boost, not magic, and it is easy to try."],visual:{kind:"table",title:"Temptation bundling in two studies",columns:["Study","Who","What happened"],rows:[["Milkman et al. 2014","226 university gym members","51% more gym visits at first with gym-only audiobooks; the effect faded after a break"],["Kirgios et al. 2020","6,792 gym members","Taught to bundle: 10–14% more likely to work out in a given week, up to 17 weeks"]],note:"Both studies are about exercise. The effect is modest on average and may differ for other goals."}}],example:{title:"Kofi, 47, bus mechanic",text:"Kofi had kept up his evening walk for eleven days when a family visit knocked it out for five. His first thought was that he had “ruined it” and would need to walk twice as far to make up. Instead, he looked at his short weekly note: what had helped? Walking right after dinner, and his podcast. What had not? Nothing about the plan — just a busy week. So on Monday he returned to the small version: one loop around the block after dinner. To make it more inviting, he saved his favorite football podcast for walks only. That week he walked four times. The five missed days were still missed, but they no longer felt like the end of something."},practice:["Honestly rate your last attempt: done, partly done or not done.","Name one condition that helped, or one thing you could change.","Choose your next small attempt and create a short record you will look at once a week."],reflection:"When is your next suitable moment to start again?",question:"What about after you miss an attempt?",options:["Trying again at the next suitable moment with the small version.","Counting all progress as erased.","Pushing myself twice as hard the next day."],correct:0,feedback:"A plan for coming back is how you test whether a habit can last. A missed attempt does not measure your worth.",takeaway:"Starting again is part of progress too.",sources:["habits","monitoring","motivation-milkman","motivation-bundling-gym","motivation-bundling-teaching"],visual:{kind:"table",title:"Short weekly check-in",columns:["Week","Done / partly / not done","What helped","One change"],rows:[["Week 1","…","…","…"],["Week 2","…","…","…"],["Week 3","…","…","…"]],note:"You do not need to make up missed days by doubling up. You can come back with the small version at your next suitable cue."},technique:{name:"Temptation bundling",origin:"Katy Milkman · How to Change (2021); Milkman, Minson & Volpp (2014)",steps:["Write down one thing you keep avoiding, such as a walk, folding laundry or paperwork.","Write down one small pleasure you look forward to, such as a podcast, a series or a special tea.","Link them: allow yourself the pleasure only while doing the avoided task.","Prepare it in advance so the pleasure is ready at your starting cue.","After a week, check whether it made coming back easier and adjust the pairing."],evidence:"Field experiments with gym members found that bundling audiobooks with exercise raised gym visits: strongly at first in a small study (51%), and by a modest 10–14% in a large one. Evidence outside exercise is limited.",sourceId:"motivation-milkman"},photo:{id:"1577950248429-7530424d9682",alt:"A monthly calendar pinned to a board"}}]},M=Object.freeze(Object.defineProperty({__proto__:null,COURSE:K,SOURCES:E},Symbol.toStringTag,{value:"Module"})),Y=[{id:"hadith-intention",title:"Sahih al-Bukhari 1 · The hadith on intention",url:"https://sunnah.com/bukhari:1",type:"religious",finding:"The hadith of the Prophet Muhammad (peace be upon him), narrated by ʿUmar ibn al-Khattab, that the reward of deeds depends on intentions and each person receives according to what they intended. It is the first hadith in Sahih al-Bukhari.",limitation:"ʿUmar is the narrator here. The lesson’s modern examples are not the words of the hadith; they are ODA’s educational adaptation."},{id:"quran-trust",title:"The Qur’an · Al ʿImran 3:159",url:"https://quran.com/3/159",type:"religious",finding:"Religious reflection on the verse’s emphasis on consultation, making a decision, and then placing one’s trust in Allah, who loves those who trust in Him.",limitation:"The lesson text is ODA’s reflection; it is neither a translation of the whole verse nor scientific evidence."},{id:"quran-ease",title:"The Qur’an · Al-Sharh (Al-Inshirah) 94:5–6",url:"https://quran.com/94/5-6",type:"religious",finding:"Reflection on hope and support drawn from the verses’ emphasis that ease comes with hardship.",limitation:"No personal guarantee is drawn about when a particular difficulty will end."},{id:"gratitude",title:"Kirca, Malouff & Meynadier · 2023 · Meta-analysis of expressed gratitude",url:"https://link.springer.com/article/10.1007/s41042-023-00086-6",type:"research",finding:"25 randomized trials with 6,745 people: expressing gratitude had a small average effect on well-being compared with neutral conditions (g = 0.22); for happiness g = 0.16, life satisfaction g = 0.22 and positive affect g = 0.21. Against bona fide therapeutic comparisons the difference was not significant (g = 0.12).",limitation:"It is not advice to suppress difficult feelings. Results varied between studies, samples were mostly non-clinical US adults, and this psychological research does not test religious claims or the clinical effect of worship."},{id:"faith-hadith-good-intention",title:"Sahih al-Bukhari 6491 · Intending a good deed",url:"https://sunnah.com/bukhari:6491",type:"religious",finding:"Narrated by Ibn ʿAbbas: the Prophet (peace be upon him) said that if someone intends a good deed and does not do it, Allah records it as a full good deed, and if they intend it and do it, it is recorded many times over; a bad deed intended but not done is also recorded as a good deed.",limitation:"Cited for its meaning about intention; the lesson’s application to planning is ODA’s reflection, not a ruling."},{id:"faith-hadith-camel",title:"Jamiʿ at-Tirmidhi 2517 · “Tie it and rely on Allah”",url:"https://sunnah.com/tirmidhi:2517",type:"religious",finding:"Narrated by Anas ibn Malik: a man asked whether he should tie his camel and trust in Allah or leave it untied and trust; the Prophet (peace be upon him) told him to tie it and rely on Allah. Graded hasan (Darussalam).",limitation:"Tirmidhi himself called it a gharib (unusual) narration known to him only through this chain, and noted a similar report from ʿAmr ibn Umayyah. The lesson uses it as a widely cited illustration, not as a ruling."},{id:"faith-quran-sufficient",title:"The Qur’an · Al-Talaq 65:3",url:"https://quran.com/65/3",type:"religious",finding:"The verse says that whoever puts their trust in Allah will find Him sufficient, and that Allah has set a measure for everything.",limitation:"Paraphrased here. The lesson does not promise a particular worldly outcome."},{id:"faith-quran-gratitude",title:"The Qur’an · Ibrahim 14:7",url:"https://quran.com/14/7",type:"religious",finding:"The verse recalls Allah’s declaration that if people are grateful He will give them more, and warns against ingratitude.",limitation:"Paraphrased here. It is religious teaching, not a psychological finding, and the lesson draws no promise of specific material gain from it."},{id:"faith-hadith-thank-people",title:"Sunan Abi Dawud 4811 · Thanking people",url:"https://sunnah.com/abudawud:4811",type:"religious",finding:"Narrated by Abu Hurayrah: the Prophet (peace be upon him) said that whoever does not thank people has not thanked Allah. Graded sahih by al-Albani.",limitation:"Cited for its meaning; the thank-you note exercise is ODA’s adaptation."},{id:"faith-hadith-believer",title:"Sahih Muslim 2999 · The affair of the believer",url:"https://sunnah.com/muslim:2999",type:"religious",finding:"Narrated by Suhayb: the Prophet (peace be upon him) said that the affair of the believer is remarkable, for there is good in all of it: when something pleasing happens they give thanks, and that is good for them; when hardship strikes they are patient, and that is good for them.",limitation:"The lesson’s reading of patience as active endurance is ODA’s reflection, not a ruling. It does not mean hardship should be hidden or endured without help."},{id:"faith-quran-patience",title:"The Qur’an · Al-Baqarah 2:153",url:"https://quran.com/2/153",type:"religious",finding:"The verse calls on believers to seek help through patience and prayer, and says that Allah is with those who are patient.",limitation:"Paraphrased here. It is not a psychological treatment and does not replace medical or mental health care."},{id:"faith-religious-coping",title:"Ano & Vasconcelles · 2005 · Meta-analysis of religious coping and adjustment to stress",url:"https://mhwbf.org/wp-content/uploads/2019/02/Ano-2005-Religious-coping-and-psychological-ad.pdf",type:"research",finding:"49 studies, 13,512 people. Positive religious coping (Pargament’s term for, e.g., seeking spiritual connection, collaborative coping, seeking support from clergy, benevolent reappraisal) was moderately linked with positive outcomes (r = .33) and modestly with fewer negative outcomes. Negative religious coping (e.g., spiritual discontent, seeing hardship as punishment from God) was linked with more distress and other negative outcomes (r = .22).",limitation:"Mostly cross-sectional, self-report studies, so they show associations, not causes. About 85% of participants were Protestant or Catholic; findings may not transfer directly to Muslims. The full text was read."},{id:"faith-hadith-consistent",title:"Sahih al-Bukhari 6464 · Consistent deeds",url:"https://sunnah.com/bukhari:6464",type:"religious",finding:"Narrated by ʿAishah: the Prophet (peace be upon him) advised doing good deeds properly, sincerely and moderately, and said that the deed most beloved to Allah is the most regular and constant, even if it is small.",limitation:"Cited for its meaning; the kindness plan is ODA’s application."},{id:"faith-hadith-smile",title:"Jamiʿ at-Tirmidhi 1956 · Everyday acts of charity",url:"https://sunnah.com/tirmidhi:1956",type:"religious",finding:"Narrated by Abu Dharr: the Prophet (peace be upon him) counted smiling at your brother, guiding someone who is lost, helping someone with poor sight, removing a stone, thorn or bone from the road, and pouring water from your bucket into another’s as acts of charity (sadaqah). Graded hasan (Darussalam).",limitation:"Paraphrased; the modern examples in the lesson are ODA’s adaptation."},{id:"faith-kindness",title:"Curry et al. · 2018 · Meta-analysis of acts of kindness and the well-being of the giver",url:"https://ora.ox.ac.uk/objects/uuid:4701365b-5760-4ece-a390-857a5f7b3c0c",type:"research",finding:"27 studies with 4,045 participants: performing acts of kindness had a small-to-medium effect on the well-being of the person doing them (δ = 0.28). The effect did not depend on sex, age, type of participant or type of intervention, and there was no sign of publication bias.",limitation:"Short-term psychological studies of well-being; they say nothing about religious reward and do not test this course. Only the abstract was read."}],q={id:"faith",title:"Faith",subtitle:"Trust, gratitude and effort.",description:"Listen to your intention, make your gratitude concrete and add to your hope a kindness you can do today.",scope:"Islamic reflection and voluntary daily practices. Religious sources and psychological research are shown separately; anxiety or struggle is not treated as a lack of faith. This is not a religious ruling and not a substitute for mental health care. If you are in crisis or thinking about harming yourself, contact your local emergency number.",outcome:"An intention of your own, a thank-you you can give and a small kindness plan.",photo:{id:"1767396024869-756a346dc39d",alt:"A mosque courtyard with arched doorways and trees"},lessons:[{id:"faith-1",title:"Return to your intention",minutes:6,goal:"Notice the intention behind something you will do today.",reading:["The very first hadith in Sahih al-Bukhari is about intention. It was narrated by ʿUmar ibn al-Khattab, and the words are those of the Prophet Muhammad (peace be upon him): the value of a deed depends on the intention behind it. This lesson is an original practice built on that source. It invites you to look at an ordinary task and ask why you are doing it, and for whom. The answer may be simple, and that is fine.","You might choose to help someone quietly, to learn something, or to keep a promise you made. There is no need to freeze while trying to make your intention perfectly pure; that can become one more reason never to begin. Look at it honestly, as it is today, and then choose your action. Intentions grow clearer through practice, not only through thinking about them, and a small action is often the best way to find out what you really meant."],deeper:[{heading:"What niyyah means",paragraphs:["Niyyah is the Arabic word for intention: the purpose in the heart that gives an act its direction. The same outward action — cooking a meal, going to work, helping a neighbor — can carry very different meanings depending on why it is done.","Another hadith in Bukhari, narrated by Ibn ʿAbbas, adds a hopeful note: when someone intends a good deed and does not manage to do it, it is still recorded for them as a good deed. Sincere intention matters even before action is complete. That is not a reason to stop at intending, but it is a reason not to despair when a plan falls short."],visual:{kind:"table",title:"Two hadiths on intention",columns:["Source","Its meaning (paraphrased)","What this lesson takes from it"],rows:[["Bukhari 1","Deeds are judged by their intentions","Look at the why behind an ordinary task"],["Bukhari 6491","A good deed intended is recorded even if not done","Do not despair when a plan falls short"]],note:"Paraphrased from sunnah.com. The right-hand column is ODA’s reflection, not a religious ruling."}},{heading:"Intention is not perfectionism",paragraphs:["Some people delay good actions because they worry their motives are mixed. Honest reflection is valuable, but waiting for a flawless heart can quietly become avoidance. You can notice a mixed motive, name the better one you want to strengthen, and act on it in a small way.","A simple plan helps here, too. Deciding when and where you will act on your intention is a psychology finding about planning, shown separately in this lesson’s sources. It supports the practice; it does not prove or disprove anything religious."]}],example:{title:"Yusuf, 29, IT support technician",text:"Yusuf had promised to help his elderly neighbor set up a new phone, and he kept putting it off. On Tuesday he stopped to ask himself why he wanted to do it at all. Part of the answer was guilt, and part was wanting to look like a good neighbor. But under that he found something he cared about: he did not want her to feel cut off from her grandchildren. He decided to hold on to that reason. He chose a small preparation — charging the phone and writing down her Wi-Fi password — and knocked on her door on Thursday after work. It took forty minutes. On the walk back he noticed the guilt had gone, and the intention he had chosen was still there."},practice:["Pick an ordinary task you will do today.","Think about who you want this task to benefit, and how.","Make one small preparation that connects your intention to action."],reflection:"How would you describe today’s intention in your own words?",question:"In this lesson, how is the hadith related to the practice?",options:["Every sentence of the modern exercise is a hadith.","The hadith source and ODA’s daily practice interpretation are separate.","Scientific research has proven the hadith true."],correct:1,feedback:"The religious source is named clearly; the modern examples and exercises are ODA’s interpretation.",takeaway:"Make your intention visible with a small effort.",sources:["hadith-intention","mcii","faith-hadith-good-intention"],visual:{kind:"steps",title:"From intention to a small effort",steps:[{label:"Task",text:"Pick an ordinary task you will do today."},{label:"Intention",text:"Who do you want it to benefit, and how?"},{label:"Preparation",text:"Take one small step that links your intention to action."}],note:"Source: Sahih al-Bukhari 1, the hadith on intention. These steps are not the words of the hadith; they are ODA’s adaptation for daily practice."},photo:{id:"1778616364918-34490657598f",alt:"A man holding prayer beads"}},{id:"faith-2",title:"Let preparation go with trust",minutes:7,goal:"Separate the preparation you can do from the outcome you cannot control.",reading:["In Al ʿImran 3:159, consultation, making a decision and trusting in Allah appear together, in that order. Trust, tawakkul, comes after people have talked things through and decided — not instead of it. This lesson’s question for reflection is therefore a practical one: what preparation, within your reach, could you do today? Naming it clearly can turn a vague worry into something you can act on, and leave the rest, with a quieter mind, where it belongs.","You cannot guarantee the result of an exam, a job interview or a medical test. You can study a topic, prepare your questions, or ask about the part you do not understand. Feeling uncertain does not mean you did not make an effort, and it does not mean you lack trust. Many sincere believers feel anxious before important moments; trust and worry can exist in the same heart. The practice here is to let the worry point you toward preparation, and then to let it rest."],deeper:[{heading:"Tawakkul: trust that walks with effort",paragraphs:["A well-known hadith in Tirmidhi’s collection tells of a man who asked whether he should tie his camel and trust in Allah, or leave it loose and trust. The Prophet (peace be upon him) told him to tie it and then rely on Allah. Tirmidhi himself noted that this narration is unusual in its chain, yet it is widely cited because it pictures tawakkul so clearly: effort and trust together.","Al-Talaq 65:3 says that whoever puts their trust in Allah will find Him sufficient. In this lesson, that is read as a source of calm about what is beyond your hands — not as a promise that every outcome will match your wishes."],visual:{kind:"steps",title:"A pattern drawn from Al ʿImran 3:159",steps:[{label:"Consult",text:"Talk it through with someone you trust."},{label:"Decide",text:"Choose a course of action."},{label:"Prepare",text:"Do the part within your reach: “tie the camel.”"},{label:"Trust",text:"Place the outcome with Allah and let go of the rest."}],note:"ODA’s reflection on 3:159 and Tirmidhi 2517; it does not promise any particular result."}},{heading:"When worry is heavy",paragraphs:["Worry about an uncertain outcome is a human experience, not a sign of weak faith. If it becomes constant, disturbs your sleep or keeps you from daily life, it deserves care like any other burden. Talking with someone you trust, a knowledgeable imam or a mental health professional can all be part of “tying the camel.”"]}],example:{title:"Fatima, 22, nursing student",text:"Fatima’s licensing exam was two weeks away, and every night she lay awake running through what would happen if she failed. On Sunday she took a sheet of paper and drew a line down the middle. On the left she wrote what she could do: review cardiac medications, do one practice test a day, ask her instructor about the questions she kept missing. On the right she wrote what she could not control: the exact questions, how nervous she would feel, the result. She sent her instructor an email that evening. Then, after her night prayer, she made a short dua of her own and consciously left the right-hand column with Allah. The worry did not vanish, but it had a smaller place to live."},practice:["Choose something that is weighing on your mind.","Name separately the preparation you can do and the part beyond your control.","Pick one small preparation, or one step toward getting advice from someone you trust."],reflection:"Which part can you take responsibility for today?",question:"Which one is this lesson’s practice of trust?",options:["Accepting the outcome as certain in advance.","Dropping preparation altogether.","Doing what I can and accepting that I cannot fully control the outcome."],correct:2,feedback:"This is ODA’s interpretation of the verse for daily life. It does not promise that the outcome will be what you want.",takeaway:"One step of effort, a little room for uncertainty.",sources:["quran-trust","mcii","faith-hadith-camel","faith-quran-sufficient"],visual:{kind:"compare",title:"Preparation and trust",left:{label:"The preparation within my reach",items:["Studying the topic","Asking about what I do not understand","Getting advice from someone I trust"]},right:{label:"Beyond my control",items:["The exam result","Whether the outcome is what I want"]},note:"ODA’s interpretation, drawing on the emphasis on consultation, decision and trust in Al ʿImran 3:159; it does not promise an outcome."},photo:{id:"1590682680695-43b964a3ae17",alt:"Hands planting a seedling in soil"}},{id:"faith-3",title:"Carry your gratitude to a person",minutes:7,goal:"Prepare a sincere expression of thanks.",reading:["Think of one thing someone did that helped you: a friend who listened, a coworker who made your job easier, a small kindness from a stranger. If you like, write a short thank-you that tells that person exactly what helped and why it mattered. Specific thanks tend to land better than general ones, because they show the person you truly noticed. Choose someone with whom contact feels safe and welcome. Whether you send it is entirely your choice.","Gratitude does not mean denying the difficulties you are going through. You can feel worn out and thankful at the same time. Research on expressing thanks looks at psychological well-being; it is not trying to prove that a belief is true or that a particular act of worship works in a certain way. In this lesson, faith and research each keep their own place, and neither is used to argue for the other."],deeper:[{heading:"Shukr in the Islamic tradition",paragraphs:["Shukr, gratitude, is a central theme in the Qur’an. In Ibrahim 14:7, Allah declares that if people are grateful He will give them more, and the verse warns against ingratitude. Gratitude here is first directed to Allah, the source of every good.","A hadith in Abu Dawud’s collection, graded sahih by al-Albani, links this to everyday life: the Prophet (peace be upon him) said that whoever does not thank people has not thanked Allah. Thanking the person who helped you is itself part of shukr."]},{heading:"What psychology research found — separately",paragraphs:["A 2023 meta-analysis of 25 randomized trials with 6,745 people found that expressing gratitude had a small positive effect on well-being compared with neutral activities. The effect was not clearly different from established therapeutic approaches.","These studies measure mood and life satisfaction in mostly non-clinical groups. They neither confirm nor question religious teaching about gratitude, and they are no reason to hide sadness behind a thankful face."],visual:{kind:"bars",title:"Expressing gratitude: average effects",bars:[{label:"Happiness",value:.16,display:"g = 0.16"},{label:"Life satisfaction",value:.22,display:"g = 0.22"},{label:"Positive affect",value:.21,display:"g = 0.21"}],note:"Kirca, Malouff & Meynadier 2023, compared with neutral activities: small effects that varied between studies. Psychology research, shown separately from scripture.",sourceId:"gratitude"}}],example:{title:"Omar, 58, taxi driver",text:"It had been a hard month for Omar: his knee was bad and the fares were slow. When the lesson asked him to think of one helpful act, he remembered the young mechanic who had stayed late on a Friday to fix his car, so he would not lose a weekend of work. Omar had paid and said a quick thanks, nothing more. That evening he wrote three sentences on a card: “When you stayed late last Friday, you saved my weekend. I could work and pay my rent on time. I have not forgotten it.” He hesitated, then dropped the card at the garage on Monday. The mechanic grinned and pinned it above his bench. Omar’s knee still hurt, but he drove home lighter."},practice:["Recall a safe person you would like to thank, or a small kindness.","Write a concrete sentence: “When you did …, it helped me with ….”","Choose to keep it for yourself, or pass it on if that feels right."],reflection:"What moved you about this kindness?",question:"How can a gratitude practice coexist with difficult feelings?",options:["You have to ignore the hardship.","I can notice what helped while also accepting that things are hard.","If I give thanks, I will have no problems left."],correct:1,feedback:"Both feelings can be present at once. Giving thanks is not an assignment to produce a positive feeling on demand.",takeaway:"Notice what helped; you do not have to silence your pain.",sources:["gratitude","self-compassion","faith-quran-gratitude","faith-hadith-thank-people"],visual:{kind:"table",title:"Thank-you note template",columns:["Part","Your note"],rows:[["To whom?","A safe person or a small kindness: …"],["What did they do?","“When you …”"],["How did it help?","“…it helped me with ….”"],["Your choice","Keep it for yourself, or pass it on if that feels right."]],note:"Gratitude is not denying hardship; you can be tired and thankful at the same time."},photo:{id:"1634906346143-aacbc4c02fec",alt:"A thank-you note on a table next to a pair of glasses"}},{id:"faith-4",title:"Something to hold on to in hard times",minutes:6,goal:"Connect hope with one step of support or care today.",reading:["You can reflect on the emphasis in Al-Sharh 94:5–6 that ease comes with hardship. We do not conclude from these verses that a personal difficulty will end by a certain date, or in a certain way. The focus of this lesson is closer and smaller: finding something to hold on to within this one day, whether that is a person, a practice, a place or a moment of rest. A day is a size of hardship you can usually work with.","Making dua, talking to someone you trust, resting, or asking for professional help can all be meaningful options for you, and they can go together. Needing help does not reduce the worth of your faith. Seeking support is not a failure of patience; often it is exactly how patience is lived. If you are in crisis or thinking about harming yourself, contact your local emergency number right away. You deserve care in hard times, too."],deeper:[{heading:"Sabr: patience that keeps moving",paragraphs:["Sabr is often translated as patience, but it is richer than waiting quietly. In Al-Baqarah 2:153, believers are called to seek help through patience and prayer, and are told that Allah is with those who are patient. Patience here is something you seek help through — an active, steady endurance.","A hadith in Sahih Muslim describes the believer’s affair as remarkable, because there is good in all of it: gratitude when something pleasing happens, patience when hardship comes. Shukr and sabr are presented as two sides of one life, not as opposites."],visual:{kind:"compare",title:"Two sides of one life (Sahih Muslim 2999)",left:{label:"When something pleasing happens",items:["Notice it","Give thanks (shukr)","Share the good"]},right:{label:"When hardship comes",items:["Name it honestly","Endure with patience (sabr)","Seek help through prayer and people"]},note:"The hadith paraphrased from sunnah.com; the items are ODA’s reflection, not a ruling."}},{heading:"What research says about religious coping",paragraphs:["Psychologist Kenneth Pargament distinguishes positive religious coping — such as seeking a spiritual connection, facing problems in partnership with God, or seeking support from clergy — from negative religious coping, such as discontent with God or seeing hardship as punishment. A 2005 meta-analysis of 49 studies found positive religious coping moderately linked with better outcomes, and negative religious coping linked with more distress.","These studies show associations, not causes, and most participants were Christian. If you find yourself feeling punished or far from God, that is not a failure of faith; it is a heavy experience worth sharing with a knowledgeable imam and a mental health professional."],visual:{kind:"bars",title:"Religious coping and adjustment: average correlations",bars:[{label:"Positive coping ↔ positive outcomes",value:.33,display:"r = .33"},{label:"Negative coping ↔ distress",value:.22,display:"r = .22"}],note:"Ano & Vasconcelles 2005, 49 studies, 13,512 people. Mostly cross-sectional and about 85% Christian samples: associations, not proof of cause. Psychology research, shown separately from scripture.",sourceId:"faith-religious-coping"}}],example:{title:"Leila, 39, pharmacy cashier",text:"Since her father’s illness, Leila had been driving to the hospital every evening after work and telling everyone she was fine. One night she caught herself thinking that if her faith were stronger, she would not feel this tired. She stopped at that thought. She asked herself what she needed today, and wrote one sentence: “Today I need someone to sit with Dad so I can sleep.” She texted her cousin, who said yes immediately. That night Leila prayed in her own words, slept seven hours, and made an appointment with the hospital’s counselor for the following week. Nothing about her father’s illness had changed. But she was no longer carrying all of it alone."},practice:["Name one person, practice or safe place that could support you today.","Put your need into one clear sentence: “Today I need support with ….”","If you can, take one small step toward that support; if you want to make dua, use your own words."],reflection:"What could you hold on to today?",question:"Which is more helpful when it comes to asking for help?",options:["Admitting that I am struggling and looking for trustworthy support.","Telling myself a believer should never struggle.","Telling myself I must solve everything alone."],correct:0,feedback:"Needing support is human. This lesson does not treat hardship as a moral or religious flaw.",takeaway:"While you make room for hope, you can also reach for support.",sources:["quran-ease","self-compassion","faith-quran-patience","faith-hadith-believer","faith-religious-coping"],visual:{kind:"steps",title:"Something to hold on to today",steps:[{label:"Acknowledge",text:"Notice that you are struggling; this is not a flaw."},{label:"Name it",text:"“Today I need support with ….”"},{label:"Choose",text:"Dua, someone you trust, rest or professional support."},{label:"Reach out",text:"Take one small step toward that support."}],note:"An ODA practice inspired by reflection on Al-Sharh 94:5–6; it makes no promise about when a difficulty will end."},photo:{id:"1570739260082-39a84dae80c8",alt:"A lit lantern on a wooden table"}},{id:"faith-5",title:"Keep up a small kindness",minutes:8,goal:"Bring intention, thanks and effort together in one daily action that suits you.",reading:["A plan for kindness does not have to be big, visible or expensive. Listening to someone with full attention, tidying a shared space, or following through on a promise are all actions you can choose. The tradition you have met in this course places real value on such everyday acts, and on doing them steadily. Small is not a lesser version of kindness; very often it is the version that actually happens.","Mind your own limits. You do not have to carry everyone’s burdens, and a kindness that leaves you exhausted or resentful will not last. Today, choose one small action, decide when you will do it, and afterward notice what it left in you. Let it be voluntary: you do not need thanks or anything in return for it to count. If it suits you, repeat it next week; if not, choose another kindness that fits better."],deeper:[{heading:"Small, steady deeds",paragraphs:["A hadith in Sahih al-Bukhari, narrated by ʿAishah, says that the deed most beloved to Allah is the one done most regularly, even if it is small, and advises doing good sincerely and in moderation. Another, in Tirmidhi’s collection, counts a smile for your brother, guiding someone who is lost, or removing a thorn or stone from the road as acts of charity (sadaqah).","Together they paint a picture of kindness that fits into ordinary days: modest in size, repeated, and done with a good intention — which brings you back to the first lesson."],visual:{kind:"table",title:"Everyday charity, then and now",columns:["From the hadith (paraphrased)","A modern version"],rows:[["Smiling at your brother","Greeting a coworker warmly"],["Guiding someone who is lost","Helping someone find the right form or bus"],["Removing harm from the road","Picking up a hazard from a shared stairway"],["Pouring from your bucket into another’s","Sharing what you have extra of"]],note:"Tirmidhi 1956 and Bukhari 6464, paraphrased from sunnah.com. The modern versions are ODA’s examples."}},{heading:"What research says about kindness — separately",paragraphs:["Psychologists have also studied what kindness does for the person who gives it. A 2018 meta-analysis of 27 studies with 4,045 participants found that performing acts of kindness had a small-to-medium positive effect on the giver’s well-being.","This is a finding about mood and well-being, measured over short periods. It says nothing about reward in the religious sense, and it is not a reason to be kind only when it makes you feel good."]}],example:{title:"Nadia, 44, office manager",text:"Nadia’s first idea was ambitious: volunteer every weekend at the food bank. Looking at her real week — two kids, a long commute, an aging mother — she knew it would not last a month. She chose something smaller: every Wednesday, she would call her mother’s elderly neighbor, who lived alone, just to ask how she was. She put it in her calendar for 6:30 p.m., after dinner. The first call lasted eight minutes and was mostly about the weather. The third call lasted twenty, and the neighbor mentioned she had not spoken to anyone else all week. Nadia did not expect thanks, but she noticed she had started looking forward to Wednesdays. The call stayed on her calendar."},practice:["Choose a small, free kindness that fits your limits.","Decide when, where and how you will do it; do not make getting something in return a condition.","Afterward, briefly reflect on how your intention and action fit together, and decide whether repeating it suits you."],reflection:"What small kindness would you like to bring into your daily life?",question:"Which is a sustainable kindness plan?",options:["Taking on everyone’s problems.","Making sure I get something in return.","Choosing a concrete, voluntary action that respects my limits."],correct:2,feedback:"A small, voluntary action with clear limits gives you a plan you can actually carry out.",takeaway:"Add to your intention a kindness you can do today.",sources:["hadith-intention","mcii","monitoring","faith-hadith-consistent","faith-hadith-smile","faith-kindness"],visual:{kind:"table",title:"A small kindness plan",columns:["Small kindness","When / where?","What did you notice afterward?"],rows:[["Listening to someone with full attention","…","…"],["Tidying a shared space","…","…"],["Following through on a promise","…","…"]],note:"Choose something free, voluntary and within your limits; do not make getting something in return a condition."},photo:{id:"1710092784814-4a6f158913b8",alt:"A woman handing a plate of food to another woman"}}]},R=Object.freeze(Object.defineProperty({__proto__:null,COURSE:q,SOURCES:Y},Symbol.toStringTag,{value:"Module"})),N=[{id:"manifest-positive-fantasies",title:"Kappes & Oettingen · 2011 · Positive fantasies about idealized futures sap energy",url:"https://www.sciencedirect.com/science/article/abs/pii/S002210311100031X",type:"research",finding:"Four experiments. Experimentally induced positive fantasies about an idealized future led to less energy, measured with physiological and behavioral indicators, than fantasies that questioned the desired future, negative fantasies or neutral fantasies. The drop in energy was larger when the fantasy concerned a more pressing need. The authors conclude that low energy is one reason spontaneous positive fantasies predict poorer achievement.",limitation:"Laboratory experiments with small samples. They do not show that dreaming is always harmful, only that an idealized fantasy with no obstacle and no plan can reduce the energy to act. Only the abstract was read."},{id:"manifest-belief-study",title:"Dixon, Hornsey & Hartley · Personality and Social Psychology Bulletin · The psychology of belief in manifestation (University of Queensland summary, 2023)",url:"https://news.uq.edu.au/2023-09-20-manifesting-your-way-bankruptcy",type:"research",finding:"Three studies with 1,023 participants. About one-third endorsed manifestation beliefs. Believers reported stronger perceptions of their own success and higher aspirations, but they were also more drawn to risky investments, more likely to have experienced bankruptcy and more likely to hold unrealistic expectations of getting rich quickly. The researchers found no objective evidence that manifesting works.",limitation:"Survey research that shows associations, not causes. The university’s news summary was read, not the full article, so details of the measures were not checked."},{id:"manifest-murphy",title:"Joseph Murphy · The Power of Your Subconscious Mind (1963; Tarcher edition 2008)",url:"https://www.penguinrandomhouse.com/books/296695/the-power-of-your-subconscious-mind-by-joseph-murphy-phd-dd/",type:"technique",finding:"Murphy teaches that the drowsy state just before sleep is the moment most open to suggestion. He suggests shortening a wish into a brief phrase, repeating it calmly like a lullaby, picturing a short scene as if the result were happening now (for example a friend congratulating you) and ending the scene with a feeling of thanks. The publisher describes the book’s core idea as believing without reservation and picturing the result so that inner obstacles fall away.",limitation:"The publisher page was read. Rehearsal and a clear intention before sleep may help you prepare. The book’s claims that the subconscious mind brings wealth, success or physical healing are not supported by research, and no one should change medical treatment because of it."}],j={id:"manifest",title:"Manifest",subtitle:"From intention to action.",description:"Get clear on what you want, rehearse the path in your mind, face the real obstacle and plan your first step.",scope:"Here, manifesting means the practice of intention, preparation and action. The course does not claim that thoughts steer events through quantum effects, that the universe delivers what you focus on, or that any wish is sure to come true. It is not financial, medical or psychological advice.",outcome:"One goal, a short mental rehearsal, a response to your main obstacle and a date to review how it went.",photo:{id:"1676782778930-11b311ec5134",alt:"Dirt road climbing a grassy hill toward distant mountains"},lessons:[{id:"manifest-1",title:"Turn your wish into a behavior",minutes:6,goal:"Separate the result you want from the work you can do today.",reading:["“I want a better job” is a wish about an outcome. “This week I will rework the first section of my résumé” is a goal about your own behavior. You cannot control other people’s decisions: whether an employer calls back, whether a client says yes. You can choose the part you prepare. This is the working core of what people call manifesting. A clear intention points your attention and your effort at something specific, and the clearer the behavior, the easier it becomes to notice chances and to start.","There is room for dreaming in this course. Next to the dream we will place your conditions, your resources and your effort. What we will not do is explain a missed opportunity by saying you did not think positively enough. Popular manifesting often promises that the universe delivers whatever you focus on, but no research shows thoughts acting like a physical force on events. That is good news, in a way: the outcome was never a test of your inner purity, and the next step is still yours to choose."],practice:["Write or think of one wish that matters to you, in a single sentence.","Choose one behavior within your control that moves you toward that wish.","Describe the behavior with a small finish line, for example “three lines of a draft”."],reflection:"What is today’s behavior version of your wish?",question:"Which of these is a behavior you can choose directly?",options:["The employer definitely choosing me.","Editing three lines of my résumé tomorrow.","Nothing going wrong at all."],correct:1,feedback:"You cannot guarantee other people’s decisions. You can make your own preparation concrete.",takeaway:"Give your intention a task you can actually touch.",sources:["mcii","manifest-belief-study"],visual:{kind:"compare",title:"From wish to behavior",left:{label:"Wish about an outcome",items:["I want a better job.","The employer definitely choosing me","Nothing going wrong at all"]},right:{label:"Goal about a behavior",items:["Rework the first section of my résumé this week","Write a three-line draft tomorrow"]},note:"You cannot guarantee other people’s decisions; you can make your own preparation concrete."},deeper:[{heading:"What holds up, and what does not",paragraphs:["Manifesting books and videos usually mix two very different things. One is a set of ordinary, useful habits: deciding clearly what you want, picturing it, keeping it in view and acting on it. The other is a story about how the world works, often called the law of attraction: that like attracts like, that your thoughts send out a signal, that the universe arranges events to match it, and sometimes that quantum physics proves all this.","You can keep the first part and set the second aside without losing anything that works. Physicists do not describe the world that way, and no study has shown that thinking about money, a partner or a job makes it arrive on its own. The habits, on the other hand, overlap with methods that have been tested: clear goals, mental rehearsal, planning for obstacles and tracking progress. That is what this course builds on."],visual:{kind:"compare",title:"The working core and the claims to leave aside",left:{label:"Keep: the working core",items:["A clear, specific intention","Rehearsing the steps in your mind","Seeing the obstacle and planning for it","Acting, then reviewing honestly"]},right:{label:"Leave aside: no evidence",items:["Thoughts as a magnet that pulls in events","“The universe delivers” what you focus on","Quantum physics reshaping your reality","A setback as proof of negative thinking"]},note:"Setting aside the right-hand column does not mean giving up hope. It means your hope gets a plan."}},{heading:"What research on manifesting beliefs found",paragraphs:["Researchers at the University of Queensland studied people who believe in manifesting. Across three studies with 1,023 participants, about a third endorsed manifestation beliefs. Those believers felt more successful and aimed higher, which sounds encouraging. But they were also more drawn to risky investments, more likely to have been through bankruptcy and more likely to expect quick wealth. The researchers found no objective evidence that manifesting works.","These were surveys, so they show a link, not a cause. Still, the pattern fits the rest of this course. The wish is not the problem. The risk comes when a strong feeling of certainty replaces checking the facts, asking for advice and taking small, testable steps. A behavior goal keeps you in contact with reality."]}],example:{title:"Daniel, 31, warehouse shift supervisor",text:"Daniel wanted to move into a logistics planning role. For months he had a picture of an office desk as his phone wallpaper and told himself the right job would find him. On Sunday he tried the exercise. Wish: “a planning job.” Behavior: “By Thursday, rewrite the top three lines of my résumé so they mention the shift schedules I already build.” He did it on Wednesday after dinner in about twenty minutes. One line still sounded awkward, and no one called that week. But he now had a page he could send, and the next step, finding two job postings to compare, was obvious. The wallpaper stayed. It just had a task attached to it now."},photo:{id:"1768055104910-8c8d213835fb",alt:"Hand writing a to-do list in a notebook"}},{id:"manifest-2",title:"See the path, not only the result",minutes:7,goal:"Do a short mental rehearsal of your first move.",reading:["Take a moment to think about what reaching the result you want would mean to you. Then bring the scene back to today: where are you sitting, which file are you opening, what do you type in the first line? Picturing the finish line gives the wish some warmth. Picturing the first move gives it a place to begin. Both have value, but the second is the one that tells you what to do next. This is a preparation exercise, a kind of dress rehearsal before the real thing.","You do not have to close your eyes. If no vivid images come, simply describing the steps to yourself in words is enough; many people think more in sentences than in pictures. The rehearsal does not replace the real attempt. It exists to help you pick the detail that will get the attempt started: the pen that needs to be on the desk, the email you will open, the first sentence you will say. When the rehearsal is over, do one real thing it showed you."],practice:["Name one difference you want your goal to make in your life.","Put your first two moves in order, as images or as words.","After the rehearsal, actually do one preparation step."],reflection:"Which missing preparation did you notice during the rehearsal?",question:"What does mental rehearsal mean in this course?",options:["An exercise that prepares you for real action.","Controlling outside events for certain with your thoughts.","No longer needing to try at all."],correct:0,feedback:"Rehearsal is preparation. It does not replace action or outside conditions, and the independent effect of this single exercise has not been proven.",takeaway:"After the dream, see the first move.",sources:["mcii","manifest-murphy","identity-cole","identity-toth","identity-dispenza-habit"],visual:{kind:"steps",title:"Rehearsing from the result to the first move",steps:[{label:"Meaning",text:"What would reaching the result mean to you?"},{label:"Place",text:"Where are you sitting today?"},{label:"Tool",text:"Which file are you opening?"},{label:"First line",text:"What do you write in the first line?"},{label:"Real step",text:"After the rehearsal, actually do one preparation."}],note:"If no images come, describing the steps in words is enough. Rehearsal does not replace the real attempt."},deeper:[{heading:"What the research on mental rehearsal says",paragraphs:["A 2021 meta-analysis pooled 94 randomized studies of mental simulation, meaning deliberately imagining a future action or event. Overall, it changed later behavior by a medium amount. The type of imagery mattered. Picturing yourself carrying out the action, especially doing it well, worked best. Picturing only the desired outcome had a small effect. Picturing only the process steps was not reliable, though that estimate rests on just five effects, and the eight studies that combined an outcome with the process showed a larger effect.","A separate review of mental practice in skills and sport found a small but real benefit, and found that physical practice beat mental practice alone. So the honest summary is: seeing yourself do the thing helps a little to a moderate amount; doing the thing helps more."],visual:{kind:"bars",title:"Mental simulation and later behavior (average effect, Hedges’ g)",bars:[{label:"Rehearsing yourself performing well",value:.67,display:"g = 0.67"},{label:"Standard performance rehearsal",value:.48,display:"g = 0.48"},{label:"Imagining the desired outcome",value:.23,display:"g = 0.23"},{label:"Imagining process steps only (5 effects)",value:.17,display:"g = 0.17"}],note:"From Cole et al. (2021), 94 randomized studies. About 0.2 is small and 0.5 medium. Most participants were students, some types rest on few studies, and the process-only estimate was not statistically reliable.",sourceId:"identity-cole"}},{heading:"How Joseph Murphy and Dr. Joe Dispenza do it",paragraphs:["Two well-known teachers build their methods around rehearsal. Joseph Murphy, in The Power of Your Subconscious Mind, recommends the drowsy minutes before sleep: shorten your wish to a brief phrase, repeat it calmly, picture a short scene as if the result were already happening, and end with a feeling of thanks. Dr. Joe Dispenza, in Breaking the Habit of Being Yourself, uses a morning meditation in which you rehearse in detail how your new self thinks, acts and feels.","Both contain a useful core, and both go well beyond the evidence. Murphy writes that the subconscious can bring wealth and healing; Dispenza links his practice to a quantum field and to changing your genes. You can keep the rehearsal and gently leave the rest."],visual:{kind:"table",title:"Two rehearsal methods, sorted honestly",columns:["Teacher","What you do","Keep","Leave aside"],rows:[["Joseph Murphy","Short phrase and a finished scene before sleep","A calm, clear intention; rehearsing a scene","The subconscious attracting money or healing"],["Dr. Joe Dispenza","Morning meditation rehearsing the new self","Rehearsing how you will act and respond","Quantum-field and gene-changing claims"],["This course","Outcome first, then the first concrete move","Seeing yourself do the step","Treating the picture as a replacement for action"]],note:"A paraphrase of each method, not a full account. Neither method has been tested as a whole in controlled trials."}}],example:{title:"Priya, 27, pediatric nurse",text:"Priya wanted to apply for a specialist training program, and she often pictured the day she would wear the new badge. That felt good but changed nothing. One night, lying in bed, she tried a different scene. After the badge, she pictured tomorrow morning: her kitchen table after breakfast, the laptop open, the application portal on the screen, the box that says “personal statement.” She noticed she did not know her login and that the statement needed a first sentence. In the morning she reset the password, wrote one rough sentence about why she chose children’s nursing, and closed the laptop after ten minutes. The badge was still months away. The application, though, had finally started."},technique:{name:"The pre-sleep scene, with a first step",origin:"Joseph Murphy · The Power of Your Subconscious Mind (1963)",steps:["In bed, as you begin to feel drowsy, shorten your wish to a brief sentence you can believe.","Repeat the sentence slowly a few times, calmly, without forcing it.","Picture a short scene as if the result had happened, for example someone you like congratulating you.","ODA addition: replay the first concrete step for tomorrow, where you will be and what you will open or say.","End with a moment of thanks for what is already going right, and let sleep come."],evidence:"Rehearsing yourself doing a task has small-to-moderate support in research; picturing only the finished outcome has a small effect, which is why this version adds the first step. There is no evidence that the subconscious mind draws in money, success or healing. This is not a substitute for medical or psychological treatment.",sourceId:"manifest-murphy"},photo:{id:"1517363898874-737b62a7db91",alt:"Person sitting quietly by a window in warm light"}},{id:"manifest-3",title:"Meet the real obstacle",minutes:8,goal:"Clearly name one obstacle between what you want and where you are now.",reading:["After thinking about the future you want, look at where you are now: maybe you hesitate to begin, maybe the plan is too big, maybe you cannot get the information you need. Psychologist Gabriele Oettingen calls this step mental contrasting: holding the wished-for future and the present reality side by side. It can feel less pleasant than dreaming alone, and that is part of why it works. The more concrete the obstacle, the clearer your response to it can be.","Not every obstacle is inside you. Time, money, caring for others and access to resources are real conditions. Do not treat an obstacle outside your control as a flaw in your character, and do not treat it as a sign that you did not believe hard enough. You may need to change the size of the goal, its timing or the support around it. Seeing the obstacle honestly is not pessimism; it is what turns a wish into something you can work on."],practice:["Name the nearest obstacle standing in front of your goal.","Separate the part of the obstacle you can influence from the part that needs support or time.","If it cannot be done right now, make the goal smaller or move it to a suitable time."],reflection:"Looking at your obstacle more realistically, what changed in your plan?",question:"When outside conditions get in the way…",options:["I should assume it is because I did not believe enough.","I should ignore the conditions.","I can reconsider support, timing or the size of the goal."],correct:2,feedback:"A realistic plan takes outside conditions into account. Outcomes are not decided by your thoughts alone.",takeaway:"Seeing the obstacle honestly gives your plan a direction.",sources:["mcii","oettingen-woop-method","manifest-positive-fantasies"],visual:{kind:"table",title:"Sorting the obstacle honestly",columns:["Obstacle","Type","Possible response"],rows:[["Hesitating to begin","Inner","Make the step smaller"],["The plan is too big","Plan","Reduce the size of the goal"],["Cannot reach the information you need","Access","Ask for support"],["Time, money, caring for others","Outside condition","Change the timing or the size"]],note:"Outside conditions are real, not flaws in your character. Outcomes are not decided by your thoughts alone."},deeper:[{heading:"Why a pleasant daydream can drain you",paragraphs:["Earlier research by Oettingen’s group had found that people who spontaneously indulged in rosy fantasies about the future tended to achieve less. To test why, Heather Barry Kappes and Gabriele Oettingen ran four experiments in which they asked people to imagine an idealized future. Compared with fantasies that questioned that future, negative fantasies or neutral ones, the positive fantasies left people with less energy, measured both in the body and in behavior. The drop was larger when the need felt more pressing.","One way to understand it: an idealized picture lets you taste the arrival without the journey, so the body relaxes as if the work were done. This does not mean dreaming is bad. It means a dream works better as a starting point than as a destination."],visual:{kind:"cycle",title:"The fantasy loop",center:"Dream only",nodes:[{label:"Idealized picture",text:"You imagine the finished result, with no obstacles."},{label:"Feels like arriving",text:"The mind enjoys it as if it were already real."},{label:"Energy drops",text:"Less urgency to act; the body relaxes."},{label:"Little action",text:"The day passes without a concrete step."},{label:"Wish still far",text:"The gap feels painful, so you return to the dream."}],note:"A simplified picture based on Kappes & Oettingen (2011). The way out of the loop is not to stop dreaming but to add the obstacle and a plan."}},{heading:"Dream first, then look: how WOOP works",paragraphs:["Oettingen turned mental contrasting into a four-step method called WOOP: Wish, Outcome, Obstacle, Plan. You start with the pleasant part, naming the wish and imagining the best outcome, and only then turn to the main obstacle inside you, such as a habit, a feeling or a belief. The last step, the plan, comes in the next lesson.","A 2021 meta-analysis of 21 studies with 15,907 participants found that mental contrasting combined with if-then plans had a small-to-medium average effect on reaching goals. That is a real effect, not a guarantee. WOOP also gives you useful information when it does not fit: if you look honestly at the obstacle and the wish no longer feels feasible, that is a signal to reshape it, not a failure."]}],example:{title:"Lena, 38, secondary-school teacher",text:"Lena wanted to finish an online course in data skills. Her usual daydream was the certificate and a new role at the district office. This time she used WOOP. Wish: finish module three this month. Outcome: feeling capable with spreadsheets at work. Then the obstacle. The honest one was not laziness: after grading and putting her two children to bed, it was 9:30 p.m. and she was worn out, so she reached for her phone. Part of that was an outside condition she could not change. So she changed the plan instead: forty-five minutes on Saturday mornings while her partner took the kids to the park. She finished one lesson that first Saturday, less than she had hoped, but more than in the previous three weeks."},technique:{name:"WOOP",origin:"Gabriele Oettingen · Rethinking Positive Thinking (2014)",steps:["Wish: name a wish that matters to you and is challenging but feasible, in a few words.","Outcome: imagine the best outcome of fulfilling it and let yourself feel it for a moment.","Obstacle: ask what inside you, a habit, feeling or thought, most gets in the way, and picture it clearly.","Plan: write one sentence in the form “If [obstacle], then I will [action].”"],evidence:"Research on mental contrasting with if-then plans shows small-to-medium average effects on reaching goals. Results vary by person and situation, and the official WOOP site belongs to the method’s developers rather than being an independent evaluation.",sourceId:"oettingen-woop-method"},photo:{id:"1767134063671-322e6faf9206",alt:"Fallen tree lying across a leafy forest path"}},{id:"manifest-4",title:"If this happens, then I will…",minutes:7,goal:"Link one small response to an obstacle signal.",reading:["Now turn the obstacle you chose in the last lesson into a plan. For example: “If I open the file and don’t know where to start, then I will only write the title.” Choose a response that has a clear trigger and is small and doable. The “if” part names the moment, a time, a place or a feeling you can recognize. The “then” part names what you will do in that moment. Deciding in advance means you do not have to rely on willpower or memory when the moment arrives.","If you want to use affirmations, keep them realistic: rather than “I will achieve everything,” try “I can try the first draft.” A sentence like that is useful not because it steers the universe but because it reminds you of the behavior you chose. Grand statements can feel good for a moment and then collide with a hard day. A believable sentence tied to one small action is more likely to still be standing when the obstacle actually shows up."],practice:["Describe one obstacle signal in the form “If …”.","In the “then …” part, write a single small behavior.","Check that the plan fits the time and tools you have, then rehearse it once."],reflection:"What is your if-then sentence?",question:"Which plan can actually be tried?",options:["Everything will sort itself out.","If I get stuck when I open the file, I will write the title first.","If I send good energy, all the obstacles will disappear."],correct:1,feedback:"The second option links a specific situation to an observable behavior. The approach studied in research looks like this kind of action planning.",takeaway:"Tie your wish to a way of starting.",sources:["mcii","if-then-plans"],visual:{kind:"steps",title:"Wish → outcome → obstacle → plan",steps:[{label:"Wish",text:"What do you want? For example, the first draft of my résumé."},{label:"Outcome",text:"What would change for you once it is done?"},{label:"Obstacle",text:"“When I open the file, I won’t know where to start.”"},{label:"Plan",text:"“If I get stuck, then I will only write the title.”"}],note:"If you use an affirmation, keep it realistic: “I can try the first draft.” Its value is in reminding you of the behavior you chose."},deeper:[{heading:"Why if-then plans work",paragraphs:["Psychologists call these plans implementation intentions. Peter Gollwitzer and Paschal Sheeran pooled 94 independent tests and found that plans saying in advance when, where and how you will act had a medium-to-large average effect on reaching goals. Newer analyses that correct for publication bias may put the true effect lower, but the direction is consistent.","The likely reason is simple. When you link a situation to a response ahead of time, the situation itself becomes the reminder. You no longer need to decide in the moment, when you are tired or uneasy and the easiest option is to scroll. The plan has already done the deciding for you."],visual:{kind:"compare",title:"Vague intentions and usable plans",left:{label:"Vague",items:["I’ll work on it this week.","I’ll try to be more disciplined.","I’ll stay positive no matter what."]},right:{label:"If-then",items:["If it is 8 p.m. on Tuesday, then I open the file at the kitchen table.","If I reach for my phone, then I put it in the other room for 15 minutes.","If I feel discouraged, then I write down one thing that did work."]},note:"A good “if” is something you will notice; a good “then” is small enough to do even on a bad day."}},{heading:"Common mistakes",paragraphs:["The most common one is a vague cue: “if I have time” rarely arrives. Tie the plan to a clock time, a place or a moment you already know, such as finishing lunch. The second is a response that is too big: “then I will write the whole chapter” invites the same avoidance as before. The third is making too many plans at once. One or two plans you actually use beat a page of rules.","If a plan does not fire, treat it as information, not a verdict on you. Maybe the cue was hidden, or the action was still too large. Adjust one part and try again."]}],example:{title:"Tomás, 35, freelance graphic designer",text:"Tomás had been “manifesting” a portfolio website for a year. He could picture it clearly, but every time he opened the site builder, the blank page made him switch to email. So he wrote two plans on a sticky note by his screen. “If I open the builder and feel stuck, then I will only type the page title and the names of two projects.” And: “If it is 9 a.m. on Tuesday and I haven’t started, then I will set a ten-minute timer.” On Tuesday the second plan kicked in at 9:05. He typed the title and three project names, then stopped after twelve minutes. It was not a website yet, but for the first time it was more than a picture in his head."},photo:{id:"1591462391971-9ffc57b382b9",alt:"Colorful sticky notes and pens"}},{id:"manifest-5",title:"Try, look, choose again",minutes:8,goal:"Review your plan in real life and choose your next step.",reading:["As you move toward a goal, looking back at what you did can help you see which part of the plan is working. Record not only the result but also the behavior you tried, the conditions you met and what you learned. A short note is enough: “Wrote for ten minutes on Tuesday; the kids were home; starting with the title helped.” Over a few weeks, notes like these show patterns that memory alone tends to blur, and they give you something concrete to adjust.","If the result you wanted does not come, you do not have to explain it with bad thoughts, low energy or a lack of faith. Sometimes a different route, more support or a different goal is needed. Changing course is not giving up on yourself; it is using what reality has taught you. No course can guarantee an outcome. What you can do is weigh your own part and the outside conditions together, and then choose the next step with clearer eyes."],practice:["Do your first small attempt, or fix exactly when you will do it.","Set a reasonable date to check the result, and use the questions “What did I try, and what did I learn?”","Choose what fits best: continue, make it smaller, get support, or change the goal."],reflection:"On which day, and looking at which information, will you review your plan?",question:"When the result you wanted does not come, what is the most useful review?",options:["My thoughts were not strong enough.","Looking at the behaviors I tried and the conditions, then making the next choice.","Keeping the same expectation without looking at reality."],correct:1,feedback:"Comparing the plan with reality gives you new information. No course guarantees a result; you can weigh your own part and the outside conditions together.",takeaway:"Put effort into your dream, and make room for what reality teaches you.",sources:["monitoring","mcii","manifest-belief-study"],visual:{kind:"bars",title:"Tracking progress: average effect",bars:[{label:"Harkin et al. 2016 · 138 studies",value:.4,display:"d = 0.40"}],note:"The average effect on reaching goals of interventions that increased progress monitoring; different goals and methods were pooled. It does not promise an effect or a result for this single exercise.",sourceId:"monitoring"},deeper:[{heading:"What to track, and why writing it down helps",paragraphs:["A meta-analysis of 138 experiments with nearly 20,000 people found that interventions which got people to monitor their progress helped them reach their goals, with a small-to-moderate average effect. The benefit was larger when progress was physically recorded, on paper or in an app, and when it was reported to someone else. You do not have to share your notes, but a quick line in writing seems to work better than a vague sense of how things are going.","Track mostly what you control: did you do the step, when, and under what conditions? The outcome matters too, but outcomes often lag behind effort and depend on other people. If you only track the outcome, a slow month can look like failure even when your behavior was steady."],visual:{kind:"cycle",title:"The review loop",center:"Review day",nodes:[{label:"Try",text:"Do the small step you planned."},{label:"Record",text:"Write one line: what you did, when, under what conditions."},{label:"Look",text:"On your review day, read the notes together."},{label:"Learn",text:"What helped? What got in the way?"},{label:"Choose again",text:"Keep, shrink, get support or change the goal."}],note:"The loop turns every attempt, including the ones that did not work, into information for the next one."}},{heading:"When the result does not come",paragraphs:["Popular manifesting has a hidden cost here. If thoughts create reality, then an outcome that does not arrive must mean your thoughts were wrong, so the only answer is to believe harder. That can keep people stuck, and sometimes it pushes them toward risky bets. Survey research on people who strongly believe in manifesting found exactly this link with risky investments and bankruptcy, though it cannot show cause.","A kinder and more useful question is: what does the evidence from my own attempts say? Sometimes the answer is to keep going, because effort and results are simply out of sync for now. Sometimes it is to change the plan, ask for help or let a goal go. Each is a legitimate choice."],visual:{kind:"table",title:"Reading your review",columns:["What you see","A reasonable next choice"],rows:[["You did the steps; the result is slow","Continue, and set the next review date"],["You rarely did the step","Make it smaller or change the “if” cue"],["An outside condition kept blocking you","Change the timing, or ask for support"],["The goal no longer matters to you","Let it go, or choose a new wish"]],note:"None of these choices is a failure; each one is a decision based on what actually happened."}}],example:{title:"Aisha, 45, runs a small home bakery",text:"Aisha wanted ten regular weekly orders by the end of the quarter. For six weeks she posted photos every Monday and handed out samples at two local cafés, writing one line in a notebook each time. On her review day she read the notes. She had nine posts and six sample days, and four regular orders, not ten. Instead of deciding she had not believed enough, she looked closer. Three of the four regulars came from the same café, where she had talked with customers in person. So she chose to drop two of the posts each month and spend that time at a second café. The goal date moved back a month, and that felt like a decision rather than a defeat."},photo:{id:"1762920738995-f393efe82205",alt:"Wooden signpost pointing in several directions in a forest"}}]},G=Object.freeze(Object.defineProperty({__proto__:null,COURSE:j,SOURCES:N},Symbol.toStringTag,{value:"Module"})),F=[{id:"task-switching",title:"Monsell · 2003 · The cost of switching tasks",url:"https://pubmed.ncbi.nlm.nih.gov/12639695/",type:"research",finding:"According to this review, people slow down right after switching from one task to another and usually make more errors; this switch cost shrinks with preparation but does not disappear completely.",limitation:"Only the published abstract was read, and it contains no numbers; the short delays seen in simple laboratory tasks cannot be translated directly into losses in real work."},{id:"interruptions",title:"Mark, Gudith & Klocke · 2008 · The cost of interrupted work: speed and stress",url:"https://ics.uci.edu/~gmark/chi08-mark.pdf",type:"research",finding:"In a laboratory experiment with 48 people, participants whose work was interrupted finished the task in slightly less time without losing quality, but reported higher stress, frustration, time pressure and effort.",limitation:"A small sample, mostly university students, working on an artificial email-answering task; the results cannot be transferred directly to real working life."},{id:"notifications",title:"Kushlev, Proulx & Dunn · 2016 · An experiment on notifications and inattention",url:"https://interruptions.net/literature/Kushlev-CHI16.pdf",type:"research",finding:"221 university students spent one week with notifications on and the phone within sight, and one week with notifications off and the phone out of reach; in the week with notifications they reported more inattention (d = 0.44) and hyperactivity (d = 0.45).",limitation:"The measures rely on self-report, participants knew which condition they were in, and the raw differences were small, around 0.1 points; the authors stress that this does not mean notifications cause clinical ADHD."},{id:"phone-presence",title:"Hartanto et al. · 2024 · Meta-analysis on the mere presence of a phone",url:"https://assets.pubpub.org/mgkf17za/tmb_tmb0000123-41706626995650.pdf",type:"research",finding:"A meta-analysis pooling 33 studies and 4,368 participants found no overall effect of a phone merely being nearby on cognitive performance (d = −0.02), and the small effect seen on working memory disappeared after correcting for publication bias.",limitation:"Based on laboratory tasks, and it examines only the phone being nearby, not using it or receiving notifications; the authors found signs of publication bias in the published studies."},{id:"brain-drain",title:"Ward, Duke, Gneezy & Bos · 2017 · The “brain drain” experiment (not replicated)",url:"https://www.journals.uchicago.edu/doi/full/10.1086/691462",type:"research",finding:"In two experiments (N = 520 and N = 275), people whose phone was on the desk scored slightly lower on a working memory task than people whose phone was in another room; the effects were small (partial η² = 0.014–0.026).",limitation:"A preregistered direct replication found no effect, and a meta-analysis of 33 studies showed no overall effect; this finding should not be used as evidence on its own."},{id:"brain-drain-replication",title:"Ruiz Pardo & Minda · 2022 · Replicating the “brain drain” study",url:"https://www.sciencedirect.com/science/article/pii/S0001691822002323",type:"research",finding:"In a preregistered direct replication (N = 383) of the second experiment by Ward and colleagues, the phone’s location did not affect working memory performance (p = 0.91).",limitation:"The sample consisted of young university students, and the study was run in a single laboratory."},{id:"microbreaks",title:"Albulescu et al. · 2022 · Meta-analysis of micro-breaks",url:"https://journals.plos.org/plosone/article?id=10.1371/journal.pone.0272460",type:"research",finding:"In a meta-analysis pooling 22 samples (N = 2,335), micro-breaks of up to 10 minutes increased vigor (d = 0.36) and reduced fatigue (d = 0.35), while the effect on overall performance was not significant (d = 0.16).",limitation:"The number of studies is small, the well-being measures rely on self-report, there are signs of publication bias for performance, and no effect of breaks on performance was seen for mentally demanding tasks."},{id:"focus-attention-residue",title:"Leroy · 2009 · Attention residue when switching between work tasks",url:"https://www.sciencedirect.com/science/article/abs/pii/S0749597809000399",type:"research",finding:"In two experiments, Sophie Leroy found that thoughts about a first task tended to persist after people moved on to a second one (“attention residue”), which hurt performance on the second task. Leaving the first task unfinished made this worse, finishing it was not always enough to let go, and finishing it under some time pressure helped people disengage.",limitation:"Only the abstract was read; sample sizes and effect sizes were not checked. The experiments used laboratory tasks, and the helpful role of time pressure applied to closing the first task, not to working under pressure in general."},{id:"focus-ready-to-resume",title:"Leroy & Glomb · 2018 · The “ready-to-resume plan” (University of Washington news release)",url:"https://www.washington.edu/news/2018/01/16/task-interrupted-a-plan-for-returning-helps-you-move-on/",type:"technique",finding:"According to the university’s summary of a paper in Organization Science, four experiments (a study with 202 working professionals and laboratory studies with student participants) tested a “ready-to-resume plan”: on being interrupted, people spent about a minute writing down where they had stopped, what was still unresolved and what they would do next. The plan reduced attention residue and led to better decisions and better recall of information on the interrupting task.",limitation:"A university news release, not the paper itself; no effect sizes were given. Whether the plan improves later performance on the original, interrupted task was not tested."},{id:"focus-newport-time-blocking",title:"Cal Newport · 2013 · “Deep Habits: The Importance of Planning Every Minute of Your Work Day” (calnewport.com)",url:"https://calnewport.com/deep-habits-the-importance-of-planning-every-minute-of-your-work-day/",type:"technique",finding:"Author and computer scientist Cal Newport describes time blocking: each evening he spends 10–20 minutes reviewing his task lists and calendar, then divides the next workday into labeled blocks on paper, leaving space beside them to redraw the plan when something unexpected happens and giving reactive work its own blocks. He says the method reduces his stress and greatly increases his output.",limitation:"A personal blog post (first published 2013, updated 2023); his estimate of how much more productive it makes him is a personal impression, not a study. No controlled trial of time blocking was found."}],U={id:"focus",title:"Focus",subtitle:"Your attention is limited; take good care of it.",description:"See what switching between tasks costs you, tidy up your notifications, check the claims about phones against the evidence, try short breaks and build your own focus plan.",scope:"Suggestions for everyday working habits; this is not a diagnosis or treatment for attention disorders. If attention difficulties persist and affect your daily life, talk to a health professional. Do not silence calls you need for emergencies, caregiving or work.",outcome:"Tidied-up notifications, a focus block you have actually tried and a plan for breaks.",photo:{id:"1505330622279-bf7d7fc918f4",alt:"A bright, tidy work desk"},lessons:[{id:"focus-1",title:"Attention is limited, and switching has a price",minutes:7,goal:"Notice how often you switch between things during the day and how it feels.",reading:["When you move from one task to another, your mind has to change gear. A review of laboratory studies found that people slow down right after a switch and usually make more mistakes. Getting ready for the switch shrinks this cost, but it does not make it disappear. In everyday life the switches are rarely dramatic: a glance at your inbox in the middle of a report, a reply to a message halfway through a thought, another tab opened “just for a second.” Each one is small. Together, they shape how your day feels.","Being interrupted does not always slow you down. In a small experiment, people whose work was interrupted actually finished a little faster, without losing quality, but they reported more stress, frustration and time pressure. So the benefit of staying with one task may not be speed alone; it may also be working more calmly. You will not find popular figures here such as “multitasking costs you this much of your productivity,” because we could not find solid evidence behind them. What we can say is more modest: each switch carries a small load, and some switches are optional."],practice:["For the next hour, make a tally mark every time you switch to another task or app.","Sort the switches: how many were your own choice, and how many came from a notification or another person?","Before your next switch, try a short preparation sentence: “Now I am moving on to …”"],reflection:"How did the switches feel to you?",question:"According to this lesson, what can working with interruptions cost you?",options:["It always makes you finish much more slowly.","Interruptions have no cost at all.","Even if your speed holds up, you may feel more stress and pressure."],correct:2,feedback:"In a small experiment, people who were interrupted sped up a little but reported more stress. Sometimes the cost shows up not in time, but in how you feel.",takeaway:"Every switch is a small load; you can cut the ones you do not need.",sources:["task-switching","interruptions","focus-attention-residue","focus-ready-to-resume"],visual:{kind:"compare",title:"Two ways of working",left:{label:"Frequently interrupted",items:["Changing gear again and again","A short slowdown and a risk of mistakes after each switch","More stress and time pressure"]},right:{label:"Staying with one task",items:["Fewer switches","Time to prepare for the switches you do make","A chance of a calmer pace"]},note:"A general comparison drawn from laboratory findings; it does not give an exact figure for gains or losses."},deeper:[{heading:"Attention residue: part of you stays behind",paragraphs:["Management researcher Sophie Leroy gave a name to a familiar feeling. In two experiments, she found that when people moved from one task to the next, part of their attention stayed with the first one. She called this attention residue: your thoughts keep circling the task you left, so the new task gets less of you than it seems, and performance on it suffers.","Two details from her work are useful. The residue was stronger when the first task was left unfinished. And finishing was not always enough to let go; people disengaged more easily when they had wrapped up the first task under a little time pressure, which seemed to help them close it off. Only the abstract was read, so treat these as the headline findings rather than the full picture."],visual:{kind:"cycle",title:"The switching loop",center:"An open task keeps calling",nodes:[{label:"Switch",text:"You move to something new before the last task is closed."},{label:"Residue",text:"Part of your mind keeps working on the old task."},{label:"Slow start",text:"The new task takes longer to get into and invites mistakes."},{label:"Pull back",text:"You check the old task “just quickly”, and switch again."}],note:"Our illustration, drawing on switch-cost research (Monsell) and attention residue (Leroy); it is not a measured model."}},{heading:"A one-minute note before you switch",paragraphs:["In later work with Theresa Glomb, Leroy tested a simple fix. When an interruption arrived, people spent about a minute writing down where they had stopped, what was still open and what they would do first when they came back. According to the university’s summary, this “ready-to-resume plan” reduced attention residue and helped people make better decisions on the interrupting task, including in a study with working professionals.","What was not tested is whether it also helped with the original task afterward, and our information comes from the university’s summary rather than the full paper. Still, it costs about a minute, and it is a fuller version of the preparation sentence in today’s practice: a short note that closes one door before you open the next."]}],technique:{name:"Ready-to-resume plan",origin:"Sophie Leroy & Theresa Glomb · Organization Science (2018)",steps:["When an interruption comes that cannot wait, pause for about a minute before switching.","Write down where you stopped in the current task.","Note what is still open or unresolved.","Write the first thing you will do when you come back.","Then turn fully to the new task."],evidence:"In experiments summarized by the University of Washington, a plan of about one minute reduced attention residue and improved performance on the interrupting task. Whether it helps with the original task afterward was not tested, and only the news release was read.",sourceId:"focus-ready-to-resume"},example:{title:"Leila, 34, project manager",text:"Leila kept a sticky note next to her keyboard for one hour on a Tuesday morning and made a tally mark at every switch. By ten o’clock she had nineteen marks. When she sorted them, twelve came from chat pings and colleagues stopping by; only seven were her own choice. She did not change anything else that day. But before each of her own switches she tried saying quietly, “Now I am moving on to the budget sheet.” Twice, when a colleague interrupted her, she scribbled one line first: “Stopped at row 40, check the travel costs next.” Coming back was noticeably easier. The day was not transformed, but she left work feeling a little less scattered than usual."},photo:{id:"1745474633597-be94033b16d6",alt:"A person working at a laptop, glancing at a phone"}},{id:"focus-2",title:"How notifications pull at your attention",minutes:7,goal:"Review your notifications and silence them for one work session.",reading:["In one experiment, 221 university students spent one week with notifications on and their phone within sight, and another week with notifications off and the phone put away. In the week with notifications, they reported slightly more inattention and hyperactivity, such as feeling restless and finding it harder to stay with a task. The difference was small, but it was measurable. It is worth noticing how ordinary the change was: nobody gave up their phone. They only changed what it was allowed to do while they worked.","This does not mean notifications cause an attention disorder, and the authors themselves stress that point. The honest message is this: silencing notifications will not solve everything on its own, but it is a low-cost step. You can leave exceptions for important people and emergencies, so you do not have to worry about missing something that matters. You can also try checking your messages at a few fixed times during the day instead of the moment they arrive. Treat it as an experiment rather than a rule, and see what changes for you."],practice:["Look at which apps have sent you notifications in the last hour.","Turn off or silence notifications for at least two apps that can safely wait.","Turn on “Do Not Disturb” for one work session and add exceptions for people who may need you urgently."],reflection:"Which notification was easy to turn off, and which was hard?",question:"Which is the most honest summary of this study’s result?",options:["Cutting notifications made a small but measurable difference.","Notifications cause ADHD.","Turning notifications off solves all attention problems."],correct:0,feedback:"The difference was about 0.1 points and was measured by self-report. You can think of silencing notifications as a low-cost trial, without expecting a miracle.",takeaway:"Silencing notifications is a small step, and small steps count.",sources:["notifications"],visual:{kind:"bars",title:"Average inattention (self-reported)",sourceId:"notifications",bars:[{label:"Notifications on, phone within sight",value:2.38,display:"2.38"},{label:"Notifications off, phone out of reach",value:2.27,display:"2.27"}],note:"221 students, one week in each condition. The difference is small (d = 0.44), based on self-report, and participants knew which week they were in."},deeper:[{heading:"Reading a small effect honestly",paragraphs:["The effect size in this study, d = 0.44, is a standardized measure that compares the difference with how much scores varied. On the questionnaire itself, the gap between the two weeks was only about 0.1 points. Both things are true at once: the difference was real enough to measure, and small in everyday terms. Participants also knew which week they were in, so their expectations may have played a part.","That is why this lesson presents silencing notifications as a cheap experiment rather than a cure. If a slight drop in restlessness is what you get for changing a few settings, that is still a fair trade. And if you notice no difference at all, you have learned something about yourself at almost no cost."]},{heading:"Setting it up without missing what matters",paragraphs:["The main worry people have about silencing their phone is missing something important. Most phones let you choose who can still reach you in “Do Not Disturb” mode, so you can build the exceptions first and silence the rest afterward. It can help to sort your notifications into a few groups, as in the table below, and decide once rather than every time a new app asks."],visual:{kind:"table",title:"Sorting your notifications for a focus block",columns:["Kind of notification","Example","During a focus block"],rows:[["People who may need you urgently","Family, caregiving, on-call work","Let through"],["Time-bound work tools","Team chat on a deadline day","Check at set times"],["Everything else","Social media, shopping, news","Silenced"]],note:"A suggestion, not a tested rule. Adjust it to your job and responsibilities, and never silence calls you need for emergencies or care."}}],example:{title:"Daniel, 27, graduate student",text:"Daniel checked his notification history and was surprised: in one hour, a shopping app, two news apps and a game had all buzzed. He turned all four off. Then, before sitting down with his thesis chapter at nine, he switched on Do Not Disturb for two hours and added two exceptions: his sister, who was expecting a baby, and his supervisor. In the first twenty minutes he reached for the phone three times out of habit and found nothing on the screen. At eleven he checked his messages; nothing had needed him. He is not sure he wrote more than usual, but he noticed he reread fewer paragraphs, and he plans to repeat the setup tomorrow."},photo:{id:"1526045612212-70caf35c14df",alt:"A person holding a smartphone"}},{id:"focus-3",title:"The phone on the desk: claim and evidence",minutes:8,goal:"Tell the difference between a phone simply being near you and actually using it.",reading:["The claim that “your phone drains your mind even when it just sits on the desk” has been shared widely. The 2017 experiments that first proposed it found a small effect. But when researchers repeated one of those experiments in a preregistered direct replication, meaning the plan and analysis were fixed in advance, the effect did not appear. A meta-analysis, a study that pools the results of many others, combined 33 studies and also found no general effect of a phone simply being nearby on cognitive performance.","This does not mean phones never affect attention. What was tested was a phone just being there; using it and getting notifications are separate questions. Putting your phone in another room may still help you. The likely reason is that it reduces the urge to pick it up, or at least makes acting on that urge harder. That is our inference, not a tested finding, which is exactly why this lesson asks you to test it on yourself rather than take anyone’s word for it."],practice:["Notice where you usually keep your phone while you work and how many times you pick it up.","For one work session, put your phone somewhere you cannot reach, and note each time you feel the urge to pick it up.","On another day, try keeping the phone on the desk but silenced; compare the two days using your own observations."],reflection:"What is really hard for you: the phone being there, or the urge to pick it up?",question:"What does current evidence say about a phone simply sitting on the desk?",options:["It definitely drains your mind.","No general effect was found; using it and notifications are a separate question.","Putting your phone in another room is pointless."],correct:1,feedback:"Looking at replications and a meta-analysis, rather than a single first study, gives a more reliable picture. In science, first findings do not always replicate. Keeping your phone out of reach may still work for you as a personal experiment.",takeaway:"How often you reach for your phone may matter more than whether it is there.",sources:["phone-presence","brain-drain","brain-drain-replication","notifications"],visual:{kind:"table",title:"Tracing the “phone on the desk” claim",columns:["Study","Type","Result"],rows:[["Ward et al. 2017","First experiments (N = 520 and 275)","Small effect"],["Ruiz Pardo & Minda 2022","Preregistered direct replication (N = 383)","No effect"],["Hartanto et al. 2024","Meta-analysis, 33 studies (N = 4,368)","No general effect (d = −0.02)"]],note:"Evidence that builds up over time, rather than any single study, gives a more reliable picture."},deeper:[{heading:"How a popular finding became shaky",paragraphs:["The original experiments were careful and the effect they found was small. The idea spread because it was striking and easy to picture. When another team repeated the second experiment with more than 380 students and a plan registered in advance, the phone’s location made no difference to working memory.","The meta-analysis added one more layer. Across 33 studies, there was no overall effect, and a small effect on working memory disappeared once the authors corrected for publication bias, the tendency for studies with positive results to get published more often. This is not a scandal. It is how science is meant to correct itself, and it is a good reason to hold single striking findings a little more loosely."],visual:{kind:"steps",title:"How one claim was tested over time",steps:[{label:"First study",text:"Two experiments find a small effect of a phone on the desk."},{label:"Wide attention",text:"The idea spreads quickly because it is easy to picture."},{label:"Replication",text:"A preregistered repeat of the experiment finds no effect."},{label:"Meta-analysis",text:"33 studies together show no general effect."}],note:"Summary of the three studies in this lesson’s sources."}},{heading:"Presence versus reach",paragraphs:["It helps to keep two questions apart. One is whether a silent phone lying nearby changes how well your mind works; the evidence now says, in general, no. The other is what happens when the phone is allowed to interrupt you or when you keep picking it up. The notification experiment in the previous lesson belongs to that second question, and there the effect was small but present.","So if you work better with your phone in another room, you do not have to give that up. The benefit is probably about the reaching, not about the phone’s mere presence, and your own two-day comparison will tell you more than any headline."],visual:{kind:"compare",title:"Two different questions",left:{label:"Phone just nearby",items:["Tested in many laboratory studies","No general effect on performance","A small working memory effect vanished after bias correction"]},right:{label:"Phone in use or alerts on",items:["A separate question","Alerts on and phone visible: slightly more self-reported inattention","How often you reach for it may matter more"]},note:"The right-hand side draws on the notification study from lesson 2; “reaching” is our inference."}}],example:{title:"Marcus, 41, accountant",text:"Marcus had read that a phone on the desk “drains your brain” and felt guilty every time he saw his. He decided to test it instead. On Monday he left the phone in his coat in the hallway during a two-hour block and made a mark on a notepad whenever he felt like getting it: six marks, mostly in the first half hour. On Wednesday he kept it face down and silenced on his desk. He picked it up nine times, and twice he only noticed after he was already scrolling. His conclusion was modest. The phone lying there did not seem to be the problem; how easy it was to grab was. He now keeps it in the hallway on heavy days and does not feel guilty on light ones."},photo:{id:"1635398235411-2c41ca32ffbc",alt:"A phone lying on a wooden table"}},{id:"focus-4",title:"Short breaks: what they promise and what they do not",minutes:6,goal:"Try a short break and observe how it works for you.",reading:["A meta-analysis that pooled 22 samples found that breaks of up to 10 minutes increased people’s vigor, meaning a sense of energy and alertness, and reduced their fatigue. The effect on overall performance, however, was not statistically significant. In other words, a break can make you feel better; we cannot say it will necessarily make your work faster. That is still worth something. Feeling less drained in the middle of the afternoon is a real benefit, even if it never shows up on a productivity chart.","For mentally demanding work, short breaks showed no effect on performance; tasks like that may need longer breaks. There is also no firm prescription for what to do during a break. Something that takes your mind away from the work is worth trying, such as getting up from the screen, looking out of a window or taking a short walk. Scrolling on your phone may feel like a rest, yet it keeps your attention on a screen, so it may be worth comparing it with a break that does not. Let your own notes decide."],practice:["Put a five- to ten-minute break at the end of one work session.","For the break, choose something that takes you away from the screen: getting up for a glass of water, looking out of the window or a short walk.","Before and after the break, rate how tired you feel from 1 to 5 and write it down."],reflection:"What did your break change for you, and what did it not change?",question:"Which statement about short breaks fits the evidence better?",options:["They definitely improve performance in every kind of work.","Taking a break is just a waste of time.","Promising for vigor and fatigue; the effect on performance is unclear."],correct:2,feedback:"The evidence is more consistent for feeling better than for performance. You can think of a break not as a tool for speeding up your work, but as part of looking after yourself.",takeaway:"A short break can leave you feeling more energetic; try it without expecting a miracle.",sources:["microbreaks","procrastination-pomodoro-breaks"],visual:{kind:"bars",title:"Average effect of micro-breaks",sourceId:"microbreaks",bars:[{label:"Increase in vigor",value:.36,display:"d = 0.36"},{label:"Reduction in fatigue",value:.35,display:"d = 0.35"},{label:"Overall performance (not significant)",value:.16,display:"d = 0.16"}],note:"d shows the size of an effect; 0.36 is a small-to-medium effect. The effect on performance was not statistically significant, and the number of studies is small."},deeper:[{heading:"Fixed breaks or breaks when you feel like it?",paragraphs:["A small Dutch study compared three ways of taking breaks during a study session. Students who chose their own breaks worked and rested in longer stretches, but reported more fatigue and distraction and less concentration and motivation than students on a fixed schedule. How much they got done did not differ meaningfully.","This fits the meta-analysis above: breaks seem to change how you feel more clearly than how much you produce. It also suggests a practical point. Waiting until you feel you need a break may mean you take it later than would be good for you, so a gentle, planned break is worth trying."],visual:{kind:"table",title:"Three break schedules in one study",columns:["Schedule","How it worked","What students reported"],rows:[["Self-chosen","Breaks whenever they wanted","More fatigue and distraction, less concentration and motivation"],["Fixed, Pomodoro-style","6-minute break after every 24 minutes","Better mood; similar amount of work done"],["Fixed, shorter","3-minute break after every 12 minutes","Better mood; similar amount of work done"]],note:"Biwer et al. 2023: 87 university students in a single session; only the abstract was read. It supports trying a schedule, not a particular number of minutes."}},{heading:"Judge a break by how you feel",paragraphs:["Because the evidence for performance is weak, the fairest test of a break is the one in today’s practice: how tired you feel before and after. If your rating drops from 4 to 2, the break did its job, even if your to-do list looks the same.","If you do very demanding work, such as writing, coding or studying hard material, a few minutes may not be enough to recover, and a longer pause or a change of task may serve you better. Try different lengths over a week and keep the ones that help."]}],example:{title:"Grace, 45, customer support team lead",text:"Grace usually worked through the afternoon and felt flat by four o’clock. On Thursday she set a timer to end her 2 p.m. session with a seven-minute break. Before it, she rated her tiredness 4 out of 5. She left her headset on the desk, walked to the end of the corridor and back, and refilled her water bottle. Afterward she rated herself 2. She could not tell whether she answered tickets any faster, and she did not pretend otherwise. What she noticed was that the last hour of the day felt less like a slog. She has kept the afternoon walk and is now trying a second one at eleven."},photo:{id:"1556833232-52da3e4bd5d8",alt:"A woman walking along a path"}},{id:"focus-5",title:"Your own focus plan",minutes:8,goal:"Combine your decisions about notifications, your phone, a work block and a break into one personal experiment.",reading:["Time blocking, which means setting aside a specific stretch of time for a single task, is a method many people use. We have not reviewed a solid study that tests it directly, so we will not call it proven. Still, given what the earlier lessons showed about the cost of switching and the stress of interruptions, it is a reasonable personal experiment. A block gives your attention one job, a start and an end, and it brings the notification and phone decisions you have already made together into one concrete plan.","Add to your plan what you will do when your attention drifts: “If I want to pick up my phone, then I will finish my sentence first.” Plans written in this if–then form have helped people follow through on their intentions in many studies. When the block ends, take a short break and look at how it went. If the block turned out shorter than you hoped, or you did not manage it at all, that is not a failure. It is information for adjusting your plan, and adjusting is part of the method."],practice:["Choose one task for tomorrow and a block length that suits you; starting short is fine.","Complete the sentence “If my attention drifts, then I will …” and set up your notifications before the block starts.","After the block and the break, briefly note what worked and what you would change."],reflection:"Which part of your focus plan supports you the most?",question:"What is the most honest way to approach time blocking?",options:["It is the best method for everyone, and it is proven.","A reasonable personal experiment; you look at the result and adjust.","If a block falls apart, the whole day is wasted."],correct:1,feedback:"Time blocking is a sensible thing to try, but it is not a proven technique. Watching how it works for you and adjusting it is part of the plan. If your attention difficulties persist, you can talk to a health professional.",takeaway:"Your focus plan is an experiment: try it, look, adjust.",sources:["interruptions","mcii","monitoring","if-then-plans","focus-newport-time-blocking","procrastination-pomodoro","procrastination-pomodoro-breaks"],visual:{kind:"steps",title:"One focus block",steps:[{label:"Choose",text:"Pick one task and a length of time that suits you."},{label:"Prepare",text:"Silence notifications and leave exceptions for urgent contacts."},{label:"Work",text:"If you drift, jot down what came to mind and return to the task."},{label:"Break",text:"Get up from the screen and step away for a few minutes."},{label:"Review",text:"Note what worked and adjust the plan."}],note:"This sequence is not a proven technique; it is a suggestion to try on yourself."},deeper:[{heading:"How Cal Newport plans his day",paragraphs:["Computer scientist and author Cal Newport, who writes about focused, undistracted work, has described time blocking on his blog. Each evening he spends ten to twenty minutes looking over his tasks and calendar, then divides the next day’s working hours into blocks on paper, each labeled with what he will do.","Two details make the method more forgiving than it sounds. He leaves space next to the blocks so he can redraw the rest of the day when something unexpected happens, and he gives reactive work such as email its own blocks instead of pretending it will not come. He says the approach lowers his stress and raises his output a great deal; that is his own impression, not a measured result."]},{heading:"Pomodoro: a block in miniature",paragraphs:["Francesco Cirillo’s Pomodoro Technique is a smaller cousin of time blocking. It is usually taught as 25 minutes of focused work followed by a short break, repeated. Cirillo himself stresses that the point is not to collect as many rounds as possible, but to notice what your mind does while you work.","The Dutch break study from the previous lesson gives it modest support: students on fixed breaks felt better than those who chose their own, without getting less done. If a whole morning block feels too big, one 25-minute round can be your first experiment."]},{heading:"The plan–try–adjust loop",paragraphs:["A focus plan works best as a loop rather than a one-time decision. Research on progress monitoring found that people who kept track of how they were doing were more likely to reach their goals, especially when they wrote it down. That is why the review step matters: a two-line note after each block turns a bad day into useful information."],visual:{kind:"cycle",title:"The plan–try–adjust loop",center:"Each round teaches you something",nodes:[{label:"Plan",text:"One task, a length of time and an if–then sentence."},{label:"Protect",text:"Notifications silenced, phone out of easy reach."},{label:"Work",text:"Stay with the task; note stray thoughts and return."},{label:"Rest",text:"A short break away from the screen."},{label:"Review",text:"Write what worked and change one thing for next time."}],note:"A suggested routine, not a tested technique. The review step draws on research linking progress monitoring to reaching goals."}}],technique:{name:"Time blocking",origin:"Cal Newport · “Deep Habits: The Importance of Planning Every Minute of Your Work Day”, calnewport.com (2013)",steps:["The evening before, spend 10–20 minutes looking over your tasks, calendar and notes.","Divide the next day’s working hours into blocks and label each with one task.","Leave space beside the blocks for changes.","Give reactive work, such as email or messages, its own blocks.","When the day goes off plan, redraw the remaining blocks instead of giving up."],evidence:"Newport describes the method from his own experience and says it greatly increases his output, but he offers no study for that claim, and no controlled trial of time blocking was found. The related evidence is on the cost of switching, the stress of interruptions and the benefit of if–then plans.",sourceId:"focus-newport-time-blocking"},example:{title:"Priya, 38, freelance translator",text:"Priya planned a 45-minute block for 9 a.m. to translate a contract, the task she kept pushing to the afternoon. The night before, she wrote it on a paper plan and added one sentence: “If I want to check email, I will write the thought on the pad and keep going.” In the morning she set Do Not Disturb, with her daughter’s school as the only exception. She drifted twice and wrote “invoice” and “call the bank” on the pad. After 30 minutes a client called with something urgent, and the block ended early. She did not call it a failure. Her note read: “30 minutes, 4 pages. Start at 8:30 next time, before clients are awake.”"},photo:{id:"1632772998001-cc9bf6f7c852",alt:"A planner with two pens lying on it"}}]},L=Object.freeze(Object.defineProperty({__proto__:null,COURSE:U,SOURCES:F},Symbol.toStringTag,{value:"Module"})),_=[{id:"sleep-duration",title:"Watson et al. · 2015 · Consensus statement on adult sleep duration",url:"https://doi.org/10.5664/jcsm.4758",type:"guidance",finding:"Fifteen experts from the American Academy of Sleep Medicine (AASM) and the Sleep Research Society concluded that adults should sleep 7 or more hours per night on a regular basis for good health; regularly sleeping less was associated with many health problems.",limitation:"An expert consensus that rests largely on observational studies, so it does not prove that short sleep on its own causes these problems. The full text could not be read; only the abstract and AASM public pages were reviewed."},{id:"cdc-sleep",title:"CDC · Recommended amounts of sleep by age",url:"https://www.cdc.gov/sleep/about/index.html",type:"guidance",finding:"The CDC recommends 7 or more hours of sleep per night for ages 18–60, 7–9 hours for ages 61–64 and 7–8 hours for ages 65 and older. It advises going to bed and getting up at the same times every day and turning off screens at least 30 minutes before bed.",limitation:"General public guidance; it does not replace a personal medical assessment, and the page does not detail the evidence behind it."},{id:"sleep-light",title:"National Sleep Foundation · 2025 · Light and sleep recommendations",url:"https://www.thensf.org/good-light-bad-light-and-better-sleep/",type:"guidance",finding:"The NSF recommends spending at least an hour outdoors in the morning or afternoon, dimming the lights in the evening and turning off screens at least an hour before bed.",limitation:"A public article from a foundation; the one-hour figures are practical suggestions rather than tested thresholds, and the page gives no primary study data."},{id:"sleep-habits",title:"AASM · Healthy sleep habits",url:"https://sleepeducation.org/healthy-sleep/healthy-sleep-habits/",type:"guidance",finding:"The AASM advises getting out of bed and doing a quiet activity in low light if you cannot fall asleep within about 20 minutes, getting up at the same time every day including weekends, and turning off screens at least 30 minutes before bed.",limitation:"A public education page that does not state levels of evidence; 20 minutes is a practical guideline, not a precise scientific threshold."},{id:"caffeine-timing",title:"Drake et al. · 2013 · Caffeine taken 0, 3 or 6 hours before bed",url:"https://doi.org/10.5664/jcsm.3170",type:"research",finding:"In 12 healthy people, 400 mg of caffeine taken right at bedtime, 3 hours before or 6 hours before disrupted sleep compared with placebo; even when taken 6 hours before bed, measured total sleep was reduced by more than an hour.",limitation:"Only the abstract and an AASM press release were read. The sample was very small and a single high dose was tested, so the result cannot be applied directly to lower doses or to other people."},{id:"caffeine-amounts",title:"FDA · 2024 · How much caffeine is too much?",url:"https://www.fda.gov/consumers/consumer-updates/spilling-beans-how-much-caffeine-too-much",type:"guidance",finding:"The FDA states that for most healthy adults, 400 mg of caffeine a day is not generally associated with negative effects, though sensitivity varies from person to person, and it gives approximate amounts per drink.",limitation:"The amounts refer to US drink sizes and do not include values for Turkish coffee or a tea glass; extra care is needed during pregnancy, breastfeeding, childhood and adolescence."},{id:"nhs-insomnia",title:"NHS · Insomnia guide",url:"https://www.nhs.uk/conditions/insomnia/",type:"guidance",finding:"The NHS counts insomnia lasting 3 months or longer as long-term. It advises stopping tea, coffee, alcohol and smoking at least 6 hours before bed, stopping exercise at least 4 hours before, and starting to wind down at least 1 hour before bed.",limitation:"A general information page; most of the advice consists of practical habit suggestions rather than individually tested numerical thresholds."},{id:"insomnia-self-help",title:"NHS Greater Glasgow and Clyde · Insomnia self-help page",url:"https://www.nhsggc.scot/your-health/heads-up-mental-health-support/mental-health-conditions/insomnia/",type:"guidance",finding:"Suggests that people with long-standing sleep problems allow about a quarter of an hour to fall asleep and, if still awake, get up and do something relaxing.",limitation:"A regional self-help page without evidence details; only the relevant sections were reviewed."},{id:"insomnia-guideline",title:"Qaseem et al. (ACP) · 2016 · Chronic insomnia guideline",url:"https://www.acpjournals.org/doi/10.7326/M15-2175",type:"guidance",finding:"The American College of Physicians recommends cognitive behavioral therapy for insomnia (CBT-I) as the first treatment for adults with chronic insomnia disorder (strong recommendation, moderate-quality evidence).",limitation:"The guideline is for adults with symptoms at least 3 nights a week for at least 3 months and cannot be applied directly to a short self-help course; the abstract and recommendation text were reviewed."},{id:"cbti-insomnia",title:"Trauer et al. · 2015 · Meta-analysis of CBT-I for chronic insomnia",url:"https://pubmed.ncbi.nlm.nih.gov/26054060/",type:"research",finding:"20 randomized trials, 1,162 participants: at the end of treatment, CBT-I shortened the time taken to fall asleep by 19.03 minutes and the time spent awake during the night by 26.00 minutes; the 7.61-minute increase in total sleep time was not statistically significant.",limitation:"Only the abstract was read; narrow inclusion criteria limit how far the results generalize, and they apply to CBT-I delivered by clinicians, not to this short course."},{id:"sleep-apnea",title:"NHS · Sleep apnoea guide",url:"https://www.nhs.uk/conditions/sleep-apnoea/",type:"guidance",finding:"The NHS lists breathing that stops and starts during sleep, gasping, snorting or choking noises, loud snoring, feeling very tired during the day and headaches on waking among the signs of sleep apnea.",limitation:"A symptom list does not make a diagnosis; if these signs are present, see a doctor."},{id:"sleep-cbti-overview",title:"Sleep Foundation · Newsom (reviewed by Dimitriu, MD) · 2026 · Cognitive behavioral therapy for insomnia (CBT-I): how it works",url:"https://www.sleepfoundation.org/insomnia/treatment/cognitive-behavioral-therapy-insomnia",type:"guidance",finding:"Describes the parts of CBT-I: stimulus control (use the bed only for sleep and sex, and get out of bed when you cannot fall asleep, here after about 10 minutes, to break the link between the bedroom and wakefulness); sleep restriction (limiting time in bed to build sleep drive, not recommended for people with conditions that sleep loss can worsen, such as bipolar disorder or seizures); sleep hygiene; relaxation methods such as breathing exercises and progressive muscle relaxation; and cognitive restructuring. It describes a nightly cycle in which past bad nights lead to worry about falling asleep and to extra time in bed trying to force sleep, which makes falling asleep harder. CBT-I usually takes six to eight sessions, and digital versions exist.",limitation:"A medically reviewed overview on a health information site, not a study. Its 10-minute figure differs from the AASM’s 20 minutes, which shows these are practical guidelines. Its effectiveness percentages are not tied to a named study on the page, so this course does not use them."}],Z={id:"sleep",title:"Sleep and energy",subtitle:"Give your rest a rhythm.",description:"Get to know how much sleep you need, time your light and caffeine, know what to do when you can’t sleep, and learn when to ask for help.",scope:"Sleep-habit education for adults; it is not a diagnosis or treatment and not a substitute for care. See a doctor if insomnia happens at least 3 nights a week for more than 3 months, if you snore loudly and someone notices pauses in your breathing, or if daytime sleepiness makes daily life hard or affects your driving. Do not start, stop or change sleep medication or any other medication without talking to your doctor.",outcome:"A fixed wake-up time, an evening cut-off for caffeine and screens, a plan for nights when you can’t sleep, and a list of signs that mean it is time to get help.",photo:{id:"1606796913825-2b02883605e9",alt:"Bed with white sheets next to a green plant"},lessons:[{id:"sleep-1",title:"How much sleep do you need?",minutes:7,goal:"Plan your sleep opportunity by counting back from a fixed wake-up time.",reading:["The CDC recommends at least 7 hours of sleep a night for adults aged 18 to 60. Fifteen experts from the American Academy of Sleep Medicine (AASM) and the Sleep Research Society reached the same lower limit. This is not one magic number that fits everyone. Think of it as a floor you try not to drop below on most nights, rather than a target you must hit exactly every single time.","Regularly sleeping too little has been linked with problems such as heart disease, diabetes and depression. Most of these findings come from observational studies, which means they show a connection but do not prove that short sleep alone is the cause. An occasional bad night is also no reason to panic. Today you will choose one simple starting point to build on: getting up at the same time every day, weekends included."],deeper:[{heading:"Why the wake-up time comes first",paragraphs:["Both the CDC and the AASM advise getting up at the same time every day, and the AASM specifically includes weekends. You can control when you get up far more reliably than when you fall asleep, so a fixed wake-up time is the most practical anchor. Your bedtime then follows from it instead of drifting from night to night.","The space between the time you get into bed and the time you get up is your sleep window: the opportunity you give yourself to sleep. Counting back from the wake-up time makes that window visible, and it shows you straight away whether 7 hours can actually fit."],visual:{kind:"steps",title:"Counting back from your wake-up time",steps:[{label:"Fix the wake-up time",text:"For example 6:30 a.m., on weekdays and weekends alike."},{label:"Count back 7 hours",text:"That brings you to 11:30 p.m. as the latest time to be asleep."},{label:"Add time to settle",text:"Allow a little time to drift off, so lights out is around 11:15 p.m."},{label:"Check it for a week",text:"Note when you went to bed and got up, and adjust if needed."}],note:"A worked example, not a prescription. The 7-hour floor comes from the CDC and the AASM consensus; how long you take to fall asleep is personal."}},{heading:"What the numbers can and cannot tell you",paragraphs:["The 7-hour figure is a consensus of experts who looked at a large body of research, much of it observational. That is a sensible basis for a recommendation, but it does not mean that 6 hours and 50 minutes is harmful or that everyone needs exactly the same amount. The CDC’s ranges also shift a little with age.","What matters most is the pattern over weeks, not a single night. If you notice that you regularly fall well short, that is useful information, and it is the kind of pattern this course helps you work on."]}],example:{title:"Daniel, 41, warehouse supervisor",text:"Daniel’s alarm went off at 5:45 on workdays, but on weekends he slept until 9 and then lay awake late on Sunday night. He chose 6:15 as a wake-up time he could keep every day, since his shift started at 7. Counting back 7 hours gave 11:15 p.m., so he aimed to have the lights out by 11. He wrote the two times on a sticky note inside his wardrobe door and kept a short log on his phone. The first Saturday he got up at 6:15 grudgingly and napped on the couch in the afternoon. By the second weekend it was easier, and Sunday night no longer felt like a battle. Nothing dramatic changed; his week simply started with less of a jolt."},practice:["Choose one wake-up time you can keep on both weekdays and weekends.","Count back at least 7 hours from it and, allowing time to fall asleep, set the time you will get into bed.","For the next seven days, jot down a short note of when you went to bed and when you got up."],reflection:"What might make it hard to keep the wake-up time you chose?",question:"How should the adult sleep recommendation be read?",options:["Everyone must sleep exactly 8 hours.","At least 7 hours is a floor you aim to reach on most nights.","If you sleep badly one night, your health will definitely suffer."],correct:1,feedback:"The recommendation is a lower limit and is about regular habits. A single bad night is not the same as a pattern that lasts for a long time.",takeaway:"A fixed wake-up time gives the rest of your sleep a frame.",sources:["cdc-sleep","sleep-duration","sleep-habits"],visual:{kind:"table",title:"Recommended sleep by age (CDC)",columns:["Age","Recommended sleep"],rows:[["18–60","7 or more hours per night"],["61–64","7–9 hours"],["65 and older","7–8 hours"]],note:"The NHS says 7–9 hours for adults. Individual needs can vary; this table is not a medical assessment."},photo:{id:"1767443522987-a83deb358199",alt:"Classic alarm clock on a wooden floor"}},{id:"sleep-2",title:"Give light to the day, dimness to the evening",minutes:6,goal:"Choose one change to your daylight or evening screen use.",reading:["The National Sleep Foundation (NSF) recommends spending at least an hour outdoors in the morning or afternoon and dimming the lights in the evening as you wind down. This is a practical suggestion from a foundation; we are not giving a numerical research result for morning light here. Still, it is an easy experiment: step outside on a break, take a phone call while walking, or drink your coffee by a bright window.","The CDC and the AASM recommend turning off electronic devices at least 30 minutes before bed; the NSF puts it at an hour. You do not have to do all of this at once. A good starting point can be to decide when you will put the screen down and to have a calm activity ready to take its place, so the evening does not suddenly feel empty or restless."],deeper:[{heading:"The guidelines side by side",paragraphs:["Three respected organizations give slightly different numbers, which is a useful reminder that these are practical guidelines rather than precise thresholds. None of them says that 29 minutes without a screen fails and 31 minutes works. They point in the same direction: more light during the day, less light and stimulation in the last part of the evening.","If an hour without screens feels impossible, 30 minutes is still in line with the CDC and AASM advice. You can start there and stretch it later if you notice a difference."],visual:{kind:"table",title:"What each guide suggests",columns:["Guide","Daytime","Evening"],rows:[["NSF","At least an hour outdoors, morning or afternoon","Dim the lights; screens off at least an hour before bed"],["CDC","Not specified","Screens off at least 30 minutes before bed"],["AASM","Not specified","Screens off at least 30 minutes before bed"]],note:"From the public pages of the NSF, CDC and AASM. These are practical recommendations, not tested cut-off points."}},{heading:"Common mistakes",paragraphs:["The most common one is all-or-nothing thinking: trying to go outdoors for an hour, cut every screen and change the whole evening from day one, then giving up after two days. One small change you actually keep does more than a perfect plan you drop.","Another is taking the phone away without putting anything in its place. The screen often fills a real need, such as winding down, company or distraction from worries. A book, gentle stretching or music in dim light gives the evening a new shape instead of a gap."]}],example:{title:"Ana, 29, customer support agent",text:"Ana worked indoors all day and scrolled on her phone in bed until she felt sleepy, often past midnight. She did not try to change everything. On weekdays she began taking her lunch break on a bench outside the office, about twenty minutes, plus a short walk to the bus stop. In the evening she set a reminder for 10:30, half an hour before her usual bedtime, and plugged her phone into a charger in the kitchen. The first few nights felt restless, so she kept a novel and a small lamp on her nightstand. Some evenings she slipped and checked messages anyway. After two weeks the phone stayed in the kitchen on most nights, and falling asleep felt a little less like waiting."},practice:["Pick a moment in your day when you can spend time outdoors or by a window.","Tonight, set the time you will put screens down to at least 30 minutes before bed.","Choose a calm, dimly lit activity to replace the screen: a book, light stretching or music."],reflection:"At what time in the evening is it hardest for you to put the screen down?",question:"For evening screens, which is a starting point that fits the official recommendations?",options:["Using screens right up until you get into bed.","Winding down with a screen and all the lights fully on.","Putting screens away at least 30 minutes before bed."],correct:2,feedback:"The CDC and the AASM recommend at least 30 minutes; the NSF recommends an hour. You can start with the length that suits you and notice how you feel.",takeaway:"Go into the light by day; turn it down in the evening.",sources:["sleep-light","cdc-sleep","sleep-habits"],visual:{kind:"compare",title:"Light across the day",left:{label:"Daytime",items:["Spend time outdoors in the morning or afternoon","Drink your coffee by a window or outside","Tie a short walk to something you already do each day"]},right:{label:"Evening",items:["Dim the lights as you wind down","Put screens away at least 30 minutes before bed","Stretch that to an hour if you can"]},note:"The recommendations come from NSF, CDC and AASM public guidance; they are not tested precise thresholds."},photo:{id:"1527377761-f99968ed8a7f",alt:"Sunlight falling on the floor through a window"}},{id:"sleep-3",title:"Caffeine and evening habits",minutes:8,goal:"Set your last caffeine time and one boundary for your evening habits.",reading:["In an experiment by Drake and colleagues with 12 people, even 400 mg of caffeine taken 6 hours before bed cut measured total sleep by more than an hour. The researchers also reported a gap between how people rated their own sleep and what was measured. The sample was small and only one high dose was tested; even so, the feeling that coffee does not affect you may not always be reliable.","The FDA says that for most healthy adults, a total of 400 mg of caffeine a day is not generally linked with negative effects; the dose in the experiment delivered that whole amount at once. The NHS suggests stopping tea, coffee, alcohol and smoking at least 6 hours before bed, and exercise at least 4 hours before. For example, if you go to bed at 11 p.m., your last tea or coffee could be at 5 p.m. at the latest."],deeper:[{heading:"Building your evening timeline",paragraphs:["The NHS, AASM and CDC each give a time before bed for a different habit. Placed on one timeline, they turn into a simple evening schedule that starts from your bedtime and runs backward, the same way lesson one worked from your wake-up time.","The times below use an 11 p.m. bedtime as an example. Move every line by the same amount if your bedtime is different. You do not need to adopt every line at once; one clear cut-off is a good start."],visual:{kind:"table",title:"An evening timeline for an 11 p.m. bedtime",columns:["Habit","Guide","Cut-off"],rows:[["Tea, coffee, alcohol, smoking","At least 6 hours before (NHS)","5 p.m."],["Exercise","At least 4 hours before (NHS)","7 p.m."],["Start winding down","At least 1 hour before (NHS)","10 p.m."],["Screens off","At least 30 minutes before (CDC, AASM)","10:30 p.m."]],note:"The hour gaps come from the NHS insomnia guide and the AASM and CDC pages; the clock times are a worked example. These are practical habits, not tested thresholds."}},{heading:"Why your own impression can mislead you",paragraphs:["In the Drake study, people’s own ratings of their sleep did not fully match what the measurements showed. Someone can fall asleep after an afternoon coffee and still get less sleep than they would have otherwise. That is why a simple test can be more informative than a hunch: move your last coffee earlier for a week and see how your mornings feel.","Caffeine is also not only in coffee. Black and green tea, cola and energy drinks contain it too, in very different amounts. A one-day log is often surprising, because a few small drinks can add up to more than one strong cup."]}],example:{title:"Tom, 38, high school teacher",text:"Tom thought caffeine never bothered him. He had coffee at breakfast, another at lunch, and a cola while marking papers around 7 p.m. For one day he wrote down every caffeinated drink and was surprised by the evening cola. His bedtime was 11, so he counted back 6 hours and set 5 p.m. as his last caffeine. He swapped the evening cola for sparkling water and moved his run from 8 p.m. to straight after school. The first evenings he missed the little lift while marking. After about ten days he noticed he was falling asleep a bit sooner, though some nights were still restless. He decided the change was worth keeping."},practice:["Count back 6 hours from your bedtime to set the time of your last tea or coffee.","For one day, jot down every caffeinated drink you have.","Choose one boundary for the evening: dropping late coffee, eating your heavy meal earlier or moving exercise earlier."],reflection:"Which of your evening habits seems easiest to change?",question:"What conclusion can be drawn from the Drake 2013 experiment?",options:["A high dose of caffeine taken 6 hours before bed can still shorten sleep.","Caffeine only affects sleep if taken right before bed.","Caffeine does not affect anyone’s sleep."],correct:0,feedback:"In a small experiment, more than an hour of sleep was lost even with caffeine taken 6 hours before bed. The result may differ at lower doses; your own observation also matters.",takeaway:"Count back from your bedtime to find your last caffeine time.",sources:["caffeine-timing","caffeine-amounts","nhs-insomnia","sleep-habits","cdc-sleep"],visual:{kind:"table",title:"Approximate caffeine content (FDA)",columns:["Drink (~12 oz / 355 ml)","Caffeine"],rows:[["Green tea","37 mg"],["Black tea","71 mg"],["Caffeinated soft drink","23–83 mg"],["Energy drink","41–246 mg"],["Brewed coffee","113–247 mg"]],note:"Values are for a US 12-ounce drink; there are no values for Turkish coffee or a tea glass. Extra care is needed during pregnancy, breastfeeding and adolescence."},photo:{id:"1743689374053-be49ca407b7c",alt:"A cup of coffee by a window"}},{id:"sleep-4",title:"Don’t wrestle with sleep in bed",minutes:7,goal:"Prepare a calm plan to use when sleep won’t come.",reading:["The AASM suggests that if you cannot fall asleep within about 20 minutes, you get out of bed, do something quiet in low light and return when you feel sleepy. It also advises using the bed only for sleep and sex; the idea is to pair the bed with sleep rather than with lying awake and struggling. The NHS in Greater Glasgow gives the same advice with about a quarter of an hour, so this is a practical guideline, not an exact threshold.","You do not need to keep checking the clock; the sense that you have been awake for a long time is signal enough. The NHS suggests starting to wind down at least an hour before bed, going to bed only when you feel sleepy and avoiding naps during the day. However the night goes, try to get up at the same time the next morning, even if you feel tired; that keeps tomorrow night on track."],deeper:[{heading:"The worry–wakefulness loop",paragraphs:["Overviews of cognitive behavioral therapy for insomnia (CBT-I) describe a pattern many people recognize. A few bad nights lead to worry about sleep. To make up for it, you spend longer in bed and try harder to fall asleep. Effort and worry keep you alert, so you lie awake, and the bed slowly becomes a place linked with frustration rather than rest. That makes the next night harder too.","Getting up is a way to step out of this loop. It removes the struggle from the bed, so over time the bed can go back to being a cue for sleep. This part of CBT-I is called stimulus control."],visual:{kind:"cycle",title:"The worry–wakefulness loop",center:"Trying harder to sleep",nodes:[{label:"A bad night",text:"You sleep poorly once or several times."},{label:"Worry",text:"“If I don’t sleep tonight, tomorrow will be a disaster.”"},{label:"More time in bed",text:"You go to bed early or stay in bed longer to force sleep."},{label:"More alert",text:"Effort and frustration keep your mind switched on."},{label:"Bed means struggle",text:"Lying awake becomes linked with the bed itself."}],note:"Based on how CBT-I overviews describe the cycle. Getting up when you cannot sleep and keeping a fixed wake-up time are ways to break it."}},{heading:"What to do in your quiet corner",paragraphs:["The aim is not to fill the time productively but to let sleepiness return. Choose something low-key that you can stop at any moment. CBT-I programs also teach relaxation methods, such as slow breathing and progressive muscle relaxation (tensing and then releasing muscle groups one by one), which fit well here.","Different guides suggest getting up after about 10, 15 or 20 minutes. Pick a rough length that feels right for you and estimate it by feel rather than by watching the clock."],visual:{kind:"compare",title:"While you are up at night",left:{label:"Tends to help",items:["Low light, a quiet spot","A dull book or magazine","Slow breathing or gentle stretching"]},right:{label:"Tends to keep you up",items:["Phone, laptop or TV","Checking the time again and again","Working or planning tomorrow in detail"]},note:"Drawn from AASM advice and the relaxation methods described in CBT-I overviews."}}],example:{title:"Nadia, 52, accountant",text:"During tax season Nadia would lie awake for an hour, turning over work in her head and checking the clock. She set up a corner of the living room with a small lamp, a blanket and an old travel book she found mildly boring. On Tuesday night she noticed she had been awake for a long while, so she got up without looking at the time. She read a few pages and did some slow breathing, then went back when her eyes felt heavy. She had to get up once more before falling asleep. In the morning she still rose at 6:45, tired but on schedule. By the end of the week the long stretches of lying awake had become shorter, if not gone."},practice:["Choose a quiet, dimly lit corner you can go to when you can’t sleep.","Pick a screen-free activity to do there: a dull book, light stretching or slow breathing.","Write a short wind-down routine that starts an hour before bed, and try it tonight."],reflection:"On a night when you can’t sleep, what would you like to say to yourself?",question:"What does the AASM suggest if you haven’t fallen asleep after about 20 minutes?",options:["Try harder to force yourself to sleep.","Start scrolling on your phone in bed.","Get up, do something quiet in low light and go back when you feel sleepy."],correct:2,feedback:"Getting out of bed replaces the struggle in bed. You go back when you feel sleepy, and you still get up at the same time in the morning.",takeaway:"Sleep can’t be forced; you make room for it.",sources:["sleep-habits","insomnia-self-help","nhs-insomnia","sleep-cbti-overview"],visual:{kind:"steps",title:"The roughly 20-minute rule",steps:[{label:"Notice",text:"Notice you have been awake a long time; don’t watch the clock."},{label:"Get up",text:"Leave the bed and go to your dimly lit, quiet corner."},{label:"Do something calm",text:"Choose a light, dull activity without a screen."},{label:"Return when sleepy",text:"Go back to bed when you feel sleepy; repeat if needed."},{label:"Same wake-up time",text:"However the night went, get up at the same time."}],note:"The AASM says about 20 minutes and NHS Greater Glasgow about 15; both are practical guidelines."},photo:{id:"1789930445611-3b13fd7d6de4",alt:"Person reading a book by the light of a small desk lamp"}},{id:"sleep-5",title:"When to ask for help",minutes:8,goal:"Recognize sleep signs that may need professional support and choose your next step.",reading:["If insomnia happens at least 3 nights a week and lasts longer than 3 months, it may be chronic insomnia. For chronic insomnia, the American College of Physicians recommends cognitive behavioral therapy for insomnia (CBT-I) as the first treatment, rather than medication. In a meta-analysis that combined 20 randomized trials, CBT-I cut the time taken to fall asleep by about 19 minutes and time spent awake at night by 26 minutes; the increase in total sleep was not statistically significant.","Sleep apnea is a different condition and is not the subject of this course. The NHS lists breathing that stops and starts during sleep, gasping or choking noises, loud snoring, feeling very tired during the day and headaches on waking as signs. If someone else has noticed these, going to the doctor together can help. Do not start, stop or change sleep medication or any other medication without talking to your doctor."],deeper:[{heading:"What CBT-I actually involves",paragraphs:["CBT-I is a structured program, usually over about six to eight sessions with a trained clinician, and digital versions also exist. It combines several parts, and some of them, like stimulus control, you have already met in this course in a simplified form.","One part, sleep restriction, deliberately limits time in bed for a while to build up sleep pressure. It is not recommended for people with conditions that lost sleep can worsen, such as bipolar disorder or seizures, which is one reason it belongs with a professional rather than in a self-help course."],visual:{kind:"table",title:"The main parts of CBT-I",columns:["Part","What it involves"],rows:[["Stimulus control","Bed only for sleep and sex; get up when you can’t sleep"],["Sleep restriction","Temporarily limiting time in bed; best done with a professional"],["Relaxation","Breathing exercises, progressive muscle relaxation and similar methods"],["Cognitive work","Examining worries and unrealistic expectations about sleep"],["Sleep hygiene","How habits, diet, exercise and the bedroom affect sleep"]],note:"Summarized from a medically reviewed CBT-I overview. This course is not CBT-I; it borrows only a few of its gentler ideas."}},{heading:"Signs that call for a doctor, not a course",paragraphs:["Some sleep problems are about habits and can improve with the steps in this course. Others need a proper assessment. Long-lasting insomnia, signs of sleep apnea and daytime sleepiness that gets in the way of life are all good reasons to book an appointment rather than try harder on your own.","If you ever feel so sleepy that it is hard to stay alert while driving, do not drive, and see a doctor soon. A two-week sleep log, with bedtimes, wake-up times and night wakings, makes that conversation easier and more useful."],visual:{kind:"compare",title:"Self-help or see a doctor?",left:{label:"Worth trying on your own",items:["An irregular schedule or late screens","Late-day caffeine","Occasional bad nights after a stressful day"]},right:{label:"Worth seeing a doctor",items:["Insomnia 3+ nights a week for over 3 months","Loud snoring with pauses in breathing, gasping or choking","Daytime sleepiness that affects work, daily life or driving"]},note:"Drawn from the ACP guideline and the NHS insomnia and sleep apnea pages. This is not a diagnostic checklist."}}],example:{title:"Karen, 58, school librarian",text:"Karen had been sleeping badly for most of the year and felt worn out by early afternoon. She had fixed her wake-up time and cut her late tea, which helped a little, but not enough. One morning her husband mentioned that she sometimes seemed to stop breathing for a moment and then snort. She had not known. That week she kept a simple log of bedtimes, wake-up times and how often she woke, and asked her husband to jot down what he noticed. She booked an appointment with her doctor and brought both notes, along with a list of her medicines. She did not change anything on her own. The doctor referred her for a sleep assessment, and she left feeling relieved to have a next step."},practice:["Think honestly about how many nights a week you have struggled to sleep over the last three months.","Ask the person you live with whether they have noticed any signs of sleep apnea.","If needed, keep a short two-week sleep log to take to a doctor: bedtime, wake-up time and night wakings."],reflection:"What might you gain from talking to a professional about your sleep?",question:"For insomnia that happens at least 3 nights a week for more than 3 months, what is the recommended first step?",options:["Start sleeping pills on your own.","See a professional and talk about options such as CBT-I.","Assume that repeating this course will be enough."],correct:1,feedback:"The ACP guideline recommends CBT-I as the first treatment for chronic insomnia; it is a structured therapy delivered with a professional. This course does not replace it.",takeaway:"A sleep problem that lasts is reason enough to ask for help.",sources:["insomnia-guideline","cbti-insomnia","sleep-apnea","nhs-insomnia","sleep-cbti-overview"],visual:{kind:"bars",title:"Change after CBT-I (end of treatment)",bars:[{label:"Time to fall asleep",value:19.03,display:"19 min faster"},{label:"Time awake during the night",value:26,display:"26 min less"},{label:"Total sleep time",value:7.61,display:"+7.6 min · not significant"}],note:"20 randomized trials, 1,162 people; average minute reductions with clinician-delivered CBT-I, and a small increase in total sleep that was not statistically significant. This short course is not CBT-I.",sourceId:"cbti-insomnia"},photo:{id:"1653656120968-accae8452c9e",alt:"Woman sitting on a sofa talking with another woman"}}]},J=Object.freeze(Object.defineProperty({__proto__:null,COURSE:Z,SOURCES:_},Symbol.toStringTag,{value:"Module"})),V=[{id:"cyclic-sighing",title:"Balban et al. · 2023 · Randomized study of cyclic sighing and other brief breathing practices",url:"https://pmc.ncbi.nlm.nih.gov/articles/PMC9873947/",type:"research",finding:"In this remote randomized study, 108 people spent 5 minutes a day for 28 days on a breathing exercise (cyclic sighing, box breathing or cyclic hyperventilation with breath holds) or on mindfulness meditation. The breathing groups, especially cyclic sighing, which lengthens the exhale, showed a greater rise in positive affect than meditation (mean daily change per person 1.91 versus 1.22) and a greater drop in breathing rate. State anxiety fell in all groups (mindfulness −3.95, breathing groups combined −3.03).",limitation:"Most participants were healthy young people from an undergraduate psychology course at Stanford, subgroup samples were small, adherence was self-reported, and the study was exploratory and not registered in advance (it was registered retrospectively); no meaningful changes were found in heart rate variability or sleep measures."},{id:"slow-breathing",title:"Zaccaro et al. · 2018 · Systematic review of slow breathing",url:"https://www.frontiersin.org/journals/human-neuroscience/articles/10.3389/fnhum.2018.00353/full",type:"research",finding:"This review of techniques using fewer than 10 breaths per minute screened 2,461 abstracts and included 15 articles; slow breathing was associated with higher heart rate variability, more relaxation and comfort, and less anxiety, arousal, depressive symptoms and anger.",limitation:"It covers only 15 small studies in healthy people, with very different designs and techniques; according to the review, none used a longitudinal or randomized controlled design, and no effect sizes were calculated."},{id:"activity-mood",title:"Singh et al. · 2023 · Umbrella review of physical activity and mental health",url:"https://bjsm.bmj.com/content/57/18/1203",type:"research",finding:"Pooling 97 systematic reviews (1,039 randomized trials, 128,119 participants), physical activity reduced symptoms of depression (median effect size −0.43), anxiety (−0.42) and psychological distress (−0.60); higher intensity was linked with greater improvement, and interventions of 12 weeks or less showed the largest effects.",limitation:"77 of the 97 included reviews were rated critically low in quality on the AMSTAR tool, so the exact numbers should be read with caution; movement does not replace professional treatment for severe depression or an anxiety disorder."},{id:"emotion-regulation",title:"Webb, Miles & Sheeran · 2012 · Meta-analysis of emotion regulation strategies",url:"https://eric.ed.gov/?id=EJ971301",type:"research",finding:"Across 306 experimental comparisons, taking a different perspective (d+ = 0.45) and reappraising the situation (d+ = 0.36) had small-to-medium effects on emotion, while suppressing thoughts was not effective (d+ = −0.12).",limitation:"Only the abstract was read. Most studies used brief emotions induced in the lab, so the results do not generalize directly to long-term everyday stress or to clinical groups."},{id:"affect-labeling",title:"Torre & Lieberman · 2018 · Review of putting feelings into words (affect labeling)",url:"https://journals.sagepub.com/doi/10.1177/1754073917742706",type:"research",finding:"This narrative review proposes that putting feelings into words can soften emotional experience and that, unlike explicit regulation techniques, it may not feel like a regulation process at all.",limitation:"Not a systematic review or meta-analysis; it gives no numerical effect sizes, and only part of the abstract could be read."},{id:"who-stress",title:"WHO · Stress: questions and answers",url:"https://www.who.int/news-room/questions-and-answers/item/stress",type:"guidance",finding:"The WHO defines stress as a state of worry or mental tension caused by a difficult situation. To cope, it recommends a regular daily routine, regular sleep, regular exercise, staying connected with people you trust and sharing your feelings, and cutting down on news and social media.",limitation:"General public guidance with no numerical effect data."},{id:"nhs-stress",title:"NHS · Get help with stress",url:"https://www.nhs.uk/mental-health/feelings-symptoms-behaviours/feelings-and-symptoms/stress/",type:"guidance",finding:"The NHS notes that stress can show up as headaches, muscle tension, difficulty concentrating, feeling overwhelmed, irritability and changes in sleep. It suggests talking about your feelings with a friend, family member or health professional, and seeing a GP if you are struggling to cope with stress or self-help is not working.",limitation:"Written for UK services; in an emergency, contact your local emergency number."},{id:"nhs-stress-tips",title:"NHS · 10 tips to reduce stress",url:"https://www.nhs.uk/mental-health/self-help/guides-tools-and-activities/tips-to-reduce-stress/",type:"guidance",finding:"The NHS lists 10 suggestions, including being active, connecting with people and helping others, and notes that exercise will not make stress go away but can reduce some of the emotional intensity you feel.",limitation:"A general list of suggestions with no stated level of evidence."},{id:"calm-nhs-anxiety",title:"NHS Every Mind Matters · Anxiety",url:"https://www.nhs.uk/every-mind-matters/mental-health-issues/anxiety/",type:"guidance",finding:"Lists physical and mental signs of anxiety, including tiredness, restlessness, dizziness, trouble concentrating, worrying about the past or future, catastrophic thinking, headaches, stomach ache, muscle tension, a racing heart and breathlessness. It warns that avoiding situations, or relying on habits we think keep us safe, can actually make anxiety worse, and suggests facing feared situations gradually, together with breathing exercises, a diary of triggers, a set daily worry time and looking at situations from different angles. It advises contacting NHS 111 or a GP if anxiety is seriously affecting daily life, and getting urgent help if you cannot cope or keep yourself safe.",limitation:"Public self-help guidance for England with no evidence details; services and phone numbers differ by country. In an emergency, contact your local emergency number."}],$={id:"calm",title:"Stress and calm",subtitle:"Make room around the tension.",description:"Notice and name stress, lengthen your exhale, get your body moving, look at the situation from another angle, and know when to ask for help.",scope:"Everyday stress-management education for adults; it is not a diagnosis or treatment and not a substitute for care. If you feel dizzy or unwell during a breathing exercise, stop and return to your normal breathing. If you have panic attacks, if stress or anxiety is disrupting your daily life, or if self-help is not working, see a doctor or mental health professional; do not stop any treatment or medication without talking to your doctor. If you have thoughts of harming yourself or are in immediate danger, call your local emergency number.",outcome:"Your own stress signals, a breathing exercise you have tried, a short movement plan, a perspective question and a list of people and services to turn to.",photo:{id:"1557316655-8715fdecd2d1",alt:"Still lake at the foot of a mountain"},lessons:[{id:"calm-1",title:"Notice stress, give it a name",minutes:6,goal:"Notice how stress shows up in your body and mind, and give it a name.",reading:["The World Health Organization (WHO) describes stress as a state of worry or mental tension caused by a difficult situation. Feeling tense before an exam, during a heavy week at work or in an argument is an ordinary human response; stress on its own is not a sign of weakness. It is part of how people react to challenges. Trouble usually starts when the tension becomes too strong or goes on for too long, and begins to crowd out rest, sleep and the things that normally steady you.","The NHS notes that stress can show up as headaches, muscle tension, trouble concentrating, feeling overwhelmed, irritability and changes in sleep. When you spot one of these signs, you can ask yourself, “What am I feeling right now?” and answer with a single word: tense, hurt, overwhelmed. A review by Torre and Lieberman suggests that putting feelings into words can soften the experience a little. The review gives no numbers, so treat this as an experiment worth trying rather than a proven fix."],deeper:[{heading:"Where stress can show up",paragraphs:["Stress rarely announces itself with the word “stress”. It often arrives first as a clenched jaw, a tight stomach, a short temper or a mind that keeps jumping between tasks. The NHS lists signs across the body and the mind, and its anxiety pages add a racing heart, breathlessness, restlessness and catastrophic thinking, which means jumping straight to the worst possible outcome.","Your own pattern is usually more consistent than you expect. Some people feel it in their shoulders, others in their sleep or their patience. Knowing your first two or three signals gives you an early warning while the stress is still small enough to work with."],visual:{kind:"table",title:"Common signs of stress and anxiety",columns:["Where","What you might notice"],rows:[["Body","Headaches, muscle tension, stomach ache, a racing heart"],["Mind","Trouble concentrating, feeling overwhelmed, expecting the worst"],["Mood","Irritability, restlessness"],["Rest","Changes in sleep, tiredness"]],note:"From NHS pages on stress and anxiety. These signs have many possible causes; if they persist or worry you, see a doctor."}},{heading:"Why a single word can help",paragraphs:["Torre and Lieberman describe affect labeling, the simple act of naming a feeling, as a quiet form of emotion regulation. Unlike techniques where you deliberately try to change how you feel, naming may not feel like doing anything at all. That is part of its appeal: there is nothing to get right.","A useful label is specific and small. “Everything is terrible” is a verdict about your whole life; “I am tense about tomorrow’s presentation” describes this moment. The second one points toward something you can do, such as preparing one slide or asking a colleague for feedback. Naming does not solve the problem, and that is fine. It simply helps you see it more clearly."]}],example:{title:"Priya, 34, project coordinator",text:"By mid-afternoon Priya’s jaw often ached, and in the evenings she snapped at her partner over small things. She had always called it “just a busy week”. On Tuesday, after a tense meeting, she paused at her desk and asked herself what she was feeling. The first word that came was “annoyed”, then, more accurately, “worried”. She wrote one line in her notes app: “I’m worried because the client moved the deadline.” Nothing about the deadline changed. But she noticed her shoulders drop slightly, and she sent a short message to her manager asking which task could wait. That evening she told her partner she was stressed about work instead of arguing about the dishes. It was a small shift, and it made the evening easier."},practice:["Find one sign of tension you can notice in your body right now: your jaw, shoulders, stomach or breathing.","Give the feeling a one-word name; it does not have to be the perfect word.","Describe the situation behind it in one sentence: “In this situation, I feel …”."],reflection:"Which sign most often tells you that you are stressed?",question:"Which view of stress fits this lesson?",options:["If I feel stressed, something must be badly wrong, and I need to get rid of it right away.","Stress is an ordinary response to difficult situations; noticing and naming it can be a first step.","Naming my feeling will only make it bigger, so I should ignore it."],correct:1,feedback:"Stress is an ordinary response to a difficult situation. Noticing and naming it makes room to choose what to do next; when it becomes too strong or lasts too long, getting support matters.",takeaway:"First notice it, then name it.",sources:["who-stress","nhs-stress","affect-labeling","calm-nhs-anxiety"],visual:{kind:"compare",title:"A verdict or a name?",left:{label:"Sweeping verdict",items:["Everything is going wrong.","I can’t handle this.","I can never calm down."]},right:{label:"Naming",items:["I’m tense about tomorrow’s presentation.","My shoulders are tight and I feel a bit overwhelmed.","I’m irritated after that conversation."]},note:"Naming does not solve the problem; it can make it easier to see what you are going through."},photo:{id:"1758876019128-e76eebf402bd",alt:"Tired person resting their head on one hand at a table"}},{id:"calm-2",title:"Lengthen your exhale",minutes:7,goal:"Try cyclic sighing for about 5 minutes, within your own limits.",reading:["In a study by Balban and colleagues, 108 people spent 5 minutes a day for 28 days on either a breathing exercise or mindfulness meditation. In the breathing groups, and especially with cyclic sighing, which lengthens the exhale, positive mood rose a little more than with meditation, and breathing rate slowed more. Anxiety also fell in the meditation group, so there is no single right method. What mattered was a short, regular practice that people actually did.","Most participants were healthy university students, the groups were small and the study was not registered in advance, so this is an exercise worth trying, not a treatment. A review by Zaccaro and colleagues also linked slow breathing, at fewer than 10 breaths a minute, with more relaxation and lower anxiety, but none of the 15 small studies it covered was a randomized controlled trial. If you feel dizzy, notice pressure in your chest or feel unwell in any way, stop and return to your normal breathing."],deeper:[{heading:"What the study actually compared",paragraphs:["The volunteers were randomly assigned to one of four practices. Cyclic sighing meant a slow inhale through the nose, a second short inhale to fill the lungs completely, then a slow, full exhale through the mouth. Box breathing used inhales, holds and exhales of equal length. A third group did rounds of rapid, deep breaths followed by a breath hold. The fourth group practiced mindfulness meditation, resting attention on one spot and gently returning to it when the mind wandered.","The researchers suggest that a long exhale may help by engaging the calming branch of the nervous system. That is a plausible explanation, not something this study proved. The chart shows the average daily rise in positive mood for the breathing groups taken together and for meditation."],visual:{kind:"bars",title:"Average daily rise in positive mood",bars:[{label:"Breathing exercises (three groups combined)",value:1.91,display:"1.91"},{label:"Mindfulness meditation",value:1.22,display:"1.22"}],note:"Balban et al. 2023: mean daily change per person over 28 days, 108 mostly healthy students. Cyclic sighing showed the largest gain among the breathing groups. State anxiety fell in all groups, slightly more with meditation (−3.95 versus −3.03).",sourceId:"cyclic-sighing"}},{heading:"When to stop, and when breathing is not enough",paragraphs:["NHS inform advises stopping any breathing exercise if you feel discomfort or pain, staying seated for a moment afterwards so you do not get dizzy, and talking to your doctor first if you have a medical condition such as a breathing problem. Go gently; you do not need to force either the inhale or the exhale.","Slow breathing is also one of the NHS self-help steps during a panic attack, a sudden wave of intense fear. Attacks are frightening but not dangerous. If they keep coming back, a breathing exercise is not the answer on its own: see a doctor, because talking therapies such as cognitive behavioral therapy are among the main treatments for panic disorder."]}],example:{title:"Marcus, 45, bus driver",text:"Marcus often came off his late shift wound up, replaying near misses in traffic, and then lay awake. He decided to try cyclic sighing in his parked car before driving home. He set a 5-minute timer, breathed in through his nose, added a short second sip of air, then let it out slowly through his mouth. On the first evening he felt slightly light-headed after a minute, so he slowed down and breathed more gently. Some days he felt calmer afterwards; on others he noticed nothing much, and he wrote that down too. After two weeks the routine had become a clear line between work and home. His stressful shifts did not change, but he walked in the door a little less tense."},practice:["Sit somewhere comfortable, let your shoulders drop and set a timer for about 5 minutes.","Breathe in slowly through your nose; when your lungs feel full, add one short extra inhale, then breathe out slowly and completely through your mouth.","When you finish, note one change you notice in your body or mood; noticing no change is also an observation."],reflection:"What did you notice in your body when you lengthened your exhale?",question:"What is the emphasis in cyclic sighing?",options:["Holding your breath for as long as possible.","Taking fast, deep breaths one after another.","Keeping the exhale slow and long."],correct:2,feedback:"In this exercise, two inhales are followed by a slow, long exhale. If you feel dizzy or uncomfortable, stopping is always the right choice.",takeaway:"A long exhale can be a short break.",sources:["cyclic-sighing","slow-breathing","state-nhs-breathing-tips","state-nhs-panic"],visual:{kind:"steps",title:"Cyclic sighing (about 5 minutes)",steps:[{label:"Settle",text:"Sit comfortably; relax your shoulders and jaw."},{label:"In through the nose",text:"Breathe in slowly through your nose."},{label:"One more short inhale",text:"When your lungs feel full, add one short extra breath in."},{label:"Long out through the mouth",text:"Breathe out slowly and completely through your mouth."},{label:"Keep going",text:"Repeat at your own pace for about 5 minutes."}],note:"If you feel dizzy, short of breath or uncomfortable, stop and return to your normal breathing. This is not a treatment."},photo:{id:"1717691526463-975c4119505c",alt:"Woman standing with her eyes closed in front of a tree"}},{id:"calm-3",title:"Get your body moving",minutes:7,goal:"Fit a short movement break that suits you into your day.",reading:["Singh and colleagues brought together 97 systematic reviews covering 1,039 randomized trials and 128,119 participants. Physical activity was linked with fewer symptoms of depression, anxiety and psychological distress. Somewhat more vigorous activity went with greater improvement, and programs of 12 weeks or less showed the largest effects. In other words, you do not need to run a marathon. A brisk walk, climbing the stairs or a few minutes of dancing in the kitchen all count as physical activity.","Of those 97 reviews, 77 were rated critically low in quality, so read the numbers as pointers, not firm conclusions. The NHS also says exercise will not make stress go away, but it can reduce some of the emotional intensity you feel. Movement is not a substitute for professional treatment for depression or an anxiety disorder. If you have a health condition, talk to your doctor about the right pace for you, and start gently rather than pushing hard on the first day."],deeper:[{heading:"Making it a break, not a punishment",paragraphs:["Exercise plans often fail because they are built like a punishment: too long, too hard and scheduled at the worst time of day. The WHO recommends regular exercise for coping with stress, and regular is much easier when the movement is short and tied to something you already do.","Rating your tension before and after, on a 0 to 10 scale, turns this into a small experiment. Over a week you learn which kind of movement actually helps you, rather than which one you think you should do."],visual:{kind:"compare",title:"Two ways to plan movement",left:{label:"Punishment mode",items:["An hour at the gym or nothing","Pushing as hard as you can on day one","Giving up after one missed day"]},right:{label:"Break mode",items:["Ten minutes of brisk walking after lunch","Something you enjoy, such as dancing or cycling","Starting again the next day, no catching up needed"]},note:"Practical suggestions, not tested rules. Check with your doctor about pace if you have a health condition."}},{heading:"Reading the numbers honestly",paragraphs:["The numbers in the chart are standardized effect sizes, a way of comparing results across studies that used different questionnaires. Values in this range are roughly moderate. They describe average changes across many people, not what will happen to you.","The quality warning matters. When most of the reviews in an umbrella review are rated critically low, the direction of the finding is more trustworthy than its exact size. The honest summary is that moving your body is a reasonable, low-risk thing to try for stress, alongside other support."]}],example:{title:"Lena, 52, dental receptionist",text:"Lena’s days were a stream of phone calls and waiting-room complaints, and by 4 p.m. she felt wired and heavy at the same time. She used to promise herself an hour at the gym and then skip it. This time she chose a 12-minute brisk walk around the block after lunch, the one break she reliably had. Before leaving she rated her tension at 7; when she came back it was 5. Some days it only dropped by one point, and on one rainy day she climbed the building’s stairs instead. After three weeks the walk had become normal, and on quieter days she added a second lap. Her job was no less busy, but the afternoons felt less crushing."},practice:["Choose one kind of movement you could do today: a brisk walk, climbing stairs or a few minutes of dancing.","Link it to a moment that already happens in your day, such as a short walk after lunch.","Rate your tension from 0 to 10 before and after moving, and note the difference."],reflection:"Which kind of movement feels like a break to you, rather than a punishment?",question:"How should the 2023 umbrella review by Singh and colleagues be read?",options:["Movement is linked with fewer symptoms, but most of the reviews were of low quality.","Everyone who exercises will definitely lose their anxiety.","If I exercise, I no longer need medication or therapy."],correct:0,feedback:"The findings suggest movement can help, but most of the reviews were rated critically low in quality, and movement does not replace professional treatment when it is needed.",takeaway:"Short, regular movement can make room on a hard day.",sources:["activity-mood","nhs-stress-tips","who-stress"],visual:{kind:"bars",title:"Reduction in symptoms after physical activity",bars:[{label:"Depression symptoms",value:.43,display:"0.43 reduction"},{label:"Anxiety symptoms",value:.42,display:"0.42 reduction"},{label:"Psychological distress",value:.6,display:"0.60 reduction"}],note:"97 reviews, 1,039 randomized trials; median standardized effect size (shown with a minus sign in the source, meaning a reduction). 77 of the 97 reviews were critically low in quality; this short course has not been tested.",sourceId:"activity-mood"},photo:{id:"1758272421829-7028296dee8f",alt:"Woman stretching on the floor of a living room"}},{id:"calm-4",title:"Change the angle",minutes:8,goal:"Instead of pushing a difficult situation away, try reading it from a different angle.",reading:["Webb, Miles and Sheeran combined 306 experimental comparisons of ways people try to change their emotions. Reappraising the situation, asking “What else could this mean?”, and taking the perspective of an outside observer were among the most effective strategies. Trying not to think about the event at all did not work; its average effect was slightly below zero. Pushing a thought away tends to keep it close, while looking at it from a new angle gives your mind something useful to do with it.","Most of these studies were done in the lab with brief, deliberately triggered emotions, so the findings do not transfer directly to long-term everyday stress or to clinical groups. Reappraising is not pretending a situation is fine, or accepting something unfair. As the NHS suggests, choosing the part you can change and accepting what you cannot change can also be part of this new angle. The aim is a view that is more complete, not one that is forced to be positive."],deeper:[{heading:"How avoidance keeps anxiety going",paragraphs:["Suppressing a thought has a close cousin in behavior: avoiding the situation altogether. The NHS warns that steering clear of situations, or leaning on habits we think keep us safe, can actually make anxiety worse. In the moment, avoiding brings quick relief, which makes it tempting to avoid again next time. Meanwhile you never get the chance to find out that you could have coped.","The way out is usually gradual. The NHS suggests facing feared situations step by step, so they can start to feel manageable, alongside tools such as looking at the situation from different angles. Changing the angle on a thought and taking one small step toward a situation work well together. If anxiety is disrupting your daily life, this is work best done with a professional."],visual:{kind:"cycle",title:"The anxiety–avoidance loop",center:"Quick relief, lasting fear",nodes:[{label:"Trigger",text:"A situation that feels threatening, like a difficult phone call."},{label:"Anxious thought",text:"“This will go badly and I won’t cope.”"},{label:"Avoidance",text:"You put off the call or find a way out."},{label:"Relief",text:"The tension drops, for now."},{label:"Fear grows",text:"You never learn you could cope, so the next trigger feels bigger."}],note:"A simplified loop. NHS guidance warns that avoiding situations can make anxiety worse and suggests facing them gradually. If anxiety disrupts your daily life, see a professional."}},{heading:"Reappraisal is not pretending",paragraphs:["A common mistake is to treat reappraisal as forced positivity: “It’s actually great that my manager criticized me.” That tends to ring false, and the mind rejects it. A more useful reappraisal stays true to the facts and simply adds what you had left out.","The questions below are one way to find that fuller picture. You do not need all of them; one honest answer can be enough to loosen the grip of your first interpretation."],visual:{kind:"table",title:"From a first reading to a fuller one",columns:["Question","Example answer"],rows:[["What happened, in plain facts?","My manager pointed out two errors in my report."],["What else could this mean?","She reads my work closely because the report matters."],["How would an outside observer see it?","Two errors in a long report are common and fixable."],["Which part can I change?","I can fix them today and ask for a second check next time."]],note:"Built on the strategies in Webb et al. 2012 (reappraisal and perspective taking); the questions are practical prompts, not tested scripts."}}],example:{title:"Sam, 27, junior web developer",text:"Sam got a short message from his team lead: “Can we talk tomorrow?” His first reading was that he was about to be let go, and he spent the evening trying not to think about it, which only made the thought louder. Around nine he wrote the situation down in one sentence and asked himself what else it could mean. He came up with two options: a new project, or feedback on last week’s bug. Then he imagined how a friend would see it: a vague message, nothing more. He still felt nervous, but he made a short list of what he had worked on, just in case, and slept better than he expected. The meeting turned out to be about a deadline change. Next time, he decided, he would reach for the pen sooner."},practice:["Write down, in one sentence, a situation that has been stressing you lately.","Ask yourself, “What else could this mean?” and find at least two different explanations.","Imagine how the situation would look to a neutral observer, then say to yourself the sentence you would say to a friend going through the same thing."],reflection:"When you read the situation from another angle, what changed and what stayed the same?",question:"In the 2012 meta-analysis by Webb and colleagues, which stood out as a more effective strategy?",options:["Trying not to think about the event at all.","Trying to see the situation through the eyes of an outside observer.","Getting stuck on the negative feeling and dwelling on it."],correct:1,feedback:"Taking a different perspective and reappraising the situation were among the most effective strategies, while suppressing thoughts did not work. These findings mostly come from short lab experiments.",takeaway:"Instead of pushing the feeling away, look at the situation from another angle.",sources:["emotion-regulation","nhs-stress-tips","calm-nhs-anxiety"],visual:{kind:"bars",title:"Average effect of emotion regulation strategies",bars:[{label:"Taking a different perspective",value:.45,display:"d+ = 0.45"},{label:"Reappraising the situation",value:.36,display:"d+ = 0.36"},{label:"Suppressing thoughts",value:.12,display:"d+ = −0.12 · opposite direction"}],note:"306 experimental comparisons, mostly short lab studies. The effect of suppressing thoughts was below zero; the bar shows its size only.",sourceId:"emotion-regulation"},photo:{id:"1658279366796-e0c28623cd27",alt:"Woman sitting on a windowsill looking outside"}},{id:"calm-5",title:"Support, and when to get help",minutes:8,goal:"Identify the people you trust and recognize the situations that call for professional help.",reading:["To cope with stress, the WHO recommends a regular daily routine, regular sleep and exercise, staying connected with people you trust and sharing your feelings, and cutting down on news and social media. The NHS also says a support network of friends, family and colleagues can ease your troubles, and that talking things through can help you find solutions. Trying to relieve stress with alcohol, smoking, gambling or drugs is not recommended, even when it seems to take the edge off in the moment.","If you are struggling to cope with stress, or the self-help you have tried is not working, you can see a doctor or another health professional; this course is not a diagnosis or treatment. The same goes for panic attacks that keep coming back, or anxiety that gets in the way of work, relationships or daily life. Asking for help is not weakness; it is a way of taking care of yourself. If you have thoughts of harming yourself or are in immediate danger, call your local emergency number."],deeper:[{heading:"Building your support list",paragraphs:["A support list works best when you write it on a calm day, not in the middle of a hard one. When stress is high, it is harder to think of whom to call, and easy to decide that you would only be a burden.","Include different kinds of support: someone you can simply talk to, someone who can help with practical things, and professional contacts. Keep the list somewhere you can find it quickly, such as the notes app on your phone."],visual:{kind:"steps",title:"Four lines for your support list",steps:[{label:"Someone to talk to",text:"A friend or family member you can call or message on a hard day."},{label:"Practical help",text:"A colleague, neighbor or relative who could take one task off your plate."},{label:"Your doctor",text:"The practice or clinic you would contact if stress stops being manageable."},{label:"Emergency",text:"Your local emergency number, for thoughts of self-harm or immediate danger."}],note:"Based on WHO and NHS advice on staying connected and knowing when to get help. Add a crisis line for your country if one exists."}},{heading:"Panic attacks and anxiety that disrupts daily life",paragraphs:["A panic attack is a sudden wave of intense fear, often with strong physical sensations. The NHS says attacks are frightening but not dangerous, and slow breathing can help during one. When attacks happen regularly, that may be panic disorder, and it is worth seeing a doctor: talking therapy such as cognitive behavioral therapy (CBT) is one of the main treatments, and medication helps some people.","The NHS also advises getting help if anxiety is seriously affecting your daily life, and urgent help if you feel you cannot cope or keep yourself safe. CBT with a trained therapist usually runs over 5 to 15 sessions; the short exercises in this course can sit alongside it but are not a substitute for it."]}],example:{title:"Rosa, 61, retired nurse",text:"Since her husband’s surgery, Rosa had been managing his appointments, the house and her own worries alone. She kept telling herself she did not want to bother anyone. One quiet morning she sat down with the support table from this lesson and wrote four lines: her sister for talking, her neighbor for lifts to the hospital, her family doctor, and the emergency number. That week she called her sister and, for the first time, said plainly that she was tired and scared. Her sister offered to come over on Thursdays. Rosa also booked an appointment with her doctor, because her sleep had been poor for over a month. Nothing was fixed overnight, but she no longer felt she was carrying it all alone."},practice:["Name two people you trust whom you could call or message on a hard day.","Choose a moment this week to tell someone how you are doing, or to ask for a small bit of support.","Using the help table, write down in your own notes whom you will turn to in which situation."],reflection:"On a hard day, who is the first person you would want to reach?",question:"What should you do if you have thoughts of harming yourself or are in immediate danger?",options:["Finish the rest of the course exercises and wait.","Handle it on my own so I don’t burden anyone.","Call my local emergency number and, if possible, ask someone to be with me."],correct:2,feedback:"If you are in immediate danger, call your local emergency number. Breathing, movement and perspective exercises are for everyday stress; in an emergency, or when stress becomes unmanageable, they do not replace professional help.",takeaway:"Asking for support is a coping skill too.",sources:["who-stress","nhs-stress","nhs-stress-tips","calm-nhs-anxiety","state-nhs-panic","optimism-nhs-cbt"],visual:{kind:"table",title:"Which support for which situation?",columns:["Situation","Possible step"],rows:[["Everyday tension, a hard day","Breathing, movement, talking to someone you trust"],["You are struggling to cope with stress","See a doctor or health professional"],["Self-help is not working","Talk through your options with a health professional"],["Panic attacks, or anxiety that disrupts daily life","See a doctor or mental health professional"],["Thoughts of harming yourself or immediate danger","Call your local emergency number"]],note:"Based on NHS and WHO advice. This table is not a medical assessment."},photo:{id:"1747764925585-6c2df83b3fd2",alt:"Two women talking over coffee"}}]},Q=Object.freeze(Object.defineProperty({__proto__:null,COURSE:$,SOURCES:V},Symbol.toStringTag,{value:"Module"})),X=[{id:"meditation-goyal",title:"Goyal et al. · 2014 · Meta-analysis of meditation programs (JAMA Internal Medicine)",url:"https://jamanetwork.com/journals/jamainternalmedicine/fullarticle/1809754",type:"research",finding:"From 18,753 records screened, 47 randomized trials with 3,515 participants were included. Mindfulness meditation programs showed small improvements, with moderate-strength evidence, in anxiety (0.38 at 8 weeks; 0.22 at 3–6 months), depression (0.30; 0.23) and pain (0.33); evidence for stress/distress and mental-health-related quality of life was low. There was no evidence that meditation programs were better than active treatments such as drugs, exercise or other behavioral therapies.",limitation:"Evidence was insufficient, or no effect was found, for outcomes such as positive mood, attention, sleep and weight. Programs varied widely in length and content, and this short course was not tested. The abstract and key points on the article page were read."},{id:"meditation-body-scan",title:"Gan, Zhang & Chen · 2022 · Meta-analysis of the body scan (Applied Psychology: Health and Well-Being)",url:"https://doi.org/10.1111/aphw.12366",type:"research",finding:"Across 14 studies of the body scan practiced on its own, it produced only a small increase in mindfulness compared with passive controls (g = 0.268). The authors concluded that the body scan alone is not effective enough to improve health-related outcomes; dropout was low in longer practice periods.",limitation:"Study quality was low and results varied widely between studies. Only the abstract was read."},{id:"meditation-lovingkindness",title:"Zeng et al. · 2015 · Meta-analysis of loving-kindness meditation and positive emotions (Frontiers in Psychology)",url:"https://www.frontiersin.org/journals/psychology/articles/10.3389/fpsyg.2015.01693/full",type:"research",finding:"Across 24 studies (1,759 people), randomized trials showed that loving-kindness meditation increased daily positive emotions compared with waitlist controls (high-arousal positive emotions g = 0.395; low-arousal positive emotions g = 0.392). Practices focused on loving-kindness (g = 0.424) gave clearer results than practices focused on compassion (g = 0.286, with a confidence interval that included zero).",limitation:"38.9% of the studies reviewed had a high risk of bias; expectation effects and self-selected volunteers may inflate the results. Only four studies compared the practice with another active method, and the analysis looked only at positive emotions."},{id:"mental-practice",title:"Toth et al. · 2020 · Mental practice meta-analysis, 24 years later (Psychology of Sport and Exercise)",url:"https://www.sciencedirect.com/science/article/abs/pii/S1469029219301530",type:"research",finding:"Replicating the method of Driskell, Copper and Moran’s 1994 meta-analysis, this study examined 115 effects from 37 studies published between 1995 and 2018. After publication-bias analyses, mental practice (rehearsing a task in the mind without moving) had a small but significant positive effect on performance (r = 0.131, compared with r = 0.255 in the 1994 analysis). The effect depended on practice duration, task type and type of imagery.",limitation:"The studies are mostly about movement and skill performance; they do not test personality change, mood or illness outcomes. The abstract on the publisher’s page was read."},{id:"meditation-adverse",title:"Farias et al. · 2020 · Systematic review of adverse effects in meditation (Acta Psychiatrica Scandinavica)",url:"https://pubmed.ncbi.nlm.nih.gov/32820538/",type:"research",finding:"From 6,742 records, 83 studies (6,703 people) were reviewed. The overall prevalence of adverse effects was 8.3% (3.7% in experimental studies, 33.2% in observational studies). The most commonly reported were anxiety, depression and cognitive anomalies, and adverse effects also occurred in people with no previous history of mental health problems.",limitation:"Studies measured adverse effects in different and often incomplete ways, so the prevalence estimate is uncertain, and it is not clear how many of these effects were caused directly by meditation. Only the abstract was read."},{id:"meditation-nccih",title:"NCCIH · Meditation and mindfulness: effectiveness and safety",url:"https://www.nccih.nih.gov/health/meditation-and-mindfulness-effectiveness-and-safety",type:"guidance",finding:"The US National Center for Complementary and Integrative Health notes that meditation is generally considered low-risk but that research on harms is limited, and cites a 2020 review in which about 8% of participants experienced a negative effect. It stresses that meditation should not replace conventional medical care or be a reason to postpone seeing a doctor about a health problem.",limitation:"General US public guidance. In an emergency, call your local emergency number."},{id:"meditation-mind-wandering-cycle",title:"Hasenkamp et al. · 2012 · Mind wandering and attention during focused meditation (NeuroImage)",url:"https://www.sciencedirect.com/science/article/abs/pii/S1053811911007695",type:"research",finding:"Fourteen experienced meditators practiced breath-focused meditation in an fMRI scanner and pressed a button whenever they noticed their mind had wandered, then returned to the breath. The researchers described a repeating cycle of four phases: mind wandering, awareness of mind wandering, shifting attention back, and sustained focus. Different brain networks were more active in different phases (the default mode network during mind wandering, the salience network during awareness, executive regions during shifting and focus), and some activity patterns were linked with lifetime meditation experience.",limitation:"A small brain-imaging study of 14 experienced meditators; it describes what happens during practice and does not show health benefits or prove that practice causes the brain differences. The abstract on the publisher’s page was read."},{id:"meditation-trauma-sensitive",title:"David Treleaven · Trauma-sensitive mindfulness (davidtreleaven.com)",url:"https://davidtreleaven.com/",type:"guidance",finding:"Treleaven, an educator who trains mindfulness teachers, warns that mindfulness can unintentionally activate symptoms of traumatic stress, and that people with trauma may experience flashbacks, dysregulation or dissociation during practice that turns attention inward. His site offers training and resources to help teachers and practitioners avoid these pitfalls.",limitation:"An educator’s website, not a study. Only the homepage was read; it does not list specific adjustments, so the suggestions in this course (eyes open, shorter sits, an outward anchor, a trained teacher) are common safety practice rather than findings from this page."},{id:"meditation-kabat-zinn",title:"Jon Kabat-Zinn · Full Catastrophe Living (revised edition, 2013)",url:"https://www.penguinrandomhouse.com/books/89149/full-catastrophe-living-revised-edition-by-jon-kabat-zinn-preface-by-thich-nhat-hanh-foreword-by-joan-borysenko/",type:"technique",finding:"Kabat-Zinn describes the mindfulness-based stress reduction (MBSR) program he developed at the University of Massachusetts Medical School: breath awareness, the body scan, sitting meditation, mindful yoga and bringing attention to everyday activities.",limitation:"Mindfulness programs have shown small-to-moderate benefits in research, but reading the book is not the same as an eight-week program with a teacher. The book and programs do not replace diagnosis or treatment."},{id:"meditation-benson",title:"Herbert Benson · The relaxation response (Harvard Health summary)",url:"https://www.health.harvard.edu/blog/a-once-and-future-meditator-tries-the-relaxation-response-for-stress-201110143598",type:"technique",finding:"Benson’s method: sit quietly with eyes closed, relax the muscles, silently repeat a chosen word, sound, phrase or prayer, and let intruding thoughts pass while returning to the focus; practice regularly for 10–20 minutes a day.",limitation:"This page is a blog post and offers no numerical research data. The method is not a treatment and does not replace a doctor’s advice for blood pressure, heart or digestive problems."},{id:"meditation-thich-nhat-hanh",title:"Thich Nhat Hanh · Plum Village · Walking meditation",url:"https://plumvillage.org/mindfulness/mindfulness-practice/walking-meditation",type:"technique",finding:"Plum Village teaches matching steps to the breath (two or three steps on the in-breath, three or four on the out-breath), feeling the moment the foot touches the ground, relaxing the shoulders and arms, and opening attention to the sounds and sights around you; it says this walking can be done anywhere.",limitation:"A traditional practice guide; large, high-quality studies of walking meditation specifically are limited. In traffic and crowds, safety comes first."},{id:"meditation-salzberg",title:"Sharon Salzberg · Lovingkindness (1995; 25th anniversary edition 2020)",url:"https://www.sharonsalzberg.com/lovingkindness",type:"technique",finding:"Salzberg teaches four qualities from the Buddhist tradition, loving-kindness, compassion, sympathetic joy (rejoicing in others’ happiness) and equanimity, through meditations that direct short phrases of good wishes first to yourself and then, in turn, to others.",limitation:"Loving-kindness meditation has been linked with small-to-moderate increases in positive emotions, but many of the studies carry a high risk of bias. Sending good wishes to someone you find difficult does not mean giving up your boundaries."},{id:"dispenza-breaking-habit",title:"Dr. Joe Dispenza · Breaking the Habit of Being Yourself (2012)",url:"https://www.penguinrandomhouse.com/books/603255/breaking-the-habit-of-being-yourself-by-dr-joe-dispenza/",type:"technique",finding:"Dispenza proposes a meditation that expands step by step over four weeks: settling into the body and the present moment, noticing and admitting the old pattern of feeling and thinking you want to change, letting it go, recognizing and interrupting the moments it switches on during the day, and rehearsing the new self you want to become together with its emotion.",limitation:"Mental rehearsal and noticing habits fit with research. The book’s claims about changing reality through quantum physics, influencing genes and healing illness with thought are not supported by science; do not change your treatment because of this method."}],ee={id:"meditation",title:"How to meditate",subtitle:"Attention that starts with the breath.",description:"Try breath awareness, the body scan, a repeated word, walking, loving-kindness and Dr. Joe Dispenza’s mental rehearsal, one step at a time. Along the way, learn honestly what research does and does not support for each technique.",scope:"Meditation education for adults; it is not diagnosis or treatment and does not replace therapy or medication. Do not stop a treatment or medication without talking to your doctor. If you have a history of trauma, psychosis or severe mental distress, practice with a mental health professional or a trained teacher; shorter sits with your eyes open may feel safer. Meditation can occasionally bring up difficult feelings or memories. If your distress grows, you feel dizzy or you feel cut off from reality during practice, stop, open your eyes and return to normal breathing; get support if you need it. If you have thoughts of harming yourself or face an emergency, call your local emergency number.",outcome:"Six techniques you have actually tried, a daily 10-minute routine that suits you, a backup plan for hard days, and a clear list of when to stop and ask for help.",photo:{id:"1522075782449-e45a34f1ddfb",alt:"A woman sitting quietly on a bench looking out over a mountain view"},lessons:[{id:"meditation-1",title:"Your first sit: attention on the breath",minutes:8,goal:"Sit for five minutes and watch your breath; when your attention wanders, notice it and gently come back.",reading:["Meditation is not emptying the mind. In this course we treat meditation as placing your attention somewhere on purpose, noticing when it slips away, and bringing it back. In mindfulness-based stress reduction (MBSR), the program Jon Kabat-Zinn developed, the first step is often the breath, because the breath is always with you and you can watch it without changing it. Your mind may wander ten times in a minute. Each time you notice, that noticing is the exercise itself.","Goyal and colleagues screened 18,753 records and examined 47 randomized trials with 3,515 people. Mindfulness meditation programs were linked with small but meaningful improvements in anxiety, depression and pain, and the strength of that evidence was rated moderate. Evidence for stress was low, and there was no sign that meditation beat exercise, medication or other behavioral treatments. So meditation is a learnable skill that may help. It is not a miracle, and it is not a replacement for treatment."],deeper:[{heading:"Why wandering is part of the practice",paragraphs:["A small brain-imaging study gives a useful picture of what a sit actually looks like. Fourteen experienced meditators focused on the breath and pressed a button each time they noticed their mind had drifted. The researchers described a loop that kept repeating: the mind wanders, you become aware of it, you shift attention back, and you stay with the breath for a while until it wanders again.","Even experienced meditators went around this loop again and again. That is worth remembering on a restless day. A sit full of wandering is not a failed sit; it is a sit with many repetitions of the two moves that matter most, noticing and returning. The study was small and does not show health effects, but the loop itself matches what most people experience."],visual:{kind:"cycle",title:"The loop inside every sit",center:"Breath as the anchor",nodes:[{label:"Wander",text:"Attention drifts into a plan, a memory or a worry."},{label:"Notice",text:"You realize you are no longer with the breath."},{label:"Return",text:"You gently shift attention back, without scolding."},{label:"Stay",text:"You rest with the breath for a few moments, until it drifts again."}],note:"Based on the four phases described by Hasenkamp et al. (2012) in 14 experienced meditators. The loop is normal; noticing and returning are the training."}},{heading:"Common mistakes",paragraphs:["The most common mistake is trying to control the breath: making it deeper, slower or more “correct”. For this practice you only watch. If watching makes your breathing feel awkward, move your attention to a place where it feels more neutral, such as the feeling of air at the nostrils or the rise of the belly.","The second mistake is turning each return into a small scolding. A quiet mental note, such as “thinking”, and a kind return work better than frustration. Starting with five minutes is enough; a short sit you repeat beats a long one you dread."]}],example:{title:"Leyla, 31, pharmacist",text:"Leyla set a five-minute timer before her morning shift and sat on a kitchen chair with her feet flat on the floor. She chose the rise and fall of her belly as her anchor. Within the first minute she was mentally reorganizing the delivery schedule. She noticed, said “thinking” in her head, and went back to her belly. Then a text message she needed to answer. Then a song. By the end she had lost count of the returns and felt a bit annoyed that her mind was so busy. On the bus she remembered the loop from the lesson: wander, notice, return, stay. She had just done the exercise dozens of times. The next morning she sat again, a little less annoyed, and the annoyance itself became one more thing to notice."},practice:["Sit on a chair upright but not stiff, with your feet on the floor, and set a timer for 5 minutes.","Choose the place where you feel your breath most clearly, such as the tip of your nose, your chest or your belly, and watch it there without changing it.","Each time your attention wanders, say “thinking” silently and return to the breath; there is no need to count the returns."],reflection:"Where did your attention wander most, and how did it feel to come back?",question:"If your attention keeps wandering during a sit, what does that mean?",options:["Meditation is not for me, and I should stop.","Noticing the wandering and coming back is the exercise itself.","I should push myself harder until my mind is completely empty."],correct:1,feedback:"Wandering is normal. In mindfulness meditation the goal is not a thought-free mind but the skill of noticing and gently coming back.",takeaway:"Noticing and coming back is the meditation.",sources:["meditation-goyal","meditation-kabat-zinn","meditation-mind-wandering-cycle"],visual:{kind:"bars",title:"Average effect of mindfulness meditation programs",bars:[{label:"Anxiety (8 weeks)",value:.38,display:"0.38"},{label:"Depression (8 weeks)",value:.3,display:"0.30"},{label:"Pain",value:.33,display:"0.33"}],note:"47 randomized trials, 3,515 people; standardized effect sizes (small to moderate). The strength of evidence was moderate; evidence for stress was low, and no advantage over active treatments was shown. This short course was not tested.",sourceId:"meditation-goyal"},technique:{name:"Breath awareness",origin:"Jon Kabat-Zinn · Full Catastrophe Living (1990; revised edition 2013)",steps:["Choose an upright but relaxed posture; close your eyes or lower your gaze to the floor.","Find the place in your body where you feel the breath most clearly.","Watch the breath coming and going with curiosity, without controlling it.","When your attention slips into a thought, notice this without judging it.","Gently return to the breath; repeat this as often as needed.","To finish, feel your whole body for a few breaths, then open your eyes."],evidence:"Mindfulness programs showed small-to-moderate benefits for anxiety, depression and pain, with moderate-strength evidence. The effect of short breath sits on their own has been studied less, and meditation was not found to be better than active treatments.",sourceId:"meditation-kabat-zinn"},photo:{id:"1758273240112-c7724c9bb4a5",alt:"A young woman meditating with her eyes closed on the floor at home"}},{id:"meditation-2",title:"The body scan",minutes:8,goal:"Move your attention through your body from your feet to your head and notice sensations without trying to change them.",reading:["The body scan is one of the core practices taught in the first weeks of MBSR. You lie on your back or sit, and move your attention through the regions of your body in turn: toes, legs, belly, back, hands, shoulders and face. The aim is not necessarily to relax. It is to notice whatever is there, including warmth, pressure, tingling or no sensation at all. If you reach a painful or sensitive area, you can move past it quickly or rest your attention on the breath instead.","A 2022 meta-analysis by Gan and colleagues looked at 14 studies of the body scan practiced on its own. Compared with passive controls, it produced only a small increase in mindfulness, and the authors concluded that the body scan alone is not effective enough to improve health-related outcomes. Study quality was low and results varied a lot. So think of the body scan not as a miracle relaxation technique but as one part of a wider meditation routine."],deeper:[{heading:"How the scan moves",paragraphs:["A simple route keeps the scan from turning into a guessing game. Start where sensations are usually easy to find, such as the soles of the feet, and move slowly upward. At each region, stay for a few breaths, notice what is there, then let it go on an out-breath and move on.","You do not need to cover every square inch. A short scan of five or six regions done with real attention is better than a rushed tour of the whole body."],visual:{kind:"steps",title:"A short body-scan route",steps:[{label:"Feet",text:"Toes, soles, heels: pressure, temperature, contact with the floor or bed."},{label:"Legs",text:"Calves, knees, thighs: weight, tension, or nothing in particular."},{label:"Torso",text:"Belly and back: the movement of breathing, contact with the surface."},{label:"Arms and hands",text:"Fingers, palms, forearms: tingling, warmth, stillness."},{label:"Shoulders and face",text:"Neck, jaw, eyes, forehead: then the whole body as one."}],note:"A simplified route based on the MBSR body scan. Skip or pass lightly over any area that feels painful or distressing."}},{heading:"If your body is a hard place to be",paragraphs:["For some people, especially those with a history of trauma or chronic pain, paying close attention to the body for a long time can bring up distress rather than calm. Trauma educators warn that inward-focused practice can sometimes trigger flashbacks or a sense of being disconnected.","You stay in charge. You can keep your eyes open, sit rather than lie down, shorten the scan to a few minutes, or scan only the hands and feet. If it still feels too much, choose an outward anchor such as sounds in the room, and consider learning with a trained teacher."]}],example:{title:"Tom, 46, delivery driver",text:"Tom tried the body scan lying on his bed after a long shift and was asleep before he reached his knees. The next evening he sat in an armchair instead, eyes half open, and set a timer for eight minutes. His feet felt hot and heavy. His calves felt like nothing much, and he noticed the urge to decide whether that was right or wrong. He simply named it: no clear sensation here. When he reached his lower back, the familiar ache was there. He did not try to fix it; he stayed for two breaths and moved on. At the end he wrote three words in his phone: heavy, ache, warm. It was not a deep relaxation. It was the first time in weeks he had noticed his body before it complained."},practice:["Choose a place where you can lie down or sit comfortably, and set a timer for 8–10 minutes.","Start with the toes of your left foot; stay a few breaths in each region, then slowly move upward.","When you finish, name the three sensations you noticed most clearly, each in a single word."],reflection:"Which part of your body felt new or surprising to notice?",question:"During a body scan, what do you do if you feel nothing in one area?",options:["I tense or move that area until I feel something.","I notice “no clear sensation here” and move on.","I assume I did it wrong and start again from the beginning."],correct:1,feedback:"Numbness or a neutral sensation is also an observation. The body scan trains noticing what is there, not producing something.",takeaway:"Listen to your body without trying to change it.",sources:["meditation-body-scan","meditation-kabat-zinn","meditation-trauma-sensitive"],visual:{kind:"compare",title:"The body scan: expectation and practice",left:{label:"Common expectation",items:["I should feel deeply relaxed every time.","I have to make the pain go away.","If I fall asleep, I have failed."]},right:{label:"In practice",items:["I notice whatever is there.","I can move gently past a difficult area.","If I fall asleep, next time I try sitting up."]},note:"Lying down can make you sleepy; if you want to stay awake, try sitting or keeping your eyes slightly open."},technique:{name:"Body scan",origin:"Jon Kabat-Zinn · MBSR program, Full Catastrophe Living",steps:["Lie on your back or sit comfortably; for a few breaths, feel where your body touches the floor or chair.","Bring your attention to the toes of your left foot and explore the sensations there with curiosity.","On an out-breath, let that region go and move your attention to the next one.","Move slowly from the feet to the legs, torso, arms, neck and head.","When your mind wanders, remember where you were and return there.","At the end, feel your whole body as one for a few breaths."],evidence:"The body scan on its own showed a small increase in mindfulness but no clear effect on health outcomes; it has mostly been studied as part of wider programs. For some people with a history of trauma, focusing on the body for a long time can be hard; you can keep your eyes open and the practice short.",sourceId:"meditation-kabat-zinn"},photo:{id:"1535987271305-c26a8935f74a",alt:"A woman lying on the grass in sunlight, resting"}},{id:"meditation-3",title:"The relaxation response: sit with a word",minutes:7,goal:"Using Herbert Benson’s method, sit for 10 minutes repeating a word you have chosen.",reading:["In the 1970s, cardiologist Herbert Benson distilled the common elements of different meditation traditions into a simple method he called the relaxation response. It has two core elements: repeating a word, sound, phrase or short prayer, and a passive, unforced attitude toward the thoughts that come in. You choose the word. It can be a neutral word like “calm”, or a short prayer or phrase that means something to you. Benson recommends practicing for 10–20 minutes a day.","What Benson emphasized was regular practice more than the technique itself. You do not need to check whether you are saying the word correctly or relaxing enough; when a thought comes, returning to the word is enough. The numbers with moderate-strength evidence in the Goyal meta-analysis were for mindfulness programs, so this course gives no precise effect figure for Benson’s method in particular. The method is not a treatment and does not replace a doctor’s advice for blood pressure or heart problems."],deeper:[{heading:"Why a passive attitude matters",paragraphs:["Many people turn meditation into another task to perform well. They fight thoughts, check their progress and get tense about not being relaxed. Benson’s method deliberately removes that pressure. The word gives the mind something simple to hold, and the passive attitude means a thought is not a problem to solve, only a signal to return.","This is the same move as in the breath practice, with a different anchor. Some people find a word easier than the breath, because it is something they do rather than something they watch. Others find it too mechanical. Both are fine; you are looking for the anchor that suits you."],visual:{kind:"compare",title:"Effort or ease?",left:{label:"Forcing",items:["Pushing thoughts away","Checking whether I am relaxed yet","Repeating the word faster when distracted"]},right:{label:"Passive attitude",items:["Letting thoughts come and go","Not grading the sit","Returning to the word at the same easy pace"]},note:"Our summary of the passive attitude in Benson’s method as described in the Harvard Health summary."}},{heading:"Choosing your word",paragraphs:["A good word is short, easy to say silently on an out-breath, and pleasant or neutral for you. It can come from your faith, such as a short prayer or a phrase of remembrance, or it can be an everyday word like “calm”, “here” or “one”. Benson’s method works the same way with either.","Try to keep the same word for at least a week. Changing it every day turns the practice into a search for the perfect word, which is one more way of forcing."]}],example:{title:"Mehmet, 58, retired teacher",text:"Mehmet found watching his breath made him fidgety, so he tried Benson’s method after his afternoon tea. He chose a short phrase of remembrance from his prayers, one he had known since childhood. He sat in his armchair, relaxed his muscles from his feet up to his face, and silently said the phrase on each out-breath. Thoughts about his grandson’s exam kept arriving. Each time he said to himself “that’s all right” and went back to the phrase, at the same slow pace. After ten minutes he sat quietly for another minute before getting up. He did not feel transformed. He did notice he had not looked at his phone for eleven minutes, which was new. He decided to keep the same phrase and the same armchair for the rest of the week."},practice:["Choose a short word, phrase or brief prayer that feels good to you.","Sit comfortably, close your eyes, relax your muscles from your feet up to your face, and set a timer for 10 minutes.","Say your word silently on each out-breath; when a thought comes, say “that’s all right” and return to your word."],reflection:"How did the word you chose feel, and will you use the same one tomorrow?",question:"In Benson’s method, what do you do when thoughts come in?",options:["I push the thought away and empty my head.","I stop the sit halfway; it means I cannot focus.","Without forcing, I say “that’s all right” and return to my word."],correct:2,feedback:"The passive attitude is the heart of the method. Instead of chasing or suppressing thoughts, noticing them and returning to the word is enough.",takeaway:"One word, one breath, one more return.",sources:["meditation-benson","meditation-goyal"],visual:{kind:"table",title:"The four elements of the relaxation response",columns:["Element","How to practice it"],rows:[["A quiet setting","A corner where no one will disturb you for a short while"],["A focus word","A word like “calm”, or a short prayer or phrase that means something to you"],["A passive attitude","Return to the word without chasing thoughts"],["A comfortable posture","An upright, relaxed sitting position in which you will not fall asleep"]],note:"Benson recommends 10–20 minutes a day; you can start with less."},technique:{name:"The relaxation response",origin:"Herbert Benson · The Relaxation Response (1975)",steps:["Choose a short word, sound, phrase or prayer that means something to you.","Sit comfortably in a quiet place and close your eyes.","Relax your muscles in turn, starting at your feet and moving up to your face.","Breathe naturally through your nose; silently repeat your word on each out-breath.","When thoughts come, return to your word without engaging with them.","After 10–20 minutes, sit quietly with your eyes closed for a minute or two, then get up slowly."],evidence:"Meditation programs in general showed small-to-moderate benefits for anxiety and depression; we cannot give a strong effect figure for Benson’s method specifically. The method is not a treatment and does not replace medication.",sourceId:"meditation-benson"},photo:{id:"1513097847644-f00cfe868607",alt:"A woman sitting quietly on a wooden jetty in sunlight"}},{id:"meditation-4",title:"Walking meditation",minutes:7,goal:"Walk slowly and mindfully for a few minutes, matching your steps to your breath.",reading:["Sitting still is not easy for everyone; sometimes the body wants to move. The Vietnamese Zen teacher Thich Nhat Hanh taught walking as a meditation too: walking not to get somewhere, but to be present in the step you are taking. As the Plum Village community describes it, you might take two or three steps on the in-breath and three or four on the out-breath; your breath and your pace set the number. Feeling the moment your foot touches the ground becomes an anchor that ties your attention to the present.","Walking meditation can be done for a few minutes in a hallway at home, in a park or on the way to work. Movement itself may also help: an umbrella review by Singh and colleagues found physical activity was linked with reductions in symptoms of depression, anxiety and distress, although most of the included reviews were of low quality. We could not find a strong meta-analysis of walking meditation specifically, so treat it as a practice worth trying, not a proven treatment. In traffic or crowds, keep your eyes open; your safety always comes first."],deeper:[{heading:"In daily life",paragraphs:["You do not need a special path. Many people find it easiest to attach walking meditation to walks they already take: the last stretch to the bus stop, a corridor at work, the walk from the car to the front door. Even a minute of mindful steps counts.","Slow walking works best somewhere quiet and safe. On busy streets, walk at a normal pace and simply feel your feet and the air on your face, with your eyes fully on your surroundings."],visual:{kind:"table",title:"Where and how to walk mindfully",columns:["Place","Pace","Anchor"],rows:[["Hallway or room at home","Very slow","Each foot lifting, moving, touching down"],["Park or quiet path","Slow","Steps matched to the breath"],["Walk to work or the bus","Normal","Feet and the sounds around you, eyes open"]],note:"Our own suggestions based on the Plum Village guidance. Safety comes first in traffic, on stairs and in crowds."}},{heading:"Why a moving anchor can help",paragraphs:["For people who feel restless, sleepy or uneasy sitting with their eyes closed, walking offers an anchor that is outside the head and easy to find: the sole of the foot meeting the ground. Your eyes stay open, and your body is doing something.","That makes walking meditation a good option on days when sitting feels impossible, and a gentler way in for anyone who finds inward-focused practice uncomfortable."]}],example:{title:"Ana, 27, nurse",text:"After night shifts Ana was too wired to sit still, so she tried walking meditation in the small park next to the hospital. She picked a quiet stretch of path about fifteen steps long. At first she counted two steps on the in-breath and three on the out-breath, and it felt clumsy, so she let it settle at two and two. Her mind kept replaying a difficult patient handover. Each time she noticed, she brought her attention back to the moment her heel touched the gravel. For the last two minutes she stopped counting and listened: a bus braking, sparrows, wind in the trees. It took seven minutes in total. She still went home tired, but the handover was no longer looping in her head on the tram."},practice:["Choose a calm, safe path of 10–15 steps at home or outdoors.","Take two or three steps on the in-breath and three or four on the out-breath, adjusting the count to your own rhythm.","For the last two minutes, stop counting steps and notice the sounds, the light and the air around you."],reflection:"While walking slowly, what did you see or hear that you had not noticed before?",question:"In walking meditation, how is the number of steps decided?",options:["It is fixed for everyone: four steps per breath.","It is adjusted to your own breathing rhythm and pace.","The goal is to take as many steps as possible."],correct:1,feedback:"The number of steps varies from person to person. What matters is the harmony between breath and step and noticing the moment your foot touches the ground.",takeaway:"Every step is a chance to come back to now.",sources:["meditation-thich-nhat-hanh","activity-mood"],visual:{kind:"compare",title:"An ordinary walk and walking meditation",left:{label:"Ordinary walk",items:["To get somewhere","Mind on plans or on the phone","Steps taken without noticing"]},right:{label:"Walking meditation",items:["For the step itself","Attention on the feet and the breath","Each step placed on the ground knowingly"]},note:"Keep your eyes open in traffic, on stairs and in crowds; safety comes first."},technique:{name:"Walking with the breath",origin:"Thich Nhat Hanh · Plum Village tradition",steps:["Choose a short, safe path where you are not in a hurry.","Stand still and feel your feet on the ground for a few breaths.","Start walking a little more slowly than usual; relax your shoulders and arms.","Count the steps you take while breathing in, then the steps you take while breathing out.","When your mind goes to the past or the future, bring your attention back to the moment your foot touches the ground.","To finish, stop and notice the sounds and colors around you for a few breaths."],evidence:"Movement is linked with fewer mental health symptoms, but the specific effect of walking meditation has not been tested enough in large, high-quality studies. See it as an option for days when sitting is hard.",sourceId:"meditation-thich-nhat-hanh"},photo:{id:"1477332552946-cfb384aeaf1c",alt:"A woman walking slowly along a sunny path"}},{id:"meditation-5",title:"Loving-kindness (metta)",minutes:8,goal:"Spend a few minutes directing short phrases of good wishes first to yourself, then to others.",reading:["Metta means loving-kindness in the Buddhist tradition. As Sharon Salzberg describes it in her book Lovingkindness, you silently repeat a few short phrases of good wishes, for example: may I be safe, may I be peaceful, may I be healthy. Then you direct the same wishes in turn to someone you love, a neutral acquaintance, someone you find difficult, and finally all living beings. If no warm feeling comes, that is fine; in this practice, the intention comes before the feeling.","A 2015 meta-analysis by Zeng and colleagues examined 24 studies with 1,759 people. In randomized trials, loving-kindness meditation produced a small-to-moderate increase in daily positive emotions compared with a waitlist. But 38.9% of the studies had a high risk of bias, and only four compared the practice with another active method. Sending good wishes to yourself may feel artificial at first; self-compassion is also a skill supported by separate research."],deeper:[{heading:"What the research says",paragraphs:["The meta-analysis looked at two kinds of positive emotion: energetic ones, such as joy and enthusiasm, and calm ones, such as contentment and peace. Loving-kindness meditation raised both by a similar, modest amount compared with waiting-list groups.","These are encouraging but limited results. Most studies compared the practice with doing nothing, many carried a high risk of bias, and people who sign up for a kindness meditation study may already expect to feel better. The fair summary: a small-to-moderate lift in positive feelings, not a personality transformation."],visual:{kind:"bars",title:"Loving-kindness meditation and daily positive emotions",bars:[{label:"High-arousal positive emotions",value:.395,display:"g = 0.395"},{label:"Low-arousal positive emotions",value:.392,display:"g = 0.392"}],note:"Standardized effect sizes from randomized trials versus waitlist controls in Zeng et al. (2015), a meta-analysis of 24 studies with 1,759 people. 38.9% of the studies had a high risk of bias.",sourceId:"meditation-lovingkindness"}},{heading:"Common mistakes",paragraphs:["The first mistake is trying to force warmth. Repeating the phrases with intention is the practice; the feeling may come later, or on a different day. The second is starting with the hardest person. It is fine to spend weeks on yourself, a loved one and a neutral person before you try someone difficult.","The third is confusing good wishes with giving in. Wishing someone freedom from suffering does not mean excusing what they did, reconciling or lowering your boundaries. If directing wishes to yourself feels painful, start with someone you love and come back to yourself later."]}],example:{title:"Zeynep, 38, graphic designer",text:"Zeynep thought loving-kindness sounded sentimental, but she tried it after a tense week with a client. Sitting at her desk before opening her email, she silently said: may I be safe, may I be at ease, may I be kind to myself. It felt like reading a greeting card. She kept going anyway, then sent the same wishes to her sister, then to the man at the corner shop whose name she did not know. She felt almost nothing, and that was fine according to the lesson. She skipped the difficult client; she was not ready. Later that day the client sent another sharp message. Zeynep noticed that her reply, while still firm, came out a little less sharp than usual. A small change, and she decided to try again the next morning."},practice:["Choose three short phrases of good wishes for yourself, or use the ones from this lesson.","Repeat the phrases silently, first to yourself, then to someone you love, then to a neutral person.","If you feel ready, send a single good wish to someone you find mildly difficult; if not, skip this step."],reflection:"To whom was it easiest, and to whom hardest, to direct your good wishes?",question:"What do you do if you feel no warm emotion during metta?",options:["I decide the method does not work for me and stop.","I try to force the feeling to appear.","I keep repeating the phrases with intention; the practice continues even without the feeling."],correct:2,feedback:"Metta is not a race to produce a feeling. Repeating the phrases with intention is the practice itself; the feeling sometimes comes and sometimes does not.",takeaway:"A good wish begins as an intention; the feeling can follow.",sources:["meditation-lovingkindness","meditation-salzberg","self-compassion"],visual:{kind:"table",title:"The metta sequence",columns:["To whom","Example wish"],rows:[["Yourself","May I be safe and at peace."],["Someone you love","May you be healthy and happy."],["A neutral acquaintance","May your day go easily."],["Someone you find difficult","May you, too, be free from suffering."],["All living beings","May everyone be safe and at peace."]],note:"If starting with yourself feels hard, you can begin with someone you love. Sending good wishes to someone difficult does not mean you have to reconcile or drop your boundaries."},technique:{name:"Loving-kindness meditation (metta)",origin:"Buddhist tradition · Sharon Salzberg, Lovingkindness (1995)",steps:["Sit comfortably and notice the center of your chest for a few breaths.","Choose three or four short phrases of good wishes for yourself.","Repeat the phrases slowly and silently to yourself.","Bring to mind someone you love and send them the same wishes.","Move to a neutral person and then, if you are ready, to someone you find difficult.","Finally, extend the wishes to all living beings and finish with a few breaths."],evidence:"Meta-analyses suggest loving-kindness meditation can raise positive emotions by a small-to-moderate amount. But many studies carry a high risk of bias, and comparisons with active methods are few.",sourceId:"meditation-salzberg"},photo:{id:"1604881991720-f91add269bed",alt:"Two people holding hands kindly across a table"}},{id:"meditation-6",title:"Rehearse your new self",minutes:9,goal:"With Dr. Joe Dispenza’s meditation, notice your old automatic state, let it go, and rehearse the person you want to be, together with how it feels.",reading:["In Breaking the Habit of Being Yourself, Dr. Joe Dispenza argues that most of us spend much of the day on autopilot, running the same thoughts, feelings and reactions. In the meditation he suggests, you first notice this old state in detail, for example a recurring anxiety or anger and the thoughts and behaviors that come with it. Then you honestly admit it, intend to let it go, and learn to recognize the moments it switches on during the day. Finally, you picture the person you want to be, how they think, speak and act, and try to feel that state now.","Mental rehearsal has research support. A 2020 meta-analysis by Toth and colleagues found that across 37 studies from 1995 to 2018, mental practice improved performance by a small but significant amount. The same study reports that the effect was smaller than in the pioneering 1994 meta-analysis, and the studies mostly involve movement and skill tasks. The book’s claims about changing reality through the quantum field, influencing genes or healing illness with thought are not supported by scientific research. Use this lesson as rehearsal for a behavior you want to change, not as a treatment or a way to shape reality."],deeper:[{heading:"The working core and the claims to leave aside",paragraphs:["Dispenza’s meditation mixes practical elements with big claims, and it helps to separate them kindly. The working core has three parts. Attention: catching the old pattern as it happens instead of after the fact. Rehearsal: walking through the new response in your mind, in a specific scene. Emotion: letting the rehearsal carry a feeling, such as calm or confidence, which makes it more vivid and memorable.","Those parts fit what research says about noticing habits, mental practice and planning. The claims around them, that meditation reshapes reality through the quantum field, switches genes on and off or heals illness by thought, do not have scientific support. You can use the core without accepting the claims, and you should never change a treatment because of them."],visual:{kind:"compare",title:"Dispenza’s meditation: what to keep and what to leave aside",left:{label:"Working core",items:["Noticing the old pattern and its triggers","Rehearsing a new response in a specific scene","Feeling the emotion of the new state during rehearsal","Taking one small real-world step afterward"]},right:{label:"Not supported by evidence",items:["Changing reality through the quantum field","Switching genes on or off by thinking","Healing illness with thought instead of treatment"]},note:"Our own summary, based on the book’s description and on research on mental practice and if–then plans."}},{heading:"How Dispenza does it, and how to make it practical",paragraphs:["In the book the meditation builds up over four weeks, adding one stage at a time: settling into the body, recognizing and admitting the old state, letting it go, noticing when it switches on, and rehearsing the new self. This lesson compresses it into a single nine-minute sit, which is a simplification.","Research on mental practice points to one clear way to get more from it: rehearse a specific, realistic scene, then act on it. An if–then plan, such as “if my manager criticizes my work, then I will pause, breathe out and ask one question”, turns the rehearsal into a behavior you can actually try the same day."]}],example:{title:"Kerem, 42, sales manager",text:"Kerem wanted to stop snapping at his team when numbers were late. In a nine-minute sit, he first pictured the old pattern in detail: the report arriving, the heat in his chest, the thought that nobody takes this seriously, the curt message. He admitted it plainly and imagined setting it down. Then he rehearsed the Monday meeting three times as the manager he wanted to be: pausing, breathing out, asking what was blocking the report. He let himself feel steady rather than tense while he pictured it. Before opening his eyes he made one plan: if a report is late, then I ask one question before I say anything else. On Monday a report was late. He felt the heat, remembered the plan, and asked the question. The meeting went slightly better."},practice:["Choose one automatic state you want to change; write down the moment that triggers it, the thought that comes with it and what you do.","In a nine-minute sit, follow the technique steps and picture the state you want to be in, within a specific scene, at least three times.","Choose one small behavior you will do today in this new state and turn it into a plan: “If … happens, then I will …”."],reflection:"In the moment your old state switches on, what would the person you want to be do differently?",question:"Which part of this technique is best supported by research?",options:["Changing events and reality through the quantum field.","Rehearsing the behavior you want in your mind and then trying it in real life.","Healing illness with thought so that medication is no longer needed."],correct:1,feedback:"Mental rehearsal shows a small but significant benefit, especially when followed by a real-life attempt. The quantum and healing claims are not supported; never stop a treatment for that reason.",takeaway:"Rehearse your new self in your mind, then bring it to life with one step.",sources:["dispenza-breaking-habit","mental-practice","if-then-plans"],visual:{kind:"bars",title:"Average effect of mental practice on performance",bars:[{label:"Driskell et al. · 1994",value:.255,display:"r = 0.255"},{label:"Toth et al. · 2020",value:.131,display:"r = 0.131"}],note:"Values from Toth et al. (2020); the newer analysis covers 37 studies from 1995 to 2018 and corrects for publication bias. The studies are mostly about movement and skill tasks; personality change and recovery from illness were not measured.",sourceId:"mental-practice"},technique:{name:"Let go of the old self, rehearse the new",origin:"Dr. Joe Dispenza · Breaking the Habit of Being Yourself (2012)",steps:["Sit comfortably, close your eyes and, by sensing the space around your body, bring your attention down from your thoughts into your body and the present moment.","Choose an old state you want to change: a feeling you often have, and the thoughts and behaviors that come with it.","Honestly admit this state to yourself, silently state your intention to let it go, and relax as if you were handing it over.","Picture in detail the moments in your day when the old state switches on, and decide on the signal you will use to tell yourself “stop, change” in that moment.","Ask yourself how you would be at your best; picture how that person thinks, speaks and acts.","Try to feel the emotion of this new state, such as calm, confidence or gratitude, in your body now, and rehearse the scene a few times.","Before opening your eyes, choose one small behavior you will do today in this new state."],evidence:"Mental rehearsal shows a small but significant benefit for skill performance; noticing an old habit and tying a new behavior to a concrete plan are also supported approaches. Claims about changing reality through the quantum field, influencing genes or healing illness with thought are not scientifically supported.",sourceId:"dispenza-breaking-habit"},photo:{id:"1631832293782-2eda7804489b",alt:"A quiet room with morning sun streaming through the window and a potted plant in front of it"}},{id:"meditation-7",title:"Your own routine, and what to watch for",minutes:8,goal:"Build a daily meditation routine that suits you and know when to stop and ask for help.",reading:["For most people, short regular sits are more sustainable than long, occasional ones. Ten minutes each day tied to the same cue, for example right after you pour your morning tea, can be a good start. A study by Lally and colleagues showed that behaviors repeated in the same context become more automatic over time, but how long that takes varies a lot between people. On hard days, shorten the sit, walk instead of sitting, or settle for a few long out-breaths; missing one day does not break your routine.","Meditation is safe for most people, but it is not risk-free. A 2020 systematic review by Farias and colleagues found an overall rate of adverse effects of 8.3% across 83 studies with 6,703 people; the most commonly reported were anxiety and depressive symptoms, and they also occurred in people with no previous mental health problems. If you have a history of trauma or psychosis, practice with a professional; if your distress grows, old memories shake you or you feel cut off from reality, stop and get support. Meditation does not replace therapy or medication; if you have thoughts of harming yourself or face an emergency, call your local emergency number."],deeper:[{heading:"Building the routine",paragraphs:["A routine rests on three things: a cue you already have, a length you can manage on a bad day, and a backup for when the plan fails. An if–then plan ties them together: “if I have poured my morning tea, then I sit for ten minutes.” Plans in this form have helped people turn intentions into action across many studies.","Keep the first week simple. One technique, one time, one place. At the end of the week, look back at what worked and adjust the length or technique, rather than starting over from scratch."],visual:{kind:"steps",title:"A one-week starter routine",steps:[{label:"Pick a cue",text:"Something you already do daily, such as pouring tea or parking the car."},{label:"Pick a technique",text:"Breath, body scan, word, walking, metta or rehearsal."},{label:"Set a length",text:"Ten minutes on normal days, three minutes as the minimum."},{label:"Write a backup",text:"“If I cannot sit, I will walk mindfully for three minutes.”"},{label:"Review",text:"After seven days, note what helped and adjust one thing."}],note:"Our own template, based on research on habits in a stable context and on if–then plans."}},{heading:"When meditation stirs things up",paragraphs:["Sometimes a quiet sit brings up difficult feelings, memories or body sensations. This is not a sign you are doing it wrong, and it is not a sign you should push through. Trauma educators note that practices that turn attention inward can occasionally trigger flashbacks, strong dysregulation or a sense of being disconnected, especially for people with trauma.","Practical adjustments help many people: keep your eyes open, keep sits short, choose an outward anchor such as sounds or your feet on the floor, and stop whenever you need to. If you have a trauma history, learning with a trained teacher or alongside a therapist is a sensible choice. Some people find that a few slow breaths with a long exhale help them settle before or after a sit."]}],example:{title:"Elif, 35, teacher",text:"Elif chose the body scan as her technique and tied it to the moment she parked her car after work. For four days it went well. On the fifth, halfway through the scan, a tight feeling in her chest brought back a painful memory from years ago, and she felt shaky. She remembered the lesson: she opened her eyes, pressed her feet into the car floor, looked at the trees outside and let out a few long breaths. She stopped for the day. The next day she switched to three minutes of walking meditation with her eyes open, her written backup plan. When the memory came back again that week, she mentioned it to her therapist, who suggested keeping sits short and eyes open for now. Stopping, she realized, had also been part of the practice."},practice:["Choose a daily cue and time to tie your meditation to, for example right after breakfast.","Choose your favorite technique from this course and practice it for 10 minutes every day for one week.","Write your backup plan for a hard day: “If I cannot sit, I will do 3 minutes of walking meditation.”"],reflection:"Which technique in this course helped you most, and why?",question:"If your distress clearly grows during meditation and old memories shake you, what should you do?",options:["I stop, open my eyes, feel my feet and get support from a professional.","I sit longer and wait for these feelings to pass on their own.","I take it as a sign the meditation is going well and keep pushing."],correct:0,feedback:"Adverse effects are not rare, and stopping is part of the practice. With a history of trauma or psychosis, working with a professional is the right step, and in an emergency, call your local emergency number.",takeaway:"Practice short and regularly; knowing when to stop is a skill too.",sources:["meditation-adverse","meditation-nccih","habits","if-then-plans","cyclic-sighing","meditation-kabat-zinn","meditation-trauma-sensitive"],visual:{kind:"table",title:"What can you do, and when?",columns:["Situation","Possible step"],rows:[["I am bored, my mind is very scattered","Shorten the sit or switch to walking meditation"],["Mild unease or tension","Open your eyes, feel your feet, take a few long out-breaths"],["Distress is growing, old memories shake me","Stop and talk to a mental health professional"],["A history of trauma or psychosis","Plan your meditation together with a professional"],["Thoughts of harming yourself, or an emergency","Call your local emergency number"]],note:"Based on Farias et al. (2020) and NCCIH guidance. This table is not a medical assessment."},technique:{name:"Formal and everyday practice",origin:"Jon Kabat-Zinn · Formal and informal practice in MBSR",steps:["Plan a 10-minute formal sit each day after the same cue.","Choose one of the techniques from this course: breath, body scan, word, walking, metta or rehearsal.","Also choose one everyday task to do mindfully: brushing your teeth, washing the dishes or drinking tea.","During that task, pay attention to your senses; when your mind wanders, gently come back.","At the end of the week, review which technique helped you and whether you want to change the length."],evidence:"Regular repetition in the same context supports habit formation, and if–then plans help turn intentions into behavior. Meditation can also have adverse effects; stopping and getting support when distress grows is part of the practice.",sourceId:"meditation-kabat-zinn"},photo:{id:"1781255575628-d645cc39160f",alt:"A simple corner with colorful floor cushions and woven poufs on a wooden floor"}}]},ae=Object.freeze(Object.defineProperty({__proto__:null,COURSE:ee,SOURCES:X},Symbol.toStringTag,{value:"Module"})),ie=[{id:"murphy-subconscious",title:"Joseph Murphy · The Power of Your Subconscious Mind · 1963",url:"https://www.penguinrandomhouse.com/books/296695/the-power-of-your-subconscious-mind-by-joseph-murphy-phd-dd/",type:"technique",finding:"Murphy describes the drowsy state just before sleep as the moment most open to suggestion. He suggests shrinking a wish to one short sentence and repeating it like a lullaby, picturing the result as a brief scene happening now (for example, a friend congratulating you), and ending the scene with a sincere feeling of thanks.",limitation:'Pre-sleep rehearsal and intention can help you prepare, but the claims that the subconscious "attracts" money, health or opportunities, and that thought heals illness, are not supported by research. Never stop medical treatment.'},{id:"expectation-suggestion",title:"Peerdeman et al. · 2016 · Meta-analysis of expectation interventions for pain",url:"https://cris.maastrichtuniversity.nl/en/publications/relieving-patients-pain-with-expectation-interventions-a-meta-ana/",type:"research",finding:"Of 15,955 screened records, 30 studies were included and 27 entered the quantitative analysis. Brief expectation interventions reduced patients’ pain by a moderate amount (Hedges g = 0.61): verbal suggestion (18 studies) g = 0.75, verbal suggestion combined with conditioning (3 studies) g = 0.65, and imagery (6 studies) g = 0.27. Effects were moderate to large for experimental and procedural pain and small for chronic pain.",limitation:"The suggestions were given by researchers or health professionals, not by the patients themselves; self-suggestion was not tested separately. Differences between studies were high (I² = 73%). Only the abstract was read."},{id:"positive-self-statements",title:"Wood, Perunovic & Lee · 2009 · Experiments on positive self-statements",url:"https://journals.sagepub.com/doi/10.1111/j.1467-9280.2009.02370.x",type:"research",finding:"In a survey of 249 students, people reported using positive self-statements often and believing they work. In an experiment with 68 people, participants with low self-esteem who repeated “I am a lovable person” 16 times felt worse than those who did not repeat it, while participants with high self-esteem felt slightly better. A third study with 116 people showed a similar pattern.",limitation:"Participants were Canadian university students, the measures were short-term mood, and a single sentence was tested; the finding does not mean that every positive sentence is harmful."},{id:"self-affirmation-health",title:"Epton et al. · 2015 · Meta-analysis of self-affirmation and health behavior",url:"https://research.manchester.ac.uk/en/publications/the-impact-of-self-affirmation-on-health-behavior-change-a-meta-a/",type:"research",finding:"Across 144 experimental tests, reflecting on important values, qualities or relationships (self-affirmation) produced small but reliable increases in accepting a health message (34 tests, N = 3,433, d = 0.17), in intentions to change (64 tests, N = 5,564, d = 0.14) and in later behavior (46 tests, N = 2,715, d = 0.32).",limitation:"The effects are small and were mostly measured together with a health message; it does not mean that values writing on its own improves mood. Only the abstract was read."},{id:"self-affirmation-review",title:"Cohen & Sherman · 2014 · Review of self-affirmation interventions",url:"https://www.annualreviews.org/content/journals/10.1146/annurev-psych-010213-115137",type:"research",finding:"The review reports that in self-affirmation interventions people usually write about their core personal values, that this reduces the impact of a threat by widening how they see themselves, and that when well timed it has shown benefits in education, health and relationships that sometimes lasted for months.",limitation:"A narrative review with no single average effect; the authors stress that the effect depends on timing and context. Only the abstract was read."},{id:"distanced-self-talk",title:"Kross et al. · 2014 · Experiments on distanced self-talk",url:"https://pubmed.ncbi.nlm.nih.gov/24467424/",type:"research",finding:"In seven studies with 585 people in total, using your own name or “you” instead of “I” while reflecting increased self-distance. In first-impression and public-speaking tasks this group performed better according to independent raters, felt less distress and ruminated less after the speech; they also appraised future stressors more as challenges than as threats. Results did not differ by level of social anxiety.",limitation:"Done in the laboratory, with short tasks and mostly with university students; it is not a clinical treatment and long-term effects were not measured."},{id:"sport-self-talk",title:"Hatzigeorgiadis et al. · 2011 · Meta-analysis of self-talk and sport performance",url:"https://journals.sagepub.com/doi/abs/10.1177/1745691611413136",type:"research",finding:"Across 62 effect sizes from 32 studies, self-talk interventions produced a moderate improvement in performance on sport tasks (ES = 0.48). The effect was larger for fine-skill and newly learned tasks; instructional self-talk (d = 0.55) was more effective than motivational self-talk (d = 0.37), especially on fine tasks (d = 0.83). Programs that included practice of the self-talk beforehand (d = 0.80) were more effective than those that did not (d = 0.37).",limitation:"The studies are limited to sport and motor tasks and most have small samples; an effect of the same size should not be expected for office work or emotional difficulties. The subgroup numbers were taken from a full-text summary."},{id:"positive-fantasies",title:"Kappes & Oettingen · 2011 · Experiments on positive fantasies and energy",url:"https://www.sciencedirect.com/science/article/abs/pii/S002210311100031X",type:"research",finding:"In four experiments, positive fantasies that idealized a desired future were linked with less energy (systolic blood pressure and self-report) than fantasies that questioned that future, negative fantasies or neutral ones. In one experiment this showed up a week later as less success with everyday challenges; the more pressing the need, the larger the drop in energy.",limitation:"Small laboratory experiments; they do not show that daydreaming is always harmful, only the risk of a fantasy with no action and no obstacle. Only the abstract was read."},{id:"sleep-memory-reactivation",title:"Paller, Creery & Schechtman · 2021 · Review of sleep and memory",url:"https://www.annualreviews.org/content/journals/10.1146/annurev-psych-010419-050815",type:"research",finding:"The review describes how memories learned while awake are reactivated during sleep and strengthened, and how this may support problem solving, creativity and emotion regulation. It states that learning new information during sleep is limited to simple associative and perceptual kinds of learning.",limitation:"A narrative review with no numerical effects; it does not test pre-sleep suggestion directly. It also notes that rehearsing worries too much during sleep could be harmful."},{id:"coue-autosuggestion",title:"Émile Coué · Self Mastery Through Conscious Autosuggestion · 1920",url:"https://www.gutenberg.org/ebooks/27203",type:"technique",finding:"Coué teaches that when imagination and willpower are in conflict, imagination wins, so the desired state should be imagined calmly, without forcing. He suggests repeating a general sentence of improvement twenty times on waking and in bed at night, eyes closed, in a low, even voice, using a string with twenty knots to count; he also describes repeating “it is passing” quickly in a moment of discomfort. He says a doctor’s treatment should continue, with suggestion added to it.",limitation:"The book is in the public domain and its evidence is mostly Coué’s own observations. We found no modern controlled study testing the formula directly. The book’s claims about curing organic diseases are not supported by research."},{id:"hill-autosuggestion",title:"Napoleon Hill · Think and Grow Rich · 1937",url:"https://www.naphill.org/shop/books/paperback/think-and-grow-rich-the-1937-edition/",type:"technique",finding:"Hill suggests writing a goal down clearly (what you want, by when and what you will give in return), reading it aloud twice a day, at night before bed and in the morning on waking, and picturing yourself already having reached it with feeling while you read; he presents this as the autosuggestion step.",limitation:"The book is mainly about making money and relies on anecdotes. Writing a goal down and pairing it with a plan can be useful; the claim that thought alone attracts wealth has not been tested."},{id:"hay-mirror-work",title:"Louise Hay · Affirmations and mirror work",url:"https://www.louisehay.com/affirmations/",type:"technique",finding:"Louise Hay popularized saying positive sentences to yourself in a mirror, looking into your own eyes with a kind voice (mirror work), and recommends doing it regularly even though it can feel uncomfortable at first.",limitation:"We found no controlled study testing mirror work. Because sentences you do not believe can backfire for people with low self-esteem, it matters that the sentence is believable; Hay’s views that thoughts cause or cure illness are not supported."},{id:"kross-chatter",title:"Ethan Kross · Chatter · 2021",url:"https://www.penguinrandomhouse.com/books/575664/chatter-by-ethan-kross/",type:"technique",finding:"To turn the inner voice from a critic into a coach, Kross describes addressing yourself by name or as “you”, talking to yourself as you would advise a friend, looking at an event from a distance in time, and tools such as writing or talking with someone you trust.",limitation:"Most of the tools rest on short laboratory experiments; they do not replace professional support for intense, persistent negative thinking."},{id:"gallwey-inner-game",title:"W. Timothy Gallwey · The Inner Game of Tennis · 1974",url:"https://www.penguinrandomhouse.com/books/57757/the-inner-game-of-tennis-50th-anniversary-edition-by-w-timothy-gallwey/",type:"technique",finding:"Gallwey teaches quieting the judging, instruction-giving inner voice (Self 1) so that the body can learn (Self 2), by tying attention to a concrete cue; for example saying “bounce” when the ball hits the ground and “hit” when it meets the racket, and observing the result without judging it as good or bad.",limitation:"The method itself has not been tested separately in meta-analyses; the benefit of short instructional self-talk that directs attention is, however, supported by sport research."},{id:"cohen-belonging",title:"Geoffrey L. Cohen · Belonging · 2022",url:"https://www.geoffreylcohen.com/book",type:"technique",finding:"Cohen describes the values-affirmation exercise, in which a person chooses core values and writes for about 10 minutes about why they matter, as a brief “wise intervention” used before challenging moments.",limitation:"The effects are usually small and depend on timing and context; in some large school trials the results did not replicate."}],ne={id:"suggestion",title:"Self-suggestion",subtitle:"Talk to yourself kindly.",description:"Try well-known suggestion techniques step by step, from Coué and Murphy to Kross and Dispenza, and learn what research says about each of them.",scope:"A course in self-suggestion and self-talk for adults. It is not hypnotherapy, diagnosis or treatment. Suggestion does not replace medication or any treatment you are receiving; do not stop a medication or treatment without talking to your doctor. The claims in some books that suggestion cures illness or attracts money are not supported by research. If the negative sentences inside you are very intense, or you have felt low for a long time, reach out to a mental health professional. If you have thoughts of harming yourself or are in immediate danger, call your local emergency number.",outcome:"A suggestion sentence you can believe, an image, an if–then plan and a personal suggestion card you will review after 7 days.",photo:{id:"1779922811108-245a9403ef44",alt:"Silhouette of a person standing on a hilltop at dawn"},lessons:[{id:"suggestion-1",title:"What suggestion is, and what it is not",minutes:8,goal:"Tell apart what suggestion can change and what it cannot.",reading:["In this course, suggestion means regularly repeating a sentence you have chosen, together with an image and a small action. The French pharmacist Émile Coué spread this idea in the 1920s under the name “conscious autosuggestion”. In his view, wanting something through gritted teeth did not work; calmly imagining the state you wanted had more influence on behavior. Coué had noticed that the harder people forced a state, the stronger its opposite became. So the tone of this course is gentle on purpose.","There is research showing that expectation can shape experience. In a meta-analysis by Peerdeman and colleagues that combined 27 studies, brief verbal suggestions given to patients reduced pain by a moderate amount. But the suggestions came from researchers, and the effect in chronic pain was small. So expectation can open a door, but it does not cure illness or take the place of medication or treatment. Coué himself wanted a doctor’s treatment to continue, with suggestion added on top of it."],deeper:[{heading:"Expectation is real, and it has edges",paragraphs:["The effect in the chart is not imaginary. When a trusted person tells you a procedure will hurt less, many people really do feel less pain. Expectation changes where attention goes, how tense the body gets and how a sensation is read. That is a genuine effect, and it is worth using.","Notice, though, what the studies measured: pain, something you feel and report. They do not show that expectation shrinks a tumor, lowers blood sugar or clears an infection, and Coué’s own claims about curing organic disease have not held up. Keep both halves in mind. Suggestion can change how a hard moment feels and what you do next. It is not a replacement for care."],visual:{kind:"compare",title:"Where suggestion can help, and where it cannot",left:{label:"Can shift",items:["How tense you feel before a hard moment","How strongly a sensation such as pain is felt","Where your attention goes","Which small step you take next"]},right:{label:"Cannot replace",items:["Medication or medical treatment","Diagnosis of a symptom","Other people’s decisions","Practice and preparation"]},note:"The pain studies used suggestions from researchers or clinicians. Self-suggestion was not tested separately."}},{heading:"The loop Coué noticed",paragraphs:["Coué described what he saw in his patients: the more someone strained not to be nervous, the more nervous they became. Many people know this from trying to fall asleep, or trying not to blush. Effort pulls attention onto the very thing you want to get rid of, and that attention feeds it.","Coué treated this as a law. It is better understood as an observation that often fits, not a proven rule. Still, it explains why this course asks you to say your sentence softly and then let it go, rather than pushing it through clenched teeth."],visual:{kind:"cycle",title:"The forcing loop",center:"Trying too hard",nodes:[{label:"Strain",text:"You tell yourself firmly: do not be nervous."},{label:"Watch",text:"You start scanning for signs of nervousness."},{label:"Find",text:"A fast heartbeat or a dry mouth gets your full attention."},{label:"Worry",text:"The signs feel like proof that it is not working."},{label:"Strain harder",text:"You push even more, and the loop starts again."}],note:"Coué’s observation, retold in our words; it is not an experimentally proven law."}}],example:{title:"Leyla, 34, dental hygienist",text:"Before Monday team meetings, Leyla always told herself, firmly, “Do not get flustered this time.” By the time she spoke, her face was hot and she rushed her words. On Sunday she tried the lesson. She wrote the forcing sentence and, next to it, a softer one: “I can take my time.” Before the meeting she let her shoulders drop, took three slow breaths and said the softer sentence quietly, picturing herself pausing before her first point. Her face still warmed a little. But she noticed she paused once, and the words came out in order. Afterward she wrote one line in her phone: “Jaw less tight.” Nothing magical happened; the meeting just felt a notch less like a fight."},practice:["Write, in one sentence, a small situation you would like to change a little this week.","For that situation, write a sentence you say through gritted teeth and a calmer version of it side by side.","Try the technique once, then note one thing you noticed in your body."],reflection:"Which sentence do you say to yourself most often, and how does it affect you?",question:"How is suggestion defined in this course?",options:["A secret command sent to the subconscious that changes everything by itself.","Repeating a chosen sentence, an image and a small action together.","A thinking technique that can replace medication or treatment."],correct:1,feedback:"Suggestion is treated as a combination of sentence, image and action. Expectation can affect experience, but suggestion does not replace treatment and does not guarantee results.",takeaway:"Say it without forcing, imagine it calmly, take one small step.",sources:["expectation-suggestion","coue-autosuggestion"],technique:{name:"Imagine without forcing (conscious autosuggestion)",origin:"Émile Coué · Self Mastery Through Conscious Autosuggestion (1920)",steps:["Choose a small situation you would like to change, for example the tension before a meeting.","Let your shoulders drop and take a few calm breaths; do not try to force anything.","Say the state you want in a short, soft sentence: “I am slowly calming down.”","While you say it, picture that state as a short scene in your mind.","If the thought “I can’t” comes, do not fight it; notice it and gently return to your sentence.","If an uncomfortable moment comes, repeat “it is passing, it is passing” quickly and quietly."],evidence:"Research supports the idea that expectation can affect experiences such as pain, but in those studies the suggestion was mostly given by a health professional. Coué’s method has hardly been tested in modern studies, and the claim that it cures organic diseases is not supported.",sourceId:"coue-autosuggestion"},visual:{kind:"bars",title:"Effect of brief expectation interventions on pain",bars:[{label:"Verbal suggestion (18 studies)",value:.75,display:"g = 0.75"},{label:"Suggestion + conditioning (3 studies)",value:.65,display:"g = 0.65"},{label:"Imagery (6 studies)",value:.27,display:"g = 0.27"}],note:"Pain reduction in patients, Hedges g; overall average 0.61. The suggestions were given by researchers or health professionals, and the effect in chronic pain was small; self-suggestion and this course were not tested separately.",sourceId:"expectation-suggestion"},photo:{id:"1461468611824-46457c0e11fd",alt:"Woman sitting and looking out at the sea"}},{id:"suggestion-2",title:"The Coué formula",minutes:8,goal:"Practice Coué’s daily formula morning and evening, without forcing it.",reading:["Coué’s best-known suggestion was to repeat the sentence “Every day, in every respect, I am getting better and better” twenty times, on waking and in bed at night, with your eyes closed. To count the repetitions he recommended a string with twenty knots; today prayer beads or your fingers work just as well. Saying the sentence in an even voice, like a lullaby and without effort, mattered to him. “In every respect” was kept broad on purpose, so you did not have to think through your problems one by one.","We found no recent, well-designed study that tests this formula directly; the success stories from Coué’s time are mostly anecdotes. Even so, tying the formula to the same moment morning and evening may help the repetition become automatic over time, as in the habit study by Lally and colleagues. Think of this exercise not as a promise of healing but as a ritual that opens and closes the day calmly. If you have pain or symptoms of illness, the formula does not replace a medical assessment."],deeper:[{heading:"Why a plain sentence can still help",paragraphs:["The formula is deliberately dull. It asks nothing of you except a quiet voice and a few minutes, which is exactly why it is easy to repeat. In the habit study by Lally and colleagues, people who repeated a behavior in the same setting found that it gradually took less thought, though how long this took varied widely, and missing a day now and then did not spoil the process.","That gives the formula a realistic job: a small, steady ritual attached to waking up and lying down. What it does to your mood is for you to notice, not for a study to promise. Some people find it soothing; others find it strange at first and settle into it after a few nights."],visual:{kind:"cycle",title:"A ritual anchored to the same moment",center:"Same time, same place",nodes:[{label:"Cue",text:"You wake up, or you lie down at night."},{label:"Routine",text:"Twenty quiet repetitions, counted on knots or beads."},{label:"Moment",text:"A short pause of calm before the day or before sleep."},{label:"Repeat",text:"The same cue tomorrow makes starting easier."}],note:"Repetition in the same context makes a behavior more automatic over time (Lally et al., 2010). The formula’s own effect has not been tested."}},{heading:"Common mistakes",paragraphs:["Most of the ways the formula goes wrong come from treating it as a test. People say it loudly, check after each round whether anything changed, or get annoyed when their mind wanders. Coué suggested the opposite on every point."],visual:{kind:"table",title:"Common mistakes and gentler alternatives",columns:["Mistake","Gentler alternative"],rows:[["Saying it loudly and forcefully","A low, even voice, almost a murmur"],["Checking for results after each round","Let the knots count; review after a week"],["Scolding yourself when your mind wanders","Notice it and pick the sentence up again"],["Using it instead of seeing a doctor","Use it alongside any care you need"]]}}],example:{title:"Sam, 42, bus driver",text:"Sam’s early shifts meant he woke at 4:30 already thinking about traffic. His sister, who prays with beads, lent him a short string of twenty. On Tuesday night he lay down and murmured the formula twenty times, moving one bead each time. He lost count twice and just carried on. On Wednesday morning he did it again before his feet touched the floor. It took about two minutes. He did not feel transformed. What he noticed was that the first thing in his head was a quiet sentence instead of the ring road. He wrote “less rushed start” on a sticky note. By Friday he was doing it without thinking, and on Saturday he forgot entirely, which, he decided, was fine."},practice:["Prepare a string with twenty knots, or set aside twenty beads on a prayer string.","Tonight, when you get into bed, say the formula twenty times in a low, even voice.","Repeat it tomorrow morning before you get up, and after the two sessions write one sentence about how you feel."],reflection:"How did it feel to say the formula without forcing it: soothing, strange, boring?",question:"Which of these fits the attitude Coué recommended for his formula?",options:["Saying the sentence as forcefully as possible, through gritted teeth.","Saying the sentence in a relaxed, low voice and leaving the counting to the string or beads.","Checking after every repetition whether something has changed."],correct:1,feedback:"Coué believed that more effort creates the opposite effect, so he recommended relaxed, even repetition. That was his observation; the formula’s effect has hardly been tested in modern studies.",takeaway:"A short sentence, a calm voice, the same moment every day.",sources:["coue-autosuggestion","habits"],technique:{name:"The Coué formula (twenty repetitions)",origin:"Émile Coué · Self Mastery Through Conscious Autosuggestion (1920)",steps:["Prepare a string with twenty knots, or set aside twenty beads on a prayer string.","In the morning when you wake, before getting up, close your eyes and lie comfortably.","Say “Every day, in every respect, I am getting better and better” in a low, even voice.","Move one knot or bead with each repetition; leave the counting to the string.","Do not try hard to think about the meaning; let the sentence flow like a lullaby.","Do the same at night when you get into bed, before you fall asleep."],evidence:"Very few modern controlled studies test the formula itself; the evidence is mostly accounts from Coué’s time. It can be tried as a calming ritual, but the claim that it cures illness is not supported.",sourceId:"coue-autosuggestion"},visual:{kind:"compare",title:"Forcing it, or Coué’s way?",left:{label:"Forcing it",items:["Saying it loudly through gritted teeth","Checking the result after every repetition","Getting angry when your mind wanders"]},right:{label:"Coué’s way",items:["A relaxed, low, even voice","Leaving the counting to a string or beads","Gently returning to the sentence when your mind wanders"]},note:"In Coué’s view, the harder you try, the stronger the opposite effect; this is his observation, not an experimentally proven law."},photo:{id:"1762328490563-9b9c300fba3e",alt:"Person holding a string of beads"}},{id:"suggestion-3",title:"Build sentences you can believe",minutes:9,goal:"Turn forced affirmations into believable sentences that describe a process.",reading:["In experiments by Wood, Perunovic and Lee in 2009, participants repeated the sentence “I am a lovable person” 16 times within a few minutes. People with high self-esteem felt slightly better, but people with low self-esteem felt worse than those who had not repeated it at all. One likely explanation: when a sentence is too far from what you believe, your mind argues with it, and the argument is what stays with you. So the boldest sentence may not be the most effective one.","A more believable route is to build sentences about process and learning: “I am learning”, “I can take one step today”. Another route is to remind yourself of your values instead of passing judgment on yourself. In the self-affirmation studies reviewed by Cohen and Sherman, people write briefly about a value that matters to them. In a meta-analysis by Epton and colleagues combining 144 tests, this kind of writing produced small but reliable increases in accepting health messages and in later behavior."],deeper:[{heading:"Why an unbelievable sentence can backfire",paragraphs:["Popular advice often says to repeat a positive statement until you believe it. The Wood experiments suggest a catch. For people who already felt good about themselves, the sentence fit and did a little good. For people who did not, each repetition seemed to invite a quiet “that is not true”, and the gap between the sentence and their own view became more noticeable.","This was one sentence, tested on students over a few minutes, so it does not show that all affirmations harm. It does suggest a simple check: if a sentence makes you wince, shrink it until it feels possible."],visual:{kind:"cycle",title:"How a sentence you do not believe can backfire",center:"The gap",nodes:[{label:"Bold sentence",text:"“I am completely confident.”"},{label:"Inner objection",text:"A voice answers: that is not true."},{label:"Counter-evidence",text:"Memories of the opposite come to mind."},{label:"Worse mood",text:"The gap feels bigger than before."}],note:"A likely explanation offered by the researchers, not something they measured step by step. The effect appeared in people with low self-esteem."}},{heading:"What the research on values says",paragraphs:["Self-affirmation is different from saying nice things about yourself. You do not claim a trait you may not feel. You write about something you care about, such as family, honesty or faith, and why it matters. The idea is that a threat, like criticism or a scary health message, then takes up less of your whole picture of yourself.","The effects are modest. Across many experiments, values writing made people a little more open to health messages and, a bit more clearly, more likely to change their behavior afterward. Timing mattered, and some large trials in schools did not replicate earlier results."],visual:{kind:"bars",title:"Self-affirmation and health behavior",bars:[{label:"Accepting the message (34 tests)",value:.17,display:"d = 0.17"},{label:"Intention to change (64 tests)",value:.14,display:"d = 0.14"},{label:"Later behavior (46 tests)",value:.32,display:"d = 0.32"}],note:"Epton et al. (2015), 144 experimental tests. Small effects, mostly measured together with a health message; values writing on its own and this course were not tested.",sourceId:"self-affirmation-health"}}],example:{title:"Priya, 27, junior accountant",text:"Priya had a sticky note on her mirror that said “I am brilliant at my job.” Every morning she read it and felt a small sting, because last week she had made an error in a report. On Thursday she rated how much she believed it: three out of ten. She rewrote it: “I am learning this job, and I check my work.” That one was a seven. She also spent ten minutes writing about honesty, the value she cares about most, and a recent moment when she had owned a mistake to her manager. The next morning the new note did not make her feel brilliant. It just did not sting. Before a review meeting, she reread her paragraph on honesty and walked in a little steadier."},practice:["Write down a positive sentence you often say to yourself, or would like to.","Rate from 0 to 10 how much you believe it; if it is under 5, rewrite it in the language of process or learning.","Do the 10-minute values writing and add your most important value to your card in one word."],reflection:"Which sentence makes you think, “yes, that could be true”?",question:"Based on Wood and colleagues’ findings, which is the wiser choice?",options:["Repeating the boldest sentence more often, even if you do not believe it.","Choosing a sentence you can believe that describes a process.","Never saying any positive sentence to yourself."],correct:1,feedback:"Sentences people did not believe could backfire, especially for those with low self-esteem. Believable, process-focused sentences and remembering your values are a safer place to start.",takeaway:"Your sentence does not have to be bold; it has to be believable.",sources:["positive-self-statements","self-affirmation-review","self-affirmation-health","cohen-belonging"],technique:{name:"Remember your values (values writing)",origin:"Geoffrey L. Cohen · Belonging (2022); Cohen and Sherman’s self-affirmation research",steps:["Make a list of values that matter to you: family, honesty, curiosity, faith, helping others.","Choose the one or two values that matter most to you today.","Write freely for about 10 minutes about why this value is important to you.","Add a small recent moment when you lived this value.","Before a difficult conversation, exam or piece of feedback, reread what you wrote."],evidence:"A meta-analysis showed that values writing reduces defensiveness and supports health behavior by a small but reliable amount. The effects are small, vary with timing and context, and have not replicated in every trial.",sourceId:"cohen-belonging"},visual:{kind:"table",title:"A forced sentence, or a believable one?",columns:["Forced sentence","Believable version"],rows:[["I am perfect.","I can make mistakes and still keep learning."],["I never feel anxious.","I feel anxious; I can still say my first sentence."],["Everyone loves me.","Some people care about me; today I can message one of them."],["I am rich and successful.","This week I look at my budget once and take one step."]],note:"In Wood and colleagues’ experiments, repeating “I am a lovable person” worsened mood for people with low self-esteem. The sentences on the right were not tested in that study; the aim is to trigger less inner objection."},photo:{id:"1616628188467-8fb29f49bbe8",alt:"Hand writing a note on white paper"}},{id:"suggestion-4",title:"Call yourself by name",minutes:8,goal:"Before a hard moment, gain some distance by addressing yourself by name or as “you”.",reading:["Kross and colleagues ran seven studies with 585 people in total. People who used their own name or “you” instead of “I” while thinking about a difficult situation could look at it more from the outside. After a short preparation, this group gave a public speech that independent raters judged as better; they felt less distress and went over the speech less afterward. They also started to see future challenges more as tests to meet than as threats.","This small change in language may make it easier to turn toward yourself the calm view you have when advising a friend. What matters is that the tone is kind, not harsh; scolding yourself by name is not the point of the technique. The studies were done in a lab, with short tasks and mostly with students; this is not a treatment. If your inner voice has been very harsh and unstoppable for weeks, talking to a mental health professional is a good step."],deeper:[{heading:"Why a name creates distance",paragraphs:["When you think “I”, you are inside the situation, close to every sensation and fear. When you use your name, your mind borrows the grammar you use for other people. Most of us are wiser about a friend’s problem than about our own, because we can see the whole of it. The name is a quick way to step into that friend’s chair.","Kross describes this and several related tools in his book Chatter: imagining how you will see the event in a year, writing about it, or talking it through with someone you trust. They share one move, a step back, and each suits a different moment."],visual:{kind:"steps",title:"A two-minute distanced check-in",steps:[{label:"Name",text:"Address yourself: “Ali, what is going on right now?”"},{label:"Describe",text:"Say what is happening using “you”, not “I”."},{label:"Advise",text:"Say what you would tell a friend in the same spot."},{label:"Zoom out",text:"Ask how this will look to you in a year."},{label:"Next step",text:"End with one concrete action for the next minute."}],note:"Adapted from Ethan Kross’s tools. The laboratory studies tested using a name or “you”; the other steps were not tested together."}},{heading:"Kind, not harsh",paragraphs:["Distance helps most when it comes with warmth. Saying “Ali, you idiot” uses your name but brings the critic along with it. A review of dozens of trials found that self-compassion practices, meaning treating yourself with the kindness you would offer a friend, reduced stress and anxiety by small to moderate amounts in the short term, although many of the trials had weaknesses.","A useful test is simple: would you say this sentence, in this tone, to someone you love? If not, change the tone before you change the words."]}],example:{title:"Marcus, 38, nurse",text:"Marcus had to give a short handover to a new charge nurse he found intimidating. Walking to the ward, his head was full of “I’ll mess this up, I always forget something.” He stopped by the supply room for two minutes and tried the lesson under his breath: “Marcus, you’re nervous because you want to get this right. You’ve done a hundred handovers.” Then he asked what he would tell a younger colleague: “Start with the sickest patient and go in order.” He said that to himself too. The handover was not perfect; he forgot one lab result and added it at the end. But he noticed he had not spent the next hour replaying it, which usually happened."},practice:["Pick a moment this week that will be hard for you, and note its time.","Before that moment, take two minutes to describe the situation to yourself, calling yourself by name.","Then say to yourself the supportive sentence you would say to a friend in the same situation."],reflection:"How did your tone change when you called yourself by name?",question:"In Kross’s 2014 experiments, which kind of self-talk was more helpful under social stress?",options:["Calling yourself by name or “you”.","Thinking about the situation at length, using only “I”.","Motivating yourself with harsh criticism."],correct:0,feedback:"Using your name or “you” increased distance; this group felt less distress and performed better. The findings come from short laboratory tasks.",takeaway:"Talk to yourself by name, the way you would talk to a friend.",sources:["distanced-self-talk","kross-chatter","self-compassion"],technique:{name:"Distanced self-talk",origin:"Ethan Kross · Chatter (2021)",steps:["Before a hard moment, take two minutes: a presentation, an interview or a difficult conversation.","Address yourself silently or in a whisper by name: “Emma, what is happening right now?”","Describe the situation using “you” instead of “I”: “You’re excited because this matters to you.”","Say to yourself what you would say to a friend in the same situation.","If it helps, ask: “How will you see this a year from now?”","End with a concrete next step: “Say your first sentence slowly.”"],evidence:"In seven experiments, talking to yourself by name or as “you” was linked with less distress and better performance under social stress. The studies were done in the lab, mostly with students; it is not a clinical treatment.",sourceId:"kross-chatter"},visual:{kind:"compare",title:"“I”, or your name?",left:{label:"First person",items:["I can’t do this.","Why is it always me?","I’m definitely going to embarrass myself."]},right:{label:"Your name, or “you”",items:["Mike, this is hard, but you prepared.","You have got through this before.","Say your first sentence slowly."]},note:"The aim is not to scold yourself, but to speak with distance and kindness, as you would to a friend."},photo:{id:"1641907173006-6b8930ae1191",alt:"Woman looking up at the sky, lost in thought"}},{id:"suggestion-5",title:"Give yourself instructions",minutes:9,goal:"Choose short instructional and motivational cue words for a task and try them.",reading:["Hatzigeorgiadis and colleagues combined 32 studies testing self-talk in sport and found a moderate improvement in performance. There are two kinds of self-talk: instructional self-talk tells you what to do (“elbow up”, “watch the ball”), while motivational self-talk gives you courage (“come on”, “you can do it”). Instructional self-talk was especially strong for fine, attention-demanding and newly learned tasks. Programs that practiced the self-talk a few times beforehand were also more effective.","You can carry this idea into daily life: “draft first” when writing, “slow and clear” when speaking, “taste it” when cooking. Keep the cue short, one to three words, and make it describe what you will do now, not what kind of person you are. These numbers come from sport tasks; you should not expect an effect of the same size for office work or emotional difficulties. Still, it is an easy and cheap tool to try."],deeper:[{heading:"Instructional or motivational?",paragraphs:["Both kinds have a place. Instructional cues point attention at one detail, which helps when a task is new or delicate and your mind tends to wander or tighten. Motivational cues help more with effort and staying power, such as the last stretch of a run or the tenth email of the afternoon.","A handy rule: when you are learning or need precision, choose an instruction; when you know what to do but are running low on drive, choose encouragement. The cue should always be short enough to say in one breath."],visual:{kind:"table",title:"Cue words for everyday tasks",columns:["Task","Instructional cue","Motivational cue"],rows:[["Writing a report","Draft first","Keep going"],["Speaking in a meeting","Slow and clear","You’re ready"],["Learning to drive","Mirror, signal","Steady"],["Cooking a new recipe","Taste it","Enjoy it"]],note:"Examples only; they were not tested in the meta-analysis, which covered sport and motor tasks."}},{heading:"How Gallwey does it",paragraphs:["Tim Gallwey, a tennis coach, noticed that players often played worse when they lectured themselves. He called the judging voice Self 1 and the body that actually learns Self 2. His answer was not more instruction but simpler attention: saying “bounce” when the ball lands and “hit” when it meets the racket, and watching what happens without calling it good or bad.","Research has not tested his method on its own. It fits, though, with what the meta-analysis found about short cues that direct attention, and it offers a kind way to handle mistakes: instead of a verdict, pick one thing to watch next time."],visual:{kind:"compare",title:"Self 1 or a simple cue?",left:{label:"Judging voice (Self 1)",items:["“That was terrible.”","A list of five corrections at once","Tension and overthinking"]},right:{label:"Simple cue",items:["One word tied to one moment","Watching what happens","One thing to notice next time"]},note:"Gallwey’s description, in our words. The method itself has not been tested separately in meta-analyses."}},{heading:"Practice the cue before you need it",paragraphs:["One of the clearest patterns in the meta-analysis was that programs where people practiced their self-talk beforehand worked better than those where they did not. A cue works best when it is already familiar at the moment you need it. Try it in an easy round first, then take it into the harder one."]}],example:{title:"Ana, 45, school administrator",text:"Ana was learning to use a new spreadsheet system at work and kept making small errors when entering data, then scolding herself. She chose two cues. Instructional: “check the column”. Motivational: “one row at a time”. On Monday she practiced them on ten easy rows before the real task, saying “check the column” each time before she typed. Then she did the real batch. She still made two errors in fifty rows, fewer than usual, and when she spotted them she did not call herself careless. She simply wrote in her notebook: “watch dates”. On Wednesday she added “watch dates” as her new cue. It was a small thing, but the afternoon felt less like being graded."},practice:["Choose a task this week that you find hard to learn or to do well.","Write one instructional and one motivational cue word for that task.","While doing the task, repeat the cue in a short, calm voice, and note the result without judging it."],reflection:"Which cue actually drew your attention into the task?",question:"According to the meta-analysis, when did instructional self-talk work especially well?",options:["In tasks that need fine skill and attention.","Only in very well-learned, automatic tasks.","On the first attempt only, with no practice at all."],correct:0,feedback:"Instructional self-talk was especially effective for fine and new skills, and programs that practiced beforehand showed larger effects.",takeaway:"Tell yourself what to do now, not who you are.",sources:["sport-self-talk","gallwey-inner-game"],technique:{name:"Watch and say (“bounce–hit”)",origin:"W. Timothy Gallwey · The Inner Game of Tennis (1974)",steps:["Choose a concrete signal in your task to anchor your attention: the ball’s bounce, your breath, the tip of your pen.","When that moment comes, say a short word silently; in tennis, “bounce” when the ball lands and “hit” when it meets the racket.","Stop judging the result as good or bad; just watch what happens.","If you make a mistake, instead of scolding yourself, choose one word for what to watch on the next attempt.","After a few minutes, notice how your body adjusts on its own."],evidence:"Gallwey’s method has not been tested separately in meta-analyses; however, short instructional self-talk that directs attention has been shown to improve performance, especially for fine and new skills. The effects come from sport tasks.",sourceId:"gallwey-inner-game"},visual:{kind:"bars",title:"Effect of self-talk on sport performance",bars:[{label:"Average across all studies",value:.48,display:"ES = 0.48"},{label:"Instructional self-talk",value:.55,display:"d = 0.55"},{label:"Motivational self-talk",value:.37,display:"d = 0.37"},{label:"Programs with practice beforehand",value:.8,display:"d = 0.80"},{label:"Programs without practice",value:.37,display:"d = 0.37"}],note:"32 studies, 62 effect sizes; sport and motor tasks. The effect of instructional self-talk on fine tasks was 0.83. These are averages, they cannot be carried over directly to everyday tasks, and this course was not tested separately.",sourceId:"sport-self-talk"},photo:{id:"1523497804259-88c4c134ca90",alt:"Athlete getting ready to run on a track"}},{id:"suggestion-6",title:"Suggestion before sleep",minutes:10,goal:"Practice Murphy’s pre-sleep technique together with an obstacle and a plan.",reading:["In his 1963 book, Joseph Murphy describes the drowsy moment before sleep as the time most open to suggestion. He suggests shortening your wish into a brief sentence and repeating it like a lullaby, seeing the result in a short scene as if it were happening now, for example hearing a friend congratulate you, and ending the scene with heartfelt thanks. In 1937 Napoleon Hill had suggested writing a goal down clearly and reading it aloud twice a day, at night and in the morning. Both stress feeling and repetition.","Research supports part of this: a meta-analysis of 37 studies found that rehearsing in your mind makes a small but real contribution to performance. A review by Paller and colleagues shows that sleep strengthens what you learned during the day, while learning new information in sleep stays very limited. In Kappes and Oettingen’s experiments, only imagining the good outcome lowered energy; so we add the real obstacle and an if–then plan to the scene. Claims that the subconscious attracts money or health, or that thought cures illness, are not supported."],deeper:[{heading:"What sleep does, and what it does not",paragraphs:["Sleep is not idle time for memory. According to the review by Paller and colleagues, memories from the day are replayed and strengthened overnight, which may help with problem solving and with how emotions settle. That gives a short, calm rehearsal before bed a sensible role: it is one of the last things you practiced.","What sleep does not do is take orders. Learning genuinely new material while asleep is limited to very simple kinds, and the review also warns that going over worries again and again may do harm. The subconscious in Murphy’s book works like an obedient genie. Research describes something more ordinary: habits, attention and memory that respond to practice."],visual:{kind:"compare",title:"Sleep and suggestion: what fits the evidence",left:{label:"Fits the evidence",items:["Rehearsing a first step before bed","Calm repetition of a short sentence","Letting sleep consolidate what you practiced"]},right:{label:"Not supported",items:["The subconscious bringing money or health","Learning complex new skills while asleep","Thought curing illness"]},note:"Based on the review by Paller, Creery and Schechtman (2021), which did not test pre-sleep suggestion directly."}},{heading:"Why add the obstacle",paragraphs:["A pleasant fantasy can feel like progress. In Kappes and Oettingen’s experiments, people who pictured an idealized future had less energy afterward, and in one study they got less done in the following week. The mind seems to relax as if the goal were already reached.","The fix is not to stop dreaming but to add two steps. After you see the result, name the main thing inside you that could get in the way, and link it to an if–then plan. Across 21 studies, this combination showed a small-to-medium average effect on reaching goals."],visual:{kind:"steps",title:"From an evening scene to a morning plan",steps:[{label:"Wish",text:"A short sentence, repeated slowly as you get drowsy."},{label:"Scene",text:"A brief picture of the result, such as a friend congratulating you."},{label:"Obstacle",text:"In the morning: what in you could get in the way?"},{label:"Plan",text:"“If … happens, then I will …”"}],note:"Pairing a desired future with the obstacle and an if–then plan showed an average effect of g = 0.336 across 21 studies (Wang, Wang & Gai, 2021)."}},{heading:"If your mind turns to worry",paragraphs:["Some nights the sentence slides into a list of everything that could go wrong. That is not a failure of the technique. Leave the scene, jot the worry on a notepad by the bed if you need to, and return to slow breathing. Sleep matters more than the exercise. If worry keeps you awake most nights, that is worth talking through with a doctor."]}],example:{title:"Tomás, 33, junior architect",text:"Tomás had a design review on Friday and kept rehearsing disasters at night. On Wednesday he tried the lesson. He shortened his wish to “The review went smoothly” and wrote it on a card. In bed, as he got drowsy, he repeated it slowly and pictured his colleague Ines saying, “Nice job on the site plan.” He fell asleep before the scene ended. On Thursday morning he wrote the real obstacle: “I rush when someone questions me.” And the plan: “If someone challenges a detail, then I will pause, repeat the question and answer the part I know.” On Friday one partner did challenge the parking layout. Tomás paused, a little awkwardly, and answered. The review was not flawless, but it was not the disaster he had rehearsed."},practice:["Tonight, shorten your wish into a brief sentence of five or six words and write it on paper.","In bed, as you get sleepy, repeat the sentence slowly and briefly picture a friend congratulating you.","In the morning, write in one line the real obstacle on the way to that result and a plan: “If … happens, then I will …”."],reflection:"What did the scene you built before sleep remind you of in the morning?",question:"Which approach to pre-sleep suggestion fits the research best?",options:["Imagining the result and also adding the real obstacle and an if–then plan.","Waiting for the subconscious to attract money and health by itself during sleep.","Only imagining the good outcome and making no plan at all."],correct:0,feedback:"Mental rehearsal can make a small contribution, but a purely positive fantasy can lower energy. Combining the dream with an obstacle and a plan fits the research better.",takeaway:"At night, see the result; in the morning, write the obstacle and the first step.",sources:["murphy-subconscious","hill-autosuggestion","mental-practice","sleep-memory-reactivation","positive-fantasies","mcii","if-then-plans"],technique:{name:"Pre-sleep suggestion",origin:"Joseph Murphy · The Power of Your Subconscious Mind (1963)",steps:["Lie down in bed, relax your body and wait for the drowsiness sleep brings.","Shorten your wish to a brief sentence of a few words, such as “My presentation went smoothly”.","Repeat this sentence slowly, over and over, like a lullaby.","See the result in a short scene as if it were happening now: a friend congratulates you, and you hear their voice.","Add a feeling of heartfelt thanks to the scene and let yourself drift into sleep."],evidence:"A short rehearsal and intention before sleep can help you prepare; mental rehearsal makes a small contribution to performance. Learning new information during sleep is limited; claims that the subconscious attracts money or health and cures illness are not supported, and purely positive fantasy can lower energy.",sourceId:"murphy-subconscious"},visual:{kind:"table",title:"Teachings and research",columns:["Approach","What it suggests","What research says"],rows:[["Murphy: before sleep","A short sentence when drowsy, a finished scene, thanks","Rehearsal can help you prepare; learning new things in sleep is limited"],["Hill: written goal","Write the goal, read it aloud morning and night","Clarifying a goal can help; the claim that it attracts wealth is untested"],["Positive fantasy only","Imagining the good result again and again","Lowered energy in experiments"],["Dream + obstacle + plan","See the result, name the obstacle, make an if–then plan","Small-to-medium effect in a meta-analysis (g = 0.336)"]],note:"This table is not meant to belittle the teachings, but to show which parts are supported by evidence. Suggestion does not replace treatment."},photo:{id:"1757796859729-270d1e3ad4d5",alt:"Open book on a nightstand under a lit lamp"}},{id:"suggestion-7",title:"Your own suggestion card",minutes:10,goal:"Gather your sentence, image, plan and time on one card, and review it after 7 days.",reading:["Now we bring together what you have learned: a sentence you can believe, calling yourself by name, a short cue word, an image of your first step and an if–then plan. In Breaking the Habit of Being Yourself, Joe Dispenza suggests noticing an old habit during a morning meditation, telling yourself “change” when you catch it during the day, and rehearsing in your mind, with gratitude, the state you want to be in. Research supports a small but real contribution from mental rehearsal. Claims that thought changes events through a quantum field or cures illness are not supported.","You can add the mirror work popularized by Louise Hay as an option: looking into your own eyes in a mirror and saying your sentence in a kind voice. We found no controlled study testing it; it is normal for it to feel strange at first. But if the inner objection grows while you say it, make your sentence more believable, as in lesson 3, or choose to read it from paper. After seven days, review your card; meta-analyses show that tracking progress supports reaching goals."],deeper:[{heading:"How the pieces fit together",paragraphs:["Each part of the card does a different job. The sentence sets the tone, the image shows the first move, the plan handles the moment things get hard, and the time makes it a habit rather than a mood. On its own, each is a small tool. Together they form a loop you can run for a week and then adjust.","Research backs some links in this loop more than others: if–then plans and progress tracking have the clearest support, mental rehearsal a small effect, and the sentence itself mostly works by not getting in your way."],visual:{kind:"cycle",title:"The suggestion card as a weekly loop",center:"Your card",nodes:[{label:"Sentence",text:"A believable line, maybe starting with your name."},{label:"Image",text:"A short scene of your first step."},{label:"Plan",text:"If the obstacle shows up, then you know what to do."},{label:"Action",text:"The small step you actually take that day."},{label:"Review",text:"After 7 days: keep, change or shrink."}],note:"The loop combines tools from the earlier lessons; the card as a whole has not been tested as one method."}},{heading:"Mirror work, gently",paragraphs:["Louise Hay made mirror work popular: saying a kind sentence to your own reflection. For some people it is moving; for others it is excruciating. Both are normal reactions, and there is no controlled research telling us which people it helps.","Given what the Wood experiments found, use the mirror as a test rather than a duty. If the sentence feels a bit more true when you look yourself in the eye, keep it. If it sets off a stronger “no”, go back to paper, or soften the sentence first."]},{heading:"Reviewing without blame",paragraphs:["A review is a tuning session, not an exam. Studies that increased how often people checked their progress found a moderate average benefit for reaching goals, and recording progress on paper or on screen helped more than keeping it in your head. Write your answers down, even briefly."],visual:{kind:"table",title:"Questions for your 7-day review",columns:["Question","If yes","If no"],rows:[["Did I read the card most days?","Keep the time as it is","Tie it to a firmer cue, like brushing your teeth"],["Did I believe the sentence?","Keep it","Make it smaller and more about process"],["Did the plan fire when the obstacle came?","Keep the plan","Make the “if” more specific"]],note:"Tracking progress supported goal attainment on average (d = 0.40) in Harkin et al. (2016); these particular questions were not tested."}}],example:{title:"Hana, 51, pharmacy technician",text:"Hana wanted to start walking in the evenings but always ended up on the sofa. On an index card she wrote, on the front: “Hana, you can do ten minutes.” Underneath, an image: lacing her shoes by the door. On the back: “If I sit down after dinner, then I will stand up and put my shoes on before deciding.” And the time: 7 p.m., read after clearing the table. She tried the mirror once and felt silly, so she read the card from paper instead. Over seven days she walked four times, twice for just ten minutes. At her review she kept the sentence, changed the image to setting her shoes out before dinner, and moved the reading time earlier. Four out of seven was more than zero."},practice:["On the front of a card, write your believable sentence and a short image of your first step.","On the back, write an if–then plan and the time you will read the card.","Set a reminder in your calendar for 7 days from now, and review your card on that day."],reflection:"After seven days, what on your card would you keep exactly as it is, and what would you change?",question:"When you review your suggestion card after seven days, which approach is most useful?",options:["Blaming yourself if nothing has changed.","Looking at what worked and adjusting the sentence, the image or the plan.","Starting to say a bolder sentence more loudly."],correct:1,feedback:"A review is not an exam but a time to tune. Keep what worked, and make what felt forced more believable and smaller.",takeaway:"One sentence, one image, one plan, one time: then review.",sources:["dispenza-breaking-habit","hay-mirror-work","mental-practice","positive-self-statements","if-then-plans","monitoring"],technique:{name:"Morning rehearsal",origin:"Joe Dispenza · Breaking the Habit of Being Yourself (2012)",steps:["In the morning, before the day begins, sit somewhere quiet for 10 minutes and relax with a few slow breaths.","Notice an old habit you want to let go of: which thought and feeling does it start with?","Describe the state you want to be in: how does that version of you think, act and feel?","Rehearse step by step in your mind one moment today when you will live in that state.","End the rehearsal with a feeling of gratitude, as if that moment had already happened.","During the day, when you catch the old state, briefly tell yourself “change” and return to the first step of your rehearsal."],evidence:"Meta-analyses show that mental rehearsal improves performance by a small but meaningful amount. Claims that thought changes events by acting on a quantum field, or cures illness, are not supported.",sourceId:"dispenza-breaking-habit"},visual:{kind:"steps",title:"Your suggestion card",steps:[{label:"Sentence",text:"One believable sentence about a process; it can start with your name."},{label:"Image",text:"A short scene of you taking the first step."},{label:"Plan",text:"“If … happens, then I will …”"},{label:"Time",text:"On waking or at bedtime, at the same time every day."},{label:"Review",text:"After 7 days: what worked, and what will you change?"}],note:"You can say your sentence while looking in a mirror if you like; if that feels uncomfortable, reading it from paper is enough. The card is not a treatment."},photo:{id:"1484480974693-6ca0a78fb36b",alt:"Hand writing a checklist in a notebook"}}]},te=Object.freeze(Object.defineProperty({__proto__:null,COURSE:ne,SOURCES:ie},Symbol.toStringTag,{value:"Module"})),re=[{id:"identity-dispenza-habit",title:"Dr. Joe Dispenza · Breaking the Habit of Being Yourself (Hay House, 2012)",url:"https://www.penguinrandomhouse.com/books/603255/breaking-the-habit-of-being-yourself-by-dr-joe-dispenza/",type:"technique",finding:"Dispenza presents a four-week meditation program: settle into the body and the present moment, recognize and admit the old pattern of thoughts, feelings and reactions you want to change, let it go, watch for it during the day and interrupt it, and rehearse the new self you want to become, including how that self feels.",limitation:"Becoming aware of habits and rehearsing new behavior fit well with research. The publisher’s description also promises that readers can reprogram their biology and genetics using principles from quantum physics; those claims are not supported by scientific evidence. The publisher page was read; the program itself has not been tested in controlled trials."},{id:"identity-dispenza-supernatural",title:"Dr. Joe Dispenza · Becoming Supernatural (Hay House, 2017)",url:"https://books.google.com/books/about/Becoming_Supernatural.html?id=NWL6DwAAQBAJ",type:"technique",finding:"The book builds on the earlier program with further meditations, including walking meditations, and adds ideas about tuning in to a “quantum field of infinite possibilities”, heart coherence for healing, the pineal gland as a gateway to mystical experience and balancing the body’s energy centers.",limitation:"Only the rehearsal and attention parts of these meditations overlap with research. The claims about a quantum field, healing, the pineal gland and energy centers are not supported by science. The publisher’s description on Google Books was read."},{id:"identity-dispenza-change",title:"Dr. Joe Dispenza · The Art of Change (blog, 2019)",url:"https://drjoedispenza.com/dr-joes-blog/the-art-of-change",type:"technique",finding:"Dispenza describes change as moving from thinking to doing to being: becoming aware of automatic habits of mind and reaction, mentally reviewing the old pattern so it fires less, “un-memorizing” emotional states that have become part of the personality and conditioning the body to a new emotion through repetition.",limitation:"The post also states that the quantum field responds to who we are, which is not supported by science. Its explanations of brain wiring are simplified. The full post was read."},{id:"identity-dispenza-new-self",title:"Dr. Joe Dispenza · The Habit of Your New Self (blog, 2018)",url:"https://drjoedispenza.com/dr-joes-blog/the-habit-of-your-new-self",type:"technique",finding:"Dispenza argues that lasting change means leaving familiar thoughts, behaviors and emotions behind, and practicing the new self through the day, not only in meditation: walking, sitting and choosing the way your future self would, and teaching the body to feel that future self’s emotions.",limitation:"A personal blog post, not research. The idea of repeated practice fits habit research; the neural explanations are simplified. The full post was read."},{id:"identity-clear-identity",title:"James Clear · Identity-based habits (excerpt from Atomic Habits, 2018)",url:"https://jamesclear.com/identity-based-habits",type:"technique",finding:"Clear describes three layers of change — outcomes, processes and identity — and a two-step approach: decide what kind of person you want to be, then prove it to yourself with small wins, such as starting a movement habit with only a few dozen steps.",limitation:"A practical synthesis by a writer, not a tested program. The author’s own page was read."},{id:"identity-clear-votes",title:"James Clear · How to change your beliefs and stick to your goals (identity votes, Atomic Habits)",url:"https://jamesclear.com/identity-votes",type:"technique",finding:"Clear compares each action to a vote for the kind of person you want to become: no single vote decides anything, you need a majority rather than every vote, and small habits pile up evidence for a new identity over time.",limitation:"A helpful metaphor that fits self-perception research, but it has not been tested as a method. The author’s own page was read."},{id:"identity-clear-stacking",title:"James Clear · Habit stacking (Atomic Habits, 2018; after BJ Fogg)",url:"https://jamesclear.com/habit-stacking",type:"technique",finding:"Clear’s habit stacking links a new habit to a current one with the formula “After/Before [current habit], I will [new habit]”. He credits the method to BJ Fogg’s Tiny Habits (where it is called anchoring) and advises choosing a specific cue that happens as often as the new habit should.",limitation:"Habit stacking itself has not been tested as a named method; it rests on research on context cues and if-then plans. The author’s own page was read."},{id:"identity-clear-environment",title:"James Clear · Environment design (jamesclear.com)",url:"https://jamesclear.com/environment-design",type:"technique",finding:"Clear recommends shaping your surroundings so good habits take less effort (lay out what you need, keep it visible) and unwanted habits take more (move the cue out of sight), noting that people tend to stick with default options.",limitation:"Practical advice drawing on behavioral science; the specific tips have not been tested as a package. The author’s own page was read."},{id:"identity-clear-second-mistake",title:"James Clear · Avoid the second mistake (jamesclear.com, 2014)",url:"https://jamesclear.com/second-mistake",type:"technique",finding:"Clear argues that one missed day is an outlier while two in a row can start a new pattern, and suggests focusing on getting back on track rather than making up for the miss, scheduling habits, and removing whatever caused the slip.",limitation:"A rule of thumb, not a tested method. The author’s own page was read."},{id:"identity-oyserman",title:"Daphna Oyserman · Identity-based motivation (USC research overview)",url:"https://dornsife.usc.edu/daphna-oyserman/identity-and-self/",type:"research",finding:"Identity-based motivation theory holds that which identities come to mind depends on context, that people prefer actions that feel in line with an identity that is active in the moment, and that the same difficulty can be read as a sign of importance (“this matters to me”), of impossibility (“not for people like me”) or of improvement (hard times build character).",limitation:"A researcher’s own summary of a research program; the studies behind it focus mostly on students and school outcomes. The overview page was read."},{id:"identity-pathways",title:"Oyserman, O’Donnell, Sorensen & Wingert · 2021 · Pathways-to-Success classroom intervention",url:"https://files.eric.ed.gov/fulltext/ED618114.pdf",type:"research",finding:"In 1,142 eighth-graders in 10 high-poverty Chicago schools, a 12-session teacher-led program based on identity-based motivation raised identity-based motivation and improved academic outcomes when teachers delivered it with higher fidelity; moving from 60% to 80% fidelity went with a 0.50 standard-deviation difference in academic performance.",limitation:"A school program for teenagers, analyzed by fidelity of delivery; it does not show that an adult self-help exercise works the same way. The abstract and summary were read."},{id:"identity-bem",title:"Bem · 1972 · Self-perception theory",url:"https://www.sciencedirect.com/science/chapter/bookseries/pii/S0065260108600246",type:"research",finding:"Bem proposed that people come to know their own attitudes and emotions partly by inferring them from their own behavior and its circumstances, much as an outside observer would, especially when inner cues are weak or unclear.",limitation:"A classic theory with mixed support that competes with other explanations; it does not predict how quickly a new identity forms. The chapter abstract was read."},{id:"identity-hershfield",title:"Hershfield · 2011 · Future self-continuity",url:"https://pmc.ncbi.nlm.nih.gov/articles/PMC3764505/",type:"research",finding:"This review reports that people who feel similar and connected to their future self, who see that self vividly and who view it positively tend to make more future-friendly choices; for example, seeing age-progressed images of oneself increased hypothetical retirement saving compared with control conditions.",limitation:"Most studies concern money and short lab tasks, not personal change programs. The review and summary were read."},{id:"identity-cole",title:"Cole, Smith, Ragan, Suurmond & Armitage · 2021 · Mental simulation and behavior change meta-analysis",url:"https://pmc.ncbi.nlm.nih.gov/articles/PMC8500882/",type:"research",finding:"94 randomized studies (123 effects, 5,685 people): mentally simulating future behavior changed later behavior by a medium amount overall (g = 0.49). Rehearsing oneself performing well (g = 0.67) and standard performance rehearsal (g = 0.48) worked best; imagining a desired outcome had a small effect (g = 0.23); imagining only the process steps was not reliable (g = 0.17, five effects).",limitation:"Most participants were students; some subtypes rest on few studies. Behaviors were mostly health, sport and skill tasks, not identity itself. The article’s abstract and results were read."},{id:"identity-toth",title:"Toth et al. · 2020 · Does mental practice still enhance performance? A 24-year follow-up",url:"https://www.sciencedirect.com/science/article/abs/pii/S1469029219301530",type:"research",finding:"37 studies published 1995–2018 (115 effects): mental practice had a small but significant positive effect on performance (r = 0.131), influenced by how long it was practiced, the type of task and the kind of imagery. Physical practice was more effective than mental practice alone.",limitation:"Mainly motor and sports skills; it does not test personality change, mood or illness. The abstract was read."},{id:"identity-gollwitzer",title:"Gollwitzer & Sheeran · 2006 · Implementation intentions meta-analysis",url:"https://www.sciencedirect.com/science/chapter/bookseries/abs/pii/S0065260106380021",type:"research",finding:"Across 94 independent tests, forming if-then plans (implementation intentions) had a medium-to-large positive effect on goal attainment (d = 0.65). The plans made the chosen situation easier to notice and the planned response more automatic.",limitation:"Studies varied widely in goals and settings, and published studies may overstate effects. It does not show that plans work equally for everyone or for long-term identity change. The abstract was read."},{id:"identity-lally",title:"Lally, van Jaarsveld, Potts & Wardle · 2010 · How are habits formed",url:"https://www.researchgate.net/publication/32898894_How_are_habits_formed_Modeling_habit_formation_in_the_real_world",type:"research",finding:"96 volunteers repeated a self-chosen daily eating, drinking or activity behavior in the same context for 12 weeks. Automaticity rose along a curve that levelled off; the time to reach 95% of that level ranged from 18 to 254 days (median about 66 days among the 39 people whose data fit the model). Missing one opportunity did not materially affect habit formation.",limitation:"Small, self-reported study; the model fit fewer than half of the people with enough data, and times beyond the 84 days observed are estimates. The abstract was read; the 66-day median comes from the full paper as reported in a follow-up article by the same team and in secondary summaries."},{id:"identity-gardner",title:"Gardner, Lally & Wardle · 2012 · Making health habitual",url:"https://pmc.ncbi.nlm.nih.gov/articles/PMC3505409/",type:"research",finding:"Summarizing habit research for doctors, the authors report that automaticity plateaued after an average of 66 days, with considerable variation, that simple actions became automatic faster than demanding ones, and that missing an occasional day did not seriously impair habit formation. Their advice: choose a simple action, do it at a consistent time and place, and repeat it.",limitation:"A narrative review and practice guide, not a new trial. The full article was read."},{id:"identity-wood-everyday",title:"Wood, Quinn & Kashy · 2002 · Habits in everyday life",url:"https://dornsife.usc.edu/wendy-wood/wp-content/uploads/sites/183/2023/10/Wood.Quinn_.Kashy_.2002_Habits_in_everyday_life.pdf",type:"research",finding:"In two hourly diary studies, 35% (Study 1) and 43% (Study 2) of behaviors were habits, done almost daily and usually in the same place. During habits, people’s thoughts matched what they were doing only 40% and 44% of the time, compared with 70% and 60% during non-habitual behavior.",limitation:"US college students only; habit was defined by frequency and stable location. The article’s abstract and summary were read."},{id:"identity-wood-runger",title:"Wood & Rünger · 2016 · Psychology of habit",url:"https://www.annualreviews.org/content/journals/10.1146/annurev-psych-122414-033417",type:"research",finding:"This review describes habits as responses that form when people repeat the same action in the same context while pursuing goals, and that are then cued by the context. Habits act as an efficient default and can persist even when people’s intentions change.",limitation:"A narrative review; it explains mechanisms rather than testing a specific method. The abstract was read."},{id:"identity-killingsworth",title:"Killingsworth & Gilbert · 2010 · A wandering mind is an unhappy mind (Harvard Gazette report)",url:"https://news.harvard.edu/gazette/story/2010/11/wandering-mind-not-a-happy-mind/",type:"research",finding:"A smartphone study of about 2,250 adults, with around 250,000 data points, found that people’s minds were wandering 46.9% of the time, and at least 30% of the time during nearly every activity. People were less happy when their minds wandered.",limitation:"Volunteers who used an app, mostly from the US. The data are observational; the time-lag analysis suggested mind-wandering tended to come before unhappiness, but this is not a controlled experiment. A university news report of the Science paper was read."},{id:"identity-lieberman",title:"Lieberman et al. · 2007 · Putting feelings into words (affect labeling)",url:"https://sanlab.psych.ucla.edu/wp-content/uploads/sites/31/2015/05/Lieberman_AL-2007.pdf",type:"research",finding:"In 30 adults in a brain scanner, choosing a word for the emotion on a face (such as “angry” or “scared”) was linked with lower amygdala response than choosing a name matching the face’s gender, and with more activity in the right ventrolateral prefrontal cortex.",limitation:"A single small lab study of brief reactions to pictures; it does not show that naming feelings improves mood over weeks. The article was read."},{id:"identity-breines",title:"Breines & Chen · 2012 · Self-compassion increases self-improvement motivation",url:"https://journals.sagepub.com/doi/abs/10.1177/0146167212445599",type:"research",finding:"In four experiments, people encouraged to take a self-compassionate view of a weakness, failure or moral mistake were more motivated to improve than people in self-esteem or neutral control conditions; for example, they spent more time studying for a difficult test after failing an initial one.",limitation:"Short lab experiments, mostly with students; long-term behavior was not measured. The abstract was read."},{id:"identity-harkin",title:"Harkin et al. · 2016 · Does monitoring goal progress promote goal attainment?",url:"https://eprints.whiterose.ac.uk/id/eprint/87431/",type:"research",finding:"A meta-analysis of 138 studies with 19,951 people found that interventions that increased progress monitoring improved goal attainment (d = 0.40). Effects were larger when progress was physically recorded or reported to others.",limitation:"Goals and ways of monitoring varied widely; the review does not test a specific weekly review format like this lesson’s. The abstract was read."}],le={id:"identity",title:"New Self",subtitle:"Change who you are, one small vote at a time.",description:"What if lasting change starts with who you think you are, not only with what you force yourself to do? Learn to spot your old self on autopilot and practice a new one, in a short morning rehearsal and in small proof every day.",scope:"For adults who want an everyday way to change a familiar pattern of thinking, feeling or reacting. It draws on Dr. Joe Dispenza and James Clear and says plainly which of their ideas research supports and which it does not. It is not therapy and not a treatment for depression, anxiety, trauma or any illness; if you are struggling, talk to a health professional, and in a crisis call your local emergency number.",outcome:"A written portrait of your old self and the new self you are choosing, a 10-minute morning rehearsal, three if-then plans for your hardest moments, and a weekly review to carry you through the first months.",photo:{id:"1611569518992-0927098278b7",alt:"A woman walking alone down a dirt road between green trees"},lessons:[{id:"identity-1",title:"Meet your old self",minutes:8,goal:"Write an honest, kind portrait of the thoughts, feelings and reactions you repeat on most days.",reading:["Much of your day runs on repeats. You wake up, pick up the same thoughts about the same problems, slip into the same familiar moods and react to the same people in the same way. Dr. Joe Dispenza, in Breaking the Habit of Being Yourself, calls this bundle the “old self”: not a bad person, just a set of well-practiced programs. Research agrees that a large part of daily life is habitual. In two diary studies, somewhere between a third and almost half of what people did was repeated almost daily in the same place, often while their minds were somewhere else.","Change starts with seeing the program clearly. That is the aim of this lesson: an inventory, not a verdict. You will notice which thoughts come back most often, which feelings follow them, and what you usually do next. Try to describe yourself the way a friendly researcher would describe someone they are observing: specific, curious and without insults. “I’m lazy” gives you nothing to work with. “After lunch at my desk I think ‘this is too much’ and scroll my phone for twenty minutes” shows you exactly where to step in."],deeper:[{heading:"Why awareness comes first",paragraphs:["Habits are triggered by context, not by your latest intentions. In their review of habit research, Wendy Wood and Dennis Rünger describe habits as the brain’s efficient default: once a response has been repeated often in a setting, that setting can call it up even after your goals have changed. That is why a New Year’s resolution so often loses to an ordinary Tuesday afternoon.","Dispenza’s first step points the same way. Before you try to become someone new, you get to know the automatic self in detail — the thoughts, feelings and behaviors you want to leave behind. You cannot interrupt a loop you have never noticed."],visual:{kind:"cycle",title:"How the old self keeps itself going",center:"Old self",nodes:[{label:"Familiar setting",text:"The same place, time, person or mood."},{label:"Familiar thought",text:"The usual story: “here we go again.”"},{label:"Familiar feeling",text:"The mood that feels like home, good or bad."},{label:"Familiar reaction",text:"What you do next without deciding to."},{label:"Familiar result",text:"It seems to prove “this is just who I am.”"}],note:"A simplified picture based on habit research and Dispenza’s description. Real life is messier, and any point in the loop is a place where you can step in."}},{heading:"Common mistakes",paragraphs:["Turning the inventory into a court case. You are collecting information, not evidence against yourself. Harsh labels can turn curiosity into defensiveness, and a defensive mind notices less.","Listing only behaviors. The old self is also made of thoughts and moods. “I skip the gym” is useful; “I skip the gym after I think ‘I’m too tired’ and feel flat” is more useful, because it shows the thought and the feeling you can catch earlier."]},{heading:"What this is not",paragraphs:["If the old self you are describing includes long-lasting low mood, panic, flashbacks or thoughts of harming yourself, this is not something to handle alone with a worksheet. Please talk to a doctor or mental health professional, and in a crisis call your local emergency number. This course is for everyday patterns; it is not a substitute for treatment."]}],example:{title:"Leyla, 34, project coordinator",text:"Leyla set three phone reminders for a normal Wednesday. At 10:40 she wrote: reading a short email from her manager, thinking “she thinks I’m careless”, tight chest, rewrote the reply four times. At 2:15: skipped lunch, thinking “no time”, buzzing and tense. At 6:30: stayed late to double-check a report nobody had asked about. That night she read her notes and saw the same thread running through all three: a small trigger, the thought that she was about to be found out, and a rush to over-prepare. She did not try to fix anything yet. She wrote two neutral sentences about “the old Leyla” and was surprised to feel relief. The pattern had edges now, and a start and an end."},practice:["Set three reminders for today, and each time one goes off, write one line: what I was thinking, what I was feeling, what I was doing.","Tonight, read your notes and circle the thought, feeling or reaction that showed up more than once.","Write a two-sentence portrait of your old self in neutral words, as if describing a friend you are getting to know."],reflection:"Which of your thoughts or feelings is so familiar that you rarely notice it anymore?",question:"Which note is most useful for getting to know your old self?",options:["I am simply a lazy person.","After lunch at my desk I think “this is too much”, feel heavy and scroll my phone.","Starting tomorrow I will be a completely different person."],correct:1,feedback:"A specific note shows the setting, the thought, the feeling and the action, so you can see where to step in. Labels and big promises leave you with nothing to work on.",takeaway:"You cannot change a pattern you have never met, so meet it with curiosity.",sources:["identity-dispenza-habit","identity-wood-everyday","identity-wood-runger"],visual:{kind:"table",title:"Your old-self inventory",columns:["Layer","Ask yourself","Example"],rows:[["Thoughts","What do I tell myself on most days?","“I never have enough time.”"],["Feelings","Which mood feels like home?","Low-level worry by mid-morning"],["Reactions","What do I do when that mood shows up?","Check email again, skip lunch"],["Setting","Where and when does it usually start?","At my desk, between 10 and 11"]],note:"Fill in your own version. Aim for specific and kind rather than complete."},technique:{name:"The old-self inventory",origin:"Dr. Joe Dispenza · Breaking the Habit of Being Yourself (2012)",steps:["Pick one area where you want to change, such as stress at work or how you react at home.","Write down the thoughts you think most often in that area, the way they sound in your head.","Name the feelings that come with those thoughts and where you notice them in your body.","Describe what you usually do or say next: your automatic reactions.","Note the places, times and people that tend to set the whole pattern off.","Read the list back and admit to yourself, without blame, that this is how you have been running. That honest look is the starting point."],evidence:"Noticing and writing down your own patterns fits well with habit research, which shows that much everyday behavior is cued by familiar settings. The inventory has not been tested on its own; treat it as a starting map, not a cure.",sourceId:"identity-dispenza-habit"},photo:{id:"1519087630026-63fb0dab69bb",alt:"A woman looking at her reflection in a wall mirror"}},{id:"identity-2",title:"Memorized emotions",minutes:9,goal:"Spot one feeling you have practiced so often that it now feels like part of your personality.",reading:["Dispenza describes a particular kind of habit: an emotion you have felt so many times that your body seems to reach for it on its own. Worry before every meeting. Irritation the moment you walk into the kitchen. Guilt whenever you rest. He calls these memorized emotions. They may have started as reactions to real events, but through repetition they now arrive before anything has happened, and they start to feel like who you are: “I’m just an anxious person.”","You do not need to accept his whole theory to find this idea useful. Habit research shows that repeated responses become cued by context, and it seems plausible that some emotional reactions work in a similar way, although this has been studied less directly. A small line of research also suggests that putting a feeling into words can soften it. In one brain-imaging study, naming the emotion on a face was linked with less activity in the amygdala, a brain area involved in threat responses. Today you will practice spotting and naming your most familiar feeling."],deeper:[{heading:"What the research says",paragraphs:["In Matthew Lieberman’s study, 30 adults looked at emotional faces in a brain scanner. When they picked a word for the emotion, such as angry or scared, their amygdala responded less than when they picked a name that matched the face’s gender. The only area more active during emotion labeling was a region at the front of the brain linked to self-control.","It is one small lab study, and a calmer amygdala for a few seconds is not the same as feeling better for weeks. Still, it matches everyday experience: “I notice dread in my stomach” gives you a little distance that “everything is going wrong” does not."],visual:{kind:"compare",title:"Fused with a feeling vs. naming it",left:{label:"Fused with it",items:["I’m useless.","Everything is going wrong.","This is just how I am."]},right:{label:"Naming it",items:["I notice dread in my stomach.","There’s my old Monday worry.","This feeling is familiar, and it passes."]},note:"Naming a feeling does not mean arguing with it or pushing it away."}},{heading:"How Dispenza frames it, and what to leave out",paragraphs:["In his books and blog, Dispenza goes much further. He links emotional states to reprogramming your genes and biology, to healing, and to a “quantum field” that is said to respond to who you are and rearrange events around you. These claims are not supported by scientific research. Never delay or change medical treatment because of them.","What you can keep is the practical core: notice the familiar feeling early, name it, and choose not to feed it with the same old thoughts and reactions. Over time you give a different feeling a chance to become familiar instead."]},{heading:"When a feeling is more than a habit",paragraphs:["Some feelings are signals worth listening to: anger at real unfairness, grief after a loss, fear in a situation that is actually unsafe. And persistent anxiety or low mood can need professional help. This lesson is about habitual feelings in ordinary life; it is not a substitute for treatment."]}],example:{title:"Daniel, 41, teacher",text:"Every Sunday around six in the evening, a heavy dread settled on Daniel. For years he took it as a sign that the coming week would be bad, so he spent the evening checking school email and snapping at his family. This Sunday, when the familiar weight arrived, he said to himself: there it is, the old Sunday dread. He noticed his shoulders were up near his ears and let out a slow breath. Then he wrote down the one task he really needed to prepare, did it in fifteen minutes and closed the laptop. The feeling did not vanish, but it was smaller and it no longer decided his evening. He watched a film with his daughter, and on Monday the week turned out to be ordinary."},practice:["Choose one feeling that shows up on most days, and write down when it usually arrives and where you feel it in your body.","The next time it appears, silently name it with a short label, such as “old worry” or “Monday irritation”.","After naming it, take three slow breaths and ask: what would I do right now if this feeling were not in charge?"],reflection:"Which feeling do you reach for so often that you might have mistaken it for your personality?",question:"Which response fits the practical core of this lesson best?",options:["Accept that the feeling is simply who you are.","Try to change your genes by feeling happy for long enough.","Notice the familiar feeling early, name it and choose your next action."],correct:2,feedback:"Noticing and naming a familiar feeling creates a little space to choose what you do next. Claims about changing genes or healing through emotion are not supported by research.",takeaway:"A feeling you have practiced is not a fact about who you are.",sources:["identity-dispenza-change","identity-dispenza-habit","identity-dispenza-supernatural","identity-lieberman","identity-wood-runger"],visual:{kind:"cycle",title:"How a feeling becomes a mood, and a mood a self",center:"Memorized emotion",nodes:[{label:"Trigger",text:"A message, a room, a memory, a time of day."},{label:"Feeling",text:"Worry, irritation or guilt, felt in the body."},{label:"Thought",text:"The mind finds reasons the feeling is right."},{label:"Reaction",text:"Avoid, snap, over-prepare, withdraw."},{label:"Repeat",text:"Next time the feeling arrives sooner and stays longer."}],note:"Dispenza’s idea drawn as a loop. The general pattern fits habit research; his more detailed biological explanations go beyond what has been tested."},technique:{name:"Un-memorize an emotion",origin:"Dr. Joe Dispenza · The Art of Change (2019)",steps:["Pick one emotion you want to stop living in, such as worry, resentment or guilt.","Recall a recent time it took over, and replay it slowly in your mind: the thoughts, the sensations and what you did.","As you watch the replay, decide that this is the reaction you are no longer going to practice.","Ask how you would like to feel in that same situation instead, and let yourself sense a little of that feeling now.","Repeat this short review often, so the new response starts to feel as familiar as the old one."],evidence:"Reviewing a pattern and rehearsing a different response overlaps with mental rehearsal and emotion labeling, which have modest research support. Dispenza’s explanations involving a quantum field, genes and healing are not supported by science.",sourceId:"identity-dispenza-change"},photo:{id:"1762126242240-cafa01fb1351",alt:"A person in an armchair looking out of a rainy window"}},{id:"identity-3",title:"Catch the autopilot",minutes:8,goal:"Interrupt your old self at least once in the middle of an ordinary day.",reading:["A quiet moment in the morning is the easy part. The real test comes at three in the afternoon, when the familiar trigger shows up and the old self takes over before you notice. Dispenza’s program includes this daytime step: once you have studied your old self, you watch for it during the day, and the moment you catch it, you remind yourself of the choice you made and redirect. Awareness in the moment turns an automatic loop into a decision point.","This matters because so much of the day runs on autopilot. In two diary studies by Wendy Wood and colleagues, 35 and 43 percent of students’ behaviors were habits done almost daily in the same place, and during those habits people were often thinking about something else. A separate phone study of about 2,250 adults found their minds wandering in almost half of the moments sampled. You will not catch every loop; nobody does. Catching a few is how change starts."],deeper:[{heading:"Where your attention goes during habits",paragraphs:["In the same diary studies, people’s thoughts matched what they were doing much less often during habits than during non-habitual actions. Habits free the mind to wander. That is handy when you tie your shoes, and less handy when the habit is snapping at someone you love.","The smartphone study by Matthew Killingsworth and Daniel Gilbert also found that people were less happy when their minds wandered. That finding is observational, so it does not prove that wandering causes unhappiness, but it is a gentle reason to come back to the present more often."],visual:{kind:"bars",title:"Were people thinking about what they were doing?",bars:[{label:"Study 1 · during habits",value:40,display:"40%"},{label:"Study 1 · other actions",value:70,display:"70%"},{label:"Study 2 · during habits",value:44,display:"44%"},{label:"Study 2 · other actions",value:60,display:"60%"}],note:"Share of diary entries in which thoughts matched the current action, from Wood, Quinn & Kashy (2002). Participants were US college students.",sourceId:"identity-wood-everyday"}},{heading:"How to catch it",paragraphs:["Catching the old self is a skill, and skills improve with practice. Start with one pattern only, and look for its earliest sign. That is often a body sensation or a small movement, such as reaching for your phone, before the full thought arrives."],visual:{kind:"steps",title:"Catch, name, pause, redirect",steps:[{label:"Catch",text:"Notice the first sign: a sensation, a familiar thought, a reach for the phone."},{label:"Name",text:"Say your cue word silently: “there it is”."},{label:"Pause",text:"One slow breath out. Feel your feet on the floor."},{label:"Redirect",text:"Ask what your new self would do next, and do the smallest version of it."}],note:"Adapted from Dispenza’s daytime practice. The pause matters more than the exact order."}},{heading:"Common mistakes",paragraphs:["Scolding yourself for catching it late. Noticing the loop after it has run is still noticing it; tomorrow you may catch it a minute earlier.","Relying on memory alone. Tie your practice to reminders you will actually see: a word on your phone’s lock screen, a sticky note on your laptop, a hair tie on your wrist. Lesson 6 goes further with cues."]}],example:{title:"Sofia, 27, nurse",text:"Sofia’s old self showed up on the drive home. After every shift she replayed each mistake, real or imagined, and walked through her front door tense and short-tempered. She chose a cue: the moment she turned the key in the car. On Monday she forgot completely. On Tuesday she caught it at a red light, halfway home, and said silently: replay mode. She breathed out, put on a podcast she liked and named one thing she had done well that day. On Wednesday she caught it at the key. It did not work every evening, but on three evenings that week she came home noticeably calmer, and her partner noticed too."},practice:["Choose one old-self moment to watch for today, such as the urge to check your phone or the first flash of irritation.","Pick a cue word to say silently when you catch it, such as “there it is” or “change”.","Each time you catch it, breathe out slowly once, do one small thing your new self would do, and make a tally mark."],reflection:"What is the earliest sign, in your body or your thoughts, that your old self is about to take over?",question:"You catch your old reaction halfway through. What is the most helpful response?",options:["Name it, pause for one breath and choose a small next step.","Decide the day is ruined and try again next week.","Criticize yourself harshly so you remember next time."],correct:0,feedback:"Catching the loop at any point is progress. A name, a pause and one small step turn the habit back into a choice; harsh self-criticism usually makes you less likely to look closely next time.",takeaway:"Every time you catch the autopilot, you turn a habit back into a choice.",sources:["identity-dispenza-habit","identity-wood-everyday","identity-killingsworth"],visual:{kind:"bars",title:"How much of everyday behavior is habit?",bars:[{label:"Diary study 1",value:35,display:"35%"},{label:"Diary study 2",value:43,display:"43%"}],note:"Share of reported behaviors that were habits, meaning done almost daily and usually in the same place, from Wood, Quinn & Kashy (2002). Participants were US college students, so the share may differ for you.",sourceId:"identity-wood-everyday"},technique:{name:"Catch and redirect during the day",origin:"Dr. Joe Dispenza · Breaking the Habit of Being Yourself (2012)",steps:["In the morning, remind yourself which old thought, feeling or reaction you are letting go of today.","During the day, watch for the moments it tends to appear: the people, places and times from your inventory.","When you notice it, interrupt the loop on purpose; a short cue word you say silently can help.","Remind yourself of the person you decided to be this morning.","Choose a response that fits that person, even a very small one.","In the evening, look back briefly: when did you catch it, and when did it slip past?"],evidence:"Noticing cues and deciding in advance how to respond fits research on habits and if-then plans. This specific daytime routine has not been tested in controlled studies.",sourceId:"identity-dispenza-habit"},photo:{id:"1626257690705-8d62125575b0",alt:"A man in a dark jacket walking along a city pedestrian lane in daylight"}},{id:"identity-4",title:"Every action is a vote",minutes:9,goal:"Choose the identity you want to grow and cast your first small vote for it today.",reading:["James Clear, in Atomic Habits, describes three layers of change. The outer layer is outcomes, such as losing weight or finishing a book. The middle layer is process: your routines and systems. The deepest layer is identity, meaning what you believe about yourself. Most of us start from the outside. Clear suggests starting from the inside: decide who you want to be, then prove it to yourself with small wins. He compares each action to a vote for a certain kind of person. No single vote wins the election, but as votes pile up, so does the evidence for a new self.","The idea has older roots in psychology. Daryl Bem’s self-perception theory, from 1972, proposes that we partly learn what we are like by watching what we do, much as an outside observer would, especially when our inner feelings are unclear. Daphna Oyserman’s research on identity-based motivation adds that people prefer actions that feel in line with who they are in the moment; when something feels “not for people like me”, effort drops. So the goal is not a heroic day. It is a small action that fits the new self."],deeper:[{heading:"Why small proof works",paragraphs:["Oyserman’s research also looks at how people read difficulty. If a task feels hard and you conclude that it must not be for someone like you, you tend to give up. If you conclude that it is hard because it matters to you, you tend to keep going. A classroom program built on these ideas, Pathways-to-Success, was linked with better grades among eighth-graders in high-poverty Chicago schools, especially when teachers delivered it as designed.","A school program is a long way from your morning walk, and it does not prove that this lesson will work for you. But the principle carries over: read difficulty as a sign of importance, not as a verdict on who you are."],visual:{kind:"table",title:"Three ways to read difficulty",columns:["When it feels hard, you think…","What usually follows"],rows:[["This must not be for someone like me.","Effort drops, and the old self wins by default."],["This is hard because it matters to me.","You keep going, or try a smaller step."],["Hard times are shaping who I am becoming.","Setbacks become part of the story, not its end."]],note:"Adapted from Daphna Oyserman’s identity-based motivation research: difficulty as impossibility, as importance and as improvement."}},{heading:"Common mistakes",paragraphs:["Choosing a verdict instead of a direction. “I am a disciplined person” can feel false and make you defensive. “I am becoming someone who keeps small promises to myself” leaves room to grow.","Picking votes that are too big. Clear’s own example of someone starting to exercise begins with only a few dozen steps a day. And do not count only perfect days: in an election you need a majority, not every single vote."]}],example:{title:"Amir, 38, sales manager",text:"Amir wanted to stop being the dad who came home and yelled about shoes in the hallway. He wrote: I am becoming a calm father. His first vote was tiny. When he parked outside the house, he stayed in the car for sixty seconds, breathed out slowly three times and pictured greeting his kids before anything else. He kept a tally in his phone. By Friday he had five marks. On Thursday he still snapped about homework, but ten minutes later he went back and apologized, and he counted that as a vote too. It was not a transformation. It was the first week in a long time in which he had evidence that he could be the father he wanted to be."},practice:["Finish this sentence in writing: “I am becoming someone who…”, and keep it about who you are, not about a result.","Pick one vote so small that you could do it on your worst day, and do it within the next hour.","Start a simple tally on paper or in your phone, and add a mark each time you cast a vote."],reflection:"What small action today would count as evidence that you are becoming the person you described?",question:"In identity-based habits, what matters most in the first weeks?",options:["Getting impressive results as fast as possible.","Casting small, repeated votes that prove the new identity to yourself.","Waiting until you feel like a new person before you act."],correct:1,feedback:"Small, repeated actions build evidence for the new identity. Results come later; waiting to feel different first usually means waiting a long time.",takeaway:"You do not need a perfect record, just a growing majority of votes.",sources:["identity-clear-identity","identity-clear-votes","identity-bem","identity-oyserman","identity-pathways"],visual:{kind:"compare",title:"Outcome goals vs. identity-based habits",left:{label:"Starting with the outcome",items:["I want to run a half-marathon.","Motivation depends on visible progress.","A missed week feels like failure."]},right:{label:"Starting with the identity",items:["I am becoming someone who moves every day.","Each short walk counts as proof.","A missed day is one vote, not the election."]},note:"Based on James Clear’s description of identity-based habits. Outcome goals still help; identity gives them a home."},technique:{name:"Identity-based habits: decide, then prove",origin:"James Clear · Atomic Habits (2018)",steps:["Look at a result you want and ask what kind of person would get it naturally.","Write that identity as a short sentence: “I am becoming someone who…”.","Choose the smallest action such a person would take today.","Do it, even if it feels too small to matter.","Record it as one vote for your new identity.","Grow the action slowly once it feels easy."],evidence:"Clear’s model is a practical synthesis, not a tested program. It fits self-perception theory and identity-based motivation research, which suggest that actions shape how we see ourselves and that actions in line with an identity feel more worth doing.",sourceId:"identity-clear-identity"},photo:{id:"1787154604447-4a62ed6654e3",alt:"A woman in a dark hijab and sports clothes jogging along a city street"}},{id:"identity-5",title:"Rehearse the new self",minutes:12,goal:"Practice a 10-minute morning rehearsal of the person you are becoming and link it to one real action.",reading:["The heart of Dispenza’s method is a morning meditation in which you rehearse your new self. After settling your body and letting go of the old pattern, you imagine in detail how your new self thinks, speaks and acts in real situations from your day, and you try to feel now the emotions that person would feel: calm, confidence, warmth. He suggests doing it before the day’s routine takes over, so that you start the day as the new self rather than the old one.","Mental rehearsal has real research support, with limits. A 2021 meta-analysis of 94 randomized studies found that mentally simulating a behavior changed later behavior by a medium amount overall. Picturing yourself doing the action well worked best; picturing only a happy outcome worked much less. Sports research finds that mental practice improves skills a little, but less than real practice. So rehearse the process, not just the prize, and follow it with a real action the same day. Dispenza’s claims that meditation reshapes genes, heals illness or changes reality through a quantum field are not supported by science."],deeper:[{heading:"The 10-minute morning rehearsal",paragraphs:["You can do this sitting on the edge of your bed or in a chair, before you look at your phone. Use a timer so you do not have to watch the clock. The minutes below are a guide; a shorter version on a rushed day still counts.","If rehearsing brings up strong distress or old painful memories, open your eyes, feel your feet on the floor and stop. This is not the right tool for working through trauma; a trained professional can help with that."],visual:{kind:"steps",title:"Ten minutes, five parts",steps:[{label:"Settle · 2 min",text:"Close your eyes, breathe slowly and move your attention from thoughts into your body."},{label:"Release · 2 min",text:"Name the old self you are leaving behind today and let it go."},{label:"Rehearse · 4 min",text:"Picture your new self in two or three real scenes from your day, doing it well."},{label:"Feel · 1 min",text:"Let yourself feel a little of that self’s calm or confidence now."},{label:"Commit · 1 min",text:"Choose one concrete action and when you will do it."}],note:"A shortened adaptation of Dispenza’s longer meditation, weighted toward the parts research supports."}},{heading:"What the research says",paragraphs:["A 2020 update of a classic sports meta-analysis looked at 37 studies and found that mental practice had a small but real effect on performance, smaller than an earlier estimate from 1994, and that physical practice worked better. The broader 2021 review found larger effects on behavior when people rehearsed doing the action, especially doing it well.","Put together: rehearsal is a warm-up, not a substitute. It seems to help most when it is specific, repeated and followed by doing the real thing."],visual:{kind:"compare",title:"Keep this, leave that",left:{label:"Supported by research",items:["Rehearsing specific actions in your mind","Seeing yourself do it well, then trying it for real","Making your future self feel vivid and close"]},right:{label:"Not supported by research",items:["Changing your genes by thinking","Healing illness through meditation alone","Shifting reality through a quantum field","Mystical abilities through the pineal gland"]},note:"Meditation is not a replacement for medical care. Do not stop or delay treatment because of any claim like those on the right."}},{heading:"Keep the future self close",paragraphs:["Hal Hershfield’s research on future-self continuity suggests why rehearsal can matter. People who feel similar and connected to their future self, who can see that self vividly and who view it positively tend to make choices that help that future self, such as saving more. Your morning rehearsal is a way to meet your future self every day, so that it feels less like a stranger and more like you."]}],example:{title:"Mei, 45, accountant",text:"Mei wanted to become someone who speaks up in meetings. Each morning after pouring her tea, she sat for ten minutes with a timer. She let go of the old Mei who stayed silent and then went over the ten o’clock meeting in her head: raising her hand, her voice steady, the calm feeling in her chest. She finished with one commitment: I will make one point before the first twenty minutes are over. On day one she stayed quiet anyway. On day three she asked one question. In the second week she shared an idea about the budget and her manager asked her to write it up. She still felt nervous, but the nervousness no longer made the decision for her."},practice:["Write three short scenes from today in which your new self will show up: who is there, what happens and what you do.","Tomorrow morning, before you pick up your phone, do the 10-minute rehearsal and play each scene in your mind at least once, including the feeling.","End by choosing one real action for the day and tie it to a moment: “When … happens, I will …”."],reflection:"In your rehearsal, what does your new self do differently in the first five minutes of a hard moment?",question:"Which kind of rehearsal is most likely to change what you actually do?",options:["Imagining yourself doing the specific action well, then trying it for real.","Picturing only the reward: the applause, the money or the new body.","Meditating to change your genes so the change happens by itself."],correct:0,feedback:"Rehearsing yourself doing the action well had the largest effects in research, especially when real practice followed. Picturing only the outcome helped much less, and gene claims are not supported.",takeaway:"Rehearse the process in your mind, then give it one real chance today.",sources:["identity-dispenza-habit","identity-dispenza-supernatural","identity-dispenza-new-self","identity-cole","identity-toth","identity-hershfield"],visual:{kind:"bars",title:"Which kind of mental rehearsal changed behavior?",bars:[{label:"Rehearsing doing it well",value:.67,display:"g = 0.67"},{label:"Rehearsing doing it",value:.48,display:"g = 0.48"},{label:"Imagining a great outcome",value:.23,display:"g = 0.23"},{label:"Imagining the steps only",value:.17,display:"g = 0.17, not reliable"}],note:"Average effects (Hedges’ g) from Cole et al. (2021): 94 randomized studies, 5,685 people, mostly students. About 0.2 is small and 0.5 medium. The “steps only” result rests on just five effects and was not statistically reliable.",sourceId:"identity-cole"},technique:{name:"Morning rehearsal of the new self",origin:"Dr. Joe Dispenza · Breaking the Habit of Being Yourself (2012)",steps:["Sit comfortably, close your eyes and spend a couple of minutes bringing your attention from your thoughts into your body and the present moment.","Recall the old self you are leaving behind and, in your own words, let it go for today.","Ask yourself how the best version of you would think, speak and act today.","Picture that person moving through two or three real scenes from your day, in detail.","Let yourself feel a little of the emotion that new self would feel, such as calm, gratitude or confidence, as if it were already true.","Before opening your eyes, choose one concrete action that proves it today."],evidence:"Mentally rehearsing specific actions has small-to-medium research support, especially when real practice follows. The books’ claims about a quantum field, gene expression, healing illness and mystical states are not supported by scientific evidence; do not use this practice in place of medical care.",sourceId:"identity-dispenza-habit"},photo:{id:"1600618528240-fb9fc964b853",alt:"A woman meditating on a wooden deck at sunset"}},{id:"identity-6",title:"Cues and environment",minutes:9,goal:"Set up your surroundings and three if-then plans so that your new self becomes the easy default.",reading:["Habits are cued by context: places, times, people, the phone lying on the table. That cuts both ways. The same mechanism that keeps the old self running can carry the new one. James Clear calls one version of this habit stacking, building on an idea from BJ Fogg: attach a new habit to one you already do every day. “After I switch on the kettle, I will write one line in my journal.” Clear also suggests designing your space so the new choice is visible and easy, and the old one takes an extra step.","Research on if-then plans, which psychologists call implementation intentions, supports this. Peter Gollwitzer and Paschal Sheeran pooled 94 tests and found that plans in the form “if situation X happens, then I will do Y” improved goal attainment by a medium-to-large amount on average. The plan works partly because the situation becomes easier to notice and the response more automatic. For identity change, write if-then plans for the exact moments your old self usually wins."],deeper:[{heading:"Write plans for the moments that matter",paragraphs:["Go back to your old-self inventory from lesson 1. Its settings column is your list of danger moments. Each one can become the “if” of a plan, and your new self’s smallest vote can become the “then”."],visual:{kind:"table",title:"Old-self moments, new-self plans",columns:["If…","then I will…"],rows:[["I sit down at my desk after lunch,","open the hardest file first, for five minutes."],["I feel the old irritation as I park at home,","take three slow breaths before I go inside."],["I reach for my phone in bed,","put it on the charger across the room and read one page."]],note:"Keep the “if” concrete and observable, and the “then” small enough to do even on a bad day."}},{heading:"What the research says",paragraphs:["Habit researchers Wendy Wood and Dennis Rünger point out that habits can persist even when intentions change, because the context keeps cueing them. That is why changing the context, or planning in advance for it, often works better than trying harder.","Studies by Phillippa Lally’s team also suggest keeping the new action at a consistent time and place while it is forming. A steady cue gives repetition something to attach to."],visual:{kind:"bars",title:"Average effect of if-then plans on reaching goals",bars:[{label:"If-then plan vs. goal alone",value:.65,display:"d = 0.65"}],note:"From Gollwitzer & Sheeran (2006), 94 independent tests. About 0.5 is medium and 0.8 large. Goals and settings varied widely, and published studies may overstate effects.",sourceId:"identity-gollwitzer"}},{heading:"Common mistakes",paragraphs:["A vague cue. “In the morning” is not a moment you will notice; “after I switch on the kettle” is. Clear also advises matching frequencies: a daily habit needs an anchor that happens daily.","Relying on willpower in a tempting space. If the old self’s cue is always in view, the new self is fighting uphill. Move the cue, add a step, or change the room."]}],example:{title:"Jonas, 31, software developer",text:"Jonas’s old self lost most evenings to video games until one in the morning. His new self was someone who reads and sleeps well. On Sunday he unplugged the console controller and put it in a drawer in the hallway, and he left a novel on his pillow. He wrote one plan on a note by the kitchen: if I close my laptop after dinner, then I put the kettle on and read ten pages. Some nights he still played, but only after reading, and by then he often felt too sleepy to start. In the first week he was asleep before midnight on four nights out of seven, which was four more than the week before."},practice:["Pick one daily habit you already do reliably and attach your new-self action to it: “After I …, I will …”.","Change one thing in your space tonight so that the new action is visible and the old one takes an extra step.","Write three if-then plans for the moments your old self usually wins, and keep them where you will see them."],reflection:"Which place or object in your life is quietly voting for your old self?",question:"Which plan is most likely to help?",options:["I will try to be more patient this week.","I will be a completely new person starting Monday.","If my child spills something at dinner, then I will breathe out once before I speak."],correct:2,feedback:"A concrete if-then plan names the exact moment and the exact response, which makes both easier to notice and to do. General intentions and big promises do not tell you when to act.",takeaway:"Make the new self the easy default, and plan for the moments the old one usually wins.",sources:["identity-clear-stacking","identity-clear-environment","identity-gollwitzer","identity-wood-runger","identity-gardner"],visual:{kind:"steps",title:"Build a cue for your new self",steps:[{label:"Pick an anchor",text:"A habit you already do daily, at the right time and place."},{label:"Stack the new action",text:"“After I …, I will …”, kept small and specific."},{label:"Make it visible",text:"Put what the new action needs where you will see it."},{label:"Add friction to the old",text:"Move the old cue out of sight or add one extra step."},{label:"Test and adjust",text:"After a week, keep what works and change the anchor if needed."}],note:"Based on James Clear’s habit stacking and environment design, and on research about context cues."},technique:{name:"Habit stacking",origin:"James Clear · Atomic Habits (2018), after BJ Fogg’s Tiny Habits",steps:["List habits you already do every day without fail, such as making coffee or brushing your teeth.","Choose one that happens at the right time and place for your new action.","Write the formula: after I [current habit], I will [new habit].","Keep the new action small and specific so it fits into that moment.","Set up your space so that everything the new habit needs is already there.","Try it for a week, and change the anchor if it does not fit."],evidence:"Linking a new action to a stable daily cue matches research on habit formation and if-then plans, which show medium-to-large benefits on average. Habit stacking itself has not been tested as a named method.",sourceId:"identity-clear-stacking"},photo:{id:"1675762647949-1b25f669a687",alt:"A pair of white shoes sitting on a wooden floor"}},{id:"identity-7",title:"The 66-day road",minutes:10,goal:"Plan how to keep going for the long run, including what you will do when you slip.",reading:["How long until the new self feels natural? You may have heard that it takes 21 days. The best-known real-world study points to something slower and more varied. Phillippa Lally and colleagues at University College London asked volunteers to repeat a daily health behavior in the same context. The time until it felt close to fully automatic ranged from 18 to 254 days, with a median of about 66. Simple actions, such as drinking a glass of water, became automatic faster than demanding ones, such as a set of sit-ups.","Two findings make the road kinder. Missing a single day did not meaningfully harm habit formation, and change followed a curve: bigger gains early, then a slow levelling off. So plan for slips instead of pretending they will not happen. James Clear’s rule of thumb is to avoid missing twice in a row. And be kind to yourself when you slip: in experiments by Juliana Breines and Serena Chen, people encouraged to view a failure with self-compassion were more motivated to improve; for example, they studied longer after failing a test."],deeper:[{heading:"A weekly review",paragraphs:["Tracking progress helps. A meta-analysis of 138 studies with nearly 20,000 people found that interventions that got people to monitor their progress more often improved goal attainment, with a moderate average effect. Effects were larger when progress was written down or shared with someone.","A weekly review is a simple way to do this. Fifteen minutes, same day and time each week, with your tally from lesson 4 in front of you."],visual:{kind:"table",title:"Your 15-minute weekly review",columns:["Question","Why it helps"],rows:[["How many votes did I cast this week?","Counting makes progress visible."],["When did the old self win, and what was the cue?","It turns slips into information."],["What will I adjust: the cue, the size or the plan?","It keeps the system learning."],["What did my new self do that I am glad about?","It adds to the evidence for who you are becoming."]],note:"Writing your answers down, or sharing them with a friend, may strengthen the effect."}},{heading:"When you slip",paragraphs:["Slips are part of every real change. What matters is what you tell yourself next. A shame spiral says the whole project has failed; a self-compassionate restart treats the slip as human and asks what got in the way.","Clear’s advice is to focus on getting back, not on making up for the missed day. The next action only has to be small."],visual:{kind:"compare",title:"Two ways to respond to a slip",left:{label:"Shame spiral",items:["I blew it; I’m back to square one.","It’s already ruined, so why bother today?","Stop tracking so I don’t have to see it."]},right:{label:"Kind restart",items:["This happened, and it is human.","What got in the way this time?","Do the smallest version today."]},note:"If a slip leaves you feeling hopeless for days, or low mood will not lift, please reach out to a health professional. In a crisis, call your local emergency number."}},{heading:"Keep your future self in view",paragraphs:["Research on future-self continuity suggests that people make more future-friendly choices when their future self feels vivid, similar and connected to who they are now. A short note from yourself one year from now, thanking you for something specific you kept doing, is one way to keep that person close on the long road."]}],example:{title:"Rosa, 52, shop owner",text:"On day 23 of becoming someone who walks every morning, Rosa caught the flu and missed four days in a row. Her old self had a familiar line ready: typical, I never stick to anything. At her Sunday review she counted instead. Seventeen walks in twenty-three days. Every missed day came either from illness or from the one week she had opened the shop early. On Monday she restarted with a five-minute walk around the block, which was all she had energy for. By day sixty the habit still was not automatic on rainy mornings, but on dry ones she no longer argued with herself about going. She wrote that down too."},practice:["Put a 15-minute weekly review in your calendar, on the same day and at the same time each week.","Write your restart plan now: “If I miss a day, then the next day I will do the smallest version of my habit.”","Write a short note from your future self, one year from now, thanking you for one specific thing you kept doing."],reflection:"What would you like to say to yourself on the day you slip, so that you start again the next day?",question:"You have missed two days of your new habit. What does the research suggest?",options:["It proves you are not the kind of person who can change.","Restart today with a small version; occasional misses did not derail habit formation in research.","Wait until you feel motivated again, even if that takes a month."],correct:1,feedback:"In habit research, a missed opportunity did not materially harm habit formation. Restarting quickly and kindly, with a small step, keeps a slip from becoming a new pattern.",takeaway:"The new self is built by returning, not by never leaving.",sources:["identity-lally","identity-gardner","identity-clear-second-mistake","identity-breines","identity-harkin","identity-hershfield"],visual:{kind:"bars",title:"Days until a daily habit felt close to automatic",bars:[{label:"Fastest",value:18,display:"18 days"},{label:"Median",value:66,display:"66 days"},{label:"Slowest",value:254,display:"254 days"}],note:"From Lally et al. (2010): 96 volunteers, 12 weeks, one self-chosen daily behavior each; the curve could be estimated for 39 people. Automaticity was self-reported, and times beyond the 84 days observed are extrapolations.",sourceId:"identity-lally"},technique:{name:"Never miss twice",origin:"James Clear · Avoid the Second Mistake (2014)",steps:["Accept in advance that you will miss some days.","When you miss one, focus only on getting back the next day, not on making up for it.","Make the restart easy by doing the smallest version of the habit.","Put the habit on a fixed schedule so it does not depend on your mood.","Look at what caused the miss and remove that obstacle if you can."],evidence:"This is a practical rule of thumb, not a tested method. It is consistent with habit research showing that an occasional missed day did not seriously slow habit formation, and with experiments in which self-compassion after failure increased the motivation to improve.",sourceId:"identity-clear-second-mistake"},photo:{id:"1760715160644-7f5939675b68",alt:"Hikers walking along a trail through a golden meadow"}}]},oe=Object.freeze(Object.defineProperty({__proto__:null,COURSE:le,SOURCES:re},Symbol.toStringTag,{value:"Module"})),se=[{id:"state-emotion-decisions",title:"Lerner, Li, Valdesolo & Kassam · 2015 · Emotion and decision making (Annual Review of Psychology)",url:"https://escholarship.org/uc/item/8552m415",type:"research",finding:"A review of roughly 35 years of research concluding that emotions are potent, pervasive and predictable drivers of decision making, sometimes harmful and sometimes beneficial, and that they shape judgments and choices in regular, identifiable ways. The review describes how incidental emotions, feelings from one situation, often carry over into unrelated decisions without people noticing; for example, reading sad news stories raised people’s estimates of unrelated risks.",limitation:"A narrative review, not a meta-analysis, so it gives no single effect size. It describes how emotions shape decisions in general; it does not test any of the quick state-change tools in this course. The abstract and the author’s copy of the full text were read."},{id:"state-reappraisal-gross",title:"Gross · 2002 · Emotion regulation: affective, cognitive and social consequences (Psychophysiology)",url:"https://www.cambridge.org/core/journals/psychophysiology/article/abs/emotion-regulation-affective-cognitive-and-social-consequences/552536BD5988D0D2079A7E0CC82E1ED8",type:"research",finding:"James Gross compares two strategies. Reappraisal, changing how a situation is construed to lower its emotional impact, reduced both emotional experience and outward expression without harming memory. Suppression, hiding the outward signs of a feeling, did not reduce the feeling itself, impaired memory and raised physiological stress responses in the person and in their conversation partners.",limitation:"A review of laboratory findings, mostly short experiments with emotional films and conversations. It explains the process model of emotion regulation but gives no pooled effect size. The abstract was read."},{id:"state-regulation-meta",title:"Webb, Miles & Sheeran · 2012 · Meta-analysis of emotion regulation strategies (Psychological Bulletin)",url:"https://www.academia.edu/13555860/Dealing_With_Feeling_A_Meta_Analysis_of_the_Effectiveness_of_Strategies_Derived_From_the_Process_Model_of_Emotion_Regulation",type:"research",finding:"190 studies with 306 experimental comparisons. Average effects on emotional outcomes: cognitive change (reappraisal) d+ = 0.36, response modulation d+ = 0.16, attentional deployment d+ = 0.00. Within these families: perspective taking 0.45, reappraising the emotional situation 0.36, reappraising the emotional response 0.23; distraction 0.27, concentration on the emotional situation −0.26; suppressing the expression of emotion 0.32, suppressing the experience −0.04, suppressing thoughts about the event −0.12.",limitation:"Most studies were short laboratory experiments with emotional films, pictures or tasks; effects in daily life and over weeks may differ. The paper was read through an online copy of the published article."},{id:"state-acute-exercise",title:"Reed & Ones · 2006 · Acute aerobic exercise and positive activated affect: a meta-analysis",url:"https://experts.umn.edu/en/publications/the-effect-of-acute-aerobic-exercise-on-positive-activated-affect/",type:"research",finding:"158 studies (1979–2005), 450 effect sizes, 13,101 participants. A single bout of aerobic exercise increased positive activated affect (feeling energetic, enthusiastic, alert) with a corrected average effect of 0.47. Low intensity, sessions of up to about 35 minutes and low-to-moderate doses worked well; the lift lasted at least about 30 minutes before returning to baseline. Control groups showed a small drop (−0.17).",limitation:"Self-reported feelings, mostly in healthy volunteers; individual differences were large. Short-term mood effects are not evidence that one walk treats depression or anxiety. The abstract was read."},{id:"state-exercise-mental-health",title:"Singh et al. · 2023 · Physical activity for depression, anxiety and distress: umbrella review (BJSM)",url:"https://bjsm.bmj.com/content/57/18/1203",type:"research",finding:"97 systematic reviews covering 1,039 randomized trials and 128,119 participants. Physical activity reduced symptoms of depression (median effect −0.43), anxiety (−0.42) and psychological distress (−0.60). Higher intensity was linked to larger improvements, and interventions of 12 weeks or less showed the largest effects.",limitation:"77 of the 97 reviews were rated critically low in quality, so the exact numbers need caution. These are programs over weeks, not a single burst of movement, and they do not replace professional treatment. The abstract was read."},{id:"state-facial-feedback",title:"Coles, Larsen & Lench · 2019 · Meta-analysis of the facial feedback literature",url:"https://trace.tennessee.edu/utk_gradthes/5003/",type:"research",finding:"286 effect sizes from 136 studies: facial expressions had a small but reliable effect on emotional experience (d = 0.20). About 70% of the variation between studies reflected real differences in context; effects were larger with imagined scenarios and when no emotional stimulus was present. Evidence that faces change how people rate the emotional quality of pictures weakened after correcting for publication bias.",limitation:"Effects are small and variable. The abstract of the University of Tennessee version of this work (published in Psychological Bulletin in 2019) was read."},{id:"state-many-smiles",title:"Coles et al. (Many Smiles Collaboration) · 2022 · A multi-lab test of the facial feedback hypothesis",url:"https://www.nature.com/articles/s41562-022-01458-9",type:"research",finding:"A preregistered study with 3,878 participants in 19 countries. Deliberately mimicking smiles and voluntarily posing a smile both amplified and initiated feelings of happiness. When facial feedback was manipulated covertly with a pen held in the mouth, results were inconclusive.",limitation:"The abstract gives no effect sizes; the authors conclude the conditions under which facial feedback works are more limited than broad embodiment theories suggest. Only happiness was tested. The abstract was read."},{id:"state-power-pose-replication",title:"Ranehill et al. · 2015 · Robustness of power posing: no effect on hormones and risk tolerance",url:"https://faculty.haas.berkeley.edu/dana_carney/ranehill.pdf",type:"research",finding:"With 200 participants (102 men, 98 women), a blinded experimenter and longer poses, power posing did not change testosterone (p = .162), cortisol (p = .272) or financial risk taking (p = .215). Self-reported feelings of power did increase (p = .017).",limitation:"One conceptual replication in a lab setting; it does not test every possible outcome of posture. The full article was read."},{id:"state-music-stress",title:"de Witte et al. · 2020 · Music interventions and stress-related outcomes: two meta-analyses (Health Psychology Review)",url:"https://pure.uva.nl/ws/files/58927620/Effects_of_music_interventions_on_stress_related_outcomes_a_systematic_review_and_two_meta_analyses.pdf",type:"research",finding:"104 randomized trials, 9,617 participants, 327 effect sizes. Music interventions reduced physiological stress (d = 0.380) and psychological stress (d = 0.545). Among physiological outcomes, effects were larger on heart rate (d = 0.456) than on blood pressure (d = 0.343) or hormone levels (d = 0.349). Slower music (60–80 beats per minute) showed a trend toward larger psychological effects; self-selected versus researcher-selected music made no significant difference.",limitation:"Many trials were in health-care settings and some categories had few effect sizes. The analyses focus on stress reduction, not on music for raising energy. The abstract and summary were read."},{id:"state-cyclic-sighing",title:"Balban et al. · 2023 · Brief structured respiration practices and mood (Cell Reports Medicine)",url:"https://pmc.ncbi.nlm.nih.gov/articles/PMC9873947/",type:"research",finding:"In a remote randomized trial, 108 participants practiced 5 minutes a day for 28 days: cyclic sighing (n = 30), box breathing (n = 21), cyclic hyperventilation with retention (n = 33) or mindfulness meditation (n = 24). Average daily increase in positive affect: breathwork combined 1.91 versus mindfulness 1.22; cyclic sighing 1.89, box breathing 1.84, cyclic hyperventilation 1.97. Breathwork reduced resting respiratory rate more than mindfulness; state anxiety fell similarly in all groups.",limitation:"Small groups, remote delivery with self-reported adherence, four weeks only and no follow-up. Participants were healthy volunteers, so the results say nothing about anxiety or panic disorders. The full article was read on PubMed Central."},{id:"state-affect-labeling",title:"Lieberman et al. · 2007 · Putting feelings into words: affect labeling and the amygdala (Psychological Science)",url:"https://sanlab.psych.ucla.edu/wp-content/uploads/sites/31/2015/05/Lieberman_AL-2007.pdf",type:"research",finding:"In an fMRI study with 30 adults viewing emotional faces, choosing a word for the emotion (affect labeling) produced less amygdala activity than choosing a gender label or matching faces. The right ventrolateral prefrontal cortex was more active during affect labeling, and its activity was inversely related to amygdala activity.",limitation:"A single brain-imaging session with a small sample; subjective distress was not measured in this study, and brain activity is not the same as how someone feels. The full article was read."},{id:"state-labeling-review",title:"Torre & Lieberman · 2018 · Affect labeling as implicit emotion regulation (Emotion Review)",url:"https://journals.sagepub.com/doi/10.1177/1754073917742706",type:"research",finding:"A review arguing that putting feelings into words can lower emotional intensity across self-report, physiological responses, brain activity and behavior, with effects comparable to explicit strategies such as reappraisal, even though it rarely feels like regulation. People tend to predict that labeling will intensify their feelings.",limitation:"A narrative review, not a meta-analysis; it gives no pooled effect size and notes many open questions about when and for whom labeling works. The abstract was read."},{id:"state-gratitude-meta",title:"Cregg & Cheavens · 2021 · Gratitude interventions for depression and anxiety: a meta-analysis",url:"https://link.springer.com/article/10.1007/s10902-020-00236-6",type:"research",finding:"27 studies, 3,675 participants. Gratitude interventions had a small effect on symptoms of depression and anxiety at post-test (g = −0.29) and at follow-up (g = −0.23). Effects were larger against waitlist controls than against active control conditions.",limitation:"The authors recommend that people seeking to reduce depression or anxiety use interventions with stronger evidence; part of the benefit may reflect expectation effects. The abstract was read."},{id:"state-gratitude-expressed",title:"Kirca, Malouff & Meynadier · 2023 · Expressed gratitude interventions and well-being: a meta-analysis",url:"https://link.springer.com/article/10.1007/s41042-023-00086-6",type:"research",finding:"25 randomized samples, 6,745 participants. Expressing gratitude improved well-being compared with neutral conditions (g = 0.22), including happiness (g = 0.16), life satisfaction (g = 0.22) and positive affect (g = 0.21). Benefits appeared even when the gratitude was not delivered to the other person, and intervention length did not significantly change the effect.",limitation:"Small average effects; the studies tested writing or expressing gratitude to others, not the exact morning routine in this course. The abstract was read."},{id:"state-positive-self-statements",title:"Wood, Perunovic & Lee · 2009 · Positive self-statements: power for some, peril for others (Psychological Science)",url:"https://journals.sagepub.com/doi/10.1111/j.1467-9280.2009.02370.x",type:"research",finding:"In a survey (249 students) people reported using positive self-statements and believing they help. In an experiment (68 students), repeating “I’m a lovable person” 16 times made participants with low self-esteem feel worse than those who did not repeat it, while those with high self-esteem felt somewhat better. In a third study (116 students), low self-esteem participants fared better when allowed to consider ways the statement was both true and not true.",limitation:"Canadian undergraduates, one statement, short-term mood; it does not show that every positive statement is harmful. The abstract and the full article were read."},{id:"state-mental-contrasting",title:"Wang, Wang & Gai · 2021 · Mental contrasting with implementation intentions: a meta-analysis",url:"https://www.frontiersin.org/journals/psychology/articles/10.3389/fpsyg.2021.565202/full",type:"research",finding:"21 studies with 24 effect sizes and 15,907 participants. Imagining a desired future, then the obstacles in the way, combined with if-then plans, had a small-to-medium average effect on goal attainment (g = 0.336). Face-to-face delivery (g = 0.465) worked better than written materials (g = 0.277).",limitation:"A small number of studies; the two largest studies made up most participants and were excluded from moderator analyses. It tests mental contrasting, not the Dickens process itself. The article was read."},{id:"state-self-compassion-motivation",title:"Breines & Chen · 2012 · Self-compassion increases self-improvement motivation",url:"https://hqinstitute.org/wp-content/uploads/sites/5/2022/09/Breines_Chen_SelfCompMotivation.2012.pdf",type:"research",finding:"Four experiments. Taking a self-compassionate view of a weakness, a moral transgression or a failed test increased belief that the weakness could change, motivation to make amends and avoid repeating the mistake, and time spent studying after a failed test, compared with self-esteem boosting or control conditions.",limitation:"Mostly university students plus one online adult sample; short-term motivation and behavior in the lab, not long-term change. The article was read."},{id:"state-power-pose-review",title:"The Psychologist (British Psychological Society) · A decade of power posing: where do we stand?",url:"https://www.bps.org.uk/psychologist/decade-power-posing-where-do-we-stand",type:"guidance",finding:"Summarizes the debate: the original claim that expansive poses raise testosterone and lower cortisol largely failed to replicate, with a 2017 special issue finding virtually zero hormonal effect. Expansive posture does reliably change how powerful people feel, possibly partly by avoiding slumped, contracted postures.",limitation:"A magazine review of a contested literature, not a new study; the exact size of the felt-power effect is still debated."},{id:"state-nhs-breathing-tips",title:"NHS inform (Scotland) · Tips for doing breathing and relaxation exercises",url:"https://www.nhsinform.scot/healthy-living/mental-wellbeing/breathing-and-relaxation-exercises/tips-for-doing-breathing-and-relaxation-exercises/",type:"guidance",finding:"Advises stopping if you feel any discomfort or pain during breathing exercises, staying seated or lying down for a moment afterwards to avoid dizziness, and speaking to a GP practice first if you have a medical condition such as breathing problems.",limitation:"General public guidance from the Scottish NHS; it is not specific to cyclic sighing or to energizing breathwork."},{id:"state-nhs-panic",title:"NHS · Panic disorder",url:"https://www.nhs.uk/mental-health/conditions/panic-disorder/",type:"guidance",finding:"Panic disorder means regularly having sudden attacks of panic or fear. Attacks are frightening but not dangerous. The NHS recommends seeing a GP; the main treatments are talking therapy such as cognitive behavioural therapy and, for some people, medication. Slow, deep breathing is one of the self-help steps during an attack.",limitation:"UK health service guidance; services and phone numbers differ by country. In an emergency, contact your local emergency number."},{id:"state-robbins-triad",title:"Tony Robbins · Discover your peak state (tonyrobbins.com)",url:"https://www.tonyrobbins.com/blog/discover-your-peak-state",type:"technique",finding:"Robbins presents three forces that he says control emotions: physiology, language and focus. He teaches that by changing them deliberately you can reshape your daily emotional experience and reach a more resourceful state.",limitation:"A coaching model from the author’s own site, not a scientific theory; the triad as a whole has not been tested. Each lever is checked against separate research in this course."},{id:"state-robbins-questions",title:"Tony Robbins · How to ask questions and better yourself every day (tonyrobbins.com)",url:"https://www.tonyrobbins.com/blog/ask-better-questions",type:"technique",finding:"Robbins argues that the questions you habitually ask yourself act as filters that direct focus and interpretation, and recommends replacing disempowering questions with empowering ones as a daily practice.",limitation:"Coaching advice; no study has tested Robbins’s question sets directly. Related research on attention is cited separately."},{id:"state-robbins-words",title:"Tony Robbins · Harness the power of words: transform your words in 4 steps (tonyrobbins.com)",url:"https://www.tonyrobbins.com/blog/transform-your-words-in-4-steps",type:"technique",finding:"Describes transformational vocabulary: notice the habitual words you attach to difficult emotions and swap intense labels for milder ones (for example “down” instead of “depressing”, “frustrated” instead of “enraged”), practiced as a 10-day challenge.",limitation:"Coaching advice; the vocabulary challenge itself has not been studied. Related research on affect labeling and reappraisal is cited separately."},{id:"state-robbins-rituals",title:"Tony Robbins · Morning rituals that can change your life (tonyrobbins.com)",url:"https://www.tonyrobbins.com/blog/whats-your-morning-ritual",type:"technique",finding:"Distinguishes affirmations (encouraging words that are simply said) from incantations (statements spoken while fully embodying them with voice, posture and movement), and argues that affirmations alone may fail as a transformative technique.",limitation:"Coaching advice; incantations have not been tested in research. Evidence on positive self-statements (Wood et al., 2009) suggests believability matters."},{id:"state-robbins-priming",title:"Tony Robbins · Train your brain in minutes (tonyrobbins.com)",url:"https://www.tonyrobbins.com/health-vitality/train-your-brain-in-minutes-4/",type:"technique",finding:"Describes priming as a roughly 10-minute daily practice of directed breathing and movement, gratitude and visualization, intended to adjust thoughts and emotions toward a peak state.",limitation:"The author’s own site; the page gives few step details and priming as a package has not been studied."},{id:"state-priming-cnbc",title:"CNBC · 2019 · Tony Robbins’ 10-minute morning routine (Grogan)",url:"https://www.cnbc.com/2019/04/09/tony-robbins-10-minute-morning-routine-to-get-in-a-peak-state.html",type:"technique",finding:"A written summary of Robbins’s priming routine in under 10 minutes: rounds of forceful breathing with arm movements, reflecting on three things you are grateful for, a visualization of light filling the body, and focusing on three goals as if already achieved.",limitation:"A journalist’s summary, not a study; the healing visualization is not evidence of any effect on illness, and fast breathing can cause dizziness."},{id:"state-robbins-dickens",title:"Tony Robbins · Unlocking potential: the Dickens process (tonyrobbins.com)",url:"https://www.tonyrobbins.com/personal-growth/unlocking-potential",type:"technique",finding:"Describes the Dickens process, named after the ghosts of Christmas past, present and future: identify a limiting belief, then examine what it has cost you in the past, what it costs you and people you love now, and what it will cost in one, three, five and ten years, before replacing it with a new belief.",limitation:"Coaching advice; the Dickens process has not been studied. In its intense form it may feel distressing, so this course uses a gentler, shorter version."},{id:"state-robbins-standards",title:"Tony Robbins · How to raise your standards and upgrade your life (tonyrobbins.com)",url:"https://www.tonyrobbins.com/blog/how-to-raise-your-standards",type:"technique",finding:"Robbins argues that lasting change comes from raising your standards: turning vague “shoulds” into non-negotiable “musts”, updating the beliefs behind them and focusing on key areas such as relationships, career and health.",limitation:"Coaching advice without research testing; this course pairs it with evidence on mental contrasting and self-compassion."},{id:"state-stanford-sighing",title:"Stanford Medicine · 2023 · Cyclic sighing can help breathe away anxiety",url:"https://med.stanford.edu/news/insights/2023/02/cyclic-sighing-can-help-breathe-away-anxiety.html",type:"technique",finding:"Describes cyclic sighing as studied by David Spiegel, Andrew Huberman and Melis Yilmaz Balban: inhale through the nose, take a second deeper inhale to fully expand the lungs, then exhale slowly through the mouth, repeated for about five minutes a day. In their month-long trial it improved positive mood more than mindfulness meditation.",limitation:"An institutional news summary. The trial excluded people with moderate to severe psychiatric conditions; the method has not been tested as a treatment for anxiety disorders."}],de={id:"state",title:"Change Your State",subtitle:"Shift how you feel on purpose, in minutes.",description:"Learn short, practical ways to move from tense or flat to steady and ready, using your body, your focus and your words. Each tool from coach Tony Robbins is checked against the research, including the parts that did not hold up.",scope:"For adults who want everyday tools to shift mood and energy. This is education, not diagnosis or treatment, and it is not a treatment for anxiety disorders, panic disorder or depression; it does not replace therapy or medication. Stop any breathing drill at once if you feel dizzy, light-headed, tingly or short of breath, return to normal breathing and sit down; if you have a heart or lung condition or are pregnant, check with a clinician before trying energizing breathwork, and never practice it while driving or in water. If you are in crisis or have thoughts of harming yourself, contact your local emergency number (911 in the US, 112 in Türkiye and much of Europe).",outcome:"A personal toolkit of seven state-changers you have tried: a triad check, a two-minute body reset, cyclic sighing, a set of better questions, a label-and-reframe routine, a ten-minute morning priming with one honest incantation, and one new standard with a daily action, plus a clear picture of what each tool can and cannot do.",photo:{id:"1500080628126-901233e80205",alt:"A woman standing on a wooden dock at golden hour, raising one hand toward the light"},lessons:[{id:"state-1",title:"State colors everything",minutes:7,goal:"Notice the state you are in right now and name the three levers that shape it: body, focus and words.",reading:["Your state is the mix of mood, energy and body tension you are in right now. The same late train, blunt email or spilled juice lands very differently when you feel rested and steady than when you feel drained and tense. A review of about 35 years of research by Jennifer Lerner and colleagues concluded that emotions are powerful and predictable drivers of decisions, sometimes helpful and sometimes harmful. So your state is not a side issue. It quietly shapes what you notice, what you decide and how you treat the people around you.","Tony Robbins, the coach and author, teaches that your state is not simply something that happens to you. In his model, three forces shape it: physiology (how you breathe, stand and move), focus (what you pay attention to) and language (the words and meanings you give events). Change one of them and the state tends to shift. This course takes his triad seriously but checks each part against research. Some parts hold up well, some only partly, and one popular idea did not replicate. You will get short, practical tools and an honest picture of what each can do."],deeper:[{heading:"Why a few minutes matter",paragraphs:["Feelings from one situation often spill into the next. Irritation from a tense morning can color how you read a colleague’s neutral message an hour later. Research on decision making calls these incidental emotions and finds that they often carry over without our noticing. That is one reason a short reset before an important conversation can be worth it.","Timing also matters. In James Gross’s research on emotion regulation, changing how you interpret a situation reduced both the feeling and its outward expression, while simply hiding a feeling left it in place and raised physiological stress. Acting early, before a state hardens into a mood, gives you more room to steer."],visual:{kind:"table",title:"One moment, two states",columns:["Moment","Drained, tense state","Steady, resourced state"],rows:[["The train is 20 minutes late","This day is ruined.","Annoying. I will message ahead and use the time."],["A blunt email from your manager","They think I am useless.","Short email. I will ask what they need."],["Your child melts down at dinner","I cannot cope with this.","Tired kid. Lower the volume, then deal with it."]],note:"Illustrative examples. The event stays the same; the state changes what you notice and how you respond."}},{heading:"What the triad is, and what it is not",paragraphs:["The triad is a teaching model, not a tested scientific theory. Still, each lever lines up with a real research field: movement, posture and breathing; attention; and the way we label and interpret events. The next lessons take one lever at a time and look at what the studies found.","The aim is not to feel great all the time. Sadness, anger and worry carry useful information. The aim is choice: noticing when a state is not serving you and having a few reliable ways to shift it."]}],example:{title:"Dana, 34, emergency room nurse",text:"Dana finishes a hard night shift and has to call her landlord about a leak. She notices she is slumped over the steering wheel, replaying a rude comment from a patient and muttering that everyone is against her. Before dialing, she runs a quick triad check. Body: she sits up, rolls her shoulders and takes a slow breath. Focus: she asks what she actually needs from this call, which is a plumber by Thursday. Words: she swaps “everyone is against me” for “it was a rough shift”. The call is still a little tense, but she stays clear and gets a date. Nothing magical happened; she simply stopped letting the last patient decide how she spoke to the next person."},practice:["Pause now and rate your energy from 0 to 10 and your tension from 0 to 10.","Check the triad: notice how you are sitting and breathing, what you are focused on, and which words are running in your head.","Change one lever for 60 seconds, such as standing and stretching or rephrasing one sentence, then rate energy and tension again."],reflection:"Which of the three levers do you usually reach for, and which do you tend to forget?",question:"In Robbins’s triad, which of these is a way to change your state?",options:["Wait until your circumstances change on their own.","Push the feeling away and act as if it is not there.","Change your body, your focus, or the words and meaning you give an event."],correct:2,feedback:"Right. The triad points to three levers you can move: physiology, focus and language. Hiding a feeling tends to leave it in place, and waiting for circumstances hands the steering wheel to chance.",takeaway:"Your state shapes your day, and you have three levers to shift it: body, focus and words.",sources:["state-emotion-decisions","state-reappraisal-gross","state-robbins-triad"],visual:{kind:"cycle",title:"How a state keeps itself going",nodes:[{label:"Body",text:"Breath, posture, movement and muscle tension."},{label:"Focus",text:"What you notice, replay and look for."},{label:"Words and meaning",text:"The labels and stories you give events."},{label:"Feeling",text:"The state you actually experience."},{label:"Action",text:"What you then do, which feeds back into body and focus."}],center:"Your state",note:"Based on Tony Robbins’s triad, a coaching model rather than a tested theory. Each lever is checked against research in the lessons that follow."},technique:{name:"The triad state check",origin:"Tony Robbins · Discover your peak state, tonyrobbins.com",steps:["Stop for a moment and name the state you are in with one word.","Body: notice your posture, breathing and where you hold tension.","Focus: notice what you are paying attention to or replaying.","Words: notice the phrases you are using in your head about the situation.","Pick the easiest lever to move and change it deliberately for about a minute.","Name your state again and notice any difference, however small."],evidence:"The triad is a coaching model and has not been tested as a whole. Its parts line up with research on movement, attention and reappraisal, which show small to moderate short-term effects on feelings in studies. It is a way to organize your options, not a guaranteed switch.",sourceId:"state-robbins-triad"},photo:{id:"1758192139097-1e7f30c2498e",alt:"A man crossing a quiet city street under sunlit trees"}},{id:"state-2",title:"The body goes first",minutes:8,goal:"Use movement, posture and music to shift your energy in about two minutes, and know which body claims hold up.",reading:["Robbins often puts the physiology lever simply: the way you move changes the way you feel. Here the research is fairly kind to him. A meta-analysis by Jennifer Reed and Deniz Ones pooled 158 studies with more than 13,000 participants and found that a single bout of aerobic exercise raised energetic, positive feelings with a moderate average effect. Low-intensity sessions of up to about 35 minutes worked well, and the lift lasted at least half an hour. Meanwhile, people in the control groups who stayed still tended to drift slightly downward.","Your face and posture matter too, but less than popular claims suggest. A review of 136 studies found that facial expressions change feelings by a small, variable amount. A large test across 19 countries found that deliberately smiling nudged happiness up. Power posing is the cautionary tale: a replication with 200 people found no effect on testosterone, cortisol or risk taking, although people did feel more powerful. So stand tall if it helps you feel more capable, but do not expect it to change your hormones."],deeper:[{heading:"What held up and what did not",paragraphs:["The original 2010 power-pose study claimed two minutes of an expansive stance raised testosterone and lowered cortisol. Later studies largely failed to find those hormone changes. What does replicate is a change in how powerful people feel, possibly partly because slumped, contracted postures make people feel worse.","That leaves a modest but useful message: posture and a real smile are small nudges. Movement that raises your heart rate is a bigger one."],visual:{kind:"compare",title:"Body and state: the honest version",left:{label:"Supported (small to moderate)",items:["A brisk walk or short aerobic bout lifts energy for a while.","Deliberately smiling nudges happiness up a little.","An open, upright posture can make you feel more powerful."]},right:{label:"Not supported",items:["Two minutes of posing changes testosterone or cortisol.","Posture alone reliably changes risk taking or performance.","One burst of movement treats depression or an anxiety disorder."]},note:"Based on meta-analyses of exercise and facial feedback and a large power-posing replication."}},{heading:"Music as a shortcut",paragraphs:["A meta-analysis of 104 randomized trials with over 9,600 people found that music interventions reduced stress, with a medium effect on how stressed people felt and a smaller effect on body measures such as heart rate. Slower music, around 60 to 80 beats per minute, showed a trend toward larger effects on felt stress.","The trials studied calming, not energizing. For a lift, pairing a song with movement combines two levers. For winding down, choose something slow."],visual:{kind:"bars",title:"Music interventions and stress: average effects",bars:[{label:"Felt (psychological) stress",value:.545,display:"d = 0.545"},{label:"Heart rate",value:.456,display:"d = 0.456"},{label:"Body stress measures overall",value:.38,display:"d = 0.380"},{label:"Blood pressure",value:.343,display:"d = 0.343"}],note:"104 randomized trials, 9,617 participants (de Witte et al., 2020). Effect sizes for stress reduction compared with controls; many trials were in health-care settings.",sourceId:"state-music-stress"}},{heading:"Over weeks, not only minutes",paragraphs:["Regular activity matters beyond the quick lift. An umbrella review of 97 reviews found that physical activity programs reduced symptoms of depression, anxiety and distress, with shorter, more intense programs showing larger effects. Most of those reviews were of low quality, and exercise does not replace treatment when you need it."]}],example:{title:"Marcus, 41, warehouse supervisor",text:"At 2 p.m. Marcus hits his usual slump right before the weekly safety briefing he has to lead. He used to stand at the front with his arms folded, voice flat, hoping it would be over quickly. This week he tries a two-minute reset first. He takes the stairs to the loading dock and back at a brisk pace, puts on one upbeat song in his earbuds, and rolls his shoulders open while it plays. He does not feel transformed, but his energy moves from about a 3 to a 5 out of 10, and his voice sounds more like his own. Two people ask questions afterwards, which rarely happens. He decides to keep the stairs and drop the expectation of a miracle."},practice:["Stand up, roll your shoulders back and walk briskly for two minutes, using stairs, a hallway or the street.","Play one song that matches the state you want, slow for calm or upbeat for energy, and move to it.","Rate your energy from 0 to 10 before and after, and note which part made the most difference."],reflection:"When your energy dips, what is the smallest movement you could realistically do where you are?",question:"What did a large replication of power posing find?",options:["Hormones changed strongly after two minutes of posing.","People felt more powerful, but hormones and risk taking did not change.","Posture has no link to feelings at all."],correct:1,feedback:"Correct. With 200 participants, power posing did not change testosterone, cortisol or risk taking, but people reported feeling more powerful. Treat posture as a small nudge, not a hormone switch.",takeaway:"Move first: a few minutes of motion is one of the most reliable ways to shift how you feel.",sources:["state-acute-exercise","state-facial-feedback","state-many-smiles","state-power-pose-replication","state-power-pose-review","state-music-stress","state-exercise-mental-health","state-robbins-triad"],visual:{kind:"steps",title:"A two-minute body reset",steps:[{label:"Notice",text:"How is your body holding this state? Slumped, clenched, shallow breath?"},{label:"Open",text:"Stand, lengthen your spine and let your shoulders drop back."},{label:"Move",text:"Walk briskly, climb stairs or shake out your arms for one to two minutes."},{label:"Add a cue",text:"Play one song or try a real smile while you move."},{label:"Check",text:"Rate your energy again and notice what changed."}],note:"Single bouts of aerobic exercise raised energetic feelings with a moderate average effect in a meta-analysis of 158 studies; posture and smiling are smaller nudges."},technique:{name:"Change your physiology",origin:"Tony Robbins · Discover your peak state, tonyrobbins.com",steps:["Notice how your body is holding your current state.","Stand up and adopt the posture you would have if you already felt steady and capable.","Move with some intensity for one to two minutes: brisk walking, stairs or shaking out your arms.","Let your breath deepen, with a slow, long exhale.","Add a genuine smile or a song that fits the state you want.","Check in and carry the new posture into your next task."],evidence:"A single bout of aerobic exercise raised energetic, positive feelings with a moderate average effect that lasted around half an hour. Facial expressions have a small, variable effect, and expansive postures changed feelings of power but not hormones or risk taking in a large replication.",sourceId:"state-robbins-triad"},photo:{id:"1692933216024-8de20c41321a",alt:"A woman walking along a boardwalk through green plants"}},{id:"state-3",title:"Calm in two breaths",minutes:8,goal:"Learn cyclic sighing and practice it for five minutes, stopping at once if you feel dizzy.",reading:["Breathing is the one part of your stress response you can steer directly. Cyclic sighing uses two breaths in and one long breath out: inhale through the nose, top up with a second short inhale, then exhale slowly through the mouth until your lungs feel empty. Researchers David Spiegel, Andrew Huberman and Melis Yilmaz Balban at Stanford tested it against other methods. In their trial, 108 people practiced for five minutes a day for 28 days, randomly assigned to cyclic sighing, box breathing, fast cyclic hyperventilation or mindfulness meditation.","The breathing groups together showed a larger daily rise in positive mood than the mindfulness group and a greater drop in resting breathing rate. Anxiety fell by a similar amount in all groups. The three breathing methods differed only a little from each other. The limits matter: the groups were small, practice was self-reported, the study lasted four weeks and people with moderate to severe psychiatric conditions were excluded. Cyclic sighing is a promising everyday tool, not a treatment for anxiety or panic disorders."],deeper:[{heading:"How to do it",paragraphs:["The first inhale can be fairly full; the second is a short sip that tops the lungs up. The exhale is the important part: slower and longer than the inhale, like a relaxed sigh. Go at a comfortable pace, not as fast as possible.","The study tested five minutes a day. In a tense moment, one to three cycles are a sensible small dose, but that exact use was not tested."],visual:{kind:"steps",title:"Cyclic sighing, one cycle",steps:[{label:"Settle",text:"Sit or stand comfortably and let your shoulders drop."},{label:"Inhale",text:"Breathe in slowly through your nose."},{label:"Top up",text:"Take a second, shorter inhale through the nose to fill your lungs."},{label:"Long exhale",text:"Breathe out slowly through your mouth until your lungs feel empty."},{label:"Repeat",text:"Continue for up to five minutes, then breathe normally."}],note:"As described by Stanford Medicine. Stop and breathe normally if you feel dizzy or uncomfortable."}},{heading:"Safety and limits",paragraphs:["NHS guidance on breathing exercises is simple: stop if you feel discomfort, stay seated for a moment before standing, and talk to your doctor first if you have a breathing or heart condition. Tingling, light-headedness or a racing heart mean you are overdoing it; return to normal breathing. This course does not teach the fast hyperventilation method from the study.","If you have repeated, unexpected panic attacks, the NHS recommends seeing a doctor. Talking therapy such as cognitive behavioral therapy and, for some people, medication are the treatments with evidence. Slow breathing can support you during an attack, but it does not replace that care. In a crisis, contact your local emergency number."]}],example:{title:"Aylin, 27, junior lawyer",text:"Aylin has a habit of holding her breath while reading hostile emails from opposing counsel. She decides to try cyclic sighing for five minutes each morning on the bus for a month, and to use two or three cycles before replying to difficult emails. The first mornings feel awkward and she worries people can hear her. By the second week she can do it quietly. She notices that when an aggressive email arrives, the long exhale gives her a small gap before she types. Her replies get shorter and calmer. She still feels the jolt of anger; it just no longer drives her fingers. On one day she felt light-headed, so she stopped and breathed normally, and went slower the next time."},practice:["Sit comfortably and do three slow cycles: nose inhale, short top-up inhale, long mouth exhale.","If that feels fine, set a five-minute timer and continue at a relaxed pace, stopping if you feel dizzy.","Afterwards, rate how calm you feel from 0 to 10 and choose one moment tomorrow to use two or three cycles."],reflection:"In which daily moment would a slow, long exhale help you most?",question:"What should you do if you feel dizzy during cyclic sighing?",options:["Stop, breathe normally and stay seated for a moment.","Push through, because dizziness means it is working.","Breathe faster to balance it out."],correct:0,feedback:"Yes. Dizziness or tingling is a signal to stop and return to normal breathing. The method is meant to be gentle and slow, not forced.",takeaway:"Two breaths in, one long breath out: a small, portable way to settle your body.",sources:["state-cyclic-sighing","state-stanford-sighing","state-nhs-breathing-tips","state-nhs-panic"],visual:{kind:"bars",title:"Daily rise in positive mood over 28 days (5 minutes a day)",bars:[{label:"Cyclic sighing",value:1.89,display:"1.89"},{label:"Box breathing",value:1.84,display:"1.84"},{label:"Cyclic hyperventilation",value:1.97,display:"1.97"},{label:"Mindfulness meditation",value:1.22,display:"1.22"}],note:"Average daily increase in positive affect score by group (Balban et al., 2023; 108 participants). The breathing groups differed little from each other; combined, they beat mindfulness (1.91 versus 1.22). Small groups, four weeks, healthy volunteers.",sourceId:"state-cyclic-sighing"},technique:{name:"Cyclic sighing",origin:"David Spiegel, Andrew Huberman & Melis Yilmaz Balban · Stanford Medicine (2023)",steps:["Sit or stand comfortably and relax your shoulders.","Inhale slowly through your nose.","Add a second, shorter inhale through your nose to fill your lungs.","Exhale slowly and fully through your mouth, longer than the inhale.","Repeat at a relaxed pace for up to five minutes.","Stop and breathe normally if you feel dizzy, tingly or uncomfortable."],evidence:"In a small month-long trial with healthy volunteers, five minutes a day of breathwork, including cyclic sighing, raised positive mood more than mindfulness and lowered resting breathing rate. It has not been tested as a treatment for anxiety or panic disorders.",sourceId:"state-stanford-sighing"},photo:{id:"1763713383838-5cd702c13160",alt:"A woman with her eyes closed, hugging herself gently in a forest"}},{id:"state-4",title:"Change your focus and your questions",minutes:8,goal:"Catch one draining question you keep asking yourself and swap it for one that points your attention somewhere useful.",reading:["Robbins argues that much of thinking is asking and answering questions, and that the questions you habitually ask decide what you focus on. Ask yourself why this always happens to you, and your mind will dutifully search for proof that you are unlucky. Ask what one useful step would be, and it searches for options instead. He suggests treating questions as a daily practice: a few in the morning to set direction and a few in the evening to notice what went well and what you learned.","Research on attention supports the direction, if not the drama. A meta-analysis by Thomas Webb and colleagues pooled 190 studies of emotion regulation. Distraction, deliberately turning attention to something else, helped a little on average. Concentrating on the upsetting situation and your feelings about it made things slightly worse. A good question is a gentle way to move attention. It is not about ignoring real problems. It points you toward the part you can act on, so you can come back to the hard part with a steadier head."],deeper:[{heading:"What the research says about attention",paragraphs:["In Webb’s meta-analysis, attention strategies as a whole averaged out to zero effect, because the two directions cancel each other: moving attention away helped a little, and dwelling on the emotional side of the situation hurt a little.","Distraction is a short-term tool. It buys time, but problems still need solving later. Questions that lead to a next step do both: they shift focus and move you forward."],visual:{kind:"table",title:"Where attention goes, and what it did on average",columns:["Strategy","What it means","Average effect"],rows:[["Distraction","Turning attention to something neutral or pleasant","Small benefit (d = 0.27)"],["Concentration","Dwelling on the emotional situation and your feelings","Slightly worse (d = −0.26)"],["Attention strategies overall","Both directions pooled together","About zero (d = 0.00)"]],note:"Webb, Miles & Sheeran (2012), 190 studies, mostly short laboratory experiments."}},{heading:"Morning and evening questions",paragraphs:["A few examples in ODA’s words. Morning: What am I looking forward to today? What is one thing I am grateful for? What is the one task that would make today feel worthwhile? Evening: What did I give today? What did I learn? What went better than I expected?","If the honest answer is “nothing”, shrink the question: what is one small thing that was okay? A question that demands fake cheer can feel hollow. One that invites an honest, specific answer is easier to believe."]},{heading:"Common mistakes",paragraphs:["Using questions to deny a real problem, or turning them into harsh interrogation (“What is wrong with you?”), defeats the point. The best questions sound like something a kind, practical friend would ask."]}],example:{title:"Javier, 38, sales representative",text:"Javier loses a deal he had worked on for three months. On the drive home he hears himself asking, “Why do I always blow the big ones?” and notices that his mind is serving up every past failure in order. At a red light he tries a different question: “What is one thing I can learn from this deal?” The answer comes slowly: he never spoke to the person who actually signs off on budgets. Then a second question: “What is one step I can take tomorrow?” He decides to map the decision makers on his two open deals. He still feels disappointed that evening, but he sleeps better, and the next morning he has a short list instead of a long story about being unlucky."},practice:["Write down one question you often ask yourself when things go wrong.","Rewrite it as a question that points to learning or a next step you control.","Pick three morning questions and ask them tomorrow before you check your phone."],reflection:"What question has been running your focus lately, and where has it been leading you?",question:"Which question is most likely to move your focus toward options?",options:["Why does this always happen to me?","Who is responsible for ruining my day?","What is one small step I can take in the next ten minutes?"],correct:2,feedback:"Exactly. A question about a small, doable step directs attention to what you can control. The other two send your mind searching for proof of bad luck or someone to blame.",takeaway:"Change the question and you change where your attention goes.",sources:["state-robbins-questions","state-regulation-meta"],visual:{kind:"compare",title:"Questions that drain and questions that direct",left:{label:"Questions that drain",items:["Why does this always happen to me?","What is wrong with me?","Who is to blame for this?"]},right:{label:"Questions that direct",items:["What is one thing I can do in the next ten minutes?","What would I tell a friend in this spot?","What is still going right?","What can I learn from this?"]},note:"Example questions in ODA’s words, inspired by Tony Robbins’s idea of empowering questions."},technique:{name:"Empowering questions",origin:"Tony Robbins · How to ask questions and better yourself every day, tonyrobbins.com",steps:["Notice the question your mind is repeating when you feel stuck or upset.","Ask yourself where that question is pointing your attention.","Replace it with a question that points to learning, gratitude or a next step you control.","Answer it honestly and specifically, even if the answer is small.","Build a short set of morning and evening questions and use them daily for a week."],evidence:"No study has tested Robbins’s question sets directly. Research on attention shows that where you put it changes feelings: moving attention away from the upsetting side of a situation helped a little on average, while dwelling on the emotion made things slightly worse.",sourceId:"state-robbins-questions"},photo:{id:"1543379232-77ee894c85dd",alt:"A woman in a knit hat facing the low sun"}},{id:"state-5",title:"Words and meaning",minutes:9,goal:"Name what you feel in a word or two, then try one alternative meaning for the situation.",reading:["The third lever is language. Robbins suggests noticing the intense words you habitually attach to difficult moments and swapping them for milder, still honest ones: frustrated instead of enraged, a setback instead of a disaster. Research on naming feelings points the same way. In a brain-imaging study led by Matthew Lieberman, choosing a word for the emotion on a face produced less activity in the amygdala, a region involved in threat responses, than choosing a name for the person’s gender. A later review argued that putting feelings into words tends to lower their intensity, even though people expect it to do the opposite.","Meaning goes one step further. Psychologist James Gross calls it cognitive reappraisal: changing how you interpret a situation so that its emotional impact changes. In his work, reappraisal reduced both the feeling and its outward signs, while simply hiding a feeling did not reduce it inside. A meta-analysis of 190 studies found reappraisal had a small-to-moderate average effect, and taking another person’s perspective did slightly better. Reappraisal is not pretending. It is looking for an interpretation that is at least as true and more useful."],deeper:[{heading:"Label, then reframe",paragraphs:["Naming works best when it is specific. “Bad” tells you little; “embarrassed and a bit anxious” tells you more and often takes some of the heat out. Once the feeling has a name, you can ask what else the situation could mean.","You do not need a perfect word. A rough label, said calmly, is enough to start."],visual:{kind:"steps",title:"Label and reframe in about a minute",steps:[{label:"Pause",text:"Take one slow breath and notice that a feeling is here."},{label:"Name it",text:"Say or write it: I am noticing frustration and some worry."},{label:"Rate it",text:"Give it a number from 0 to 10."},{label:"Reframe",text:"Ask: what else could this mean, and how would a fair friend see it?"},{label:"Next step",text:"Choose one action that fits the new meaning."}],note:"Combines affect labeling (Lieberman) and cognitive reappraisal (Gross)."}},{heading:"Softening is not denying",paragraphs:["Robbins’s vocabulary challenge has not been studied directly; its closest research cousins are affect labeling and reappraisal. The key is accuracy. Calling a real danger “a bit awkward” is not reappraisal, it is denial. If someone is harming you or a situation is unsafe, the right move is action and support, not a softer word.","Hiding feelings is also different from reframing them. Suppressing a feeling reduced outward expression but did little for how people felt inside, and it raised physiological stress."]}],example:{title:"Priya, 45, school administrator",text:"Priya notices that she describes almost every scheduling problem as “a total disaster”, and that her shoulders climb toward her ears each time. For ten days she tries a small experiment. When a problem appears, she names the feeling first, usually “frustrated and rushed”, and then asks what else it could mean. A teacher calling in sick becomes “a staffing puzzle for the next hour” rather than “a disaster”. When a parent sends a sharp email, she reminds herself it is probably a worried parent, not an enemy. She is still busy and some days are still bad. But she snaps less at her team, and on day nine a colleague asks how she stays so calm."},practice:["Think of one situation from today that bothered you and name the feeling in one or two precise words.","Write one alternative interpretation that is at least as true as your first one.","List two intense words you use often and choose a milder, accurate replacement for each."],reflection:"Which word do you use most often for a bad moment, and is it accurate?",question:"Which of these is an example of cognitive reappraisal?",options:["Smiling in a meeting while you seethe inside.","Thinking: this blunt feedback is information about the draft, not a verdict on me.","Telling yourself nothing bad happened when it clearly did."],correct:1,feedback:"Correct. Reappraisal changes the meaning of a situation in a way that is still honest. Hiding a feeling is suppression, and pretending nothing happened is denial.",takeaway:"Name it, then find a truer, more useful meaning.",sources:["state-robbins-words","state-affect-labeling","state-labeling-review","state-reappraisal-gross","state-regulation-meta"],visual:{kind:"bars",title:"Changing meaning versus changing the response",bars:[{label:"Taking another perspective",value:.45,display:"d = 0.45"},{label:"Reappraising the situation",value:.36,display:"d = 0.36"},{label:"Reappraising your response",value:.23,display:"d = 0.23"},{label:"Modulating the response (overall)",value:.16,display:"d = 0.16"}],note:"Average effects on emotional outcomes in Webb, Miles & Sheeran (2012), 190 studies. Suppressing the experience of an emotion averaged −0.04 and suppressing thoughts about the event −0.12. Mostly short laboratory studies.",sourceId:"state-regulation-meta"},technique:{name:"Transformational vocabulary",origin:"Tony Robbins · Harness the power of words, tonyrobbins.com",steps:["For a few days, notice the intense words you use for frustrating or painful moments.","Pick two or three that come up most often.","Choose a milder replacement for each that is still honest, such as frustrated for enraged.","When the old word rises, say the new one instead, out loud or in your head.","Keep it up for ten days and notice any change in how intense moments feel."],evidence:"The vocabulary challenge itself has not been tested. Related research supports two parts of it: putting feelings into words tends to lower their intensity, and reinterpreting a situation had a small-to-moderate average effect on emotions. Hiding feelings does little for how you feel inside.",sourceId:"state-robbins-words"},photo:{id:"1534330207526-8e81f10ec6fc",alt:"A man standing quietly in front of a bright window"}},{id:"state-6",title:"Morning priming and incantations",minutes:10,goal:"Build a ten-minute morning priming and one honest, spoken incantation you can say without inner argument.",reading:["Robbins starts his days with what he calls priming, a routine of under ten minutes. As described in his materials and a CNBC summary, it combines rounds of forceful breathing with arm movements, three moments of gratitude from your past, present or future, a visualization of light filling the body, and focusing on three goals as if they were already done. The ODA version keeps the structure but offers slow breathing as the default, since fast breathing can cause dizziness. Its purpose is simple: decide your state before your inbox decides it for you.","Robbins distinguishes incantations from affirmations. An affirmation is a phrase you say; an incantation is spoken with your whole body, voice and conviction. That difference matters, but so does believability. In experiments by Joanne Wood and colleagues, people with low self-esteem who repeated “I’m a lovable person” 16 times felt worse afterwards, while people with high self-esteem felt slightly better. When a statement is far from what you believe, your mind argues back. So make incantations specific, believable and tied to action."],deeper:[{heading:"What the gratitude research shows",paragraphs:["Gratitude exercises help, but modestly. A meta-analysis of 25 randomized samples found that expressing gratitude improved well-being with a small average effect. Another, of 27 studies, found small effects on symptoms of depression and anxiety, with the authors recommending better-supported treatments for those conditions.","In your priming, you can make it concrete: picture one real scene, such as a friend’s laugh or a quiet coffee, and stay with it for a few breaths."],visual:{kind:"bars",title:"Expressing gratitude and well-being: average effects",bars:[{label:"Well-being overall",value:.22,display:"g = 0.22"},{label:"Life satisfaction",value:.22,display:"g = 0.22"},{label:"Positive feelings",value:.21,display:"g = 0.21"},{label:"Happiness",value:.16,display:"g = 0.16"}],note:"Kirca, Malouff & Meynadier (2023): 25 randomized samples, 6,745 participants, compared with neutral conditions. Small effects.",sourceId:"state-gratitude-expressed"}},{heading:"Affirmation or incantation?",paragraphs:["Wood’s third study offers a clue: people with low self-esteem did better when allowed to notice that a positive statement was both true and not entirely true. Leaving room for doubt reduces the inner argument.","Incantations themselves have not been tested. The version here borrows the embodiment from Robbins and the believability lesson from the research."],visual:{kind:"compare",title:"A plain affirmation versus an honest incantation",left:{label:"Plain affirmation that can backfire",items:["A sweeping claim, such as “I am perfect”.","Repeated passively while your mind argues.","Ignores doubt completely.","Not linked to anything you will do."]},right:{label:"Honest incantation",items:["Specific and believable, such as “I can make one brave call today”.","Spoken aloud with upright posture and a strong breath.","Makes room for doubt: “even if part of me is unsure”.","Tied to one action you will take today."]},note:"Based on Robbins’s distinction and on Wood et al. (2009). Example statements are ODA’s own."}},{heading:"About the light visualization and fast breathing",paragraphs:["Imagining light moving through your body can be a calming image, and you are welcome to use it. It cannot heal illness and is not a reason to delay medical care. Fast, forceful breathing can make you light-headed; keep rounds short, stop if you feel dizzy or tingly, and never do it while driving, in water or standing somewhere you could fall."]}],example:{title:"Sam, 52, bus driver",text:"Sam starts early shifts and used to spend his first twenty minutes scrolling news in the break room, arriving at the wheel already irritated. He tries a ten-minute priming at the kitchen table before leaving. Two minutes of cyclic sighing, since fast breathing made him dizzy the one time he tried it. Three minutes on three gratitude scenes: his granddaughter’s drawing, the dawn over the depot, his wife’s coffee. Three minutes picturing the route going well, including staying patient with the passenger who always argues about change. Then he stands, puts his shoulders back and says, “I can be steady today, even when people are not.” He notices his temper holds a little longer, and he keeps the routine on four mornings out of five."},practice:["Write three specific gratitude scenes from your past, present or future, one line each.","Draft one incantation that is specific, believable and tied to an action you will take today.","Set a ten-minute timer tomorrow morning and run the priming steps before looking at your phone."],reflection:"What would you say to yourself in the morning that you could actually believe?",question:"What did Wood and colleagues find about repeating a positive self-statement?",options:["It helped everyone, regardless of self-esteem.","It made people with low self-esteem feel worse, while people with high self-esteem felt slightly better.","It had no effect on anyone either way."],correct:1,feedback:"Right. Statements far from what you believe can trigger inner argument and backfire, especially for people who feel low about themselves. Specific, believable wording works with you rather than against you.",takeaway:"Prime your state before the day primes it for you, with words you can believe.",sources:["state-robbins-priming","state-priming-cnbc","state-robbins-rituals","state-positive-self-statements","state-gratitude-expressed","state-gratitude-meta","state-cyclic-sighing","state-nhs-breathing-tips"],visual:{kind:"steps",title:"Ten-minute priming, ODA version",steps:[{label:"Breathe (2 min)",text:"Cyclic sighing by default; if you try faster rounds, keep them short and stop if dizzy."},{label:"Gratitude (3 min)",text:"Relive three specific moments from your past, present or future."},{label:"Visualize (3 min)",text:"See today going well, including how you handle one likely obstacle."},{label:"Three outcomes (1 min)",text:"Name the three results that would make today worthwhile."},{label:"Incantation (1 min)",text:"Stand tall and say one believable commitment out loud."}],note:"Adapted from Tony Robbins’s priming. The package has not been studied; its parts have small or partial evidence."},technique:{name:"Priming",origin:"Tony Robbins · Train your brain in minutes, tonyrobbins.com",steps:["Sit upright with your eyes closed or lowered.","Breathe for about two minutes, slowly by default; stop if you feel dizzy.","Recall three specific moments you are grateful for and feel each one.","Optionally, picture a calming light or warmth moving through your body.","Focus on three outcomes for today and imagine them done, including handling one obstacle.","Stand and say one specific, believable incantation out loud with energy."],evidence:"Priming as a package has not been studied. Its parts have partial support: slow breathing lifted positive mood in a small month-long trial, gratitude exercises show small average effects, and positive self-statements can backfire for people with low self-esteem. Imagery of healing light cannot treat illness.",sourceId:"state-robbins-priming"},photo:{id:"1552838671-0e948f9f69b5",alt:"A woman sitting on green grass looking toward the morning sun"}},{id:"state-7",title:"The Dickens process and new standards",minutes:11,goal:"Use a short, kind version of the Dickens process to see what one old pattern costs, then set one new standard with a small daily action.",reading:["Robbins named the Dickens process after the three ghosts in A Christmas Carol. You pick one limiting belief or pattern, then look at what it has cost you in the past, what it costs you and people you love now, and what it will cost in one, three, five and ten years if nothing changes. Then you picture the future if you do change it. Robbins runs it with great intensity to create leverage. ODA uses a gentler version: short, written, factual, and spending most of its time on the future you want and a first step.","Robbins also argues that lasting change comes from raising your standards, turning a vague “should” into a clear “must”. Research suggests how to make that work without cruelty. A meta-analysis of mental contrasting, imagining a wished-for future and then the obstacles in the way, combined with if-then plans, found a small-to-medium average effect on reaching goals. And in four experiments by Juliana Breines and Serena Chen, treating a failure with self-compassion increased motivation to improve, including more study time after a failed test. You do not need shame to change."],deeper:[{heading:"Why kindness beats shame",paragraphs:["Harsh self-criticism can feel like the price of change. In Breines and Chen’s studies, though, self-compassion made people more willing to see a weakness as changeable, to make amends and to put in effort.","Self-compassion is not letting yourself off the hook. It is holding a high standard while treating yourself as someone worth helping."],visual:{kind:"compare",title:"Two ways to review an old pattern",left:{label:"Shame-driven review",items:["I am pathetic for still doing this.","A huge vow with no plan.","One slip means I have failed again."]},right:{label:"Self-compassionate review",items:["This matters, and I am human.","One standard and one small daily action.","A slip is information; I start again tomorrow."]},note:"Informed by Breines & Chen (2012), four experiments on self-compassion and motivation."}},{heading:"Turning a should into a standard",paragraphs:["A standard sticks when it becomes concrete. Decide on one clear standard, name the obstacle most likely to get in the way, and write an if-then plan for it. Then do the smallest daily action that proves the standard to yourself, and review it kindly each week."],visual:{kind:"cycle",title:"How a new standard sticks",nodes:[{label:"Decide",text:"One clear standard, such as: I reply to my family before my inbox."},{label:"Plan",text:"If the likely obstacle shows up, then I do a specific thing."},{label:"Act",text:"The smallest daily action that proves the standard."},{label:"Review",text:"Look kindly at what worked and adjust."}],center:"New standard",note:"Mental contrasting with if-then plans showed a small-to-medium average effect on goal attainment (g = 0.336) in a meta-analysis of 21 studies."}},{heading:"When to skip this exercise",paragraphs:["Looking at costs can stir strong feelings. If you are grieving, feeling very low or depressed, skip the future-cost step and go straight to the future you want, or leave this lesson for another day and talk to someone you trust or a professional. If you have thoughts of harming yourself, contact your local emergency number now."]}],example:{title:"Elena, 36, graphic designer",text:"Elena has told herself for years that she will update her portfolio “when I feel ready”. On a Sunday afternoon she sets a twenty-minute timer and writes the gentle Dickens process. Past: two job openings she never applied for. Present: she feels stuck and quietly resentful at work. Future unchanged: in five years, the same desk and the same story. She notices her chest tighten, so she moves on and spends most of the time on the future she wants: a studio role and work she is proud to show. Her new standard is that she works on her portfolio before social media on weekday mornings. Her first action is fifteen minutes on Monday. She misses Wednesday, shrugs, and starts again on Thursday."},practice:["Choose one pattern or belief that is holding you back and write it in one sentence.","Write two or three factual lines each for past, present and future costs, then twice as much about the future you want.","Turn it into one standard with an if-then plan and a small action you will do tomorrow."],reflection:"What is one should in your life that is ready to become a standard?",question:"What makes ODA’s version of the Dickens process different from simply beating yourself up?",options:["It is short and factual, and ends with the future you want and a first step.","It dwells on every mistake until you feel bad enough to change.","It skips the costs and only imagines success."],correct:0,feedback:"Yes. Seeing costs clearly can create leverage, but the gentle version keeps it brief and factual and puts most of the effort into the future you want and a concrete first step. Research suggests self-compassion supports change better than shame.",takeaway:"See the cost clearly, then choose one new standard and prove it with a small daily action.",sources:["state-robbins-dickens","state-robbins-standards","state-mental-contrasting","state-self-compassion-motivation"],visual:{kind:"table",title:"The gentle Dickens process",columns:["Stage","Question","Keep it kind"],rows:[["Past","What has this pattern cost me so far?","Write facts, not insults."],["Present","What is it costing me and people I love now?","Two or three lines are enough."],["Future, unchanged","Where does it lead in one, five and ten years?","Stop if it feels overwhelming."],["Future, changed","What becomes possible if I change it?","Spend the most time here."],["First step","What one action tomorrow proves the new standard?","Make it small enough to do."]],note:"Adapted from Tony Robbins’s Dickens process. The process itself has not been studied."},technique:{name:"The Dickens process (gentle version)",origin:"Tony Robbins · Unlocking potential, tonyrobbins.com",steps:["Name one limiting belief or pattern in a single sentence.","Write briefly what it has cost you in the past, in facts rather than insults.","Write what it is costing you and people you care about now.","Picture where it leads in one, five and ten years if nothing changes, and stop if it becomes overwhelming.","Spend the most time picturing the future if you change it, in concrete detail.","Write a new belief or standard and one small action you will take tomorrow."],evidence:"The Dickens process itself has not been studied. A related method, imagining a wished-for future and then the obstacles, plus if-then plans, has small-to-medium average effects on reaching goals. Self-compassion after a failure raised motivation to improve in experiments; there is no evidence that shaming yourself works better.",sourceId:"state-robbins-dickens"},photo:{id:"1633210155534-e43f00c1d627",alt:"A woman sitting on top of a rock outdoors, writing in a notebook"}}]},ue=Object.freeze(Object.defineProperty({__proto__:null,COURSE:de,SOURCES:se},Symbol.toStringTag,{value:"Module"})),he=[{id:"optimism-maier-seligman",title:"Maier & Seligman · 2016 · Learned helplessness at fifty: insights from neuroscience (Psychological Review)",url:"https://doi.org/10.1037/rev0000033",type:"research",finding:"The review concludes that the original 1967 theory got the mechanism backward. Passivity after prolonged, uncontrollable shock is an unlearned default response (mediated by the dorsal raphe nucleus). What animals learn is control: the medial prefrontal cortex detects control and then inhibits that default. The authors speculate that this has implications for treating depression.",limitation:"Based mainly on animal research; how it applies to people facing everyday setbacks is the authors’ speculation, not something this review tested. Abstract read (via Europe PMC)."},{id:"optimism-sweeney",title:"Sweeney, Anderson & Bailey · 1986 · Attributional style in depression: a meta-analytic review (Journal of Personality and Social Psychology)",url:"https://doi.org/10.1037/0022-3514.50.5.974",type:"research",finding:"Across 104 studies with nearly 15,000 participants, explaining negative events by internal, stable and global causes was reliably associated with depression scores. Explaining positive events by external, unstable and specific causes was also associated with depression, but more weakly. The patterns held for student and psychiatric samples and for real and hypothetical events.",limitation:"Correlational: it shows an association, not that explanatory style causes depression. An older review. Abstract read (via Europe PMC)."},{id:"optimism-malouff",title:"Malouff & Schutte · 2017 · Can psychological interventions increase optimism? A meta-analysis (Journal of Positive Psychology)",url:"https://doi.org/10.1080/17439760.2016.1221122",type:"research",finding:"29 randomized controlled trials with 3,319 participants: interventions increased optimism with an average effect of g = 0.41. Effects were larger for the Best Possible Self exercise, in-person delivery, active control groups, assessment within one day of the intervention and completer (rather than intention-to-treat) analyses.",limitation:"Larger effects in short-term measures and completer analyses suggest that lasting change is less certain. Abstract read (University of New England repository)."},{id:"optimism-rozanski",title:"Rozanski et al. · 2019 · Association of optimism with cardiovascular events and all-cause mortality (JAMA Network Open)",url:"https://jamanetwork.com/journals/jamanetworkopen/fullarticle/2752100",type:"research",finding:"Meta-analysis of 15 studies with 229,391 participants and a mean follow-up of 13.8 years. Higher optimism was associated with a lower risk of cardiovascular events (pooled relative risk 0.65, 95% CI 0.51–0.78; 10 studies) and of death from any cause (0.86, 0.80–0.92; 9 studies).",limitation:"All included studies were observational, with high heterogeneity and different optimism measures and adjustments. It shows association, not that optimism causes better health or that raising optimism would lower risk. Key results and limitations read."},{id:"optimism-prp-meta",title:"Brunwasser, Gillham & Kim · 2009 · A meta-analytic review of the Penn Resiliency Program’s effect on depressive symptoms (Journal of Consulting and Clinical Psychology)",url:"https://ppc.sas.upenn.edu/sites/default/files/prpmetaanalyticreview.pdf",type:"research",finding:"17 controlled evaluations with 2,498 young people aged 8–18. Compared with no intervention, participants reported fewer depressive symptoms after the program (d = 0.11), at 6–8 months (d = 0.21) and at 12 months (d = 0.20). Compared with active control conditions there was no significant difference, and the effect on depression diagnoses was not significant.",limitation:"Small effects in young people taking a structured group program; it does not test adults using ABC skills on their own. Author-hosted PDF (abstract and summary sections) read."},{id:"optimism-penn-prp",title:"Positive Psychology Center, University of Pennsylvania · Resilience in children (Penn Resiliency Program)",url:"https://ppc.sas.upenn.edu/research/resilience-children",type:"guidance",finding:"The Penn Resiliency Program is built around Ellis’s ABC model: students learn to detect inaccurate thoughts, evaluate their accuracy and challenge negative beliefs by considering other interpretations, alongside assertiveness, problem solving and relaxation. It runs as 12 ninety-minute or 18–24 sixty-minute sessions. The page cites about 20 controlled studies and acknowledges some inconsistent findings.",limitation:"Written by the program’s developers. The independent meta-analysis found small effects and no advantage over other active programs."},{id:"optimism-hofmann",title:"Hofmann et al. · 2012 · The efficacy of cognitive behavioral therapy: a review of meta-analyses (Cognitive Therapy and Research)",url:"https://pmc.ncbi.nlm.nih.gov/articles/PMC3584580/",type:"research",finding:"The review covered 269 meta-analyses of CBT. The strongest support was for CBT of anxiety disorders, somatoform disorders, bulimia, anger control problems and general stress. Of 11 reviews comparing response rates, CBT had higher response rates than the comparison conditions in 7 and lower in 1.",limitation:"About CBT delivered as therapy, not self-help in an app. The authors note too few high-quality studies for some conditions and no meta-analyses for groups such as ethnic minorities or low-income samples. Full-text summary read."},{id:"optimism-smernoff",title:"Smernoff, Mitnik, Kolodner & Lev-ari · 2015 · The effects of “The Work” meditation (Byron Katie) on psychological symptoms and quality of life: a pilot clinical study (EXPLORE)",url:"https://www.sciencedirect.com/science/article/abs/pii/S1550830714002067",type:"research",finding:"197 people from a non-clinical sample took a nine-day course in The Work. Depression, anxiety, happiness and quality-of-life scores improved significantly (all p < .001) after the course and at six months. 164 completed the post-course measures and 102 the six-month follow-up.",limitation:"A single-group pilot study with no control group and high dropout; the authors call for randomized trials. Abstract read."},{id:"optimism-seligman-exercises",title:"Seligman, Steen, Park & Peterson · 2005 · Positive psychology progress: empirical validation of interventions (American Psychologist)",url:"https://greatergood.berkeley.edu/images/uploads/Seligman-PosPsychProgress.pdf",type:"research",finding:"Online, randomized, placebo-controlled study: 577 adults randomized, 411 completed all follow-ups. All groups, including placebo, felt better right after the one-week exercise. People who wrote three things that went well each day and why, for one week, were happier and less depressed than at baseline from one month on, and stayed so at three and six months; using signature strengths in a new way showed a similar pattern. People who kept practicing beyond the week were the ones who kept benefiting.",limitation:"Self-selected, mostly well-educated, white and mildly depressed volunteers who wanted to be happier. Later replications found smaller or less specific effects. Full text read (copy hosted by the Greater Good Science Center)."},{id:"optimism-mongrain",title:"Mongrain & Anselmo-Matthews · 2012 · Do positive psychology exercises work? A replication of Seligman et al. (2005) (Journal of Clinical Psychology)",url:"https://doi.org/10.1002/jclp.21839",type:"research",finding:"Using the original method with an improved control and an added “positive placebo”, three good things and using signature strengths produced lasting increases in happiness, but so did the positive placebo. The exercises did not beat the control condition for changes in depression.",limitation:"Abstract read only (via Europe PMC); sample details not reviewed. The authors suggest the benefit may come from a general effect of thinking about positive, self-relevant information."},{id:"optimism-bolier",title:"Bolier et al. · 2013 · Positive psychology interventions: a meta-analysis of randomized controlled studies (BMC Public Health)",url:"https://link.springer.com/article/10.1186/1471-2458-13-119",type:"research",finding:"39 studies with 6,139 participants. Right after the programs: subjective well-being d = 0.34, psychological well-being d = 0.20, depression d = 0.23. At 3–6 months: 0.22, 0.16 and 0.17, with the effect on depression no longer significant.",limitation:"None of the studies met all quality criteria (20 were rated low quality) and there was evidence of publication bias. It pools many different exercises, not three good things alone. Abstract and results read."},{id:"optimism-wood",title:"Wood, Perunovic & Lee · 2009 · Positive self-statements: power for some, peril for others (Psychological Science)",url:"https://journals.sagepub.com/doi/10.1111/j.1467-9280.2009.02370.x",type:"research",finding:"A survey showed that people often use and trust positive self-statements. In two experiments, people with low self-esteem who repeated a statement about being a lovable person ended up in a worse mood than controls, while people with high self-esteem felt only slightly better.",limitation:"Short experiments measuring mood in the moment; abstract read only. It does not show that every form of positive thinking is harmful."},{id:"optimism-nhs-cbt",title:"NHS · Cognitive behavioural therapy (CBT)",url:"https://www.nhs.uk/mental-health/talking-therapies-medicine-treatments/talking-therapies-and-counselling/cognitive-behavioural-therapy-cbt/overview/",type:"guidance",finding:"The NHS describes CBT as a talking therapy in which a therapist helps you change how you think and act. It is used for depression, anxiety disorders, PTSD and other conditions, usually over 5 to 15 sessions; if symptoms do not improve, more sessions or other treatments may be needed. The page links to urgent mental health help.",limitation:"Access details are specific to England. The self-help exercises in this course are not a substitute for CBT with a trained therapist; in an emergency, call your local emergency number."},{id:"optimism-distortions",title:"Psychology Tools · Cognitive distortions: unhelpful thinking styles (extended)",url:"https://www.psychologytools.com/resource/cognitive-distortions-unhelpful-thinking-styles-extended",type:"guidance",finding:"Describes 20 unhelpful thinking styles, including all-or-nothing thinking, catastrophizing, disqualifying the positive, mental filter, mind reading, overgeneralization, personalizing and “should” statements, and traces the idea to Aaron Beck’s work in the 1960s, later popularized by David Burns.",limitation:"A clinician resource summarizing common categories; the categories overlap and are not a diagnosis."},{id:"optimism-seligman-book",title:"Martin E. P. Seligman · Learned Optimism: How to Change Your Mind and Your Life (1990; Vintage edition 2006)",url:"https://www.penguinrandomhouse.com/books/163862/learned-optimism-by-martin-e-p-seligman-phd/",type:"technique",finding:"Seligman describes explanatory style (how permanent, pervasive and personal your explanations for setbacks are) and teaches readers to replace give-up habits with more constructive explanations. His ABCDE method extends Albert Ellis’s ABC model with Disputation and Energization.",limitation:"Publisher’s page read; the ABCDE and three Ps steps here are retold from secondary descriptions and from the closely related skills in Penn’s resilience programs, not from the book’s text. Programs built on these ideas show small effects; the book has not been tested as a treatment and does not replace one."},{id:"optimism-ellis",title:"Albert Ellis · Emotional disturbance and its treatment in a nutshell (Albert Ellis Institute)",url:"https://albertellis.org/wp-content/uploads/2021/09/Emotional-Disturbance-and-Its-Treatment-in-a-Nutshell-ABCs-.pdf",type:"technique",finding:"Ellis explains the ABC model he first presented in 1956: activating events (A) lead to emotional and behavioral consequences (C) through beliefs (B). Rigid demands (“musts” and “shoulds”) and catastrophic conclusions fuel disturbance; disputing them (D) cognitively, emotionally and behaviorally leads to new, more flexible beliefs based on preferences (E).",limitation:"A description of rational emotive behavior therapy by its founder, not a research review; REBT outcome research was not reviewed for this course."},{id:"optimism-beck-thought-record",title:"Judith S. Beck · Thought Record Worksheet, from Cognitive Behavior Therapy: Basics and Beyond, 3rd edition (Beck Institute, 2020)",url:"https://beckinstitute.org/wp-content/uploads/2021/08/Thought-Record-Worksheet.pdf",type:"technique",finding:"The worksheet has columns for date and time, situation, automatic thoughts with a belief rating (0–100%), emotions with intensity, cognitive distortion, adaptive response and outcome. Its guiding questions ask about evidence for and against the thought, other explanations, the worst, best and most realistic outcomes, what you would tell a friend, and the effect of keeping versus changing the thought.",limitation:"A clinical worksheet designed for use in CBT. Used alone it is self-help, and self-guided use is less studied than therapist-led CBT."},{id:"optimism-the-work",title:"Byron Katie · Do The Work: instructions (thework.com)",url:"https://thework.com/instruction-the-work-byron-katie/",type:"technique",finding:"Katie’s instructions: write stressful judgments about a person or situation in short, simple sentences; then ask four questions of each (whether it is true, whether you can be absolutely sure, how you react when you believe it, who you would be without it); then turn the thought around (to yourself, to the other, to the opposite) and find at least three genuine examples of each turnaround.",limitation:"The author’s own instructions; the research base is limited to early, uncontrolled studies."},{id:"optimism-mrt",title:"Reivich, Seligman & McBride · 2011 · Master Resilience Training in the U.S. Army (American Psychologist)",url:"https://ppc.sas.upenn.edu/sites/default/files/mrtinarmyjan2011.pdf",type:"technique",finding:"Describes a resilience course for Army sergeants adapted from the Penn Resiliency Program: the ABC model and explanatory style, thinking traps (such as overgeneralizing, jumping to conclusions and a “me” style), deeper “iceberg” beliefs, putting it in perspective (worst, best and most likely outcome, then a plan), and hunting the good stuff, a daily record of good things.",limitation:"A program description. At publication only trainees’ immediate feedback was reported, and controlled evaluations were still under way. Author-hosted PDF read."},{id:"optimism-ggia-three-good-things",title:"Greater Good in Action (UC Berkeley) · Three Good Things",url:"https://ggia.berkeley.edu/practice/three-good-things",type:"technique",finding:"Instructions: spend about ten minutes a day for at least a week writing three things that went well, with details, how they made you feel and what caused them. The page cites the 2005 Seligman study and later studies in several countries reporting better well-being and less pessimism, depression or anxiety.",limitation:"A university practice guide that summarizes favorable studies and says more research is needed across cultures. Replications suggest effects are small and not always specific to this exercise."}],me={id:"optimism",title:"Learned Optimism",subtitle:"Change the story you tell yourself after a setback.",description:"Setbacks hurt, and the story you tell yourself about them decides how long they keep hurting. Learn to catch that story, test it, and replace it with one that is kinder and more accurate.",scope:"For adults who tend to give up, blame themselves or expect the worst after setbacks. The course draws on Martin Seligman’s learned optimism, cognitive behavioral therapy (CBT) and Byron Katie’s The Work. It is self-help, not a treatment for depression, anxiety or any other condition, and it does not replace therapy or medication. If hopelessness lasts for weeks, if ordinary days become hard to get through, or if you have thoughts of harming yourself, please talk to a doctor or mental health professional. In an emergency, call your local emergency number.",outcome:"A clear picture of your explanatory style, a pocket ABCDE routine, a thought record you know how to fill in, four questions for stressful thoughts, a worst–best–most-likely check and a nightly three good things habit, plus an honest sense of what each tool can and cannot do.",photo:{id:"1465188162913-8fb5709d6d57",alt:"A woman walking along a hilltop path in golden evening light"},lessons:[{id:"optimism-1",title:"Learned helplessness, learned hope",minutes:8,goal:"Understand why giving up after a setback is a normal default, and practice finding one piece of the situation you can still influence.",reading:["In the 1960s, Martin Seligman and Steven Maier ran experiments in which animals received shocks they could not escape. Later, when escape became easy, many of them simply stopped trying. The researchers called this learned helplessness: the idea that experience had taught the animals that nothing they did mattered. It became one of the best-known findings in psychology, and Seligman spent decades asking the human version of the question. Why do some people give up after a setback, while others keep going?","Fifty years later, Maier and Seligman revisited the work with the tools of neuroscience and concluded that the original theory had it backward. Passivity after long, uncontrollable stress seems to be the brain’s default, unlearned reaction. What gets learned is control: when a region at the front of the brain detects that actions make a difference, it dampens that default. This is animal research, so be careful about applying it directly to people. Still, it offers a hopeful frame for this course. Freezing after a blow is not a character flaw, and noticing what you can influence is a skill you can practice."],deeper:[{heading:"What the research says about optimism",paragraphs:["Optimism, broadly meaning the expectation that things will turn out reasonably well, is linked with better health. A 2019 meta-analysis pooled 15 long-term studies with about 229,000 people. The most optimistic people had a lower risk of heart and circulation events and of death from any cause than the least optimistic. These were observational studies: optimists may also exercise more, smoke less or have more resources. So this is an association, not proof that optimism itself protects your health.","Can optimism be learned? A meta-analysis of 29 randomized trials with 3,319 people found that psychological exercises raised optimism by a moderate amount on average. Effects were larger when measured right after the exercise, so how long the change lasts is less certain."]},{heading:"In daily life",paragraphs:["Helplessness rarely announces itself. It sounds like “what’s the point”, looks like closing the laptop, and feels like heaviness in the body. The move this course practices is small: before you decide nothing can be done, find one part of the situation that responds to your action. A message you can send, a question you can ask, ten minutes you can spend."],visual:{kind:"steps",title:"From stuck to moving",steps:[{label:"Notice",text:"Name the give-up moment to yourself: I am about to stop trying here."},{label:"Separate",text:"Split what is outside your control from what is not, even slightly."},{label:"Choose",text:"Pick one small action that is clearly yours to take."},{label:"Record",text:"Afterward, write down what your action changed, however little."}]}},{heading:"Common mistakes",paragraphs:["Learned optimism is not pretending a setback is fine, and it is not blaming yourself for feeling low. Some situations really are out of your hands, and seeing that accurately is part of realistic thinking. The aim is flexibility: seeing the parts you can move without denying the parts you cannot."]}],example:{title:"Daniel, 34, warehouse supervisor",text:"Daniel applied for an internal promotion and heard that someone else got it. By lunch he had decided there was no point trying again, and he was quietly planning to stop volunteering for extra projects. On the drive home he noticed the familiar pull to give up and tried the exercise instead. Outside his control: the decision, which was already made. Inside his control: asking his manager what would make him a stronger candidate next time. He sent a two-line email that evening. The reply named one skill, the scheduling software, that he could learn in about a month. He still felt disappointed that week. But the promotion no longer felt like a verdict on his whole future, and he booked the first training session."},practice:["Recall a recent setback and write one neutral sentence describing what happened.","Draw two columns and list what was outside your control and what was, even slightly, within it.","Choose one small action from the second column and do it, or put it in your calendar, within the next 24 hours."],reflection:"Where in your life have you stopped trying because it once felt pointless, and is that still true today?",question:"According to Maier and Seligman’s 2016 update, what is actually learned in the helplessness experiments?",options:["That nothing you do matters: bad experiences teach helplessness.","Control: the brain learns to detect when actions make a difference, which dampens a default passive response.","Optimism: some animals are simply born hopeful and others are not."],correct:1,feedback:"In the updated view, passivity under long, uncontrollable stress is the default. What experience teaches is that actions can matter. That is why finding and using small pieces of control is worth practicing.",takeaway:"Freezing is the default; noticing what you can influence is the skill.",sources:["optimism-maier-seligman","optimism-rozanski","optimism-malouff","optimism-seligman-book"],visual:{kind:"compare",title:"Learned helplessness: the old and the new explanation",left:{label:"Original theory (1967)",items:["Inescapable shocks teach that nothing you do matters","Passivity is learned from experience","Helplessness is the lesson"]},right:{label:"Neuroscience update (2016)",items:["Passivity is the default response to long, uncontrollable stress","Detecting control dampens that default","Control is the lesson"]},note:"Based on animal studies reviewed by Maier and Seligman (2016); how exactly this maps onto people is still being studied."},photo:{id:"1527580094867-0e719f119120",alt:"A hiker crossing grey rocks in the early morning, waiting for sunrise"}},{id:"optimism-2",title:"Your explanatory style",minutes:9,goal:"Learn the three dimensions of how you explain bad events and spot your own style in a real example.",reading:["Soon after the animal studies, researchers noticed that people differ in how they explain what goes wrong. Seligman called this habit your explanatory style, and it has three dimensions. Permanence: will this last forever (I always mess up) or is it temporary (I was exhausted this week)? Pervasiveness: does it spoil everything (I am useless) or one area (I am not good at statistics yet)? Personalization: is it entirely about you (I am stupid) or did circumstances play a part (the instructions were unclear and I rushed)? A pessimistic style reaches for permanent, pervasive and personal explanations.","This matters because explanations shape what you do next. If a cause is permanent and everywhere, trying again looks pointless. A review of 104 studies with nearly 15,000 people found that explaining bad events by internal, stable and global causes was reliably linked with more depressive symptoms. That is a correlation, not proof of cause, and it does not mean you should never take responsibility. The optimistic alternative is not “it is never my fault”. It is a more precise story: what exactly happened, which part was temporary, and which part you can change."],deeper:[{heading:"Good events run the other way",paragraphs:["Explanatory style has a mirror image. People with a pessimistic style often explain good events as temporary, narrow and down to luck: the client was just in a good mood. The same review found that this pattern was also linked with depressive symptoms, though more weakly than the pattern for bad events. So part of the practice is letting good news count, by noticing when a success came from your effort or from a strength you can use again."],visual:{kind:"compare",title:"One pessimistic style, two kinds of events",left:{label:"After a bad event",items:["This will always happen (permanent)","This ruins everything (pervasive)","It is all because of me (personal)"]},right:{label:"After a good event",items:["That was a one-off (temporary)","It only counts here (specific)","I just got lucky (external)"]},note:"The pessimistic pattern flips with the kind of event. Knowing both halves helps you catch it."}},{heading:"Common mistakes",paragraphs:["Swapping blame for excuses. Moving from “it is all my fault” to “it is all their fault” is not optimism; it is another inaccurate story. Aim for a fair split of causes.","Treating your style as one more permanent flaw. Explanatory style is a habit of thinking, not a fixed verdict, and research on optimism training suggests it can shift, at least in the short term."]}],example:{title:"Aylin, 27, graphic designer",text:"Aylin’s client rejected her first logo draft in a short email. Her first thought was that she was not creative enough for this career. She stopped and ran the three Ps. Permanent? This was one draft for one client, the first she had missed this year. Pervasive? Her portfolio and two happy clients said otherwise. Personal? Partly: she had skipped asking about the client’s color preferences. Partly not: the brief was two sentences long. Her new explanation was that she had rushed the questions stage on a vague brief. That told her what to do next. She booked a fifteen-minute call and asked six questions. The second draft was not perfect, but she went into the call as a designer fixing a draft, not a fraud waiting to be found out."},practice:["Write down one recent disappointment and your first explanation for it, exactly as it ran through your head.","Mark whether that explanation was permanent or temporary, pervasive or specific, and all about you or shared with circumstances.","Rewrite it as a precise explanation that is temporary, specific and fair about what was yours to change."],reflection:"When something goes well for you, how do you usually explain it, and does that explanation let the success count?",question:"Which rewrite of “I failed the exam because I am stupid” reflects a more optimistic explanatory style?",options:["The teacher dislikes me, so nothing I do will ever matter.","It is fine, exams do not matter anyway.","I started studying too late for this exam; next time I will begin two weeks earlier."],correct:2,feedback:"The third option is temporary (this exam), specific (study timing) and honest about the part you can change. The first moves the blame but keeps it permanent; the second waves away a real problem.",takeaway:"Make your explanations temporary, specific and fair, and you give yourself something to do next.",sources:["optimism-sweeney","optimism-seligman-book","optimism-malouff"],visual:{kind:"table",title:"The three Ps of explanatory style",columns:["Dimension","Pessimistic story","Optimistic story"],rows:[["Permanence","It will always be like this.","This is a rough patch."],["Pervasiveness","This ruins everything.","This affects one area of my life."],["Personalization","It is entirely my fault; I am the problem.","I played a part, and so did the circumstances."]],note:"After Martin Seligman’s description of explanatory style. The pessimistic column is linked with depressive symptoms in correlational research."},technique:{name:"The three Ps check",origin:"Martin Seligman · Learned Optimism (1990; Vintage edition 2006)",steps:["Write down the exact explanation that went through your head after the setback.","Ask whether you are treating it as permanent, and look for evidence that it is temporary.","Ask whether you are letting it spread to everything, and name the one area it really affects.","Ask whether you are taking all of the blame, or none of it, and divide the causes fairly.","Write a new explanation that is temporary, specific and fair, and name one next step it suggests."],evidence:"A pessimistic explanatory style is consistently associated with depressive symptoms, and optimism-building exercises show a moderate short-term effect on optimism. This particular self-check has not been tested on its own.",sourceId:"optimism-seligman-book"},photo:{id:"1509029032154-54ba8b3216d4",alt:"A man in glasses looking thoughtfully out of a window"}},{id:"optimism-3",title:"ABCDE: arguing with yourself, fairly",minutes:10,goal:"Walk one real setback through Adversity, Belief, Consequence, Disputation and Energization.",reading:["Seligman’s main tool for learned optimism builds on the ABC model that psychologist Albert Ellis introduced in the 1950s. A is the adversity: what happened, described the way a camera would record it. B is your belief: the story you told yourself about it. C is the consequence: what you felt and what you did. Most of us assume that A causes C directly: the rude email made me furious. Ellis pointed out that B sits in between. The same email can lead to fury, worry or a shrug, depending on what you believe it means.","Seligman added two steps. D is disputation: arguing with the belief the way you would argue with a stranger who said something unfair about you. Look for evidence against it, for other possible causes, for a less catastrophic view of what it means, and ask whether the belief is useful even if part of it is true. E is energization: notice how your feelings and actions change once the belief loosens. The goal is not a cheerful belief but an accurate one. When the evidence really does support a painful belief, the useful question becomes what you can do about it."],deeper:[{heading:"Where ABC came from",paragraphs:["Albert Ellis first presented his ABC idea in 1956 and built rational emotive behavior therapy (REBT) around it. He paid special attention to rigid demands, such as the belief that you must succeed or that others should always treat you fairly, and to the catastrophic conclusions that follow when they do not. His alternative was to hold strong preferences instead of absolute demands: you would very much like to succeed, and you can bear it if you do not. Seligman’s ABCDE and Aaron Beck’s cognitive therapy share this core idea: feelings follow interpretations, and interpretations can be examined."]},{heading:"Four ways to dispute",paragraphs:["Disputation works best when it is specific. Vague reassurance, such as telling yourself it will all be fine, rarely convinces the worried part of you. Evidence and concrete alternatives do."],visual:{kind:"steps",title:"Four ways to argue with a belief",steps:[{label:"Evidence",text:"Which facts support the belief, and which facts contradict it?"},{label:"Alternatives",text:"What else could have contributed? Look for causes that are temporary, specific and changeable."},{label:"Implications",text:"Even if the belief is partly true, what does it realistically mean? Is it as bad as it feels?"},{label:"Usefulness",text:"Does holding on to this belief help right now, or would focusing on the next step serve you better?"}],note:"Our own wording of the disputation step as it is commonly described."}},{heading:"What the research says",paragraphs:["The Penn Resiliency Program teaches young people the ABC model, disputing and problem solving over twelve or more group sessions. A meta-analysis of 17 controlled studies with 2,498 young people found small reductions in depressive symptoms compared with no intervention, lasting at least a year. Compared with other active programs, however, it showed no clear advantage, and it did not significantly reduce actual depression diagnoses. Even the program’s developers acknowledge that results vary between studies."],visual:{kind:"bars",title:"Penn Resiliency Program vs no intervention: depressive symptoms",bars:[{label:"Right after the program",value:.11,display:"d = 0.11"},{label:"6–8 months later",value:.21,display:"d = 0.21"},{label:"12 months later",value:.2,display:"d = 0.20"}],note:"Standardized effect sizes (d) from 17 studies of 2,498 young people aged 8–18: small effects. Against active control programs there was no significant difference. Adults using ABCDE on their own were not studied.",sourceId:"optimism-prp-meta"}}],example:{title:"Priya, 41, nurse",text:"Priya’s manager moved her to night shifts for a month without asking. A: the new rota was posted, with four weeks of nights. B: she does not value me, and I will be stuck on nights forever. C: anger, a sleepless evening and a sharp reply drafted on her phone. Before sending it, Priya opened her notebook for D. Evidence: two colleagues had also been moved, and the rota said four weeks, not forever. Alternatives: the unit was short-staffed after two resignations. Implications: a hard month, not a career sentence. Usefulness: the anger was pushing her toward an email she would regret. E: her anger dropped from nine to five. She deleted the draft and asked instead to keep her usual Sunday off. Her manager agreed."},practice:["Pick a setback from this week and write the A as a camera would record it, with no interpretation.","Write the B exactly as you thought it, then the C: what you felt (rated 0–10) and what you did or wanted to do.","Dispute the belief using evidence, alternatives, implications and usefulness, then write the E: how your feeling and plan changed."],reflection:"Which belief shows up again and again in your ABCs, and whose voice does it sound like?",question:"In the ABC model, what sits between an event and your emotional reaction?",options:["Your belief about what the event means.","The size of the event itself.","Your personality, which cannot change."],correct:0,feedback:"Ellis and Seligman both place the belief (B) between the adversity (A) and the consequence (C). Events matter, but the same event can lead to very different reactions depending on the story you tell about it.",takeaway:"Between what happened and how you feel there is a story, and stories can be checked.",sources:["optimism-seligman-book","optimism-ellis","optimism-prp-meta","optimism-penn-prp"],visual:{kind:"cycle",title:"The ABC loop",nodes:[{label:"Adversity",text:"Something happens: a rejection, a mistake, a delay."},{label:"Belief",text:"You explain it to yourself, often in a split second."},{label:"Consequence",text:"Feelings and actions follow the belief, not just the event."},{label:"Next situation",text:"What you do shapes what happens next, and the loop starts again."}],center:"Step in at B",note:"After Albert Ellis’s ABC model, which Martin Seligman extended with Disputation and Energization."},technique:{name:"ABCDE",origin:"Martin Seligman · Learned Optimism (1990; Vintage edition 2006)",steps:["Adversity: describe the event in neutral, factual words.","Belief: write down the thoughts you had about it, word for word.","Consequence: note your feelings, how strong they were and what you did.","Disputation: argue with the belief using evidence, alternative causes, realistic implications and usefulness.","Energization: record how your feelings, energy and plans changed after disputing."],evidence:"ABC-based skills are part of the Penn Resiliency Program, which reduced depressive symptoms in young people by a small amount compared with no intervention, but not compared with other active programs. ABCDE used alone by adults has little direct research.",sourceId:"optimism-seligman-book"},photo:{id:"1643148636630-0b0fb138fc74",alt:"A person writing in a notebook with a pen"}},{id:"optimism-4",title:"Thinking traps and the thought record",minutes:11,goal:"Recognize common thinking traps and complete one thought record, from situation to balanced response.",reading:["In the 1960s, psychiatrist Aaron Beck noticed that his depressed patients had quick, automatic thoughts that were biased in predictable ways. He called these patterns cognitive distortions; many people now call them thinking traps. Among the most common are all-or-nothing thinking (one mistake means total failure), catastrophizing (jumping to the worst outcome), mind reading (assuming you know what others think), overgeneralizing (one event becomes a rule) and the mental filter (noticing only the negatives). Everyone falls into these traps sometimes. They are mental shortcuts, not signs that something is wrong with you.","Beck’s approach grew into cognitive behavioral therapy (CBT), one of the most researched talking therapies. A review of 269 meta-analyses found the strongest support for CBT in anxiety disorders, stress, anger problems and several other conditions. A central CBT tool is the thought record: a structured sheet where you write the situation, the automatic thought and how strongly you believe it, your emotions, the trap involved, a balanced response and the outcome. Writing it down matters. Thoughts that feel like facts inside your head often look different on paper."],deeper:[{heading:"How to write a balanced response",paragraphs:["A balanced response is not a positive thought. It keeps the true parts of the worry and adds what the worry left out. “My presentation was a disaster” might become: I lost my place twice, I also answered every question, and two people asked for my slides.","Helpful questions from the Beck Institute worksheet include: what is the evidence for and against this thought, is there another explanation, what are the worst, best and most realistic outcomes, and what would you tell a friend in the same situation?"],visual:{kind:"steps",title:"A thought record, column by column",steps:[{label:"Situation",text:"Where you were, what happened, when."},{label:"Automatic thought",text:"The thought, word for word, with how much you believe it (0–100%)."},{label:"Emotion",text:"Name each feeling and rate its strength (0–100)."},{label:"Balanced response",text:"Weigh the evidence and write a fairer, fuller version."},{label:"Outcome",text:"Re-rate your belief and emotions, and note what you will do."}]}},{heading:"When thought records feel hard",paragraphs:["Some days a thought record feels like arguing with a wall: the balanced response makes sense, but you do not feel it yet. That is common. Re-rate your belief anyway; a drop from 90% to 70% is real progress.","If writing about a situation leaves you feeling much worse, or the same painful thoughts dominate most of your days, that is a good moment to work with a trained CBT therapist rather than alone. Self-help worksheets are useful, but they are not a substitute for treatment."]}],example:{title:"Marcus, 38, sales manager",text:"Marcus noticed that his boss had not replied to his weekly report for two days. By Wednesday he was convinced his job was in danger. At his desk he opened a blank page and drew columns. Situation: no reply to the report. Automatic thought: she thinks my numbers are bad and is planning to let me go, believed at 80%. Emotion: anxiety, seven out of ten. Traps: mind reading and catastrophizing. Evidence against: last month’s review was positive, and she had been travelling all week. Balanced response: I do not know why she has not replied; the likeliest reason is her travel, and I can ask at Friday’s check-in. Outcome: belief down to 30%, anxiety down to four. On Friday she mentioned she had barely opened her email all week."},practice:["Read the thinking traps table and pick the two you fall into most often.","Take one upsetting thought from the past few days and write the situation, the thought with a belief percentage, the emotion with a rating, and the trap.","Answer the evidence-for, evidence-against and friend questions, write a balanced response, and re-rate your belief and emotion."],reflection:"Which thinking trap would the people who know you best say you fall into most often?",question:"Which of these is a balanced response in the CBT sense?",options:["Everything will be perfect if I just believe it.","I made a mistake in the report, my manager has also praised most of my work this year, and I can fix this one.","I always ruin things, so there is no point trying."],correct:1,feedback:"A balanced response keeps what is true (there was a mistake) and adds what the anxious thought left out (the praise, the fix). The first option ignores reality; the third is overgeneralizing.",takeaway:"You do not have to believe every thought; you can put it on paper and weigh it.",sources:["optimism-hofmann","optimism-beck-thought-record","optimism-distortions","optimism-mrt","optimism-ellis","optimism-nhs-cbt"],visual:{kind:"table",title:"Common thinking traps",columns:["Trap","What it sounds like","A question to test it"],rows:[["All-or-nothing","If it is not perfect, it is a failure.","Is there any middle ground between perfect and failure?"],["Catastrophizing","This is going to be a disaster.","What is the most likely outcome, not just the worst?"],["Mind reading","They think I am useless.","What do I actually know about what they think?"],["Overgeneralizing","This always happens to me.","Is it really always? When did it not happen?"],["Mental filter","The whole day was bad.","What went neutral or well that I am filtering out?"],["Personalizing","It is all because of me.","Which other people or circumstances played a part?"]],note:"A selection of the cognitive distortions first described by Aaron Beck and later popularized by David Burns; the test questions are our own wording."},technique:{name:"Thought record",origin:"Judith S. Beck · Cognitive Behavior Therapy: Basics and Beyond (3rd edition, 2020)",steps:["Write the situation: where you were, what happened and when.","Write the automatic thought and rate how much you believe it, from 0 to 100%.","Name your emotions and rate each one from 0 to 100.","Identify the thinking trap, if one fits.","Answer the questions: evidence for and against, other explanations, worst, best and most realistic outcome, and what you would tell a friend.","Write a balanced response, then re-rate your belief and your emotions."],evidence:"Thought records are a core part of CBT, which is supported by a very large body of research, especially for anxiety and stress-related problems. Self-guided thought records outside therapy are less studied, and using them alone is not a substitute for treatment.",sourceId:"optimism-beck-thought-record"},photo:{id:"1681396059172-7532b1ef8b47",alt:"An open journal lying on a table in soft morning light"}},{id:"optimism-5",title:"Four questions for a stressful thought",minutes:9,goal:"Try Byron Katie’s four questions and turnaround on one thought that keeps hurting you.",reading:["Byron Katie, an American speaker and author, developed a method she calls The Work. Instead of arguing with a thought using evidence, you sit with it and ask four questions. First, ask whether the thought is true. Second, ask whether you can be absolutely certain that it is true. Third, notice how you react, in your body, feelings and behavior, when you believe it. Fourth, imagine who you would be in the same situation without that thought. You write your answers down and give each question time, rather than rushing to the answer you think is correct.","Then comes the turnaround: you flip the original thought and look for real examples of the reversed version. “My brother should listen to me” can become “I should listen to my brother”, “I should listen to myself”, or “My brother should not listen to me”, perhaps because the advice was never asked for. For each turnaround you look for at least three genuine examples. The Work overlaps with CBT, since both treat thoughts as something to examine rather than obey, but it leans on curiosity more than on building a counterargument. Its research base is much thinner, as you will see below."],deeper:[{heading:"How it differs from a thought record",paragraphs:["A thought record builds a case; The Work pauses the case. The third question asks you to notice what the thought costs you, and the fourth invites you to picture the moment without it. Some people find that a thought loosens this way even when they cannot yet disprove it. Others prefer the structure of weighing evidence. You can use whichever fits the thought in front of you."],visual:{kind:"compare",title:"Thought record and The Work side by side",left:{label:"CBT thought record",items:["Weighs evidence for and against","Names the thinking trap","Ends with a balanced response","Backed by a large research base"]},right:{label:"The Work",items:["Asks whether you can be certain","Notices how the thought affects you","Ends with turnarounds and examples","Backed by limited, early research"]}}},{heading:"What the research says",paragraphs:["The main published study followed 197 people in Israel through a nine-day course in The Work. Scores for depression, anxiety and quality of life improved and were still better six months later. But there was no control group, participants were not a clinical sample, and only 102 of the 197 completed the six-month follow-up, so the people who benefited may have been the ones who stayed. The authors themselves called the results promising and asked for randomized trials. Treat The Work as an interesting reflective tool, not an evidence-based treatment."],visual:{kind:"bars",title:"How many people stayed in the main study of The Work",bars:[{label:"Start of the course",value:197,display:"197"},{label:"After the course",value:164,display:"164"},{label:"Six months later",value:102,display:"102"}],note:"Participants completing assessments in an uncontrolled pilot study (Smernoff et al., 2015). Losing about half the sample makes the lasting improvements hard to interpret.",sourceId:"optimism-smernoff"}},{heading:"Use it with care",paragraphs:["Turnarounds are meant to widen your view, not to make you responsible for someone else’s harmful behavior. If a thought is about being mistreated, threatened or unsafe, the priority is your safety and support from people you trust or from professionals, not a reframing exercise."]}],example:{title:"Elena, 52, teacher",text:"For weeks Elena had been replaying one thought: my daughter should call me more. One Sunday she sat down with the four questions. Was it true? It felt true. Could she be absolutely sure? No; her daughter was working two jobs. How did she react when she believed it? She checked her phone constantly, felt hurt, and opened their calls with complaints. Who would she be without the thought? Probably calmer, and simply glad when the phone did ring. Turning it around, she tried “I should call my daughter more” and found three recent weeks when she had waited instead of calling. That evening she sent a short, warm message with no hint of reproach. Her daughter replied with a voice note, and they set up a regular Sunday call."},practice:["Write down one short, specific thought about a person or situation that has been bothering you.","Answer the four questions in writing, taking at least a minute of quiet with each one.","Turn the thought around in two or three ways and find three genuine examples for one of the turnarounds."],reflection:"Which thought, if you could hold it more loosely, would change the most in your daily life?",question:"What is an honest summary of the evidence for Byron Katie’s The Work?",options:["It is as well researched as CBT.","It has been proven not to work.","Early, uncontrolled studies are encouraging, but it has not been tested in strong randomized trials."],correct:2,feedback:"The main study showed improvements but had no control group and lost about half its participants by follow-up. That makes The Work an interesting tool to try, not an evidence-based treatment.",takeaway:"Before you argue with a thought, ask whether you can be sure of it and who you would be without it.",sources:["optimism-the-work","optimism-smernoff","optimism-hofmann"],visual:{kind:"steps",title:"The Work in five moves",steps:[{label:"True?",text:"Ask whether the thought is true. A simple yes or no is enough."},{label:"Certain?",text:"Ask whether you can be absolutely sure. Look at the situation again."},{label:"Reaction",text:"Notice what happens in your body, feelings and actions when you believe it."},{label:"Without it",text:"Picture yourself in the same situation without the thought."},{label:"Turn it around",text:"Reverse the thought and find three real examples of the reversal."}],note:"Retold in our own words from the instructions on Byron Katie’s website."},technique:{name:"The Work",origin:"Byron Katie · The Work (instructions at thework.com)",steps:["Write one short, specific stressful thought on paper, ideally about a person.","Ask whether it is true, and answer only yes or no.","Ask whether you can be absolutely certain that it is true.","Notice how you react when you believe the thought: body, feelings, actions, and how you treat yourself and others.","Imagine yourself in the same situation without the thought, and notice what changes.","Turn the thought around (to yourself, to the other person, to the opposite) and find three genuine examples for each."],evidence:"An uncontrolled pilot study found improvements in depression, anxiety and quality of life after a nine-day course, but it had no control group and lost about half its participants by follow-up. Effectiveness has not been established in randomized trials.",sourceId:"optimism-the-work"},photo:{id:"1503541517233-120571491cf3",alt:"A man sitting on a park bench with his eyes closed, surrounded by trees"}},{id:"optimism-6",title:"Realistic optimism and three good things",minutes:10,goal:"Tell realistic optimism apart from forced positivity, and start a nightly three good things habit.",reading:["Learned optimism is not the same as positive thinking. Forcing cheerful statements can even backfire: in one set of experiments, people with low self-esteem who repeated that they were a lovable person ended up in a worse mood than those who did not. Toxic positivity, the pressure to look on the bright side no matter what, can make people feel their pain is not allowed. Realistic optimism sees the problem clearly, lets you feel what you feel, and still expects that effort, time or help can make things somewhat better. It asks what is most likely, not what is most pleasant.","One simple practice trains your attention toward what went well without denying what did not. In a 2005 online study by Seligman and colleagues, people wrote down three things that went well each day, and why they went well, for one week. Compared with a placebo writing task, they were happier and less depressed from one month on, and the difference lasted to six months, mainly for people who kept doing it. Later studies found smaller and less specific effects, so think of it as a gentle habit that may lift your mood a little, not as a cure."],deeper:[{heading:"Realistic optimism versus toxic positivity",paragraphs:["The difference shows up in how you treat a bad feeling. Toxic positivity pushes it away; realistic optimism lets it be there and then looks for the next useful step. You can say “this is really hard” and “I can take one step today” in the same breath."],visual:{kind:"compare",title:"Two ways to respond to a setback",left:{label:"Toxic positivity",items:["Just stay positive!","Hides sadness, worry or anger","Ignores real risks","Repeats slogans you do not believe"]},right:{label:"Realistic optimism",items:["This is hard, and I can still act.","Allows feelings, then looks forward","Plans for the most likely outcome","Uses explanations you can believe"]},note:"Positive self-statements lifted mood slightly for people with high self-esteem but lowered it for people with low self-esteem (Wood and colleagues, 2009)."}},{heading:"Put it in perspective",paragraphs:["When a worry starts to spiral, a tool from the resilience training Seligman’s team built for the US Army can help. Write the worst case your mind is playing, then deliberately write an equally unlikely best case, then the most likely outcome. Finally, make a plan for the most likely one. The best case is there to loosen the grip of the worst case, not to replace it."],visual:{kind:"steps",title:"Worst, best, most likely",steps:[{label:"Worst",text:"Write down the catastrophic version your mind is already playing."},{label:"Best",text:"Write an equally unlikely best-case version."},{label:"Most likely",text:"Write what will probably happen, based on the evidence you have."},{label:"Plan",text:"Decide one step to handle the most likely outcome."}]}},{heading:"What the research says",paragraphs:["A replication of the 2005 study found that three good things raised happiness over time, but so did a positive placebo task, and the exercise did not beat the control condition for depression. A broader meta-analysis of positive psychology exercises found small effects on well-being and depression that shrank at follow-up, and many of the studies were of low quality.","Health research adds another nuance: optimism is linked with a lower risk of heart disease and earlier death, but those studies are observational and cannot show cause. Keep the habit because it helps you notice more of your life, not because it guarantees any outcome."]}],example:{title:"Sam, 45, bus driver",text:"Sam was skeptical about gratitude lists, but after a rough month of overtime and worry about his father’s health, he agreed to try three good things for a week. The first night he wrote: a regular passenger thanked him for waiting, the soup at lunch was hot, and his sister called. Why? He had chosen to wait, he had packed lunch the night before, and his sister cares about him. Some nights it was hard to find three, so he wrote small things: a run of green lights, a quiet stop. He still phoned the clinic about his father’s tests; the list did not replace that. But by the end of the week he noticed himself scanning his shift for things to write down, and the drive home felt a little lighter."},practice:["Tonight, write three things that went well today, however small, and one line on why each one happened.","Pick a current worry and write the worst case, an equally unlikely best case and the most likely outcome, plus one step for the likeliest.","Tomorrow, when you feel pulled to force positivity, name the difficulty out loud or on paper and add one realistic next step."],reflection:"What is the difference, for you, between hoping something will go well and pretending it is already fine?",question:"Which statement best describes realistic optimism?",options:["Acknowledging a problem honestly while expecting that effort, time or help can improve things.","Repeating positive statements until the negative feelings disappear.","Expecting the worst so you are never disappointed."],correct:0,feedback:"Realistic optimism keeps both eyes open: it names the difficulty and still looks for the next useful step. Forced positive statements can backfire, and always expecting the worst drains the motivation to act.",takeaway:"See the problem clearly, and look just as clearly for what can still go right.",sources:["optimism-wood","optimism-seligman-exercises","optimism-mongrain","optimism-bolier","optimism-mrt","optimism-ggia-three-good-things","optimism-rozanski"],visual:{kind:"bars",title:"Positive psychology exercises: average effect right after the program",bars:[{label:"Subjective well-being",value:.34,display:"d = 0.34"},{label:"Psychological well-being",value:.2,display:"d = 0.20"},{label:"Depression (reduction)",value:.23,display:"d = 0.23"}],note:"39 randomized studies with 6,139 people (Bolier and colleagues, 2013): small to moderate effects. At 3–6 months the effects were smaller and the effect on depression was no longer significant. Many studies were of low quality, and the analysis covers many exercises, not three good things alone.",sourceId:"optimism-bolier"},technique:{name:"Three good things",origin:"Martin Seligman and colleagues · Positive Psychology Progress, American Psychologist (2005)",steps:["Set aside about ten minutes before bed, with a notebook rather than a phone if you can.","Write down three things that went well today; small things count.","For each one, add a few details about what happened and how it felt.","For each one, write why you think it happened, including any part you played.","Repeat every night for at least a week, then decide whether to keep going."],evidence:"In the original study, benefits compared with a placebo appeared from one month on and lasted six months, mainly for people who kept practicing. A replication found similar happiness gains with a positive placebo and no specific benefit for depression, so expect small, general effects.",sourceId:"optimism-ggia-three-good-things"},photo:{id:"1750885847789-f5748b585e3a",alt:"A woman on a balcony looking out over a city"}}]},ye=Object.freeze(Object.defineProperty({__proto__:null,COURSE:me,SOURCES:he},Symbol.toStringTag,{value:"Module"})),ke=[{id:"meaning-frankl",title:"Viktor E. Frankl · Man’s Search for Meaning (1946) and the Viktor Frankl Institute Vienna (logotherapy overview)",url:"https://www.viktorfrankl.org/logotherapy.html",type:"technique",finding:"The Viktor Frankl Institute describes logotherapy and existential analysis as a meaning-centered approach to psychotherapy that Frankl developed from the 1930s. It rests on three assumptions: freedom of will (people can choose their stance toward their circumstances, even in illness or hardship), the will to meaning (searching for meaning is a primary human motivation, and when it is frustrated people can feel an inner emptiness), and meaning in life (meaning is specific to each person and situation, to be discovered rather than prescribed). In his book Frankl describes three broad sources of meaning: creating a work or doing a deed, experiencing something or loving someone, and the attitude you take toward suffering you cannot avoid.",limitation:"The institute page was read. The three sources of meaning are taken from Frankl’s book as widely summarized and were not re-checked against an opened page. Logotherapy is a clinical approach with a smaller research base than many other therapies; the reflections in this course are self-practice, not logotherapy."},{id:"meaning-act-values",title:"Association for Contextual Behavioral Science · The six core processes of ACT (values and committed action)",url:"https://contextualscience.org/the_six_core_processes_of_act",type:"technique",finding:"Acceptance and Commitment Therapy (ACT) aims to build psychological flexibility through six connected processes. Values are described as chosen qualities of purposeful action that can never be obtained like an object but can be lived moment by moment, as ongoing directions in areas such as family and work; ACT helps people choose values that are truly their own rather than driven by avoidance, social pressure or “I should” thoughts. Committed action means building larger and larger patterns of values-based behavior, linking concrete, achievable goals to values and working with the inner barriers that show up along the way.",limitation:"A description by the professional association around ACT, not a study. It explains the model; it does not show how much a values exercise done on your own helps. The compass picture used in this course is a common way of teaching ACT values, not a term from this page."},{id:"meaning-carrillo",title:"Carrillo et al. · 2019 · Effects of the Best Possible Self intervention: a systematic review and meta-analysis (PLOS One)",url:"https://doi.org/10.1371/journal.pone.0222386",type:"research",finding:"Pooling 29 studies with 2,909 participants, the meta-analysis found that the Best Possible Self exercise improved optimism (d = 0.334), positive affect (d = 0.511) and wellbeing (d = 0.325), and reduced negative affect (d = 0.192) and depressive symptoms (d = 0.115), compared with control conditions.",limitation:"Effects were small to medium, and the effect on depressive symptoms was small. Studies differed in how often and how long people wrote, and most measured short-term outcomes. The analysis tests the Best Possible Self exercise, not meaning in life directly and not this course."},{id:"meaning-best-possible-self",title:"Laura A. King · Best Possible Self writing (2001), as reviewed by Carrillo et al. (2019)",url:"https://doi.org/10.1371/journal.pone.0222386",type:"technique",finding:"In the Best Possible Self exercise, people imagine a future in which things have gone as well as they realistically could, after working hard toward what matters to them, and write about that future for several minutes, sometimes on several occasions. Carrillo et al. pooled 29 studies of this exercise.",limitation:"King’s original 2001 paper was not opened; the procedure is described as it is commonly used in the studies that were reviewed. Session length and number of sessions vary between studies. Linking the exercise to personal values is this course’s own addition."}],ce={id:"meaning",title:"Meaning and Values",subtitle:"Find what matters to you, then take one small step toward it today",description:"What if meaning is less a big answer you find once and more a direction you choose again each day? This course brings together Viktor Frankl’s ideas about meaning and the values work of Acceptance and Commitment Therapy, and turns them into small, daily decisions.",scope:"For adults who feel busy but directionless, are at a crossroads, or want their days to reflect what they care about. It is education and self-reflection, not therapy or treatment. Feeling unsure about meaning from time to time is part of being human, but if life has felt empty or meaningless for weeks, please talk to a doctor or a mental health professional. If you have thoughts of harming yourself, contact your local emergency number now.",outcome:"A map of where meaning already shows up in your life, a short list of values in your own words, a check for which of them are truly yours, a way to face hard situations you cannot change, a written picture of your best possible future, and one small values-based decision you can make every day.",photo:{id:"1500530855697-b586d89ba3ee",alt:"A road winding through open hills toward the horizon"},lessons:[{id:"meaning-1",title:"Where meaning comes from",minutes:8,goal:"Learn Frankl’s three broad sources of meaning and notice where each already shows up in your life.",reading:["Viktor Frankl was a Viennese psychiatrist who developed an approach he called logotherapy, a therapy centered on meaning. His best-known book grew out of his years as a prisoner in Nazi concentration camps. One of his central ideas is that the search for meaning is a basic human drive, not a luxury for people whose other problems are solved. When that search is blocked for a long time, he argued, people can feel an inner emptiness. Frankl did not think anyone could hand you the meaning of your life. In his view it is specific to you and your situation, and it is discovered rather than invented.","Frankl described three broad places where meaning can be found. The first is creating or doing: work, a project, a deed, something you give to the world. The second is experiencing or loving: beauty, nature, truth, and above all another person, known and cared for as they are. The third is the attitude you take toward suffering you cannot avoid. Most people find meaning in all three at different times. The useful question is not what the meaning of life is in general. It is what this moment, this relationship or this task is asking of you."],deeper:[{heading:"Meaning as a response, not a big answer",paragraphs:["Many people wait for one grand purpose to arrive before they feel their life counts. Frankl turned the question around. Instead of asking what life owes you, you can ask what life is asking of you, here, today. That shift makes meaning smaller and closer: a conversation to show up for, a piece of work to do well, a person to care for.","The Viktor Frankl Institute describes this as freedom of will: even when circumstances are fixed, you keep some freedom in how you respond. That freedom does not make hard things easy. It gives you somewhere to stand."],visual:{kind:"compare",title:"Two ways to ask about meaning",left:{label:"Waiting for a big answer",items:["What is the meaning of my life?","I will feel it once everything is sorted.","Meaning is somewhere else."]},right:{label:"Responding to this moment",items:["What is this moment asking of me?","I can act on what matters today.","Meaning is often close by."]},note:"Our own illustration of the shift Viktor Frankl describes."}},{heading:"What the research says, and what it does not",paragraphs:["Logotherapy is a clinical approach with a smaller research base than many other therapies, so this course treats Frankl’s ideas as a helpful way of thinking rather than a proven treatment. Some pieces of his picture do connect with research, though. A meta-analysis of 27 studies with 4,045 people found that doing acts of kindness had a small-to-medium positive effect on the wellbeing of the person doing them.","That is one small, measurable slice of the first source of meaning: doing something for someone else. It does not prove Frankl right about everything, and it is not a reason to force yourself into good deeds. It is a hint that meaning often lives in ordinary actions."]}],example:{title:"Tomás, 41, warehouse supervisor",text:"Tomás had started to feel that his life was just work, sleep and bills. One Sunday evening he drew three columns on the back of an envelope: doing, experiencing, facing. Under doing he wrote that he had trained two new starters that month, and both were now confident. Under experiencing he wrote the Saturday walks with his daughter and the smell of the bakery on his route to work. Under facing he wrote his father’s illness, which he could not fix but could keep visiting. Nothing in his life had changed. But on Monday he noticed he was paying more attention when the newest starter asked a question, because now he knew that part of the job mattered to him."},practice:["Draw three columns labeled doing, experiencing and facing, and write at least one thing from the past month under each.","Circle the entry that surprised you most, the one you did not expect to count as meaningful.","Choose one moment today where you will ask yourself what this moment is asking of you, and write down when it will be."],reflection:"Which of the three sources of meaning do you tend to overlook in your own life?",question:"Which set describes Frankl’s three broad sources of meaning?",options:["Money, status and recognition.","Creating or doing, experiencing or loving, and the attitude toward unavoidable suffering.","Positive thinking, visualization and affirmations."],correct:1,feedback:"Frankl pointed to what you give (work and deeds), what you receive (experiences and love) and the stance you take toward suffering you cannot avoid.",takeaway:"Meaning is less a single answer than a response to what each day asks of you.",sources:["meaning-frankl","faith-kindness"],visual:{kind:"table",title:"Three sources of meaning",columns:["Source","What it involves","An everyday example"],rows:[["Creating or doing","Giving something through work, a project or a deed","Helping a new colleague find their feet"],["Experiencing or loving","Receiving beauty, truth, nature or another person","A slow walk with someone you love"],["Attitude","The stance you take toward suffering you cannot avoid","Keeping your dignity and kindness through an illness"]],note:"Sources from Viktor Frankl; the examples are our own."},technique:{name:"Three sources of meaning review",origin:"Viktor E. Frankl · Man’s Search for Meaning (1946)",steps:["Set aside ten quiet minutes with paper and a pen.","Under “doing”, list things you have made, given or accomplished recently, however small.","Under “experiencing”, list moments of beauty, connection or love you have received.","Under “facing”, list any difficulty you cannot change and how you have chosen to carry it.","Read the lists back and ask which one you would like to feed a little more this week."],evidence:"This review is our own structured way of reflecting on Frankl’s three sources of meaning; it has not been tested as an exercise. Frankl’s ideas come from clinical experience and philosophy more than from controlled trials.",sourceId:"meaning-frankl"},photo:{id:"1469474968028-56623f02e42e",alt:"A lone figure on a rock above a misty valley"}},{id:"meaning-2",title:"Values are a direction, not a finish line",minutes:9,goal:"Understand the difference between values and goals, and name a few values in your own words.",reading:["Acceptance and Commitment Therapy, usually called ACT, is a modern psychological approach that gives values a central place. In ACT, values are chosen qualities of how you want to act: being caring, being curious, being honest, being brave. They are different from goals. A goal can be finished and ticked off, such as running a race, getting a job or paying off a loan. A value can never be completed. You never reach the end of being caring. You can only act in a caring way, or not, in this particular moment.","A helpful picture is a compass. If you want to travel west, you can walk west for years and never arrive at a place called West. Along the way you pass real destinations, and those are your goals. Values tell you which way to face; goals mark the stops on the road. This matters because goals come and go. When you reach one you can feel strangely empty, and when you miss one you can feel lost. A value stays with you in both cases and points to the next step."],deeper:[{heading:"Values across areas of life",paragraphs:["ACT describes values as ongoing directions in different areas of life, such as family, work, friendship, health and community. It can help to look at a few areas one at a time, because the value that matters most at work might be different from the one that matters most at home.","Keep the words short and active. “Being a present parent” is easier to act on than “family”. If a value sounds like something you would only say to impress others, set it aside for now."],visual:{kind:"table",title:"The same area, seen as a value and as a goal",columns:["Life area","A value (a direction)","A goal (a destination)"],rows:[["Family","Being warm and present","Eat dinner together three nights this week"],["Work","Doing careful, useful work","Finish the report by Friday"],["Health","Caring for my body","Walk 20 minutes after lunch"],["Friendship","Being loyal and in touch","Call Sam this weekend"]],note:"Our own examples of the values-versus-goals distinction described in ACT."}},{heading:"Common mistakes",paragraphs:["The first mistake is writing feelings as values, such as “being happy” or “feeling calm”. Feelings come and go and are not fully in your control. Values are about what you do, which is why they stay usable on hard days.","The second mistake is turning values into rules: “I must always be productive”. A value is a freely chosen direction, not a stick to beat yourself with. The third is choosing too many at once. Three or four values that feel alive are more useful than a list of twenty."]}],example:{title:"Priya, 33, graphic designer",text:"Priya had set herself a goal of landing a senior role by the end of the year. When the promotion went to someone else, she felt that the whole year had been wasted. That evening she tried the compass exercise. Under work she wrote the value “making things that are clear and kind to use”. Looking back at the year, she could see dozens of moments where she had lived that value: the accessibility fixes nobody asked for, the junior designer she had coached. The goal had slipped away, but the direction was still there. The next morning she spent twenty minutes sketching a portfolio piece built around that value, instead of scrolling job ads."},practice:["Pick three areas of your life and write one value for each as a short phrase that starts with “being” or a verb.","Next to each value, write one goal that would move you in that direction in the next month.","Check each value: could you act on it even on a bad day? If not, rewrite it as something you do rather than something you feel."],reflection:"If nobody would ever know what you did, which direction would you still want your life to face?",question:"According to ACT, what is the key difference between a value and a goal?",options:["Values are more important than goals, so you should drop your goals.","Values are feelings, and goals are actions.","A goal can be completed, while a value is an ongoing direction you can only act on moment by moment."],correct:2,feedback:"Goals are destinations you can reach and tick off. Values are chosen directions that can never be completed, only lived in each moment. You need both.",takeaway:"Goals are the stops on the road; values are the way you are facing.",sources:["meaning-act-values","motivation-sdt"],visual:{kind:"compare",title:"Values and goals",left:{label:"Values",items:["A direction you choose","Never finished","Available in every moment","Example: being caring"]},right:{label:"Goals",items:["A destination you reach","Can be ticked off","Belong to a future point","Example: visit Mom on Sunday"]},note:"Our own summary of the distinction described by the Association for Contextual Behavioral Science."},technique:{name:"Values compass",origin:"Acceptance and Commitment Therapy · values work, as described by the Association for Contextual Behavioral Science",steps:["Draw a simple compass and label four points with areas of your life, such as relationships, work, health and personal growth.","For each area, write in a few words how you want to act there, as a quality rather than an outcome.","Rate from 0 to 10 how closely your actions this past week matched each value.","Choose the area with the biggest gap that you care about most.","Write one small action you could take this week in that direction."],evidence:"Values clarification is a core part of ACT, which is described as a set of processes rather than a single exercise. This compass version has not been tested on its own, and its effect when done alone, outside therapy, is unknown.",sourceId:"meaning-act-values"},photo:{id:"1470071459604-3b5ec3a7fe05",alt:"Clouds drifting over green cliffs and a valley"}},{id:"meaning-3",title:"Whose values are these?",minutes:9,goal:"Separate values you have truly chosen from ones driven by pressure, guilt or fear.",reading:["Some of the values we carry are borrowed. They come from parents, a culture, a job or social media, and they often arrive with the word “should”. I should want a bigger house. I should be more ambitious. ACT encourages people to choose values that are genuinely their own, and not to pick them to avoid discomfort, to please others or because a thought insists on it. A borrowed value is not always wrong. Many values we learned from others become truly ours. The question is whether it still feels chosen when you look at it closely.","Research on self-determination theory draws a similar line. It separates autonomous motivation, which comes from interest and personal values, from controlled motivation, which comes from rewards, pressure or other people’s expectations. Motivation that feels chosen tends to be of higher quality and easier to keep up. A simple check is to imagine that nobody would ever see or praise what you do. If the value still matters, it is probably yours. If it deflates at once, it may belong to someone else’s picture of your life."],deeper:[{heading:"Asking “why”, honestly",paragraphs:["Popular coaches, Tony Robbins among the best known, often urge people to find their “why”: the deeper reason behind what they want. The idea has something real in it. Asking why you want something a few times in a row can move you from a surface goal toward the value underneath it.","But the dramatic promises that sometimes come with it, that the right “why” will make you unstoppable, have not been tested. The honest version is quieter. Asking why helps you see what you care about. It does not replace planning, rest or support, and your answer can change over the years."],visual:{kind:"compare",title:"A “should” value or a chosen one?",left:{label:"Feels like a should",items:["Comes with guilt or fear","Matters mostly if others see it","Sounds like someone else’s voice"]},right:{label:"Feels chosen",items:["Still matters when nobody is watching","Gives a sense of energy or rightness","You would pick it again today"]},note:"Our own checklist, based on ACT’s emphasis on freely chosen values and on self-determination theory."}},{heading:"What the research says",paragraphs:["A meta-analysis of 73 intervention studies in health found that programs based on self-determination theory produced small-to-medium increases in autonomous motivation and small positive changes in physical and psychological health. People whose autonomous motivation grew also tended to improve their health behaviors.","Those studies were about health habits, not life values in general, and the health effects were modest. Still, they fit with the idea behind this lesson: doing something for reasons you own tends to hold up better than doing it under pressure."]}],example:{title:"Marcus, 26, junior accountant",text:"Marcus had listed “financial success” as one of his top values. When he tried the nobody-is-watching test, it went flat almost at once. What he actually felt was a fear of disappointing his parents, who had struggled for money. He asked himself why he wanted financial success, three times in a row. The answers moved from “to have a good salary” to “so my family feels safe” to “being someone people can rely on”. That last phrase felt alive. He kept working hard at his job, but he also started calling his younger brother every week to help him with his college applications. It cost nothing, and it felt more like him than the salary target ever had."},practice:["Take the values you wrote in the last lesson and read each one while imagining that nobody would ever see or praise you for living it.","Mark each value as chosen, should, or unsure, and notice any body sensations as you do.","For one value marked should or unsure, ask “why does this matter to me?” three times and write down where you end up."],reflection:"Which of your values would you keep even if the people you want to impress never found out?",question:"What does self-determination theory say about motivation that comes from personal values?",options:["It is a form of autonomous motivation, which tends to be of higher quality than motivation driven by pressure or rewards.","It is weaker than motivation driven by rewards and pressure.","It only matters for people who already have high self-esteem."],correct:0,feedback:"Self-determination theory separates autonomous motivation, rooted in interest and values, from controlled motivation, driven by rewards, pressure or others’ expectations. The first tends to last longer and feel better.",takeaway:"A value is yours if it still matters when nobody is watching.",sources:["meaning-act-values","motivation-sdt","motivation-sdt-meta"],visual:{kind:"steps",title:"From a surface goal to a value",steps:[{label:"Name it",text:"Write down something you want, such as a promotion or a new city."},{label:"Ask why",text:"Why does that matter to me? Write the answer in one line."},{label:"Ask again",text:"Repeat two more times, going one layer deeper each time."},{label:"Check it",text:"Would this still matter if nobody ever knew? If yes, you may have found a value."}],note:"Our own version of a common “why” exercise; it has not been tested as a separate technique."},technique:{name:"Chosen or should? check",origin:"Acceptance and Commitment Therapy · values work, as described by the Association for Contextual Behavioral Science",steps:["Write down one value you hold, in a short active phrase.","Ask whether you are holding it to avoid a feeling such as guilt, shame or fear.","Ask whether you are holding it mainly to please someone or to look good to others.","Ask whether it comes from a thought that says you should value it, rather than from caring about it.","If the answers are mostly no, keep it; if they are mostly yes, look for the value underneath or rewrite it in your own words."],evidence:"These questions follow ACT’s description of choosing values that are not driven by avoidance, social pressure or “should” thoughts. The check itself has not been tested as a stand-alone exercise.",sourceId:"meaning-act-values"},photo:{id:"1447752875215-b2761acb3c5d",alt:"A wooden footbridge through a green forest"}},{id:"meaning-4",title:"Meaning when things are hard",minutes:10,goal:"Learn how to find the part you can still choose when you face a situation you cannot change.",reading:["Frankl’s third source of meaning is the most demanding: the attitude you take toward suffering you cannot avoid. It is easy to misread. Frankl did not say that suffering is good or that you should seek it out. If suffering can be removed, the meaningful thing is to remove it, whether that means changing a job, leaving a harmful situation or getting medical help. His point was about what remains when something truly cannot be changed: a loss, an illness, a past event. Even then, he argued, you keep some freedom in how you carry it.","That freedom is usually small and practical. It might be the choice to stay kind while you are in pain, to keep one routine that makes you feel like yourself, or to let a loss deepen your care for the people still here. This is not the same as pretending to be fine. You can feel grief, anger and fear fully and still ask what you want your response to stand for. ACT makes a related point: values can guide what you do while difficult feelings are still present."],deeper:[{heading:"What this idea is not",paragraphs:["This lesson is not a claim that everything happens for a reason, and it is not a demand that you find a silver lining. Some things are simply painful and unfair. Searching for meaning too early, especially when someone else pushes you to, can feel like being told your pain is not allowed.","It is also not a replacement for help. Choosing your attitude works alongside practical steps and support from others, never instead of them."]},{heading:"When to get more support",paragraphs:["Hard seasons are part of life, and many people get through them with time, rest and the people around them. But if you have felt empty, hopeless or that life is meaningless for several weeks, or if daily life is becoming hard to manage, please talk to a doctor or a mental health professional. This course is not a substitute for treatment.","If you ever have thoughts of harming yourself, contact your local emergency number or a crisis line straight away. Reaching out is not a failure of meaning. It is one of the most meaningful things a person can do."],visual:{kind:"steps",title:"If a hard time does not ease",steps:[{label:"Notice",text:"Has the emptiness or hopelessness lasted for weeks, or is it growing?"},{label:"Tell someone",text:"Share how you feel with one person you trust."},{label:"Get help",text:"Talk to a doctor or a mental health professional."},{label:"In a crisis",text:"If you think about harming yourself, call your local emergency number now."}],note:"General safety guidance, not medical advice."}}],example:{title:"Elena, 52, primary school teacher",text:"Elena’s mother had moved into a care home with advancing dementia, and visits left Elena drained and tearful. She had tried everything she could think of to slow the decline, and nothing worked. One evening she wrote two lists: what she could still change and what she could not. The illness went on the second list. On the first she wrote the way she spent her visits. Instead of testing her mother’s memory, which upset them both, she started bringing old songs to hum together and a hand cream her mother liked. The visits were still sad. But Elena began to leave them feeling that she had shown up as the daughter she wanted to be."},practice:["Pick one current difficulty and split it into two lists: what you can still change and what you truly cannot.","For the first list, choose one practical step and decide when you will take it.","For the second list, write one sentence about how you want to carry it, starting with “Even so, I can…”."],reflection:"In a situation you cannot change, what would you like your response to stand for?",question:"What did Frankl mean by finding meaning in unavoidable suffering?",options:["That suffering is good for you and should be sought out.","That you should hide your pain and act as if you are fine.","That when something truly cannot be changed, you can still choose the attitude you take toward it."],correct:2,feedback:"Frankl was clear that avoidable suffering should be removed. The attitude you take matters for what remains when change is not possible, and it can coexist with grief and fear.",takeaway:"Change what you can; for what you cannot, choose how you want to carry it.",sources:["meaning-frankl","meaning-act-values"],visual:{kind:"compare",title:"Two lists for a hard situation",left:{label:"What I can change",items:["Asking for help or information","Practical steps, however small","Leaving what is harmful, if I can"]},right:{label:"What I cannot change",items:["The loss, the diagnosis or the past event","Other people’s choices","My stance toward it is still mine"]},note:"Our own illustration, based on Frankl’s idea of the attitude toward unavoidable suffering."},technique:{name:"The attitude question",origin:"Viktor E. Frankl · Man’s Search for Meaning (1946)",steps:["Name the situation in one plain sentence, without softening it.","Write down what you feel about it, and let those feelings be there.","Check honestly whether any part of it can still be changed, and plan a step for that part first.","For the part that cannot change, ask what kind of person you want to be while you carry it.","Choose one small action today that fits that answer."],evidence:"This sequence is our own way of applying Frankl’s idea of the attitude toward unavoidable suffering. It comes from his clinical and personal experience and has not been tested as an exercise. It is not a treatment for grief, trauma or depression.",sourceId:"meaning-frankl"},photo:{id:"1519681393784-d120267933ba",alt:"Stars above snowy mountains at night"}},{id:"meaning-5",title:"Picture the life you are aiming for",minutes:10,goal:"Use the Best Possible Self exercise to picture a future shaped by your values, and turn it into a first step.",reading:["The Best Possible Self exercise was developed by psychologist Laura King. You imagine yourself at some point in the future, after things have gone as well as they realistically could because you worked hard toward what matters to you. Then you write about that future for several minutes, in as much concrete detail as you can. The point is not to predict the future or to wish things into existence. It is to give your values a picture. When you can see what a life lived in a certain direction might look like, it becomes easier to take the first step toward it.","This is one of the better-studied positive psychology exercises. A 2019 meta-analysis pooled 29 studies with 2,909 participants. Compared with control conditions, the exercise improved optimism, positive feelings and wellbeing, and reduced negative feelings and depressive symptoms. The effects were small to medium, and the effect on depression was small. That is honest, useful evidence: a short writing exercise can shift how you feel about the future a little. It does not make that future happen on its own. That part still depends on what you do next."],deeper:[{heading:"Making the picture useful",paragraphs:["A vivid future is most helpful when it connects back to today. After writing, it helps to name the value your best possible self is living, the main obstacle that could get in the way, and a plan for that obstacle.","That second half has its own evidence. A meta-analysis of 21 studies with 15,907 participants found that contrasting a goal with the real obstacle and making an if–then plan had a small-to-medium average effect on reaching goals."],visual:{kind:"table",title:"From picture to plan",columns:["Step","Question","Example"],rows:[["Picture","What does my best possible future look like?","I run a small, calm design studio."],["Value","Which value is it living?","Making things that are clear and kind to use."],["Obstacle","What in me could get in the way?","I avoid showing my work."],["Plan","If that happens, then what will I do?","If I hesitate, then I send one piece to one person."]],note:"Our own example, combining the Best Possible Self exercise with goal-obstacle-plan thinking."}},{heading:"What the research says",paragraphs:["The largest effect in the meta-analysis was on positive feelings, and the smallest was on depressive symptoms. Studies differed in how often and how long people wrote, and most measured changes over days or weeks rather than years.","So the fair summary is this: the exercise reliably lifts mood and hope a little in the short term. Linking it to your values and to a first step is this course’s own addition, meant to turn that lift into action."]}],example:{title:"Jonah, 38, nurse",text:"Jonah had been feeling stuck in night shifts for years. On a day off he set a timer for fifteen minutes and wrote about himself five years on, with things having gone as well as they realistically could. To his surprise, the picture was not about money. It was about teaching: running training sessions for new nurses, calm and prepared. When he read it back, he named the value, “helping others become confident”, and the obstacle, his fear of speaking in front of groups. He wrote an if–then plan: if a chance to present comes up, then I will say yes before I can talk myself out of it. The next week he volunteered to run a ten-minute session at the ward meeting."},practice:["Set a timer for 15 minutes and write about your life a few years from now, after things have gone as well as they realistically could because you worked for them.","Underline the value that your best possible self is living, and name one inner obstacle that could get in the way.","Write one if–then plan for that obstacle and one small step you can take this week."],reflection:"Which value is quietly at the center of the future you pictured?",question:"What did the 2019 meta-analysis of the Best Possible Self exercise find?",options:["It guarantees that the imagined future will happen.","Small-to-medium improvements in optimism, positive feelings and wellbeing, with a small effect on depressive symptoms.","No effect on anything measured."],correct:1,feedback:"Across 29 studies, the exercise produced small-to-medium improvements, largest for positive feelings and smallest for depressive symptoms. It changes how you feel about the future, not the future itself.",takeaway:"Picture where your values could lead, then take the first step on your own two feet.",sources:["meaning-carrillo","meaning-best-possible-self","mcii"],visual:{kind:"bars",title:"Best Possible Self exercise vs control conditions",bars:[{label:"Positive feelings",value:.511,display:"d = 0.511"},{label:"Optimism",value:.334,display:"d = 0.334"},{label:"Wellbeing",value:.325,display:"d = 0.325"},{label:"Fewer negative feelings",value:.192,display:"d = 0.192"},{label:"Fewer depressive symptoms",value:.115,display:"d = 0.115"}],note:"Standardized effect sizes from a meta-analysis of 29 studies with 2,909 participants (Carrillo et al., 2019). Mostly short-term outcomes; this is not a test of this course.",sourceId:"meaning-carrillo"},technique:{name:"Best Possible Self",origin:"Laura A. King · Best Possible Self writing (2001)",steps:["Choose a point in the future, such as five years from now.","Imagine that everything has gone as well as it realistically could, because you worked hard and stayed true to what matters to you.","Write about that future continuously for about 15 minutes, in concrete detail: where you are, what you do, who is with you.","Do not worry about spelling or style; keep the pen moving.","If you like, repeat the exercise on a few different days and notice what stays the same."],evidence:"A meta-analysis of 29 studies found small-to-medium short-term improvements in optimism, positive feelings and wellbeing, with a small effect on depressive symptoms. How long and how often people wrote varied between studies.",sourceId:"meaning-best-possible-self"},photo:{id:"1501785888041-af3ef285b470",alt:"A calm lake surrounded by mountains"}},{id:"meaning-6",title:"One values-based decision a day",minutes:8,goal:"Turn your values into one small, concrete decision each day, and keep it going.",reading:["Values only change a life when they show up in behavior. ACT calls this committed action: building larger and larger patterns of behavior that are guided by your values, starting from steps you can actually take. The steps can be tiny. Being caring might mean sending one message. Being curious might mean reading five pages. Being healthy might mean going to bed twenty minutes earlier. What turns them into committed action is that you choose them on purpose, because of the direction they point in, and that you come back to them when you drift.","This is the idea behind making one decision a day. Each morning, or the night before, you ask one question: what is one small thing I can do today that moves me toward a value I care about? Then you decide when and where you will do it. If–then plans help here: a meta-analysis of 94 tests found that deciding in advance when, where and how to act had a medium-to-large effect on reaching goals. Some days you will miss. Research on habits suggests that missing once does not undo the process."],deeper:[{heading:"Why small works",paragraphs:["Big commitments made in a burst of inspiration often collapse on the first difficult day. Small, specific steps are easier to start and easier to repeat, and repetition in the same context is how actions slowly become automatic. A study that followed 96 people for 12 weeks found that the time this took varied a lot between people, so there is no magic number of days.","Keeping a simple record also helps. A meta-analysis of 138 studies found that monitoring your progress improved the chances of reaching goals, especially when progress was written down."],visual:{kind:"table",title:"From value to today’s decision",columns:["Value","Today’s decision","If–then plan"],rows:[["Being a present parent","Phone in a drawer during dinner","If I sit down to eat, then my phone goes in the drawer."],["Caring for my body","A 15-minute walk","If I finish lunch, then I walk around the block."],["Being a loyal friend","Message one friend","If I get on the bus home, then I text Ana."],["Learning and growing","Read five pages","If I get into bed, then I read before any screen."]],note:"Our own examples of linking values to if–then plans."}},{heading:"Common mistakes",paragraphs:["The first mistake is choosing a decision that is really a goal in disguise, such as “get fit”. Make it something you could finish today. The second is treating a missed day as proof that you do not really hold the value. A value is a direction; you can turn back toward it at any moment.","The third is only choosing decisions that feel comfortable. Committed action sometimes means doing something that brings up nervousness or doubt, because it matters. You can take those feelings with you."]}],example:{title:"Sofia, 45, office manager",text:"Sofia had finished this course with three values: being warm with her family, caring for her body and doing honest work. Each night she wrote one decision for the next day on a sticky note by the kettle. On Monday it was “ask Leo about his game, and listen”. On Tuesday it was “walk to the station instead of taking the bus”. On Wednesday she forgot entirely, felt the old voice call her hopeless, and wrote Thursday’s note anyway. By the end of the month she had kept about three in four. Her life did not look dramatically different, but she felt more like the person she had described in her values."},practice:["Choose one value from your list and write one decision you can finish today that points in its direction.","Turn it into an if–then plan by naming exactly when and where you will do it.","Tonight, mark whether you did it, and write tomorrow’s decision before you go to sleep."],reflection:"What is one small thing you could do today that the person you want to be would do?",question:"Which daily decision best fits the idea of committed action?",options:["Promise yourself to become a completely different person starting Monday.","Walk for 15 minutes after lunch today, because you value caring for your body.","Wait until you feel motivated before doing anything."],correct:1,feedback:"Committed action is a specific, doable step chosen because of a value. It does not require a big transformation or waiting for the right feeling.",takeaway:"One small decision a day, pointed in the right direction, adds up to a life.",sources:["meaning-act-values","if-then-plans","habits","monitoring"],visual:{kind:"cycle",title:"The daily values loop",center:"Your direction",nodes:[{label:"Value",text:"Pick one value you care about today."},{label:"Decide",text:"Choose one small action and when you will do it."},{label:"Act",text:"Do it, even if doubt or tiredness comes along."},{label:"Notice",text:"Record what happened, without judging yourself."},{label:"Adjust",text:"Make tomorrow’s step easier, harder or different."}],note:"Our own loop, based on committed action in ACT, if–then planning and progress monitoring."},technique:{name:"Committed action step",origin:"Acceptance and Commitment Therapy · committed action, as described by the Association for Contextual Behavioral Science",steps:["Choose one value and one area of life where you want to act on it.","Set a small, concrete goal that serves that value and can be done today or this week.","Name the inner barriers you expect, such as doubt, boredom or fear.","Decide how you will act while those feelings are present, instead of waiting for them to leave.","Take the step, then choose the next one, slowly building a larger pattern."],evidence:"Committed action is one of ACT’s six core processes, and the planning part draws on well-studied tools such as if–then plans. This simplified sequence has not been tested on its own.",sourceId:"meaning-act-values"},photo:{id:"1472214103451-9374bd1c798e",alt:"A green meadow with trees in soft light"}}]},ge=Object.freeze(Object.defineProperty({__proto__:null,COURSE:ce,SOURCES:ke},Symbol.toStringTag,{value:"Module"})),be=[{id:"stoic-epictetus-iep",title:"Keith H. Seddon · Epictetus (Internet Encyclopedia of Philosophy)",url:"https://iep.utm.edu/epictetu/",type:"guidance",finding:"Epictetus (c. 55–135 CE) was born enslaved in Hierapolis, later freed, and taught philosophy in Nicopolis, Greece; his student Arrian recorded his teaching in the Discourses and the Handbook. The article explains his central distinction between what is up to us (our opinions, intentions, desires, aversions and how we use impressions) and what is not (body, possessions, reputation, health, status and the outcomes of our actions), and his teaching that people are disturbed by their judgments about events rather than by the events themselves.",limitation:"An encyclopedia overview of the philosophy, not psychological research; it does not discuss modern therapy. The page was read; the ancient texts are paraphrased in this course, not quoted."},{id:"stoic-seneca-iep",title:"Robert Wagoner · Seneca (Internet Encyclopedia of Philosophy)",url:"https://iep.utm.edu/seneca/",type:"guidance",finding:"Seneca (c. 4 BCE–65 CE) was a Stoic philosopher who tutored the young Nero and later served as one of his advisers. The article explains the Stoic view, as Seneca presents it, that emotions such as anger involve judgments about value: the first movement in response to a situation is involuntary, but becoming angry requires agreeing to the judgment that you have been wronged.",limitation:"An encyclopedia overview, not research. It does not describe Seneca’s evening review or advice on anticipating misfortune; in this course those practices are sourced to the Stoic Week handbook. The page was read."},{id:"stoic-week-handbook",title:"Stoicism Today (Gill, Ussher, Sellars, LeBon, Evans, Garratt, Robertson) · Stoic Week 2016 Handbook (Modern Stoicism)",url:"https://modernstoicism.com/wp-content/uploads/2016/10/Stoic-Week-2016-Handbook-Stoicism-Today.pdf",type:"technique",finding:"The handbook teaches daily Stoic exercises with their ancient sources: the dichotomy of control from Epictetus’s Handbook (asking of each situation whether it is up to you); a morning meditation that rehearses the day’s likely difficulties and plans good responses; premeditation of adversity done realistically, at a manageable intensity and without rumination; a five-to-ten-minute evening review based on Seneca and Epictetus (what did I do badly, what did I do well, what could I do differently, reviewed as a friend would rather than harshly); and Marcus Aurelius’s view from above. It rejects the idea that Stoicism means suppressing emotion and describes Stoic psychology as an influence on modern cognitive behavioral therapy.",limitation:"Practice guidance written by philosophers, classicists and therapists, not a trial. It states that it is not a substitute for medical advice or treatment and that the course is not suitable for people with severe mental health problems such as clinical depression or PTSD. The PDF was read."},{id:"stoic-week-report",title:"Tim LeBon · Report on Stoic Week 2021 (Modern Stoicism)",url:"https://modernstoicism.com/wp-content/uploads/2022/01/Stoic-Week-2021-Results-Tim-LeBon-1-1.pdf",type:"research",finding:"1,369 people completed valid questionnaires at the start of the free seven-day online course and 459 at the end (a 33% completion rate); participants spent an average of 42 minutes a day on it. Among those who finished, flourishing rose by 11.5%, life satisfaction by 14.5% and positive emotions by 13%, while negative emotions fell by 21%.",limitation:"A report by the course organizers. Participants chose to take part, there was no control group, all measures were self-reported and two thirds of starters did not complete the final questionnaire, so it cannot show that Stoic practice caused the changes. The PDF was read."},{id:"stoic-kross-distancing",title:"Kross & Ayduk · 2017 · Self-distancing: theory, research, and current directions (Advances in Experimental Social Psychology, vol. 55)",url:"https://sites.lsa.umich.edu/emotion-selfcontrol-psych/wp-content/uploads/sites/1322/2017/09/Self-distancing-theory-research-future.pdf",type:"research",finding:"The review summarizes experiments comparing self-immersed reflection (reliving an event through your own eyes) with self-distanced reflection (watching yourself from a distance, like a fly on the wall). Distancing reduced negative emotion and rumination, shifted thinking from recounting details toward making sense of the event, sped blood pressure recovery, reduced aggressive responses and supported wiser reasoning; its benefits held up over time better than distraction. Imagining how you will feel in ten years reduced distress, apparently by highlighting that feelings pass. Using your own name or “you” in self-talk produced similar benefits. The authors trace the idea partly to Aaron Beck’s concept of distancing in cognitive therapy.",limitation:"Mostly short laboratory studies, often with students. Benefits were clearest for people who were more distressed and small or absent in some low-distress samples; the authors distinguish distancing to understand feelings from distancing to avoid them. The chapter PDF was read."},{id:"stoic-kross-self-talk",title:"Kross et al. · 2014 · Self-talk as a regulatory mechanism: how you do it matters (Journal of Personality and Social Psychology)",url:"https://doi.org/10.1037/a0035173",type:"research",finding:"Seven studies with 585 participants: reflecting on yourself with non-first-person pronouns and your own name, rather than “I”, increased self-distancing. In first-impression and public-speaking tasks this group performed better, felt less distress and ruminated less afterwards, and appraised future stressors more as challenges than as threats. A meta-analysis across the studies found the benefits did not depend on social anxiety.",limitation:"Short laboratory tasks; long-term and clinical effects were not tested. Only the abstract was read (via Europe PMC)."}],pe={id:"stoic",title:"Stoic Calm",subtitle:"Ancient tools for putting your energy where it can do some good",description:"What would change if you spent your energy only on what is actually yours to move? This course turns five Stoic practices into short daily exercises and checks each one honestly against modern psychology.",scope:"For adults who want steadier responses to stress, setbacks and uncertainty. Stoicism here does not mean suppressing emotions or putting on a brave face; feelings are welcome, and the practice is about what you do next. This is education and self-practice, not therapy, and it is not a substitute for treatment. If you live with anxiety, depression, trauma or intrusive worry, some exercises, especially imagining setbacks, may not suit you; please work with a qualified professional. If you are in crisis or thinking about harming yourself, contact your local emergency number now.",outcome:"A control sort for any worry, a way to catch the judgment between an event and your reaction, a gentle version of rehearsing setbacks, a step-back technique for heated moments, a five-minute evening review, and one small decision you act on today.",photo:{id:"1439066615861-d1af74d74000",alt:"A wooden pier on a still mountain lake"},lessons:[{id:"stoic-1",title:"What is up to you",minutes:8,goal:"Sort a current worry into what is up to you and what is not, and move your energy to the first list.",reading:["Epictetus was born enslaved in the first century and later taught philosophy in Greece. His student Arrian wrote down his lessons in two works, the Discourses and a short Handbook. The idea that opens the Handbook is simple and demanding. Some things are up to us: our judgments, our intentions, what we want and avoid, and how we choose to act. Other things are not: our body, our possessions, our reputation, other people and, importantly, the results of our actions. Epictetus argued that much of our distress comes from treating the second list as if it belonged to the first.","This is not a call to stop caring. You can care a great deal about a job interview. But the offer is not up to you; your preparation, your honesty in the room and your follow-up are. When you pour worry into the offer, the worry has nowhere to go. When you pour it into preparation, it turns into something useful. Modern Stoic teachers treat this as the most basic exercise in the tradition: ask of each situation whether it is up to you, and put your effort where the answer is yes. The rest you hold more lightly, not because it does not matter, but because gripping it does not help."],deeper:[{heading:"Why it works",paragraphs:["Worry tends to circle around outcomes: will they like me, will it work, will it happen. Outcomes depend on many things you cannot see or steer, so thinking about them rarely reaches an end point. Actions are different. An action has a first step, a time and a place, so thinking about it can finish in doing it.","The control sort does not remove the uncomfortable feeling. It gives the feeling a job. That practical idea links this ancient exercise with the modern planning research you will meet in the last lesson of this course."],visual:{kind:"steps",title:"The control sort",steps:[{label:"Name it",text:"Write the worry in one plain sentence."},{label:"Split it",text:"Draw two columns: up to me, and not up to me."},{label:"Check the first column",text:"Keep only your own judgments, intentions and actions there; move outcomes across."},{label:"Choose",text:"Pick one item from the first column to act on today."},{label:"Release",text:"For the second column, note that you have done your part."}],note:"Our step-by-step version of the dichotomy of control as taught in the Stoic Week handbook."}},{heading:"Common mistakes",paragraphs:["The first mistake is putting outcomes in the first column. Getting the job, being liked, recovering from an illness: you can influence them, but you do not decide them. What you decide is your effort, your attitude and your next step. Keeping those separate is the whole exercise.","The second mistake is using the idea to excuse passivity. If something unfair is happening, your response to it is up to you, and that response can include speaking up, asking for help or leaving. The dichotomy of control asks you to act well, not to shrug."]}],example:{title:"Leyla, 31, nurse",text:"Leyla had a performance review on Friday and spent Wednesday evening replaying every possible thing her manager might say. At ten she took a sheet of paper and drew a line down the middle. On the right she wrote what was not up to her: her manager’s mood, the budget for raises, and how a colleague had described a shift that went badly. On the left she wrote what was: bringing the patient feedback she had saved, asking one clear question about her next training step, and explaining the difficult shift calmly rather than defensively. She put the page in her bag and went to bed. The worry did not vanish, but it had shrunk to three concrete tasks. On Friday the review was mixed. She came out knowing she had done her part."},practice:["Write one worry that has been on your mind this week in a single sentence.","Split it into two columns, what is up to you and what is not, and move any outcome you placed on the left over to the right.","Circle one item in the left column and decide when today you will act on it."],reflection:"Where are you spending energy on something that is not yours to decide?",question:"In Epictetus’s distinction, which of these is up to you?",options:["Whether your application is accepted.","How carefully you prepare your application.","What other people think of your application."],correct:1,feedback:"Your preparation is your own action. Acceptance and other people’s opinions depend on things outside you, even though your effort can influence them.",takeaway:"Care about the outcome, and work on the part that is yours.",sources:["stoic-epictetus-iep","stoic-week-handbook"],visual:{kind:"compare",title:"Up to you, or not?",left:{label:"Up to you",items:["Your judgments about what happened","Your intentions and effort","How you respond, including what you say next"]},right:{label:"Not up to you",items:["Other people’s choices and opinions","Results, reputation and status","Health, possessions and much of what happens to your body"]},note:"Summarized from Epictetus’s Handbook as described in the Internet Encyclopedia of Philosophy and the Stoic Week handbook."},technique:{name:"The control sort",origin:"Epictetus · Handbook, recorded by Arrian (early 2nd century), as taught in the Stoic Week Handbook (Modern Stoicism, 2016)",steps:["Write down the situation that is troubling you.","Ask of each part of it: is this up to me?","List what is up to you as actions, judgments or intentions, not outcomes.","Choose one of those actions and decide when you will take it.","Remind yourself that the rest is not yours to decide, and let your attention return to the action."],evidence:"The distinction is a philosophical tool, not a tested treatment. It is part of Stoic Week, whose self-selected participants reported improved well-being in uncontrolled surveys, but no controlled study has tested the control sort on its own.",sourceId:"stoic-week-handbook"},photo:{id:"1507525428034-b723cf961d3e",alt:"A calm shoreline where clear water meets the sand"}},{id:"stoic-2",title:"The story between event and feeling",minutes:9,goal:"Catch the judgment that sits between something that happens and how you feel about it.",reading:["Epictetus taught that people are disturbed less by what happens than by the judgments they make about it. A message left unanswered is just a message left unanswered. The pain comes from the verdict we add: they are ignoring me, I have done something wrong, I do not matter. The Stoics practiced pausing before agreeing with such a verdict. Seneca described the first jolt of anger as involuntary, something like a flinch. In his account, anger proper begins only when we agree that we have been wronged and that striking back is right. The flinch happens to you; the agreement is yours.","Nearly two thousand years later, psychologist Albert Ellis built a therapy on a similar insight. His ABC model says that an activating event (A) leads to emotional and behavioral consequences (C) through beliefs (B), especially rigid musts and catastrophic conclusions. Aaron Beck, the other founder of cognitive therapy, helped people step back and see a thought as a thought rather than a fact. The Stoic Week team, which includes cognitive therapists, describes Stoic psychology as an influence on modern cognitive behavioral therapy (CBT). The point is not to feel nothing. It is to notice the story, test it, and choose one that fits the facts better."],deeper:[{heading:"Not suppressing, but examining",paragraphs:["A common picture of Stoicism is a stiff upper lip: feel nothing, show nothing. The ancient Stoics did aim to be free of what they called passions, emotions built on false judgments. But the Stoic Week handbook points out that Marcus Aurelius admired one of his teachers for being free of passions and full of affection at the same time. Stoic calm is not numbness.","Seneca’s distinction helps here. The first flinch of fear or anger is not a failure; it is a body doing its job. The practice begins in the moment after, when you ask what you are telling yourself and whether it is true. Pushing the feeling down skips that question. Examining the judgment answers it."]},{heading:"What the research says, and what it does not",paragraphs:["CBT, which grew partly from these ideas, has broad research support as a therapy. A review of 269 meta-analyses found the strongest evidence for anxiety disorders, anger problems and general stress, among others. That is evidence for therapy with a trained professional, not for reading a lesson.","Stoicism itself has been studied mostly through Stoic Week, a free seven-day online course. In 2021, 1,369 people filled in the opening questionnaire and 459 filled in the closing one. Those who finished reported higher well-being and fewer negative emotions. But participants chose to take part, there was no control group, two thirds did not complete the final questionnaire and everything was self-reported. These figures show what finishers said, not what Stoicism causes."],visual:{kind:"bars",title:"Stoic Week 2021: changes reported by people who finished",bars:[{label:"Flourishing",value:11.5,display:"+11.5%"},{label:"Life satisfaction",value:14.5,display:"+14.5%"},{label:"Positive emotions",value:13,display:"+13%"},{label:"Negative emotions (reduction)",value:21,display:"−21%"}],note:"459 of 1,369 starters finished. Self-selected participants, no control group, self-report measures. Figures from Tim LeBon’s Stoic Week 2021 report.",sourceId:"stoic-week-report"}}],example:{title:"Sam, 26, junior designer",text:"Sam’s lead replied to his first big mock-up with a single line: let’s talk tomorrow. By lunch Sam was sure he had failed and was drafting an apology. He remembered the ABC idea and wrote it out. A: a short message asking to talk. B: she hates it, I am out of my depth, I should have known better. C: dread, and an afternoon of anxious tinkering. Then he read B as if a stranger had written it. The message said nothing about quality, and short messages were how she scheduled every meeting. A better-fitting belief was: she wants to discuss it, and I do not yet know how she sees it. The dread eased a notch. He spent the afternoon listing his design choices and his reasons. The next day she asked for two changes and said the rest worked."},practice:["Recall one moment today when you felt a sharp emotion, and write the event in neutral words a camera could record.","Underneath, write the judgment you added, word for word, including any must, should or always.","Write one alternative judgment that fits the facts at least as well, and notice whether the feeling shifts even slightly."],reflection:"Which judgment do you tend to add to events without noticing?",question:"In the Stoic view, where does most of the distress in an upsetting moment come from?",options:["From the event itself, which cannot be changed.","From feeling any emotion at all.","From the judgment we add about what the event means."],correct:2,feedback:"Epictetus located the disturbance in our judgments about events. Feelings themselves are not the enemy; Seneca saw the first jolt as involuntary. The work lies in examining what we agree to next.",takeaway:"Between what happens and how you feel, there is a story, and you can check it.",sources:["stoic-epictetus-iep","stoic-seneca-iep","stoic-week-handbook","optimism-ellis","stoic-kross-distancing","optimism-hofmann","optimism-nhs-cbt","stoic-week-report"],visual:{kind:"cycle",title:"Event, judgment, feeling, action",nodes:[{label:"Event",text:"Something happens: a message, a delay, a comment."},{label:"Judgment",text:"You add a verdict: this is a disaster, they must respect me."},{label:"Feeling",text:"The emotion follows the verdict more than the event."},{label:"Action",text:"You act on the feeling, which shapes what happens next."}],center:"Pause at the judgment",note:"Our summary of Epictetus’s point and Albert Ellis’s ABC model."},technique:{name:"The ABC check, Stoic style",origin:"Albert Ellis · ABC model of rational emotive behavior therapy (first presented 1956)",steps:["A: write the activating event in plain, factual words.","B: write the belief you added, especially any must, should or catastrophe.","C: note the feeling and what you did, or wanted to do.","Dispute: ask whether the belief is true, whether it helps, and which part of it is up to you to hold differently.","Write a more flexible belief based on preference rather than demand, and one action it suggests."],evidence:"The ABC model is a core part of rational emotive behavior therapy, and CBT as a therapy has broad research support. This self-help version has not been tested on its own and is not a substitute for therapy with a trained professional.",sourceId:"optimism-ellis"},photo:{id:"1500534314209-a25ddb2bd429",alt:"Layers of hazy hills at dusk"}},{id:"stoic-3",title:"Rehearse the hard day, gently",minutes:9,goal:"Imagine a likely setback briefly and realistically, then plan your response, without sliding into worry.",reading:["The Stoics practiced something that sounds gloomy at first: imagining difficulties in advance. Later writers call it premeditatio malorum, the premeditation of adversities. Marcus Aurelius, a Roman emperor who kept a private notebook we now call the Meditations, wrote about starting the day by expecting to meet difficult people and deciding in advance how he would treat them. The purpose was not to invite disaster. It was to meet ordinary setbacks, like a delayed train or a rude reply, with a plan instead of a shock. The Stoic Week handbook compares it with modern exposure: looking calmly at a feared possibility, in small doses, can make it less frightening.","Done badly, this becomes rumination: replaying worst cases over and over with no end and no plan. The Stoic Week handbook is clear about the difference. Keep the imagined setback realistic, keep the intensity manageable, and pair it with how you want to respond. That last part matters. Research on mental contrasting, developed by Gabriele Oettingen and colleagues, found that picturing a real obstacle and then making an if-then plan had a small-to-medium average effect on reaching goals. The Stoic rehearsal and the modern plan meet in the same place: see the difficulty clearly, then decide what you will do about it."],deeper:[{heading:"Premeditation or worry?",paragraphs:["Worry and premeditation both look ahead, but they feel different. Worry repeats the same scene, grows more vivid and ends in dread. Premeditation visits the scene once, notes what is likely rather than everything that is possible, and ends with a response you could actually give.","A useful test: after two or three minutes, do you have a sentence that starts with “If this happens, I will…”? If yes, you rehearsed. If you are still circling, stop, stand up and do something with your hands. You can come back to it later."],visual:{kind:"steps",title:"A two-minute rehearsal",steps:[{label:"Pick",text:"Choose one realistic setback for today or this week."},{label:"Picture",text:"Imagine it once, briefly, at a manageable intensity."},{label:"Sort",text:"Notice which parts of it are up to you."},{label:"Plan",text:"Write one if-then sentence for your response."},{label:"Stop",text:"Close the exercise and return to your day."}],note:"Our summary, combining the Stoic Week handbook’s cautions with if-then planning."}},{heading:"Who should skip this one",paragraphs:["The Stoic Week handbook itself says its course is not suitable for people with severe mental health problems, naming conditions such as clinical depression and PTSD, and that it is not a substitute for medical advice. If imagining bad outcomes pulls you into panic, intrusive images or hours of worry, skip this lesson’s practice and talk with a qualified professional. Therapists who use exposure for anxiety do it carefully and with support, for good reason."]}],example:{title:"Ana, 38, primary school teacher",text:"Ana had a parent meeting at four with a father who had complained twice by email. In the morning, over coffee, she gave herself two minutes. She pictured the likely version, not the worst: he interrupts, raises his voice a little and says she is unfair to his son. She noticed her chest tighten and let it. Then she asked what was hers: her tone, the facts she brought and whether she stayed focused on the child’s progress. She wrote on a sticky note: if he interrupts, I will pause, say I want to hear him, and then return to the reading scores. At four, he did interrupt. Ana paused, as planned. The meeting was not warm, but it stayed on track, and she did not spend the evening replaying it."},practice:["Choose one realistic difficulty that could come up in the next day or two, not the worst thing you can imagine.","Picture it once for about a minute, noticing your feelings without pushing them away.","Write one sentence starting with “If this happens, I will…”, then close the exercise and move on."],reflection:"Which setback would feel lighter if you had already decided how to respond?",question:"What separates Stoic premeditation from rumination?",options:["Premeditation imagines the worst possible outcome as vividly as possible.","Premeditation is brief and realistic and ends with a planned response.","Premeditation means repeating the scene until the fear goes away."],correct:1,feedback:"Rehearsal visits a likely difficulty briefly, at a manageable intensity, and closes with a plan. Rumination repeats worst cases without an end or a decision.",takeaway:"See the hard moment once, decide your response, then return to today.",sources:["stoic-week-handbook","state-mental-contrasting","if-then-plans"],visual:{kind:"table",title:"Rehearsal or rumination?",columns:["Question","Stoic rehearsal","Rumination"],rows:[["How long?","A minute or two","Hours, on and off"],["What do you imagine?","A likely difficulty","The worst possible case"],["How does it end?","With an if-then plan","With more dread"],["What happens next?","You return to your day","The scene replays"]],note:"Our summary, based on the cautions in the Stoic Week handbook."},technique:{name:"Premeditation of adversity",origin:"Marcus Aurelius · Meditations (2nd century), as taught in the Stoic Week Handbook (Modern Stoicism, 2016)",steps:["Pick one realistic difficulty you may meet today.","Imagine it briefly and at a manageable intensity.","Remind yourself which parts of it are up to you.","Decide how you want to respond and put it into an if-then sentence.","End the exercise and turn your attention back to the present."],evidence:"No controlled trial has tested Stoic premeditation on its own. The closest modern evidence is for mental contrasting and if-then plans, which showed small-to-medium average effects on reaching goals in meta-analyses. It is not suitable for everyone who struggles with anxiety or intrusive thoughts.",sourceId:"stoic-week-handbook"},photo:{id:"1464822759023-fed622ff2c3b",alt:"Forested valleys below snowy mountains"}},{id:"stoic-4",title:"The view from above",minutes:9,goal:"Step back from a heated moment by changing your viewpoint, the words you use, or your sense of time.",reading:["In his Meditations, Marcus Aurelius often pictured his life from far away: the whole earth, crowds of people, centuries passing. Modern Stoics call this the view from above. From that height, the argument at breakfast or the tense email looks smaller, not because it does not matter, but because it takes its place among everything else. The exercise is less about feeling tiny and more about loosening the grip one moment can have on your whole attention. You are still in the scene. You simply see more of it than the part that hurts.","Psychologists Ethan Kross and Ozlem Ayduk have studied a close cousin of this idea, which they call self-distancing. In their experiments, people who replayed a painful memory as a fly on the wall, watching themselves from a distance, reported less negative emotion than people who relived it through their own eyes, and they made more sense of what had happened. Another route is language. In seven studies with 585 people, those who talked to themselves using their own name or “you” instead of “I” felt less distress, performed better on a stressful speech according to observers, and ruminated less afterwards."],deeper:[{heading:"Three ways to step back",paragraphs:["Kross and Ayduk’s review describes several routes to distance. You can change your viewpoint in space, as in the fly-on-the-wall exercise. You can change your words, by addressing yourself by name. Or you can change your viewpoint in time, by asking how you will feel about this in ten years. In their studies, the time route seemed to work by reminding people that feelings pass."],visual:{kind:"table",title:"Three ways to step back",columns:["Route","Try this","What studies found"],rows:[["Space","Watch the scene as a fly on the wall, seeing yourself in it.","Less negative emotion, more understanding, faster blood pressure recovery than reliving it."],["Words","Coach yourself by name or as “you”.","Less distress and rumination, better-rated speeches, more challenge than threat."],["Time","Ask how you will see this in ten years.","Less distress, linked to seeing feelings as temporary."]],note:"From Kross & Ayduk (2017) and Kross et al. (2014); mostly short laboratory studies."}},{heading:"Limits and fair questions",paragraphs:["Most of these studies were short laboratory experiments, often with students. Benefits were clearest for people who were already quite upset; in some studies people with little distress gained little. The authors also separate stepping back to understand a feeling from stepping back to avoid it. Distancing helps when you use it to look more clearly, not to look away.","The Stoics and the psychologists are not describing exactly the same thing. Marcus Aurelius aimed at a vast, cosmic perspective; the experiments ask for a few steps back. Both point the same way: a little distance makes room for a wiser response."]}],example:{title:"Priya, 33, software tester",text:"Priya was about to join a video call where a colleague had publicly blamed her team for a missed release. Her heart was racing and she had a sharp reply ready. With three minutes to go she tried two things. First she pictured the call from the corner of the room, as if watching two tired people in a busy company, one of whom was her. Then she talked to herself by name: Priya, you want the release fixed, not a win in the chat. You know the timeline. Say it once, calmly. She still felt angry when the call began. But she opened with the timeline instead of the reply, and the conversation moved to what each team needed. Afterwards she noticed she was not replaying it, which was new."},practice:["Think of a situation that is bothering you right now and notice how close and loud it feels.","Replay it for a minute as a fly on the wall, watching yourself in the scene from a distance.","Give yourself one sentence of advice using your own name or “you”, the way a calm friend would."],reflection:"How will this situation look to you ten years from now?",question:"In Kross and colleagues’ studies, what helped people handle a stressful speech?",options:["Talking to themselves by name or as “you” instead of “I”.","Replaying the worst moments through their own eyes.","Distracting themselves until the feeling vanished."],correct:0,feedback:"Non-first-person self-talk increased distance, reduced distress and rumination, and led to speeches that observers rated higher. The review also found that distancing held up better over time than distraction.",takeaway:"A few steps back can turn a flood into a view.",sources:["stoic-week-handbook","stoic-kross-distancing","stoic-kross-self-talk"],visual:{kind:"compare",title:"Immersed or distanced?",left:{label:"Through your own eyes",items:["Replays the details: what they said, how it felt.","Asks why me, again and again.","Feelings stay loud and return later."]},right:{label:"From a few steps back",items:["Sees yourself in the wider scene.","Asks what makes sense of this.","Emotion eases and the event feels clearer."]},note:"Our summary of self-immersed and self-distanced reflection in Kross & Ayduk (2017)."},technique:{name:"The view from above",origin:"Marcus Aurelius · Meditations (2nd century), as taught in the Stoic Week Handbook (Modern Stoicism, 2016)",steps:["Sit quietly and picture yourself where you are right now.","Slowly rise above the room, the street and the city, seeing yourself as a small figure in it.","Keep widening the view to the country, the planet and the long stretch of time.","From that height, look back at what is troubling you and notice its place among everything else.","Return slowly and ask what one wise response to it would be."],evidence:"The view from above itself has not been tested in trials. Experiments on self-distancing, a related idea, found less emotional reactivity and rumination, mostly in short laboratory studies; benefits were larger for people who were more distressed.",sourceId:"stoic-week-handbook"},photo:{id:"1506905925346-21bda4d32df4",alt:"Mountain ridges seen from above a sea of clouds"}},{id:"stoic-5",title:"The evening review",minutes:8,goal:"Close the day with a short, fair review that turns mistakes into one lesson for tomorrow.",reading:["Seneca, a Roman philosopher who tutored and later advised the emperor Nero, is one of the Stoics linked with a nightly habit: before sleep, going back over the day. Epictetus recommended the same kind of review. In its modern form, taught in the Stoic Week handbook, it takes five to ten minutes and three questions. What did I do badly? What did I do well? What could I do differently? The review is meant to be specific. Not “I was awful today” but “I cut Ali off in the meeting when he disagreed.” Specific actions can be learned from. Global verdicts about yourself cannot.","The handbook adds a condition that changes everything: review the day as a good friend or a fair teacher would, not as a prosecutor. A harsh review keeps you awake replaying scenes. A fair one names the slip, notes what went right, and ends with a small adjustment. There is a link here to the self-distancing research from the last lesson. When people reflect from a few steps back, they tend to move from recounting what happened to understanding it, and they ruminate less. The evening review works best in that spirit: a look back that makes sense of the day, then a closed notebook and sleep."],deeper:[{heading:"Keeping it from becoming rumination",paragraphs:["Put a limit on it: five to ten minutes, on paper, at roughly the same time each evening. Paper gives the review an end. When the three questions are answered, the day is closed.","Count the good as carefully as the bad. The second question is not decoration. If you only look for faults, the review turns into a list of charges. If you also look for what went well, you learn what to repeat."],visual:{kind:"cycle",title:"The review loop",nodes:[{label:"Act",text:"Live the day, making the best choices you can."},{label:"Review",text:"In the evening, answer the three questions on paper."},{label:"Adjust",text:"Pick one small change for tomorrow."},{label:"Rest",text:"Close the notebook and let the day end."}],center:"Learn, not punish",note:"Our summary of the evening meditation in the Stoic Week handbook."}},{heading:"What the evidence says",paragraphs:["No controlled trial has tested the Stoic evening review on its own. In Stoic Week it is one of several daily practices, and the course as a whole has been evaluated only with self-selected, self-reported surveys without a control group. The best reason to try it is practical: it is short, free and easy to drop if it does not help you.","If an evening review regularly leaves you more anxious or unable to sleep, move it earlier, shorten it or stop. If low mood or self-criticism is heavy and lasting, talk with a professional."]}],example:{title:"Tom, 52, shop owner",text:"Tom used to lie awake going over everything that had gone wrong in the shop. He decided to try the review at nine, at the kitchen table, with a small notebook. The first night he wrote: badly, snapped at a supplier on the phone when a delivery was late; well, stayed patient with a confused older customer and found her the right part; differently, when a delivery is late, ask for the new time before saying anything else. It took seven minutes. He closed the notebook and left it on the counter. He still thought about the supplier in bed, but the thought had somewhere to go: it was written down, with a plan. After two weeks he noticed the same kinds of slip showing up, which told him where to practice."},practice:["Set a five-minute timer this evening and write short answers to: what did I do badly, what did I do well, what could I do differently?","Rewrite any harsh sentence in the tone a fair friend would use, keeping the facts.","Choose one small adjustment for tomorrow, write it at the top of a new page, and close the notebook."],reflection:"What would a fair friend say about how you handled today?",question:"What tone does the modern Stoic evening review recommend?",options:["The tone of a strict judge, so you never repeat a mistake.","The tone of a fair friend who names mistakes and what went well.","No judgment at all: list only what went well so you sleep better."],correct:1,feedback:"The review names real slips and real successes, specifically and kindly, and ends with one adjustment. Harshness tends to feed rumination; ignoring mistakes teaches nothing.",takeaway:"Look back to learn, then close the day.",sources:["stoic-seneca-iep","stoic-week-handbook","stoic-kross-distancing","stoic-week-report"],visual:{kind:"steps",title:"Three questions before sleep",steps:[{label:"What did I do badly?",text:"Name one specific action, not a verdict on yourself."},{label:"What did I do well?",text:"Find at least one thing worth repeating."},{label:"What could I do differently?",text:"Turn the lesson into one small change for tomorrow."}],note:"From the evening meditation in the Stoic Week handbook, based on Seneca and Epictetus."},technique:{name:"Evening review",origin:"Seneca and Epictetus, as taught in the Stoic Week Handbook (Modern Stoicism, 2016)",steps:["Sit down at a set time in the evening with a notebook.","Go through the day briefly, in order, from morning to now.","Answer: what did I do badly, what did I do well, what could I do differently?","Use the voice of a fair friend, naming specific actions rather than judging yourself as a person.","Write one adjustment for tomorrow and close the notebook."],evidence:"The review has not been tested on its own in controlled studies. It is one part of Stoic Week, whose finishers reported improved well-being in uncontrolled, self-reported surveys.",sourceId:"stoic-week-handbook"},photo:{id:"1475924156734-496f6cac6ec1",alt:"Waves on a rocky shore at dusk"}},{id:"stoic-6",title:"One decision today",minutes:8,goal:"Turn the Stoic focus on what is up to you into one small, concrete decision you act on today.",reading:["For the Stoics, philosophy was a way of living, not only a set of ideas to admire. Everything in this course leads here. The control sort shows you where your power is. Checking your judgment keeps a story from steering you. Rehearsal prepares a response, distance cools a heated moment, and the evening review teaches you something about your day. None of it matters much until you do one thing differently. That is also the idea behind ODA: one decision a day, made on purpose, in the part of life that is actually yours to shape.","A good Stoic decision has three features. It is inside your control: an action, not an outcome. It is small enough to do today. And it is tied to a moment, so you do not have to rely on memory or willpower. Planning research helps with that last part. Across 94 tests, plans in the form “If situation X happens, then I will do Y” had a medium-to-large average effect on reaching goals, though newer analyses suggest the true effect may be smaller. Gabriele Oettingen’s WOOP method adds a wish and an obstacle to the plan; the research it rests on shows a small-to-medium effect."],deeper:[{heading:"Why small and specific",paragraphs:["Big resolutions usually live in the outcome column: get fit, be calmer, fix the relationship. A Stoic decision moves the resolution back into your own column: walk for ten minutes after lunch, take three breaths before answering my manager, ask my partner one real question at dinner. You can keep that decision today, however the day treats you.","Then let the result go. If you took the walk and still feel tired, the decision was kept. The outcome belongs to the second column. What you learned goes into tonight’s review."],visual:{kind:"compare",title:"Outcome resolution or Stoic decision?",left:{label:"Outcome resolution",items:["Get the promotion.","Stop being anxious.","Make them understand me."]},right:{label:"Stoic decision for today",items:["Send the project summary to my manager by 3 pm.","When my chest tightens, breathe slowly three times before replying.","Listen to their side for two minutes before giving mine."]},note:"Our own examples."}},{heading:"When the day goes wrong anyway",paragraphs:["Some days the plan will not happen. A child gets sick, a meeting runs late, energy runs out. The Stoic answer is not self-blame. What remains up to you is how you respond now: a smaller version of the same decision, or simply noting what got in the way for tonight’s review. Keep the thread, not a perfect record.","This course is a set of practices, not a treatment. If stress, low mood or anxiety are getting in the way of daily life, the most Stoic decision may be to ask for professional help, an action that is fully within your control."]}],example:{title:"Can, 29, sales assistant",text:"Can had been worried for weeks about money and about a tense relationship with his brother. Both felt too big to touch. On Sunday morning he did a control sort. His brother’s mood and the rent increase went in the second column. In the first went checking his spending for the month and getting in touch with his brother. He picked one decision for the day: if he finished lunch, then he would send his brother a short message asking how his new job was going. He wrote it on his phone’s lock screen. After lunch he almost skipped it, then sent it. The reply came in the evening, brief but friendly. Nothing was fixed. But that night, in his review, Can wrote that he had acted on something that was his, and chose tomorrow’s decision: the spending check."},practice:["Pick one worry or goal and write the part of it that is up to you as an action, not an outcome.","Shrink that action until you could do it today in under fifteen minutes.","Attach it to a moment with an if-then sentence, such as “If I finish lunch, then I will…”, and then do it."],reflection:"What is one small thing, fully up to you, that you could do today?",question:"Which of these is a Stoic-style decision for today?",options:["Become a calmer person this year.","Make sure my team approves my proposal.","If I open my laptop after lunch, then I will spend ten minutes outlining the proposal."],correct:2,feedback:"It is an action within your control, small enough for today, and tied to a moment by an if-then plan. The other two describe outcomes or long-term hopes.",takeaway:"Do one small thing that is yours, today, and let the rest be.",sources:["stoic-epictetus-iep","stoic-week-handbook","if-then-plans","oettingen-woop-method","mcii"],visual:{kind:"table",title:"From worry to one decision",columns:["Worry","Up to you","Decision for today"],rows:[["Will I get the job?","Preparation and follow-up","Practice my answer to the hardest question for ten minutes after dinner."],["Is my friend upset with me?","Reaching out and listening","Send a short, honest message before noon."],["Am I neglecting my health?","Movement and bedtime","Take a ten-minute walk after lunch."]],note:"Our own examples of the control sort turned into if-then decisions."},technique:{name:"WOOP",origin:"Gabriele Oettingen · Rethinking Positive Thinking (2014)",steps:["Wish: name something you want that is challenging but possible.","Outcome: picture the best result of it for a moment.","Obstacle: find the main obstacle in your way, often a habit or a feeling of your own.","Plan: write “If [obstacle], then I will [action]” and pick a time today to begin."],evidence:"Mental contrasting combined with if-then plans showed a small-to-medium average effect on reaching goals across 21 studies (g = 0.336). The official WOOP site belongs to the method’s developers and is not an independent evaluation.",sourceId:"oettingen-woop-method"},photo:{id:"1502082553048-f009c37129b9",alt:"A single tree standing in an open landscape"}}]},fe=Object.freeze(Object.defineProperty({__proto__:null,COURSE:pe,SOURCES:be},Symbol.toStringTag,{value:"Module"})),ve=[{id:"compassion-neff-definition",title:"Kristin Neff · What is self-compassion? (self-compassion.org)",url:"https://self-compassion.org/what-is-self-compassion/",type:"guidance",finding:"Neff defines self-compassion as offering yourself the warmth and understanding you would offer a struggling friend, with three components: self-kindness versus self-judgment, common humanity versus isolation, and mindfulness versus over-identification. She distinguishes tender self-compassion (comforting and accepting yourself) from fierce self-compassion (acting to protect yourself, set boundaries, pursue goals or leave harmful situations), and separates self-compassion from self-esteem, self-pity and self-indulgence.",limitation:"A definition written by the researcher who developed the concept, not a study; it explains the model rather than testing it. The page was read."},{id:"compassion-neff-exercises",title:"Kristin Neff · Self-Compassion (2011) and self-compassion exercises (self-compassion.org)",url:"https://self-compassion.org/",type:"technique",finding:"Neff offers practical exercises for building self-compassion, including asking how you would treat a friend, the self-compassion break (acknowledge the pain, recall common humanity, offer kindness, often with supportive touch), a self-compassion journal, and writing a letter to yourself from the perspective of an unconditionally loving friend.",limitation:"Practice guidance from the developer of the concept. The individual exercises have not each been tested in trials; the evidence comes from programs that combine them."},{id:"compassion-mindful-self-compassion-rct",title:"Neff & Germer · 2013 · A pilot study and randomized controlled trial of the Mindful Self-Compassion program (Journal of Clinical Psychology)",url:"https://doi.org/10.1002/jclp.21923",type:"research",finding:"In a randomized trial with community adults, the eight-week Mindful Self-Compassion program led to larger increases in self-compassion, mindfulness, compassion for others and life satisfaction, and larger decreases in depression, anxiety, stress and emotional avoidance, than a waitlist control. Gains were maintained at six-month and one-year follow-ups, and more practice was linked to larger gains in self-compassion.",limitation:"A small trial run by the program’s developers, compared with a waitlist rather than an active alternative, with mostly self-report measures. It tests the whole program, not single exercises."},{id:"compassion-ferrari",title:"Ferrari et al. · 2019 · Self-compassion interventions and psychosocial outcomes: a meta-analysis of RCTs (Mindfulness)",url:"https://doi.org/10.1007/s12671-019-01134-6",type:"research",finding:"Pooling 27 randomized controlled trials of self-compassion interventions, the meta-analysis found improvements across a range of psychosocial outcomes, including self-compassion itself, rumination, self-criticism, stress, depression and anxiety.",limitation:"Many included trials were small and varied in format, population and control condition; most outcomes were self-reported and follow-up periods were short."},{id:"compassion-gilbert-cft",title:"Gilbert · 2014 · The origins and nature of compassion focused therapy (British Journal of Clinical Psychology)",url:"https://doi.org/10.1111/bjc.12043",type:"research",finding:"Gilbert describes how compassion-focused therapy (CFT) was developed for people with high shame and self-criticism who could understand therapy’s logic but struggled to feel reassured or safe. It builds on a model of three interacting emotion regulation systems: threat and protection, drive and resource-seeking, and soothing, contentment and affiliation.",limitation:"A theoretical and clinical review rather than a trial. The three-systems model is a simplified clinical framework, and evidence for CFT as a therapy is still developing."},{id:"compassion-gilbert-mind",title:"Paul Gilbert · The Compassionate Mind (2009) and the Compassionate Mind Foundation",url:"https://www.compassionatemind.co.uk/",type:"technique",finding:"Gilbert’s compassionate mind training includes soothing rhythm breathing (slowing the breath to a steady, comfortable rhythm) and imagining your compassionate self, a wise, strong and caring version of you, as ways to activate the soothing system.",limitation:"Practice guidance from the developer of CFT and his foundation. These exercises are usually taught within therapy or structured training and have not been tested here as standalone self-help."},{id:"compassion-tangney-moral-emotions",title:"Tangney, Stuewig & Mashek · 2007 · Moral emotions and moral behavior (Annual Review of Psychology)",url:"https://doi.org/10.1146/annurev.psych.56.091103.070145",type:"research",finding:"The review distinguishes shame, a painful focus on the whole self, from guilt, a focus on a specific behavior. Guilt-proneness is linked with empathy and reparative action, while shame-proneness is linked with hiding, denial, defensive anger, blaming others and psychological symptoms.",limitation:"Mostly correlational research on dispositions (being shame-prone or guilt-prone); it does not show that switching from shame to guilt in a single moment changes outcomes."},{id:"compassion-brown-shame-resilience",title:"Brown · 2006 · Shame resilience theory: a grounded theory study on women and shame (Families in Society)",url:"https://doi.org/10.1606/1044-3894.3483",type:"research",finding:"Based on interviews with women, the study describes shame resilience along four continua: recognizing shame and understanding its triggers, practicing critical awareness, reaching out to others, and speaking shame.",limitation:"Qualitative, theory-building research with women only; it describes patterns but does not test whether practicing the four elements reduces shame."},{id:"compassion-brown-practice",title:"Brené Brown · I Thought It Was Just Me (2007) and brenebrown.com",url:"https://brenebrown.com/",type:"technique",finding:"Brown distinguishes shame (a painful feeling that you are flawed and unworthy) from guilt (discomfort about something you did) and presents shame resilience as a set of skills: recognizing shame and its triggers, reality-checking the messages behind it, reaching out, and speaking about shame.",limitation:"A popular book and website built on the author’s qualitative research; the practices have not been tested as an intervention."}],we={id:"compassion",title:"Self-Compassion",subtitle:"Treat yourself like someone you love, and still own your mistakes",description:"What if the voice in your head could be honest and on your side at the same time? This course explores what research and practice say about self-compassion, and how it can make taking responsibility easier, not harder.",scope:"For adults who are hard on themselves after mistakes, setbacks or painful moments. It is education and self-practice, not therapy. If you live with trauma, abuse, or shame that is persistent or overwhelming, please work with a qualified professional; self-compassion exercises can sometimes stir up old pain. If you are in crisis or thinking about harming yourself, contact your local emergency number now.",outcome:"A clear picture of what self-compassion is and is not, a two-minute self-compassion break for hard moments, a way to read your threat, drive and soothing systems, a plan for the next time shame hits, and a compassionate letter that ends in one concrete, accountable step.",photo:{id:"1470252649378-9c29740c9fa8",alt:"A quiet field in warm evening light"},lessons:[{id:"compassion-1",title:"Compassion is not weakness",minutes:8,goal:"See why being kind to yourself after a failure can support, rather than undermine, doing better.",reading:["Many people believe their inner critic is what keeps them in line. If they stopped being hard on themselves, the thinking goes, they would become lazy, careless or selfish. Psychologist Kristin Neff, who developed the modern research on this topic, describes self-compassion very differently: giving yourself the same warmth and understanding you would offer a good friend who is struggling. That does not mean pretending nothing went wrong. A good friend notices the mistake too. They just do not add contempt on top of it, and they stay on your side while you work out what to do next.","Research suggests this kindness is not the soft option it looks like. In a set of experiments by Juliana Breines and Serena Chen, people who were encouraged to take a self-compassionate view of a weakness, a moral mistake or a failed test became more motivated to improve. They were more likely to believe the weakness could change and more willing to make amends, and after failing a test they spent longer studying for the next one. The comparison groups, including one that received a boost to self-esteem, did not show the same pattern. Harshness can feel like responsibility. Often it just adds fear."],deeper:[{heading:"Why the critic feels so useful",paragraphs:["Self-criticism often starts as protection. If you criticize yourself first, nobody else can surprise you with it, and the sting feels like proof that you care. The trouble is what fear does to effort. When a mistake means an attack, the easiest way to avoid the attack is to avoid looking at the mistake: excuses, blaming someone else, or not trying again.","Self-compassion lowers the cost of looking. When the response to a failure is support rather than punishment, it becomes safer to admit what happened and study it. That is the logic behind Breines and Chen’s findings, and it is why this course keeps pairing kindness with accountability."],visual:{kind:"table",title:"Common beliefs about self-compassion",columns:["Common belief","What the evidence and definitions suggest"],rows:[["It will make me lazy.","In lab experiments it increased effort to improve, such as more study time after a failed test."],["It is just self-esteem.","Self-esteem depends on feeling good or special compared with others; self-compassion does not have to be earned."],["It is self-pity.","Self-pity gets stuck in why me; self-compassion remembers that everyone struggles."],["It lets me off the hook.","Its fierce side includes setting boundaries and pursuing goals."]],note:"Summarized from Breines & Chen (2012) and Kristin Neff’s definitions."}},{heading:"What the research says, and what it does not",paragraphs:["Across 56 randomized trials, self-compassion programs showed small-to-medium short-term reductions in stress, anxiety and depressive symptoms, although the overall risk of bias in those studies was high. A separate meta-analysis of 27 randomized trials found improvements in outcomes such as rumination, self-criticism, stress and depression. These are real but modest effects, mostly measured over weeks or months.","Breines and Chen mostly studied university students and measured motivation in the short term. So the honest claim is not that self-compassion guarantees success. It is that kindness and high standards do not have to be enemies."]}],example:{title:"Daniel, 34, project manager",text:"Daniel missed a deadline on a client report because he had underestimated how long the data cleaning would take. On the train home his head ran the usual script: sloppy, unprofessional, you always do this. He noticed he was also drafting excuses to send his boss. He tried a different question: what would he say to a colleague in the same spot? Probably that this was a real miss, that it happens to good people, and that the useful thing now was a new date and a better estimate next time. He typed that into his phone. The next morning he told his boss plainly what had happened, gave a realistic date and added a buffer line to his planning template. The report went out two days late. The template change stayed."},practice:["Write down, word for word, the last harsh thing you said to yourself after a mistake.","Rewrite it the way you would say it to a good friend in the same situation, keeping the facts but dropping the contempt.","Add one sentence that names a concrete next step, so the kind version still points toward doing better."],reflection:"What do you fear would happen if you stopped being hard on yourself?",question:"In Breines and Chen’s experiments, what happened when people took a self-compassionate view of a failure?",options:["They became more motivated to improve, for example studying longer after a failed test.","They stopped caring about the result.","They felt better but made no more effort than anyone else."],correct:0,feedback:"Compared with self-esteem boosting or neutral conditions, self-compassion increased motivation to improve and to make amends. Kindness lowered the fear of looking at the mistake.",takeaway:"You can hold a high standard and still be on your own side.",sources:["state-self-compassion-motivation","compassion-neff-definition","compassion-neff-exercises","self-compassion","compassion-ferrari"],visual:{kind:"compare",title:"After a mistake: inner critic or inner coach?",left:{label:"Inner critic",items:["Attacks the person: I am useless.","Makes looking at the mistake painful, so you avoid it.","Adds fear to the next attempt."]},right:{label:"Compassionate coach",items:["Names the behavior: that estimate was off.","Makes it safe to study what happened.","Points to one next step."]},note:"Our own summary of the contrast between self-judgment and self-kindness."},technique:{name:"How would you treat a friend?",origin:"Kristin Neff · Self-Compassion (2011)",steps:["Think of a time a close friend felt bad about a mistake or a struggle, and recall how you responded, including your words and your tone.","Now think of a time you felt bad about yourself, and recall how you responded to yourself.","Notice the difference between the two responses and ask yourself what drives it.","Write down how you might respond to yourself if you treated yourself the way you treat that friend.","Try that response the next time you struggle, and notice what changes."],evidence:"This reflection exercise has not been tested on its own. It targets the core of self-compassion as Neff defines it, and self-compassion programs that include exercises like it show small-to-medium short-term benefits in randomized trials.",sourceId:"compassion-neff-exercises"},photo:{id:"1474418397713-7ede21d49118",alt:"A person sitting on a rock, watching the sun rise over the mountains"}},{id:"compassion-2",title:"The three parts",minutes:9,goal:"Learn Neff’s three components of self-compassion and spot the one you most often miss.",reading:["Neff describes self-compassion as three parts working together. The first is self-kindness instead of self-judgment: being warm and supportive toward yourself when you struggle, rather than cold and cutting. The second is common humanity instead of isolation: remembering that suffering and imperfection are part of being human, not proof that something is uniquely wrong with you. The third is mindfulness instead of over-identification: seeing a painful feeling clearly, without pushing it away and without letting it swallow everything else. Each part has an opposite that most of us know well, and each one supports the other two.","The parts are easiest to see when one is missing. Kindness without mindfulness can turn into rushing to feel better before you have even admitted what hurts. Mindfulness without common humanity can leave you seeing your pain clearly but feeling utterly alone in it. Common humanity without kindness can sound like a shrug: everyone fails, so what. Together they sound more like this: this is painful, other people have been here too, and I can treat myself decently while I deal with it. You do not need to feel all three strongly. Noticing which one is weakest for you is a useful start."],deeper:[{heading:"What self-compassion is not",paragraphs:["Neff separates self-compassion from three look-alikes. Self-esteem depends on judging yourself positively, often by feeling special or above average, so it tends to disappear exactly when you fail. Self-pity focuses on your own troubles and forgets that other people have them too. Self-indulgence trades long-term wellbeing for short-term pleasure. Self-compassion, in her account, offers a steadier sense of worth that does not have to be won."],visual:{kind:"compare",title:"Two different questions",left:{label:"Self-esteem asks",items:["Am I better than others?","Did I succeed this time?","Am I good enough to deserve respect?"]},right:{label:"Self-compassion asks",items:["What do I need right now?","What would help me learn from this?","How can I care for myself while I fix it?"]},note:"Our own illustration of the distinction Kristin Neff draws."}},{heading:"Common mistakes",paragraphs:["The first mistake is treating self-compassion as a feeling you must produce. You do not have to feel warm; the intention to be kind already counts. The second is using the three parts to dodge responsibility, for example by saying everyone makes mistakes and then not repairing the one you made. Common humanity is meant to reduce isolation, not to dissolve accountability.","The third mistake is expecting it to feel natural straight away. If you have spoken to yourself harshly for years, kindness can feel awkward or even uncomfortable at first. Keep the practice short and light, and treat the awkwardness as part of learning something new."]}],example:{title:"Aisha, 27, junior doctor",text:"After a long shift, Aisha sat down with a notebook. Earlier that day she had missed a drug interaction that the pharmacist caught. Her first line was pure judgment: dangerous, should never have qualified. Underneath she wrote the three parts. Mindfulness: I feel scared and ashamed, and my chest is tight. Common humanity: interaction errors are a known risk, which is exactly why pharmacists double-check, and colleagues she respected had told her about their own near misses. Kindness: I am tired, and this hurts because I care about my patients. Then she added what she would do: read up on that class of drugs and ask her supervisor how the team flags these interactions. She did not feel great. She did sleep, and she did both things the next day."},practice:["Recall a recent difficult moment and write one sentence for each part: what you feel, who else has faced something like it, and one kind thing you can say to yourself.","Mark the sentence that was hardest to write; that part is your practice edge for this week.","Before the day ends, use that hardest part once more in a small moment of stress."],reflection:"Which of the three opposites is most familiar to you: self-judgment, isolation, or being swallowed by the feeling?",question:"Which set lists Neff’s three components of self-compassion?",options:["Self-kindness, common humanity and mindfulness.","Self-esteem, positive thinking and confidence.","Self-discipline, perfectionism and resilience."],correct:0,feedback:"Neff pairs each part with an opposite: self-kindness with self-judgment, common humanity with isolation, and mindfulness with over-identification.",takeaway:"This hurts, I am not alone in it, and I can be kind to myself while I deal with it.",sources:["compassion-neff-definition","compassion-neff-exercises","self-compassion"],visual:{kind:"table",title:"Three parts and their opposites",columns:["Part","Its opposite","What it can sound like"],rows:[["Self-kindness","Self-judgment","This is hard, and I am doing my best with it."],["Common humanity","Isolation","Other people struggle with this too."],["Mindfulness","Over-identification","I notice that I feel ashamed right now."]],note:"Components from Kristin Neff; the example sentences are our own."},technique:{name:"Self-compassion journal",origin:"Kristin Neff · Self-Compassion (2011)",steps:["At the end of the day, write down anything that made you feel bad, anything you judged yourself for, or any difficult experience.","For mindfulness, name the feelings as they are, without drama and without dismissing them.","For common humanity, write how this experience connects you with other people who have felt the same.","For self-kindness, write a few understanding, supportive words to yourself, in the tone you would use with a friend.","Keep it short; a few lines each evening is enough."],evidence:"The journal has not been tested on its own. The evidence is for self-compassion programs as a whole, which show small-to-medium short-term benefits in randomized trials.",sourceId:"compassion-neff-exercises"},photo:{id:"1529156069898-49953e39b3ac",alt:"Friends sitting arm in arm, seen from behind"}},{id:"compassion-3",title:"The self-compassion break",minutes:8,goal:"Learn a two-minute practice for the moment something hurts.",reading:["The self-compassion break is Neff’s short practice for the moment itself: the email you regret sending, the bad news, the argument that just ended. It follows the three parts in order. First you acknowledge that this is a moment of suffering, in plain words, such as this hurts or this is stressful. Then you remind yourself that struggle is part of life and that other people feel this way too. Finally you offer yourself some kindness, often with a hand on your heart or another gentle touch, and ask what you need to hear right now.","The words matter less than the direction. Some people find the idea of a moment of suffering too dramatic and prefer something like ouch, this is hard. Others dislike the hand on the chest and rest a hand on their arm instead, or simply breathe out slowly. The point is to turn toward the pain instead of away from it, to loosen the sense of being the only one, and to add warmth. The practice takes about two minutes. It is not meant to fix the problem, but it can steady you enough to face it."],deeper:[{heading:"Why supportive touch?",paragraphs:["Neff suggests supportive touch because warm, gentle contact is one of the most basic ways people are soothed, from infancy on. You do not have to believe in it for it to be worth trying. Many people find that a hand on the chest or a gentle squeeze of their own arm makes kind words feel less abstract.","If touch does not feel safe or pleasant for you, skip it. The practice works through attention and tone, not through any particular gesture."],visual:{kind:"compare",title:"Meeting a painful moment",left:{label:"Turning away",items:["Distract, scroll or push through without noticing.","Tell yourself you should not feel this way.","Replay what you did wrong."]},right:{label:"Turning toward",items:["Name it: this is hard.","Remember that others feel this too.","Offer one kind sentence or gesture."]},note:"Our own summary of the logic of the self-compassion break."}},{heading:"What the research says",paragraphs:["The self-compassion break is part of Mindful Self-Compassion, an eight-week program developed by Neff and psychologist Christopher Germer. In their randomized trial with community adults, people who took the program showed larger increases in self-compassion, mindfulness, compassion for others and life satisfaction, and larger decreases in depression, anxiety and stress, than people on a waitlist. The gains were still there six months and one year later.","It was a small trial, the comparison was a waitlist rather than another active course, and the developers ran it themselves. The two-minute break has not been tested on its own. It is best seen as one practical piece of a program with promising, not definitive, support."]},{heading:"If it stirs up pain",paragraphs:["Sometimes kindness toward yourself brings old hurt to the surface, the way warmth can make cold hands ache at first. That is not a sign that you are doing it wrong. Make the practice shorter, open your eyes, feel your feet on the floor, or stop and do something ordinary. If painful memories keep flooding in, or they are linked to trauma or abuse, please work with a qualified therapist rather than pushing on alone."]}],example:{title:"Tomás, 45, bus driver",text:"Tomás received a formal complaint from a passenger who said he had closed the doors on her. He had not seen her, and he felt sick about it all through his break. Sitting in the depot canteen, he tried the self-compassion break for the first time. He said in his head: this is really stressful. Then: every driver he knew had had a complaint at some point. He rested a hand on his forearm, which felt less odd than his chest, and asked what he needed to hear. The answer was simple: you are careful, and you can tighten your routine. The knot did not vanish, but it loosened. He wrote a calm reply to his supervisor that included one change: an extra mirror check before closing the doors at busy stops."},practice:["Pick a small stress from today and bring it to mind until you feel a little of it in your body.","Say three phrases silently: one that names the pain, one that remembers others feel this too, and one kind wish for yourself.","Add a gentle gesture if it feels right, then write one line about what you need next."],reflection:"Which words would sound both kind and believable to you in a hard moment?",question:"What is the order of the self-compassion break?",options:["Acknowledge the pain, remember common humanity, then offer yourself kindness.","Solve the problem first, then try to feel better about it.","List your achievements until the feeling passes."],correct:0,feedback:"The break follows Neff’s three parts: mindfulness of the pain, common humanity, then self-kindness. It steadies you so you can face the problem; it does not replace that step.",takeaway:"Two minutes of turning toward the pain can steady you enough to deal with it.",sources:["compassion-neff-exercises","compassion-mindful-self-compassion-rct","compassion-neff-definition"],visual:{kind:"steps",title:"The self-compassion break",steps:[{label:"Name it",text:"This hurts. This is stressful. Ouch."},{label:"Remember others",text:"Other people feel this too; I am not alone in it."},{label:"Offer kindness",text:"A hand on the heart or arm, and a wish to be kind to yourself."},{label:"Ask",text:"What do I need to hear, or do, right now?"}],note:"Retold in our own words from Kristin Neff’s practice; choose phrases that feel natural to you."},technique:{name:"Self-compassion break",origin:"Kristin Neff · Self-Compassion (2011); Mindful Self-Compassion program with Christopher Germer",steps:["Bring to mind a situation that is causing you stress or pain right now, and let yourself feel a little of it.","Acknowledge the pain in simple words, such as this hurts or this is hard.","Remind yourself that struggle is part of being human and that others feel this way too.","Place a hand on your heart or another comforting spot and feel its warmth.","Offer yourself a kind wish or ask what you need to hear, and say that to yourself."],evidence:"The break is part of the Mindful Self-Compassion program, which showed benefits over a waitlist in a small randomized trial with follow-up to one year. The short break on its own has not been tested in a trial.",sourceId:"compassion-neff-exercises"},photo:{id:"1499209974431-9dddcece7f88",alt:"A person opening their arms toward the setting sun"}},{id:"compassion-4",title:"Threat, drive and soothing",minutes:10,goal:"Use Paul Gilbert’s three-systems model to notice which system is running you, and how to call on soothing.",reading:["British psychologist Paul Gilbert developed compassion-focused therapy, or CFT, after noticing that many people with high shame and self-criticism could follow the logic of therapy but still could not feel any warmth or reassurance. His model describes three emotion systems. The threat system detects danger and responds with anxiety, anger or disgust, pushing you to fight, flee or freeze. The drive system seeks rewards and achievements and brings excitement and wanting. The soothing system brings a sense of safeness, contentment and connection when you are neither under threat nor chasing something.","All three are useful. Problems start when they fall out of balance. A harsh inner critic keeps the threat system switched on, and many people try to escape it by overworking the drive system: if I achieve enough, I will finally feel safe. That rarely lasts, because achievement is not what the threat system is waiting for. Gilbert’s idea is that compassion, including compassion toward yourself, strengthens the soothing system, which can calm threat from the inside. Slower breathing, a warm inner voice, the image of a kind face and the feeling of being cared for are all ways in."],deeper:[{heading:"What each system feels like",paragraphs:["It helps to learn the signature of each system in your own body and thoughts. You cannot argue a system into switching off, but you can notice which one is driving and choose what to feed."],visual:{kind:"table",title:"The three systems at a glance",columns:["System","Feels like","Typical thought","What helps"],rows:[["Threat","Tight chest, racing heart, anger or dread","Something is wrong; I am not safe.","Slowing down, cues of safety, a kind voice"],["Drive","Buzz, wanting, restlessness","I need to get or achieve more.","Enjoying it, then pausing on purpose"],["Soothing","Slower breathing, warmth, ease","I am okay right now.","Connection, rest, compassion practices"]],note:"Based on Paul Gilbert’s model; the examples are our own simplification."}},{heading:"What the research says",paragraphs:["The three-systems model is a clinical framework that draws on evolutionary and brain research, not a precise map of brain circuits, and Gilbert presents it as a simplification. Evidence for CFT as a therapy is growing but still early.","Research on warmth practices gives a sense of scale. A meta-analysis of loving-kindness and compassion meditation found that, in randomized studies, these practices increased everyday positive emotions compared with waitlists. Practices centered on loving-kindness showed a clearer effect than those centered on compassion, whose estimate was smaller and not statistically certain."],visual:{kind:"bars",title:"Kindness meditation and daily positive emotions",bars:[{label:"Loving-kindness focused",value:.424,display:"g = 0.424"},{label:"Compassion focused",value:.286,display:"g = 0.286"}],note:"Standardized effect sizes from a meta-analysis of 24 studies with 1,759 people. The compassion-focused estimate had a confidence interval that included zero, and 38.9% of the studies had a high risk of bias. This is not a test of CFT or of this lesson.",sourceId:"meditation-lovingkindness"}}],example:{title:"Mei, 38, accountant",text:"In the last week of the quarter, Mei noticed she had answered emails at midnight three nights running. Using Gilbert’s model, she asked which system was running her. Drive, clearly, but underneath it threat: a fear that one missed error would expose her as incompetent. More work was feeding the wrong system. That evening she set a timer for five minutes, slowed her breathing until each out-breath was a little longer than the in-breath, and let the voice in her head sound like the kind manager she once had. It felt silly for the first minute. By the end her shoulders had dropped. She closed the laptop at ten, left a note of three tasks for the morning, and slept better than she had all week."},practice:["Pause three times today and ask which system is loudest right now: threat, drive or soothing.","When it is threat, slow your breathing for one minute, letting each out-breath be a little longer than the in-breath.","Picture a warm, wise presence, real or imagined, and let it say one kind sentence to you."],reflection:"When your threat system fires, do you usually try to calm it or to outrun it with more achievement?",question:"In Gilbert’s model, which system helps calm the threat system from the inside?",options:["The soothing system, fed by safeness, connection and compassion.","The drive system, by achieving more.","The threat system itself, by planning for every danger."],correct:0,feedback:"Achievement can distract from threat for a while, but in Gilbert’s model it is the soothing system, built through warmth and connection, that brings a sense of safeness.",takeaway:"You cannot achieve your way out of feeling unsafe, but you can learn to soothe.",sources:["compassion-gilbert-cft","compassion-gilbert-mind","meditation-lovingkindness"],visual:{kind:"cycle",title:"Three emotion systems",center:"Balance",nodes:[{label:"Threat",text:"Detects danger: anxiety, anger, self-criticism. Protects you, but narrows attention."},{label:"Drive",text:"Seeks rewards and goals: wanting, excitement, achievement."},{label:"Soothing",text:"Safeness, contentment and connection; calms threat and steadies drive."}],note:"After Paul Gilbert’s compassion-focused therapy. The systems interact, and none of them is bad."},technique:{name:"Soothing rhythm breathing and the compassionate self",origin:"Paul Gilbert · The Compassionate Mind (2009)",steps:["Sit comfortably with your feet on the floor and let your breathing slow a little, without forcing it.","Let each out-breath be slightly longer than the in-breath, and find a gentle, even rhythm.","Soften your face and, if it helps, allow a slight, friendly expression.","Imagine yourself at your wisest and kindest: calm, strong and caring. Notice how that version of you would sit and speak.","From there, say one sentence to the part of you that is struggling."],evidence:"These are core exercises in compassion-focused therapy. CFT is a developing approach with early but encouraging evidence; the exercises have not been tested here as standalone self-help, and they are not a substitute for therapy.",sourceId:"compassion-gilbert-mind"},photo:{id:"1441974231531-c6227db76b6e",alt:"Sunlight falling through a calm forest"}},{id:"compassion-5",title:"Shame and guilt",minutes:10,goal:"Tell shame from guilt, and use four steps to move through shame instead of hiding.",reading:["Researcher Brené Brown draws a simple line between the two. Guilt is about something you did: that was a bad thing to do. Shame is about who you are: I am bad. The distinction builds on research by psychologist June Tangney and colleagues. Guilt focuses on a specific behavior and tends to point toward repair: apologizing, confessing, making things right. Shame targets the whole self. It makes people want to hide, deny or lash out, and in research it is linked with anger, defensiveness and distress rather than with doing better. Guilt can be uncomfortable and still useful. Shame mostly shrinks you.","From her interview research, Brown developed what she calls shame resilience: not avoiding shame, which nobody manages, but moving through it without losing yourself. She describes four elements. Recognize shame and know your triggers, including how it shows up in your body. Practice critical awareness, which means reality-checking the messages and expectations behind the shame. Reach out to someone you trust and tell your story. And speak shame: name it out loud instead of letting it work in silence. Self-compassion supports every step, because it turns a global verdict back into a specific event you can deal with."],deeper:[{heading:"The four elements in practice",paragraphs:["Brown’s study described shame resilience as a set of skills rather than a fixed trait, which means it can be practiced. The steps below retell her four elements in our own words. You do not have to do them in a perfect order; recognizing shame is usually the hardest and most important part."],visual:{kind:"steps",title:"Four elements of shame resilience",steps:[{label:"Recognize",text:"Notice the body signals and the situations that trigger shame for you."},{label:"Reality-check",text:"Ask whose expectations these are and whether they are realistic."},{label:"Reach out",text:"Tell a trusted person what happened, instead of hiding it."},{label:"Speak shame",text:"Name the feeling out loud: I feel ashamed about this."}],note:"After Brené Brown’s shame resilience theory; the wording is ours."}},{heading:"Why guilt can help and shame rarely does",paragraphs:["In Tangney’s research, people prone to guilt tended to show more empathy and to take reparative action, while people prone to shame were more likely to hide, feel defensive anger and blame others. That does not make guilt pleasant, and heavy guilt about things you did not cause is its own problem. But a clear, proportionate sense of having done something wrong is part of a working conscience.","Self-compassion helps move shame toward healthy guilt. When you do not have to defend your whole worth, you can look at the specific thing you did and decide what repair it calls for."]},{heading:"When to get more help",paragraphs:["Shame that is persistent, that follows you across many situations, or that is tied to trauma or abuse deserves more than a four-step card. A qualified therapist can help, and compassion-focused therapy was designed with high shame in mind. If shame ever comes with thoughts of harming yourself, contact your local emergency number or a crisis line now."]}],example:{title:"Jonas, 31, teacher",text:"Jonas snapped at a student in front of the class, and the boy went quiet for the rest of the lesson. By lunchtime Jonas had slid from I handled that badly to I am a terrible teacher and should not be doing this job. He recognized the familiar heat in his face and the urge to avoid the staffroom. Then he reality-checked: one harsh moment in six years, on a day with too little sleep, did not cancel his whole career. He reached out to a colleague he trusted and told her what had happened. Saying it out loud, he could separate the two things: he was not a bad teacher, but he had done something that needed repair. The next morning he apologized to the student privately and asked how he was doing."},practice:["Recall a recent moment when you felt bad about yourself and write down the exact sentence in your head.","Check whether it is guilt about an action or shame about your whole self, and rewrite any shame sentence as a specific behavior.","Decide whether that behavior needs repair, and if it does, name the smallest honest step, such as an apology or a correction."],reflection:"Who is one person you could reach out to the next time shame makes you want to hide?",question:"Which statement is guilt rather than shame?",options:["I was rude to her, and I need to apologize.","I am a horrible person.","I always ruin everything."],correct:0,feedback:"Guilt focuses on a specific behavior and points toward repair. The other two are global verdicts about the self, which is how shame speaks.",takeaway:"Name what you did, not what you are, and repair what you can.",sources:["compassion-brown-shame-resilience","compassion-brown-practice","compassion-tangney-moral-emotions","compassion-gilbert-cft"],visual:{kind:"compare",title:"Shame or guilt?",left:{label:"Shame",items:["I am bad.","Focuses on the whole self.","Pushes you to hide, deny or blame others.","Linked with defensive anger and distress."]},right:{label:"Guilt",items:["I did something bad.","Focuses on a specific action.","Pushes you toward apology and repair.","Linked with empathy."]},note:"After June Tangney’s research and Brené Brown’s distinction. Excessive guilt can also be harmful."},technique:{name:"Shame resilience",origin:"Brené Brown · I Thought It Was Just Me (2007)",steps:["When you feel exposed, small or unworthy, name the feeling to yourself as shame.","Notice where you feel it in your body and what situation set it off.","Reality-check the message: whose expectation is this, and is it realistic?","Reach out to one trusted person and tell them what happened.","Speak about the shame directly, and ask for what you need."],evidence:"Shame resilience theory comes from qualitative interview research, which describes patterns rather than testing an intervention. The distinction between shame and guilt behind it is well supported by research on moral emotions.",sourceId:"compassion-brown-practice"},photo:{id:"1544027993-37dbfe43562a",alt:"Two hands reaching toward each other"}},{id:"compassion-6",title:"A letter to yourself, and compassionate accountability",minutes:12,goal:"Write a compassionate letter about something you regret or dislike in yourself, and turn it into one accountable step.",reading:["Neff’s letter exercise asks you to write about something that makes you feel bad about yourself, such as a mistake, a habit or a trait, from the point of view of an imaginary friend who loves you unconditionally. This friend knows all your strengths and weaknesses, including the thing you are struggling with. They understand how your history and circumstances shaped you, and they are kind without being blind. Writing in their voice gives you a little distance from the critic. It also tends to produce a more balanced account of what happened than the one your threat system writes.","A compassionate letter is not an excuse note. The loving friend would also want you to change what harms you or others, and that is where accountability comes in. Neff calls this the fierce side of self-compassion: protecting yourself, setting boundaries and pursuing goals because you care about your wellbeing, not because you reject yourself. Tender self-compassion comforts and accepts; fierce self-compassion acts. So end your letter with the friend asking a practical question: given everything, what is one thing you could do differently, and what support would help you do it?"],deeper:[{heading:"How to write the letter",paragraphs:["Take fifteen minutes somewhere private. Write by hand if you can, and do not edit for style. Then put the letter away and read it again later, letting the words land."],visual:{kind:"steps",title:"Writing a compassionate letter",steps:[{label:"Choose",text:"Pick one thing you feel bad about, not your whole life story."},{label:"Imagine",text:"Picture a friend who loves you unconditionally and knows the full context."},{label:"Write",text:"Let them tell you what they understand, what they feel for you and what they hope for you."},{label:"Ask",text:"End with one practical change and the support you would need."},{label:"Reread",text:"Put it away, reread it later and notice how it lands."}],note:"Retold in our own words from Kristin Neff’s letter exercise."}},{heading:"Tender and fierce, together",paragraphs:["Most of us lean toward one side. Some people comfort themselves well but never set a limit; others push hard for change but never rest. Neff’s point is that both are forms of care. A parent who only soothes and a parent who only pushes are each offering half of what a child needs.","Compassionate accountability uses both. It names the harm honestly, feels the discomfort without collapsing into shame, repairs what can be repaired and plans one change. Breines and Chen’s findings fit here: when people met a moral mistake with self-compassion, they were more motivated to make amends and to avoid repeating it."]},{heading:"What the research says",paragraphs:["The letter is one of the practices taught in the Mindful Self-Compassion program, whose randomized trial found benefits over a waitlist that lasted to the one-year follow-up. A meta-analysis of 27 randomized trials of self-compassion interventions found improvements in outcomes such as rumination, self-criticism, depression and anxiety. The letter itself has not been tested in isolation, and the research base is still made up of mostly small studies, so it is fair to treat it as a promising practice rather than a proven treatment."]}],example:{title:"Rosa, 52, shop owner",text:"For years Rosa had hated how she handled money: she avoided opening letters from the bank until they piled up. She wrote a letter to herself from an imaginary friend who knew her well. The friend understood that she had grown up in a house where bills meant shouting, so avoiding them had once kept her safe. The friend also said, gently and clearly, that the pile was hurting her now and that she deserved better than dread. At the end the friend asked for one change. Rosa chose Saturday at nine, coffee in hand, to open every letter from the week, and asked her son to sit with her the first time. She reread the letter a week later. The pile was smaller, and the dread a little quieter."},practice:["Choose one thing about yourself that you feel bad about, and set a timer for fifteen minutes.","Write a letter to yourself from the point of view of a friend who loves you unconditionally and knows the full context.","End the letter with one concrete, accountable change and the support you will ask for, then put that change in your calendar."],reflection:"Which do you lean on more, tender or fierce self-compassion, and what would the other one add?",question:"What makes self-compassion accountable in this lesson?",options:["It combines comfort with honest naming of harm, repair and one concrete change.","It means never feeling bad about anything you do.","It means punishing yourself enough that you never repeat the mistake."],correct:0,feedback:"Tender and fierce self-compassion work together: comfort keeps shame from taking over, and fierce care turns the lesson into repair and change.",takeaway:"Love that tells the truth, then helps you do something about it.",sources:["compassion-neff-exercises","compassion-neff-definition","compassion-mindful-self-compassion-rct","compassion-ferrari","state-self-compassion-motivation","self-compassion"],visual:{kind:"table",title:"Tender and fierce self-compassion",columns:["Question","Tender","Fierce"],rows:[["What it does","Comforts, soothes, accepts","Protects, sets boundaries, pursues goals"],["What it can sound like","This is hard, and I am here for you.","This is not okay, and I will do something about it."],["When you may need it","You are hurting or grieving.","A line has been crossed or a goal matters."],["Without the other","Can drift into avoidance.","Can harden into harshness."]],note:"Tender and fierce self-compassion as described by Kristin Neff; the last row is our own reading."},technique:{name:"Compassionate letter",origin:"Kristin Neff · Self-Compassion (2011)",steps:["Choose something about yourself that makes you feel inadequate, ashamed or not good enough.","Imagine a friend who loves and accepts you unconditionally, knows all your strengths and weaknesses, and understands your history.","Write a letter to yourself from that friend’s perspective about the thing you are struggling with.","Let the friend acknowledge your pain, remind you that everyone is imperfect, and suggest, kindly, what might help you change.","Put the letter aside, then come back later and read it again slowly."],evidence:"The letter is part of the Mindful Self-Compassion program, which showed benefits over a waitlist in a small randomized trial. The letter has not been tested on its own.",sourceId:"compassion-neff-exercises"},photo:{id:"1455390582262-044cdead277a",alt:"A hand writing in a notebook with a pen"}}]},ze=Object.freeze(Object.defineProperty({__proto__:null,COURSE:we,SOURCES:ve},Symbol.toStringTag,{value:"Module"})),b=[T,I,H,W,M,R,G,L,J,Q,ae,te,oe,ue,ye,ge,fe,ze],Se=b.map(e=>e.COURSE).filter(e=>e.lessons.length>0),m=b.flatMap(e=>e.SOURCES),Be=[{id:"identity-dispenza-habit",title:"Dr. Joe Dispenza · Breaking the Habit of Being Yourself (Hay House, 2012) (Kendin Olma Alışkanlığını Kırmak)",url:"https://www.penguinrandomhouse.com/books/603255/breaking-the-habit-of-being-yourself-by-dr-joe-dispenza/",type:"technique",finding:"Dispenza dört haftalık bir meditasyon programı sunuyor. Önce dikkatini bedenine ve içinde bulunduğun ana getirirsin. Değiştirmek istediğin eski düşünce, duygu ve tepki kalıbını fark edip kabul edersin. Sonra onu bırakır, gün içinde ortaya çıktığında yakalayıp kesersin. Olmak istediğin yeni benliği, onun hislerini de içerecek biçimde zihninde prova edersin.",limitation:"Alışkanlıkların farkına varmak ve yeni davranışları prova etmek araştırmalarla iyi örtüşüyor. Yayıncının tanıtımı ayrıca, okurların kuantum fiziği ilkeleriyle biyolojilerini ve genetiklerini yeniden programlayabileceğini vaat ediyor; bu iddiaların bilimsel bir dayanağı yok. Yayıncının sayfası okundu; programın kendisi kontrollü çalışmalarda sınanmadı."},{id:"identity-dispenza-supernatural",title:"Dr. Joe Dispenza · Becoming Supernatural (Hay House, 2017) (Doğaüstü Olmak)",url:"https://books.google.com/books/about/Becoming_Supernatural.html?id=NWL6DwAAQBAJ",type:"technique",finding:"Kitap, önceki programı yürüyüş meditasyonları dahil yeni meditasyonlarla genişletiyor; “sonsuz olasılıkların kuantum alanına” uyum sağlama, iyileşme için kalp uyumu, mistik deneyimin kapısı olarak epifiz bezi ve vücudun enerji merkezlerini dengeleme gibi fikirler ekliyor.",limitation:"Bu meditasyonlardan yalnızca prova ve dikkat kısımları araştırmalarla örtüşüyor. Kuantum alanı, iyileşme, epifiz bezi ve enerji merkezleriyle ilgili iddialar bilimsel olarak desteklenmiyor. Yayıncının Google Books’taki tanıtımı okundu."},{id:"identity-dispenza-change",title:"Dr. Joe Dispenza · The Art of Change (blog, 2019) (Değişim Sanatı)",url:"https://drjoedispenza.com/dr-joes-blog/the-art-of-change",type:"technique",finding:"Dispenza değişimi, düşünmekten yapmaya ve yaptığını yaşamının parçası hâline getirmeye geçiş olarak anlatıyor. Önce otomatik düşünce ve tepkilerini fark edersin. Eski kalıbı daha az devreye girmesi için zihninde gözden geçirirsin. Kişiliğinin parçası olmuş duyguların alışılmış etkisini azaltır, tekrarla bedenini yeni bir duyguya alıştırırsın.",limitation:"Yazı ayrıca kuantum alanının kim olduğumuza karşılık verdiğini söylüyor; bu bilimsel olarak desteklenmiyor. Beyin bağlantılarına dair açıklamalar basitleştirilmiş. Yazının tamamı okundu."},{id:"identity-dispenza-new-self",title:"Dr. Joe Dispenza · The Habit of Your New Self (blog, 2018) (Yeni Benliğinin Alışkanlığı)",url:"https://drjoedispenza.com/dr-joes-blog/the-habit-of-your-new-self",type:"technique",finding:"Dispenza kalıcı değişimin tanıdık düşünce, davranış ve duyguları geride bırakmak anlamına geldiğini, yeni benliği yalnızca meditasyonda değil gün boyu uygulamak gerektiğini savunuyor: yürürken, otururken ve seçim yaparken gelecekteki benliğin gibi davranmak, bedene o benliğin duygularını hissetmeyi öğretmek.",limitation:"Kişisel bir blog yazısı, araştırma değil. Tekrarlı uygulama fikri alışkanlık araştırmalarıyla uyumlu; sinirsel açıklamalar basitleştirilmiş. Yazının tamamı okundu."},{id:"identity-clear-identity",title:"James Clear · Identity-based habits (Atomic Habits’ten alıntı, 2018) (Kimliğe dayalı alışkanlıklar)",url:"https://jamesclear.com/identity-based-habits",type:"technique",finding:"Clear değişimin üç katmanını anlatıyor: sonuçlar, süreçler ve kimlik. Önerdiği yaklaşım iki adımlı: nasıl biri olmak istediğine karar ver, sonra bunu küçük kazanımlarla kendine kanıtla; örneğin hareket alışkanlığına sadece birkaç düzine adımla başlamak.",limitation:"Bir yazarın pratik sentezi; sınanmış bir program değil. Yazarın kendi sayfası okundu."},{id:"identity-clear-votes",title:"James Clear · How to change your beliefs and stick to your goals (identity votes, Atomic Habits) (İnançlarını nasıl değiştirirsin: kimlik oyları)",url:"https://jamesclear.com/identity-votes",type:"technique",finding:"Clear her eylemi, olmak istediğin kişiye verilen bir oya benzetiyor: tek bir oy hiçbir şeyi belirlemez, her oya değil çoğunluğa ihtiyacın var ve küçük alışkanlıklar zamanla yeni bir kimlik için kanıt biriktirir.",limitation:"Öz algı araştırmalarıyla uyumlu, faydalı bir benzetme; ancak bir yöntem olarak sınanmadı. Yazarın kendi sayfası okundu."},{id:"identity-clear-stacking",title:"James Clear · Habit stacking (Atomic Habits, 2018; BJ Fogg’dan uyarlanmış) (Alışkanlık istifleme)",url:"https://jamesclear.com/habit-stacking",type:"technique",finding:"Clear’ın alışkanlık istifleme yönteminde, yeni davranışı mevcut bir alışkanlığa bağlarsın: “[Mevcut alışkanlık] öncesinde veya sonrasında [yeni alışkanlık] yapacağım.” Clear yöntemi BJ Fogg’un Tiny Habits çalışmasına dayandırıyor. Fogg buna çıpalama diyor. Clear, yeni davranışı ne sıklıkta yapacaksan o sıklıkta gerçekleşen somut bir hatırlatıcı seçmeni öneriyor.",limitation:"Alışkanlık istifleme, kendi adıyla ayrı bir yöntem olarak sınanmadı. Ortamın hatırlatıcı etkisi ve eğer-öyleyse planları üzerine araştırmalara dayanıyor. Yazarın kendi sayfası okundu."},{id:"identity-clear-environment",title:"James Clear · Environment design (jamesclear.com) (Çevre tasarımı)",url:"https://jamesclear.com/environment-design",type:"technique",finding:"Clear, iyi alışkanlıkların daha az çaba, istenmeyen alışkanlıkların daha çok çaba gerektirmesi için çevreni şekillendirmeni öneriyor (ihtiyacın olanı hazırla, görünür tut; ipucunu gözden uzağa taşı) ve insanların varsayılan seçeneklere sadık kalma eğiliminde olduğunu belirtiyor.",limitation:"Davranış bilimine dayanan pratik öneriler; belirli ipuçları bir paket olarak sınanmadı. Yazarın kendi sayfası okundu."},{id:"identity-clear-second-mistake",title:"James Clear · Avoid the second mistake (jamesclear.com, 2014) (İkinci hatadan kaçın)",url:"https://jamesclear.com/second-mistake",type:"technique",finding:"Clear, kaçırılan tek bir günün istisna olduğunu, üst üste iki günün ise yeni bir kalıp başlatabileceğini savunuyor; kaçırdığını telafi etmeye değil yoluna geri dönmeye odaklanmayı, alışkanlıkları programa bağlamayı ve aksamaya yol açanı ortadan kaldırmayı öneriyor.",limitation:"Bir pratik kural; sınanmış bir yöntem değil. Yazarın kendi sayfası okundu."},{id:"identity-oyserman",title:"Daphna Oyserman · Identity-based motivation (USC research overview) (Kimliğe dayalı motivasyon)",url:"https://dornsife.usc.edu/daphna-oyserman/identity-and-self/",type:"research",finding:"Kimliğe dayalı motivasyon kuramına göre hangi kimliklerin akla geldiği bağlama bağlı; insanlar o anda etkin olan bir kimlikle uyumlu hissettiren eylemleri tercih ediyor ve aynı zorluk önemin (“bu benim için önemli”), imkânsızlığın (“benim gibiler için değil”) ya da gelişimin (zor zamanlar karakter kazandırır) işareti olarak okunabiliyor.",limitation:"Bir araştırmacının kendi araştırma programına dair özeti; arkasındaki çalışmalar çoğunlukla öğrencilere ve okul başarısına odaklanıyor. Genel bakış sayfası okundu."},{id:"identity-pathways",title:"Oyserman, O’Donnell, Sorensen & Wingert · 2021 · Pathways-to-Success classroom intervention (Başarıya Giden Yollar sınıf müdahalesi)",url:"https://files.eric.ed.gov/fulltext/ED618114.pdf",type:"research",finding:"Chicago’nun yoksulluğun yoğun olduğu 10 okulunda, 1.142 sekizinci sınıf öğrencisiyle çalışma yapıldı. Öğretmenlerin yürüttüğü 12 oturumluk program, kimliğe dayalı motivasyonu artırdı. Öğretmenler programı tasarlandığı biçime daha bağlı kalarak uyguladığında akademik sonuçlar da iyileşti. Programa bağlılığın %60’tan %80’e çıkması, akademik performansta 0,50 standart sapmalık farkla birlikte görüldü.",limitation:"Ergenlere yönelik bir okul programı. Sonuçlar, öğretmenlerin programı tasarlandığı biçimde uygulama düzeyine göre incelendi. Yetişkinlerin kendi başlarına yaptığı bir alıştırmanın aynı sonucu vereceğini göstermez. Özet ve özetleme metni okundu."},{id:"identity-bem",title:"Bem · 1972 · Self-perception theory (Öz algı kuramı)",url:"https://www.sciencedirect.com/science/chapter/bookseries/pii/S0065260108600246",type:"research",finding:"Bem, insanların kendi tutum ve duygularını kısmen, dışarıdan bir gözlemcinin yapacağı gibi kendi davranışlarından ve koşullarından çıkararak öğrendiğini öne sürdü; özellikle içsel ipuçları zayıf ya da belirsiz olduğunda.",limitation:"Desteği karışık, başka açıklamalarla yarışan klasik bir kuram; yeni bir kimliğin ne kadar hızlı oluştuğunu öngörmüyor. Bölüm özeti okundu."},{id:"identity-hershfield",title:"Hershfield · 2011 · Future self-continuity (Gelecekteki benlikle süreklilik)",url:"https://pmc.ncbi.nlm.nih.gov/articles/PMC3764505/",type:"research",finding:"Bu derlemeye göre, gelecekteki kendisiyle benzerlik ve bağ hisseden, onu canlı biçimde hayal edip olumlu gören kişiler geleceğine yarar sağlayan seçimlere daha yatkın. Örneğin kendilerinin yaşlandırılmış görüntüsünü gören kişiler, kontrol gruplarına göre varsayımsal olarak daha fazla emeklilik tasarrufu ayırdı.",limitation:"Çalışmaların çoğu para ve kısa laboratuvar görevleriyle ilgili; kişisel değişim programlarıyla değil. Derleme ve özet okundu."},{id:"identity-cole",title:"Cole, Smith, Ragan, Suurmond & Armitage · 2021 · Mental simulation and behavior change meta-analysis (Zihinsel simülasyon ve davranış değişimi meta-analizi)",url:"https://pmc.ncbi.nlm.nih.gov/articles/PMC8500882/",type:"research",finding:"94 rastgele kontrollü çalışma (123 etki, 5.685 kişi): gelecekteki davranışı zihinde canlandırmak, sonraki davranışı genel olarak orta düzeyde değiştirdi (g = 0,49). Kendini iyi performans gösterirken prova etmek (g = 0,67) ve standart performans provası (g = 0,48) en iyi sonucu verdi; istenen sonucu hayal etmenin etkisi küçüktü (g = 0,23); yalnızca süreç adımlarını hayal etmek güvenilir değildi (g = 0,17, beş etki).",limitation:"Katılımcıların çoğu öğrenciydi; bazı alt türler az sayıda çalışmaya dayanıyor. Davranışlar çoğunlukla sağlık, spor ve beceri görevleriydi, kimliğin kendisi değil. Makalenin özeti ve bulgular bölümü okundu."},{id:"identity-toth",title:"Toth et al. · 2020 · Does mental practice still enhance performance? A 24-year follow-up (Zihinsel pratik hâlâ performansı artırıyor mu? 24 yıllık takip)",url:"https://www.sciencedirect.com/science/article/abs/pii/S1469029219301530",type:"research",finding:"1995–2018 arasında yayımlanan 37 çalışma (115 etki): zihinsel pratiğin performans üzerinde küçük ama anlamlı olumlu bir etkisi vardı (r = 0,131); etki, pratiğin süresine, görevin türüne ve hayal türüne göre değişti. Fiziksel pratik, tek başına zihinsel pratikten daha etkiliydi.",limitation:"Ağırlıklı olarak motor ve spor becerileri; kişilik değişimini, ruh hâlini ya da hastalığı sınamıyor. Özet okundu."},{id:"identity-gollwitzer",title:"Gollwitzer & Sheeran · 2006 · Implementation intentions meta-analysis (Uygulama niyetleri meta-analizi)",url:"https://www.sciencedirect.com/science/chapter/bookseries/abs/pii/S0065260106380021",type:"research",finding:"94 bağımsız testte, eğer-öyleyse planları (uygulama niyetleri) hedefe ulaşmada orta ile büyük arası olumlu bir etki gösterdi (d = 0,65). Planlar, seçilen durumu fark etmeyi kolaylaştırdı ve planlanan tepkiyi daha otomatik hâle getirdi.",limitation:"Çalışmaların hedefleri ve ortamları çok farklıydı; yayımlanmış çalışmalar etkileri olduğundan büyük gösteriyor olabilir. Planların herkes için ya da uzun vadeli kimlik değişimi için aynı işe yaradığını göstermiyor. Özet okundu."},{id:"identity-lally",title:"Lally, van Jaarsveld, Potts & Wardle · 2010 · How are habits formed (Alışkanlıklar nasıl oluşur)",url:"https://www.researchgate.net/publication/32898894_How_are_habits_formed_Modeling_habit_formation_in_the_real_world",type:"research",finding:"96 gönüllü, kendi seçtikleri günlük bir yeme, içme ya da aktivite davranışını 12 hafta boyunca aynı bağlamda tekrarladı. Otomatiklik, sonra düzleşen bir eğri boyunca yükseldi; bu düzeyin %95’ine ulaşma süresi 18 ile 254 gün arasında değişti (verisi modele uyan 39 kişide ortanca yaklaşık 66 gün). Tek bir fırsatı kaçırmak alışkanlık oluşumunu belirgin biçimde etkilemedi.",limitation:"Küçük ve kendi bildirimine dayalı bir çalışma; model, yeterli verisi olan kişilerin yarısından azına uydu ve gözlenen 84 günün ötesindeki süreler tahmin. Özet okundu; 66 günlük ortanca, aynı ekibin sonraki bir makalesinde ve ikincil özetlerde aktarıldığı şekliyle tam metinden alındı."},{id:"identity-gardner",title:"Gardner, Lally & Wardle · 2012 · Making health habitual (Sağlığı alışkanlık hâline getirmek)",url:"https://pmc.ncbi.nlm.nih.gov/articles/PMC3505409/",type:"research",finding:"Yazarlar, alışkanlık araştırmalarını doktorlar için özetlerken otomatikliğin ortalama 66 gün sonra düzleştiğini, bunun kişiden kişiye epey değiştiğini, basit eylemlerin zorlayıcı olanlardan daha hızlı otomatikleştiğini ve ara sıra bir günü kaçırmanın alışkanlık oluşumunu ciddi biçimde bozmadığını bildiriyor. Önerileri: basit bir eylem seç, onu tutarlı bir zamanda ve yerde yap, tekrar et.",limitation:"Yeni bir deney değil, anlatısal bir derleme ve uygulama rehberi. Makalenin tamamı okundu."},{id:"identity-wood-everyday",title:"Wood, Quinn & Kashy · 2002 · Habits in everyday life (Gündelik hayatta alışkanlıklar)",url:"https://dornsife.usc.edu/wendy-wood/wp-content/uploads/sites/183/2023/10/Wood.Quinn_.Kashy_.2002_Habits_in_everyday_life.pdf",type:"research",finding:"Saatlik tutulan iki günlük çalışmasında davranışların %35’i (1. çalışma) ve %43’ü (2. çalışma) neredeyse her gün, genellikle aynı yerde yapılan alışkanlıklardı. Alışkanlıklar sırasında insanların düşünceleri yaptıklarıyla yalnızca %40 ve %44 oranında örtüşüyordu; alışkanlık dışı davranışlarda bu oran %70 ve %60’tı.",limitation:"Yalnızca ABD’li üniversite öğrencileri; alışkanlık, sıklık ve sabit yerle tanımlandı. Makalenin özeti ve özetleme metni okundu."},{id:"identity-wood-runger",title:"Wood & Rünger · 2016 · Psychology of habit (Alışkanlık psikolojisi)",url:"https://www.annualreviews.org/content/journals/10.1146/annurev-psych-122414-033417",type:"research",finding:"Bu derleme, alışkanlıkları aynı eylemi aynı koşullarda tekrar ederken oluşan tepkiler olarak tanımlıyor. Sonrasında aynı koşullar bu tepkileri tetikliyor. Alışkanlıklar az çabayla devreye giriyor. İnsanların niyetleri değişse bile sürebiliyor.",limitation:"Anlatısal bir derleme; belirli bir yöntemi sınamak yerine mekanizmaları açıklıyor. Özet okundu."},{id:"identity-killingsworth",title:"Killingsworth & Gilbert · 2010 · A wandering mind is an unhappy mind (Harvard Gazette report) (Dalgın zihin mutsuz zihindir)",url:"https://news.harvard.edu/gazette/story/2010/11/wandering-mind-not-a-happy-mind/",type:"research",finding:"Yaklaşık 2.250 yetişkinle yapılan bir akıllı telefon çalışmasında yaklaşık 250.000 veri noktası toplandı. İnsanların aklı, zamanın %46,9’unda başka yerdeydi. Neredeyse her etkinlikte bu oran en az %30’du. Aklı başka yerde olan kişiler daha az mutluydu.",limitation:"Uygulama kullanan, çoğunlukla ABD’li gönüllüler. Veriler gözleme dayalı; zaman gecikmeli analiz zihin dalgınlığının mutsuzluktan önce geldiğini düşündürdü, ancak bu kontrollü bir deney değil. Science makalesinin bir üniversite haber özeti okundu."},{id:"identity-lieberman",title:"Lieberman et al. · 2007 · Putting feelings into words (affect labeling) (Duyguları sözcüğe dökmek)",url:"https://sanlab.psych.ucla.edu/wp-content/uploads/sites/31/2015/05/Lieberman_AL-2007.pdf",type:"research",finding:"Beyin tarayıcısındaki 30 yetişkinde, bir yüzdeki duyguya bir sözcük seçmek (“kızgın” ya da “korkmuş” gibi), yüzün cinsiyetine uyan bir isim seçmeye göre daha düşük amigdala tepkisiyle ve sağ ventrolateral prefrontal korteksteki daha yüksek etkinlikle ilişkiliydi.",limitation:"Resimlere verilen kısa tepkilere bakan tek ve küçük bir laboratuvar çalışması; duyguları adlandırmanın haftalar içinde ruh hâlini iyileştirdiğini göstermiyor. Makale okundu."},{id:"identity-breines",title:"Breines & Chen · 2012 · Self-compassion increases self-improvement motivation (Öz şefkat kendini geliştirme motivasyonunu artırır)",url:"https://journals.sagepub.com/doi/abs/10.1177/0146167212445599",type:"research",finding:"Dört deneyde, bir zayıflığa, başarısızlığa ya da ahlaki bir hataya şefkatli bakmaya yönlendirilen kişiler, benlik saygısı ya da nötr kontrol koşullarındakilerden daha fazla gelişme motivasyonu gösterdi; örneğin ilk sınavda başarısız olduktan sonra zor bir sınava daha çok zaman ayırarak çalıştılar.",limitation:"Çoğunlukla öğrencilerle yapılan kısa laboratuvar deneyleri; uzun vadeli davranış ölçülmedi. Özet okundu."},{id:"identity-harkin",title:"Harkin et al. · 2016 · Does monitoring goal progress promote goal attainment? (Hedefte ilerlemeyi izlemek hedefe ulaşmayı destekler mi?)",url:"https://eprints.whiterose.ac.uk/id/eprint/87431/",type:"research",finding:"19.951 kişiyle yapılmış 138 çalışmanın meta-analizi, ilerleme izlemeyi artıran müdahalelerin hedefe ulaşmayı iyileştirdiğini buldu (d = 0,40). İlerleme fiziksel olarak kaydedildiğinde ya da başkalarına bildirildiğinde etkiler daha büyüktü.",limitation:"Hedefler ve izleme yolları çok çeşitliydi; derleme, bu dersteki gibi belirli bir haftalık gözden geçirme biçimini sınamıyor. Özet okundu."}],Te={id:"identity",title:"Yeni benlik",subtitle:"Kim olduğunu küçük adımlarla değiştir. Her adım bir oy.",description:"Kalıcı değişim, yalnızca kendini yapmaya zorladıklarından değil, kendini nasıl biri olarak gördüğünden de başlar. Otomatikleşmiş eski tepkilerini fark et. Kısa bir sabah provası ve her gün küçük adımlarla yeni benliğini hayata geçir.",scope:"Gündelik düşünce, duygu ve tepkilerini değiştirmek isteyen yetişkinler için. Dr. Joe Dispenza ve James Clear’ın fikirlerinden yararlanır. Araştırmaların hangi fikirleri desteklediğini, hangilerini desteklemediğini açıkça anlatır. Terapi değildir; depresyon, kaygı, travma ya da başka bir hastalığın tedavisi değildir. Zorlanıyorsan bir sağlık uzmanıyla konuş. Kriz anında 112’yi ara.",outcome:"Eski benliğini ve seçtiğin yeni benliğini anlatan bir metin, 10 dakikalık sabah provası, zor anlar için üç eğer-öyleyse planı ve ilk aylarda sana yardımcı olacak haftalık gözden geçirme.",photo:{id:"1611569518992-0927098278b7",alt:"Yeşil ağaçların arasındaki toprak yolda tek başına yürüyen bir kadın"},lessons:[{id:"identity-1",title:"Eski benliğinle tanış",minutes:8,goal:"Günlerin çoğunda tekrarladığın düşünce, duygu ve tepkilerini dürüstçe, kendine nazik davranarak anlat.",reading:["Gününün büyük kısmında aynı şeyleri tekrarlarsın. Uyanınca aynı sorunları düşünür, tanıdık ruh hâllerine girer, aynı insanlara aynı tepkileri verirsin. Dr. Joe Dispenza, Breaking the Habit of Being Yourself kitabında bu bütüne “eski benlik” diyor. Bu, kötü bir insan olduğun anlamına gelmiyor. Yalnızca çok tekrar ettiğin davranışların otomatikleştiğini anlatıyor. Araştırmalar da gündelik yaşamın büyük bölümünün alışkanlıklardan oluştuğunu gösteriyor. İki günlük tutma çalışmasında, davranışların üçte biri ile neredeyse yarısı her gün aynı yerde tekrarlanıyordu. İnsanların aklı da çoğu zaman başka yerdeydi.","Değişim, bu otomatik düzeni açıkça görmekle başlar. Bu derste kendini yargılamadan bir liste çıkaracaksın. En sık hangi düşüncelerin geldiğine, ardından ne hissettiğine ve ne yaptığına bakacaksın. Kendini, birini merakla gözlemleyen dostça bir araştırmacı gibi anlat: somut konuş, hakaret etme. “Tembelim” deyince neyi değiştireceğin belli olmaz. “Öğle yemeğinden sonra masamda ‘bu bana fazla geliyor’ diye düşünüp yirmi dakika telefonda geziniyorum” dersen, nerede araya girebileceğini görürsün."],deeper:[{heading:"Önce neden fark etmek gerekiyor?",paragraphs:["Alışkanlıkları yeni aldığın kararlardan çok, bulunduğun koşullar tetikler. Wendy Wood ve Dennis Rünger’e göre beyin, sık tekrar edilen bir tepkiyi kolayca devreye sokar. Hedeflerin değişse bile aynı ortam bu tepkiyi yeniden başlatabilir. Bu yüzden yılbaşında aldığın karar, sıradan bir salı öğleden sonra eski alışkanlığına yenilebilir.","Dispenza da benzer bir yerden başlar. Yeni biri olmaya çalışmadan önce, geride bırakmak istediğin düşünce, duygu ve davranışları ayrıntısıyla tanırsın. Fark etmediğin bir döngüye ara veremezsin."],visual:{kind:"cycle",title:"Eski benlik nasıl devam eder?",center:"Eski benlik",nodes:[{label:"Tanıdık ortam",text:"Aynı yer, zaman, kişi ya da ruh hâli."},{label:"Tanıdık düşünce",text:"Alıştığın düşünce: “Yine aynı şey oluyor.”"},{label:"Tanıdık duygu",text:"İyi ya da kötü, artık alıştığın ruh hâli."},{label:"Tanıdık tepki",text:"Düşünmeden verdiğin tepki."},{label:"Tanıdık sonuç",text:"“Ben zaten böyleyim” demenin kanıtı gibi görünür."}],note:"Alışkanlık araştırmalarına ve Dispenza’nın anlatımına dayanan basit bir şema. Gerçek yaşam daha karışık olabilir. Döngünün her aşamasında araya girebilirsin."}},{heading:"Sık yapılan hatalar",paragraphs:["Listeyi kendini yargılamak için kullanmak. Amacın bilgi toplamak. Kendine sert etiketler koyarsan merak etmek yerine savunmaya geçebilirsin. Bu da olanları fark etmeyi zorlaştırır.","Yalnızca davranışlara bakmak. Eski benliğinin bir parçası da düşünceler ve ruh hâlleridir. “Spora gitmiyorum” bir bilgi verir. “‘Çok yorgunum’ diye düşünüp keyifsiz hissedince spora gitmiyorum” ise daha çok şey anlatır. Böylece düşünceyi ve duyguyu daha erken yakalayabilirsin."]},{heading:"Ne zaman uzman desteği gerekir?",paragraphs:["Uzun süren keyifsizlik, panik, geçmişteki acı olayları yeniden yaşıyormuş gibi hissetmek ya da kendine zarar verme düşünceleri varsa, bu listeyle tek başına başa çıkmaya çalışma. Bir doktorla ya da ruh sağlığı uzmanıyla konuş. Kriz anında 112’yi ara. Bu kurs gündelik davranış kalıpları içindir; tedavinin yerini tutmaz."]}],example:{title:"Leyla, 34, proje koordinatörü",text:"Leyla sıradan bir çarşamba günü için telefonuna üç hatırlatıcı kurdu. 10.40’ta yazdı: yöneticisinden kısa bir e-posta okuyordu, “Beni dikkatsiz sanıyor” diye düşünüyordu, göğsü sıkışıyordu. Yanıtını dört kez yeniden yazmıştı. 14.15’te: öğle yemeğini atlamıştı, “Vaktim yok” diye düşünüyordu, huzursuz ve gergindi. 18.30’da: kimsenin istemediği bir raporu yeniden kontrol etmek için işte kalmıştı. O gece notlarında ortak bir şey gördü: küçük bir tetikleyici, yetersizliğinin anlaşılacağı korkusu ve gereğinden fazla hazırlanma telaşı. Henüz bir şeyi düzeltmeye çalışmadı. “Eski Leyla” hakkında tarafsız iki cümle yazdı. Rahatladığını fark edince şaşırdı. Artık bu kalıbın nerede başlayıp nerede bittiğini görebiliyordu."},practice:["Bugün için üç hatırlatıcı kur ve her çaldığında tek satır yaz: ne düşünüyordum, ne hissediyordum, ne yapıyordum.","Bu akşam notlarını oku ve birden fazla kez ortaya çıkan düşünceyi, duyguyu ya da tepkiyi daire içine al.","Eski benliğinin iki cümlelik portresini, tanımaya başladığın bir arkadaşını anlatır gibi tarafsız sözcüklerle yaz."],reflection:"Hangi düşüncen ya da duygun o kadar tanıdık ki artık neredeyse fark etmiyorsun?",question:"Eski benliğini tanımak için en yararlı not hangisi?",options:["Ben sadece tembel biriyim.","Öğle yemeğinden sonra masamda “Bu bana fazla geliyor” diye düşünüyor, üzerimde bir ağırlık hissediyor ve telefonda geziniyorum.","Yarından itibaren tamamen başka biri olacağım."],correct:1,feedback:"Somut bir not, ortamı, düşünceyi, duyguyu ve davranışı gösterir. Böylece nerede araya girebileceğini görürsün. Etiketler ve büyük sözler neyi değiştireceğini göstermez.",takeaway:"Bir kalıbı değiştirmek için önce fark etmen gerekir. Ona merakla bak.",sources:["identity-dispenza-habit","identity-wood-everyday","identity-wood-runger"],visual:{kind:"table",title:"Eski benliğini tanıma listen",columns:["Katman","Kendine sor","Örnek"],rows:[["Düşünceler","Çoğu gün kendime ne söylüyorum?","“Hiç vaktim yetmiyor.”"],["Duygular","En çok hangi ruh hâline alıştım?","Öğleden önce hafif bir endişe"],["Tepkiler","O ruh hâline girince ne yapıyorum?","E-postayı yine kontrol ediyorum, öğle yemeğini atlıyorum"],["Ortam","Genellikle nerede ve ne zaman başlıyor?","Masamda, 10 ile 11 arasında"]],note:"Kendi listeni doldur. Her şeyi yazman gerekmiyor. Somut ol ve kendine nazik davran."},technique:{name:"Eski benliğini tanıma listesi",origin:"Dr. Joe Dispenza · Breaking the Habit of Being Yourself (2012)",steps:["Değiştirmek istediğin bir alan seç; örneğin işteki stres ya da evde verdiğin tepkiler.","Bu alanda aklından en sık geçen düşünceleri, kendine söylediğin sözlerle yaz.","Bu düşüncelerle birlikte ne hissettiğini ve bunu bedeninde nerede fark ettiğini yaz.","Ardından genellikle ne yaptığını ya da söylediğini anlat. Bunlar otomatik tepkilerin.","Bütün kalıbı çoğunlukla tetikleyen yerleri, zamanları ve kişileri not et.","Listeyi yeniden oku. Kendini suçlamadan, şimdiye kadar böyle davranmış olduğunu kabul et. Bu dürüst bakış başlangıç noktan."],evidence:"Kendi kalıplarını fark edip yazmak, alışkanlık araştırmalarıyla örtüşüyor. Bu araştırmalar, gündelik davranışların çoğunu tanıdık koşulların tetiklediğini gösteriyor. Listenin kendisi ayrı bir yöntem olarak sınanmadı. Onu bir tedavi olarak değil, nereden başlayacağını gösteren bir harita olarak kullan.",sourceId:"identity-dispenza-habit"},photo:{id:"1519087630026-63fb0dab69bb",alt:"Duvardaki aynada kendi yansımasına bakan bir kadın"}},{id:"identity-2",title:"Ezberlenmiş duygular",minutes:9,goal:"Sık sık yaşadığın için kişiliğinin parçası sandığın bir duyguyu fark et.",reading:["Dispenza, sık yaşadığın bir duygunun zamanla kendiliğinden ortaya çıkmasını anlatıyor. Her toplantıdan önce endişe. Mutfağa girer girmez sinirlenmek. Dinlenince suçluluk duymak. Bunlara “ezberlenmiş duygular” diyor. İlk başta gerçek olaylara tepki olarak ortaya çıkmış olabilirler. Ama tekrarlandıkça, henüz bir şey olmadan gelmeye başlarlar. Sen de “Ben zaten kaygılı biriyim” diye düşünürsün.","Bu fikirden yararlanmak için Dispenza’nın bütün kuramını kabul etmen gerekmiyor. Alışkanlık araştırmalarına göre, tekrar edilen tepkileri zamanla ortam tetiklemeye başlar. Bazı duygusal tepkiler de benzer biçimde işliyor olabilir, ancak bunu doğrudan inceleyen araştırmalar daha az. Bazı araştırmalar, duyguyu sözcüklere dökmenin onu hafifletebileceğini de düşündürüyor. Bir beyin görüntüleme çalışmasında, bir yüzdeki duyguyu adlandıranların amigdalasında daha az etkinlik görüldü. Amigdala, tehditlere verdiğimiz tepkilerde rol oynayan bir beyin bölgesi. Bugün en tanıdık duygunu fark etmeyi ve adını koymayı deneyeceksin."],deeper:[{heading:"Araştırma ne diyor",paragraphs:["Matthew Lieberman’ın çalışmasında 30 yetişkin, beyinleri taranırken duygu gösteren yüzlere baktı. “Kızgın” ya da “korkmuş” gibi bir sözcük seçtiklerinde, yüzün cinsiyetine uygun bir isim seçtikleri zamana göre amigdala daha az tepki verdi. Duyguyu adlandırırken daha etkin olan tek bölge, beynin ön kısmında kendini kontrol etmeyle ilişkili bir bölgeydi.","Bu, küçük bir laboratuvar çalışması. Amigdalanın birkaç saniye daha az tepki vermesi, haftalarca daha iyi hissetmek demek değil. Yine de gündelik bir deneyimle örtüşüyor: “Midemde korkuyu hissediyorum” demek, duyguyla arana biraz mesafe koyabilir. “Her şey ters gidiyor” demek ise bu alanı açmaz."],visual:{kind:"compare",title:"Bir duyguyla özdeşleşmek ve onu adlandırmak",left:{label:"Onunla özdeşleşmek",items:["Ben işe yaramazım.","Her şey ters gidiyor.","Ben zaten böyleyim."]},right:{label:"Onu adlandırmak",items:["Midemde bir korku fark ediyorum.","İşte eski pazartesi endişem.","Bu duygu tanıdık ve geçiyor."]},note:"Duygunun adını koymak, onunla tartışmak ya da onu bastırmak değildir."}},{heading:"Dispenza’nın hangi iddiaları desteklenmiyor?",paragraphs:["Dispenza, kitaplarında ve blogunda bundan çok daha fazlasını öne sürüyor. Duyguların genleri ve biyolojiyi yeniden programlayabileceğini, hastalıkları iyileştirebileceğini söylüyor. Kim olduğumuza karşılık vererek çevremizdeki olayları düzenlediği söylenen bir “kuantum alanından” da söz ediyor. Bu iddiaları bilimsel araştırmalar desteklemiyor. Bu iddialar yüzünden tıbbi tedavini geciktirme ya da değiştirme.","Yararlanabileceğin pratik fikir şu: tanıdık duyguyu erken fark et, adını koy ve aynı düşünce ve tepkilerle onu beslememeyi seç. Zamanla başka bir duygunun da sana tanıdık gelmesine fırsat verirsin."]},{heading:"Bir duygu alışkanlıktan fazlası olduğunda",paragraphs:["Bazı duygulara kulak vermek gerekir. Gerçek bir haksızlık karşısında öfkelenmek, kayıptan sonra yas tutmak, güvensiz bir ortamda korkmak gibi. Sürekli kaygı ya da keyifsizlik de uzman desteği gerektirebilir. Bu ders, gündelik yaşamda alışkanlığa dönüşmüş duygularla ilgilidir. Tedavinin yerini tutmaz."]}],example:{title:"Daniel, 41, öğretmen",text:"Her pazar akşamı altı civarında Daniel’in içine ağır bir korku yerleşirdi. Yıllarca bunu, gelecek haftanın kötü geçeceğine işaret saydı. Akşamı okul e-postalarına bakıp ailesine terslenerek geçiriyordu. Bu pazar aynı his gelince kendine “İşte yine o eski pazar korkusu” dedi. Omuzlarını kulaklarına kadar kaldırdığını fark etti ve yavaşça nefes verdi. Gerçekten hazırlaması gereken tek işi yazdı, on beş dakikada bitirdi ve bilgisayarı kapattı. Duygu geçmedi ama hafifledi. Artık akşamını o belirlemiyordu. Kızıyla bir film izledi. Pazartesi geldiğinde de hafta beklediği kadar kötü değil, gayet sıradandı."},practice:["Çoğu gün gelen bir duygu seç ve genellikle ne zaman geldiğini, bedeninde nerede hissettiğini yaz.","Bir dahaki sefere ortaya çıktığında ona içinden “eski endişe” ya da “pazartesi sinirliliği” gibi kısa bir ad ver.","Adını koyduktan sonra üç yavaş nefes al ve sor: bu duygu kontrolü elinde tutmasaydı şu an ne yapardım?"],reflection:"Hangi duyguyu o kadar sık yaşıyorsun ki onu kişiliğinin parçası sanmış olabilirsin?",question:"Bu dersin temel önerisine en uygun tepki hangisi?",options:["Bu duygunun kişiliğinin değişmez bir parçası olduğunu kabul etmek.","Yeterince uzun süre mutlu hissederek genlerini değiştirmeye çalışmak.","Tanıdık duyguyu erken fark etmek, adlandırmak ve bir sonraki eylemini seçmek."],correct:2,feedback:"Tanıdık bir duyguyu fark edip adlandırmak, bir sonraki adımını seçmen için küçük bir alan açar. Duygu yoluyla genleri değiştirme ya da iyileşme iddiaları araştırmalarla desteklenmiyor.",takeaway:"Sık yaşadığın bir duygu, kim olduğunu tek başına belirlemez.",sources:["identity-dispenza-change","identity-dispenza-habit","identity-dispenza-supernatural","identity-lieberman","identity-wood-runger"],visual:{kind:"cycle",title:"Bir duygu nasıl ruh hâline, ruh hâli nasıl bir benliğe dönüşür",center:"Ezberlenmiş duygu",nodes:[{label:"Tetikleyici",text:"Bir mesaj, bir oda, bir anı, günün bir saati."},{label:"Duygu",text:"Bedende hissedilen endişe, sinirlilik ya da suçluluk."},{label:"Düşünce",text:"Zihin, duygunun haklı olduğuna dair nedenler bulur."},{label:"Tepki",text:"Kaçınmak, ters cevap vermek, aşırı hazırlanmak, geri çekilmek."},{label:"Tekrar",text:"Bir dahaki sefere duygu daha erken gelir ve daha uzun kalır."}],note:"Dispenza’nın fikrini gösteren bir döngü. Genel yapı alışkanlık araştırmalarıyla örtüşüyor. Ayrıntılı biyolojik açıklamaları ise araştırmalarla sınanmış olanın ötesine geçiyor."},technique:{name:"Alıştığın duygusal tepkiyi değiştir",origin:"Dr. Joe Dispenza · The Art of Change (2019)",steps:["Sürekli yaşamak istemediğin bir duygu seç: endişe, kırgınlık ya da suçluluk gibi.","Bu duygunun seni yönettiği yakın bir anı hatırla. Düşüncelerini, bedenindeki hisleri ve yaptıklarını zihninde yavaşça yeniden canlandır.","Bu anı düşünürken, artık bu tepkiyi tekrar etmek istemediğine karar ver.","Aynı durumda nasıl hissetmek istediğini düşün. Şimdi o duygudan biraz hissetmeyi dene.","Yeni tepki eskisi kadar tanıdık gelmeye başlasın diye bu kısa gözden geçirmeyi sık sık tekrarla."],evidence:"Bir kalıbı gözden geçirip farklı bir tepkiyi prova etmek, zihinsel prova ve duyguyu adlandırma araştırmalarıyla örtüşüyor. Bu araştırmalar sınırlı bir destek sunuyor. Dispenza’nın kuantum alanı, genler ve iyileşmeyle ilgili açıklamalarını ise bilim desteklemiyor.",sourceId:"identity-dispenza-change"},photo:{id:"1762126242240-cafa01fb1351",alt:"Koltukta oturmuş, yağmurlu pencereden dışarı bakan bir kişi"}},{id:"identity-3",title:"Otopilotu yakala",minutes:8,goal:"Gün içinde eski tepkilerinden birine en az bir kez ara ver.",reading:["Sabah sakin sakin prova yapmak işin kolay kısmı. Asıl sınav, öğleden sonra üçte tanıdık bir şey olduğunda gelir. Eski tepkin, sen fark etmeden devreye girer. Dispenza’nın programında gün içinde de çalışırsın: eski benliğini tanıdıktan sonra, ne zaman ortaya çıktığına bakarsın. Yakaladığında sabah verdiğin kararı hatırlayıp başka bir tepki seçersin. O anı fark etmek, otomatik bir döngüyü karar verebileceğin bir ana çevirir.","Günün büyük kısmı otomatik geçer. Wendy Wood ve arkadaşlarının iki günlük tutma çalışmasında, öğrencilerin davranışlarının %35’i ve %43’ü neredeyse her gün aynı yerde yapılan alışkanlıklardı. İnsanlar bu sırada çoğu zaman başka şeyler düşünüyordu. Ayrı bir telefon çalışmasında yaklaşık 2.250 yetişkinin aklı, kaydedilen anların neredeyse yarısında başka yerdeydi. Her döngüyü yakalayamazsın. Kimse yakalayamaz. Birkaçını fark etmek bile değişimin başlangıcıdır."],deeper:[{heading:"Alışkanlıklar sırasında dikkatin nereye gidiyor",paragraphs:["Aynı günlük tutma çalışmalarında, insanlar alışkanlıkla yaptıkları iş sırasında o işe daha az odaklanıyordu. Alışkanlıklar zihnin başka şeyler düşünmesine alan açar. Ayakkabı bağlarken bu yararlıdır. Ama alışkanlığın sevdiğin birine terslenmekse o kadar yararlı olmaz.","Matthew Killingsworth ve Daniel Gilbert’ın akıllı telefon çalışmasında, aklı başka yerde olan insanlar daha az mutluydu. Bu gözleme dayalı bir bulgu. Dalgınlığın mutsuzluğa yol açtığını kanıtlamıyor. Yine de dikkati daha sık içinde bulunduğun ana getirmek için bir neden olabilir."],visual:{kind:"bars",title:"İnsanlar yaptıkları şeyi mi düşünüyordu?",bars:[{label:"1. çalışma · alışkanlık sırasında",value:40,display:"%40"},{label:"1. çalışma · diğer eylemler",value:70,display:"%70"},{label:"2. çalışma · alışkanlık sırasında",value:44,display:"%44"},{label:"2. çalışma · diğer eylemler",value:60,display:"%60"}],note:"Düşüncelerin o anki eylemle örtüştüğü günlük kayıtlarının payı; Wood, Quinn & Kashy (2002). Katılımcılar ABD’li üniversite öğrencileriydi.",sourceId:"identity-wood-everyday"}},{heading:"İlk işareti nasıl yakalarsın?",paragraphs:["Eski tepkiyi yakalamak, denedikçe gelişen bir beceri. Tek bir kalıpla başla. En erken işaretine bak. Bu, düşünce bütünüyle gelmeden önce bedenindeki bir his ya da telefona uzanmak gibi küçük bir hareket olabilir."],visual:{kind:"steps",title:"Yakala, adlandır, dur, yön değiştir",steps:[{label:"Yakala",text:"İlk işareti fark et: bir duyum, tanıdık bir düşünce, telefona uzanan el."},{label:"Adlandır",text:"İçinden ipucu sözcüğünü söyle: “işte bu.”"},{label:"Dur",text:"Bir kez yavaşça nefes ver. Ayaklarını yerde hisset."},{label:"Yön değiştir",text:"Yeni benliğinin şimdi ne yapacağını sor. Bunun en küçük hâlini dene."}],note:"Dispenza’nın gün içindeki uygulamasından uyarlandı. Adımların sırasından çok, bir an durmak önemli."}},{heading:"Sık yapılan hatalar",paragraphs:["Geç fark ettiğin için kendini azarlamak. Döngü bittikten sonra fark etmek de bir ilerleme. Yarın bir dakika daha erken yakalayabilirsin.","Yalnızca hatırlamaya güvenmek. Uygulamayı görebileceğin bir hatırlatıcıya bağla: telefonun kilit ekranında bir sözcük, bilgisayarında bir not ya da bileğinde bir toka. 6. derste bu hatırlatıcılarla daha ayrıntılı çalışacaksın."]}],example:{title:"Sofia, 27, hemşire",text:"Sofia’nın eski benliği eve dönüş yolunda ortaya çıkıyordu. Her vardiyadan sonra gerçek ya da yalnızca olmuş olabileceğini düşündüğü hatalarını zihninde tekrar ediyordu. Eve gergin ve sinirli giriyordu. Kendine bir hatırlatıcı seçti: arabada anahtarı çevirdiği an. Pazartesi bunu tamamen unuttu. Salı günü yarı yolda, kırmızı ışıkta eski döngüyü fark etti. İçinden “Yine tekrar ediyorum” dedi. Nefes verdi, sevdiği bir podcast’i açtı ve o gün iyi yaptığı bir şeyi düşündü. Çarşamba günü daha anahtarı çevirirken fark etti. Her akşam işe yaramadı. Ama o hafta üç akşam eve belirgin biçimde daha sakin geldi. Partneri de bunu fark etti."},practice:["Bugün fark etmeye çalışacağın tek bir eski tepki seç. Telefona bakma dürtüsü ya da sinirliliğin ilk işareti olabilir.","Yakaladığında içinden söyleyeceğin bir ipucu sözcüğü seç; örneğin “işte bu” ya da “değiş”.","Her yakaladığında bir kez yavaşça nefes ver, yeni benliğinin yapacağı küçük bir şey yap ve bir çizgi at."],reflection:"Eski benliğinin devralmak üzere olduğunun, bedeninde ya da düşüncelerinde en erken işareti nedir?",question:"Eski tepkini yarı yolda yakaladın. En yararlı karşılık hangisi?",options:["Adını koymak, bir nefes boyunca durmak ve küçük bir sonraki adım seçmek.","Günün mahvolduğuna karar verip gelecek hafta yeniden denemek.","Bir dahaki sefere hatırlamak için kendini sert biçimde eleştirmek."],correct:0,feedback:"Döngüyü herhangi bir aşamada yakalamak ilerlemedir. Adını koyup bir an durmak ve küçük bir adım atmak, alışkanlığı yeniden bir seçime çevirir. Kendine sert davranırsan bir sonraki sefer dikkatle bakmak istemeyebilirsin.",takeaway:"Otopilotu her yakalayışında bir alışkanlığı yeniden bir seçime çevirirsin.",sources:["identity-dispenza-habit","identity-wood-everyday","identity-killingsworth"],visual:{kind:"bars",title:"Gündelik davranışın ne kadarı alışkanlık?",bars:[{label:"Günlük çalışması 1",value:35,display:"%35"},{label:"Günlük çalışması 2",value:43,display:"%43"}],note:"Alışkanlık olan (neredeyse her gün ve genellikle aynı yerde yapılan) bildirilmiş davranışların payı; Wood, Quinn & Kashy (2002). Katılımcılar ABD’li üniversite öğrencileriydi; senin için oran farklı olabilir.",sourceId:"identity-wood-everyday"},technique:{name:"Gün içinde yakala ve yön değiştir",origin:"Dr. Joe Dispenza · Breaking the Habit of Being Yourself (2012)",steps:["Sabah, bugün hangi eski düşünceyi, duyguyu ya da tepkiyi bıraktığını kendine hatırlat.","Listendeki kişilere, yerlere ve saatlere bak. Eski tepkinin genellikle ortaya çıktığı anları gün içinde fark etmeye çalış.","Fark ettiğinde döngüyü bilerek kes; içinden söylediğin kısa bir ipucu sözcüğü yardımcı olabilir.","Bu sabah olmaya karar verdiğin kişiyi kendine hatırlat.","O kişiye yakışan bir tepki seç; çok küçük olsa bile.","Akşam kısaca geriye bak: onu ne zaman yakaladın, ne zaman elinden kaçtı?"],evidence:"İpuçlarını fark edip nasıl karşılık vereceğine önceden karar vermek, alışkanlık ve eğer-öyleyse planları araştırmalarıyla uyumlu. Bu gündüz rutininin kendisi kontrollü çalışmalarda sınanmadı.",sourceId:"identity-dispenza-habit"},photo:{id:"1626257690705-8d62125575b0",alt:"Gün ışığında şehirdeki bir yaya yolunda yürüyen koyu ceketli bir adam"}},{id:"identity-4",title:"Her eylem bir oydur",minutes:9,goal:"Geliştirmek istediğin kimliği seç ve bugün ona ilk küçük oyunu ver.",reading:["James Clear, Atomic Habits kitabında değişimin üç katmanını anlatıyor. Dış katman sonuçlar: kilo vermek ya da bir kitabı bitirmek gibi. Orta katman süreç: rutinlerin ve sistemlerin. En derin katman kimlik, yani kendin hakkında inandığın şey. Çoğumuz dışarıdan başlıyoruz. Clear içeriden başlamayı öneriyor: kim olmak istediğine karar ver, sonra bunu küçük kazanımlarla kendine kanıtla. Her eylemi, belirli bir tür insana verilmiş bir oya benzetiyor. Tek bir oy seçimi kazanmaz, ama oylar biriktikçe yeni bir benlik için kanıt da birikir.","Bu fikrin psikolojide daha eski kökleri var. Daryl Bem’in 1972 tarihli öz algı kuramına göre, kendimizi kısmen yaptıklarımıza bakarak tanırız. Özellikle ne hissettiğimiz belirsizken, kendimize dışarıdan bir gözlemci gibi bakarız. Daphna Oyserman’ın kimliğe dayalı motivasyon araştırmaları da insanların, o an kendilerini nasıl gördükleriyle uyumlu eylemleri tercih ettiğini gösteriyor. “Bu benim gibiler için değil” diye düşününce daha az çaba gösteririz. Bu yüzden hedefin olağanüstü bir gün geçirmek olmasın. Yeni benliğine uygun küçük bir şey yap."],deeper:[{heading:"Küçük kanıt neden işe yarar",paragraphs:["Oyserman, insanların zorluğa nasıl anlam verdiğine de bakıyor. Bir iş zor gelince “Bu benim gibi biri için değil” diye düşünürsen vazgeçme ihtimalin artar. “Benim için önemli olduğu için zorlanıyorum” dersen devam etme ihtimalin artar. Bu fikirlere dayanan Pathways-to-Success sınıf programı, Chicago’nun yoksulluğun yoğun olduğu okullarındaki sekizinci sınıf öğrencilerinin daha iyi notlar almasıyla ilişkiliydi. İlişki, öğretmenler programı tasarlandığı gibi uyguladığında daha güçlüydü.","Bir okul programı, senin sabah yürüyüşünden çok farklı. Bu dersin sende işe yarayacağını kanıtlamaz. Yine de yaklaşımından yararlanabilirsin: zorlanmayı, sana uygun olmadığının kanıtı olarak değil, senin için önemli olduğunun işareti olarak gör."],visual:{kind:"table",title:"Zorluğa anlam vermenin üç yolu",columns:["Zor geldiğinde şöyle düşünürsün…","Genellikle ne olur?"],rows:[["Bu benim gibi biri için olmasa gerek.","Daha az çabalarsın; eski tepkin kendiliğinden devreye girer."],["Bu zor, çünkü benim için önemli.","Devam edersin ya da daha küçük bir adım denersin."],["Zor zamanlar, dönüşmek istediğim kişiyi şekillendiriyor.","Aksilikler hikâyenin parçası olur, sonu değil."]],note:"Daphna Oyserman’ın kimliğe dayalı motivasyon araştırmalarından uyarlandı. Zorluk, imkânsızlığın, önemin ya da gelişimin işareti olarak görülebilir."}},{heading:"Sık yapılan hatalar",paragraphs:["Bir gelişim yönü seçmek yerine kendine kesin bir etiket koymak. “Disiplinli biriyim” sana gerçek dışı gelebilir; kendini savunmaya başlayabilirsin. “Kendime verdiğim küçük sözleri tutan biri oluyorum” ise gelişmeye alan bırakır.","Fazla büyük oylar seçmek. Clear’ın egzersize yeni başlayan biriyle ilgili kendi örneği günde yalnızca birkaç düzine adımla başlıyor. Ve yalnızca kusursuz günleri sayma: bir seçimde her oya değil, çoğunluğa ihtiyacın var."]}],example:{title:"Amir, 38, satış müdürü",text:"Amir, eve gelince koridordaki ayakkabılar yüzünden bağıran baba olmaktan vazgeçmek istedi. “Sakin bir baba oluyorum” diye yazdı. İlk adımı çok küçüktü. Evin önüne park edince arabada altmış saniye kaldı. Üç kez yavaşça nefes verdi. İçeri girince önce çocuklarını selamladığını hayal etti. Telefonunda her denemesi için bir çizgi koydu. Cumaya kadar beş çizgi olmuştu. Perşembe günü ödev yüzünden yine terslendi. Ama on dakika sonra geri dönüp özür diledi ve bunu da bir oy saydı. Birden değişmemişti. Yine de uzun zamandır ilk kez, olmak istediği baba gibi davranabileceğine dair kanıtları vardı."},practice:["“Ben … biri oluyorum” cümlesini tamamlayıp yaz. Bir sonuçtan çok, nasıl biri olmak istediğini anlat.","En kötü gününde bile yapabileceğin kadar küçük bir oy seç ve önümüzdeki bir saat içinde yap.","Kâğıtta ya da telefonunda basit bir çetele tut ve her oy verdiğinde bir çizgi ekle."],reflection:"Bugün hangi küçük eylem, tarif ettiğin kişi olmakta olduğuna dair kanıt sayılır?",question:"Kimliğe dayalı alışkanlıklarda ilk haftalarda en önemli şey nedir?",options:["Etkileyici sonuçları mümkün olduğunca hızlı almak.","Yeni kimliği kendine kanıtlayan küçük ve tekrarlı oylar vermek.","Harekete geçmeden önce yeni biri gibi hissetmeyi beklemek."],correct:1,feedback:"Küçük ve tekrarlı eylemler yeni kimlik için kanıt biriktirir. Sonuçlar sonra gelir; önce farklı hissetmeyi beklemek genellikle uzun beklemek demektir.",takeaway:"Her oyun kusursuz olması gerekmez. Zamanla yeni benliğine verdiğin oylar çoğunluğu oluştursun.",sources:["identity-clear-identity","identity-clear-votes","identity-bem","identity-oyserman","identity-pathways"],visual:{kind:"compare",title:"Sonuç hedefleri ve kimliğe dayalı alışkanlıklar",left:{label:"Sonuçla başlamak",items:["Yarı maraton koşmak istiyorum.","Motivasyon görünür ilerlemeye bağlı.","Kaçırılan bir hafta başarısızlık gibi hissettiriyor."]},right:{label:"Kimlikle başlamak",items:["Her gün hareket eden biri oluyorum.","Her kısa yürüyüş bir kanıt sayılır.","Kaçırılan bir gün bir oydur, seçim değil."]},note:"James Clear’ın kimliğe dayalı alışkanlık anlatımından uyarlandı. Sonuç hedefleri de yararlıdır. Kimlik, onlara günlük yaşamında bir yer açar."},technique:{name:"Kimliğe dayalı alışkanlıklar: karar ver, sonra kanıtla",origin:"James Clear · Atomic Habits (2018)",steps:["İstediğin bir sonuca bak ve nasıl bir insanın buna doğal olarak ulaşacağını sor.","Bu kimliği kısa bir cümle olarak yaz: “Ben … biri oluyorum.”","Böyle birinin bugün yapacağı en küçük eylemi seç.","Önemsiz görünecek kadar küçük olsa da yap.","Bunu yeni kimliğin için bir oy olarak kaydet.","Kolaylaştığında eylemi yavaş yavaş büyüt."],evidence:"Clear’ın modeli farklı fikirleri bir araya getiren pratik bir yaklaşım. Sınanmış bir program değil. Öz algı kuramı ve kimliğe dayalı motivasyon araştırmalarıyla örtüşüyor. Bu araştırmalara göre yaptıklarımız kendimizi nasıl gördüğümüzü şekillendirir. Kimliğimize uygun eylemler de daha anlamlı gelir.",sourceId:"identity-clear-identity"},photo:{id:"1787154604447-4a62ed6654e3",alt:"Şehirde bir sokakta koşan koyu renk başörtülü, spor giysili bir kadın"}},{id:"identity-5",title:"Yeni benliği prova et",minutes:12,goal:"Olmak istediğin kişiyi 10 dakikalık bir sabah provasıyla zihninde canlandır. Provayı gerçek bir eyleme bağla.",reading:["Dispenza’nın yönteminde yeni benliğini prova ettiğin bir sabah meditasyonu var. Önce bedenini sakinleştirip eski kalıbı bırakırsın. Sonra gün içindeki gerçek durumları düşünürsün: olmak istediğin kişi nasıl düşünür, konuşur ve davranırdı? Ayrıntıları zihninde canlandırır, o kişinin sakinliğini, güvenini ya da sıcaklığını şimdiden hissetmeyi denersin. Dispenza bunu, günün alışılmış düzeni başlamadan önce yapmanı öneriyor. Böylece güne yeni benliğinle başlarsın.","Zihinsel provayı araştırmalar destekliyor, ancak sınırları var. 2021’de 94 rastgele kontrollü çalışma bir araya getirildi. Bir davranışı zihinde canlandırmak, sonraki davranışı genel olarak orta düzeyde değiştirdi. Kendini eylemi iyi yaparken hayal etmek en iyi sonucu verdi. Yalnızca güzel bir sonuç hayal etmek daha az yardımcı oldu. Spor araştırmalarında da zihinsel çalışma beceriyi biraz geliştirdi, ama gerçek uygulamadan daha az. Bu yüzden hem eylemi prova et hem de aynı gün gerçekten dene. Dispenza’nın meditasyonla genleri değiştirme, hastalıkları iyileştirme veya kuantum alanıyla gerçekliği değiştirme iddialarını bilim desteklemiyor."],deeper:[{heading:"10 dakikalık sabah provası",paragraphs:["Telefonuna bakmadan önce yatağının kenarında ya da bir sandalyede oturarak yapabilirsin. Saati kontrol etmemek için zamanlayıcı kur. Aşağıdaki süreler yalnızca yol gösterir. Acele bir günde daha kısa yapman da sayılır.","Prova sırasında yoğun sıkıntı hissedersen ya da eski acı anılar canlanırsa dur. Gözlerini aç ve ayaklarının yere temasını hisset. Bu uygulama travmayla çalışmak için uygun değil. Bu konuda eğitimli bir uzmandan destek alabilirsin."],visual:{kind:"steps",title:"On dakika, beş bölüm",steps:[{label:"Sakinleş · 2 dk",text:"Gözlerini kapat, yavaş nefes al ve dikkatini düşüncelerinden bedenine taşı."},{label:"Bırak · 2 dk",text:"Bugün geride bıraktığın eski benliği adlandır ve bırak."},{label:"Prova et · 4 dk",text:"Yeni benliğini gününde yaşayacağın iki ya da üç gerçek durumda, istediğin eylemi iyi yaparken canlandır."},{label:"Hisset · 1 dk",text:"O benliğin sakinliğini ya da güvenini şimdi biraz hissetmeyi dene."},{label:"Söz ver · 1 dk",text:"Somut bir eylem ve onu ne zaman yapacağını seç."}],note:"Dispenza’nın daha uzun meditasyonunun kısaltılmış bir uyarlaması; araştırmaların desteklediği bölümlere ağırlık verildi."}},{heading:"Araştırma ne diyor",paragraphs:["Klasik bir spor meta-analizinin 2020 güncellemesi 37 çalışmayı inceledi. Zihinsel çalışmanın performans üzerindeki etkisi küçük ama gerçekti. Etki, 1994’teki tahminden daha küçüktü; fiziksel çalışma daha etkiliydi. Daha geniş 2021 derlemesinde, insanlar eylemi yaparken kendilerini hayal ettiklerinde davranış üzerindeki etki daha büyüktü. Özellikle eylemi iyi yaptıklarını hayal etmek daha çok işe yaradı.","Prova seni hazırlar, ama gerçek uygulamanın yerini tutmaz. Somut bir eylemi tekrar tekrar prova edip ardından gerçekten denediğinde daha çok işe yarıyor gibi görünüyor."],visual:{kind:"compare",title:"Araştırmalar neyi destekliyor?",left:{label:"Araştırmanın desteklediği",items:["Belirli eylemleri zihninde prova etmek","Kendini iyi yaparken görmek, sonra gerçekten denemek","Gelecekteki benliğini canlı ve yakın kılmak"]},right:{label:"Araştırmanın desteklemediği",items:["Düşünerek genlerini değiştirmek","Yalnızca meditasyonla hastalığı iyileştirmek","Bir kuantum alanıyla gerçekliği değiştirmek","Epifiz bezi aracılığıyla mistik yetenekler kazanmak"]},note:"Meditasyon tıbbi bakımın yerini tutmaz. Sağdakiler gibi hiçbir iddia yüzünden tedaviyi bırakma ya da geciktirme."}},{heading:"Gelecekteki benliğini yakın tut",paragraphs:["Hal Hershfield’in gelecekteki benlikle süreklilik araştırmaları, provanın neden işe yarayabileceğini düşündürüyor. Gelecekteki kendisiyle benzerlik ve bağ hisseden, onu canlı biçimde hayal edip olumlu gören kişiler, o kişiye yarar sağlayacak seçimleri daha sık yapıyor. Daha fazla tasarruf etmek gibi. Sabah provası, gelecekteki kendinle her gün buluşmanın bir yolu olabilir. Böylece sana bir yabancıdan çok, kendin gibi gelir."]}],example:{title:"Mei, 45, muhasebeci",text:"Mei, toplantılarda söz alan biri olmak istedi. Her sabah çayını koyduktan sonra zamanlayıcı kurup on dakika oturdu. Sessiz kalan eski Mei’yi geride bıraktığını düşündü. Sonra saat ondaki toplantıyı zihninde canlandırdı: elini kaldırıyor, sesi titremeden konuşuyor, göğsünde sakinlik hissediyordu. Sonunda kendine bir söz verdi: ilk yirmi dakika dolmadan bir görüş paylaşacağım. İlk gün yine sessiz kaldı. Üçüncü gün bir soru sordu. İkinci hafta bütçeyle ilgili bir fikir paylaştı. Yöneticisi bu fikri yazıya dökmesini istedi. Mei hâlâ gergindi ama artık ne yapacağını bu gerginlik belirlemiyordu."},practice:["Bugünden yeni benliğinin ortaya çıkacağı üç kısa sahne yaz: kim orada, ne oluyor ve sen ne yapıyorsun.","Yarın sabah telefonunu almadan önce 10 dakikalık provayı yap ve her sahneyi zihninde, duygusuyla birlikte en az bir kez oynat.","Günün için gerçek bir eylem seçerek bitir ve onu bir ana bağla: “… olduğunda, ben … yapacağım.”"],reflection:"Provanda yeni benliğin, zor bir anın ilk beş dakikasında neyi farklı yapıyor?",question:"Hangi prova, davranışını değiştirmeye daha çok yardımcı olabilir?",options:["Kendini belirli eylemi iyi yaparken hayal etmek, sonra gerçekten denemek.","Yalnızca ödülü hayal etmek: alkış, para ya da yeni vücut.","Değişimin kendiliğinden olması için genlerini değiştirmek üzere meditasyon yapmak."],correct:0,feedback:"Kendini eylemi iyi yaparken prova etmek, özellikle ardından gerçek pratik geldiğinde, araştırmalarda en büyük etkileri verdi. Yalnızca sonucu hayal etmek çok daha az yardımcı oldu ve gen iddiaları desteklenmiyor.",takeaway:"Süreci zihninde prova et, sonra ona bugün gerçek bir şans ver.",sources:["identity-dispenza-habit","identity-dispenza-supernatural","identity-dispenza-new-self","identity-cole","identity-toth","identity-hershfield"],visual:{kind:"bars",title:"Hangi tür zihinsel prova davranışı değiştirdi?",bars:[{label:"İşi iyi yapmayı prova etmek",value:.67,display:"g = 0,67"},{label:"İşi yapmayı prova etmek",value:.48,display:"g = 0,48"},{label:"Harika bir sonucu hayal etmek",value:.23,display:"g = 0,23"},{label:"Yalnızca adımları hayal etmek",value:.17,display:"g = 0,17, güvenilir değil"}],note:"Cole ve arkadaşlarından (2021) ortalama etkiler (Hedges’ g): 94 rastgele kontrollü çalışma, 5.685 kişi, çoğunlukla öğrenci. Yaklaşık 0,2 küçük, 0,5 orta düzey bir etkidir. “Yalnızca adımlar” sonucu sadece beş etkiye dayanıyor ve istatistiksel olarak güvenilir değildi.",sourceId:"identity-cole"},technique:{name:"Yeni benliğin sabah provası",origin:"Dr. Joe Dispenza · Breaking the Habit of Being Yourself (2012)",steps:["Rahat otur, gözlerini kapat ve birkaç dakika dikkatini düşüncelerinden bedenine ve şimdiki âna getir.","Geride bıraktığın eski benliği hatırla ve kendi sözlerinle bugünlük bırak.","Kendine sor: bugün olmak istediğim kişi nasıl düşünür, konuşur ve davranırdı?","O kişiyi, gününde yaşayacağın iki ya da üç gerçek durumda ayrıntısıyla canlandır.","Yeni benliğinin hissedeceği sakinlik, minnettarlık ya da güveni şimdiden biraz hissetmeyi dene.","Gözlerini açmadan önce bugün bunu kanıtlayacak somut bir eylem seç."],evidence:"Belirli eylemleri zihinde prova etmek, özellikle ardından gerçek uygulama geliyorsa araştırmalardan küçük ile orta düzeyde destek buluyor. Kitaplardaki kuantum alanı, gen ifadesi, hastalık iyileştirme ve mistik hâllerle ilgili iddiaların bilimsel desteği yok. Bu uygulamayı tıbbi bakım yerine kullanma.",sourceId:"identity-dispenza-habit"},photo:{id:"1600618528240-fb9fc964b853",alt:"Gün batımında ahşap bir terasta meditasyon yapan bir kadın"}},{id:"identity-6",title:"İpuçları ve çevre",minutes:9,goal:"Yeni benliğine uygun davranmak kolay olsun diye çevreni düzenle ve üç eğer-öyleyse planı yaz.",reading:["Alışkanlıkları bulunduğun koşullar tetikler: yer, zaman, insanlar, masadaki telefon. Eski benliğini sürdüren bu düzen, yenisine de yardımcı olabilir. James Clear, BJ Fogg’un fikrinden yararlanarak yeni alışkanlığı mevcut bir alışkanlığa bağlamayı önerir. Buna “alışkanlık istifleme” der. Örneğin: “Su ısıtıcısını açtıktan sonra günlüğüme bir satır yazacağım.” Bir başka önerisi de çevreni düzenlemek: yeni seçimi görünür ve kolay yap, eski seçeneğe ulaşmak için fazladan bir adım gereksin.","Psikologların “uygulama niyetleri” dediği eğer-öyleyse planları üzerine araştırmalar bunu destekliyor. Peter Gollwitzer ve Paschal Sheeran, 94 testi bir araya getirdi. “X durumu olursa Y’yi yapacağım” biçimindeki planlar, hedefe ulaşmayı ortalama orta ile büyük düzeyde artırdı. Plan, durumun daha kolay fark edilmesini ve tepkinin daha otomatik olmasını sağlıyor. Eski benliğinin genellikle devreye girdiği belirli anlar için bu planlardan yaz."],deeper:[{heading:"Önemli anlar için planlar yaz",paragraphs:["1. dersteki eski benliğini tanıma listene dön. Ortam sütunu, eski tepkinin ortaya çıkabileceği anları gösteriyor. Her biri planın “eğer” kısmı olabilir. Yeni benliğinin atacağı küçük adım da “öyleyse” kısmı."],visual:{kind:"table",title:"Eski benlik anları, yeni benlik planları",columns:["Eğer…","öyleyse ben…"],rows:[["Öğle yemeğinden sonra masama oturursam,","en zor dosyayı önce, beş dakikalığına açacağım."],["Evin önüne park ederken o eski sinirliliği hissedersem,","içeri girmeden önce üç yavaş nefes alacağım."],["Yatakta telefonuma uzanırsam,","onu odanın öbür ucunda şarja takıp bir sayfa okuyacağım."]],note:"“Eğer” kısmını somut ve gözlemlenebilir, “öyleyse” kısmını kötü bir günde bile yapabileceğin kadar küçük tut."}},{heading:"Araştırma ne diyor",paragraphs:["Alışkanlık araştırmacıları Wendy Wood ve Dennis Rünger, bağlam onları tetiklemeye devam ettiği için alışkanlıkların niyetler değişse bile sürebileceğine dikkat çekiyor. Bu yüzden bağlamı değiştirmek ya da onun için önceden plan yapmak, çoğu zaman daha çok çabalamaktan iyi işliyor.","Phillippa Lally’nin ekibinin çalışmaları, yeni davranış yerleşirken onu aynı zamanda ve yerde yapmayı öneriyor. Düzenli bir hatırlatıcı, davranışı tekrar etmeyi kolaylaştırır."],visual:{kind:"bars",title:"Eğer-öyleyse planlarının hedefe ulaşmadaki ortalama etkisi",bars:[{label:"Eğer-öyleyse planı (yalnızca hedefe kıyasla)",value:.65,display:"d = 0,65"}],note:"Gollwitzer & Sheeran (2006), 94 bağımsız test. Yaklaşık 0,5 orta, 0,8 büyük. Hedefler ve ortamlar çok farklıydı ve yayımlanmış çalışmalar etkileri olduğundan büyük gösteriyor olabilir.",sourceId:"identity-gollwitzer"}},{heading:"Sık yapılan hatalar",paragraphs:["Belirsiz bir hatırlatıcı seçmek. “Sabah” tek başına fark edeceğin belirli bir an değil. “Su ısıtıcısını açtıktan sonra” ise belirli. Clear, yeni alışkanlığın sıklığına da dikkat etmeni önerir. Her gün yapacağın bir alışkanlığı, her gün gerçekleşen bir şeye bağla.","Eski alışkanlığını kolaylaştıran bir ortamda yalnızca iradene güvenmek. Eski tepkiyi tetikleyen şey sürekli gözünün önündeyse, yeni davranışı seçmek zorlaşır. Onu başka yere taşı, ulaşmayı biraz zorlaştır ya da ortamı değiştir."]}],example:{title:"Jonas, 31, yazılım geliştirici",text:"Jonas, akşamlarının çoğunu gece bire kadar video oyunu oynayarak geçiriyordu. Olmak istediği kişi ise kitap okuyan ve iyi uyuyan biriydi. Pazar günü konsolun kumandasını çıkarıp koridordaki bir çekmeceye koydu. Yastığının üstüne de bir roman bıraktı. Mutfağın yanına planını yazdığı bir not koydu: “Akşam yemeğinden sonra bilgisayarı kapatırsam, çaydanlığı ocağa koyup on sayfa okuyacağım.” Bazı geceler yine oynadı ama önce kitabını okudu. Çoğu zaman okumayı bitirince oyuna başlayamayacak kadar uykusu geliyordu. İlk haftada yedi gecenin dördünde gece yarısından önce uyudu. Bir önceki hafta bunu hiç yapmamıştı."},practice:["Düzenli yaptığın günlük bir alışkanlık seç. Yeni benliğine uygun davranışı ona bağla: “… yaptıktan sonra … yapacağım.”","Bu akşam çevrende bir şeyi değiştir. Yeni eylem için gereken görünür olsun. Eski eylemi yapmak ise fazladan bir adım gerektirsin.","Eski benliğinin genellikle kazandığı anlar için üç eğer-öyleyse planı yaz ve görebileceğin bir yerde tut."],reflection:"Hayatında hangi yer ya da nesne sessizce eski benliğin lehine oy veriyor?",question:"Hangi plan en çok yardımcı olur?",options:["Bu hafta daha sabırlı olmaya çalışacağım.","Pazartesiden itibaren tamamen yeni biri olacağım.","Çocuğum yemekte bir şey dökerse, konuşmadan önce bir kez nefes vereceğim."],correct:2,feedback:"Somut bir eğer-öyleyse planı, hangi anda ne yapacağını söyler. Böylece o anı fark etmek ve tepkiyi vermek kolaylaşır. Genel niyetler ve büyük sözler ise ne zaman harekete geçeceğini göstermez.",takeaway:"Yeni benliğine uygun davranmayı kolaylaştır. Eski tepkilerinin geldiği anlar için plan yap.",sources:["identity-clear-stacking","identity-clear-environment","identity-gollwitzer","identity-wood-runger","identity-gardner"],visual:{kind:"steps",title:"Yeni benliğin için bir ipucu kur",steps:[{label:"Bir çıpa seç",text:"Zaten her gün, doğru zamanda ve yerde yaptığın bir alışkanlık."},{label:"Yeni eylemi bağla",text:"“… yaptıktan sonra … yapacağım.” Eylem küçük ve somut olsun."},{label:"Görünür kıl",text:"Yeni eylemin ihtiyaç duyduğu şeyi göreceğin yere koy."},{label:"Eski davranışı zorlaştır",text:"Eski ipucunu gözden uzağa taşı ya da bir adım daha ekle."},{label:"Dene ve ayarla",text:"Bir hafta sonra işe yarayanı tut, gerekirse çıpayı değiştir."}],note:"James Clear’ın alışkanlık istifleme ve çevre tasarımı fikirlerine ve bağlam ipuçları üzerine araştırmalara dayanıyor."},technique:{name:"Alışkanlık istifleme",origin:"James Clear · Atomic Habits (2018), BJ Fogg’un Tiny Habits çalışmasından uyarlanmıştır",steps:["Her gün aksatmadan yaptığın alışkanlıkları listele; örneğin kahve yapmak ya da diş fırçalamak.","Yeni eylemin için doğru zamanda ve yerde gerçekleşeni seç.","Formülü yaz: [mevcut alışkanlık]’tan sonra [yeni alışkanlık]’ı yapacağım.","Yeni eylemi o ana sığacak kadar küçük ve somut tut.","Yeni alışkanlığın ihtiyaç duyduğu her şey hazır olsun diye alanını düzenle.","Bir hafta dene; uymazsa çıpayı değiştir."],evidence:"Yeni bir eylemi sabit bir günlük ipucuna bağlamak, ortalama olarak orta ile büyük arası fayda gösteren alışkanlık oluşumu ve eğer-öyleyse planı araştırmalarıyla örtüşüyor. Alışkanlık istiflemenin kendisi adlandırılmış bir yöntem olarak sınanmadı.",sourceId:"identity-clear-stacking"},photo:{id:"1675762647949-1b25f669a687",alt:"Ahşap zeminde duran bir çift beyaz ayakkabı"}},{id:"identity-7",title:"66 günlük yol",minutes:10,goal:"Uzun vadede nasıl devam edeceğini, aksadığında ne yapacağın dahil olmak üzere planla.",reading:["Yeni benliğinin doğal gelmesi ne kadar sürer? 21 gün olduğunu duymuş olabilirsin. En bilinen gerçek yaşam çalışması, sürenin daha uzun ve değişken olabileceğini gösteriyor. University College London’dan (UCL) Phillippa Lally ve arkadaşları, gönüllülerden sağlıkla ilgili günlük bir davranışı aynı koşullarda tekrarlamalarını istedi. Neredeyse tamamen otomatikleşmesi 18 ile 254 gün arasında sürdü. Ortanca süre yaklaşık 66 gündü. Bir bardak su içmek gibi basit eylemler, mekik çekmek gibi daha zor eylemlerden hızlı otomatikleşti.","İki bulgu bu süreci biraz kolaylaştırabilir. Tek bir günü aksatmak, alışkanlığın oluşmasına belirgin zarar vermedi. Değişim de başta daha hızlı, sonra yavaşlayarak ilerledi. Bu yüzden aksayabileceğini kabul edip ne yapacağını önceden planla. James Clear’ın pratik önerisi, üst üste iki kez aksatmamak. Aksadığında kendine nazik davran. Juliana Breines ve Serena Chen’in deneylerinde, başarısızlığına öz şefkatle bakması istenen kişilerin gelişme isteği daha yüksekti. Örneğin bir sınavda başarısız olduktan sonra daha uzun süre çalıştılar."],deeper:[{heading:"Haftalık gözden geçirme",paragraphs:["İlerlemeyi izlemek yardımcı olabilir. Yaklaşık 20.000 kişinin yer aldığı 138 çalışmanın meta-analizinde, insanları daha sık ilerleme takibine yönlendirmek hedefe ulaşmayı ortalama orta düzeyde artırdı. İlerleme yazıldığında ya da biriyle paylaşıldığında etki daha büyüktü.","Bunun basit bir yolu, her hafta aynı gün ve saatte on beş dakika ayırmak. 4. derste tuttuğun çeteleye bakarak haftanı gözden geçir."],visual:{kind:"table",title:"15 dakikalık haftalık gözden geçirmen",columns:["Soru","Neden yardımcı olur"],rows:[["Bu hafta kaç oy verdim?","Saymak ilerlemeyi görünür kılar."],["Eski benlik ne zaman kazandı ve ipucu neydi?","Aksamaları bilgiye çevirir."],["Neyi değiştireceğim: hatırlatıcıyı, adımın büyüklüğünü ya da planı mı?","Sistemin öğrenmeye devam etmesini sağlar."],["Yeni benliğimin hangi davranışı beni memnun etti?","Olmakta olduğun kişiye dair kanıtı artırır."]],note:"Cevaplarını yazmak ya da bir arkadaşınla paylaşmak etkiyi güçlendirebilir."}},{heading:"Aksadığında",paragraphs:["Her değişim sürecinde aksamalar olur. Ardından kendine ne söylediğin önemlidir. Kendini suçlayıp utanmaya devam edersen bütün çabanın boşa gittiğini düşünebilirsin. Şefkatle yeniden başlamak ise insan olduğun için aksayabildiğini kabul etmek ve neyin engel olduğunu anlamaktır.","Clear’ın önerisi kaçırılan günü telafi etmeye değil, geri dönmeye odaklanmak. Bir sonraki eylemin yalnızca küçük olması yeterli."],visual:{kind:"compare",title:"Bir aksamaya karşılık vermenin iki yolu",left:{label:"Utanç sarmalı",items:["Mahvettim; başa döndüm.","Zaten bozuldu, bugün neden uğraşayım?","Görmeyeyim diye takibi bırak."]},right:{label:"Şefkatle yeniden başlamak",items:["Bu oldu. İnsan olduğum için bazen aksayabilirim.","Bu sefer neyin engel olduğunu düşünelim.","Bugün en küçük hâlini yap."]},note:"Bir aksama yüzünden günlerce umutsuz hissediyorsan ya da keyifsizliğin geçmiyorsa bir sağlık uzmanıyla konuş. Kriz anında 112’yi ara."}},{heading:"Gelecekteki benliğini gözünün önünde tut",paragraphs:["Gelecekteki benlikle süreklilik araştırmaları şunu düşündürüyor: gelecekteki kendini canlı biçimde hayal edip şimdiki kendinle benzerlik ve bağ hissettiğinde, ona yarar sağlayacak seçimler yapma ihtimalin artıyor. Bir yıl sonraki kendinden kısa bir not yazabilirsin. Sürdürdüğün belirli bir şey için sana teşekkür etsin. Bu, uzun süreçte gelecekteki kendini yakın hissetmenin bir yolu."]}],example:{title:"Rosa, 52, dükkân sahibi",text:"Her sabah yürüyüş yapmaya başlamasının 23. gününde Rosa grip oldu. Üst üste dört gün yürüyemedi. Eski benliğinin tanıdık cümlesi hazırdı: “Yine aynı şey. Ben hiçbir şeyi sürdüremem.” Pazar günkü gözden geçirmesinde bunun yerine yürüyüşlerini saydı. Yirmi üç günde on yedi yürüyüş. Aksayan günler ya hastalık yüzündendi ya da dükkânı erken açtığı haftaya denk gelmişti. Pazartesi, gücü ancak buna yettiği için mahallede beş dakika yürüdü. Altmışıncı günde yağmurlu sabahlarda yürümek hâlâ otomatikleşmemişti. Ama yağmur olmayan günlerde çıkıp çıkmamak konusunda artık kendisiyle tartışmıyordu. Bunu da not etti."},practice:["Takvimine, her hafta aynı gün ve saatte 15 dakikalık bir haftalık gözden geçirme koy.","Yeniden başlama planını şimdi yaz: “Bir günü kaçırırsam, ertesi gün alışkanlığımın en küçük hâlini yapacağım.”","Bir yıl sonraki gelecekteki kendinden, sürdürdüğün belirli bir şey için sana teşekkür eden kısa bir not yaz."],reflection:"Aksadığın günde kendine ne söylemek istersin ki ertesi gün yeniden başlayasın?",question:"Yeni alışkanlığını iki gün kaçırdın. Araştırma ne öneriyor?",options:["Bu senin değişebilecek biri olmadığını kanıtlar.","Bugün küçük bir adımla yeniden başla. Araştırmalarda ara sıra aksatmak, alışkanlığın oluşmasını engellemedi.","Bir ay sürse bile yeniden motive hissedene kadar bekle."],correct:1,feedback:"Alışkanlık araştırmasında kaçırılan bir fırsat alışkanlık oluşumuna belirgin zarar vermedi. Küçük bir adımla hızlı ve nazik biçimde yeniden başlamak, bir aksamanın yeni bir kalıba dönüşmesini önler.",takeaway:"Yeni benliğini güçlendiren şey, her aksadığında geri dönmendir.",sources:["identity-lally","identity-gardner","identity-clear-second-mistake","identity-breines","identity-harkin","identity-hershfield"],visual:{kind:"bars",title:"Günlük bir alışkanlığın neredeyse otomatikleşmesi için geçen gün sayısı",bars:[{label:"En hızlı",value:18,display:"18 gün"},{label:"Ortanca",value:66,display:"66 gün"},{label:"En yavaş",value:254,display:"254 gün"}],note:"Lally ve arkadaşları (2010): 96 gönüllü, 12 hafta. Herkes kendi seçtiği günlük bir davranışı tekrarladı. Eğri 39 kişi için tahmin edilebildi. Otomatikleşme katılımcıların bildirimine dayanıyordu. Gözlenen 84 günden uzun süreler, modelin ileriye dönük tahminleri.",sourceId:"identity-lally"},technique:{name:"Üst üste iki kez aksatma",origin:"James Clear · Avoid the Second Mistake (2014) (İkinci hatadan kaçın)",steps:["Bazı günleri kaçıracağını önceden kabul et.","Birini kaçırdığında yalnızca ertesi gün geri dönmeye odaklan, telafi etmeye değil.","Alışkanlığın en küçük hâlini yaparak yeniden başlamayı kolaylaştır.","Alışkanlığı sabit bir programa bağla ki ruh hâline bağlı olmasın.","Kaçırmana neyin yol açtığına bak ve elinden geliyorsa o engeli kaldır."],evidence:"Bu pratik bir kural, sınanmış bir yöntem değil. Ara sıra kaçırılan bir günün alışkanlık oluşumunu ciddi biçimde yavaşlatmadığını gösteren alışkanlık araştırmalarıyla ve başarısızlıktan sonra öz şefkatin gelişme motivasyonunu artırdığı deneylerle uyumlu.",sourceId:"identity-clear-second-mistake"},photo:{id:"1760715160644-7f5939675b68",alt:"Altın rengi bir çayırdan geçen patikada yürüyen yürüyüşçüler"}}]},xe=Object.freeze(Object.defineProperty({__proto__:null,COURSE:Te,SOURCES:Be},Symbol.toStringTag,{value:"Module"})),Ae=[{id:"state-emotion-decisions",title:"Lerner, Li, Valdesolo & Kassam · 2015 · Emotion and decision making (Annual Review of Psychology) (Duygu ve karar verme)",url:"https://escholarship.org/uc/item/8552m415",type:"research",finding:"Yaklaşık 35 yıllık araştırmayı inceleyen bir derleme. Duyguların kararları güçlü ve öngörülebilir biçimde etkilediği sonucuna varıyor. Bazen yararlı, bazen zararlı olan bu etkiler yargı ve seçimlerde düzenli örüntüler gösteriyor. Bir durumun duygusu, kişi fark etmeden ilgisiz bir karara taşınabiliyor. Örneğin üzücü haberler okumak, başka konulardaki risk tahminlerini yükseltti.",limitation:"Meta-analiz değil, anlatısal bir derleme; bu yüzden tek bir etki büyüklüğü vermiyor. Duyguların kararları genel olarak nasıl şekillendirdiğini anlatıyor; bu kurstaki hızlı durum değiştirme araçlarının hiçbirini sınamıyor. Özet ve yazarın tam metin kopyası okundu."},{id:"state-reappraisal-gross",title:"Gross · 2002 · Emotion regulation: affective, cognitive and social consequences (Psychophysiology) (Duygu düzenleme: duygusal, bilişsel ve sosyal sonuçlar)",url:"https://www.cambridge.org/core/journals/psychophysiology/article/abs/emotion-regulation-affective-cognitive-and-social-consequences/552536BD5988D0D2079A7E0CC82E1ED8",type:"research",finding:"James Gross iki stratejiyi karşılaştırıyor. Yeniden değerlendirme, yani bir durumu yorumlama biçimini değiştirerek duygusal etkisini azaltmak, belleği bozmadan hem duygusal deneyimi hem dışa vurumu azalttı. Bastırma, yani bir duygunun dış belirtilerini gizlemek, duyguyu azaltmadı, belleği bozdu ve hem kişide hem sohbet ettiği kişilerde fizyolojik stres tepkilerini yükseltti.",limitation:"Laboratuvar bulgularının bir derlemesi; çoğunlukla duygusal filmler ve sohbetlerle yapılan kısa deneyler. Duygu düzenlemenin süreç modelini açıklıyor ama birleştirilmiş bir etki büyüklüğü vermiyor. Özet okundu."},{id:"state-regulation-meta",title:"Webb, Miles & Sheeran · 2012 · Meta-analysis of emotion regulation strategies (Psychological Bulletin) (Duygu düzenleme stratejilerinin meta-analizi)",url:"https://www.academia.edu/13555860/Dealing_With_Feeling_A_Meta_Analysis_of_the_Effectiveness_of_Strategies_Derived_From_the_Process_Model_of_Emotion_Regulation",type:"research",finding:"190 çalışma, 306 deneysel karşılaştırma. Duygusal sonuçlar üzerindeki ortalama etkiler: bilişsel değişim (yeniden değerlendirme) d+ = 0,36; tepki düzenleme d+ = 0,16; dikkat yönlendirme d+ = 0,00. Bu gruplardaki ayrı yöntemlerin etkileri şöyleydi: başka bir bakış açısından bakmak 0,45; duygusal durumu yeniden değerlendirmek 0,36; duygusal tepkiyi yeniden değerlendirmek 0,23. Dikkati başka yere çevirmek 0,27; duygusal duruma yoğunlaşmak −0,26. Duygunun dışa vurumunu bastırmak 0,32; duyguyu hissetmemeye çalışmak −0,04; olayla ilgili düşünceleri bastırmak −0,12.",limitation:"Çalışmaların çoğu duygusal film, resim ya da görevlerle yapılan kısa laboratuvar deneyleriydi; günlük hayattaki ve haftalar süren etkiler farklı olabilir. Makale, yayımlanmış makalenin çevrimiçi bir kopyası üzerinden okundu."},{id:"state-acute-exercise",title:"Reed & Ones · 2006 · Acute aerobic exercise and positive activated affect: a meta-analysis (Akut aerobik egzersiz ve olumlu aktif duygulanım: bir meta-analiz)",url:"https://experts.umn.edu/en/publications/the-effect-of-acute-aerobic-exercise-on-positive-activated-affect/",type:"research",finding:"158 çalışma (1979–2005), 450 etki büyüklüğü, 13.101 katılımcı. Tek bir aerobik egzersiz seansı, enerjik, hevesli ve uyanık hissetmeyi artırdı. Düzeltilmiş ortalama etki 0,47’ydi. Düşük yoğunluklu, yaklaşık 35 dakikaya kadar süren ve düşük ile orta düzeyde egzersiz içeren seanslar iyi sonuç verdi. Artış, başlangıç düzeyine dönmeden önce en az yaklaşık 30 dakika sürdü. Kontrol gruplarında küçük bir düşüş görüldü (−0,17).",limitation:"Kendi bildirimine dayalı duygular, çoğunlukla sağlıklı gönüllüler; bireysel farklar büyüktü. Kısa süreli ruh hâli etkileri, tek bir yürüyüşün depresyonu ya da kaygıyı tedavi ettiğinin kanıtı değil. Özet okundu."},{id:"state-exercise-mental-health",title:"Singh et al. · 2023 · Physical activity for depression, anxiety and distress: umbrella review (BJSM) (Depresyon, kaygı ve sıkıntı için fiziksel aktivite: şemsiye derleme)",url:"https://bjsm.bmj.com/content/57/18/1203",type:"research",finding:"1.039 rastgele kontrollü çalışmayı ve 128.119 katılımcıyı kapsayan 97 sistematik derleme. Fiziksel aktivite depresyon (ortanca etki −0,43), kaygı (−0,42) ve psikolojik sıkıntı (−0,60) belirtilerini azalttı. Daha yüksek yoğunluk daha büyük iyileşmelerle ilişkiliydi ve 12 hafta ya da daha kısa süren müdahalelerde etkiler en büyüktü.",limitation:"97 derlemenin 77’sinin kalitesi çok düşük bulundu. Bu yüzden sayıları temkinli değerlendirmek gerekir. Bunlar haftalar süren programlar; tek seferlik hareketin etkisini göstermiyor. Profesyonel tedavinin yerini de tutmazlar. Özet okundu."},{id:"state-facial-feedback",title:"Coles, Larsen & Lench · 2019 · Meta-analysis of the facial feedback literature (Yüz geri bildirimi literatürünün meta-analizi)",url:"https://trace.tennessee.edu/utk_gradthes/5003/",type:"research",finding:"136 çalışmadan 286 etki büyüklüğü: yüz ifadelerinin duygusal deneyim üzerinde küçük ama güvenilir bir etkisi vardı (d = 0,20). Çalışmalar arasındaki değişimin yaklaşık %70’i bağlamdaki gerçek farklılıkları yansıtıyordu; etkiler hayali senaryolarda ve hiçbir duygusal uyaran olmadığında daha büyüktü. Yüzlerin, insanların resimlerin duygusal niteliğini nasıl derecelendirdiğini değiştirdiğine dair kanıt, yayın yanlılığı düzeltildikten sonra zayıfladı.",limitation:"Etkiler küçük ve değişken. Bu çalışmanın Tennessee Üniversitesi sürümünün özeti (2019’da Psychological Bulletin’de yayımlandı) okundu."},{id:"state-many-smiles",title:"Coles et al. (Many Smiles Collaboration) · 2022 · A multi-lab test of the facial feedback hypothesis (Yüz geri bildirimi hipotezinin çok laboratuvarlı sınaması)",url:"https://www.nature.com/articles/s41562-022-01458-9",type:"research",finding:"19 ülkede 3.878 katılımcıyla yapılan, önceden kaydedilmiş bir çalışma. Gülümseyen yüzleri bilerek taklit etmek ve isteyerek gülümsemek, mutluluk hissini hem başlattı hem artırdı. Ağızda tutulan kalemle yüz ifadesi dolaylı olarak değiştirildiğinde ise sonuçlar belirsizdi.",limitation:"Özet etki büyüklüğü vermiyor; yazarlar yüz geri bildiriminin işlediği koşulların geniş bedenselleşme kuramlarının önerdiğinden daha sınırlı olduğu sonucuna varıyor. Yalnızca mutluluk sınandı. Özet okundu."},{id:"state-power-pose-replication",title:"Ranehill et al. · 2015 · Robustness of power posing: no effect on hormones and risk tolerance (Güç pozunun sağlamlığı: hormonlara ve risk toleransına etkisi yok)",url:"https://faculty.haas.berkeley.edu/dana_carney/ranehill.pdf",type:"research",finding:"200 katılımcıyla (102 erkek, 98 kadın) güç pozu çalışması tekrarlandı. Deneyi yürüten araştırmacı kimin hangi grupta olduğunu bilmiyordu; pozlar daha uzun tutuldu. Testosteron (p = 0,162), kortizol (p = 0,272) ve finansal risk alma (p = 0,215) değişmedi. Ancak katılımcılar kendilerini daha güçlü hissettiklerini bildirdi (p = 0,017).",limitation:"Laboratuvar ortamında tek bir kavramsal yineleme; duruşun olası her sonucunu sınamıyor. Makalenin tamamı okundu."},{id:"state-music-stress",title:"de Witte et al. · 2020 · Music interventions and stress-related outcomes: two meta-analyses (Health Psychology Review) (Müzik müdahaleleri ve stresle ilgili sonuçlar: iki meta-analiz)",url:"https://pure.uva.nl/ws/files/58927620/Effects_of_music_interventions_on_stress_related_outcomes_a_systematic_review_and_two_meta_analyses.pdf",type:"research",finding:"104 rastgele kontrollü çalışma, 9.617 katılımcı, 327 etki büyüklüğü. Müzik uygulamaları bedensel stresi (d = 0,380) ve psikolojik stresi (d = 0,545) azalttı. Bedensel ölçümlerde etki, kalp atış hızında (d = 0,456), kan basıncından (d = 0,343) ve hormon düzeylerinden (d = 0,349) daha büyüktü. Yavaş müzikte (dakikada 60–80 vuruş) psikolojik etkinin daha büyük olması yönünde bir eğilim vardı. Müziği katılımcının ya da araştırmacının seçmesi arasında anlamlı fark görülmedi.",limitation:"Birçok deney sağlık hizmeti ortamlarındaydı ve bazı kategorilerde az sayıda etki büyüklüğü vardı. Analizler stresi azaltmaya odaklanıyor, enerjiyi yükseltmek için müziğe değil. Özet ve özetleme metni okundu."},{id:"state-cyclic-sighing",title:"Balban et al. · 2023 · Brief structured respiration practices and mood (Cell Reports Medicine) (Kısa yapılandırılmış solunum pratikleri ve ruh hâli)",url:"https://pmc.ncbi.nlm.nih.gov/articles/PMC9873947/",type:"research",finding:"Uzaktan yürütülen rastgele kontrollü çalışmada 108 katılımcı, 28 gün boyunca günde 5 dakika uygulama yaptı. Gruplar: döngüsel iç çekme (n = 30), kutu nefesi (n = 21), nefes tutmayla birlikte döngüsel hiperventilasyon (n = 33), farkındalık meditasyonu (n = 24). Olumlu duygulanımdaki ortalama günlük artış, nefes grupları birlikte değerlendirildiğinde 1,91, farkındalıkta 1,22’ydi. Ayrı ayrı artışlar: döngüsel iç çekme 1,89; kutu nefesi 1,84; döngüsel hiperventilasyon 1,97. Nefes uygulamaları, dinlenirken nefes alma hızını farkındalıktan daha fazla azalttı. O andaki kaygı bütün gruplarda benzer ölçüde düştü.",limitation:"Gruplar küçüktü. Uygulamalar uzaktan yapıldı ve katılımcıların ne kadar uyguladığı kendi bildirimlerine dayanıyordu. Çalışma yalnızca dört hafta sürdü; sonrasında takip yapılmadı. Sağlıklı gönüllüler katıldığı için sonuçlar, kaygı ya da panik bozuklukları hakkında bilgi vermez. Makalenin tamamı PubMed Central üzerinden okundu."},{id:"state-affect-labeling",title:"Lieberman et al. · 2007 · Putting feelings into words: affect labeling and the amygdala (Psychological Science) (Duyguları sözcüğe dökmek: duygu adlandırma ve amigdala)",url:"https://sanlab.psych.ucla.edu/wp-content/uploads/sites/31/2015/05/Lieberman_AL-2007.pdf",type:"research",finding:"Duygusal yüzlere bakan 30 yetişkinle yapılan bir fMRI çalışmasında, duyguya bir sözcük seçmek (duygu adlandırma), cinsiyet etiketi seçmeye ya da yüzleri eşleştirmeye göre daha az amigdala etkinliği üretti. Sağ ventrolateral prefrontal korteks duygu adlandırma sırasında daha etkindi ve etkinliği amigdala etkinliğiyle ters ilişkiliydi.",limitation:"Küçük bir örneklemle tek bir beyin görüntüleme oturumu; bu çalışmada öznel sıkıntı ölçülmedi ve beyin etkinliği, bir kişinin nasıl hissettiğiyle aynı şey değil. Makalenin tamamı okundu."},{id:"state-labeling-review",title:"Torre & Lieberman · 2018 · Affect labeling as implicit emotion regulation (Emotion Review) (Örtük duygu düzenleme olarak duygu adlandırma)",url:"https://journals.sagepub.com/doi/10.1177/1754073917742706",type:"research",finding:"Bu derlemeye göre, duyguları sözcüklere dökmek duygusal yoğunluğu azaltabilir. Kişilerin bildirimlerinde, bedensel tepkilerinde, beyin etkinliğinde ve davranışta etkiler görülebiliyor. Duyguyu adlandırmak, bilinçli bir düzenleme çabası gibi gelmese de yeniden değerlendirme gibi yöntemlere benzer etkiler gösterebilir. İnsanlar ise genellikle bunun duyguyu yoğunlaştıracağını bekliyor.",limitation:"Meta-analiz değil, anlatısal bir derleme; birleştirilmiş bir etki büyüklüğü vermiyor ve adlandırmanın ne zaman ve kimler için işe yaradığına dair birçok açık soru olduğunu belirtiyor. Özet okundu."},{id:"state-gratitude-meta",title:"Cregg & Cheavens · 2021 · Gratitude interventions for depression and anxiety: a meta-analysis (Depresyon ve kaygı için minnettarlık müdahaleleri: bir meta-analiz)",url:"https://link.springer.com/article/10.1007/s10902-020-00236-6",type:"research",finding:"27 çalışma, 3.675 katılımcı. Minnettarlık müdahalelerinin depresyon ve kaygı belirtileri üzerinde son testte (g = −0,29) ve takipte (g = −0,23) küçük bir etkisi vardı. Etkiler, bekleme listesi kontrolleriyle karşılaştırıldığında aktif kontrol koşullarına göre daha büyüktü.",limitation:"Yazarlar depresyon ya da kaygıyı azaltmak isteyenlere daha güçlü kanıtı olan müdahaleleri kullanmalarını öneriyor; yararın bir kısmı beklenti etkilerinden kaynaklanıyor olabilir. Özet okundu."},{id:"state-gratitude-expressed",title:"Kirca, Malouff & Meynadier · 2023 · Expressed gratitude interventions and well-being: a meta-analysis (İfade edilen minnettarlık müdahaleleri ve iyi oluş: bir meta-analiz)",url:"https://link.springer.com/article/10.1007/s41042-023-00086-6",type:"research",finding:"25 rastgele örneklem, 6.745 katılımcı. Minnettarlığı ifade etmek, nötr koşullara kıyasla iyi oluşu (g = 0,22) artırdı; buna mutluluk (g = 0,16), yaşam doyumu (g = 0,22) ve olumlu duygulanım (g = 0,21) dahildi. Minnettarlık diğer kişiye iletilmese bile faydalar görüldü ve müdahalenin süresi etkiyi anlamlı biçimde değiştirmedi.",limitation:"Ortalama etkiler küçük; çalışmalar minnettarlığı yazmayı ya da başkalarına ifade etmeyi sınadı, bu kurstaki sabah rutininin tam kendisini değil. Özet okundu."},{id:"state-positive-self-statements",title:"Wood, Perunovic & Lee · 2009 · Positive self-statements: power for some, peril for others (Psychological Science) (Kişinin kendine söylediği olumlu cümleler: kimisi için güç, kimisi için tehlike)",url:"https://journals.sagepub.com/doi/10.1111/j.1467-9280.2009.02370.x",type:"research",finding:"249 öğrenciyle yapılan ankette, katılımcılar kendilerine olumlu cümleler söylediklerini ve bunu yararlı bulduklarını bildirdi. 68 öğrenciyle yapılan deneyde, “Sevilecek biriyim” cümlesini 16 kez tekrarlayan benlik saygısı düşük kişiler, tekrarlamayanlardan daha kötü hissetti. Benlik saygısı yüksek olanlar biraz daha iyi hissetti. 116 öğrenciyle yapılan üçüncü çalışmada, benlik saygısı düşük kişiler cümlenin hem doğru hem doğru olmayan yönlerini düşününce daha iyi hissetti.",limitation:"Kanadalı lisans öğrencileri, tek bir cümle, kısa süreli ruh hâli; her olumlu cümlenin zararlı olduğunu göstermiyor. Özet ve makalenin tamamı okundu."},{id:"state-mental-contrasting",title:"Wang, Wang & Gai · 2021 · Mental contrasting with implementation intentions: a meta-analysis (Uygulama niyetleriyle zihinsel karşılaştırma: bir meta-analiz)",url:"https://www.frontiersin.org/journals/psychology/articles/10.3389/fpsyg.2021.565202/full",type:"research",finding:"21 çalışma, 24 etki büyüklüğü ve 15.907 katılımcı. İstenen bir geleceği, sonra da önündeki engelleri hayal etmek ve bunu eğer-öyleyse planlarıyla birleştirmek, hedefe ulaşmada küçük ile orta arası bir ortalama etki gösterdi (g = 0,336). Yüz yüze uygulama (g = 0,465) yazılı materyallerden (g = 0,277) daha iyi işledi.",limitation:"Az sayıda çalışma; en büyük iki çalışma katılımcıların çoğunu oluşturuyordu ve düzenleyici analizlerin dışında bırakıldı. Dickens sürecinin kendisini değil, zihinsel karşılaştırmayı sınıyor. Makale okundu."},{id:"state-self-compassion-motivation",title:"Breines & Chen · 2012 · Self-compassion increases self-improvement motivation (Öz şefkat kendini geliştirme motivasyonunu artırır)",url:"https://hqinstitute.org/wp-content/uploads/sites/5/2022/09/Breines_Chen_SelfCompMotivation.2012.pdf",type:"research",finding:"Dört deney. Bir zayıflığa, ahlaki bir hataya ya da başarısız bir sınava şefkatli bakmak; benlik saygısını yükseltme ya da kontrol koşullarına kıyasla, zayıflığın değişebileceğine inancı, telafi etme ve hatayı tekrarlamama motivasyonunu ve başarısız bir sınavdan sonra çalışmaya ayrılan zamanı artırdı.",limitation:"Çoğunlukla üniversite öğrencileri ve bir çevrimiçi yetişkin örneklemi; laboratuvarda kısa süreli motivasyon ve davranış, uzun vadeli değişim değil. Makale okundu."},{id:"state-power-pose-review",title:"The Psychologist (British Psychological Society) · A decade of power posing: where do we stand? (Bir on yıllık güç pozu: neredeyiz?)",url:"https://www.bps.org.uk/psychologist/decade-power-posing-where-do-we-stand",type:"guidance",finding:"Tartışmayı özetliyor: geniş pozların testosteronu yükselttiği ve kortizolü düşürdüğü yönündeki özgün iddia büyük ölçüde yinelenemedi; 2017 tarihli bir özel sayı hormonal etkinin neredeyse sıfır olduğunu buldu. Geniş duruş, insanların kendilerini ne kadar güçlü hissettiğini güvenilir biçimde değiştiriyor; bunun kısmen, çökmüş ve büzülmüş duruşlardan kaçınmaktan kaynaklanması olası.",limitation:"Tartışmalı bir literatürün dergi derlemesi, yeni bir çalışma değil; hissedilen güç etkisinin tam büyüklüğü hâlâ tartışılıyor."},{id:"state-nhs-breathing-tips",title:"NHS inform (İskoçya) · Tips for doing breathing and relaxation exercises (Nefes ve gevşeme egzersizleri yapmak için ipuçları)",url:"https://www.nhsinform.scot/healthy-living/mental-wellbeing/breathing-and-relaxation-exercises/tips-for-doing-breathing-and-relaxation-exercises/",type:"guidance",finding:"Nefes egzersizinde rahatsızlık ya da ağrı hissedersen durmanı öneriyor. Baş dönmesini önlemek için sonrasında bir süre otur ya da uzan. Solunum sorunu gibi bir sağlık durumun varsa, önce aile hekiminle konuş.",limitation:"İskoçya NHS’sinin halka yönelik genel önerileri; döngüsel iç çekmeye ya da enerjilendirici nefes çalışmalarına özgü değil."},{id:"state-nhs-panic",title:"NHS · Panic disorder (Panik bozukluğu)",url:"https://www.nhs.uk/mental-health/conditions/panic-disorder/",type:"guidance",finding:"Panik bozukluğu, düzenli olarak ani panik ya da korku atakları yaşamak demek. Ataklar korkutucudur ama tehlikeli değildir. NHS bir aile hekimine görünmeyi öneriyor; başlıca tedaviler bilişsel davranışçı terapi gibi konuşma terapisi ve bazı insanlar için ilaç. Yavaş, derin nefes almak, atak sırasındaki kendi kendine yardım adımlarından biri.",limitation:"Birleşik Krallık sağlık hizmeti rehberliği; hizmetler ve telefon numaraları ülkeye göre değişir. Acil bir durumda 112’yi ara."},{id:"state-robbins-triad",title:"Tony Robbins · Discover your peak state (tonyrobbins.com) (Zirve hâlini keşfet)",url:"https://www.tonyrobbins.com/blog/discover-your-peak-state",type:"technique",finding:"Robbins’e göre duyguları etkileyen üç etken var: fizyoloji, dil ve odak. Bunları bilinçli biçimde değiştirmenin günlük hislerini de değiştirebileceğini, kendini daha hazır ve güçlü hissedebileceğini savunuyor.",limitation:"Yazarın kendi sitesinde sunduğu bir koçluk modeli. Bilimsel bir kuram değil; üçlü bir bütün olarak sınanmadı. Bu kursta her etken ayrı araştırmalarla birlikte inceleniyor."},{id:"state-robbins-questions",title:"Tony Robbins · How to ask questions and better yourself every day (tonyrobbins.com) (Nasıl soru sorulur ve her gün kendini nasıl geliştirirsin)",url:"https://www.tonyrobbins.com/blog/ask-better-questions",type:"technique",finding:"Robbins’e göre, kendine sık sorduğun sorular dikkati ve yorumu yönlendiren filtreler gibi çalışır. Günlük yaşamda seni güçsüz hissettiren sorular yerine yapabileceklerine yönelten sorular sormanı öneriyor.",limitation:"Koçluk tavsiyesi; hiçbir çalışma Robbins’in soru setlerini doğrudan sınamadı. Dikkatle ilgili araştırma ayrıca anılıyor."},{id:"state-robbins-words",title:"Tony Robbins · Harness the power of words: transform your words in 4 steps (tonyrobbins.com) (Sözcüklerin gücünden yararlan: sözcüklerini 4 adımda dönüştür)",url:"https://www.tonyrobbins.com/blog/transform-your-words-in-4-steps",type:"technique",finding:"Zor duyguları anlatırken sık kullandığın sözcükleri fark etmeyi, sonra daha yumuşak ama doğru karşılıklar seçmeyi öneriyor. Örneğin “İç karartıcı” yerine “Keyifsiz”, “Öfkeden deliye dönmüş” yerine “Sinirli” gibi. Buna 10 gün devam etmeni istiyor.",limitation:"Koçluk önerisi. Sözcük değiştirme uygulamasının kendisi araştırılmadı. Duyguyu adlandırma ve yeniden değerlendirme araştırmaları ayrıca anılıyor."},{id:"state-robbins-rituals",title:"Tony Robbins · Morning rituals that can change your life (tonyrobbins.com) (Hayatını değiştirebilecek sabah ritüelleri)",url:"https://www.tonyrobbins.com/blog/whats-your-morning-ritual",type:"technique",finding:"Olumlama ile telkini ayırıyor. Olumlama, yalnızca söylediğin cesaret verici bir cümle. Telkinde cümleyi sesin, duruşun ve hareketlerinle de destekliyorsun. Robbins, yalnızca olumlama söylemenin değişim için yeterli olmayabileceğini savunuyor.",limitation:"Koçluk tavsiyesi; telkinler araştırmada sınanmadı. Kişinin kendine söylediği olumlu cümlelere dair kanıt (Wood ve ark., 2009) inandırıcılığın önemli olduğunu düşündürüyor."},{id:"state-robbins-priming",title:"Tony Robbins · Train your brain in minutes (tonyrobbins.com) (Beynini dakikalar içinde eğit)",url:"https://www.tonyrobbins.com/health-vitality/train-your-brain-in-minutes-4/",type:"technique",finding:"Sabah hazırlığını (priming), nefes ve hareket, minnettarlık ve zihinde canlandırmayla düşünce ve duyguları daha iyi bir hâle yönelten yaklaşık 10 dakikalık günlük bir uygulama olarak anlatıyor.",limitation:"Yazarın kendi sitesi. Sayfada adımlarla ilgili az ayrıntı var. Sabah hazırlığı bir bütün olarak araştırılmadı."},{id:"state-priming-cnbc",title:"CNBC · 2019 · Tony Robbins’ 10-minute morning routine (Grogan) (Tony Robbins’in 10 dakikalık sabah rutini)",url:"https://www.cnbc.com/2019/04/09/tony-robbins-10-minute-morning-routine-to-get-in-a-peak-state.html",type:"technique",finding:"Robbins’in 10 dakikadan kısa hazırlanma rutininin yazılı bir özeti: kol hareketleriyle güçlü nefes turları, minnettar olduğun üç şey üzerine düşünmek, ışığın bedeni doldurduğu bir görselleştirme ve üç hedefe sanki zaten gerçekleşmiş gibi odaklanmak.",limitation:"Bir gazetecinin özeti, çalışma değil; iyileştirici görselleştirme hastalık üzerinde herhangi bir etkinin kanıtı değil ve hızlı nefes baş dönmesine yol açabilir."},{id:"state-robbins-dickens",title:"Tony Robbins · Unlocking potential: the Dickens process (tonyrobbins.com) (Potansiyeli açığa çıkarmak: Dickens süreci)",url:"https://www.tonyrobbins.com/personal-growth/unlocking-potential",type:"technique",finding:"Adını geçmiş, şimdiki ve gelecek Noel hayaletlerinden alan Dickens sürecini anlatıyor: sınırlayıcı bir inancı belirle, sonra onun geçmişte sana neye mal olduğunu, şimdi sana ve sevdiklerine neye mal olduğunu ve bir, üç, beş ve on yıl içinde neye mal olacağını incele, ardından yerine yeni bir inanç koy.",limitation:"Koçluk tavsiyesi; Dickens süreci incelenmedi. Yoğun biçimiyle sıkıntı verici hissettirebilir, bu yüzden bu kurs daha nazik ve kısa bir versiyon kullanıyor."},{id:"state-robbins-standards",title:"Tony Robbins · How to raise your standards and upgrade your life (tonyrobbins.com) (Standartlarını nasıl yükseltir, hayatını nasıl geliştirirsin)",url:"https://www.tonyrobbins.com/blog/how-to-raise-your-standards",type:"technique",finding:"Robbins’e göre kalıcı değişim, standartlarını yükseltmekle başlar. Belirsiz bir “Yapsam iyi olur” düşüncesini vazgeçmeyeceğin net bir karara çevirirsin. Bu kararın ardındaki inançları gözden geçirir, ilişkiler, kariyer ve sağlık gibi alanlara odaklanırsın.",limitation:"Araştırma sınaması olmayan koçluk tavsiyesi; bu kurs onu zihinsel karşılaştırma ve öz şefkat kanıtlarıyla eşleştiriyor."},{id:"state-stanford-sighing",title:"Stanford Medicine · 2023 · Cyclic sighing can help breathe away anxiety (Döngüsel iç çekme kaygıyı nefesle uzaklaştırmaya yardımcı olabilir)",url:"https://med.stanford.edu/news/insights/2023/02/cyclic-sighing-can-help-breathe-away-anxiety.html",type:"technique",finding:"David Spiegel, Andrew Huberman ve Melis Yilmaz Balban’ın incelediği şekliyle döngüsel iç çekmeyi anlatıyor: burnundan nefes al, akciğerlerin tamamen genişlemesi için ikinci, daha derin bir nefes al, sonra ağzından yavaşça ver; günde yaklaşık beş dakika tekrarla. Bir aylık denemelerinde olumlu ruh hâlini farkındalık meditasyonundan daha çok iyileştirdi.",limitation:"Kurumsal bir haber özeti. Deneme orta ile ağır düzeyde psikiyatrik durumu olan kişileri dışarıda bıraktı; yöntem kaygı bozuklukları için bir tedavi olarak sınanmadı."}],Ie={id:"state",title:"Hâlini değiştir",subtitle:"Nasıl hissettiğini birkaç dakikada değiştirmeyi dene.",description:"Bedenin, dikkatin ve sözcüklerinle gerginlik ya da durgunluktan daha dengeli ve hazır bir hâle geçmenin kısa, pratik yollarını öğren. Tony Robbins’in önerilerini araştırmalarla birlikte incele. Hangi kısımların desteklendiğini, hangilerinin desteklenmediğini gör.",scope:"Ruh hâlini ve enerjisini günlük yaşamda değiştirmek isteyen yetişkinler için. Bu kurs eğitim amaçlıdır; tanı koymaz ve tedavi sunmaz. Kaygı bozuklukları, panik bozukluğu ya da depresyonu tedavi etmez. Terapi veya ilacın yerini tutmaz. Nefes çalışmasında baş dönmesi, sersemlik, karıncalanma ya da nefes darlığı hissedersen hemen dur. Normal nefesine dön ve otur. Kalp ya da akciğer rahatsızlığın varsa veya hamileysen, enerji artıran nefes çalışmalarını denemeden önce bir hekime danış. Bu çalışmaları araba kullanırken ya da suda yapma. Krizdeysen ya da kendine zarar verme düşüncelerin varsa 112’yi ara.",outcome:"Deneyerek tanıyacağın yedi yöntem: beden, odak ve sözcükleri kontrol etmek, iki dakikalık bedensel toparlanma, döngüsel iç çekme, daha iyi sorular, duyguyu adlandırıp duruma başka açıdan bakmak, gerçekçi bir telkinle on dakikalık sabah hazırlığı ve günlük bir eylemle desteklenen yeni bir standart. Her yöntemin ne yapıp ne yapamayacağını da göreceksin.",photo:{id:"1500080628126-901233e80205",alt:"Günün sıcak ışığında ahşap bir iskelede duran, bir elini ışığa doğru kaldıran bir kadın"},lessons:[{id:"state-1",title:"Hâlin bakışını etkiler",minutes:7,goal:"Şu anki hâlini fark et. Onu etkileyen üç şeyi adlandır: beden, odak ve sözcükler.",reading:["Hâlin, o andaki ruh hâlinin, enerjinin ve bedenindeki gerginliğin birleşimidir. Geciken bir tren, sert bir e-posta ya da dökülen meyve suyu, dinlenmiş ve sakinken seni başka türlü etkiler. Bitkin ve gerginken ise başka türlü. Jennifer Lerner ve arkadaşlarının yaklaşık 35 yıllık araştırmayı inceleyen derlemesine göre duygular, kararları güçlü ve öngörülebilir biçimde etkiler. Bazen yardımcı olur, bazen zarar verirler. Hâlin, neyi fark ettiğini, hangi kararı verdiğini ve çevrendekilere nasıl davrandığını şekillendirir.","Koç ve yazar Tony Robbins’e göre hâlin yalnızca başına gelenlerin sonucu değildir. Modelinde üç etken vardır: fizyoloji, yani nefesin, duruşun ve hareketlerin; odak, yani dikkatini verdiğin şey; dil, yani olayları anlatırken seçtiğin sözcükler ve yüklediğin anlamlar. Bunlardan birini değiştirmek hâlini de değiştirebilir. Bu kursta üçlünün her parçasına araştırmalarla birlikte bakacağız. Bazıları güçlü, bazıları kısmi destek buluyor. Popüler bir iddianın sonuçları ise sonraki araştırmalarda tekrarlanmadı. Kısa uygulamalarla birlikte, her birinin ne kadar işe yarayabileceğini öğreneceksin."],deeper:[{heading:"Birkaç dakika neden önemli?",paragraphs:["Bir durumda hissettiklerin sonraki duruma taşınabilir. Gergin bir sabahın sinirliliği, bir saat sonra iş arkadaşının sıradan bir mesajını yorumlama biçimini etkileyebilir. Karar verme araştırmalarında bunlara “tesadüfi duygular” denir. Çoğu zaman bu etkiyi fark etmeyiz. Önemli bir konuşmadan önce kısa bir toparlanma bu yüzden yararlı olabilir.","Ne zaman araya girdiğin de önemli. James Gross’un duygu düzenleme araştırmasında, durumu farklı yorumlamak hem duyguyu hem dışa vurumunu azalttı. Duyguyu yalnızca gizlemek ise onu azaltmadı; bedensel stresi artırdı. Hissettiğin duygu daha kalıcı bir ruh hâline dönüşmeden araya girersen daha fazla seçeneğin olur."],visual:{kind:"table",title:"Aynı an, iki farklı hâl",columns:["An","Bitkin, gergin hâl","Dengeli, hazır hâl"],rows:[["Tren 20 dakika geç kalıyor","Bugünüm mahvoldu.","Sinir bozucu. Önceden haber verip zamanı değerlendireceğim."],["Yöneticinden sert bir e-posta","Beni işe yaramaz sanıyorlar.","Kısa bir e-posta. Neye ihtiyaçları olduğunu soracağım."],["Çocuğun akşam yemeğinde krize giriyor","Bununla başa çıkamıyorum.","Çocuğum yorgun. Önce sesimi alçaltayım, sonra durumu ele alayım."]],note:"Bunlar yalnızca örnek. Olay aynı kalır. Hâlin ise neyi fark ettiğini ve nasıl tepki verdiğini etkiler."}},{heading:"Bu üçlünün araştırmalardaki yeri",paragraphs:["Bu üçlü, seçeneklerini anlamanı sağlayan bir model. Sınanmış bir bilimsel kuram değil. Yine de parçaları araştırılan alanlarla örtüşüyor: hareket, duruş ve nefes; dikkat; olayları adlandırma ve yorumlama. Sonraki derslerde bu etkenleri tek tek inceleyip araştırmaların ne bulduğuna bakacağız.","Üzüntü, öfke ve endişe de yararlı bilgiler taşır. Her zaman çok iyi hissetmen gerekmiyor. Amaç, hâlin işini zorlaştırdığında bunu fark etmek ve değiştirmek için birkaç güvenilir seçeneğinin olması."]}],example:{title:"Dana, 34, acil servis hemşiresi",text:"Dana zor bir gece vardiyasını bitirmişti. Evdeki su sızıntısı için ev sahibini araması gerekiyordu. Direksiyonun üzerine çökmüştü. Bir hastanın kaba sözünü tekrar tekrar düşünüp “Herkes bana karşı” diye mırıldandığını fark etti. Aramadan önce üç şeyi kontrol etti. Beden: dik oturdu, omuzlarını çevirdi ve yavaşça nefes aldı. Odak: bu aramadan ne bekliyordu? Perşembeye kadar bir tesisatçının gelmesini. Sözcükler: “Herkes bana karşı” yerine “Zor bir vardiyaydı” dedi. Konuşma yine biraz gergin geçti. Ama Dana ne istediğini açıkça söyledi ve bir tarih aldı. Son hastayla yaşadıklarının, bir sonraki kişiyle nasıl konuşacağını belirlemesine ara vermişti."},practice:["Şimdi dur ve enerjini 0’dan 10’a, gerginliğini 0’dan 10’a puanla.","Üçlüyü kontrol et: nasıl oturduğunu ve nefes aldığını, neye odaklandığını ve kafanda hangi sözcüklerin döndüğünü fark et.","Bu üç etkenden birini 60 saniye boyunca değiştir. Ayağa kalkıp esneyebilir ya da bir cümleni başka türlü söyleyebilirsin. Sonra enerjine ve gerginliğine yeniden puan ver."],reflection:"Bu üç etkenden hangisini genellikle kullanıyorsun? Hangisini daha çok unutuyorsun?",question:"Robbins’in üçlüsünde bunlardan hangisi hâlini değiştirmenin bir yolu?",options:["Koşulların kendiliğinden değişmesini beklemek.","Duyguyu bastırıp yokmuş gibi davranmak.","Bedenini, odağını ya da bir olaya verdiğin sözcükleri ve anlamı değiştirmek."],correct:2,feedback:"Doğru. Bu üçlü, değiştirebileceğin üç etkeni gösterir: fizyoloji, odak ve dil. Duyguyu gizlemek çoğu zaman onu azaltmaz. Koşulların değişmesini beklemek ise ne zaman rahatlayacağını şansa bırakır.",takeaway:"Hâlin gününü etkiler. Onu değiştirmek için bedeninden, odağından ve sözcüklerinden yararlanabilirsin.",sources:["state-emotion-decisions","state-reappraisal-gross","state-robbins-triad"],visual:{kind:"cycle",title:"Bir hâl nasıl devam eder?",nodes:[{label:"Beden",text:"Nefes, duruş, hareket ve kas gerginliği."},{label:"Odak",text:"Neyi fark ettiğin, tekrar tekrar düşündüğün ve aradığın."},{label:"Sözcükler ve anlam",text:"Olaylara verdiğin etiketler ve hikâyeler."},{label:"Duygu",text:"Gerçekte yaşadığın hâl."},{label:"Eylem",text:"Ardından yaptığın şey, bedenini ve odağını yeniden etkiler."}],center:"Hâlin",note:"Tony Robbins’in üçlüsünden uyarlandı. Bu bir koçluk modeli, sınanmış bir kuram değil. Sonraki derslerde her etken araştırmalarla birlikte inceleniyor."},technique:{name:"Beden, odak ve sözcük kontrolü",origin:"Tony Robbins · Discover your peak state, tonyrobbins.com",steps:["Bir an dur ve içinde olduğun hâli tek bir sözcükle adlandır.","Beden: duruşunu, nefesini ve gerginliği nerede tuttuğunu fark et.","Odak: neye dikkat ettiğini ya da neyi tekrar tekrar düşündüğünü fark et.","Sözcükler: durum hakkında kafanda kullandığın ifadeleri fark et.","Değiştirmesi en kolay etkeni seç. Yaklaşık bir dakika boyunca onu bilinçli olarak değiştir.","Hâlini yeniden adlandır. Küçük de olsa bir fark var mı, bak."],evidence:"Bu üçlü bir koçluk modeli. Bir bütün olarak sınanmadı. Parçaları hareket, dikkat ve yeniden değerlendirme araştırmalarıyla örtüşüyor. Bu araştırmalarda duygular üzerinde küçük ile orta düzeyde kısa süreli etkiler görüldü. Model, seçeneklerini düzenlemeye yardımcı olabilir; değişimi garanti etmez.",sourceId:"state-robbins-triad"},photo:{id:"1758192139097-1e7f30c2498e",alt:"Güneş vuran ağaçların altında sakin bir şehir sokağından geçen bir adam"}},{id:"state-2",title:"Önce beden",minutes:8,goal:"Hareket, duruş ve müzikle enerjini yaklaşık iki dakikada değiştirmeyi dene. Bedenle ilgili hangi iddiaları araştırmaların desteklediğini gör.",reading:["Robbins’in fizyolojiyle ilgili önerisi basit: hareket etme biçimini değiştirmek, hislerini de değiştirebilir. Araştırmalar bunu büyük ölçüde destekliyor. Jennifer Reed ve Deniz Ones, 13.000’den fazla katılımcının yer aldığı 158 çalışmayı bir araya getirdi. Tek bir aerobik egzersiz seansı, enerjik ve olumlu hisleri ortalama orta düzeyde artırdı. Yaklaşık 35 dakikaya kadar süren düşük yoğunluklu seanslar iyi sonuç verdi. Artış en az yarım saat sürdü. Hareketsiz kalan kontrol gruplarında ise olumlu hisler biraz azalıyordu.","Yüzün ve duruşun da etkili olabilir. Ama etkileri, popüler iddiaların anlattığından daha küçük. 136 çalışmanın derlemesinde yüz ifadelerinin duyguları küçük ve değişken ölçüde etkilediği görüldü. 19 ülkedeki büyük bir çalışmada bilerek gülümsemek mutluluğu biraz artırdı. Güç pozu ise temkinli olmayı gerektiriyor. 200 kişiyle tekrarlanan bir çalışmada testosteron, kortizol ve risk alma değişmedi. İnsanlar yalnızca kendilerini daha güçlü hissetti. Dik duruş sana iyi geliyorsa kullanabilirsin. Ama hormonlarını değiştirmesini bekleme."],deeper:[{heading:"Hangi sonuçlar tekrarlandı?",paragraphs:["2010’daki ilk güç pozu çalışması, iki dakika boyunca geniş bir duruş almanın testosteronu yükseltip kortizolü düşürdüğünü öne sürdü. Sonraki çalışmalar çoğunlukla bu hormon değişikliklerini bulamadı. Tekrarlanan sonuç, insanların kendilerini daha güçlü hissetmesiydi. Bunun bir nedeni, öne kapanmış ve büzülmüş duruşlardan kaçınmak olabilir.","Buradan küçük ama yararlı bir sonuç çıkarabiliriz: duruş ve içten bir gülümseme hislerini biraz etkileyebilir. Kalp atışını artıran hareketin etkisi ise daha büyük olabilir."],visual:{kind:"compare",title:"Beden ve hâlin: araştırmalar ne diyor?",left:{label:"Destekleniyor (küçük ile orta arası)",items:["Tempolu bir yürüyüş ya da kısa bir aerobik seans enerjiyi bir süre yükseltir.","Bilerek gülümsemek mutluluğu biraz artırabilir.","Açık, dik bir duruş kendini daha güçlü hissetmeni sağlayabilir."]},right:{label:"Desteklenmiyor",items:["İki dakikalık poz testosteronu ya da kortizolü değiştirir.","Duruş tek başına risk almayı ya da performansı güvenilir biçimde değiştirir.","Tek seferlik hareket, depresyonu ya da kaygı bozukluğunu tedavi eder."]},note:"Egzersiz ve yüz geri bildirimi meta-analizlerine ve büyük bir güç pozu yinelemesine dayanıyor."}},{heading:"Müzikten yararlan",paragraphs:["9.600’den fazla kişinin yer aldığı 104 rastgele kontrollü çalışmanın meta-analizinde, müzik uygulamalarının stresi azalttığı görüldü. İnsanların hissettiği stres üzerindeki ortalama etki orta düzeydeydi. Kalp atış hızı gibi bedensel ölçümlerdeki etki daha küçüktü. Dakikada yaklaşık 60 ila 80 vuruşluk yavaş müzikte, hissedilen stresin daha fazla azalması yönünde bir eğilim vardı.","Bu deneyler, müziğin sakinleştirici etkisini araştırdı. Enerjini artırmak için müziği hareketle birleştirmeyi deneyebilirsin. Gevşemek istiyorsan yavaş bir parça seç."],visual:{kind:"bars",title:"Müzik müdahaleleri ve stres: ortalama etkiler",bars:[{label:"Hissedilen (psikolojik) stres",value:.545,display:"d = 0,545"},{label:"Kalp atış hızı",value:.456,display:"d = 0,456"},{label:"Genel olarak bedensel stres ölçümleri",value:.38,display:"d = 0,380"},{label:"Kan basıncı",value:.343,display:"d = 0,343"}],note:"104 rastgele kontrollü deney, 9.617 katılımcı (de Witte ve ark., 2020). Kontrollerle karşılaştırıldığında stres azaltma için etki büyüklükleri; birçok deney sağlık hizmeti ortamlarındaydı.",sourceId:"state-music-stress"}},{heading:"Yalnızca dakikalar değil, haftalar boyunca",paragraphs:["Düzenli hareketin etkisi kısa süreli enerji artışından daha geniş. 97 derlemeyi bir araya getiren bir incelemede, fiziksel aktivite programları depresyon, kaygı ve sıkıntı belirtilerini azalttı. Daha kısa ve yoğun programlarda etki daha büyüktü. Ancak derlemelerin çoğu düşük kalitedeydi. Gerektiğinde egzersiz, tedavinin yerini tutmaz."]}],example:{title:"Marcus, 41, depo sorumlusu",text:"Marcus, saat 14.00’te her zamanki enerji düşüşünü yaşıyordu. Hemen ardından yöneteceği haftalık iş güvenliği toplantısı vardı. Eskiden kollarını kavuşturur, tekdüze bir sesle konuşur ve toplantının bitmesini beklerdi. Bu hafta önce iki dakikalık toparlanma denedi. Merdivenlerden yükleme rampasına inip tempolu biçimde geri çıktı. Kulaklığından neşeli bir şarkı açıp omuzlarını gevşetti. Büsbütün değişmiş hissetmedi. Ama enerjisi 10 üzerinden yaklaşık 3’ten 5’e çıktı ve sesi kendisine daha tanıdık geldi. Toplantıdan sonra iki kişi soru sordu. Bu nadiren olurdu. Merdivenleri kullanmaya devam etmeye, mucize beklemekten vazgeçmeye karar verdi."},practice:["Ayağa kalk, omuzlarını geriye çevir ve merdiven, koridor ya da sokak kullanarak iki dakika tempolu yürü.","Hissetmek istediğin hâle uygun bir şarkı aç. Sakinlik için yavaş, enerji için neşeli bir parça seç ve eşliğinde hareket et.","Enerjini öncesinde ve sonrasında 0’dan 10’a puanla ve en çok hangi parçanın fark yarattığını not et."],reflection:"Enerjin düştüğünde, bulunduğun yerde gerçekçi olarak yapabileceğin en küçük hareket nedir?",question:"Güç pozu çalışmasının büyük bir tekrarı ne buldu?",options:["İki dakikalık pozdan sonra hormonlar güçlü biçimde değişti.","İnsanlar kendilerini daha güçlü hissetti, ama hormonlar ve risk alma değişmedi.","Duruşun duygularla hiçbir bağı yok."],correct:1,feedback:"Doğru. 200 katılımcıyla yapılan çalışmada güç pozu testosteronu, kortizolü ya da risk almayı değiştirmedi. Ama insanlar kendilerini daha güçlü hissettiklerini bildirdi. Duruş, küçük bir destek olabilir. Hormonlarını değiştiren bir düğme gibi düşünme.",takeaway:"Önce hareket et: birkaç dakikalık hareket, nasıl hissettiğini değiştirmenin en güvenilir yollarından biri.",sources:["state-acute-exercise","state-facial-feedback","state-many-smiles","state-power-pose-replication","state-power-pose-review","state-music-stress","state-exercise-mental-health","state-robbins-triad"],visual:{kind:"steps",title:"İki dakikada bedenen toparlan",steps:[{label:"Fark et",text:"Bedenin nasıl? Öne kapanmış, kasılmış ya da sığ nefes alıyor olabilir misin?"},{label:"Aç",text:"Ayağa kalk, omurganı uzat ve omuzlarını geriye bırak."},{label:"Hareket et",text:"Bir ile iki dakika tempolu yürü, merdiven çık ya da kollarını silk."},{label:"Bir ipucu ekle",text:"Hareket ederken bir şarkı çal ya da gerçek bir gülümseme dene."},{label:"Kontrol et",text:"Enerjini yeniden puanla ve neyin değiştiğini fark et."}],note:"158 çalışmanın meta-analizinde, tek bir aerobik egzersiz seansı enerjik hisleri ortalama orta düzeyde artırdı. Duruş ve gülümsemenin etkisi daha küçüktü."},technique:{name:"Fizyolojini değiştir",origin:"Tony Robbins · Discover your peak state, tonyrobbins.com",steps:["Şu anki hâlinin bedeninde nasıl göründüğünü fark et.","Ayağa kalk. Dengeli ve kendine güvenirken nasıl duruyorsan öyle dur.","Bir ile iki dakika tempolu yürü, merdiven çık ya da kollarını silkeleyerek hareket et.","Nefesinin derinleşmesine izin ver. Yavaşça ve uzun uzun nefes ver.","Gerçek bir gülümseme ya da istediğin hâle uyan bir şarkı ekle.","Kendini yokla ve yeni duruşu bir sonraki işine taşı."],evidence:"Tek bir aerobik egzersiz seansı, yaklaşık yarım saat süren orta düzeyde bir ortalama etkiyle enerjik, olumlu hisleri artırdı. Yüz ifadelerinin küçük, değişken bir etkisi var ve geniş duruşlar büyük bir yinelemede güç hislerini değiştirdi ama hormonları ya da risk almayı değiştirmedi.",sourceId:"state-robbins-triad"},photo:{id:"1692933216024-8de20c41321a",alt:"Yeşil bitkilerin arasından geçen bir tahta yürüyüş yolunda yürüyen bir kadın"}},{id:"state-3",title:"İki nefeste sakinlik",minutes:8,goal:"Döngüsel iç çekmeyi öğrenip beş dakika dene. Başın dönerse hemen dur.",reading:["Stres tepkinde nefesini doğrudan yönlendirebilirsin. Döngüsel iç çekmede iki kez nefes alıp bir kez uzun uzun verirsin. Burnundan nefes al. İkinci, kısa bir nefesle tamamla. Sonra akciğerlerin boşalmış gibi hissedene kadar ağzından yavaşça ver. Stanford araştırmacıları David Spiegel, Andrew Huberman ve Melis Yilmaz Balban bu yöntemi başka yöntemlerle karşılaştırdı. 108 kişi, 28 gün boyunca günde beş dakika uygulama yaptı. Rastgele döngüsel iç çekme, kutu nefesi, hızlı döngüsel hiperventilasyon ya da farkındalık meditasyonu gruplarına ayrıldılar.","Nefes grupları birlikte değerlendirildiğinde, olumlu ruh hâlindeki günlük artış farkındalık grubundan daha büyüktü. Dinlenirken nefes alma hızı da daha fazla azaldı. Kaygı ise bütün gruplarda benzer ölçüde düştü. Üç nefes yöntemi arasında az fark vardı. Araştırmanın sınırları önemli: gruplar küçüktü, uygulama sürelerini katılımcılar bildirdi ve çalışma dört hafta sürdü. Orta ya da ağır düzeyde psikiyatrik rahatsızlığı olanlar katılmadı. Döngüsel iç çekme, günlük yaşamda yararlı olabilecek bir yöntem. Kaygı ya da panik bozukluğu tedavisi değil."],deeper:[{heading:"Nasıl yapılır",paragraphs:["İlk nefesin oldukça dolu olabilir. İkinci nefes kısa olsun; akciğerlerini biraz daha doldursun. Asıl önemli olan, nefesi rahat bir iç çekme gibi yavaş ve uzun vermek. Nefes vermen, almaktan daha uzun sürsün. Rahat bir hızda ilerle.","Çalışmada günde beş dakikalık uygulama sınandı. Gergin bir anda bir ile üç döngüyle başlamak makul olabilir. Ama bu kısa kullanımın kendisi araştırılmadı."],visual:{kind:"steps",title:"Döngüsel iç çekme, tek döngü",steps:[{label:"Yerleş",text:"Rahatça otur ya da ayakta dur. Omuzlarını gevşet."},{label:"Nefes al",text:"Burnundan yavaşça nefes al."},{label:"Tamamla",text:"Akciğerlerini doldurmak için burnundan ikinci, daha kısa bir nefes al."},{label:"Uzun nefes ver",text:"Akciğerlerinin boşaldığını hissedene kadar ağzından yavaşça ver."},{label:"Tekrarla",text:"En fazla beş dakika sürdür, sonra normal nefes al."}],note:"Stanford Medicine’in anlattığı şekliyle. Baş dönmesi ya da rahatsızlık hissedersen dur ve normal nefes al."}},{heading:"Güvenlik ve sınırlar",paragraphs:["NHS’nin önerisi basit: rahatsızlık hissedersen dur ve ayağa kalkmadan önce bir süre otur. Solunum ya da kalp rahatsızlığın varsa önce doktoruna danış. Karıncalanma, sersemlik ya da hızlı kalp atışı fazla zorladığını gösterir. Normal nefesine dön. Bu kursta, araştırmadaki hızlı hiperventilasyon yöntemi öğretilmiyor.","Beklenmedik panik ataklar tekrar ediyorsa NHS bir doktorla görüşmeni öneriyor. Bilişsel davranışçı terapi gibi konuşma terapileri ve bazı kişiler için ilaçlar, araştırmalarla desteklenen tedaviler. Yavaş nefes almak atak sırasında destek olabilir. Ama tedavinin yerini tutmaz. Kriz anında 112’yi ara."]}],example:{title:"Aylin, 27, genç avukat",text:"Aylin, karşı tarafın avukatından gelen düşmanca e-postaları okurken nefesini tuttuğunu fark etti. Bir ay boyunca her sabah otobüste beş dakika döngüsel iç çekmeyi denemeye karar verdi. Zor e-postalara yanıt vermeden önce de iki ya da üç döngü yapacaktı. İlk sabahlar tuhaf geldi; insanların duyacağından endişelendi. İkinci hafta sessizce yapabiliyordu. Sert bir e-posta gelince, uzun nefes vermenin yazmaya başlamadan önce küçük bir duraklama sağladığını fark etti. Yanıtları kısaldı ve sakinleşti. Hâlâ öfkeleniyordu ama öfkeyle hemen yazmaya başlamıyordu. Bir gün başı dönecek gibi olunca durup normal nefes aldı. Sonraki sefer daha yavaş yaptı."},practice:["Rahat otur ve üç yavaş döngü yap: burundan nefes al, kısa tamamlama nefesi, ağızdan uzun nefes ver.","Bu iyi geliyorsa beş dakikalık bir zamanlayıcı kur ve rahat bir hızda sürdür; baş dönmesi hissedersen dur.","Sonrasında ne kadar sakin hissettiğini 0’dan 10’a puanla ve yarın iki ya da üç döngü kullanacağın bir an seç."],reflection:"Günlük hangi anda yavaş, uzun bir nefes vermek sana en çok yardımcı olur?",question:"Döngüsel iç çekme sırasında baş dönmesi hissedersen ne yapmalısın?",options:["Dur, normal nefes al ve bir süre otur.","Zorla devam et, çünkü baş dönmesi işe yaradığı anlamına gelir.","Dengelemek için daha hızlı nefes al."],correct:0,feedback:"Evet. Baş dönmesi veya karıncalanma hissedersen durup normal nefesine dön. Bu yöntem yavaş ve rahat yapılmalı. Kendini zorlama.",takeaway:"İki kez nefes al, bir kez uzun uzun ver. Bedenini sakinleştirmek için her yerde deneyebileceğin küçük bir yöntem.",sources:["state-cyclic-sighing","state-stanford-sighing","state-nhs-breathing-tips","state-nhs-panic"],visual:{kind:"bars",title:"28 günde olumlu ruh hâlinde günlük artış (günde 5 dakika)",bars:[{label:"Döngüsel iç çekme",value:1.89,display:"1,89"},{label:"Kutu nefesi",value:1.84,display:"1,84"},{label:"Döngüsel hiperventilasyon",value:1.97,display:"1,97"},{label:"Farkındalık meditasyonu",value:1.22,display:"1,22"}],note:"Grupların olumlu duygulanım puanındaki ortalama günlük artışı (Balban ve ark., 2023; 108 katılımcı). Nefes grupları arasında az fark vardı. Birlikte değerlendirildiğinde artış, farkındalık grubundan daha büyüktü (1,91 ve 1,22). Gruplar küçüktü; çalışma dört hafta sürdü ve sağlıklı gönüllülerle yapıldı.",sourceId:"state-cyclic-sighing"},technique:{name:"Döngüsel iç çekme",origin:"David Spiegel, Andrew Huberman & Melis Yilmaz Balban · Stanford Medicine (2023)",steps:["Rahat otur ya da ayakta dur ve omuzlarını gevşet.","Burnundan yavaşça nefes al.","Akciğerlerini doldurmak için burnundan ikinci, daha kısa bir nefes ekle.","Nefesini ağzından yavaşça ve tamamen ver. Bu, nefes almaktan daha uzun sürsün.","Rahat bir hızda en fazla beş dakika tekrarla.","Baş dönmesi, karıncalanma ya da rahatsızlık hissedersen dur ve normal nefes al."],evidence:"Sağlıklı gönüllülerle yapılan küçük, bir aylık bir denemede, döngüsel iç çekme dahil günde beş dakikalık nefes çalışması olumlu ruh hâlini farkındalıktan daha çok yükseltti ve dinlenme nefes hızını düşürdü. Kaygı ya da panik bozuklukları için bir tedavi olarak sınanmadı.",sourceId:"state-stanford-sighing"},photo:{id:"1763713383838-5cd702c13160",alt:"Ormanda gözleri kapalı, kendine hafifçe sarılan bir kadın"}},{id:"state-4",title:"Odağını ve sorularını değiştir",minutes:8,goal:"Kendine sorup durduğun, seni tüketen bir soruyu yakala ve dikkatini yararlı bir yere yönelten bir soruyla değiştir.",reading:["Robbins’e göre düşünmenin büyük kısmı, kendine soru sorup yanıt vermekten oluşur. Sürekli sorduğun sorular, dikkatini nereye verdiğini belirler. “Bu neden hep benim başıma geliyor?” dersen zihnin şanssız olduğuna dair kanıt arar. “Atabileceğim yararlı bir adım ne?” dersen seçenek arar. Robbins bu yüzden soruları günlük bir uygulama olarak öneriyor. Sabah birkaç soruyla yönünü belirle. Akşam birkaç soruyla neyin iyi gittiğine ve ne öğrendiğine bak.","Dikkat araştırmaları, bu fikri daha sınırlı biçimde destekliyor. Thomas Webb ve arkadaşları, duygu düzenlemeyle ilgili 190 çalışmayı bir araya getirdi. Dikkati bilerek başka bir şeye çevirmek ortalama küçük bir yarar sağladı. Üzücü duruma ve ona dair duygulara yoğunlaşmak ise biraz kötüleştirdi. İyi bir soru, dikkatini değiştirmene yardımcı olabilir. Gerçek sorunu görmezden gelmen gerekmez. Önce elinden gelen bir şeye odaklanıp sonra zor konuya daha sakin dönebilirsin."],deeper:[{heading:"Araştırma dikkat hakkında ne diyor",paragraphs:["Webb’in meta-analizinde dikkat yöntemlerinin toplam ortalama etkisi sıfırdı. Çünkü iki yön birbirini dengeliyordu: dikkati başka yere çevirmek biraz yardımcı oldu. Durumun duygusal tarafına takılıp kalmak ise biraz kötüleştirdi.","Dikkat dağıtma kısa vadeli bir araç. Zaman kazandırır, ama sorunların yine de sonra çözülmesi gerekir. Bir sonraki adıma götüren sorular ikisini de yapar: odağı kaydırır ve seni ileri taşır."],visual:{kind:"table",title:"Dikkati yönlendirmenin ortalama etkisi",columns:["Strateji","Ne anlama geliyor","Ortalama etki"],rows:[["Dikkat dağıtma","Dikkati nötr ya da hoş bir şeye çevirmek","Küçük fayda (d = 0,27)"],["Odaklanma","Üzücü durumun ve duyguların üzerinde tekrar tekrar durmak","Biraz daha kötü (d = −0,26)"],["Genel olarak dikkat stratejileri","İki yön birlikte","Yaklaşık sıfır (d = 0,00)"]],note:"Webb, Miles & Sheeran (2012), 190 çalışma, çoğunlukla kısa laboratuvar deneyleri."}},{heading:"Sabah ve akşam soruları",paragraphs:["ODA’dan birkaç örnek soru. Sabah: Bugün neyi dört gözle bekliyorum? Minnettar olduğum bir şey ne? Bugün hangi işi yaparsam günüm anlamlı gelir? Akşam: Bugün neye katkıda bulundum? Ne öğrendim? Ne beklediğimden iyi gitti?","Yanıtın “Hiçbir şey” ise soruyu küçült: “Fena olmayan küçük bir şey var mıydı?” Seni neşeli görünmeye zorlayan bir soru boş gelebilir. Açık ve somut yanıt verebildiğin bir soru daha inandırıcıdır."]},{heading:"Sık yapılan hatalar",paragraphs:["Soruları gerçek bir sorunu inkâr etmek için kullanmak ya da sert bir sorguya (“Sende ne sorun var?”) çevirmek amacı boşa çıkarır. En iyi sorular, nazik ve pratik bir arkadaşın soracağı şeye benzer."]}],example:{title:"Javier, 38, satış temsilcisi",text:"Javier, üç aydır çalıştığı bir anlaşmayı kaybetmişti. Eve dönerken kendine “Büyük işleri neden hep batırıyorum?” diye sordu. Zihni eski başarısızlıklarını sırayla önüne getiriyordu. Kırmızı ışıkta başka bir soru denedi: “Bu anlaşmadan ne öğrenebilirim?” Yanıt yavaş geldi: bütçeyi asıl onaylayan kişiyle hiç konuşmamıştı. Sonra “Yarın hangi adımı atabilirim?” diye sordu. Devam eden iki anlaşmasında kararları kimin verdiğini belirlemeye karar verdi. O akşam hâlâ hayal kırıklığı yaşıyordu ama daha iyi uyudu. Sabah elinde şanssız olduğuna dair uzun bir hikâye yerine kısa bir liste vardı."},practice:["İşler ters gittiğinde kendine sık sorduğun bir soruyu yaz.","Onu, öğrenmeye ya da kontrol edebileceğin bir sonraki adıma işaret eden bir soru olarak yeniden yaz.","Üç sabah sorusu seç ve yarın telefonuna bakmadan önce sor."],reflection:"Son zamanlarda odağını hangi soru yönetiyor ve seni nereye götürüyor?",question:"Hangi soru, dikkatini yapabileceklerine yöneltmeye daha çok yardımcı olur?",options:["Bu neden hep benim başıma geliyor?","Günümü mahvetmekten kim sorumlu?","Önümüzdeki on dakikada atabileceğim küçük bir adım ne?"],correct:2,feedback:"Doğru. Küçük ve yapılabilir bir adımı sorunca, dikkatini kontrol edebileceğin şeye yöneltirsin. Diğer sorular zihnini şanssızlık kanıtları ya da suçlayacak biri aramaya iter.",takeaway:"Sorduğun soruyu değiştirirsen dikkatini verdiğin şey de değişir.",sources:["state-robbins-questions","state-regulation-meta"],visual:{kind:"compare",title:"Tüketen sorular ve yön veren sorular",left:{label:"Tüketen sorular",items:["Bu neden hep benim başıma geliyor?","Bende ne sorun var?","Bunun suçlusu kim?"]},right:{label:"Yön veren sorular",items:["Önümüzdeki on dakikada yapabileceğim bir şey ne?","Bu durumda bir arkadaşıma ne derdim?","Hâlâ neler iyi gidiyor?","Bundan ne öğrenebilirim?"]},note:"ODA’nın sözcükleriyle örnek sorular; Tony Robbins’in güçlendirici sorular fikrinden esinlenildi."},technique:{name:"Güçlendirici sorular",origin:"Tony Robbins · How to ask questions and better yourself every day, tonyrobbins.com",steps:["Kendini tıkanmış ya da üzgün hissettiğinde zihninin tekrarladığı soruyu fark et.","Kendine o sorunun dikkatini nereye yönelttiğini sor.","Onu öğrenmeye, minnettarlığa ya da kontrol edebileceğin bir sonraki adıma işaret eden bir soruyla değiştir.","Yanıtın küçük olsa da somut ve dürüst olsun.","Kısa bir sabah ve akşam soruları seti oluştur ve bir hafta boyunca her gün kullan."],evidence:"Robbins’in soru setlerini doğrudan sınayan bir çalışma yok. Dikkat araştırmalarına göre odağını değiştirmek hislerini etkileyebilir. Üzücü konuya takılıp kalmak yerine dikkati başka yere çevirmek ortalama biraz yardımcı oldu. Duygunun üzerinde tekrar tekrar durmak ise biraz kötüleştirdi.",sourceId:"state-robbins-questions"},photo:{id:"1543379232-77ee894c85dd",alt:"Örgü bereli, alçak güneşe dönük bir kadın"}},{id:"state-5",title:"Sözcükler ve anlam",minutes:9,goal:"Ne hissettiğini bir ya da iki sözcükle anlat. Sonra durumu başka türlü yorumlamayı dene.",reading:["Üçüncü etken dil. Robbins, zor anları anlatırken alışkanlıkla kullandığın güçlü sözcükleri fark etmeni öneriyor. Sonra onları daha yumuşak ama yine doğru sözcüklerle değiştir: “Öfkeden deliye döndüm” yerine “Sinirlendim”, “Felaket” yerine “Aksilik” gibi. Duyguyu adlandırma araştırmaları da benzer bir yönde. Matthew Lieberman’ın beyin görüntüleme çalışmasında, yüzün cinsiyetine uygun bir isim seçmek yerine duygusunu anlatan bir sözcük seçildiğinde amigdala daha az etkinleşti. Bu bölge tehdit tepkilerinde rol oynar. Sonraki bir derlemeye göre, insanlar tersini beklese de duyguları sözcüklere dökmek yoğunluklarını azaltabilir.","Bir başka adım da duruma yüklediğin anlamı değiştirmek. Psikolog James Gross buna bilişsel yeniden değerlendirme diyor. Çalışmalarında durumu başka türlü yorumlamak hem duyguyu hem dışa vurumunu azalttı. Duyguyu yalnızca gizlemek ise hisleri azaltmadı. 190 çalışmanın meta-analizinde, yeniden değerlendirmenin ortalama etkisi küçük ile orta düzeydeydi. Başkasının bakış açısından bakmanın etkisi biraz daha büyüktü. Yeniden değerlendirme, kendini kandırmak değildir. İlk yorumun kadar doğru ve daha yararlı bir yorum ararsın."],deeper:[{heading:"Adlandır, sonra yeniden çerçevele",paragraphs:["Duyguyu somut anlatmak daha çok işe yarar. “Kötüyüm” çok az şey söyler. “Utandım ve biraz kaygılıyım” daha açık bir cümledir; duygunun yoğunluğunu da biraz azaltabilir. Adını koyduktan sonra, durumun başka ne anlama gelebileceğini sorabilirsin.","Tam doğru sözcüğü bulman şart değil. Sakince söylediğin yaklaşık bir ad da başlangıç için yeterli."],visual:{kind:"steps",title:"Yaklaşık bir dakikada adlandır ve yeniden çerçevele",steps:[{label:"Dur",text:"Bir kez yavaşça nefes al. Şu an ne hissettiğine bak."},{label:"Adlandır",text:"Söyle ya da yaz: Sinirlendiğimi ve biraz endişelendiğimi fark ediyorum."},{label:"Puanla",text:"Ona 0’dan 10’a bir sayı ver."},{label:"Yeniden çerçevele",text:"Sor: bu başka ne anlama gelebilir? Bana adil davranan bir arkadaşım bunu nasıl görürdü?"},{label:"Sonraki adım",text:"Yeni anlama uyan bir eylem seç."}],note:"Duygu adlandırmayı (Lieberman) ve bilişsel yeniden değerlendirmeyi (Gross) birleştiriyor."}},{heading:"Yumuşatmak inkâr etmek değildir",paragraphs:["Robbins’in sözcük değiştirme uygulaması doğrudan araştırılmadı. Buna en yakın çalışmalar, duyguyu adlandırma ve yeniden değerlendirme üzerine. Burada önemli olan, gerçeğe bağlı kalmak. Gerçek bir tehlikeye “Biraz tatsız” demek inkâr olur. Biri sana zarar veriyorsa ya da güvende değilsen, öncelik harekete geçmek ve destek istemektir.","Duyguyu gizlemek ile ona başka açıdan bakmak farklıdır. Bastırma, duygunun dışa vurumunu azalttı ama kişinin hislerini pek azaltmadı. Bedensel stresi de artırdı."]}],example:{title:"Priya, 45, okul yöneticisi",text:"Priya, ders programındaki neredeyse her soruna “Tam bir felaket” dediğini fark etti. Her seferinde omuzları kulaklarına doğru yükseliyordu. On gün boyunca küçük bir deneme yaptı. Sorun çıkınca önce duygusunu söyledi: genellikle “Sinirli ve telaşlıyım.” Sonra durumu başka nasıl yorumlayabileceğini sordu. Hasta olduğunu bildiren bir öğretmen olduğunda, “Felaket” yerine “Önümüzdeki saat için birini bulmam gerekiyor” dedi. Sert e-posta gönderen bir veliyi de düşman olarak değil, muhtemelen endişeli bir ebeveyn olarak gördü. İşleri hâlâ yoğundu; kötü günler de vardı. Ama ekibine daha az tersleniyordu. Dokuzuncu gün bir iş arkadaşı nasıl bu kadar sakin kaldığını sordu."},practice:["Bugün seni rahatsız eden bir durumu düşün. Duygunu bir ya da iki somut sözcükle anlat.","İlk yorumun kadar doğru olan tek bir alternatif yorum yaz.","Sık kullandığın iki yoğun sözcüğü listele ve her biri için daha ılımlı, doğru bir karşılık seç."],reflection:"Kötü bir an için en sık hangi sözcüğü kullanıyorsun ve doğru mu?",question:"Bunlardan hangisi bilişsel yeniden değerlendirmeye bir örnek?",options:["İçin için kaynarken bir toplantıda gülümsemek.","Şöyle düşünmek: bu sert geri bildirim taslak hakkında bir bilgi, benim hakkımda bir hüküm değil.","Açıkça bir şey olmuşken kendine kötü bir şey olmadığını söylemek."],correct:1,feedback:"Doğru. Yeniden değerlendirme bir durumun anlamını yine dürüst kalarak değiştirir. Bir duyguyu gizlemek bastırma, hiçbir şey olmamış gibi davranmak ise inkâr.",takeaway:"Adlandır, sonra daha doğru, daha yararlı bir anlam bul.",sources:["state-robbins-words","state-affect-labeling","state-labeling-review","state-reappraisal-gross","state-regulation-meta"],visual:{kind:"bars",title:"Anlamı değiştirmek ve tepkiyi değiştirmek",bars:[{label:"Başka bir bakış açısından bakmak",value:.45,display:"d = 0,45"},{label:"Durumu yeniden değerlendirmek",value:.36,display:"d = 0,36"},{label:"Tepkini yeniden değerlendirmek",value:.23,display:"d = 0,23"},{label:"Tepkiyi düzenlemek (genel)",value:.16,display:"d = 0,16"}],note:"Webb, Miles & Sheeran (2012), 190 çalışmada duygusal sonuçlar üzerindeki ortalama etkiler. Bir duygunun deneyimini bastırmak ortalama −0,04, olayla ilgili düşünceleri bastırmak −0,12 çıktı. Çoğunlukla kısa laboratuvar çalışmaları.",sourceId:"state-regulation-meta"},technique:{name:"Dönüştürücü kelime dağarcığı",origin:"Tony Robbins · Harness the power of words, tonyrobbins.com",steps:["Birkaç gün boyunca sinir bozucu ya da acı veren anlar için kullandığın yoğun sözcükleri fark et.","En sık ortaya çıkan iki ya da üçünü seç.","Her biri için yine dürüst olan, daha ılımlı bir karşılık seç; örneğin öfkeden deliye dönmüş yerine sinirli.","Eski sözcük aklına geldiğinde yenisini yüksek sesle ya da içinden söyle.","On gün sürdür. Yoğun anların sana hissettirdiklerinin değişip değişmediğine bak."],evidence:"Bu sözcük değiştirme uygulamasının kendisi sınanmadı. İlgili araştırmalar iki parçasını destekliyor: duyguları sözcüklere dökmek yoğunluklarını azaltabilir. Durumu yeniden yorumlamak da duygular üzerinde ortalama küçük ile orta düzeyde etki gösterdi. Duyguları gizlemek ise hislerini pek azaltmıyor.",sourceId:"state-robbins-words"},photo:{id:"1534330207526-8e81f10ec6fc",alt:"Aydınlık bir pencerenin önünde sessizce duran bir adam"}},{id:"state-6",title:"Sabah hazırlığı ve telkinler",minutes:10,goal:"On dakikalık sabah hazırlığı oluştur. Söylerken içinden itiraz etmeyeceğin, gerçekçi bir telkin seç.",reading:["Robbins güne, “priming” dediği on dakikadan kısa bir hazırlıkla başlıyor. Kendi materyalleri ve CNBC’nin özeti, şu parçaları anlatıyor: kol hareketleriyle güçlü nefes turları, geçmişten, bugünden ya da gelecekten üç minnettarlık anı, bedeni dolduran ışığı hayal etmek ve üç hedefe gerçekleşmiş gibi odaklanmak. ODA’nın uyarlaması aynı yapıyı izler. Ancak hızlı nefes baş döndürebileceği için önce yavaş nefesi önerir. Amaç, e-postalarına bakmadan önce nasıl bir hâlde güne başlamak istediğine karar vermek.","Robbins, olumlama ile telkini ayırır. Olumlama, söylediğin bir cümledir. Telkin ise bedenin, sesin ve inancınla desteklediğin bir cümle. Ama buna inanabilmen de gerekir. Joanne Wood ve arkadaşlarının deneylerinde, benlik saygısı düşük kişiler “Sevilecek biriyim” cümlesini 16 kez tekrarlayınca daha kötü hissetti. Benlik saygısı yüksek olanlar biraz daha iyi hissetti. Cümle inancından çok uzaksa zihnin itiraz edebilir. Bu yüzden telkinin somut, gerçekçi ve bir eyleme bağlı olsun."],deeper:[{heading:"Minnettarlık araştırmaları ne gösteriyor?",paragraphs:["Minnettarlık alıştırmaları yardımcı olabilir ama etkileri sınırlı. Rastgele gruplara atama yapılan 25 örneklemin meta-analizinde, minnettarlığı ifade etmek iyi oluşu ortalama küçük düzeyde artırdı. 27 çalışmanın başka bir meta-analizinde depresyon ve kaygı belirtileri üzerinde küçük etkiler bulundu. Yazarlar, bu durumlar için daha güçlü kanıtı olan tedavileri önerdi.","Sabah hazırlığında somut bir sahne seçebilirsin: arkadaşının kahkahası ya da sakince içtiğin bir kahve. Birkaç nefes boyunca o anı hatırla."],visual:{kind:"bars",title:"Minnettarlığı ifade etmek ve iyi oluş: ortalama etkiler",bars:[{label:"Genel iyi oluş",value:.22,display:"g = 0,22"},{label:"Yaşam doyumu",value:.22,display:"g = 0,22"},{label:"Olumlu duygular",value:.21,display:"g = 0,21"},{label:"Mutluluk",value:.16,display:"g = 0,16"}],note:"Kirca, Malouff & Meynadier (2023): 25 rastgele örneklem, 6.745 katılımcı, nötr koşullarla karşılaştırıldı. Küçük etkiler.",sourceId:"state-gratitude-expressed"}},{heading:"Olumlama mı, telkin mi?",paragraphs:["Wood’un üçüncü çalışmasında bir ipucu var. Benlik saygısı düşük kişiler, olumlu bir cümlenin hem doğru hem tam doğru olmayan yönlerini düşündüklerinde daha iyi hissetti. Şüpheye de yer bırakmak, içinden gelen itirazı azaltabilir.","Telkinlerin kendisi araştırmalarda sınanmadı. Buradaki uyarlama, Robbins’in beden ve ses kullanımını araştırmaların gerçekçi ifade bulgusuyla birleştiriyor."],visual:{kind:"compare",title:"Sade bir olumlama ve dürüst bir telkin",left:{label:"Ters tepebilecek sade olumlama",items:["“Mükemmelim” gibi kapsamlı bir iddia.","Zihnin karşı çıkarken pasifçe tekrarlanır.","Şüpheyi tamamen yok sayar.","Yapacağın hiçbir şeye bağlı değil."]},right:{label:"Dürüst telkin",items:["“Bugün cesur bir arama yapabilirim” gibi belirli ve inanılır.","Dik duruş ve güçlü bir nefesle sesli söylenir.","Şüpheye yer açar: “bir yanım emin olmasa bile”.","Bugün yapacağın tek bir eyleme bağlı."]},note:"Robbins’in ayrımına ve Wood ve arkadaşlarının (2009) bulgularına dayanıyor. Örnek cümleler ODA’ya ait."}},{heading:"Işık görselleştirmesi ve hızlı nefes hakkında",paragraphs:["Bedeninde ışık hareket ettiğini hayal etmek seni sakinleştirebilir. İstersen bu imgeyi kullanabilirsin. Ama hastalığı iyileştirmez; tıbbi bakımı geciktirmek için bir neden olamaz. Hızlı ve güçlü nefes başını döndürebilir. Turları kısa tut. Baş dönmesi ya da karıncalanma hissedersen dur. Araba kullanırken, suda veya düşebileceğin bir yerde ayakta deneme."]}],example:{title:"Sam, 52, otobüs şoförü",text:"Sam erken vardiyada çalışıyordu. Eskiden ilk yirmi dakikasını dinlenme odasında haberlere bakarak geçirir, direksiyona sinirli otururdu. Evden çıkmadan mutfak masasında on dakikalık hazırlığı denedi. İki dakika döngüsel iç çekme yaptı. Hızlı nefesi bir kez denemiş, başı dönmüştü. Üç dakika üç minnettarlık sahnesini düşündü: torununun çizdiği resim, garaj üzerindeki şafak, eşinin yaptığı kahve. Üç dakika boyunca güzergâhın iyi gittiğini hayal etti. Para üstü için hep tartışan yolcuya sabırla yanıt verdiğini de canlandırdı. Sonra ayağa kalkıp omuzlarını geriye aldı: “Başkaları sakin olmasa da ben bugün sakin kalabilirim.” Daha geç sinirlendiğini fark etti. Beş sabahın dördünde bu rutini sürdürdü."},practice:["Geçmişinden, bugünden ya da hayal ettiğin gelecekten üç somut minnettarlık anı yaz. Her biri bir satır olsun.","Bugün yapacağın bir eyleme bağlı, belirli ve inanılır bir telkin taslağı hazırla.","Yarın sabah on dakikalık bir zamanlayıcı kur ve telefonuna bakmadan önce hazırlık adımlarını çalıştır."],reflection:"Sabahları kendine gerçekten inanabileceğin ne söylerdin?",question:"Wood ve arkadaşları, kişinin olumlu bir cümleyi kendine tekrarlaması hakkında ne buldu?",options:["Benlik saygısından bağımsız olarak herkese yardımcı oldu.","Benlik saygısı düşük kişileri daha kötü, benlik saygısı yüksek kişileri biraz daha iyi hissettirdi.","Kimse üzerinde bir etkisi olmadı."],correct:1,feedback:"Doğru. İnanmadığın cümleleri tekrarlamak içinden itiraz doğurabilir ve ters tepebilir. Bu özellikle kendini değersiz hissedenlerde görülebilir. Somut ve gerçekçi bir cümle, kendine destek olmanı kolaylaştırır.",takeaway:"Güne nasıl başlamak istediğini önceden seç. Kendine inanabileceğin sözler söyle.",sources:["state-robbins-priming","state-priming-cnbc","state-robbins-rituals","state-positive-self-statements","state-gratitude-expressed","state-gratitude-meta","state-cyclic-sighing","state-nhs-breathing-tips"],visual:{kind:"steps",title:"On dakikalık sabah hazırlığı, ODA uyarlaması",steps:[{label:"Nefes (2 dk)",text:"Önce döngüsel iç çekmeyi seç. Daha hızlı turlar denersen kısa tut. Başın dönerse dur."},{label:"Minnettarlık (3 dk)",text:"Geçmişinden, şimdiden ya da geleceğinden üç belirli anı yeniden yaşa."},{label:"Görselleştir (3 dk)",text:"Bugünün, olası bir engelle nasıl başa çıktığın dahil, iyi gittiğini gör."},{label:"Üç sonuç (1 dk)",text:"Bugünü değerli kılacak üç sonucu adlandır."},{label:"Telkin (1 dk)",text:"Dik dur. İnanabileceğin bir sözü yüksek sesle söyle."}],note:"Tony Robbins’in sabah hazırlığından uyarlandı. Bu rutin bir bütün olarak araştırılmadı. Parçaları için sınırlı ya da kısmi kanıt var."},technique:{name:"Sabah hazırlığı (priming)",origin:"Tony Robbins · Train your brain in minutes, tonyrobbins.com",steps:["Dik otur. Gözlerini kapatabilir ya da aşağı bakabilirsin.","Yaklaşık iki dakika yavaş nefes çalışması yap. Başın dönerse dur.","Minnettarlık duyduğun üç belirli anı hatırla ve her birini hisset.","İstersen bedeninde hareket eden sakinleştirici bir ışığı ya da sıcaklığı gözünün önüne getir.","Bugün için üç sonuç seç. Bir engelle başa çıkışını da içerecek şekilde, bu sonuçlara ulaştığını hayal et.","Ayağa kalk ve belirli, inanılır tek bir telkini enerjiyle yüksek sesle söyle."],evidence:"Sabah hazırlığı bir bütün olarak araştırılmadı. Parçaları kısmen destekleniyor. Küçük, bir aylık çalışmada yavaş nefes olumlu ruh hâlini artırdı. Minnettarlık alıştırmaları ortalama küçük etkiler gösteriyor. Olumlu cümleleri kendine tekrarlamak ise benlik saygısı düşük kişilerde ters tepebilir. İyileştirici ışık hayal etmek hastalığı tedavi etmez.",sourceId:"state-robbins-priming"},photo:{id:"1552838671-0e948f9f69b5",alt:"Yeşil çimenlerde oturan, sabah güneşine bakan bir kadın"}},{id:"state-7",title:"Dickens süreci ve yeni standartlar",minutes:11,goal:"Dickens sürecinin kısa ve şefkatli uyarlamasıyla, eski bir kalıbın sana neye mal olduğunu gör. Sonra küçük bir günlük eylemle destekleyeceğin yeni bir standart seç.",reading:["Robbins, Dickens sürecinin adını Bir Noel Şarkısı’ndaki üç hayaletten aldı. Seni sınırlayan bir inanç ya da kalıp seçersin. Geçmişte sana neye mal olduğuna, şimdi seni ve sevdiklerini nasıl etkilediğine bakarsın. Hiçbir şey değişmezse bir, üç, beş ve on yıl sonra neye mal olacağını düşünürsün. Sonra değiştirirsen nasıl bir gelecek olacağını hayal edersin. Robbins bu uygulamayı yoğun duygularla yürütür; amacı değişme isteğini artırmaktır. ODA daha şefkatli bir uyarlama kullanır. Kısa ve yazılı ilerlersin, somut olanları yazarsın. Zamanın çoğunu istediğin geleceğe ve ilk adıma ayırırsın.","Robbins, kalıcı değişim için standartlarını yükseltmeni önerir. Belirsiz bir “Yapsam iyi olur” düşüncesini net bir karara çevirirsin. Araştırmalar bunu kendine sert davranmadan da yapabileceğini düşündürüyor. İstediğin geleceği ve önündeki engelleri zihninde karşılaştırıp eğer-öyleyse planlarıyla birleştirmenin, hedefe ulaşmada ortalama küçük ile orta düzeyde etkisi bulundu. Juliana Breines ve Serena Chen’in dört deneyinde de başarısızlığına öz şefkatle bakmak gelişme isteğini artırdı. Bir sınavda başarısız olduktan sonra daha uzun çalışmak buna bir örnek. Değişmek için kendini utandırman gerekmiyor."],deeper:[{heading:"Şefkat değişime nasıl yardımcı olur?",paragraphs:["Kendine sert davranmadan değişemeyeceğini düşünebilirsin. Ama Breines ve Chen’in çalışmalarında öz şefkat, bir zayıflığın değişebileceğine inanmayı, hatayı telafi etmeyi ve çaba göstermeyi artırdı.","Öz şefkat, sorumluluğu bırakmak değildir. Yüksek bir standardı korurken kendine yardıma değer biri gibi davranmaktır."],visual:{kind:"compare",title:"Eski bir kalıbı gözden geçirmenin iki yolu",left:{label:"Utanca dayalı gözden geçirme",items:["Hâlâ bunu yaptığım için acınasıyım.","Planı olmayan koca bir yemin.","Tek bir aksama yine başarısız olduğum anlamına gelir."]},right:{label:"Öz şefkatli gözden geçirme",items:["Bu konu önemli. Ben de insanım ve aksayabilirim.","Bir standart ve her gün küçük bir eylem.","Bir aksama bilgidir; yarın yeniden başlarım."]},note:"Breines & Chen (2012), öz şefkat ve motivasyon üzerine dört deneyden esinlenildi."}},{heading:"“Yapsam iyi olur” düşüncesini karara çevir",paragraphs:["Somut bir standardı sürdürmek daha kolaydır. Tek bir net karar ver. Seni en çok hangi engelin durdurabileceğini belirle ve onun için bir eğer-öyleyse planı yaz. Her gün bu kararı destekleyen küçük bir şey yap. Haftada bir, kendine nazik davranarak nasıl gittiğine bak."],visual:{kind:"cycle",title:"Yeni bir standart nasıl yerleşir?",nodes:[{label:"Karar ver",text:"Tek bir net standart. Örneğin: e-postalarımdan önce aileme yanıt veririm."},{label:"Planla",text:"Olası engel ortaya çıkarsa belirlediğim eylemi yaparım."},{label:"Harekete geç",text:"Standardı kanıtlayan en küçük günlük eylem."},{label:"Gözden geçir",text:"Neyin işe yaradığına nazikçe bak ve ayarla."}],center:"Yeni standart",note:"Eğer-öyleyse planlarıyla zihinsel karşılaştırma, 21 çalışmalık bir meta-analizde hedefe ulaşmada küçük ile orta arası bir ortalama etki gösterdi (g = 0,336)."}},{heading:"Bu alıştırmayı ne zaman atlamalı",paragraphs:["Bir kalıbın sana neye mal olduğunu düşünmek güçlü duygular doğurabilir. Yas tutuyorsan, çok keyifsizsen ya da depresif hissediyorsan gelecekteki bedeller adımını atla. Doğrudan istediğin geleceğe geçebilirsin. Ya da dersi başka bir güne bırakıp güvendiğin biriyle veya bir uzmanla konuşabilirsin. Kendine zarar verme düşüncelerin varsa hemen 112’yi ara."]}],example:{title:"Elena, 36, grafik tasarımcı",text:"Elena yıllardır portfolyosunu “Hazır hissettiğimde” güncelleyeceğini söylüyordu. Bir pazar öğleden sonra yirmi dakikalık zamanlayıcı kurdu. Dickens sürecinin şefkatli uyarlamasını yazdı. Geçmiş: başvurmadığı iki iş ilanı. Şimdi: işinde sıkışmış hissediyor ve içten içe kırgın. Değişmeyen gelecek: beş yıl sonra aynı masa ve aynı hikâye. Göğsünün sıkıştığını fark edince bu aşamayı bırakıp istediği geleceğe geçti. Zamanının çoğunu buna ayırdı: bir stüdyoda çalışmak ve göstermekten gurur duyduğu işler üretmek. Yeni standardı, hafta içi sabahları sosyal medyadan önce portfolyosuyla ilgilenmekti. İlk adımı pazartesi on beş dakika çalışmaktı. Çarşamba aksattı. Bunu kabullenip perşembe yeniden başladı."},practice:["Seni geri tutan bir kalıp ya da inanç seç ve tek cümleyle yaz.","Bu kalıbın geçmişte, bugün ve gelecekte sana neye mal olduğunu ikişer üçer somut satırla yaz. Sonra istediğin gelecek için bunun iki katını yaz.","Onu bir eğer-öyleyse planı ve yarın yapacağın küçük bir eylemle tek bir standarda çevir."],reflection:"Hayatındaki hangi “Yapsam iyi olur” düşüncesini artık net bir karara çevirmek istiyorsun?",question:"ODA’nın Dickens süreci uyarlamasını, kendini hırpalamaktan ayıran ne?",options:["Kısa ve somut ilerler. İstediğin gelecek ve ilk adımla biter.","Değişecek kadar kötü hissedene kadar her hata üzerinde duruyor.","Maliyetleri atlayıp yalnızca başarıyı hayal ediyor."],correct:0,feedback:"Evet. Bir kalıbın neye mal olduğunu görmek değişme isteğini artırabilir. Şefkatli uyarlamada bu kısmı kısa ve somut tutarsın. Asıl çabayı istediğin geleceğe ve ilk adıma ayırırsın. Araştırmalar, öz şefkatin değişimi utançtan daha iyi desteklediğini düşündürüyor.",takeaway:"Neye mal olduğunu gör. Yeni bir standart seç ve her gün küçük bir eylemle destekle.",sources:["state-robbins-dickens","state-robbins-standards","state-mental-contrasting","state-self-compassion-motivation"],visual:{kind:"table",title:"Dickens sürecinin şefkatli uyarlaması",columns:["Aşama","Soru","Kendine şefkat göster"],rows:[["Geçmiş","Bu kalıp bana şimdiye kadar neye mal oldu?","Kendine hakaret etmeden, olanı yaz."],["Şimdi","Bana ve sevdiklerime şimdi neye mal oluyor?","İki üç satır yeterli."],["Gelecek, değişmeden","Bir, beş ve on yıl içinde nereye çıkıyor?","Bunaltıcı gelirse dur."],["Gelecek, değişmiş","Onu değiştirirsem neler mümkün olur?","En çok zamanı buraya ayır."],["İlk adım","Yarın hangi tek eylem yeni standardı kanıtlar?","Yapılabilecek kadar küçük tut."]],note:"Tony Robbins’in Dickens sürecinden uyarlandı. Sürecin kendisi incelenmedi."},technique:{name:"Dickens süreci (şefkatli uyarlama)",origin:"Tony Robbins · Unlocking potential, tonyrobbins.com",steps:["Bir sınırlayıcı inancı ya da kalıbı tek cümleyle adlandır.","Geçmişte sana neye mal olduğunu, kendine hakaret etmeden kısaca yaz.","Şimdi sana ve önemsediğin insanlara neye mal olduğunu yaz.","Hiçbir şey değişmezse bir, beş ve on yıl içinde nereye çıktığını gözünün önüne getir ve bunaltıcı olursa dur.","Zamanının çoğunu, bu kalıbı değiştirirsen geleceğinin nasıl olacağını somut ayrıntılarla hayal etmeye ayır.","Yeni bir inanç ya da standart ve yarın atacağın küçük bir eylem yaz."],evidence:"Dickens sürecinin kendisi araştırılmadı. İlgili bir yöntem olan zihinsel karşılaştırmayı eğer-öyleyse planlarıyla birleştirmek, hedefe ulaşmada ortalama küçük ile orta düzeyde etki gösterdi. Deneylerde, başarısızlıktan sonra öz şefkat gelişme isteğini artırdı. Kendini utandırmanın daha iyi sonuç verdiğine dair kanıt yok.",sourceId:"state-robbins-dickens"},photo:{id:"1633210155534-e43f00c1d627",alt:"Açık havada bir kayanın üstünde oturup deftere yazan bir kadın"}}]},De=Object.freeze(Object.defineProperty({__proto__:null,COURSE:Ie,SOURCES:Ae},Symbol.toStringTag,{value:"Module"})),Ce=[{id:"optimism-maier-seligman",title:"Maier & Seligman · 2016 · Learned helplessness at fifty: insights from neuroscience (Psychological Review) (Öğrenilmiş çaresizlik elli yaşında: nörobilimden bulgular)",url:"https://doi.org/10.1037/rev0000033",type:"research",finding:"Derleme, 1967’deki özgün kuramın mekanizmayı tersinden kurduğu sonucuna varıyor. Uzun süren, kontrol edilemeyen şoklardan sonra ortaya çıkan pasiflik, öğrenilmemiş bir varsayılan tepki (dorsal rafe çekirdeği aracılığıyla). Hayvanlar, davranışlarıyla sonucu değiştirebildiklerini öğreniyor. Medial prefrontal korteks bunu fark ediyor ve bu doğal pasif tepkiyi baskılıyor. Yazarlar bunun depresyon tedavisi açısından da anlam taşıyabileceğini öne sürüyor.",limitation:"Ağırlıklı olarak hayvan araştırmalarına dayanıyor; bunun gündelik aksiliklerle karşılaşan insanlara nasıl uyarlanacağı yazarların tahminidir, bu derlemede sınanmadı. Özet okundu (Europe PMC üzerinden)."},{id:"optimism-sweeney",title:"Sweeney, Anderson & Bailey · 1986 · Attributional style in depression: a meta-analytic review (Journal of Personality and Social Psychology) (Depresyonda açıklama biçimi: bir meta-analiz)",url:"https://doi.org/10.1037/0022-3514.50.5.974",type:"research",finding:"Yaklaşık 15.000 katılımcılı 104 çalışmada, olumsuz olayları içsel, kalıcı ve genel nedenlerle açıklamak depresyon puanlarıyla tutarlı biçimde ilişkiliydi. Olumlu olayları dışsal, geçici ve belirli nedenlerle açıklamak da depresyonla ilişkiliydi, ancak daha zayıf. Bu örüntüler hem öğrenci hem psikiyatri örneklemlerinde, hem gerçek hem varsayımsal olaylarda görüldü.",limitation:"İlişkisel bir çalışma: bir bağlantı gösteriyor, açıklama biçiminin depresyona yol açtığını göstermiyor. Eski bir derleme. Özet okundu (Europe PMC üzerinden)."},{id:"optimism-malouff",title:"Malouff & Schutte · 2017 · Can psychological interventions increase optimism? A meta-analysis (Journal of Positive Psychology) (Psikolojik müdahaleler iyimserliği artırabilir mi? Bir meta-analiz)",url:"https://doi.org/10.1080/17439760.2016.1221122",type:"research",finding:"3.319 katılımcılı 29 randomize kontrollü çalışma: müdahaleler iyimserliği ortalama g = 0,41 etkiyle artırdı. Etki; En iyi olası ben egzersizinde, yüz yüze uygulamada, aktif kontrol gruplarında, müdahaleden sonraki bir gün içindeki ölçümlerde ve (çalışmaya alınan herkes yerine) yalnızca çalışmayı tamamlayanları kapsayan analizlerde daha büyüktü.",limitation:"Kısa vadeli ölçümlerde ve yalnızca çalışmayı tamamlayanları kapsayan analizlerde etkilerin daha büyük çıkması, kalıcı değişimin daha belirsiz olduğunu düşündürüyor. Özet okundu (University of New England arşivi)."},{id:"optimism-rozanski",title:"Rozanski et al. · 2019 · Association of optimism with cardiovascular events and all-cause mortality (JAMA Network Open) (İyimserliğin kalp-damar olayları ve tüm nedenlere bağlı ölümle ilişkisi)",url:"https://jamanetwork.com/journals/jamanetworkopen/fullarticle/2752100",type:"research",finding:"229.391 katılımcılı ve ortalama 13,8 yıl izlemli 15 çalışmanın meta-analizi. Daha yüksek iyimserlik, kalp-damar olayları riskinin daha düşük olmasıyla (birleşik göreli risk 0,65, %95 GA 0,51–0,78; 10 çalışma) ve herhangi bir nedenden ölüm riskinin daha düşük olmasıyla (0,86, 0,80–0,92; 9 çalışma) ilişkiliydi.",limitation:"Dahil edilen tüm çalışmalar gözlemseldi; heterojenlik yüksekti, iyimserlik ölçümleri ve düzeltmeler farklıydı. Bir ilişki gösteriyor; iyimserliğin daha iyi sağlığa yol açtığını ya da iyimserliği artırmanın riski düşüreceğini göstermiyor. Ana bulgular ve sınırlılıklar okundu."},{id:"optimism-prp-meta",title:"Brunwasser, Gillham & Kim · 2009 · A meta-analytic review of the Penn Resiliency Program’s effect on depressive symptoms (Journal of Consulting and Clinical Psychology) (Penn Dayanıklılık Programı’nın depresif belirtilere etkisi üzerine meta-analiz)",url:"https://ppc.sas.upenn.edu/sites/default/files/prpmetaanalyticreview.pdf",type:"research",finding:"8–18 yaş arası 2.498 genci kapsayan 17 kontrollü değerlendirme. Hiçbir müdahale almayanlarla kıyaslandığında katılımcılar programdan hemen sonra (d = 0,11), 6–8 ay sonra (d = 0,21) ve 12 ay sonra (d = 0,20) daha az depresif belirti bildirdi. Aktif kontrol koşullarıyla kıyaslandığında anlamlı fark yoktu ve depresyon tanıları üzerindeki etki anlamlı değildi.",limitation:"Yapılandırılmış bir grup programına katılan gençlerde küçük etkiler; yetişkinlerin ABC becerilerini kendi başlarına kullanmasını sınamıyor. Yazarların paylaştığı PDF’nin makale özeti ve sonuçların özetlendiği bölümleri okundu."},{id:"optimism-penn-prp",title:"Positive Psychology Center, University of Pennsylvania · Resilience in children (Penn Resiliency Program) (Çocuklarda dayanıklılık)",url:"https://ppc.sas.upenn.edu/research/resilience-children",type:"guidance",finding:"Penn Dayanıklılık Programı, Ellis’in ABC modeli etrafında kurulu: öğrenciler yanlış düşünceleri fark etmeyi, doğruluklarını değerlendirmeyi ve başka yorumları düşünerek olumsuz inançlara karşı çıkmayı öğreniyor; bunun yanında kendini ifade etme, problem çözme ve gevşeme de var. Program 12 adet doksan dakikalık ya da 18–24 adet altmış dakikalık oturum olarak yürüyor. Sayfa yaklaşık 20 kontrollü çalışmaya atıf yapıyor ve bazı bulguların tutarsız olduğunu kabul ediyor.",limitation:"Programın geliştiricileri tarafından yazıldı. Bağımsız meta-analiz küçük etkiler buldu ve diğer aktif programlara göre bir üstünlük göstermedi."},{id:"optimism-hofmann",title:"Hofmann et al. · 2012 · The efficacy of cognitive behavioral therapy: a review of meta-analyses (Cognitive Therapy and Research) (Bilişsel davranışçı terapinin etkililiği: meta-analizlerin derlemesi)",url:"https://pmc.ncbi.nlm.nih.gov/articles/PMC3584580/",type:"research",finding:"Derleme, BDT ile ilgili 269 meta-analizi kapsadı. En güçlü destek; anksiyete bozuklukları, somatoform bozukluklar, bulimiya, öfke kontrolü sorunları ve genel stres için BDT’de görüldü. Yanıt oranlarını karşılaştıran 11 derlemenin 7’sinde BDT’nin yanıt oranı karşılaştırma koşullarından yüksek, 1’inde düşüktü.",limitation:"Terapi olarak uygulanan BDT hakkında, bir uygulamadaki kendi kendine yardım hakkında değil. Yazarlar bazı durumlar için yüksek kaliteli çalışmaların yetersiz olduğunu ve etnik azınlıklar ya da düşük gelirli örneklemler gibi gruplar için meta-analiz bulunmadığını belirtiyor. Tam metin özeti okundu."},{id:"optimism-smernoff",title:"Smernoff, Mitnik, Kolodner & Lev-ari · 2015 · The effects of “The Work” meditation (Byron Katie) on psychological symptoms and quality of life: a pilot clinical study (EXPLORE) (“The Work” meditasyonunun psikolojik belirtilere ve yaşam kalitesine etkisi: pilot klinik çalışma)",url:"https://www.sciencedirect.com/science/article/abs/pii/S1550830714002067",type:"research",finding:"Klinik olmayan bir örneklemden 197 kişi, The Work üzerine dokuz günlük bir kursa katıldı. Depresyon, anksiyete, mutluluk ve yaşam kalitesi puanları kurstan sonra ve altı ay sonra anlamlı biçimde iyileşti (hepsinde p < ,001). 164 kişi kurs sonrası ölçümleri, 102 kişi altıncı ay takibini tamamladı.",limitation:"Kontrol grubu olmayan, tek gruplu bir pilot çalışma. Katılımcıların önemli bir kısmı çalışmadan ayrıldı. Yazarlar randomize çalışmalar yapılması gerektiğini belirtiyor. Özet okundu."},{id:"optimism-seligman-exercises",title:"Seligman, Steen, Park & Peterson · 2005 · Positive psychology progress: empirical validation of interventions (American Psychologist) (Pozitif psikolojide ilerleme: müdahalelerin deneysel doğrulanması)",url:"https://greatergood.berkeley.edu/images/uploads/Seligman-PosPsychProgress.pdf",type:"research",finding:"Çevrimiçi, randomize, plasebo kontrollü çalışma: 577 yetişkin rastgele gruplara ayrıldı, 411’i tüm takipleri tamamladı. Plasebo dahil tüm gruplar bir haftalık egzersizin hemen ardından kendini daha iyi hissetti. Bir hafta boyunca her gün iyi giden üç şeyi ve nedenini yazanlar, bir ay sonra başlayarak başlangıca göre daha mutlu ve daha az depresifti; bu durum üçüncü ve altıncı ayda da sürdü. Güçlü yönleri yeni bir biçimde kullanmak da benzer bir örüntü gösterdi. Faydalanmaya devam edenler, haftadan sonra da uygulamayı sürdürenlerdi.",limitation:"Katılımcılar araştırmaya kendi istekleriyle katılmıştı. Çoğu iyi eğitimli, beyaz ve hafif depresifti; daha mutlu olmak istiyorlardı. Sonraki tekrarlarda etkiler daha küçük ya da alıştırmalara daha az özgü çıktı. Tam metin okundu (Greater Good Science Center’ın barındırdığı kopya)."},{id:"optimism-mongrain",title:"Mongrain & Anselmo-Matthews · 2012 · Do positive psychology exercises work? A replication of Seligman et al. (2005) (Journal of Clinical Psychology) (Pozitif psikoloji egzersizleri işe yarıyor mu? Seligman ve arkadaşlarının çalışmasının tekrarı)",url:"https://doi.org/10.1002/jclp.21839",type:"research",finding:"Özgün yöntem, daha iyi bir kontrol grubu ve eklenen bir “olumlu plasebo” ile uygulandığında, üç iyi şey ve güçlü yönleri kullanma mutlulukta kalıcı artış sağladı; ancak olumlu plasebo da aynısını yaptı. Egzersizler depresyondaki değişimde kontrol koşulunu geçemedi.",limitation:"Yalnızca özet okundu (Europe PMC üzerinden); örneklem ayrıntıları incelenmedi. Yazarlar yararın, olumlu ve kişisel olarak anlamlı bilgileri düşünmenin genel bir etkisinden gelebileceğini öne sürüyor."},{id:"optimism-bolier",title:"Bolier et al. · 2013 · Positive psychology interventions: a meta-analysis of randomized controlled studies (BMC Public Health) (Pozitif psikoloji müdahaleleri: randomize kontrollü çalışmaların meta-analizi)",url:"https://link.springer.com/article/10.1186/1471-2458-13-119",type:"research",finding:"6.139 katılımcılı 39 çalışma. Programlardan hemen sonra: öznel iyi oluş d = 0,34, psikolojik iyi oluş d = 0,20, depresyon d = 0,23. 3–6 ay sonra: 0,22, 0,16 ve 0,17; depresyon üzerindeki etki artık anlamlı değildi.",limitation:"Çalışmaların hiçbiri tüm kalite ölçütlerini karşılamadı (20’si düşük kaliteli sayıldı) ve yayın yanlılığına dair kanıt vardı. Yalnızca üç iyi şeyi değil, birçok farklı egzersizi bir araya getiriyor. Özet ve sonuçlar okundu."},{id:"optimism-wood",title:"Wood, Perunovic & Lee · 2009 · Positive self-statements: power for some, peril for others (Psychological Science) (Kendine söylediğin olumlu cümleler: kimilerine güç, kimilerine tehlike)",url:"https://journals.sagepub.com/doi/10.1111/j.1467-9280.2009.02370.x",type:"research",finding:"Bir anket, insanların kendilerine söyledikleri olumlu cümleleri sık kullandığını ve onlara güvendiğini gösterdi. İki deneyde, özsaygısı düşük olup sevilmeye değer biri olduğuna dair bir cümleyi tekrarlayanların ruh hâli kontrol grubuna göre daha kötüleşti; özsaygısı yüksek olanlar ise yalnızca biraz daha iyi hissetti.",limitation:"Anlık ruh hâlini ölçen kısa deneyler; yalnızca özet okundu. Her tür olumlu düşüncenin zararlı olduğunu göstermiyor."},{id:"optimism-nhs-cbt",title:"NHS · Cognitive behavioural therapy (CBT) (Bilişsel davranışçı terapi)",url:"https://www.nhs.uk/mental-health/talking-therapies-medicine-treatments/talking-therapies-and-counselling/cognitive-behavioural-therapy-cbt/overview/",type:"guidance",finding:"NHS, BDT’yi bir terapistin düşünme ve davranma biçimini değiştirmene yardım ettiği bir konuşma terapisi olarak tanımlıyor. Depresyon, anksiyete bozuklukları, TSSB ve başka durumlar için kullanılıyor, genellikle 5 ila 15 oturum sürüyor; belirtiler düzelmezse daha fazla oturum ya da başka tedaviler gerekebilir. Sayfa acil ruh sağlığı yardımına bağlantı veriyor.",limitation:"Erişim ayrıntıları İngiltere’ye özgü. Bu kurstaki kendi kendine yardım egzersizleri, eğitimli bir terapistle yapılan BDT’nin yerini tutmaz; acil durumda 112’yi ara."},{id:"optimism-distortions",title:"Psychology Tools · Cognitive distortions: unhelpful thinking styles (extended) (Bilişsel çarpıtmalar: yardımcı olmayan düşünme biçimleri)",url:"https://www.psychologytools.com/resource/cognitive-distortions-unhelpful-thinking-styles-extended",type:"guidance",finding:"Ya hep ya hiç düşüncesi, felaketleştirme, olumluyu geçersiz sayma, zihinsel filtre, zihin okuma, aşırı genelleme, kişiselleştirme ve “-meli/-malı” cümleleri dahil 20 yardımcı olmayan düşünme biçimini anlatıyor ve fikrin kökenini Aaron Beck’in 1960’lardaki çalışmalarına dayandırıyor; fikri sonradan David Burns yaygınlaştırdı.",limitation:"Yaygın kategorileri özetleyen bir klinisyen kaynağı; kategoriler birbiriyle örtüşüyor ve bir tanı değil."},{id:"optimism-seligman-book",title:"Martin E. P. Seligman · Learned Optimism: How to Change Your Mind and Your Life (1990; Vintage edition 2006) (Öğrenilmiş iyimserlik)",url:"https://www.penguinrandomhouse.com/books/163862/learned-optimism-by-martin-e-p-seligman-phd/",type:"technique",finding:"Seligman, açıklama biçimini, yani aksilikler için verdiğin açıklamaların ne kadar kalıcı, yaygın ve kişisel olduğunu anlatıyor. Pes etme alışkanlıklarını daha yapıcı açıklamalarla değiştirmeyi öğretiyor. ABCDE yöntemi, Albert Ellis’in ABC modeline karşı çıkma (Disputation) ve enerji toplama (Energization) adımlarını ekliyor.",limitation:"Yayınevi sayfası okundu; buradaki ABCDE ve üç P adımları, kitabın metninden değil, ikincil anlatımlardan ve Penn’in dayanıklılık programlarındaki yakın ilişkili becerilerden yeniden anlatıldı. Bu fikirlere dayanan programlar küçük etkiler gösteriyor; kitap bir tedavi olarak sınanmadı ve tedavinin yerini tutmaz."},{id:"optimism-ellis",title:"Albert Ellis · Emotional disturbance and its treatment in a nutshell (Albert Ellis Institute) (Duygusal sıkıntı ve tedavisi, özet olarak)",url:"https://albertellis.org/wp-content/uploads/2021/09/Emotional-Disturbance-and-Its-Treatment-in-a-Nutshell-ABCs-.pdf",type:"technique",finding:"Ellis, ilk kez 1956’da sunduğu ABC modelini anlatıyor. Tetikleyici olaylar (A), inançlar (B) aracılığıyla duygusal ve davranışsal sonuçlara (C) yol açar. Katı zorunluluklar ve felaketleştiren yorumlar duygusal sıkıntıyı artırır. Bu inançları düşünce, duygu ve davranış düzeyinde sorgulamak (D), tercihlere dayanan yeni ve daha esnek inançlara (E) götürür.",limitation:"Akılcı duygusal davranışçı terapinin kurucusu tarafından yapılmış bir anlatım, bir araştırma derlemesi değil; bu kurs için REBT sonuç araştırmaları incelenmedi."},{id:"optimism-beck-thought-record",title:"Judith S. Beck · Thought Record Worksheet, from Cognitive Behavior Therapy: Basics and Beyond, 3rd edition (Beck Institute, 2020) (Düşünce kaydı çalışma sayfası)",url:"https://beckinstitute.org/wp-content/uploads/2021/08/Thought-Record-Worksheet.pdf",type:"technique",finding:"Çalışma sayfasında tarih ve saat, durum, inanç derecesi (%0–100) ile otomatik düşünceler, yoğunluğuyla duygular, bilişsel çarpıtma, daha işlevsel yanıt ve sonuç sütunları var. Yönlendirici soruları; düşünceyi destekleyen ve çürüten kanıtları, başka açıklamaları, en kötü, en iyi ve en gerçekçi sonuçları, bir arkadaşına ne söyleyeceğini ve düşünceye bağlı kalmanın ya da onu değiştirmenin etkisini soruyor.",limitation:"BDT içinde kullanılmak üzere tasarlanmış klinik bir çalışma sayfası. Tek başına kullanıldığında kendi kendine yardımdır ve kendi başına kullanım, terapist eşliğindeki BDT’den daha az incelenmiştir."},{id:"optimism-the-work",title:"Byron Katie · Do The Work: instructions (thework.com) (The Work’ü yap: yönergeler)",url:"https://thework.com/instruction-the-work-byron-katie/",type:"technique",finding:"Katie’nin yönergeleri: bir kişi ya da durum hakkındaki sıkıntı veren yargılarını kısa ve basit cümlelerle yaz; sonra her birine dört soru sor (doğru mu, kesinlikle emin olabilir misin, ona inandığında nasıl tepki veriyorsun, o düşünce olmasaydı kim olurdun); ardından düşünceyi ters çevir (kendine, karşındakine, tersine) ve her ters çevirme için en az üç gerçek örnek bul.",limitation:"Yazarın kendi yönergeleri; araştırma birikimi erken dönem, kontrolsüz çalışmalarla sınırlı."},{id:"optimism-mrt",title:"Reivich, Seligman & McBride · 2011 · Master Resilience Training in the U.S. Army (American Psychologist) (ABD Ordusu’nda Usta Dayanıklılık Eğitimi)",url:"https://ppc.sas.upenn.edu/sites/default/files/mrtinarmyjan2011.pdf",type:"technique",finding:"Penn Dayanıklılık Programı’ndan uyarlanan, ordu çavuşları için bir dayanıklılık kursunu anlatıyor: ABC modeli ve açıklama biçimi, düşünme tuzakları (aşırı genelleme, sonuca atlama ve “ben” odaklı bir biçim gibi), daha derindeki “buzdağı” inançlar, olaya daha geniş açıdan bakma (en kötü, en iyi ve en olası sonuç, sonra bir plan) ve iyi giden şeyleri arayıp her gün kaydetme.",limitation:"Bir program tanımı. Yayımlandığı sırada yalnızca katılımcıların anlık geri bildirimi bildirilmişti, kontrollü değerlendirmeler sürüyordu. Yazarların paylaştığı PDF okundu."},{id:"optimism-ggia-three-good-things",title:"Greater Good in Action (UC Berkeley) · Three Good Things (Üç iyi şey)",url:"https://ggia.berkeley.edu/practice/three-good-things",type:"technique",finding:"Yönerge: en az bir hafta boyunca günde yaklaşık on dakika ayırıp iyi giden üç şeyi ayrıntılarıyla, sana ne hissettirdiğini ve nedenini yazmak. Sayfa, 2005’teki Seligman çalışmasına ve çeşitli ülkelerde yapılan, daha yüksek iyi oluş ile daha az karamsarlık, depresyon ya da kaygı bildiren sonraki çalışmalara atıf yapıyor.",limitation:"Olumlu çalışmaları özetleyen ve kültürler arasında daha fazla araştırma gerektiğini söyleyen bir üniversite uygulama rehberi. Tekrarlar etkilerin küçük olduğunu ve her zaman bu egzersize özgü olmadığını düşündürüyor."}],He={id:"optimism",title:"Öğrenilmiş iyimserlik",subtitle:"Bir aksilikten sonra kendine anlattığın hikâyeyi değiştir.",description:"Aksilikler canını yakar. Onları nasıl yorumladığın, bu acının ne kadar süreceğini etkiler. Kendine anlattığın hikâyeyi fark etmeyi ve sorgulamayı öğren. Ardından daha şefkatli ve gerçeğe daha yakın bir açıklama bul.",scope:"Aksilikten sonra pes etmeye, kendini suçlamaya ya da hep en kötüsünü beklemeye yatkın yetişkinler için. Kurs, Martin Seligman’ın öğrenilmiş iyimserlik yaklaşımından, bilişsel davranışçı terapiden (BDT) ve Byron Katie’nin The Work yönteminden yararlanır. Eğitim ve kişisel çalışma içindir. Depresyon, kaygı ya da başka bir durum için tanı veya tedavi sunmaz; terapinin ya da ilacın yerini tutmaz. Umutsuzluk haftalarca sürüyorsa, gündelik hayatı sürdürmek zorlaşıyorsa ya da kendine zarar verme düşüncelerin varsa bir doktora ya da ruh sağlığı uzmanına başvur. Acil bir durumda 112’yi ara.",outcome:"Aksilikleri nasıl açıkladığını fark etmek, her yerde kullanabileceğin bir ABCDE rutini ve doldurmayı bildiğin bir düşünce kaydı. Stres veren düşünceler için dört soru, en kötü, en iyi ve en olası sonuçları değerlendirme ve her akşam üç iyi şeyi yazma alışkanlığı. Her yöntemin ne işe yarayabileceğini ve sınırlarını bilmek.",photo:{id:"1465188162913-8fb5709d6d57",alt:"Altın rengi akşam ışığında bir tepe yolunda yürüyen bir kadın"},lessons:[{id:"optimism-1",title:"Öğrenilmiş çaresizlik, öğrenilmiş umut",minutes:8,goal:"Bir aksilikten sonra pes etmenin neden doğal bir ilk tepki olabildiğini anla. Hâlâ etkileyebileceğin bir şeyi bulmayı dene.",reading:["1960’larda Martin Seligman ile Steven Maier, hayvanlara kaçınamayacakları elektrik şokları verdikleri deneyler yaptı. Sonradan kaçmak kolaylaştığında bile birçoğu denemeyi bıraktı. Araştırmacılar bu duruma öğrenilmiş çaresizlik adını verdi. Onlara göre hayvanlar, ne yaparlarsa yapsınlar sonucun değişmediğini öğrenmişti. Bu, psikolojinin en bilinen bulgularından biri oldu. Seligman onlarca yıl aynı soruyu insanlar için de araştırdı: Bazı insanlar bir aksilikten sonra neden pes ediyor, bazıları neden devam ediyor?","Elli yıl sonra Maier ve Seligman, nörobilim bulgularıyla çalışmayı yeniden ele aldı. İlk kuramın mekanizmayı ters açıkladığı sonucuna vardı. Uzun süren, kontrol edilemeyen stres karşısında pasif kalmak, beynin öğrenmeden verdiği doğal tepki gibi görünüyor. Öğrenilen şey ise kontrol: beynin ön tarafındaki bir bölge, davranışların sonucu değiştirdiğini fark ettiğinde bu tepkiyi bastırıyor. Bu bulgular hayvan araştırmalarından geliyor. İnsanlar için de aynı şeyin geçerli olduğunu varsayarken dikkatli olmak gerekir. Yine de umut veren bir bakış sunuyor: bir aksilikten sonra donup kalmak karakter kusuru değil. Neyi etkileyebileceğini fark etmek ise geliştirebileceğin bir beceri."],deeper:[{heading:"İyimserlik hakkında araştırma ne diyor",paragraphs:["İyimserlik, yani işlerin makul ölçüde iyi gideceği beklentisi, daha iyi sağlıkla bağlantılı. 2019’daki bir meta-analiz, yaklaşık 229.000 kişiyi kapsayan 15 uzun vadeli çalışmayı bir araya getirdi. En iyimser insanlarda kalp-damar olayları ve herhangi bir nedenden ölüm riski, en az iyimser olanlara göre daha düşüktü. Bunlar gözlemsel çalışmalardı: iyimserler daha çok egzersiz yapıyor, daha az sigara içiyor ya da daha fazla imkâna sahip olabilir. Yani bu bir ilişki; iyimserliğin sağlığını tek başına koruduğunun kanıtı değil.","İyimserlik öğrenilebilir mi? 3.319 kişilik 29 randomize çalışmanın meta-analizi, psikolojik egzersizlerin iyimserliği ortalama olarak orta düzeyde artırdığını buldu. Etkiler egzersizden hemen sonra ölçüldüğünde daha büyüktü; dolayısıyla değişimin ne kadar sürdüğü daha belirsiz."]},{heading:"Gündelik hayatta",paragraphs:["Çaresizlik her zaman kolay fark edilmez. Bazen aklından “Ne anlamı var ki?” geçer, bilgisayarı kapatırsın ve bedeninde bir ağırlık hissedersin. Bu kursta küçük bir adım deneyeceksin: hiçbir şey yapılamayacağına karar vermeden önce, yapacağın bir şeyle neyin değişebileceğini bul. Gönderebileceğin bir mesaj, sorabileceğin bir soru ya da ayırabileceğin on dakika olabilir."],visual:{kind:"steps",title:"Sıkışmışlıktan harekete",steps:[{label:"Fark et",text:"Pes etmek üzere olduğunu fark et ve kendine söyle: Burada denemeyi bırakmak üzereyim."},{label:"Ayır",text:"Kontrolün dışında olanları, az da olsa etkileyebileceklerinden ayır."},{label:"Seç",text:"Kendi başına atabileceğin küçük bir adım seç."},{label:"Kaydet",text:"Sonra, eyleminin neyi değiştirdiğini ne kadar küçük olursa olsun yaz."}]}},{heading:"Sık yapılan hatalar",paragraphs:["Öğrenilmiş iyimserlik, aksiliği küçümsemek ya da üzgün olduğun için kendini suçlamak değildir. Bazı durumlar gerçekten elinde değildir. Bunu fark etmek de gerçekçi düşünmenin parçasıdır. Amaç esnek düşünebilmek: değiştiremeyeceğin şeyleri kabul ederken değiştirebileceklerini de görmek."]}],example:{title:"Daniel, 34, depo amiri",text:"Daniel şirket içi bir terfi için başvurdu ve başkasının seçildiğini öğrendi. Öğlene doğru, bir daha denemenin anlamı olmadığına karar vermişti. Artık ek projelere gönüllü olmamayı düşünüyordu. Eve dönerken yine pes etmek istediğini fark etti ve alıştırmayı denedi. Terfi kararı verilmişti, bunu değiştiremezdi. Ama yöneticisine, bir dahaki sefere daha güçlü bir aday olmak için ne yapabileceğini sorabilirdi. O akşam iki satırlık bir e-posta gönderdi. Yanıtta, yaklaşık bir ayda öğrenebileceği planlama yazılımı önerildi. Daniel o hafta hâlâ hayal kırıklığı yaşıyordu. Ama bu terfi kararının bütün geleceğini belirlediğini artık düşünmüyordu. İlk eğitim oturumuna kaydoldu."},practice:["Yakın zamanda yaşadığın bir aksiliği hatırla ve ne olduğunu anlatan tarafsız bir cümle yaz.","İki sütun çiz ve kontrolünün dışında olanları ve az da olsa etkileyebileceklerini listele.","İkinci sütundan küçük bir eylem seç ve önümüzdeki 24 saat içinde yap ya da takvimine koy."],reflection:"Hayatının hangi alanında bir zamanlar anlamsız geldiği için denemeyi bıraktın ve bu bugün hâlâ doğru mu?",question:"Maier ve Seligman’ın 2016 güncellemesine göre, çaresizlik deneylerinde aslında ne öğreniliyor?",options:["Yaptığın hiçbir şeyin önemi olmadığı: kötü deneyimler çaresizliği öğretir.","Kontrol: beyin, eylemlerin ne zaman fark yarattığını algılamayı öğrenir ve bu, varsayılan pasif tepkiyi yatıştırır.","İyimserlik: bazı hayvanlar doğuştan umutludur, bazıları değildir."],correct:1,feedback:"Güncellenmiş görüşe göre, uzun süren, kontrol edilemeyen stres altında pasiflik varsayılan durumdur. Deneyimin öğrettiği şey ise eylemlerin önemli olabileceğidir. Bu yüzden az da olsa etkileyebildiğin şeyleri bulup harekete geçmeyi denemek değerlidir.",takeaway:"Donup kalmak doğal bir tepkidir. Neyi etkileyebileceğini fark etmek öğrenilebilir.",sources:["optimism-maier-seligman","optimism-rozanski","optimism-malouff","optimism-seligman-book"],visual:{kind:"compare",title:"Öğrenilmiş çaresizlik: eski ve yeni açıklama",left:{label:"Özgün kuram (1967)",items:["Kaçılamayan şoklar, yaptığın hiçbir şeyin önemi olmadığını öğretir","Pasiflik deneyimden öğrenilir","Öğrenilen şey çaresizliktir"]},right:{label:"Nörobilim güncellemesi (2016)",items:["Pasiflik, uzun süren kontrol edilemeyen strese verilen varsayılan tepkidir","Kontrolü fark etmek bu doğal tepkiyi bastırır","Öğrenilen şey kontroldür"]},note:"Maier ve Seligman’ın (2016) derlediği hayvan çalışmalarına dayanıyor; bunun insanlara tam olarak nasıl uyarlanacağı hâlâ araştırılıyor."},photo:{id:"1527580094867-0e719f119120",alt:"Güneşin doğmasını beklerken sabahın erken saatinde gri kayalardan geçen bir yürüyüşçü"}},{id:"optimism-2",title:"Açıklama biçimin",minutes:9,goal:"Kötü olayları açıklama biçiminin üç boyutunu öğren ve gerçek bir örnekte kendi biçimini fark et.",reading:["Hayvan çalışmalarından kısa süre sonra araştırmacılar, insanların aksilikleri farklı biçimlerde açıkladığını fark etti. Seligman bu alışkanlığa açıklama biçimi adını verdi. Üç boyutu var. Kalıcılık: bu hep sürecek mi (“Hep batırıyorum”), yoksa geçici mi (“Bu hafta çok yorgundum”)? Yaygınlık: her şeyi mi etkiliyor (“Hiçbir işe yaramıyorum”), yoksa tek bir alanı mı (“İstatistikte henüz iyi değilim”)? Kişiselleştirme: her şey senin yüzünden mi oldu (“Aptalım”), yoksa koşulların da payı var mı (“Yönergeler belirsizdi ve acele ettim”)? Karamsar açıklamalar, sorunu kalıcı sayar, hayatın her alanına yayar ve bütünüyle kişiye bağlar.","Açıklamaların bundan sonra ne yapacağını etkiler. Sorunun nedenini kalıcı ve hayatının her alanında geçerli sayarsan, tekrar denemek anlamsız görünür. Yaklaşık 15.000 kişinin katıldığı 104 çalışmanın derlemesinde, kötü olayları kişinin kendisine, kalıcı ve genel nedenlere bağlaması daha fazla depresif belirtiyle ilişkili bulundu. Bu bir bağlantıdır, neden sonuç ilişkisini kanıtlamaz. Sorumluluk almaman gerektiği anlamına da gelmez. İyimser açıklama “Asla benim hatam değil” demek değildir. Daha net sorular sormaktır: Tam olarak ne oldu? Hangi kısmı geçiciydi? Neyi değiştirebilirim?"],deeper:[{heading:"İyi olayları nasıl açıklıyorsun?",paragraphs:["İyi olaylarda aynı alışkanlık ters yönde işler. Karamsar düşünen insanlar başarıları geçici, yalnızca o duruma özgü ve şansa bağlı sayabilir: “Müşterinin keyfi yerindeydi, hepsi bu.” Aynı derlemede bu yaklaşım da depresif belirtilerle ilişkili bulundu. Ancak bağlantı, kötü olayları açıklama biçimindekinden daha zayıftı. Bu yüzden iyi haberlerin de hakkını vermeyi deneyeceğiz. Bir başarıda çabanın ya da yeniden kullanabileceğin güçlü bir yönünün payını fark et."],visual:{kind:"compare",title:"Karamsar açıklamalar: kötü ve iyi olaylar",left:{label:"Kötü bir olaydan sonra",items:["Bu hep olacak (kalıcı)","Bu her şeyi mahvediyor (yaygın)","Hepsi benim yüzümden (kişisel)"]},right:{label:"İyi bir olaydan sonra",items:["Bu tek seferlikti (geçici)","Sadece burada geçerli (belirli)","Sadece şanslıydım (dışsal)"]},note:"Karamsar örüntü, olayın türüne göre tersine döner. Her iki durumda nasıl işlediğini bilmek, bu alışkanlığı fark etmene yardım eder."}},{heading:"Sık yapılan hatalar",paragraphs:["Suçlamayı bahanelerle değiştirmek. “Hepsi benim suçum”dan “hepsi onların suçu”na geçmek iyimserlik değil; başka bir yanlış hikâye. Kimin ya da neyin ne kadar payı olduğunu adilce değerlendir.","Açıklama alışkanlığını değişmez bir kusur saymak. Açıklama biçimi bir düşünme alışkanlığıdır, değişmez bir hüküm değil; iyimserlik eğitimi araştırmaları da en azından kısa vadede değişebileceğini düşündürüyor."]}],example:{title:"Aylin, 27, grafik tasarımcı",text:"Aylin’in müşterisi ilk logo taslağını kısa bir e-postayla reddetti. İlk aklına gelen, bu meslek için yeterince yaratıcı olmadığıydı. Durdu ve üç P sorusunu sordu. Kalıcı mı? Bu, bir müşteri için tek bir taslaktı ve bu yıl tutturamadığı ilk işti. Yaygın mı? Portfolyosu ve iki memnun müşterisi başka bir şey söylüyordu. Kişisel mi? Kısmen: müşterinin renk tercihlerini sormayı atlamıştı. Kısmen değil: iş tanımı yalnızca iki cümleydi. Yeni açıklaması, belirsiz bir iş tanımı karşısında sorularını aceleye getirmiş olduğuydu. Böylece sonraki adımı netleşti. On beş dakikalık bir görüşme ayarladı ve altı soru sordu. İkinci taslak kusursuz değildi, ama görüşmeye yetersizliği açığa çıkacak biri gibi değil, bir taslağı düzelten bir tasarımcı olarak girdi."},practice:["Yakın zamanda yaşadığın bir hayal kırıklığını ve ona dair ilk açıklamanı, zihninden geçtiği haliyle yaz.","Açıklamanın kalıcı mı geçici mi olduğunu ve tüm hayatını mı tek bir alanı mı kapsadığını işaretle. Son olarak nedenin yalnızca seninle mi, yoksa koşullarla da mı ilgili olduğunu belirt.","Açıklamanı yeniden yaz. Geçici ve o duruma özgü olsun; senin neyi değiştirebileceğini adilce anlatsın."],reflection:"Bir şey iyi gittiğinde onu genellikle nasıl açıklıyorsun ve bu açıklama başarının hakkını veriyor mu?",question:"“Sınavda başarısız oldum çünkü aptalım” cümlesinin hangi yeni hâli daha iyimser bir açıklama biçimini yansıtıyor?",options:["Öğretmen benden hoşlanmıyor, o yüzden yaptığım hiçbir şeyin önemi olmayacak.","Sorun değil, zaten sınavların önemi yok.","Bu sınava çalışmaya çok geç başladım; bir dahaki sefere iki hafta önce başlayacağım."],correct:2,feedback:"Üçüncü seçenek geçici (bu sınav), belirli (çalışma zamanlaması) ve değiştirebileceğin kısım konusunda dürüst. Birincisi suçu başkasına atıyor ama sorunun nedenini kalıcı sayıyor; ikincisi gerçek bir sorunu geçiştiriyor.",takeaway:"Geçici, o duruma özgü ve adil bir açıklama bul. Böylece sonraki adımını görebilirsin.",sources:["optimism-sweeney","optimism-seligman-book","optimism-malouff"],visual:{kind:"table",title:"Açıklama biçiminin üç P’si",columns:["Boyut","Karamsar hikâye","İyimser hikâye"],rows:[["Kalıcılık","Hep böyle olacak.","Bu zor bir dönem."],["Yaygınlık","Bu her şeyi mahvediyor.","Bu hayatımın bir alanını etkiliyor."],["Kişiselleştirme","Tamamen benim hatam; sorun benim.","Payım var, koşulların da."]],note:"Martin Seligman’ın açıklama biçimi tanımından uyarlandı. Karamsar sütundaki açıklamalar, ilişkisel araştırmalarda depresif belirtilerle bağlantılı."},technique:{name:"Üç P kontrolü",origin:"Martin Seligman · Learned Optimism (1990; Vintage edition 2006) (Öğrenilmiş iyimserlik)",steps:["Aksilikten sonra zihninden geçen açıklamayı tam olarak yaz.","Onu kalıcı mı sayıyorsun diye sor ve geçici olduğuna dair kanıt ara.","Her şeye yayılmasına izin mi veriyorsun diye sor ve gerçekten etkilediği tek alanı adlandır.","Suçun hepsini mi yoksa hiçbirini mi üstleniyorsun diye sor ve nedenleri adil biçimde paylaştır.","Geçici, belirli ve adil yeni bir açıklama yaz ve onun işaret ettiği bir sonraki adımı adlandır."],evidence:"Karamsar açıklama biçimi depresif belirtilerle tutarlı biçimde ilişkili ve iyimserlik geliştiren egzersizler iyimserlik üzerinde kısa vadeli, orta düzeyde bir etki gösteriyor. Bu özel kontrol alıştırması tek başına sınanmadı.",sourceId:"optimism-seligman-book"},photo:{id:"1509029032154-54ba8b3216d4",alt:"Gözlüklü bir adam düşünceli biçimde pencereden dışarı bakıyor"}},{id:"optimism-3",title:"ABCDE: kendinle adilce tartışmak",minutes:10,goal:"Gerçek bir aksiliği aksilik (A), inanç (B), sonuç (C), karşı çıkma (D) ve enerji toplama (E) adımlarından geçir.",reading:["Seligman’ın öğrenilmiş iyimserlik için kullandığı temel yöntem, psikolog Albert Ellis’in 1950’lerde geliştirdiği ABC modeline dayanır. A aksiliktir: ne olduğunu, bir kamera kaydı gibi yorumsuz anlatırsın. B inancındır: olay hakkında kendine ne söyledin? C sonuçtur: ne hissettin ve ne yaptın? Çoğumuz A’nın doğrudan C’ye yol açtığını düşünürüz: “Kaba e-posta beni çıldırttı.” Ellis, arada B’nin bulunduğuna dikkat çekti. Aynı e-posta, ona verdiğin anlama göre seni öfkelendirebilir, endişelendirebilir ya da pek etkilemeyebilir.","Seligman iki adım daha ekledi. D karşı çıkmadır: düşünceyi, hakkında haksız bir şey söyleyen birine itiraz eder gibi sorgularsın. Düşünceye karşı kanıt ve başka olası nedenler ara. Sonuçlarının gerçekten düşündüğün kadar kötü olup olmadığını sor. Bir kısmı doğru olsa bile, ona tutunmak işe yarıyor mu? E enerji toplamadır: düşünceye inancın azaldığında duygularının ve davranışlarının nasıl değiştiğini fark et. Amaç kendini neşelendirmekten çok doğru bir açıklama bulmaktır. Kanıtlar acı verici bir düşünceyi gerçekten destekliyorsa, “Bu konuda ne yapabilirim?” sorusuna geçebilirsin."],deeper:[{heading:"ABC nereden geldi",paragraphs:["Albert Ellis ABC fikrini ilk kez 1956’da sundu. Akılcı duygusal davranışçı terapiyi (REBT) bu fikir üzerine kurdu. Katı zorunluluklara özellikle dikkat etti. Örneğin mutlaka başarman ya da başkalarının sana her zaman adil davranması gerektiğine inanabilirsin. Bunlar gerçekleşmeyince durumu felaket olarak yorumlayabilirsin. Ellis, kesin zorunluluklar yerine güçlü istekler benimsemeyi önerdi: başarmayı çok isteyebilir, ama başaramazsan da buna katlanabilirsin. Seligman’ın ABCDE’si ve Aaron Beck’in bilişsel terapisi aynı temel fikre dayanır. Yorumların duygularını etkiler ve bu yorumları sorgulayabilirsin."]},{heading:"Karşı çıkmanın dört yolu",paragraphs:["Düşünceye itiraz ederken somut olmak işe yarar. Her şeyin yoluna gireceğini kendine söylemek gibi belirsiz teselliler, endişeli tarafını nadiren ikna eder. Kanıtlar ve somut alternatif açıklamalar daha ikna edicidir."],visual:{kind:"steps",title:"Bir inançla tartışmanın dört yolu",steps:[{label:"Kanıt",text:"Hangi gerçekler inancı destekliyor, hangileri çürütüyor?"},{label:"Alternatifler",text:"Başka neler katkıda bulunmuş olabilir? Geçici, belirli ve değiştirilebilir nedenler ara."},{label:"Sonuçlar",text:"İnanç kısmen doğru olsa bile gerçekçi olarak ne anlama geliyor? Hissettiğin kadar kötü mü?"},{label:"Yararlılık",text:"Bu inanca tutunmak şu an işe yarıyor mu, yoksa bir sonraki adıma odaklanmak sana daha çok yardımcı olur mu?"}],note:"Karşı çıkma adımının yaygın açıklamalarını kendi sözlerimizle anlattık."}},{heading:"Araştırma ne diyor",paragraphs:["Penn Dayanıklılık Programı, gençlere on iki ya da daha fazla grup oturumunda ABC modelini, karşı çıkmayı ve problem çözmeyi öğretir. 2.498 gençle yapılan 17 kontrollü çalışmanın meta-analizi, müdahale almayanlarla kıyaslandığında depresif belirtilerde, en az bir yıl süren küçük azalmalar buldu. Ancak diğer aktif programlarla kıyaslandığında belirgin bir üstünlük göstermedi ve gerçek depresyon tanılarını anlamlı biçimde azaltmadı. Programın geliştiricileri bile sonuçların çalışmalar arasında değiştiğini kabul ediyor."],visual:{kind:"bars",title:"Penn Dayanıklılık Programı: müdahale almayanlara göre depresif belirtiler",bars:[{label:"Programdan hemen sonra",value:.11,display:"d = 0,11"},{label:"6–8 ay sonra",value:.21,display:"d = 0,21"},{label:"12 ay sonra",value:.2,display:"d = 0,20"}],note:"8–18 yaş arası 2.498 gençle yapılan 17 çalışmadan standartlaştırılmış etki büyüklükleri (d): küçük etkiler. Aktif kontrol programlarına karşı anlamlı fark yoktu. ABCDE’yi kendi başlarına kullanan yetişkinler incelenmedi.",sourceId:"optimism-prp-meta"}}],example:{title:"Priya, 41, hemşire",text:"Priya’nın yöneticisi ona sormadan bir ay boyunca gece vardiyasına aldı. A: yeni çizelge asıldı, dört hafta gece. B: Beni değerli bulmuyor ve sonsuza dek gecelerde kalacağım. C: öfke, uykusuz bir akşam ve telefonunda yazılmış sert bir yanıt. Göndermeden önce Priya D için defterini açtı. Kanıt: iki iş arkadaşı da yer değiştirmişti ve çizelgede “sonsuza dek” değil, dört hafta yazıyordu. Alternatifler: birim, iki istifadan sonra personel sıkıntısı çekiyordu. Sonuçlar: zor bir ay, bütün kariyerini belirleyecek bir karar değil. Yararlılık: öfke onu pişman olacağı bir e-postaya itiyordu. E: öfkesi dokuzdan beşe düştü. Taslağı sildi ve bunun yerine her zamanki pazar izninin korunmasını istedi. Yöneticisi kabul etti."},practice:["Bu haftadan bir aksilik seç ve A’yı, yorumsuz, bir kameranın kaydedeceği gibi yaz.","B’yi tam olarak düşündüğün gibi yaz, sonra C’yi: ne hissettiğini (0–10 arası puanla) ve ne yaptığını ya da yapmak istediğini.","İnanca kanıt, alternatifler, sonuçlar ve yararlılık üzerinden karşı çık, sonra E’yi yaz: duygun ve planın nasıl değişti."],reflection:"ABC’lerinde hangi inanç tekrar tekrar karşına çıkıyor ve kimin sesine benziyor?",question:"ABC modelinde bir olayla duygusal tepkin arasında ne durur?",options:["Olayın ne anlama geldiğine dair inancın.","Olayın kendi büyüklüğü.","Değişemeyen kişiliğin."],correct:0,feedback:"Ellis de Seligman da inancı (B), aksilik (A) ile sonuç (C) arasına yerleştirir. Olaylar önemlidir, ama aynı olay, onun hakkında anlattığın hikâyeye bağlı olarak çok farklı tepkilere yol açabilir.",takeaway:"Olanla hissettiğin arasında bir hikâye var ve bu hikâyeleri sorgulayabilirsin.",sources:["optimism-seligman-book","optimism-ellis","optimism-prp-meta","optimism-penn-prp"],visual:{kind:"cycle",title:"ABC döngüsü",nodes:[{label:"Aksilik",text:"Bir şey olur: bir ret, bir hata, bir gecikme."},{label:"İnanç",text:"Onu kendine açıklarsın, çoğu zaman saniyeler içinde."},{label:"Sonuç",text:"Duygular ve eylemler yalnızca olayı değil, inancı izler."},{label:"Sonraki durum",text:"Yaptığın şey sonra ne olacağını şekillendirir ve döngü yeniden başlar."}],center:"B’de devreye gir",note:"Albert Ellis’in ABC modeli; Martin Seligman bunu Karşı çıkma ve Enerji toplama ile genişletti."},technique:{name:"ABCDE",origin:"Martin Seligman · Learned Optimism (1990; Vintage edition 2006) (Öğrenilmiş iyimserlik)",steps:["Aksilik: olayı tarafsız bir dille, yalnızca olanları anlat.","İnanç: onunla ilgili aklından geçen düşünceleri kelimesi kelimesine yaz.","Sonuç: duygularını, ne kadar güçlü olduklarını ve ne yaptığını not et.","Karşı çıkma: inançla kanıt, alternatif nedenler, gerçekçi sonuçlar ve yararlılık üzerinden tartış.","Enerji toplama: karşı çıktıktan sonra duygularının, enerjinin ve planlarının nasıl değiştiğini kaydet."],evidence:"ABC temelli beceriler, gençlerde depresif belirtileri müdahale almayanlarla kıyaslandığında küçük ölçüde azaltan, ama diğer aktif programlarla kıyaslandığında azaltmayan Penn Dayanıklılık Programı’nın parçasıdır. ABCDE’nin yetişkinlerce tek başına kullanımı hakkında doğrudan araştırma azdır.",sourceId:"optimism-seligman-book"},photo:{id:"1643148636630-0b0fb138fc74",alt:"Kalemle defterine yazan bir kişi"}},{id:"optimism-4",title:"Düşünme tuzakları ve düşünce kaydı",minutes:11,goal:"Yaygın düşünme tuzaklarını tanı ve durumdan dengeli yanıta kadar bir düşünce kaydını tamamla.",reading:["1960’larda psikiyatrist Aaron Beck, depresyon yaşayan hastalarının aklına hızla gelen bazı düşünceleri fark etti. Bu otomatik düşünceler, belli biçimlerde gerçeği çarpıtıyordu. Beck bunlara bilişsel çarpıtmalar adını verdi. Bugün düşünme tuzakları da deniyor. En yaygınları arasında ya hep ya hiç düşüncesi (“Tek bir hata tam bir başarısızlıktır”), felaketleştirme (hemen en kötü sonucu düşünmek), zihin okuma (başkalarının ne düşündüğünü bildiğini sanmak), aşırı genelleme (tek bir olaydan genel kural çıkarmak) ve zihinsel filtre (yalnızca olumsuzları görmek) var. Herkes zaman zaman bu tuzaklara düşer. Bunlar zihnin kullandığı kestirme yollardır. Sende bir sorun olduğu anlamına gelmez.","Beck’in yaklaşımı, en çok araştırılan konuşma terapilerinden biri olan bilişsel davranışçı terapiye (BDT) dönüştü. 269 meta-analizi kapsayan bir derlemede, BDT için en güçlü kanıtlar anksiyete bozuklukları, stres, öfke sorunları ve başka bazı durumlarda bulundu. BDT’nin temel araçlarından biri düşünce kaydıdır. Durumu, otomatik düşünceyi, ona ne kadar inandığını ve duygularını bir sayfaya yazarsın. Ardından düşünme tuzağını belirler, dengeli bir yanıt yazıp sonucu kaydedersin. Yazıya dökmek önemlidir. Aklındayken gerçek gibi gelen bir düşünce, kâğıt üzerinde farklı görünebilir."],deeper:[{heading:"Dengeli yanıt nasıl yazılır",paragraphs:["Dengeli yanıt olumlu bir düşünce değildir. Endişenin doğru kısımlarını korur ve endişenin dışarıda bıraktıklarını ekler. “Sunumum bir felaketti” şuna dönüşebilir: İki kez nerede kaldığımı unuttum, ama her soruyu da yanıtladım ve iki kişi slaytlarımı istedi.","Beck Institute çalışma sayfasındaki yararlı sorular arasında şunlar var: bu düşüncenin lehine ve aleyhine kanıt nedir, başka bir açıklama var mı, en kötü, en iyi ve en gerçekçi sonuçlar nelerdir ve aynı durumdaki bir arkadaşına ne söylerdin?"],visual:{kind:"steps",title:"Bir düşünce kaydı, sütun sütun",steps:[{label:"Durum",text:"Neredeydin, ne oldu, ne zaman."},{label:"Otomatik düşünce",text:"Düşünce, kelimesi kelimesine, ona inanç derecenle birlikte (%0–100)."},{label:"Duygu",text:"Her duyguyu adlandır ve gücünü puanla (0–100)."},{label:"Dengeli yanıt",text:"Kanıtı tart ve daha adil ve kapsamlı bir yanıt yaz."},{label:"Sonuç",text:"İnancını ve duygularını yeniden puanla, ne yapacağını not et."}]}},{heading:"Düşünce kayıtları zor geldiğinde",paragraphs:["Bazı günlerde düşünce kaydı bir duvarla tartışmak gibi gelir: dengeli yanıt aklına yatar ama duyguların hemen değişmez. Bu yaygındır. Yine de inancını yeniden puanla; %90’dan %70’e düşmek gerçek bir ilerlemedir.","Bir durum hakkında yazmak seni çok daha kötü hissettiriyorsa ya da aynı acı verici düşünceler günlerinin çoğuna hâkimse, yalnız başına çalışmak yerine eğitimli bir BDT terapistiyle çalışmanın tam zamanıdır. Kendi kendine yardım çalışma sayfaları yararlıdır ama tedavinin yerini tutmaz."]}],example:{title:"Marcus, 38, satış müdürü",text:"Marcus, patronunun haftalık raporuna iki gündür yanıt vermediğini fark etti. Çarşambaya gelindiğinde işinin tehlikede olduğuna ikna olmuştu. Masasında boş bir sayfa açıp sütunlar çizdi. Durum: rapora yanıt yok. Otomatik düşünce: Rakamlarımı kötü buluyor ve beni işten çıkarmayı planlıyor, %80 inançla. Duygu: kaygı, on üzerinden yedi. Tuzaklar: zihin okuma ve felaketleştirme. Aleyhte kanıt: geçen ayki değerlendirme olumluydu ve tüm hafta seyahatteydi. Dengeli yanıt: Neden yanıt vermediğini bilmiyorum; en olası neden seyahati ve cuma günkü görüşmede sorabilirim. Sonuç: inanç %30’a, kaygı dörde düştü. Cuma günü patronu, tüm hafta e-postasını zar zor açtığından söz etti."},practice:["Düşünme tuzakları tablosunu oku ve en sık düştüğün ikisini seç.","Son birkaç günden üzücü bir düşünce seç ve durumu, inanç yüzdesiyle düşünceyi, puanıyla duyguyu ve tuzağı yaz.","Düşünceyi destekleyen ve çürüten kanıtları yaz. Aynı durumdaki bir arkadaşına ne söyleyeceğini düşün, dengeli bir yanıt yaz ve inancını ve duygunu yeniden puanla."],reflection:"Seni en iyi tanıyanlar hangi düşünme tuzağına en sık düştüğünü söylerdi?",question:"Bunlardan hangisi BDT anlamında dengeli bir yanıttır?",options:["İnanırsam her şey kusursuz olacak.","Raporda bir hata yaptım, yöneticim bu yıl işlerimin çoğunu da övdü ve bunu düzeltebilirim.","Hep bir şeyleri mahvediyorum, o yüzden denemenin anlamı yok."],correct:1,feedback:"Dengeli yanıt doğru olanı korur (bir hata vardı) ve kaygılı düşüncenin dışarıda bıraktığını ekler (övgü, düzeltme). Birinci seçenek gerçeği görmezden geliyor; üçüncüsü aşırı genelleme.",takeaway:"Her düşünceye inanmak zorunda değilsin; onu kâğıda dökebilir ve tartabilirsin.",sources:["optimism-hofmann","optimism-beck-thought-record","optimism-distortions","optimism-mrt","optimism-ellis","optimism-nhs-cbt"],visual:{kind:"table",title:"Yaygın düşünme tuzakları",columns:["Tuzak","Kulağa nasıl gelir","Sınamak için bir soru"],rows:[["Ya hep ya hiç","Kusursuz değilse başarısızlıktır.","Kusursuzla başarısızlık arasında herhangi bir orta yol var mı?"],["Felaketleştirme","Bu tam bir felaket olacak.","Yalnızca en kötüsü değil, en olası sonuç ne?"],["Zihin okuma","Beni işe yaramaz buluyorlar.","Onların ne düşündüğü hakkında gerçekte ne biliyorum?"],["Aşırı genelleme","Bu hep başıma geliyor.","Gerçekten hep mi? Ne zaman olmadı?"],["Zihinsel filtre","Bütün gün kötüydü.","Günün gözden kaçırdığım sıradan ya da iyi yanları nelerdi?"],["Kişiselleştirme","Hepsi benim yüzümden.","Başka hangi insanların ya da koşulların payı var?"]],note:"İlk olarak Aaron Beck’in tanımladığı, sonradan David Burns’ün yaygınlaştırdığı bilişsel çarpıtmalardan bir seçki; sınama soruları bize ait."},technique:{name:"Düşünce kaydı",origin:"Judith S. Beck · Cognitive Behavior Therapy: Basics and Beyond (3rd edition, 2020) (Bilişsel Davranışçı Terapi: Temeller ve Ötesi)",steps:["Durumu yaz: neredeydin, ne oldu ve ne zaman.","Otomatik düşünceyi yaz ve ona ne kadar inandığını 0’dan %100’e puanla.","Duygularını adlandır ve her birini 0’dan 100’e puanla.","Varsa, düşüncede hangi tuzağın bulunduğunu belirle.","Soruları yanıtla: lehte ve aleyhte kanıt, başka açıklamalar, en kötü, en iyi ve en gerçekçi sonuç ve bir arkadaşına ne söyleyeceğin.","Dengeli bir yanıt yaz, sonra inancını ve duygularını yeniden puanla."],evidence:"Düşünce kayıtları, özellikle anksiyete ve stresle ilgili sorunlarda çok geniş bir araştırma birikimiyle desteklenen BDT’nin temel parçasıdır. Terapi dışında kendi başına yapılan düşünce kayıtları daha az incelenmiştir ve tek başına kullanmak tedavinin yerini tutmaz.",sourceId:"optimism-beck-thought-record"},photo:{id:"1681396059172-7532b1ef8b47",alt:"Yumuşak sabah ışığında bir masanın üzerinde açık duran günlük"}},{id:"optimism-5",title:"Stres veren bir düşünce için dört soru",minutes:9,goal:"Seni tekrar tekrar üzen bir düşünce üzerinde Byron Katie’nin dört sorusunu ve ters çevirme yöntemini dene.",reading:["Amerikalı konuşmacı ve yazar Byron Katie, The Work adını verdiği bir yöntem geliştirdi. Düşünceye kanıtlarla itiraz etmek yerine, onu sakince ele alıp dört soru sorarsın. Birincisi: Bu düşünce doğru mu? İkincisi: Doğru olduğundan kesinlikle emin olabilir miyim? Üçüncüsü: Buna inandığımda bedenim, duygularım ve davranışlarım nasıl etkileniyor? Dördüncüsü: Aynı durumda bu düşünce aklımda olmasaydı nasıl biri olurdum? Yanıtlarını yaz. Doğru saydığın yanıta hemen gitmek yerine her soruya zaman ayır.","Sonra ters çevirme gelir: ilk düşünceyi tersine çevirip yeni hâlinin gerçek örneklerini ararsın. “Kardeşim beni dinlemeli” cümlesi “Ben kardeşimi dinlemeliyim”, “Ben kendimi dinlemeliyim” ya da belki tavsiye hiç istenmediği için “Kardeşim beni dinlememeli”ye dönüşebilir. Her ters çevirme için en az üç gerçek örnek ararsın. The Work, BDT ile örtüşür, çünkü ikisi de düşünceleri itaat edilecek değil, incelenecek bir şey olarak ele alır; ama karşı kanıt oluşturmaktan çok merakı esas alır. Araştırma tabanı ise, aşağıda göreceğin gibi, çok daha zayıf."],deeper:[{heading:"Düşünce kaydından farkı",paragraphs:["Düşünce kaydında kanıtları toplar ve değerlendirirsin. The Work’te ise bir süre kanıt aramayı bırakırsın. Üçüncü soru, düşüncenin seni nasıl etkilediğini fark ettirir. Dördüncü soru, o anı bu düşünce olmadan hayal etmene yardım eder. Bazı insanlar düşünceyi henüz çürütemese bile bu yolla ona daha az bağlandığını fark eder. Bazılarıysa kanıtları adım adım değerlendirmeyi tercih eder. Ele aldığın düşünceye hangisi uyuyorsa onu kullanabilirsin."],visual:{kind:"compare",title:"Düşünce kaydı ve The Work yan yana",left:{label:"BDT düşünce kaydı",items:["Lehte ve aleyhte kanıtı tartar","Düşünme tuzağını adlandırır","Dengeli bir yanıtla biter","Geniş bir araştırma birikimi var"]},right:{label:"The Work",items:["Emin olup olamayacağını sorar","Düşüncenin seni nasıl etkilediğini fark eder","Ters çevirmeler ve örneklerle biter","Sınırlı, erken dönem araştırmalara dayanır"]}}},{heading:"Araştırma ne diyor",paragraphs:["Yayımlanmış ana çalışma, İsrail’de 197 kişiyi The Work’ün dokuz günlük bir kursunda izledi. Depresyon, kaygı ve yaşam kalitesi puanları iyileşti ve altı ay sonra hâlâ daha iyiydi. Ancak kontrol grubu yoktu, katılımcılar klinik bir örneklem değildi ve 197 kişiden yalnızca 102’si altı aylık takibi tamamladı; yani yarar görenler kalanlar olabilir. Yazarlar da sonuçları umut verici buldu ve rastgele gruplara ayırarak yapılan çalışmalar gerektiğini belirtti. The Work’ü kanıta dayalı bir tedavi olarak değil, ilginç bir düşünme aracı olarak gör."],visual:{kind:"bars",title:"The Work’ün ana çalışmasında kaç kişi kaldı",bars:[{label:"Kursun başı",value:197,display:"197"},{label:"Kurstan sonra",value:164,display:"164"},{label:"Altı ay sonra",value:102,display:"102"}],note:"Kontrolsüz bir pilot çalışmada değerlendirmeleri tamamlayan katılımcılar (Smernoff et al., 2015). Örneklemin yaklaşık yarısının kaybedilmesi, kalıcı iyileşmelerin yorumlanmasını zorlaştırıyor.",sourceId:"optimism-smernoff"}},{heading:"Dikkatle kullan",paragraphs:["Ters çevirmeler bakış açını genişletmek içindir; başkasının zarar verici davranışından seni sorumlu kılmak için değil. Bir düşünce kötü muamele görmek, tehdit edilmek ya da güvende olmamakla ilgiliyse öncelik, yeniden çerçeveleme egzersizi değil; güvenliğin ve güvendiğin kişilerden ya da uzmanlardan alacağın destektir."]}],example:{title:"Elena, 52, öğretmen",text:"Elena haftalardır tek bir düşünceyi zihninde çeviriyordu: Kızım beni daha çok aramalı. Bir pazar günü oturup dört soruyu sordu. Doğru muydu? Doğru hissettiriyordu. Kesinlikle emin olabilir miydi? Hayır; kızı iki işte çalışıyordu. Buna inandığında nasıl tepki veriyordu? Sürekli telefonuna bakıyor, kırgın hissediyor ve görüşmelerini şikâyetlerle açıyordu. Düşünce olmasaydı kim olurdu? Muhtemelen daha sakin ve telefon çaldığında sadece sevinen biri. Ters çevirirken “Ben kızımı daha çok aramalıyım”ı denedi ve aramak yerine beklediği son dönemde üç ayrı haftayı buldu. O akşam sitem içermeyen kısa, sıcak bir mesaj gönderdi. Kızı bir sesli notla yanıt verdi ve her pazar konuşmak üzere anlaştılar."},practice:["Seni rahatsız eden bir kişi ya da durum hakkında kısa, belirli bir düşünce yaz.","Dört soruyu yazılı yanıtla, her biri üzerinde en az bir dakika sessizce düşün.","Düşünceyi iki ya da üç biçimde ters çevir ve ters çevirmelerden biri için üç gerçek örnek bul."],reflection:"Hangi düşünceye daha az bağlanmak günlük hayatında en çok şeyi değiştirirdi?",question:"Byron Katie’nin The Work yöntemine dair kanıtın dürüst bir özeti hangisi?",options:["BDT kadar iyi araştırılmıştır.","İşe yaramadığı kanıtlanmıştır.","İlk kontrolsüz çalışmalar umut verici, ama güçlü randomize çalışmalarda henüz sınanmadı."],correct:2,feedback:"Ana çalışma iyileşmeler gösterdi ama kontrol grubu yoktu ve takipte katılımcıların yaklaşık yarısını kaybetti. Bu, The Work’ü kanıta dayalı bir tedavi değil, denemeye değer ilginç bir araç yapıyor.",takeaway:"Bir düşünceyle tartışmadan önce, ondan emin olup olamayacağını ve o olmasaydı kim olacağını sor.",sources:["optimism-the-work","optimism-smernoff","optimism-hofmann"],visual:{kind:"steps",title:"Beş adımda The Work",steps:[{label:"Doğru mu?",text:"Düşüncenin doğru olup olmadığını sor. Basit bir evet ya da hayır yeterli."},{label:"Emin misin?",text:"Kesinlikle emin olup olamayacağını sor. Duruma yeniden bak."},{label:"Tepki",text:"Ona inandığında bedeninde, duygularında ve eylemlerinde neler olduğunu fark et."},{label:"O olmadan",text:"Kendini aynı durumda, düşünce olmadan hayal et."},{label:"Ters çevir",text:"Düşünceyi tersine çevir ve tersinin üç gerçek örneğini bul."}],note:"Byron Katie’nin web sitesindeki yönergelerden kendi sözcüklerimizle yeniden anlatıldı."},technique:{name:"The Work",origin:"Byron Katie · The Work (instructions at thework.com) (yönergeler thework.com’da)",steps:["Kısa, belirli, stres veren bir düşünceyi, tercihen bir kişiyle ilgili olanı, kâğıda yaz.","Doğru olup olmadığını sor ve yalnızca evet ya da hayır yanıtla.","Doğru olduğundan kesinlikle emin olup olamayacağını sor.","Düşünceye inandığında nasıl tepki verdiğini fark et: beden, duygular, eylemler ve kendine ve başkalarına nasıl davrandığın.","Kendini aynı durumda düşünce olmadan hayal et ve neyin değiştiğine dikkat et.","Düşünceyi ters çevir (kendine, karşındaki kişiye, tersine) ve her biri için üç gerçek örnek bul."],evidence:"Kontrolsüz bir pilot çalışma, dokuz günlük bir kurstan sonra depresyon, kaygı ve yaşam kalitesinde iyileşmeler buldu, ama kontrol grubu yoktu ve takipte katılımcıların yaklaşık yarısı kaybedildi. Etkililiği randomize çalışmalarda ortaya konmadı.",sourceId:"optimism-the-work"},photo:{id:"1503541517233-120571491cf3",alt:"Ağaçlarla çevrili bir parkta gözleri kapalı bankta oturan bir adam"}},{id:"optimism-6",title:"Gerçekçi iyimserlik ve üç iyi şey",minutes:10,goal:"Gerçekçi iyimserliği zorlama pozitiflikten ayır ve her akşam yapacağın üç iyi şey alışkanlığına başla.",reading:["Öğrenilmiş iyimserlik, olumlu düşünmekle aynı şey değildir. Kendine zorla neşeli cümleler söylemek ters tepebilir. Bir dizi deneyde, özsaygısı düşük kişiler sevilmeye değer olduklarını tekrarlayınca, bunu tekrarlamayanlara göre kendilerini daha kötü hissetti. Ne olursa olsun iyi tarafından bakma baskısı, yani zehirli pozitiflik, insanlara acılarına yer olmadığını hissettirebilir. Gerçekçi iyimserlikte sorunu açıkça görür ve duygularını kabul edersin. Yine de çabanın, zamanın ya da yardımın işleri biraz iyileştirebileceğini düşünürsün. En güzel ihtimali değil, en olası sonucu ararsın.","Basit bir alıştırmayla, kötü gidenleri yok saymadan iyi gidenleri fark etmeyi deneyebilirsin. Seligman ve arkadaşlarının 2005’teki çevrimiçi çalışmasında insanlar, bir hafta boyunca her gün iyi giden üç şeyi ve nedenlerini yazdı. Plasebo niteliğindeki bir yazma görevini yapanlara göre, bir ay sonra daha mutlu ve daha az depresiftiler. Fark altı aya kadar sürdü. Bu yararı daha çok yazmaya devam edenler gördü. Sonraki çalışmalarda etkiler daha küçük çıktı ve her zaman bu alıştırmaya özgü değildi. Bunu ruh hâline biraz iyi gelebilecek bir alışkanlık olarak düşünebilirsin. Tedavi değildir."],deeper:[{heading:"Gerçekçi iyimserlik ve zehirli pozitiflik",paragraphs:["Fark, kötü bir duyguya nasıl davrandığında ortaya çıkar. Zehirli pozitiflik o duyguyu bastırır; gerçekçi iyimserlik onun orada olmasına izin verir ve sonra bir sonraki yararlı adımı arar. Hem “bu gerçekten zor” hem de “bugün bir adım atabilirim” diyebilirsin."],visual:{kind:"compare",title:"Bir aksiliğe yanıt vermenin iki yolu",left:{label:"Zehirli pozitiflik",items:["Sadece pozitif kal!","Üzüntüyü, endişeyi ya da öfkeyi gizler","Gerçek riskleri görmezden gelir","İnanmadığın sloganları tekrarlar"]},right:{label:"Gerçekçi iyimserlik",items:["Bu zor ve yine de harekete geçebilirim.","Duygulara izin verir, sonra ileriye bakar","En olası sonuca göre plan yapar","İnanabileceğin açıklamaları kullanır"]},note:"Kendine söylediğin olumlu cümleler, özsaygısı yüksek insanlarda ruh hâlini hafifçe yükseltti ama özsaygısı düşük insanlarda düşürdü (Wood ve arkadaşları, 2009)."}},{heading:"Daha geniş açıdan bak",paragraphs:["Bir endişe zihninde giderek büyüyorsa, Seligman’ın ekibinin ABD Ordusu için geliştirdiği dayanıklılık eğitiminden bir yöntem deneyebilirsin. Önce aklından geçen en kötü senaryoyu yaz. Ardından, gerçekleşme olasılığı onun kadar düşük olan en iyi senaryoyu yaz. Sonra en olası sonucu belirle ve bunun için bir plan yap. En iyi senaryonun amacı, en kötü ihtimalin etkisini azaltmak. Onun yerine başka bir uç ihtimale inanmak değil."],visual:{kind:"steps",title:"En kötü, en iyi, en olası",steps:[{label:"En kötü",text:"Zihninin zaten oynattığı felaket senaryosunu yaz."},{label:"En iyi",text:"Aynı derecede olasılığı düşük en iyi senaryoyu yaz."},{label:"En olası",text:"Elindeki kanıta dayanarak muhtemelen ne olacağını yaz."},{label:"Plan",text:"En olası sonuçla başa çıkmak için bir adım belirle."}]}},{heading:"Araştırma ne diyor",paragraphs:["2005 çalışmasının bir tekrarı, üç iyi şeyin zamanla mutluluğu artırdığını, ama olumlu bir plasebo görevinin de aynısını yaptığını ve egzersizin depresyonda kontrol koşulunu geçemediğini buldu. Pozitif psikoloji egzersizlerinin daha kapsamlı bir meta-analizi, iyi oluş ve depresyon üzerinde takipte küçülen küçük etkiler buldu ve çalışmaların çoğu düşük kalitedeydi.","Sağlık araştırmalarında da sınırı bilmek önemli: iyimserlik, kalp hastalığı ve erken ölüm riskinin daha düşük olmasıyla ilişkili. Ancak bu çalışmalar gözlemsel olduğu için neden sonuç ilişkisini gösteremez. Bu alışkanlığı, hayatında daha fazla şeyi fark etmene yardımcı olduğu için sürdürebilirsin. Herhangi bir sonucu garanti etmez."]}],example:{title:"Sam, 45, otobüs şoförü",text:"Sam şükran listelerine şüpheyle bakıyordu; ama fazla mesailerle ve babasının sağlığı için kaygıyla geçen zor bir aydan sonra, bir hafta boyunca üç iyi şeyi denemeyi kabul etti. İlk gece şunları yazdı: düzenli bir yolcu beklediği için ona teşekkür etti, öğle çorbası sıcaktı ve kız kardeşi aradı. Neden? Beklemeyi seçmişti, öğle yemeğini bir gece önceden hazırlamıştı ve kız kardeşi onu önemsiyordu. Bazı geceler üç şey bulmak zordu, o da küçük şeyler yazdı: arka arkaya denk geldiği yeşil ışıklar, sessiz bir durak. Babasının tetkikleri için yine de kliniği aradı; liste bunun yerini almadı. Ama haftanın sonunda, vardiya boyunca yazabileceği iyi şeyleri aradığını fark etti ve eve dönüş yolu biraz daha hafif geldi."},practice:["Bu akşam, bugün iyi giden üç şeyi ne kadar küçük olursa olsun yaz ve her birinin neden olduğuna dair bir satır ekle.","Şu anki bir endişeni seç. En kötü senaryoyu, onun kadar düşük olasılıklı en iyi senaryoyu ve en olası sonucu yaz. En olası sonuç için bir adım da belirle.","Yarın, kendini zorla olumlu düşünmeye iterken fark ettiğinde, yaşadığın zorluğu sesli söyle ya da kâğıda yaz ve gerçekçi bir sonraki adım ekle."],reflection:"Senin için bir şeyin iyi gideceğini ummakla onun zaten iyi olduğunu farz etmek arasındaki fark ne?",question:"Hangi ifade gerçekçi iyimserliği en iyi tanımlıyor?",options:["Bir sorunu dürüstçe kabul ederken, çabanın, zamanın ya da yardımın işleri iyileştirebileceğini beklemek.","Olumsuz duygular kaybolana kadar olumlu cümleleri tekrarlamak.","Hiç hayal kırıklığına uğramamak için en kötüsünü beklemek."],correct:0,feedback:"Gerçekçi iyimserlikte durumun tamamını görürsün: zorluğu açıkça söyler ve yine de sonraki yararlı adımı ararsın. Zorlama olumlu cümleler ters tepebilir, hep en kötüsünü beklemek ise harekete geçme motivasyonunu tüketir.",takeaway:"Sorunu net gör; hâlâ iyi gidebilecek olanı da aynı netlikle ara.",sources:["optimism-wood","optimism-seligman-exercises","optimism-mongrain","optimism-bolier","optimism-mrt","optimism-ggia-three-good-things","optimism-rozanski"],visual:{kind:"bars",title:"Pozitif psikoloji egzersizleri: programdan hemen sonra ortalama etki",bars:[{label:"Öznel iyi oluş",value:.34,display:"d = 0,34"},{label:"Psikolojik iyi oluş",value:.2,display:"d = 0,20"},{label:"Depresyon (azalma)",value:.23,display:"d = 0,23"}],note:"6.139 kişilik 39 randomize çalışma (Bolier ve arkadaşları, 2013): küçük ile orta arası etkiler. 3–6. ayda etkiler daha küçüktü ve depresyon üzerindeki etki artık anlamlı değildi. Çalışmaların çoğu düşük kaliteliydi ve analiz yalnızca üç iyi şeyi değil, birçok egzersizi kapsıyor.",sourceId:"optimism-bolier"},technique:{name:"Üç iyi şey",origin:"Martin Seligman and colleagues · Positive Psychology Progress, American Psychologist (2005) (Pozitif Psikolojide İlerleme)",steps:["Yatmadan önce yaklaşık on dakika ayır; mümkünse telefon yerine bir defterle.","Bugün iyi giden üç şeyi yaz; küçük şeyler de sayılır.","Her biri için ne olduğuna ve nasıl hissettirdiğine dair birkaç ayrıntı ekle.","Her biri için neden olduğunu düşündüğünü, senin payın varsa onu da yaz.","En az bir hafta her gece tekrarla, sonra devam edip etmeyeceğine karar ver."],evidence:"Özgün çalışmada plaseboya kıyasla yararlar bir ay sonrasından itibaren ortaya çıktı ve altı ay sürdü; bu ağırlıklı olarak uygulamaya devam edenler içindi. Bir tekrar, olumlu bir plasebo ile benzer mutluluk kazanımları buldu ve depresyon için belirli bir yarar bulmadı; bu yüzden küçük, genel etkiler bekle.",sourceId:"optimism-ggia-three-good-things"},photo:{id:"1750885847789-f5748b585e3a",alt:"Balkonda durup şehre bakan bir kadın"}}]},Oe=Object.freeze(Object.defineProperty({__proto__:null,COURSE:He,SOURCES:Ce},Symbol.toStringTag,{value:"Module"})),Pe=[{id:"meaning-frankl",title:"Viktor E. Frankl · Man’s Search for Meaning (1946) and the Viktor Frankl Institute Vienna (logotherapy overview) (İnsanın Anlam Arayışı ve Viktor Frankl Enstitüsü Viyana, logoterapiye genel bakış)",url:"https://www.viktorfrankl.org/logotherapy.html",type:"technique",finding:"Viktor Frankl Enstitüsü, logoterapi ve varoluşsal analizi, Frankl’ın 1930’lardan itibaren geliştirdiği, anlam merkezli bir psikoterapi yaklaşımı olarak tanımlıyor. Üç varsayıma dayanıyor: irade özgürlüğü (insanlar, hastalıkta ya da zorlukta bile koşullarına karşı takınacakları tavrı seçebilir), anlam iradesi (anlam aramak temel bir insan güdüsüdür ve engellendiğinde insanlar içsel bir boşluk hissedebilir) ve hayatın anlamı (anlam her kişiye ve duruma özgüdür, dayatılmaz, keşfedilir). Frankl kitabında üç temel anlam kaynağı anlatıyor: bir eser yaratmak ya da bir iş yapmak, bir şeyi deneyimlemek ya da birini sevmek ve kaçınamayacağın acıya karşı takındığın tavır.",limitation:"Enstitünün sayfası okundu. Üç anlam kaynağı, Frankl’ın kitabının yaygın özetlerinden alındı; bu bilgiler ayrıca bir sayfa açılarak yeniden doğrulanmadı. Logoterapi, birçok başka terapiye göre daha küçük bir araştırma birikimi olan klinik bir yaklaşımdır; bu kurstaki düşünme çalışmaları kendi kendine uygulamadır, logoterapi değil."},{id:"meaning-act-values",title:"Association for Contextual Behavioral Science · The six core processes of ACT (values and committed action) (ACT’nin altı temel süreci: değerler ve kararlı eylem)",url:"https://contextualscience.org/the_six_core_processes_of_act",type:"technique",finding:"Kabul ve Kararlılık Terapisi (ACT), birbirine bağlı altı süreçle psikolojik esnekliği geliştirmeyi amaçlıyor. Değerler, amaçlı davranışlarında hangi nitelikleri seçtiğinle ilgilidir. Bir nesne gibi elde edilmez; her an davranışa dökülebilir. Aile ve iş gibi alanlarda izlediğin yönü gösterir. ACT, değerlerini rahatsızlıktan kaçmak, toplumsal baskıya uymak ya da “Böyle yapmalıyım” diye düşünmek yerine, kendin için seçmene yardım eder. Kararlı eylem, somut ve ulaşılabilir hedefleri bu değerlere bağlamak demektir. Karşına çıkan içsel engellerle çalışarak, değerlerine uygun davranışları hayatında giderek daha geniş bir alana yayarsın.",limitation:"ACT alanındaki meslek derneğinin model açıklaması; bir araştırma değil. Modeli açıklıyor; kendi başına yapılan bir değer egzersizinin ne kadar yardımcı olduğunu göstermiyor. Bu kurstaki pusula resmi, ACT değerlerini öğretmenin yaygın bir yolu, bu sayfadan bir terim değil."},{id:"meaning-carrillo",title:"Carrillo et al. · 2019 · Effects of the Best Possible Self intervention: a systematic review and meta-analysis (PLOS One) (En iyi olası ben müdahalesinin etkileri: sistematik derleme ve meta-analiz)",url:"https://doi.org/10.1371/journal.pone.0222386",type:"research",finding:"2.909 katılımcılı 29 çalışmayı bir araya getiren meta-analiz, En iyi olası ben egzersizinin kontrol koşullarına kıyasla iyimserliği (d = 0,334), olumlu duygulanımı (d = 0,511) ve iyi oluşu (d = 0,325) artırdığını, olumsuz duygulanımı (d = 0,192) ve depresif belirtileri (d = 0,115) azalttığını buldu.",limitation:"Etkiler küçük ile orta arasındaydı ve depresif belirtiler üzerindeki etki küçüktü. Çalışmalar, insanların ne sıklıkla ve ne kadar süre yazdığı bakımından farklıydı ve çoğu kısa vadeli sonuçları ölçtü. Analiz En iyi olası ben egzersizini sınıyor; doğrudan hayattaki anlamı ve bu kursu sınamıyor."},{id:"meaning-best-possible-self",title:"Laura A. King · Best Possible Self writing (2001), as reviewed by Carrillo et al. (2019) (En iyi olası ben yazımı; Carrillo ve arkadaşlarının 2019 derlemesinde ele alındığı şekliyle)",url:"https://doi.org/10.1371/journal.pone.0222386",type:"technique",finding:"En iyi olası ben egzersizinde insanlar, kendileri için önemli olana emek verdikten sonra işlerin gerçekçi olarak olabileceği kadar iyi gittiği bir gelecek hayal eder ve o geleceği birkaç dakika, bazen birkaç seferde yazar. Carrillo ve arkadaşları bu egzersizle ilgili 29 çalışmayı bir araya getirdi.",limitation:"King’in özgün 2001 makalesi açılmadı; uygulama adımları, derlenen çalışmalarda yaygın kullanıldığı şekliyle anlatılıyor. Oturum süresi ve sayısı çalışmalar arasında değişiyor. Egzersizi kişisel değerlere bağlamak bu kursun kendi eklemesidir."},{id:"motivation-sdt",title:"Center for Self-Determination Theory · The theory (Öz-belirleme kuramı merkezi · Kuram)",url:"https://selfdeterminationtheory.org/theory/",type:"guidance",finding:"Edward Deci ve Richard Ryan’ın geliştirdiği öz-belirleme kuramı, üç temel psikolojik ihtiyaç öne sürüyor: özerklik (seçme duygusuyla hareket etmek), yeterlik (kendini yetkin hissetmek) ve ilişkililik (başkalarıyla bağ). Bu ihtiyaçları destekleyen koşulların en istekli, en kaliteli motivasyonu beslediği savunuluyor; özerk motivasyon ilgiden ve değerlerden, kontrollü motivasyon ise ödüllerden, baskıdan ya da başkalarının beklentilerinden gelir.",limitation:"Kuramın kendi araştırma merkezinin genel bakış sayfası. Kuramı açıklıyor; tek başına herhangi bir egzersizin ne kadar yardımcı olduğunu göstermiyor."},{id:"motivation-sdt-meta",title:"Ntoumanis et al. · 2021 · Meta-analysis of self-determination theory-based health interventions (Öz-belirleme kuramına dayalı sağlık müdahalelerinin meta-analizi)",url:"https://eprints.whiterose.ac.uk/id/eprint/155741/",type:"research",finding:"Sağlık alanından 73 müdahale çalışması bir araya getirildi. Öz-belirleme kuramına dayanan müdahaleler, kuramın özerk motivasyon gibi ölçümlerinin çoğunda küçük ile orta arası değişimler ve fiziksel ile psikolojik sağlıkta küçük olumlu değişimler üretti; özerk motivasyondaki ve ihtiyaç desteğindeki kazanımlar sağlık davranışındaki olumlu değişimlerle ilişkiliydi.",limitation:"Sağlık üzerindeki etkiler küçüktü ve çalışmalar arasında çok değişti. Çalışmalar tüm yaşam hedefleri hakkında değil, sağlık davranışları hakkındaydı. Yalnızca özet okundu."},{id:"faith-kindness",title:"Curry et al. · 2018 · Meta-analysis of acts of kindness and the well-being of the giver (İyilik eylemleri ve yapanın iyi oluşu üzerine meta-analiz)",url:"https://ora.ox.ac.uk/objects/uuid:4701365b-5760-4ece-a390-857a5f7b3c0c",type:"research",finding:"4.045 katılımcılı 27 çalışma: iyilik eylemleri yapmanın, onu yapan kişinin iyi oluşu üzerinde küçük ile orta arası bir etkisi vardı (δ = 0,28). Etki cinsiyete, yaşa, katılımcı türüne ya da müdahale türüne bağlı değildi ve yayın yanlılığına dair bir işaret yoktu.",limitation:"İyi oluşa dair kısa vadeli psikolojik çalışmalar; dinî bir karşılık hakkında bir şey söylemiyor ve bu kursu sınamıyor. Yalnızca özet okundu."}],We={id:"meaning",title:"Anlam ve değerler",subtitle:"Senin için neyin önemli olduğunu bul, sonra bugün ona doğru küçük bir adım at",description:"Anlam, bir kez bulduğun büyük bir cevap yerine her gün yeniden seçtiğin bir yön olabilir mi? Bu kurs, Viktor Frankl’ın anlam üzerine fikirlerini ve Kabul ve Kararlılık Terapisi’nin değerler çalışmasını bir araya getiriyor. Bunları küçük günlük kararlara dönüştürmene yardım ediyor.",scope:"Yoğun bir hayat yaşadığı hâlde nereye gittiğini bilemeyen, bir yol ayrımında olan ya da günlerini önem verdiği şeylere ayırmak isteyen yetişkinler için. Eğitim ve kendin üzerine düşünme içeriğidir; tanı, terapi veya tedavi sunmaz. Zaman zaman hayatın anlamından emin olamamak doğaldır. Ama hayat haftalardır boş ya da anlamsız geliyorsa bir doktora ya da ruh sağlığı uzmanına başvur. Kendine zarar verme düşüncelerin varsa hemen 112’yi ara.",outcome:"Hayatında anlam bulduğun yerlerin bir haritası ve kendi sözlerinle yazılmış kısa bir değer listesi. Hangi değerlerin gerçekten sana ait olduğunu değerlendirme ve değiştiremeyeceğin zorluklarla yüzleşme yolları. En iyi olası geleceğini anlatan bir yazı ve her gün değerlerine uygun verebileceğin küçük bir karar.",photo:{id:"1500530855697-b586d89ba3ee",alt:"Açık tepelerin arasından ufka doğru kıvrılan bir yol"},lessons:[{id:"meaning-1",title:"Anlam nereden gelir",minutes:8,goal:"Frankl’ın üç temel anlam kaynağını öğren ve her birinin hayatında zaten nerede göründüğünü fark et.",reading:["Viktor Frankl, Viyanalı bir psikiyatristti. Anlamı merkeze alan logoterapi yaklaşımını geliştirdi. En bilinen kitabını, Nazi toplama kamplarında tutsak geçirdiği yıllardan yola çıkarak yazdı. Ona göre anlam aramak temel bir insan ihtiyacıydı. Yalnızca diğer sorunlarını çözmüş insanlara özgü bir lüks değildi. Bu arayış uzun süre engellendiğinde insanın içsel bir boşluk hissedebileceğini savundu. Frankl, kimsenin sana hayatının anlamını veremeyeceğini düşünüyordu. Ona göre anlam, sana ve içinde bulunduğun duruma özgüdür. İcat edilmez, keşfedilir.","Frankl, üç temel anlam kaynağı tarif etti. Birincisi yaratmak ya da yapmak: işin, bir proje ya da bir iyilik yoluyla dünyaya katkıda bulunmak. İkincisi deneyimlemek ya da sevmek: güzellikle, doğayla, hakikatle ve özellikle başka bir insanla bağ kurmak. O insanı tanımak ve olduğu gibi sevmek. Üçüncüsü, kaçınamayacağın acı karşısında nasıl bir tavır aldığın. Çoğu insan farklı zamanlarda bu üç alanda da anlam bulur. Genel olarak hayatın anlamını sormak yerine daha yakın bir soru sorabilirsin: Bu an, bu ilişki ya da bu iş benden ne istiyor?"],deeper:[{heading:"Büyük bir cevap değil, bir yanıt olarak anlam",paragraphs:["Birçok insan, hayatının değerli olduğunu hissedebilmek için büyük bir amaç bulmayı bekler. Frankl soruyu tersine çevirdi. Hayatın sana ne borçlu olduğunu sormak yerine, burada ve bugün senden ne istediğini sorabilirsin. Böyle bakınca anlam daha yakında görünür: katılacağın bir konuşmada, özenle yapacağın bir işte ya da ilgileneceğin bir insanda.","Viktor Frankl Enstitüsü bunu irade özgürlüğü olarak anlatıyor: koşullar sabit olsa bile, nasıl yanıt vereceğin konusunda bir miktar özgürlüğün kalır. Bu özgürlük zor şeyleri kolaylaştırmaz. Ama nasıl davranmak istediğini seçebileceğin bir alan bırakır."],visual:{kind:"compare",title:"Anlamı sormanın iki yolu",left:{label:"Büyük bir cevabı beklemek",items:["Hayatımın anlamı ne?","Her şey yoluna girince hissedeceğim.","Anlam başka bir yerde."]},right:{label:"Bu ana yanıt vermek",items:["Bu an benden ne istiyor?","Bugün önemli olan şey için harekete geçebilirim.","Anlam çoğu zaman yakınlarda."]},note:"Viktor Frankl’ın önerdiği bakış değişikliğini kendi örneklerimizle anlattık."}},{heading:"Araştırma ne diyor, neyi demiyor",paragraphs:["Logoterapi, birçok başka terapiden daha küçük bir araştırma birikimi olan klinik bir yaklaşımdır; bu yüzden bu kurs Frankl’ın fikirlerini kanıtlanmış bir tedavi olarak değil, yararlı bir düşünme biçimi olarak ele alıyor. Yine de fikirlerinin bazı yönleri araştırmayla bağlantılı. 4.045 kişilik 27 çalışmanın meta-analizi, iyilik eylemleri yapmanın, onu yapan kişinin iyi oluşu üzerinde küçük ile orta arası olumlu bir etkisi olduğunu buldu.","Bu, birinci anlam kaynağının, yani başkası için bir şey yapmanın küçük, ölçülebilir bir örneği. Frankl’ın her konuda haklı olduğunu kanıtlamıyor ve kendini iyi işlere zorlaman için bir neden değil. Anlamın çoğu zaman günlük eylemlerde bulunduğuna dair bir ipucu."]}],example:{title:"Tomás, 41, depo amiri",text:"Tomás hayatının yalnızca iş, uyku ve faturalardan ibaret olduğunu hissetmeye başlamıştı. Bir pazar akşamı bir zarfın arkasına üç sütun çizdi: yapmak, deneyimlemek, yüzleşmek. “Yapmak” sütununa o ay işe yeni başlayan iki kişiyi eğittiğini ve ikisinin de artık kendine güvendiğini yazdı. “Deneyimlemek” sütununa kızıyla cumartesi yürüyüşlerini ve işe giderken yolundaki fırının kokusunu yazdı. “Yüzleşmek” sütununa babasının hastalığını yazdı; onu düzeltemezdi ama ziyaret etmeyi sürdürebilirdi. Hayatında hiçbir şey değişmemişti. Ama pazartesi, en yeni çalışan bir soru sorduğunda daha fazla dikkat ettiğini fark etti, çünkü artık işin o kısmının onun için önemli olduğunu biliyordu."},practice:["Yapmak, deneyimlemek ve yüzleşmek başlıklı üç sütun çiz ve geçen aydan her birinin altına en az bir şey yaz.","Yazdıklarından seni en çok şaşırtanı daire içine al. Hangisinin sana anlam vereceğini beklemiyordun?","Bugün, kendine bu anın senden ne istediğini soracağın bir an seç ve ne zaman olacağını yaz."],reflection:"Üç anlam kaynağından hangisini kendi hayatında gözden kaçırmaya yatkınsın?",question:"Hangi seçenek Frankl’ın üç temel anlam kaynağını anlatıyor?",options:["Para, statü ve takdir.","Yaratmak ya da yapmak, deneyimlemek ya da sevmek ve kaçınılmaz acıya karşı tavır.","Pozitif düşünme, görselleştirme ve olumlamalar."],correct:1,feedback:"Frankl, verdiğin şeye (iş ve eylemler), aldığın şeye (deneyimler ve sevgi) ve kaçınamayacağın acıya karşı takındığın tavra işaret etti.",takeaway:"Anlam tek bir cevaptan çok, her günün senden istediğine verilen bir yanıttır.",sources:["meaning-frankl","faith-kindness"],visual:{kind:"table",title:"Üç anlam kaynağı",columns:["Kaynak","Ne içerir","Gündelik bir örnek"],rows:[["Yaratmak ya da yapmak","İş, proje ya da eylem yoluyla bir şey vermek","Yeni bir iş arkadaşının ayak uydurmasına yardım etmek"],["Deneyimlemek ya da sevmek","Güzellik, hakikat, doğa ya da başka bir insanla bağ kurmak","Sevdiğin biriyle ağır ağır yürümek"],["Tavır","Kaçınamayacağın acıya karşı takındığın duruş","Hastalık boyunca onurunu ve nezaketini korumak"]],note:"Kaynaklar Viktor Frankl’dan; örnekler bize ait."},technique:{name:"Üç anlam kaynağı taraması",origin:"Viktor E. Frankl · Man’s Search for Meaning (1946) (İnsanın Anlam Arayışı)",steps:["Kâğıt ve kalemle on dakikalık sakin bir zaman ayır.","“Yapmak” başlığının altına yakın zamanda yarattığın, verdiğin ya da başardığın şeyleri, ne kadar küçük olursa olsun, listele.","“Deneyimlemek” başlığının altına güzellik, yakınlık ya da sevgi hissettiğin anları listele.","“Yüzleşmek” başlığının altına değiştiremeyeceğin bir zorluğu ve onu nasıl taşımayı seçtiğini listele.","Listeleri yeniden oku. Bu hafta hangi alana biraz daha yer ayırmak istediğini sor."],evidence:"Bu tarama, Frankl’ın üç anlam kaynağı üzerine düşünmenin bize ait yapılandırılmış bir yolu; bir egzersiz olarak sınanmadı. Frankl’ın fikirleri kontrollü çalışmalardan çok klinik deneyimden ve felsefeden geliyor.",sourceId:"meaning-frankl"},photo:{id:"1469474968028-56623f02e42e",alt:"Sisli bir vadinin üzerinde kayanın üstünde yalnız bir kişi"}},{id:"meaning-2",title:"Değerler bir yöndür, bitiş çizgisi değil",minutes:9,goal:"Değerlerle hedefler arasındaki farkı anla ve kendi sözcüklerinle birkaç değer yaz.",reading:["Kabul ve Kararlılık Terapisi, kısaca ACT, değerlere önem veren çağdaş bir psikolojik yaklaşımdır. ACT’de değerler, nasıl davranmak istediğini seçmenle ilgilidir: şefkatli, meraklı, dürüst ya da cesur olmak. Hedefler ise farklıdır. Bir yarışı koşmak, iş bulmak ya da kredi borcunu kapatmak gibi bir hedefi tamamlayabilirsin. Değerler tamamlanmaz. Şefkatli olmanın bir son noktası yoktur. Her an yeniden şefkatli davranmayı seçebilirsin.","Bunu bir pusula gibi düşünebilirsin. Batıya doğru yıllarca yürüyebilirsin ama “Batı” adlı bir son noktaya varmazsın. Yol boyunca ulaştığın yerler ise hedeflerindir. Değerler yönünü gösterir, hedefler yol üzerindeki durakları belirler. Hedefe ulaştığında bazen tuhaf bir boşluk hissedersin. Ulaşamadığında da kaybolmuş hissedebilirsin. Değerlerin her iki durumda da sana yön gösterir ve sonraki adımını bulmana yardım eder."],deeper:[{heading:"Hayatın farklı alanlarında değerler",paragraphs:["ACT’de değerler, aile, iş, arkadaşlık, sağlık ve toplum gibi hayatın farklı alanlarında izlediğin yönlerdir. Bu alanları tek tek düşünmek yardımcı olabilir. İşte en çok önemsediğin değerle evde önemsediğin değer aynı olmayabilir.","Sözcükleri kısa ve eylem odaklı tut. “Çocuğuna zaman ve dikkat ayıran bir ebeveyn olmak”, “aile”den daha kolay eyleme dökülür. Bir değer, yalnızca başkalarını etkilemek için söyleyeceğin bir şeye benziyorsa şimdilik bir kenara bırak."],visual:{kind:"table",title:"Aynı alan, değer ve hedef olarak görülünce",columns:["Hayat alanı","Bir değer (bir yön)","Bir hedef (bir varış noktası)"],rows:[["Aile","Sevecen olmak ve birlikte zaman geçirmek","Bu hafta üç akşam birlikte yemek yemek"],["İş","Özenli, yararlı iş yapmak","Raporu cumaya kadar bitirmek"],["Sağlık","Bedenime iyi bakmak","Öğle yemeğinden sonra 20 dakika yürümek"],["Arkadaşlık","Sadık olmak ve iletişimde kalmak","Bu hafta sonu Sam’i aramak"]],note:"ACT’de anlatılan değer ve hedef ayrımına dair kendi örneklerimiz."}},{heading:"Sık yapılan hatalar",paragraphs:["Birinci hata, duyguları değer olarak yazmaktır; “mutlu olmak” ya da “sakin hissetmek” gibi. Duygular gelip gider ve tamamen senin kontrolünde değildir. Değerler yaptığın şeyle ilgilidir; bu yüzden zor günlerde de onlara göre davranabilirsin.","İkinci hata, değerleri kurallara dönüştürmektir: “Her zaman üretken olmalıyım”. Değer özgürce seçilmiş bir yöndür, kendini cezalandırmak için bir kural değil. Üçüncüsü, bir anda çok fazla değer seçmektir. Sana anlamlı gelen üç dört değer, yirmi maddelik bir listeden daha yararlıdır."]}],example:{title:"Priya, 33, grafik tasarımcı",text:"Priya kendine yıl sonuna kadar kıdemli bir göreve geçme hedefi koymuştu. Terfi başkasına gidince tüm yılın boşa gittiğini hissetti. O akşam pusula egzersizini denedi. “İş” başlığına “insanların kolay ve rahat kullanabildiği şeyler tasarlamak” değerini yazdı. O yılı düşündüğünde bu değere göre davrandığı onlarca an görebildi: kimsenin istemediği erişilebilirlik düzeltmeleri, yol gösterdiği genç tasarımcı. Hedef elinden kaymıştı ama yön hâlâ oradaydı. Ertesi sabah iş ilanlarında gezinmek yerine yirmi dakikasını bu değere uygun bir portfolyo çalışması çizmeye ayırdı."},practice:["Hayatından üç alan seç ve her biri için “şefkatli olmak” veya “özen göstermek” gibi davranışı anlatan kısa bir değer ifadesi yaz.","Her değerin yanına, önümüzdeki ay seni o yöne götürecek bir hedef yaz.","Her değeri kontrol et: kötü bir günde bile ona göre davranabilir misin? Davranamazsan, hissettiğin şey yerine yaptığın bir şey olarak yeniden yaz."],reflection:"Ne yaptığını hiç kimse asla bilmeyecek olsa, hayatının hangi yönde ilerlemesini yine de isterdin?",question:"ACT’ye göre bir değerle bir hedef arasındaki temel fark nedir?",options:["Değerler hedeflerden daha önemlidir, bu yüzden hedeflerini bırakmalısın.","Değerler duygulardır, hedefler eylemlerdir.","Bir hedef tamamlanabilir; bir değer ise her an yeniden davranışa dökebileceğin bir yöndür."],correct:2,feedback:"Hedefler ulaşabileceğin ve işaretleyebileceğin varış noktalarıdır. Değerler tamamlanamayan, yalnızca her anda yaşanabilen seçilmiş yönlerdir. İkisine de ihtiyacın var.",takeaway:"Hedefler yoldaki durakları, değerler gideceğin yönü gösterir.",sources:["meaning-act-values","motivation-sdt"],visual:{kind:"compare",title:"Değerler ve hedefler",left:{label:"Değerler",items:["Seçtiğin bir yön","Asla bitmez","Her an davranışa dökülebilir","Örnek: şefkatli olmak"]},right:{label:"Hedefler",items:["Ulaştığın bir varış noktası","Tamamlanabilir","Gelecekteki bir noktaya aittir","Örnek: pazar günü annemi ziyaret etmek"]},note:"Association for Contextual Behavioral Science’ın anlattığı ayrımın kendi özetimiz."},technique:{name:"Değerler pusulası",origin:"Acceptance and Commitment Therapy · values work, as described by the Association for Contextual Behavioral Science (Kabul ve Kararlılık Terapisi · değerler çalışması)",steps:["Basit bir pusula çiz ve dört ucuna ilişkiler, iş, sağlık ve kişisel gelişim gibi hayat alanlarını yaz.","Her alan için, orada nasıl davranmak istediğini bir sonuç olarak değil, bir nitelik olarak birkaç sözcükle yaz.","Geçen haftaki eylemlerinin her bir değerle ne kadar örtüştüğünü 0’dan 10’a puanla.","En çok önemsediğin ve en büyük açığın olduğu alanı seç.","Bu hafta o yönde atabileceğin küçük bir eylem yaz."],evidence:"Değerleri netleştirmek, tek bir egzersiz değil bir süreçler bütünü olarak tanımlanan ACT’nin temel bir parçasıdır. Bu pusula alıştırması tek başına sınanmadı ve terapi dışında tek başına yapıldığında etkisi bilinmiyor.",sourceId:"meaning-act-values"},photo:{id:"1470071459604-3b5ec3a7fe05",alt:"Yeşil uçurumların ve bir vadinin üzerinde süzülen bulutlar"}},{id:"meaning-3",title:"Bu değerler kimin?",minutes:9,goal:"Gerçekten seçtiğin değerleri baskı, suçluluk ya da korkunun yönlendirdiği değerlerden ayır.",reading:["Bazı değerleri anne babamızdan, yaşadığımız kültürden, işimizden ya da sosyal medyadan alırız. Çoğu zaman bunları zorunluluk gibi duyarız: “Daha büyük bir ev istemeliyim. Daha hırslı olmalıyım.” ACT, değerlerini kendin seçmeni önerir. Rahatsızlıktan kaçmak, başkalarını memnun etmek ya da aklındaki bir “Böyle olmalıyım” düşüncesine uymak için değil. Başkasından öğrendiğin bir değer yanlış olmak zorunda değildir. Zamanla onu kendin de benimseyebilirsin. Kendine soracağın şey şu: Yakından baktığımda bu değeri hâlâ kendi isteğimle seçiyor muyum?","Öz-belirleme kuramı da benzer bir ayrım yapar. Özerk motivasyon ilgiden ve kişisel değerlerden gelir. Kontrollü motivasyon ise ödüllere, baskıya ya da başkalarının beklentilerine dayanır. Kendi isteğinle seçtiğin bir şey için harekete geçmek genellikle daha nitelikli ve sürdürmesi daha kolay bir motivasyon sağlar. Şöyle kontrol edebilirsin: Yaptığını kimsenin görmediğini ve seni övmeyeceğini hayal et. Değerin hâlâ önemliyse, muhtemelen onu benimsemişsindir. Önemi hemen kayboluyorsa, başkasının senin için istediği hayata ait olabilir."],deeper:[{heading:"“Neden”i dürüstçe sormak",paragraphs:["Tony Robbins gibi tanınmış koçlar, insanlara istediklerinin arkasındaki derin nedeni bulmalarını sık sık önerir. Bu fikir işe yarayabilir. Bir şeyi neden istediğini art arda birkaç kez sormak, hedefin altında yatan değeri görmene yardım edebilir.","Bazen bu fikre, doğru nedeni bulmanın seni durdurulamaz yapacağı gibi büyük vaatler eşlik eder. Bunlar sınanmış değil. Daha ölçülü bir açıklama şu olabilir: “Neden?” diye sormak, neyi önemsediğini görmene yardım eder. Planlamanın, dinlenmenin ya da desteğin yerini tutmaz. Yanıtın da yıllar içinde değişebilir."],visual:{kind:"compare",title:"Zorunluluk gibi mi, kendi seçimin gibi mi?",left:{label:"Zorunluluk gibi gelir",items:["Suçluluk ya da korkuyla gelir","Çoğunlukla başkaları görürse önemlidir","Başkasının sesi gibi gelir"]},right:{label:"Kendi seçimin gibi gelir",items:["Kimse izlemezken de önemlidir","Sana enerji verir ya da içine siner","Bugün yine seçerdin"]},note:"ACT’nin özgürce seçilmiş değerler vurgusuna ve öz-belirleme kuramına dayanan kendi kontrol listemiz."}},{heading:"Araştırma ne diyor",paragraphs:["Sağlıkta 73 müdahale çalışmasının bir meta-analizi, öz-belirleme kuramına dayalı programların özerk motivasyonda küçük ile orta arası artışlar ve fiziksel ile psikolojik sağlıkta küçük olumlu değişimler ürettiğini buldu. Özerk motivasyonu artan insanlar sağlık davranışlarını da iyileştirme eğilimindeydi.","Bu çalışmalar genel olarak yaşam değerleri hakkında değil, sağlık alışkanlıkları hakkındaydı ve sağlık etkileri küçüktü. Yine de bu dersin arkasındaki fikirle uyuşuyorlar: kendi benimsediğin nedenlerle harekete geçmek, baskı altında yapmaktan genellikle daha sürdürülebilirdir."]}],example:{title:"Marcus, 26, genç muhasebeci",text:"Marcus “finansal başarı”yı en önemli değerlerinden biri olarak listelemişti. Kimsenin görmediğini hayal edince bu değerin önemi neredeyse anında kayboldu. Aslında hissettiği, para sıkıntısı çekmiş ailesini hayal kırıklığına uğratma korkusuydu. Finansal başarıyı neden istediğini art arda üç kez sordu. Cevaplar “iyi bir maaşım olsun diye”den “ailem kendini güvende hissetsin diye”ye, oradan “insanların güvenebileceği biri olmak”a taşındı. Son ifade içine sindi. İşinde çok çalışmaya devam etti, ama aynı zamanda küçük kardeşine üniversite başvurularında yardım etmek için her hafta onu aramaya başladı. Para harcamasını gerektirmiyordu ve maaş hedefinden çok daha fazla kendisine uygun geliyordu."},practice:["Son derste yazdığın değerleri al ve her birini, onu yaşadığın için kimsenin seni asla görmeyeceğini ya da övmeyeceğini hayal ederek oku.","Her değeri kendi seçimim, zorunluluk ya da emin değilim olarak işaretle ve bunu yaparken bedenindeki hislere dikkat et.","Zorunluluk ya da emin değilim olarak işaretlediğin bir değer için “Bu benim için neden önemli?” sorusunu üç kez sor ve vardığın yeri yaz."],reflection:"Etkilemek istediğin insanlar asla öğrenmese bile hangi değerlerini korurdun?",question:"Öz-belirleme kuramı, kişisel değerlerden gelen motivasyon hakkında ne söylüyor?",options:["Bu bir özerk motivasyon biçimidir ve baskı ya da ödüllerle yönlendirilen motivasyondan daha kaliteli olma eğilimindedir.","Ödüller ve baskıyla yönlendirilen motivasyondan daha zayıftır.","Yalnızca zaten yüksek özsaygısı olan insanlar için önemlidir."],correct:0,feedback:"Öz-belirleme kuramı, ilgiye ve değerlere dayanan özerk motivasyonu; ödüllerin, baskının ya da başkalarının beklentilerinin yönlendirdiği kontrollü motivasyondan ayırır. İlki daha uzun sürme ve daha iyi hissettirme eğilimindedir.",takeaway:"Bir değer, kimse izlemezken de önemliyse senindir.",sources:["meaning-act-values","motivation-sdt","motivation-sdt-meta"],visual:{kind:"steps",title:"Yüzeydeki bir hedeften bir değere",steps:[{label:"Adlandır",text:"Bir terfi ya da yeni bir şehir gibi istediğin bir şeyi yaz."},{label:"Neden diye sor",text:"Bu benim için neden önemli? Yanıtı tek satırda yaz."},{label:"Yine sor",text:"İki kez daha tekrarla, her seferinde bir kat daha derine inerek."},{label:"Kontrol et",text:"Kimse asla bilmese de bu yine önemli olur muydu? Evetse, bir değer bulmuş olabilirsin."}],note:"Yaygın bir “neden” egzersizinin kendi uyarlamamız; ayrı bir teknik olarak sınanmadı."},technique:{name:"Kendi seçimim mi, zorunluluk mu?",origin:"Acceptance and Commitment Therapy · values work, as described by the Association for Contextual Behavioral Science (Kabul ve Kararlılık Terapisi · değerler çalışması)",steps:["Taşıdığın bir değeri kısa, eylem odaklı bir ifadeyle yaz.","Onu suçluluk, utanç ya da korku gibi bir duygudan kaçınmak için mi taşıdığını sor.","Onu esas olarak birini memnun etmek ya da başkalarına iyi görünmek için mi taşıdığını sor.","Onu önemsemekten değil de, ona değer vermen gerektiğini söyleyen bir düşünceden mi aldığını sor.","Yanıtların çoğu hayırsa, değeri koru; çoğu evetse, altındaki değeri ara ya da kendi sözcüklerinle yeniden yaz."],evidence:"Bu sorular, ACT’nin kaçınmanın, toplumsal baskının ya da “-meliyim” düşüncelerinin yönlendirmediği değerleri seçme tanımını izliyor. Kontrolün kendisi tek başına bir egzersiz olarak sınanmadı.",sourceId:"meaning-act-values"},photo:{id:"1447752875215-b2761acb3c5d",alt:"Yeşil bir ormanın içinden geçen tahta bir yaya köprüsü"}},{id:"meaning-4",title:"İşler zorlaştığında anlam",minutes:10,goal:"Değiştiremeyeceğin bir durumla karşılaştığında hâlâ seçebileceğin kısmı nasıl bulacağını öğren.",reading:["Frankl’ın üçüncü anlam kaynağı en zorlayıcı olanıdır: kaçınamayacağın acı karşısında aldığın tavır. Bu fikir kolay yanlış anlaşılabilir. Frankl acının iyi olduğunu ya da onu araman gerektiğini söylemedi. Acıyı ortadan kaldırmak mümkünse, anlamlı olan bunu yapmaktır. İş değiştirmek, zarar gördüğün bir durumdan ayrılmak ya da tıbbi yardım almak gerekebilir. Frankl’ın sözünü ettiği, gerçekten değiştiremeyeceğin şeylerdi: bir kayıp, bir hastalık ya da geçmişte yaşanmış bir olay. Böyle durumlarda bile nasıl davranacağına ilişkin bir miktar özgürlüğün kaldığını savundu.","Bu özgürlük çoğu zaman küçük, somut bir seçimdir. Acı çekerken nazik davranmayı seçebilirsin. Sana kendin olduğunu hissettiren bir rutini sürdürebilirsin. Bir kaybın ardından, hayatındaki insanlara daha fazla özen gösterebilirsin. Bu, iyiymiş gibi davranmak değildir. Yas, öfke ve korkuyu yaşarken de “Nasıl bir tavır almak istiyorum?” diye sorabilirsin. ACT de benzer bir noktaya değinir: zor duygular devam ederken değerlerin davranışlarına yön verebilir."],deeper:[{heading:"Bu fikrin ne olmadığı",paragraphs:["Bu ders, her şeyin bir sebeple yaşandığını ya da her durumda iyi bir yan bulman gerektiğini söylemiyor. Bazı şeyler yalnızca acı verici ve haksızdır. Daha hazır değilken anlam bulmaya çalışmak, özellikle başkasının zorlamasıyla, acının kabul edilmediğini hissettirebilir.","Aynı zamanda yardımın yerini de tutmaz. Tavrını seçmek, pratik adımlarla ve başkalarının desteğiyle birlikte işler; asla onların yerine değil."]},{heading:"Ne zaman daha fazla destek almalısın?",paragraphs:["Zor dönemler hayatın parçasıdır. Birçok insan zamanla, dinlenerek ve çevresindeki insanların desteğiyle bu dönemleri atlatır. Ama birkaç haftadır boşluk, umutsuzluk ya da hayatın anlamsız olduğu hissi sürüyorsa bir doktora ya da ruh sağlığı uzmanına başvur. Gündelik hayatı sürdürmek zorlaşıyorsa da destek al. Bu kurs tedavinin yerini tutmaz.","Kendine zarar verme düşüncelerin olursa hemen 112’yi ya da bir kriz hattını ara. Yardım istemek, anlam bulamadığın için başarısız olduğun anlamına gelmez. Bir insanın yapabileceği en anlamlı şeylerden biridir."],visual:{kind:"steps",title:"Zor bir dönem hafiflemiyorsa",steps:[{label:"Fark et",text:"Boşluk ya da umutsuzluk haftalardır sürüyor mu, ya da büyüyor mu?"},{label:"Birine söyle",text:"Nasıl hissettiğini güvendiğin bir kişiyle paylaş."},{label:"Yardım al",text:"Bir doktorla ya da ruh sağlığı uzmanıyla konuş."},{label:"Krizde",text:"Kendine zarar vermeyi düşünüyorsan hemen 112’yi ara."}],note:"Genel güvenlik rehberliği, tıbbi tavsiye değil."}}],example:{title:"Elena, 52, ilkokul öğretmeni",text:"Elena’nın annesi ilerleyen bunama nedeniyle bir bakım evine yerleşmişti ve ziyaretler Elena’yı bitkin ve gözyaşları içinde bırakıyordu. Gerilemeyi yavaşlatmak için aklına gelen her şeyi denemişti ve hiçbiri işe yaramamıştı. Bir akşam iki liste yazdı: hâlâ değiştirebileceği şeyler ve değiştiremeyeceği şeyler. Hastalık ikinci listeye girdi. Birinciye ziyaretlerini geçirme biçimini yazdı. Annesinin hafızasını sınamak ikisini de üzüyordu. Bunun yerine, birlikte mırıldanmak için eski şarkılar ve annesinin sevdiği bir el kremi getirmeye başladı. Ziyaretler hâlâ hüzünlüydü. Ama Elena ziyaretlerden, olmak istediği evlat gibi davrandığını hissederek ayrılmaya başladı."},practice:["Şu anki bir zorluğu seç ve iki listeye ayır: hâlâ değiştirebileceklerin ve gerçekten değiştiremeyeceklerin.","Birinci liste için pratik bir adım seç ve onu ne zaman atacağına karar ver.","İkinci liste için, onu nasıl taşımak istediğine dair “Yine de şunu yapabilirim:” ile başlayan bir cümle yaz."],reflection:"Değiştiremeyeceğin bir durumda tavrının hangi değeri yansıtmasını isterdin?",question:"Frankl, kaçınılmaz acıda anlam bulmakla neyi kastetti?",options:["Acının sana iyi geldiğini ve aranması gerektiğini.","Acını gizlemen ve iyiymiş gibi davranman gerektiğini.","Bir şey gerçekten değiştirilemediğinde, ona karşı takınacağın tavrı yine de seçebileceğini."],correct:2,feedback:"Frankl, kaçınılabilir acının ortadan kaldırılması gerektiği konusunda netti. Takındığın tavır, değişimin mümkün olmadığı durumda geriye kalan için önemlidir ve yas ve korkuyla birlikte var olabilir.",takeaway:"Değiştirebildiğini değiştir; değiştiremediğini nasıl taşımak istediğini seç.",sources:["meaning-frankl","meaning-act-values"],visual:{kind:"compare",title:"Zor bir durum için iki liste",left:{label:"Değiştirebileceklerim",items:["Yardım ya da bilgi istemek","Ne kadar küçük olursa olsun pratik adımlar","Elimden geliyorsa zararlı olandan ayrılmak"]},right:{label:"Değiştiremeyeceklerim",items:["Kayıp, tanı ya da geçmişteki olay","Başkalarının seçimleri","Ona karşı duruşum hâlâ benim"]},note:"Frankl’ın kaçınılmaz acıya karşı tavır fikrine dayanan kendi çizimimiz."},technique:{name:"Tavır sorusu",origin:"Viktor E. Frankl · Man’s Search for Meaning (1946) (İnsanın Anlam Arayışı)",steps:["Durumu yumuşatmadan tek sade cümleyle anlat.","Onunla ilgili ne hissettiğini yaz ve bu duyguların orada olmasına izin ver.","Bir kısmının hâlâ değişip değişemeyeceğini dürüstçe kontrol et ve önce o kısım için bir adım planla.","Değişemeyen kısım için, onu taşırken nasıl bir insan olmak istediğini sor.","Bugün o yanıta uyan küçük bir eylem seç."],evidence:"Bu sıra, Frankl’ın kaçınılmaz acıya karşı tavır fikrini uygulamanın bize ait bir yolu. Onun klinik ve kişisel deneyiminden geliyor ve bir egzersiz olarak sınanmadı. Yas, travma ya da depresyon için bir tedavi değildir.",sourceId:"meaning-frankl"},photo:{id:"1519681393784-d120267933ba",alt:"Geceleyin karlı dağların üzerinde yıldızlar"}},{id:"meaning-5",title:"Hedeflediğin hayatı gözünde canlandır",minutes:10,goal:"Değerlerinin biçimlendirdiği bir geleceği gözünde canlandırmak için En iyi olası ben egzersizini kullan ve onu ilk adıma dönüştür.",reading:["En iyi olası ben alıştırmasını psikolog Laura King geliştirdi. Kendini gelecekte, senin için önemli olan şeylere emek verdiğin ve işlerin gerçekçi biçimde iyi gittiği bir zamanda hayal edersin. Sonra bu geleceği birkaç dakika boyunca somut ayrıntılarla yazarsın. Amaç geleceği tahmin etmek ya da sadece dileyerek gerçekleştirmek değildir. Değerlerine uygun bir hayatı gözünde canlandırmaktır. Nasıl bir yönde yaşamak istediğini görebildiğinde ilk adımı atmak kolaylaşır.","Bu, pozitif psikolojide daha çok incelenmiş alıştırmalardan biridir. 2019’daki bir meta-analiz, 2.909 katılımcılı 29 çalışmayı bir araya getirdi. Kontrol gruplarına göre alıştırma, iyimserliği, olumlu duyguları ve iyi oluşu artırdı. Olumsuz duyguları ve depresif belirtileri azalttı. Etkiler küçük ile orta düzeydeydi; depresyon üzerindeki etki küçüktü. Bu sonuçlar, kısa bir yazma alıştırmasının geleceğe dair hislerini biraz değiştirebileceğini gösteriyor. O geleceği tek başına gerçekleştirmez. Bu, sonraki adımlarına bağlıdır."],deeper:[{heading:"Hayali bugüne bağlamak",paragraphs:["Gelecek hayalin, bugüne bağlandığında daha yararlı olur. Yazının ardından üç şeyi belirle: hayal ettiğin kişinin hangi değere göre yaşadığı, önüne çıkabilecek başlıca engel ve o engelle karşılaşırsan ne yapacağın.","Bu planlama adımının da araştırma desteği var. 15.907 katılımcılı 21 çalışmanın bir meta-analizi, hedefi, önündeki gerçek engelle birlikte düşünmenin ve bir eğer-öyleyse planı yapmanın, hedeflere ulaşma üzerinde küçük ile orta arası bir ortalama etkisi olduğunu buldu."],visual:{kind:"table",title:"Hayalden plana",columns:["Adım","Soru","Örnek"],rows:[["Hayal","En iyi olası geleceğim neye benziyor?","Küçük, sakin bir tasarım stüdyosu işletiyorum."],["Değer","Hangi değere göre yaşıyorum?","İnsanların kolay ve rahat kullanabildiği şeyler tasarlamak."],["Engel","Hangi düşünce veya duygum bana engel olabilir?","Çalışmamı göstermekten kaçınıyorum."],["Plan","Bu olursa, o zaman ne yapacağım?","Tereddüt edersem, o zaman bir çalışmamı bir kişiye gönderirim."]],note:"En iyi olası ben egzersizini hedef–engel–plan düşüncesiyle birleştiren kendi örneğimiz."}},{heading:"Araştırma ne diyor",paragraphs:["Meta-analizdeki en büyük etki olumlu duygular üzerindeydi, en küçüğü ise depresif belirtiler üzerinde. Çalışmalar, insanların ne sıklıkla ve ne kadar süre yazdığı bakımından farklıydı ve çoğu, yıllar yerine günler ya da haftalar içindeki değişimleri ölçtü.","Sonuçları şöyle özetleyebiliriz: alıştırma, kısa vadede ruh hâlini ve umudu tutarlı biçimde biraz iyileştiriyor. Onu değerlerine ve ilk adıma bağlamak, bu yükselişi eyleme dönüştürmeyi amaçlayan bu kursun kendi eklemesidir."]}],example:{title:"Jonah, 38, hemşire",text:"Jonah yıllardır gece vardiyalarına sıkışıp kaldığını hissediyordu. İzinli bir günde zamanlayıcıyı on beş dakikaya kurdu. Beş yıl sonra, işlerin gerçekçi biçimde olabildiğince iyi gittiği hayatını yazdı. Hayali, şaşırtıcı biçimde parayla ilgili değildi. Yeni hemşirelere sakin ve hazırlıklı şekilde eğitim vermek istiyordu. Yazısını yeniden okuyunca değerini fark etti: “Başkalarının kendine güvenmesine yardım etmek.” Önündeki engel, grup karşısında konuşma korkusuydu. Bir eğer-öyleyse planı yazdı: “Sunum yapma fırsatı çıkarsa, kendimi vazgeçirmeden önce evet diyeceğim.” Ertesi hafta servis toplantısında on dakikalık bir oturumu yönetmeye gönüllü oldu."},practice:["Zamanlayıcıyı 15 dakikaya kur. Birkaç yıl sonra, emeklerinin karşılığını aldığın ve işlerin gerçekçi biçimde olabildiğince iyi gittiği hayatını yaz.","Hayal ettiğin kişinin yansıttığı değerin altını çiz ve yoluna çıkabilecek içsel bir engeli adlandır.","O engel için bir eğer-öyleyse planı ve bu hafta atabileceğin küçük bir adım yaz."],reflection:"Hayal ettiğin geleceğin merkezinde sessizce hangi değer duruyor?",question:"En iyi olası ben egzersizinin 2019 meta-analizi ne buldu?",options:["Hayal edilen geleceğin gerçekleşeceğini garanti ettiğini.","İyimserlik, olumlu duygular ve iyi oluşta küçük ile orta arası iyileşmeleri, depresif belirtiler üzerinde küçük bir etkiyi.","Ölçülen hiçbir şeyde etki olmadığını."],correct:1,feedback:"29 çalışma boyunca egzersiz, olumlu duygularda en büyük, depresif belirtilerde en küçük olmak üzere küçük ile orta arası iyileşmeler üretti. Geleceğin kendisini değil, gelecek hakkında nasıl hissettiğini değiştirir.",takeaway:"Değerlerinin seni nereye götürebileceğini gözünde canlandır, sonra ilk adımı kendi ayaklarınla at.",sources:["meaning-carrillo","meaning-best-possible-self","mcii"],visual:{kind:"bars",title:"En iyi olası ben egzersizi ve kontrol koşulları",bars:[{label:"Olumlu duygular",value:.511,display:"d = 0,511"},{label:"İyimserlik",value:.334,display:"d = 0,334"},{label:"İyi oluş",value:.325,display:"d = 0,325"},{label:"Daha az olumsuz duygu",value:.192,display:"d = 0,192"},{label:"Daha az depresif belirti",value:.115,display:"d = 0,115"}],note:"2.909 katılımcılı 29 çalışmanın meta-analizinden standartlaştırılmış etki büyüklükleri (Carrillo et al., 2019). Çoğunlukla kısa vadeli sonuçlar; bu kursun bir sınaması değil.",sourceId:"meaning-carrillo"},technique:{name:"En iyi olası ben",origin:"Laura A. King · Best Possible Self writing (2001) (En iyi olası ben yazımı)",steps:["Gelecekte bir nokta seç, örneğin beş yıl sonrası.","Emek verdiğin ve senin için önemli olana sadık kaldığın için her şeyin gerçekçi olarak olabileceği kadar iyi gittiğini hayal et.","O geleceği yaklaşık 15 dakika boyunca kesintisiz, somut ayrıntılarla yaz: neredesin, ne yapıyorsun, yanında kim var.","Yazım ya da üslup için endişelenme; yazmaya devam et.","İstersen egzersizi birkaç farklı günde tekrarla ve neyin aynı kaldığına dikkat et."],evidence:"29 çalışmanın bir meta-analizi, iyimserlik, olumlu duygular ve iyi oluşta küçük ile orta arası kısa vadeli iyileşmeler, depresif belirtiler üzerinde ise küçük bir etki buldu. İnsanların ne kadar süre ve ne sıklıkla yazdığı çalışmalar arasında değişti.",sourceId:"meaning-best-possible-self"},photo:{id:"1501785888041-af3ef285b470",alt:"Dağlarla çevrili sakin bir göl"}},{id:"meaning-6",title:"Günde bir değer temelli karar",minutes:8,goal:"Değerlerini her gün küçük, somut bir karara dönüştür ve sürdür.",reading:["Değerler, davranışlarına yansıdığında hayatını değiştirir. ACT buna kararlı eylem der. Atabileceğin adımlarla başlar, değerlerine uygun davranışları giderek hayatının daha geniş bir alanına taşırsın. Adımlar çok küçük olabilir. Şefkat için bir mesaj gönderebilirsin. Merak için beş sayfa okuyabilirsin. Sağlığın için yirmi dakika erken yatabilirsin. Bunları kararlı eyleme dönüştüren, değerlerine uygun oldukları için bilinçli seçmen ve yolundan uzaklaştığında yeniden bu davranışlara dönmendir.","Günde bir karar fikri buna dayanıyor. Her sabah ya da bir önceki gece kendine sor: “Bugün önemsediğim bir değere uygun hangi küçük şeyi yapabilirim?” Sonra ne zaman ve nerede yapacağını belirle. Eğer-öyleyse planları burada yardımcı olur. 94 testi kapsayan bir meta-analiz, ne zaman, nerede ve nasıl harekete geçileceğini önceden belirlemenin hedeflere ulaşmada orta ile büyük düzeyde bir etkisi olduğunu buldu. Bazı günler yapamayabilirsin. Alışkanlık araştırmaları, bir kez aksatmanın süreci bozmadığını düşündürüyor."],deeper:[{heading:"Küçük adımlar neden işe yarar?",paragraphs:["Bir anlık hevesle verdiğin büyük sözleri, ilk zor günde tutmak güç olabilir. Küçük, somut adımlara başlamak ve onları tekrarlamak daha kolaydır. Aynı koşullarda tekrarlanan davranışlar zamanla otomatikleşir. 96 kişiyi 12 hafta izleyen bir çalışmada, bunun süresi kişiden kişiye çok değişti. Yani herkes için geçerli sihirli bir gün sayısı yok.","Basit bir kayıt tutmak da yardımcı olur. 138 çalışmanın bir meta-analizi, ilerlemeni izlemenin, özellikle ilerleme yazıya döküldüğünde, hedeflere ulaşma şansını artırdığını buldu."],visual:{kind:"table",title:"Değerden bugünün kararına",columns:["Değer","Bugünün kararı","Eğer-öyleyse planı"],rows:[["Çocuğuna zaman ve dikkat ayıran bir ebeveyn olmak","Yemekte telefon çekmecede","Yemeğe oturursam, o zaman telefonumu çekmeceye koyarım."],["Bedenime iyi bakmak","15 dakikalık bir yürüyüş","Öğle yemeğini bitirirsem, o zaman sokaklarda kısa bir tur atarım."],["Sadık bir arkadaş olmak","Bir arkadaşa mesaj atmak","Eve giden otobüse binersem, o zaman Ana’ya yazarım."],["Öğrenmek ve gelişmek","Beş sayfa okumak","Yatağa girersem, o zaman ekrana bakmadan önce okurum."]],note:"Değerleri eğer-öyleyse planlarına bağlayan kendi örneklerimiz."}},{heading:"Sık yapılan hatalar",paragraphs:["Birinci hata, aslında kılık değiştirmiş bir hedef olan bir karar seçmektir; “forma gir” gibi. Bugün bitirebileceğin bir şey yap. İkincisi, kaçırılan bir günü değere gerçekten sahip olmadığının kanıtı saymaktır. Değer bir yöndür; her an ona doğru yeniden dönebilirsin.","Üçüncüsü, yalnızca rahat hissettiren kararlar seçmektir. Kararlı eylem bazen, önemli olduğu için, gerginlik ya da şüphe uyandıran bir şey yapmak demektir. Bu duygular devam ederken de adım atabilirsin."]}],example:{title:"Sofia, 45, ofis müdürü",text:"Sofia bu kursu üç değerle bitirmişti: ailesine karşı sıcak olmak, bedenine iyi bakmak ve dürüst iş yapmak. Her gece ertesi gün için bir kararı su ısıtıcısının yanındaki bir yapışkan nota yazdı. Pazartesi “Leo’ya oyununu sor ve dinle” idi. Salı “otobüse binmek yerine istasyona yürü” idi. Çarşamba tamamen unuttu, yine “Benden bir şey olmaz” diye düşündü ve yine de perşembenin notunu yazdı. Ayın sonunda dörtte üçünü yerine getirmişti. Hayatı çarpıcı biçimde farklı görünmüyordu ama değerlerinde tarif ettiği kişiye daha çok benzediğini hissetti."},practice:["Listenden bir değer seç ve bugün bitirebileceğin, onun yönünü gösteren bir karar yaz.","Onu ne zaman ve nerede yapacağını açıkça belirleyerek bir eğer-öyleyse planına dönüştür.","Bu gece yapıp yapmadığını işaretle ve uyumadan önce yarının kararını yaz."],reflection:"Olmak istediğin kişinin yapacağı, bugün yapabileceğin küçük bir şey nedir?",question:"Hangi günlük karar kararlı eylem fikrine en iyi uyuyor?",options:["Pazartesiden itibaren tamamen farklı biri olacağına kendine söz vermek.","Bedenine iyi bakmaya değer verdiğin için bugün öğle yemeğinden sonra 15 dakika yürümek.","Bir şey yapmadan önce motive hissedene kadar beklemek."],correct:1,feedback:"Kararlı eylem, bir değere uygun olduğu için seçilmiş somut, yapılabilir bir adımdır. Büyük bir dönüşüm ya da doğru duyguyu beklemek gerektirmez.",takeaway:"Her gün değerlerine uygun küçük bir karar, zamanla hayatını şekillendirir.",sources:["meaning-act-values","if-then-plans","habits","monitoring"],visual:{kind:"cycle",title:"Günlük değerler döngüsü",center:"Yönün",nodes:[{label:"Değer",text:"Bugün önemsediğin bir değeri seç."},{label:"Karar ver",text:"Küçük bir eylem seç ve onu ne zaman yapacağına karar ver."},{label:"Harekete geç",text:"Şüphe ya da yorgunluk eşlik etse bile yap."},{label:"Fark et",text:"Kendini yargılamadan ne olduğunu kaydet."},{label:"Ayarla",text:"Yarınki adımı daha kolay, daha zor ya da farklı yap."}],note:"ACT’deki kararlı eyleme, eğer-öyleyse planlamaya ve ilerleme izlemeye dayanan kendi döngümüz."},technique:{name:"Kararlı eylem adımı",origin:"Acceptance and Commitment Therapy · committed action, as described by the Association for Contextual Behavioral Science (Kabul ve Kararlılık Terapisi · kararlı eylem)",steps:["Bir değer ve o değere göre davranmak istediğin bir hayat alanı seç.","O değere uygun, bugün ya da bu hafta yapılabilecek küçük, somut bir hedef koy.","Şüphe, can sıkıntısı ya da korku gibi karşına çıkabilecek içsel engelleri belirle.","Bu duygular oradayken, gitmelerini beklemek yerine nasıl davranacağına karar ver.","Adımı at, sonra bir sonrakini seç ve değerlerine uygun davranışları yavaş yavaş hayatına yay."],evidence:"Kararlı eylem, ACT’nin altı temel sürecinden biridir ve planlama kısmı eğer-öyleyse planları gibi iyi incelenmiş araçlardan yararlanır. Bu sadeleştirilmiş sıra tek başına sınanmadı.",sourceId:"meaning-act-values"},photo:{id:"1472214103451-9374bd1c798e",alt:"Yumuşak ışıkta ağaçlı yeşil bir çayır"}}]},Ee=Object.freeze(Object.defineProperty({__proto__:null,COURSE:We,SOURCES:Pe},Symbol.toStringTag,{value:"Module"})),Ke=[{id:"stoic-epictetus-iep",title:"Keith H. Seddon · Epiktetos (Internet Encyclopedia of Philosophy)",url:"https://iep.utm.edu/epictetu/",type:"guidance",finding:"Epiktetos (yaklaşık MS 55–135), Hierapolis’te köle olarak doğdu. Daha sonra özgürlüğüne kavuştu ve Yunanistan’ın Nikopolis kentinde felsefe öğretti. Öğrencisi Arrianos, öğretilerini Söyleşiler ve El Kitabı adlı eserlerde kaydetti. Yazı, onun temel ayrımını açıklar. Görüşlerimiz, niyetlerimiz, isteklerimiz, kaçındıklarımız ve izlenimleri nasıl değerlendirdiğimiz bizim elimizdedir. Beden, mal mülk, itibar, sağlık, statü ve davranışlarımızın sonuçları ise değildir. Epiktetos’a göre insanı rahatsız eden, olaylardan çok olaylar hakkındaki yargılarıdır.",limitation:"Felsefeye giriş niteliğinde bir ansiklopedi yazısıdır, psikolojik araştırma değildir; modern terapiyi ele almaz. Sayfa okundu; antik metinler bu kursta alıntılanmadan özetlendi."},{id:"stoic-seneca-iep",title:"Robert Wagoner · Seneca (Internet Encyclopedia of Philosophy)",url:"https://iep.utm.edu/seneca/",type:"guidance",finding:"Seneca (yaklaşık MÖ 4–MS 65), genç Nero’ya hocalık etmiş, daha sonra onun danışmanlarından biri olmuş Stoacı bir filozoftur. Yazı, Seneca’nın duygu anlayışını açıklar. Öfke gibi duygular değer yargıları içerir. Bir duruma verilen ilk tepki istemsizdir. Ama öfkeye kapılmak, haksızlığa uğradığın yargısını kabul etmeni gerektirir.",limitation:"Araştırma değil, ansiklopedi düzeyinde bir özettir. Seneca’nın akşam değerlendirmesini ya da felaketleri önceden düşünme önerisini anlatmaz; bu kursta o uygulamaların kaynağı Stoic Week el kitabıdır. Sayfa okundu."},{id:"stoic-week-handbook",title:"Stoicism Today (Gill, Ussher, Sellars, LeBon, Evans, Garratt, Robertson) · Stoic Week 2016 El Kitabı (Modern Stoicism)",url:"https://modernstoicism.com/wp-content/uploads/2016/10/Stoic-Week-2016-Handbook-Stoicism-Today.pdf",type:"technique",finding:"El kitabı, günlük Stoacı alıştırmaları antik kaynaklarıyla birlikte öğretir. Epiktetos’un El Kitabı’na dayanan kontrol ayrımında, her durum için bunun benim elimde olup olmadığını sorarsın. Sabah meditasyonunda günün olası zorluklarını düşünür, iyi karşılıklar planlarsın. Zorlukları önceden düşünme çalışması gerçekçi, katlanabileceğin yoğunlukta olmalı; aynı düşünceleri tekrar tekrar döndürmeye dönüşmemelidir. Seneca ve Epiktetos’a dayanan beş ile on dakikalık akşam değerlendirmesinde neyi kötü yaptığını, neyi iyi yaptığını ve neyi farklı yapabileceğini sorarsın. Bunu sert bir yargıç değil, bir dost gibi yaparsın. Kitapta Marcus Aurelius’un yukarıdan bakış uygulaması da yer alır. Kitap, Stoacılığın duyguları bastırmak olduğu düşüncesini reddeder. Stoacı psikolojiyi modern bilişsel davranışçı terapiyi etkilemiş bir kaynak olarak tanımlar.",limitation:"Filozoflar, klasik metin uzmanları ve terapistler tarafından yazılmış bir uygulama rehberidir. Deneysel bir çalışma değildir. Tıbbi tavsiye ya da tedavinin yerini tutmadığını belirtir. Kursun klinik depresyon ya da travma sonrası stres bozukluğu (TSSB) gibi ağır ruh sağlığı sorunları yaşayan kişilere uygun olmadığını da söyler. PDF okundu."},{id:"stoic-week-report",title:"Tim LeBon · Stoic Week 2021 Raporu (Modern Stoicism)",url:"https://modernstoicism.com/wp-content/uploads/2022/01/Stoic-Week-2021-Results-Tim-LeBon-1-1.pdf",type:"research",finding:"Ücretsiz yedi günlük çevrim içi kursun başında 1.369 kişi, sonunda 459 kişi geçerli anket doldurdu. Tamamlama oranı %33’tü. Katılımcılar kursa günde ortalama 42 dakika ayırdı. Bitirenlerde psikolojik iyi oluş %11,5, yaşam doyumu %14,5 ve olumlu duygular %13 arttı. Olumsuz duygular %21 azaldı.",limitation:"Kursu düzenleyenlerin hazırladığı bir rapordur. Katılımcılar kendi istekleriyle katıldı ve kontrol grubu yoktu. Ölçümlerin tamamı kişilerin kendi bildirimlerine dayanıyordu. Başlayanların üçte ikisi son anketi doldurmadı. Bu nedenle değişimlerin Stoacı uygulamadan kaynaklandığını gösteremez. PDF okundu."},{id:"stoic-kross-distancing",title:"Kross & Ayduk · 2017 · Kendine dışarıdan bakmak: kuram, araştırma ve güncel yönelimler (Advances in Experimental Social Psychology, cilt 55)",url:"https://sites.lsa.umich.edu/emotion-selfcontrol-psych/wp-content/uploads/sites/1322/2017/09/Self-distancing-theory-research-future.pdf",type:"research",finding:"Derleme, bir olayı kendi gözlerinden yeniden yaşamakla kendini dışarıdan izleyerek düşünmeyi karşılaştıran deneyleri özetler. Dışarıdan bakmak, olumsuz duyguları ve aynı düşüncelere tekrar tekrar takılmayı azalttı. İnsanlar ayrıntıları yeniden anlatmak yerine olayı anlamlandırmaya yöneldi. Kan basıncı daha hızlı normale döndü, saldırgan tepkiler azaldı ve daha sağduyulu düşünme desteklendi. Faydalar, dikkat dağıtmanın faydalarına göre zaman içinde daha iyi korundu. On yıl sonra nasıl hissedeceğini düşünmek de sıkıntıyı azalttı. Bunun, duyguların geçici olduğunu hatırlatmaktan kaynaklandığı düşünülüyor. Kendine kendi adınla ya da sen diye seslenmek benzer faydalar sağladı. Yazarlar bu fikri kısmen Aaron Beck’in bilişsel terapideki mesafe alma kavramına dayandırır.",limitation:"Çoğu, sıklıkla öğrencilerle yapılan kısa laboratuvar çalışmalarıdır. Faydalar yoğun sıkıntı yaşayanlarda daha belirgindi. Sıkıntısı az olan bazı gruplarda etki küçük ya da yoktu. Yazarlar, duyguyu anlamak için mesafe almakla ondan kaçınmak için mesafe almayı ayırır. Bölümün PDF’si okundu."},{id:"stoic-kross-self-talk",title:"Kross ve ark. · 2014 · Bir düzenleme mekanizması olarak kendi kendine konuşma: nasıl yaptığın önemli (Journal of Personality and Social Psychology)",url:"https://doi.org/10.1037/a0035173",type:"research",finding:"585 katılımcıyla yapılan yedi çalışmada, kendini düşünürken ben yerine kendi adını ve birinci şahıs dışındaki zamirleri kullanmak, kendine dışarıdan bakmayı kolaylaştırdı. Bu grup ilk izlenim ve topluluk önünde konuşma görevlerinde daha iyi performans gösterdi. Daha az sıkıntı duydu, sonrasında aynı düşüncelere daha az takıldı. Gelecekteki stres kaynaklarını tehditten çok üstesinden gelinebilecek zorluklar olarak gördü. Çalışmaları birleştiren bir meta-analiz, bu faydaların sosyal kaygı düzeyine bağlı olmadığını buldu.",limitation:"Kısa laboratuvar görevleridir; uzun vadeli ve klinik etkiler sınanmadı. Yalnızca özet okundu (Europe PMC üzerinden)."}],Me={id:"stoic",title:"Stoacı dinginlik",subtitle:"Enerjini işe yarayacağı yere yöneltmek için eski öğretilerden alıştırmalar",description:"Enerjini gerçekten elinde olan şeylere harcasan neler değişirdi? Bu kurs beş Stoacı uygulamayı kısa günlük alıştırmalara dönüştürüyor. Her birini modern psikolojinin bulgularıyla karşılaştırıyor.",scope:"Stres, aksilik ve belirsizlik karşısında daha dengeli tepki vermek isteyen yetişkinler için. Burada Stoacılık, duyguları bastırmak ya da güçlü görünmeye çalışmak değildir. Duygularına yer vardır; alıştırmalar, ardından ne yapacağını ele alır. Kurs eğitim ve kişisel çalışma içindir. Terapi değildir, tedavinin yerini tutmaz. Kaygı, depresyon, travma ya da zihnine istemeden gelen endişeler yaşıyorsan bazı alıştırmalar sana uygun olmayabilir. Özellikle aksilikleri hayal etme çalışması için bu alanda yetkin bir uzmandan destek al. Kriz içindeysen ya da kendine zarar vermeyi düşünüyorsan hemen 112’yi ara.",outcome:"Kaygılandığında elinde olanı ayırabilmek, olayla tepkin arasındaki yargıyı fark etmek, olası aksiliklere kendini zorlamadan hazırlanmak, gergin anlara biraz uzaktan bakmak, günü beş dakikalık bir değerlendirmeyle kapatmak ve bugün uygulayacağın küçük bir karar vermek.",photo:{id:"1439066615861-d1af74d74000",alt:"Dingin bir dağ gölünde ahşap bir iskele"},lessons:[{id:"stoic-1",title:"Senin elinde olan",minutes:8,goal:"Şu anki bir kaygını elinde olan ve olmayan diye ayır. Enerjini elinde olanlara yönelt.",reading:["Epiktetos birinci yüzyılda köle olarak doğdu. Daha sonra Yunanistan’da felsefe öğretti. Öğrencisi Arrianos, derslerini Söyleşiler ve kısa bir El Kitabı adlı iki eserde kaydetti. El Kitabı’nın ilk düşüncesi basittir ama uygulaması emek ister. Bazı şeyler bizim elimizdedir: Yargılarımız, niyetlerimiz, istediklerimiz, kaçındıklarımız ve nasıl davranmayı seçtiğimiz. Bazı şeyler ise değildir: Bedenimiz, mal mülkümüz, itibarımız, başkaları ve davranışlarımızın sonuçları. Epiktetos’a göre sıkıntımızın büyük kısmı, ikinci listedekileri de elindeymiş gibi ele almaktan doğar.","Bu düşünce, hiçbir şeyi önemsememek anlamına gelmez. Bir iş görüşmesini çok önemseyebilirsin. Ama iş teklifinin gelip gelmeyeceği senin elinde değildir. Hazırlığın, görüşmedeki dürüstlüğün ve sonrasında iletişimi takip etmen ise elindedir. Yalnızca teklifi düşünüp kaygılanmak seni bir yere götürmez. Hazırlığa yöneldiğinde kaygını işe yarar bir çabaya dönüştürebilirsin. Modern Stoacı öğretmenler bunu en temel alıştırma sayar: Her durumda bunun benim elimde olup olmadığını sor, çabanı elinde olanlara yönelt. Diğerlerini daha az sıkı tut. Onlar da önemlidir ama üzerlerine daha çok düşünmek kontrolünü artırmaz."],deeper:[{heading:"Neden işe yarıyor",paragraphs:["Kaygı çoğu zaman sonuçların etrafında döner: Beni beğenecekler mi? İşe yarayacak mı? Olacak mı? Sonuçlar, göremediğin ya da yönlendiremediğin pek çok şeye bağlıdır. Bu yüzden onları düşünmek çoğu zaman bir sonuca ulaşmaz. Yapacakların ise farklıdır. Bir eylemin ilk adımı, zamanı ve yeri vardır. Onu düşünmek, harekete geçmekle sonuçlanabilir.","Elinde olanı ayırmak rahatsız edici duyguyu ortadan kaldırmaz. Ama o duyguyu bir işe yönlendirir. Bu düşünce, eski alıştırmayı kursun son dersinde ele alacağımız modern planlama araştırmalarıyla birleştirir."],visual:{kind:"steps",title:"Elinde olanı ayır",steps:[{label:"Adını koy",text:"Kaygını tek ve sade bir cümleyle yaz."},{label:"Ayır",text:"İki sütun çiz: Elimde olanlar ve elimde olmayanlar."},{label:"İlk sütunu kontrol et",text:"İlk sütunda yalnızca kendi yargıların, niyetlerin ve davranışların kalsın. Sonuçları diğer sütuna taşı."},{label:"Seç",text:"İlk sütundan bugün uygulayacağın bir madde seç."},{label:"Bırak",text:"İkinci sütun için üzerine düşeni yaptığını not et."}],note:"Stoic Week el kitabındaki kontrol ayrımını kendi sözlerimizle adım adım anlattık."}},{heading:"Sık yapılan hatalar",paragraphs:["İlk hata, sonuçları birinci sütuna koymaktır. İşe alınmak, sevilmek ya da hastalıktan iyileşmek: Bunları etkileyebilirsin ama tek başına belirleyemezsin. Elinde olan, çaban, tutumun ve sonraki adımındır. Alıştırmanın amacı bu ayrımı korumaktır.","İkinci hata, bu düşünceyi hiçbir şey yapmamak için bahane etmektir. Haksızlık olduğunda nasıl karşılık vereceğin senin elindedir. İtiraz edebilir, yardım isteyebilir ya da ortamdan ayrılabilirsin. Kontrol ayrımı, elinden geleni iyi yapmanı ister."]}],example:{title:"Leyla, 31, hemşire",text:"Leyla’nın cuma günü performans değerlendirmesi vardı. Çarşamba akşamını, yöneticisinin söyleyebileceği şeyleri zihninde tekrar ederek geçirdi. Saat onda bir kâğıdı çizgiyle ikiye ayırdı. Sağa elinde olmayanları yazdı: Yöneticisinin ruh hâli, zam bütçesi ve bir meslektaşının kötü geçen vardiyayı nasıl anlattığı. Sola elinde olanları yazdı: Sakladığı hasta geri bildirimlerini götürmek, sonraki eğitim adımı hakkında net bir soru sormak, zor vardiyayı savunmaya geçmeden sakince anlatmak. Kâğıdı çantasına koyup yattı. Kaygısı bitmedi ama artık önünde üç somut iş vardı. Cuma günkü değerlendirmede hem iyi hem kötü noktalar konuşuldu. Leyla, üzerine düşeni yaptığını bilerek çıktı."},practice:["Bu hafta aklından çıkmayan bir kaygıyı tek cümleyle yaz.","İki sütun çiz: Elinde olanlar ve olmayanlar. Sol sütuna yazdığın sonuçları sağa taşı.","Sol sütundan bir maddeyi daire içine al ve bugün ne zaman harekete geçeceğine karar ver."],reflection:"Elinde olmayan hangi şeye enerji harcıyorsun?",question:"Epiktetos’un ayrımına göre bunlardan hangisi senin elinde?",options:["Başvurunun kabul edilip edilmeyeceği.","Başvurunu ne kadar özenle hazırladığın.","Başkalarının başvurun hakkında ne düşündüğü."],correct:1,feedback:"Başvurunu hazırlamak kendi davranışındır. Kabul edilmen ve başkalarının görüşleri ise senin dışındaki etkenlere de bağlıdır. Çaban bunları etkileyebilir ama tek başına belirleyemez.",takeaway:"Sonucu önemse, elinde olan kısmı için çalış.",sources:["stoic-epictetus-iep","stoic-week-handbook"],visual:{kind:"compare",title:"Senin elinde mi, değil mi?",left:{label:"Senin elinde",items:["Olanlar hakkındaki yargıların","Niyetlerin ve emeğin","Ne söyleyeceğin dahil, nasıl karşılık verdiğin"]},right:{label:"Senin elinde değil",items:["Başkalarının seçimleri ve görüşleri","Sonuçlar, itibar ve statü","Sağlık, mal mülk ve bedeninde olanların büyük kısmı"]},note:"Epiktetos’un El Kitabı’ndan, Internet Encyclopedia of Philosophy ve Stoic Week el kitabında anlatıldığı biçimiyle özetlendi."},technique:{name:"Elinde olanı ayırma",origin:"Epiktetos · El Kitabı (Handbook), Arrianos tarafından kaydedildi (MS 2. yüzyıl başı); Stoic Week El Kitabı’nda (Modern Stoicism, 2016) öğretildiği biçimiyle",steps:["Seni rahatsız eden durumu yaz.","Her bir parçası için sor: bu benim elimde mi?","Elinde olanları sonuç olarak değil, eylem, yargı ya da niyet olarak listele.","Bu eylemlerden birini seç ve ne zaman yapacağına karar ver.","Geri kalanını senin belirleyemeyeceğini hatırla. Dikkatini yapacağın işe döndür."],evidence:"Bu ayrım felsefi bir araçtır, sınanmış bir tedavi değildir. Stoic Week’in bir parçasıdır. Bu kursa kendi isteğiyle katılanlar, kontrol grubu olmayan anketlerde daha iyi hissettiklerini bildirdi. Ancak bu alıştırmayı tek başına sınayan kontrollü bir çalışma yok.",sourceId:"stoic-week-handbook"},photo:{id:"1507525428034-b723cf961d3e",alt:"Berrak suyun kumla buluştuğu dingin bir kıyı"}},{id:"stoic-2",title:"Olayla duygu arasındaki hikâye",minutes:9,goal:"Bir olayla ona dair duygun arasındaki yargıyı fark et.",reading:["Epiktetos’a göre insanları rahatsız eden, olanlardan çok olanlar hakkındaki yargılarıdır. Yanıtsız kalan bir mesaj, yalnızca yanıtsız bir mesajdır. Acı, ona eklediğimiz anlamdan doğar: Beni görmezden geliyorlar. Yanlış bir şey yaptım. Önemli değilim. Stoacılar böyle bir yargıyı kabul etmeden önce durmayı çalışıyordu. Seneca, öfkenin ilk tepkisini istemsiz bir irkilme gibi anlatır. Ona göre asıl öfke, haksızlığa uğradığımızı ve saldırarak karşılık vermenin doğru olduğunu kabul ettiğimizde başlar. İlk irkilme kendiliğinden olur. Sonraki yargıyı kabul edip etmemek ise senin elindedir.","Yaklaşık iki bin yıl sonra psikolog Albert Ellis, benzer bir düşünceye dayanan bir terapi geliştirdi. ABC modelinde tetikleyici olay (A), inançlarımız (B) aracılığıyla duygularımızı ve davranışlarımızı (C) etkiler. Özellikle katı zorunluluklar ve felaket yorumları önemlidir. Bilişsel terapinin diğer kurucusu Aaron Beck, insanların düşüncelerine biraz mesafe almasına yardımcı oldu. Böylece bir düşünceyi gerçek değil, düşünce olarak görebiliyorlardı. Bilişsel terapistlerin de yer aldığı Stoic Week ekibi, Stoacı psikolojinin modern bilişsel davranışçı terapiyi (BDT) etkilediğini belirtir. Amaç duygusuz kalmak değildir. Olay hakkında kendine anlattığını fark etmek, sorgulamak ve gerçeklere daha iyi uyan bir yorum seçmektir."],deeper:[{heading:"Bastırmak değil, incelemek",paragraphs:["Stoacılık çoğu zaman duygularını belli etmemekle özdeşleştirilir: Hiçbir şey hissetme, hiçbir şey gösterme. Antik Stoacılar, yanlış yargılara dayanan ve tutku dedikleri duygulardan kurtulmayı hedefliyordu. Ama Stoic Week el kitabının hatırlattığı gibi, Marcus Aurelius bir öğretmenine hem tutkulardan arınmış hem sevgi dolu olduğu için hayrandı. Stoacı dinginlik, duygusuzluk değildir.","Seneca’nın ayrımı burada yardımcı olur. Korku ya da öfkenin ilk bedensel tepkisi başarısızlık değildir. Bedenin işini yapıyordur. Alıştırma bir sonraki anda başlar: Kendime ne söylüyorum? Bu doğru mu? Duyguyu bastırırsan bu soruyu atlamış olursun. Yargını incelemek ise yanıt bulmanı sağlar."]},{heading:"Araştırma ne söylüyor, ne söylemiyor",paragraphs:["Kısmen bu düşüncelerden gelişen BDT, bir terapi olarak çok sayıda araştırmayla desteklenir. 269 meta-analizi inceleyen bir derlemede güçlü kanıt bulunan alanlar arasında kaygı bozuklukları, öfke sorunları ve genel stres vardı. Bu bulgular, eğitimli bir uzmanla yapılan terapiye aittir. Bir dersi okumanın aynı etkiyi sağlayacağını göstermez.","Stoacılığın kendisi çoğunlukla ücretsiz, yedi günlük çevrim içi Stoic Week kursunda incelendi. 2021’de başlangıç anketini 1.369 kişi, son anketi 459 kişi doldurdu. Bitirenler daha iyi hissettiklerini ve daha az olumsuz duygu yaşadıklarını bildirdi. Ama katılımcılar kendi istekleriyle katılmıştı, kontrol grubu yoktu ve başlayanların üçte ikisi son anketi doldurmamıştı. Ölçümler de kişilerin kendi bildirimlerine dayanıyordu. Rakamlar, bitirenlerin söylediklerini gösterir. Değişime Stoacılığın yol açtığını kanıtlamaz."],visual:{kind:"bars",title:"Stoic Week 2021: bitirenlerin bildirdiği değişimler",bars:[{label:"Psikolojik iyi oluş",value:11.5,display:"+%11,5"},{label:"Yaşam doyumu",value:14.5,display:"+%14,5"},{label:"Olumlu duygular",value:13,display:"+%13"},{label:"Olumsuz duygular (azalma)",value:21,display:"−%21"}],note:"Başlayan 1.369 kişiden 459’u bitirdi. Katılım gönüllüydü, kontrol grubu yoktu. Ölçümler kişilerin kendi bildirimlerine dayanıyordu. Rakamlar Tim LeBon’un Stoic Week 2021 raporundan alınmıştır.",sourceId:"stoic-week-report"}}],example:{title:"Sam, 26, genç tasarımcı",text:"Sam’in yöneticisi, ilk büyük tasarım taslağına tek satırlık bir yanıt verdi: Yarın konuşalım. Öğlene doğru Sam başarısız olduğundan emindi ve özür mesajı hazırlıyordu. ABC modelini hatırlayıp yazdı. A: Görüşmek isteyen kısa bir mesaj. B: Tasarımdan nefret ediyor, bu iş bana göre değil, daha iyisini yapmalıydım. C: Korku ve tasarımla kaygı içinde oynayıp durduğu bir öğleden sonra. Sonra B’yi başka biri yazmış gibi okudu. Mesajda tasarımın kalitesi hakkında hiçbir şey yoktu. Yöneticisi bütün toplantıları kısa mesajlarla ayarlardı. Gerçeklere daha uygun bir düşünce buldu: Konuşmak istiyor. Ne düşündüğünü henüz bilmiyorum. Kaygısı biraz hafifledi. Öğleden sonra tasarım tercihlerini ve nedenlerini yazdı. Ertesi gün yöneticisi iki değişiklik istedi, geri kalanının iyi olduğunu söyledi."},practice:["Bugün yoğun bir duygu yaşadığın bir anı hatırla. Olayı, bir kameranın kaydedebileceği kadar tarafsız sözlerle yaz.","Altına eklediğin yargıyı aynen yaz. Mutlaka, hep ya da yapmalıyım gibi ifadeler varsa onları da koru.","Gerçeklere en az ilk yorumun kadar uyan başka bir yorum yaz. Duygunun az da olsa değişip değişmediğine bak."],reflection:"Olaylara fark etmeden hangi yargıyı ekliyorsun?",question:"Stoacı görüşe göre üzücü bir andaki sıkıntının çoğu nereden gelir?",options:["Değiştirilemeyecek olan olayın kendisinden.","Herhangi bir duygu hissetmekten.","Olayın ne anlama geldiğine dair eklediğimiz yargıdan."],correct:2,feedback:"Epiktetos, sıkıntının kaynağını olaylar hakkındaki yargılarımızda görüyordu. Seneca’ya göre ilk tepki istemsizdi. Alıştırma, ardından hangi düşünceyi kabul ettiğimizi incelemektir.",takeaway:"Olanla hissettiğin arasında, kendine anlattığın bir hikâye var. Onu sorgulayabilirsin.",sources:["stoic-epictetus-iep","stoic-seneca-iep","stoic-week-handbook","optimism-ellis","stoic-kross-distancing","optimism-hofmann","optimism-nhs-cbt","stoic-week-report"],visual:{kind:"cycle",title:"Olay, yargı, duygu, eylem",nodes:[{label:"Olay",text:"Bir şey olur: bir mesaj, bir gecikme, bir yorum."},{label:"Yargı",text:"Bir hüküm eklersin: bu bir felaket, bana saygı göstermeliler."},{label:"Duygu",text:"Duyguyu çoğu zaman olaydan çok, ona verdiğin anlam etkiler."},{label:"Eylem",text:"Duyguna göre davranırsın. Bu da sonrasında olanları etkiler."}],center:"Yargını fark ettiğinde dur",note:"Epiktetos’un görüşünü ve Albert Ellis’in ABC modelini kendi sözlerimizle özetledik."},technique:{name:"Stoacı yaklaşımla ABC kontrolü",origin:"Albert Ellis · Rasyonel duygusal davranış terapisinin ABC modeli (ilk kez 1956’da sunuldu)",steps:["A: Tetikleyici olayı sade sözlerle, yalnızca gerçeklere dayanarak yaz.","B: Eklediğin inancı yaz. Özellikle zorunluluk bildiren ya da durumu felaket gibi gösteren kısmı fark et.","C: duyguyu ve ne yaptığını ya da yapmak istediğini not et.","Sorgula: Bu inanç doğru mu? İşime yarıyor mu? Hangi kısmına farklı bakmak benim elimde?","Kesin bir zorunluluk yerine tercihini anlatan daha esnek bir inanç yaz. Ardından buna uygun bir adım belirle."],evidence:"ABC modeli, rasyonel duygusal davranış terapisinin temel bir parçasıdır. BDT, bir terapi olarak çok sayıda araştırmayla desteklenir. Buradaki kişisel çalışma tek başına sınanmadı. Eğitimli bir uzmanla yapılan terapinin yerini tutmaz.",sourceId:"optimism-ellis"},photo:{id:"1500534314209-a25ddb2bd429",alt:"Alacakaranlıkta sisli tepelerin katmanları"}},{id:"stoic-3",title:"Zor bir güne hazırlan",minutes:9,goal:"Olası bir aksiliği kısa ve gerçekçi biçimde hayal et. Kaygıya kapılmadan nasıl karşılık vereceğini planla.",reading:["Stoacılar, ilk duyduğunda karamsar gelebilecek bir alıştırma yapıyordu: Zorlukları önceden hayal etmek. Sonraki yazarlar buna premeditatio malorum, yani aksilikleri önceden düşünme adını verdi. Romalı imparator Marcus Aurelius, bugün Meditasyonlar olarak bildiğimiz kişisel notlarında bundan söz eder. Güne, zor insanlarla karşılaşabileceğini düşünerek başlar, onlara nasıl davranacağına önceden karar verir. Amaç felaketi çağırmak değildir. Geciken bir tren ya da kaba bir yanıt gibi sıradan aksilikleri hazırlıksız yakalanmadan, bir planla karşılamaktır. Stoic Week el kitabı bunu modern maruz bırakma uygulamasıyla karşılaştırır. Korktuğun bir olasılığı küçük dozlarda ve sakince ele almak, korkuyu azaltabilir.","Bu alıştırma yanlış yapıldığında aynı olumsuz düşüncelere takılıp kalmaya dönüşebilir. En kötü senaryoları tekrar tekrar düşünür, hiçbir plan yapmazsın. Stoic Week el kitabı aradaki farkı açıkça belirtir: Gerçekçi bir aksilik seç. Yoğunluğu başa çıkabileceğin düzeyde tut. Ardından nasıl karşılık vereceğini belirle. Son adım önemlidir. Gabriele Oettingen ve arkadaşlarının zihinsel karşılaştırma araştırmasında, gerçek bir engeli hayal edip ardından bir eğer-öyleyse planı kurmak hedeflere ulaşmada küçük ile orta düzey arasında ortalama etki gösterdi. Stoacı hazırlıkla modern planlama burada buluşur: Zorluğu açıkça gör, ne yapacağını belirle."],deeper:[{heading:"Önceden düşünmek mi, kaygı mı?",paragraphs:["Kaygı da hazırlık da geleceğe bakar ama etkileri farklıdır. Kaygıda aynı sahne tekrar eder, giderek daha canlı olur ve sonunda korku artar. Hazırlıkta ise sahneyi bir kez düşünürsün. Olabilecek her şey yerine, olması muhtemel olanı seçersin. Sonunda uygulayabileceğin bir karşılık belirlersin.","Şöyle kontrol edebilirsin: İki ya da üç dakika sonunda, bu olursa şunu yapacağım, diye bir cümle kurabildin mi? Kurduysan hazırlık yaptın. Hâlâ aynı düşüncelerin etrafında dönüyorsan dur, ayağa kalk ve ellerinle yapacağın bir işe geç. Daha sonra yeniden deneyebilirsin."],visual:{kind:"steps",title:"İki dakikalık bir prova",steps:[{label:"Seç",text:"Bugün ya da bu hafta için gerçekçi tek bir aksilik seç."},{label:"Canlandır",text:"Bir kez, kısaca ve başa çıkabileceğin yoğunlukta hayal et."},{label:"Ayır",text:"Bunun hangi kısımlarının senin elinde olduğunu fark et."},{label:"Planla",text:"Yanıtın için tek bir eğer-öyleyse cümlesi yaz."},{label:"Bitir",text:"Alıştırmayı bitir ve gününe dön."}],note:"Stoic Week el kitabındaki uyarıları eğer-öyleyse planlamasıyla birleştiren özetimiz."}},{heading:"Bu alıştırmayı kimler geçmeli?",paragraphs:["Stoic Week el kitabı, kursun klinik depresyon ve TSSB gibi ağır ruh sağlığı sorunları yaşayan kişilere uygun olmadığını belirtir. Tıbbi tavsiyenin yerini tutmadığını da söyler. Kötü sonuçları hayal etmek paniğe, istemeden gelen görüntülere ya da saatler süren kaygıya yol açıyorsa bu dersin alıştırmasını geç. Bu alanda yetkin bir uzmanla konuş. Kaygı için maruz bırakma kullanan terapistler bu çalışmayı dikkatle ve destek sunarak yürütür."]}],example:{title:"Ana, 38, ilkokul öğretmeni",text:"Ana’nın saat dörtte bir veli görüşmesi vardı. Görüşeceği baba daha önce iki kez e-postayla şikâyet etmişti. Sabah kahvesini içerken iki dakika ayırdı. En kötü ihtimali değil, muhtemel olanı hayal etti: Baba sözünü kesiyor, sesini biraz yükseltiyor ve oğluna haksızlık yapıldığını söylüyor. Ana göğsünün sıkıştığını fark etti; duyguyu bastırmadı. Sonra elinde olanları düşündü: Ses tonu, sunacağı bilgiler ve çocuğun gelişimine odaklanmak. Küçük bir not yazdı: Sözümü keserse duracağım, onu dinlemek istediğimi söyleyeceğim, sonra okuma puanlarına döneceğim. Saat dörtte baba gerçekten sözünü kesti. Ana planladığı gibi durdu. Görüşme sıcak geçmedi ama konudan sapmadı. Ana da akşamı görüşmeyi zihninde tekrar ederek geçirmedi."},practice:["Önümüzdeki bir iki gün içinde yaşanabilecek gerçekçi bir zorluk seç; hayal edebileceğin en kötü şeyi değil.","Durumu yaklaşık bir dakika boyunca bir kez canlandır. Duygularını bastırmadan fark et.","Bu olursa şunu yapacağım diye başlayan bir cümle yaz. Sonra alıştırmayı bitir ve gününe dön."],reflection:"Nasıl karşılık vereceğine önceden karar vermiş olsaydın hangi aksilik daha hafif gelirdi?",question:"Stoacı hazırlığı aynı olumsuz düşüncelere takılmaktan ayıran nedir?",options:["Mümkün olan en kötü sonucu olabildiğince canlı hayal etmek.","Kısa ve gerçekçi bir hazırlık yapmak, sonunda bir karşılık planlamak.","Korku geçene kadar aynı sahneyi tekrarlamak."],correct:1,feedback:"Hazırlıkta olası bir zorluğu kısaca, başa çıkabileceğin yoğunlukta düşünür ve bir planla bitirirsin. Olumsuz düşüncelere takıldığında ise en kötü senaryoları bir karar vermeden tekrar edersin.",takeaway:"Zor anı bir kez düşün, nasıl karşılık vereceğini belirle, sonra gününe dön.",sources:["stoic-week-handbook","state-mental-contrasting","if-then-plans"],visual:{kind:"table",title:"Hazırlanmak mı, aynı düşüncelere takılmak mı?",columns:["Soru","Stoacı prova","Olumsuz düşüncelere takılmak"],rows:[["Ne kadar sürer?","Bir iki dakika","Saatlerce, aralıklarla"],["Ne hayal edersin?","Olası bir zorluk","Mümkün olan en kötü durum"],["Nasıl biter?","Bir eğer-öyleyse planıyla","Daha fazla korkuyla"],["Sonra ne olur?","Gününe dönersin","Aynı sahne zihninde tekrarlanır"]],note:"Stoic Week el kitabındaki uyarılara dayanan özetimiz."},technique:{name:"Zorlukları önceden düşünme",origin:"Marcus Aurelius · Meditasyonlar (MS 2. yüzyıl); Stoic Week El Kitabı’nda (Modern Stoicism, 2016) öğretildiği biçimiyle",steps:["Bugün karşılaşabileceğin gerçekçi bir zorluk seç.","Kısaca ve başa çıkabileceğin yoğunlukta hayal et.","Kendine bunun hangi kısımlarının senin elinde olduğunu hatırlat.","Nasıl karşılık vermek istediğine karar ver ve bunu bir eğer-öyleyse cümlesine dök.","Alıştırmayı bitir ve dikkatini şimdiye döndür."],evidence:"Bu Stoacı hazırlık alıştırmasını tek başına sınayan kontrollü bir çalışma yok. En yakın modern bulgular, zihinsel karşılaştırma ve eğer-öyleyse planlarına ait. Meta-analizlerde bunlar hedeflere ulaşmada küçük ile orta düzey arasında ortalama etki gösterdi. Alıştırma, kaygı ya da istemeden gelen düşünceler yaşayan herkes için uygun değildir.",sourceId:"stoic-week-handbook"},photo:{id:"1464822759023-fed622ff2c3b",alt:"Karlı dağların altında ormanlık vadiler"}},{id:"stoic-4",title:"Yukarıdan bakış",minutes:9,goal:"Bakış açını, kendine söylediğin sözleri ya da zamanla ilgili bakışını değiştir. Gergin bir ana biraz mesafe al.",reading:["Marcus Aurelius, Meditasyonlar’da hayatını sık sık uzaktan hayal eder: Bütün dünya, insan kalabalıkları, geçen yüzyıllar. Modern Stoacılar buna yukarıdan bakış der. Bu açıdan, kahvaltıdaki tartışma ya da gergin bir e-posta daha küçük görünür. Önemsiz olduğu için değil, hayatın geri kalanı içinde yerini gördüğün için. Amaç kendini küçücük hissetmek değildir. Tek bir anın bütün dikkatini kaplamasını azaltmaktır. Hâlâ o durumun içindesin. Ama artık yalnızca canını yakan kısmı görmüyorsun.","Psikologlar Ethan Kross ve Ozlem Ayduk, bu düşünceye yakın bir yöntemi araştırdı: Kendine dışarıdan bakmak. Deneylerde insanlar acı veren bir anıyı, kendilerini uzaktan izliyormuş gibi düşündü. Bir duvardan bütün sahneyi seyrediyor gibiydiler. Anıyı kendi gözlerinden yeniden yaşayanlara göre daha az olumsuz duygu bildirdiler ve olayı daha iyi anlamlandırdılar. Bir başka yol, konuşma biçimini değiştirmektir. 585 kişinin katıldığı yedi çalışmada, kendine ben yerine kendi adıyla ya da sen diyerek seslenenler daha az sıkıntı duydu. Stresli bir konuşmada gözlemcilere göre daha iyi performans gösterdiler. Sonrasında aynı olumsuz düşüncelere daha az takıldılar."],deeper:[{heading:"Geri çekilmenin üç yolu",paragraphs:["Kross ve Ayduk’un derlemesinde mesafe almanın birkaç yolu anlatılır. Mekândaki bakış açını değiştirebilirsin: Kendini de gördüğün bir sahneyi dışarıdan izlemek gibi. Kullandığın sözleri değiştirebilir, kendine adınla seslenebilirsin. Ya da zamandaki bakışını değiştirebilirsin: On yıl sonra bu konuda nasıl hissedeceğim? Çalışmalarda bu son yaklaşımın, duyguların geçici olduğunu hatırlatarak yardımcı olduğu düşünülüyor."],visual:{kind:"table",title:"Geri çekilmenin üç yolu",columns:["Yol","Şunu dene","Çalışmalar ne buldu"],rows:[["Mekân","Bütün sahneyi uzaktan izle. Kendini de içinde gör.","Olayı yeniden yaşamaya göre daha az olumsuz duygu, daha iyi anlamlandırma ve kan basıncının daha hızlı normale dönmesi."],["Sözcükler","Kendine adınla ya da sen diyerek yol göster.","Daha az sıkıntı ve olumsuz düşüncelere takılma, daha iyi değerlendirilen konuşmalar, durumu tehditten çok aşılabilir bir zorluk olarak görme."],["Zaman","On yıl sonra buna nasıl bakacağını sor.","Daha az sıkıntı; duyguların geçici görülmesiyle bağlantılı."]],note:"Kross & Ayduk (2017) ve Kross ve ark. (2014) çalışmalarından; çoğunlukla kısa laboratuvar çalışmaları."}},{heading:"Araştırmanın sınırları",paragraphs:["Bu çalışmaların çoğu kısa laboratuvar deneyleriydi. Sıklıkla öğrencilerle yapıldılar. Fayda, zaten yoğun sıkıntı yaşayanlarda daha belirgindi. Bazı çalışmalarda sıkıntısı az olanlar pek fayda görmedi. Yazarlar, duyguyu anlamak için mesafe almakla duygudan kaçınmak için mesafe almayı ayırır. Bu yaklaşım, daha açık görebilmek için kullanıldığında yardımcı olur.","Stoacılarla psikologlar tam olarak aynı şeyi anlatmaz. Marcus Aurelius, evrenin ve uzun zamanın içinden geniş bir bakış arar. Deneylerde ise birkaç adım geriden bakmak yeterlidir. İki yaklaşım da biraz mesafenin daha sağduyulu bir karşılığa yer açabileceğini söyler."]}],example:{title:"Priya, 33, yazılım test uzmanı",text:"Priya bir görüntülü görüşmeye katılmak üzereydi. Bir meslektaşı, sürümün zamanında çıkmaması nedeniyle onun ekibini herkesin önünde suçlamıştı. Kalbi hızla çarpıyordu, sert bir yanıt hazırlamıştı. Görüşmeye üç dakika kala iki şey denedi. Önce odanın köşesinden görüşmeyi izlediğini hayal etti. Yoğun bir şirketteki iki yorgun insandan biri kendisiydi. Sonra kendine adıyla seslendi: Priya, istediğin sürüm sorununun çözülmesi. Tartışmayı kazanmak değil. Zaman çizelgesini biliyorsun. Bir kez, sakince anlat. Görüşme başlayınca hâlâ öfkeliydi. Ama sert yanıt yerine zaman çizelgesini anlatarak başladı. Konuşma, ekiplerin neye ihtiyacı olduğuna yöneldi. Sonrasında görüşmeyi zihninde tekrar etmediğini fark etti. Bu onun için yeniydi."},practice:["Şu an seni rahatsız eden bir durumu düşün. Dikkatini ve duygularını ne kadar kapladığını fark et.","Durumu bir dakika boyunca dışarıdan izliyormuş gibi hayal et. Kendini de sahnenin içinde gör.","Kendi adınla ya da “sen” diyerek, sakin bir arkadaşın yapacağı gibi kendine tek cümlelik bir öğüt ver."],reflection:"On yıl sonra bu durum sana nasıl görünecek?",question:"Kross ve arkadaşlarının çalışmalarında, insanların stresli bir konuşmayla başa çıkmasına ne yardımcı oldu?",options:["Kendileriyle “ben” yerine adlarıyla ya da “sen” diyerek konuşmak.","En kötü anları kendi gözlerinden yeniden yaşamak.","Duygu geçene kadar dikkatlerini dağıtmak."],correct:0,feedback:"Kendine ben dışında bir ifadeyle seslenmek mesafe almayı kolaylaştırdı. Sıkıntıyı ve aynı düşüncelere takılmayı azalttı. Gözlemciler bu grubun konuşmalarını daha iyi değerlendirdi. Derlemede mesafe almanın faydalarının, dikkat dağıtmaya göre zaman içinde daha iyi korunduğu da görüldü.",takeaway:"Biraz mesafe almak, duyguların içinde kaybolmadan durumu görmeni sağlayabilir.",sources:["stoic-week-handbook","stoic-kross-distancing","stoic-kross-self-talk"],visual:{kind:"compare",title:"İçinden yaşamak mı, dışarıdan bakmak mı?",left:{label:"Kendi gözlerinden",items:["Ne dediklerini ve nasıl hissettiğini tekrar tekrar yaşarsın.","Neden ben diye tekrar tekrar sorarsın.","Duygular yoğun kalır, sonra yeniden belirir."]},right:{label:"Birkaç adım geriden",items:["Kendini durumun bütünü içinde görürsün.","Ne olduğunu anlamaya çalışırsın.","Duygun yatışır ve olay daha açık görünür."]},note:"Kross & Ayduk (2017) çalışmasındaki içinden yaşama ve dışarıdan bakma ayrımını kendi sözlerimizle özetledik."},technique:{name:"Yukarıdan bakış",origin:"Marcus Aurelius · Meditasyonlar (MS 2. yüzyıl); Stoic Week El Kitabı’nda (Modern Stoicism, 2016) öğretildiği biçimiyle",steps:["Sessizce otur ve kendini şu an bulunduğun yerde hayal et.","Yavaşça odanın, sokağın ve şehrin üzerine yüksel; kendini içindeki küçük bir figür olarak gör.","Bakışını ülkeye, gezegene ve zamanın geniş akışına doğru büyüt.","Bu yükseklikten seni rahatsız eden duruma bak. Hayatın geri kalanı içinde yerini fark et.","Yavaşça geri dön. Bu duruma nasıl sağduyulu karşılık verebileceğini sor."],evidence:"Yukarıdan bakış alıştırması tek başına sınanmadı. Benzer bir yöntem olan kendine dışarıdan bakma, çoğu kısa laboratuvar çalışmasında duygusal tepkileri ve aynı düşüncelere takılmayı azalttı. Fayda, daha yoğun sıkıntı yaşayanlarda daha büyüktü.",sourceId:"stoic-week-handbook"},photo:{id:"1506905925346-21bda4d32df4",alt:"Bulut denizinin üzerinden görünen dağ sırtları"}},{id:"stoic-5",title:"Akşam değerlendirmesi",minutes:8,goal:"Günü kısa ve adil bir değerlendirmeyle bitir. Hatalarından yarın için bir ders çıkar.",reading:["Romalı filozof Seneca, imparator Nero’ya önce hocalık, sonra danışmanlık yaptı. Uyumadan önce günü gözden geçirme alışkanlığıyla anılan Stoacılardan biridir. Epiktetos da benzer bir değerlendirme önerdi. Stoic Week el kitabındaki modern uygulama, beş ile on dakika sürer ve üç soruya dayanır: Neyi kötü yaptım? Neyi iyi yaptım? Neyi farklı yapabilirdim? Yanıtlar somut olmalıdır. Bugün berbattım demek yerine, toplantıda Ali bana karşı çıkınca sözünü kestim, diyebilirsin. Belirli davranışlardan ders çıkarabilirsin. Kendin hakkında genel bir hüküm vermek aynı şeyi sağlamaz.","El kitabı önemli bir koşul ekler: Günü iyi bir dost ya da adil bir öğretmen gibi değerlendir. Savcı gibi değil. Sert bir değerlendirme, olayları zihninde döndürüp uykunu kaçırabilir. Adil bir değerlendirme ise hatayı söyler, iyi gidenleri de görür ve küçük bir değişiklikle biter. Önceki dersteki dışarıdan bakma araştırmasıyla burada bir bağ vardır. İnsanlar biraz mesafe alarak düşündüklerinde, olanları tekrar anlatmak yerine anlamlandırmaya yönelir. Aynı düşüncelere daha az takılırlar. Akşam değerlendirmesinde de amaç budur: Günü anlamak, sonra defteri kapatıp uyumak."],deeper:[{heading:"Aynı düşüncelere takılmayı önlemek",paragraphs:["Bir süre sınırı koy: Her akşam yaklaşık aynı saatte, beş ile on dakika. Kâğıda yaz. Yazmak, değerlendirmeye bir bitiş noktası verir. Üç soruyu yanıtlayınca günü tamamla.","İyi yaptıklarına da hataların kadar dikkat et. İkinci soru süs olsun diye yok. Yalnızca kusur ararsan değerlendirme bir suçlama listesine dönüşür. İyi gidenleri de görürsen neyi tekrar edeceğini öğrenirsin."],visual:{kind:"cycle",title:"Değerlendirme döngüsü",nodes:[{label:"Yap",text:"Gün içinde elinden gelen en iyi seçimleri yap."},{label:"Değerlendir",text:"Akşam üç soruyu kâğıt üzerinde yanıtla."},{label:"Düzelt",text:"Yarın için küçük bir değişiklik seç."},{label:"Dinlen",text:"Defteri kapat ve günün bitmesine izin ver."}],center:"Öğren, cezalandırma",note:"Stoic Week el kitabındaki akşam meditasyonunun bizim özetimiz."}},{heading:"Araştırmalar ne söylüyor?",paragraphs:["Stoacı akşam değerlendirmesini tek başına sınayan kontrollü bir çalışma yok. Stoic Week’teki birkaç günlük uygulamadan biridir. Kursun bütünü, gönüllü katılımcıların kendi bildirimleriyle ve kontrol grubu olmadan değerlendirildi. Denemek için pratik nedenler var: Kısa, ücretsiz ve yardımcı olmazsa bırakması kolay.","Akşam değerlendirmesi sık sık kaygını artırıyorsa ya da uyumanı zorlaştırıyorsa daha erken yap, kısalt ya da bırak. Düşük ruh hâli ya da kendini eleştirme yoğun ve kalıcıysa bir uzmanla konuş."]}],example:{title:"Tom, 52, dükkân sahibi",text:"Tom, dükkânda ters giden her şeyi düşünerek geceleri uyanık kalırdı. Akşam değerlendirmesini saat dokuzda, mutfak masasında küçük bir defterle denemeye karar verdi. İlk gece şöyle yazdı: Kötü yaptığım, teslimat gecikince telefonda tedarikçiye ters çıkmak. İyi yaptığım, kafası karışan yaşlı müşteriye sabır gösterip doğru parçayı bulmak. Farklı yapabileceğim, teslimat gecikince önce yeni saati sormak. Yedi dakika sürdü. Defteri kapatıp tezgâha bıraktı. Yatakta yine tedarikçiyi düşündü. Ama konu artık yazılmıştı ve bir planı vardı. İki hafta sonra aynı tür hataların tekrarlandığını fark etti. Böylece ne üzerinde çalışması gerektiğini gördü."},practice:["Bu akşam beş dakikalık bir zamanlayıcı kur ve kısa yanıtlar yaz: neyi kötü yaptım, neyi iyi yaptım, neyi farklı yapabilirdim?","Sert cümleleri, gerçekleri koruyarak adil bir dostun söyleyeceği gibi yeniden yaz.","Yarın için küçük bir düzeltme seç, yeni bir sayfanın en üstüne yaz ve defteri kapat."],reflection:"Adil bir dost bugün nasıl davrandığın hakkında ne derdi?",question:"Modern Stoacı akşam değerlendirmesi hangi tonu öneriyor?",options:["Hiçbir hatayı tekrarlamayasın diye katı bir yargıcın tonunu.","Hataları da iyi gidenleri de dile getiren adil bir dostun tonunu.","Hiç yargıda bulunmamayı, daha iyi uyumak için yalnızca iyi gidenleri yazmayı."],correct:1,feedback:"Değerlendirmede gerçek hataları ve başarıları somut, nazik sözlerle anlatır, sonunda bir değişiklik belirlersin. Sertlik aynı düşüncelere takılmayı artırabilir. Hataları yok saymak ise öğrenmeni sağlamaz.",takeaway:"Öğrenmek için geriye bak, sonra günü kapat.",sources:["stoic-seneca-iep","stoic-week-handbook","stoic-kross-distancing","stoic-week-report"],visual:{kind:"steps",title:"Uykudan önce üç soru",steps:[{label:"Neyi kötü yaptım?",text:"Kendini yargılamak yerine, yaptığın belirli bir davranışı yaz."},{label:"Neyi iyi yaptım?",text:"Tekrarlamaya değer en az bir şey bul."},{label:"Neyi farklı yapabilirdim?",text:"Öğrendiğini yarın yapacağın küçük bir değişikliğe dönüştür."}],note:"Seneca ve Epiktetos’a dayanan, Stoic Week el kitabındaki akşam meditasyonundan."},technique:{name:"Akşam değerlendirmesi",origin:"Seneca ve Epiktetos; Stoic Week El Kitabı’nda (Modern Stoicism, 2016) öğretildiği biçimiyle",steps:["Akşam belirli bir saatte bir defterle otur.","Günü sabahtan şimdiye, sırasıyla kısaca gözden geçir.","Yanıtla: neyi kötü yaptım, neyi iyi yaptım, neyi farklı yapabilirdim?","Adil bir dost gibi konuş. Kişiliğini yargılamak yerine belirli davranışlarını anlat.","Yarın için bir düzeltme yaz ve defteri kapat."],evidence:"Değerlendirme tek başına kontrollü çalışmalarda sınanmadı. Stoic Week’in bir parçasıdır. Kursu bitirenler, kontrol grubu olmayan ve kendi bildirimlerine dayanan anketlerde daha iyi hissettiklerini söyledi.",sourceId:"stoic-week-handbook"},photo:{id:"1475924156734-496f6cac6ec1",alt:"Alacakaranlıkta kayalık bir kıyıda dalgalar"}},{id:"stoic-6",title:"Bugün tek bir karar",minutes:8,goal:"Stoacıların elinde olana odaklanma yaklaşımını kullan. Bugün uygulayacağın küçük, somut bir karar ver.",reading:["Stoacılar için felsefe, yalnızca beğenilecek fikirler değil, bir yaşam biçimiydi. Bu kurstaki bütün alıştırmalar buraya gelir. Elinde olanı ayırmak, neyi değiştirebileceğini gösterir. Yargını sorgulamak, kendine anlattığın bir hikâyenin seni yönetmesini önler. Hazırlık, nasıl karşılık vereceğini belirler. Mesafe almak gerginliği azaltır. Akşam değerlendirmesi gününden ders çıkarmanı sağlar. Ama bunlar ancak bir şeyi farklı yaptığında anlam kazanır. ODA’nın temel düşüncesi de budur: Her gün, hayatının şekillendirebildiğin bir alanında bilinçli bir karar vermek.","İyi bir Stoacı kararın üç özelliği vardır. Senin elinde bir davranıştır. Bugün yapabileceğin kadar küçüktür. Belirli bir ana bağlıdır; böylece yalnızca hafızana ya da iradene dayanmaz. Planlama araştırmaları son adımda yardımcı olur. 94 testte, X durumu olursa Y yapacağım biçimindeki planlar hedeflere ulaşmada orta ile büyük düzey arasında ortalama etki gösterdi. Daha yeni analizler, gerçek etkinin daha küçük olabileceğini düşündürüyor. Gabriele Oettingen’in WOOP yöntemi bu plana bir istek ve bir engel ekler. Dayandığı araştırmalar küçük ile orta düzey arasında etki gösteriyor."],deeper:[{heading:"Neden küçük ve somut?",paragraphs:["Büyük kararlar çoğu zaman sonuç sütununa girer: Forma girmek, daha sakin olmak, ilişkiyi düzeltmek. Stoacı bir karar bunu kendi davranışına dönüştürür: Öğle yemeğinden sonra on dakika yürümek, yöneticine yanıt vermeden önce üç nefes almak, akşam yemeğinde partnerine içten bir soru sormak. Gün nasıl geçerse geçsin, bu karar için bugün adım atabilirsin.","Sonra sonucu bırak. Yürüyüşünü yaptıysan, hâlâ yorgun olsan da kararını uyguladın. Sonuç ikinci sütuna aittir. Öğrendiğin şeyi bu akşamki değerlendirmeye yazabilirsin."],visual:{kind:"compare",title:"Bir sonuç istemek mi, bugün adım atmak mı?",left:{label:"İstenen sonuç",items:["Terfi al.","Kaygılı olmayı bırak.","Beni anlamalarını sağla."]},right:{label:"Bugün için Stoacı karar",items:["Proje özetini yöneticime saat 15.00’e kadar gönder.","Göğsüm sıkışırsa yanıt vermeden önce üç kez yavaşça nefes alacağım.","Kendi görüşümü anlatmadan önce iki dakika onları dinleyeceğim."]},note:"Kendi örneklerimiz."}},{heading:"Gün yine de kötü giderse",paragraphs:["Bazı günler planını uygulayamazsın. Çocuğun hastalanır, toplantı uzar, enerjin biter. Stoacı yaklaşım kendini suçlamak değildir. Şimdi nasıl karşılık vereceğin hâlâ elindedir. Aynı kararın daha küçük bir hâlini uygulayabilir ya da neyin engel olduğunu akşam değerlendirmesi için not edebilirsin. Kusursuz yapmaya çalışmak yerine bağını koru.","Bu kurs eğitim ve kişisel çalışma içindir, tedavi değildir. Stres, düşük ruh hâli ya da kaygı günlük yaşamını aksatıyorsa, profesyonel destek istemek en yerinde Stoacı karar olabilir. Yardım istemek, senin atabileceğin bir adımdır."]}],example:{title:"Can, 29, satış danışmanı",text:"Can haftalardır para ve kardeşiyle gergin ilişkisi için kaygılanıyordu. İki konu da başa çıkamayacağı kadar büyük görünüyordu. Pazar sabahı elinde olanları ayırdı. Kardeşinin ruh hâlini ve kira artışını ikinci sütuna yazdı. İlk sütuna o ayki harcamalarını kontrol etmeyi ve kardeşiyle iletişim kurmayı koydu. Bugün için bir karar seçti: Öğle yemeğini bitirince kardeşine yeni işinin nasıl gittiğini soran kısa bir mesaj gönderecekti. Kararını telefonunun kilit ekranına yazdı. Yemekten sonra neredeyse vazgeçecekti ama mesajı gönderdi. Yanıt akşam geldi, kısa ve sıcaktı. Sorunlar çözülmemişti. Ama Can akşam değerlendirmesinde, elinde olan bir şey için harekete geçtiğini yazdı. Yarınki kararını da seçti: Harcamalarını kontrol etmek."},practice:["Bir kaygı ya da hedef seç ve onun senin elindeki kısmını sonuç olarak değil, eylem olarak yaz.","Bu eylemi, bugün on beş dakikadan kısa sürede yapabilecek hâle gelene kadar küçült.","Eylemi bir eğer-öyleyse cümlesiyle belirli bir ana bağla. Örneğin öğle yemeğini bitirirsem şunu yapacağım. Sonra uygula."],reflection:"Bugün yapabileceğin, tamamen senin elinde olan küçük bir şey ne?",question:"Bunlardan hangisi bugün için Stoacı tarzda bir karar?",options:["Bu yıl daha sakin bir insan olmak.","Ekibimin önerimi onayladığından emin olmak.","Öğle yemeğinden sonra bilgisayarımı açarsam önerinin ana hatlarını yazmak için on dakika ayıracağım."],correct:2,feedback:"Bu davranış senin elinde, bugün yapılabilecek kadar küçük ve bir eğer-öyleyse planıyla belirli bir ana bağlı. Diğer iki seçenek sonuçları ya da uzun vadeli istekleri anlatıyor.",takeaway:"Bugün elinde olan küçük bir adımı at. Gerisini bırak.",sources:["stoic-epictetus-iep","stoic-week-handbook","if-then-plans","oettingen-woop-method","mcii"],visual:{kind:"table",title:"Kaygıdan tek bir karara",columns:["Kaygı","Senin elinde olan","Bugün için karar"],rows:[["İşi alacak mıyım?","Hazırlık ve takip","Akşam yemeğinden sonra en zor sorunun yanıtını on dakika çalış."],["Arkadaşım bana kırgın mı?","İletişim kurmak ve dinlemek","Öğleden önce kısa, dürüst bir mesaj gönder."],["Sağlığımı ihmal mi ediyorum?","Hareket ve yatma saati","Öğle yemeğinden sonra on dakikalık bir yürüyüş yap."]],note:"Elinde olanı ayırıp eğer-öyleyse kararlarına dönüştürdüğümüz kendi örneklerimiz."},technique:{name:"WOOP",origin:"Gabriele Oettingen · Rethinking Positive Thinking (2014)",steps:["İstek (Wish): İstediğin, zor ama mümkün bir şeyi belirle.","Sonuç (Outcome): bunun en iyi sonucunu bir an gözünde canlandır.","Engel (Obstacle): Önündeki asıl engeli bul. Bu çoğu zaman kendi alışkanlığın ya da duygundur.","Plan: “Eğer [engel] olursa, o zaman [eylem] yapacağım” diye yaz ve bugün başlamak için bir zaman seç."],evidence:"Zihinsel karşılaştırma ile eğer-öyleyse planları, 21 çalışmada hedeflere ulaşmada küçük ile orta düzey arasında ortalama etki gösterdi (g = 0,336). Resmî WOOP sitesi yöntemin geliştiricilerine aittir. Bağımsız bir değerlendirme değildir.",sourceId:"oettingen-woop-method"},photo:{id:"1502082553048-f009c37129b9",alt:"Açık bir arazide tek başına duran bir ağaç"}}]},Ye=Object.freeze(Object.defineProperty({__proto__:null,COURSE:Me,SOURCES:Ke},Symbol.toStringTag,{value:"Module"})),qe=[{id:"compassion-neff-definition",title:"Kristin Neff · Öz şefkat nedir? (self-compassion.org)",url:"https://self-compassion.org/what-is-self-compassion/",type:"guidance",finding:"Neff, öz şefkati zorlanan bir arkadaşına göstereceğin sıcaklığı ve anlayışı kendine de göstermek olarak tanımlar. Üç bileşeni vardır: kendini yargılamak yerine kendine nazik davranmak, yalnız hissetmek yerine zorlukların insanlığın ortak deneyimi olduğunu hatırlamak, duyguyla bütünüyle özdeşleşmek yerine onu fark etmek. Teselli eden ve kabul eden öz şefkati, kendini korumak, sınır koymak, hedeflere yönelmek ya da zarar veren durumlardan ayrılmak için harekete geçen öz şefkatten ayırır. Öz şefkatin benlik saygısından, kendine acımaktan ve kendine fazla göz yummaktan da farklı olduğunu belirtir.",limitation:"Kavramı geliştiren araştırmacının tanımıdır. Bir araştırma değildir; modeli açıklar, sınamaz. Sayfa okundu."},{id:"compassion-neff-exercises",title:"Kristin Neff · Self-Compassion (2011) ve öz şefkat alıştırmaları (self-compassion.org)",url:"https://self-compassion.org/",type:"technique",finding:"Neff, öz şefkati geliştirmek için günlük hayatta kullanılabilecek alıştırmalar sunar. Bunlar arasında bir arkadaşına nasıl davranacağını düşünmek, öz şefkat molası vermek, öz şefkat günlüğü tutmak ve seni koşulsuz seven bir arkadaşın gözünden kendine mektup yazmak vardır. Molada acıyı kabul eder, başkalarının da benzer zorluklar yaşadığını hatırlar ve kendine nazik davranırsın. Buna çoğu zaman rahatlatıcı bir dokunuş eşlik eder.",limitation:"Kavramı geliştiren kişinin uygulama rehberidir. Her alıştırma ayrı ayrı araştırmalarda sınanmadı. Bulgular, bu alıştırmaları bir araya getiren programlara dayanıyor."},{id:"compassion-mindful-self-compassion-rct",title:"Neff & Germer · 2013 · Farkındalıklı Öz Şefkat programının pilot çalışması ve randomize kontrollü çalışması (Journal of Clinical Psychology)",url:"https://doi.org/10.1002/jclp.21923",type:"research",finding:"Yetişkinlerle yapılan randomize bir çalışmada, sekiz haftalık Farkındalıklı Öz Şefkat programına katılanlar bekleme listesindekilerle karşılaştırıldı. Program grubunda öz şefkat, farkındalık, başkalarına duyulan şefkat ve yaşam doyumu daha fazla arttı. Depresyon, kaygı, stres ve duygusal kaçınma daha fazla azaldı. Kazanımlar altı aylık ve bir yıllık takiplerde korundu. Daha çok uygulama yapanlarda öz şefkatteki artış daha büyüktü.",limitation:"Programın geliştiricilerinin yürüttüğü küçük bir çalışmadır. Başka bir etkin programla değil, bekleme listesiyle karşılaştırma yapılmıştır. Ölçümlerin çoğu katılımcıların kendi bildirimlerine dayanır. Çalışma, tek tek alıştırmaları değil programın bütününü sınar."},{id:"compassion-ferrari",title:"Ferrari ve ark. · 2019 · Öz şefkat müdahaleleri ve psikososyal sonuçlar: randomize kontrollü çalışmaların meta-analizi (Mindfulness)",url:"https://doi.org/10.1007/s12671-019-01134-6",type:"research",finding:"Öz şefkat müdahalelerine ilişkin 27 randomize kontrollü çalışmayı birleştiren meta-analiz, çeşitli psikososyal sonuçlarda iyileşme buldu. Bunlar arasında öz şefkat, olumsuz düşüncelere tekrar tekrar takılma, kendini eleştirme, stres, depresyon ve kaygı vardı.",limitation:"Çalışmaların çoğu küçüktü. Uygulama biçimleri, katılımcı grupları ve kontrol koşulları farklıydı. Sonuçların çoğu katılımcıların kendi bildirimlerine dayanıyordu ve takip süreleri kısaydı."},{id:"compassion-gilbert-cft",title:"Gilbert · 2014 · Şefkat odaklı terapinin kökenleri ve doğası (British Journal of Clinical Psychology)",url:"https://doi.org/10.1111/bjc.12043",type:"research",finding:"Gilbert, şefkat odaklı terapinin (ŞOT) yoğun utanç yaşayan ve kendini çok eleştiren kişiler için nasıl geliştirildiğini anlatır. Bu kişiler terapinin mantığını anlasalar da rahatlamakta ve güvende hissetmekte zorlanıyordu. ŞOT, birbiriyle etkileşen üç duygu düzenleme sistemine dayanır: tehdit ve korunma; başarma isteği ve kaynak arayışı; yatışma, hoşnutluk ve bağ kurma.",limitation:"Deneysel bir çalışma değil, kuramsal ve klinik bir derlemedir. Üç sistem modeli basitleştirilmiş bir klinik çerçevedir. ŞOT’un tedavi olarak etkililiğine ilişkin araştırmalar hâlâ gelişiyor."},{id:"compassion-gilbert-mind",title:"Paul Gilbert · The Compassionate Mind (2009) ve Compassionate Mind Foundation",url:"https://www.compassionatemind.co.uk/",type:"technique",finding:"Gilbert’in şefkatli zihin eğitimi, yatışma sistemini harekete geçirmek için iki uygulama önerir. Biri nefesi rahat, düzenli bir ritme yavaşlatmaktır. Diğeri kendini bilge, güçlü ve şefkatli bir hâlde gözünde canlandırmaktır.",limitation:"ŞOT’un geliştiricisi ve vakfının sunduğu bir uygulama rehberidir. Bu alıştırmalar genellikle terapi ya da yapılandırılmış eğitim içinde öğretilir. Burada tek başına bir kişisel çalışma olarak sınanmadılar."},{id:"compassion-tangney-moral-emotions",title:"Tangney, Stuewig & Mashek · 2007 · Ahlaki duygular ve ahlaki davranış (Annual Review of Psychology)",url:"https://doi.org/10.1146/annurev.psych.56.091103.070145",type:"research",finding:"Derleme, insanın kendisini bütünüyle kötü görmesine yol açan utancı, belirli bir davranışa odaklanan suçluluktan ayırır. Suçluluğa yatkınlık, empati ve verilen zararı telafi etme çabasıyla ilişkilidir. Utanca yatkınlık ise saklanma, inkâr, savunmaya geçerek öfkelenme, başkalarını suçlama ve psikolojik belirtilerle ilişkilidir.",limitation:"Araştırmaların çoğu utanca ya da suçluluğa yatkınlık ile diğer özellikler arasındaki ilişkilere bakar. Tek bir anda utançtan suçluluğa geçmenin sonuçları değiştirdiğini göstermez."},{id:"compassion-brown-shame-resilience",title:"Brown · 2006 · Utanç direnci kuramı: kadınlar ve utanç üzerine temellendirilmiş kuram çalışması (Families in Society)",url:"https://doi.org/10.1606/1044-3894.3483",type:"research",finding:"Kadınlarla yapılan görüşmelere dayanan çalışma, utançla başa çıkmayı dört boyutta ele alır: utancı fark etmek ve tetikleyicilerini anlamak, arkasındaki mesaj ve beklentileri sorgulamak, başkalarıyla iletişim kurmak ve utanç hakkında konuşmak. Bu beceriler her kişide farklı ölçülerde bulunabilir.",limitation:"Yalnızca kadınlarla yapılmış, kuram geliştirmeyi amaçlayan nitel bir araştırmadır. Tekrarlanan deneyimleri anlatır. Dört bileşeni uygulamanın utancı azaltıp azaltmadığını sınamaz."},{id:"compassion-brown-practice",title:"Brené Brown · I Thought It Was Just Me (2007) ve brenebrown.com",url:"https://brenebrown.com/",type:"technique",finding:"Brown, kusurlu ve değersiz hissetmeye yol açan utancı, yaptığın bir şeyden rahatsız olmana yol açan suçluluktan ayırır. Utançla başa çıkmayı bir dizi beceri olarak sunar: utancı ve tetikleyicilerini fark etmek, arkasındaki mesajların gerçeğe uyup uymadığını sorgulamak, başkalarıyla iletişim kurmak ve utanç hakkında konuşmak.",limitation:"Yazarın nitel araştırmasına dayanan, genel okura yönelik bir kitap ve web sitesidir. Uygulamalar bir müdahale olarak sınanmadı."}],Re={id:"compassion",title:"Öz şefkat",subtitle:"Kendine sevdiğin biri gibi davran, hatalarının sorumluluğunu da al",description:"İçindeki ses hem dürüst olabilir hem de sana destek verebilir mi? Bu kursta öz şefkate dair araştırmaları ve uygulamaları ele alıyoruz. Kendine nazik davranmanın sorumluluk almayı nasıl kolaylaştırabileceğine bakıyoruz.",scope:"Hata yaptığında, aksilik yaşadığında ya da canın yandığında kendine sert davranıyorsan bu kurs sana göre olabilir. Yetişkinler için eğitim ve kişisel çalışma sunar; terapi değildir. Travma, istismar ya da geçmeyen veya bunaltan bir utanç yaşıyorsan bu alanda yetkin bir uzmandan destek al. Öz şefkat alıştırmaları bazen eski acıları canlandırabilir. Kriz içindeysen ya da kendine zarar vermeyi düşünüyorsan hemen 112’yi ara.",outcome:"Öz şefkatin ne olduğunu öğrenmek, zor anlarda iki dakikalık bir mola verebilmek, tehdit, başarma isteği ve yatışma sistemlerini tanımak, utançla başa çıkmak için bir plan hazırlamak. Ayrıca kendine şefkatli bir mektup yazıp sonunda sorumluluğunu alacağın somut bir adım belirlemek.",photo:{id:"1470252649378-9c29740c9fa8",alt:"Sıcak akşam ışığında sakin bir tarla"},lessons:[{id:"compassion-1",title:"Şefkat zayıflık değildir",minutes:8,goal:"Başarısızlıktan sonra kendine nazik davranmanın daha iyisini yapmana nasıl yardımcı olabileceğini gör.",reading:["Pek çok insan, içindeki eleştirel sesin onu doğru yolda tuttuğuna inanır. Kendine sert davranmayı bırakırsa tembel, dikkatsiz ya da bencil olacağını düşünür. Bu alandaki modern araştırmalara öncülük eden psikolog Kristin Neff, öz şefkati farklı tanımlar: Zorlanan yakın bir arkadaşına göstereceğin sıcaklığı ve anlayışı kendine de göstermek. Bu, hiçbir şey ters gitmemiş gibi davranmak değildir. İyi bir arkadaş da hatayı görür. Ama seni küçümsemez. Ne yapacağını düşünürken yanında olur.","Araştırmalar, kendine nazik davranmanın çabadan vazgeçmek anlamına gelmediğini gösteriyor. Juliana Breines ve Serena Chen’in deneylerinde katılımcılar bir zayıflıklarına, ahlaki bir hatalarına ya da başarısız oldukları bir sınava öz şefkatle bakmaya teşvik edildi. Ardından kendilerini geliştirme istekleri arttı. Zayıflıklarının değişebileceğine daha çok inandılar ve hatalarını telafi etmeye daha istekli oldular. Bir sınavda başarısız olanlar, sonraki sınava daha uzun süre çalıştı. Benlik saygısı desteklenen grup da dahil, karşılaştırma gruplarında aynı sonuç görülmedi. Kendine sert davranmak sorumluluk almak gibi gelebilir. Ama çoğu zaman yalnızca korkuyu artırır."],deeper:[{heading:"İçindeki eleştirel ses neden yararlı gelir?",paragraphs:["Kendini eleştirmek çoğu zaman korunma çabası olarak başlar. Kendini önce sen eleştirirsen, başkasının eleştirisi seni hazırlıksız yakalayamaz. Duyduğun acı da konuyu önemsediğinin kanıtı gibi gelir. Ama korku çabanı etkiler. Her hata bir saldırıyla karşılanıyorsa, saldırıdan kaçınmanın en kolay yolu hataya bakmamaktır. Bahane üretir, başkasını suçlar ya da yeniden denemekten vazgeçersin.","Öz şefkat, hataya bakmayı kolaylaştırır. Başarısızlığın ardından ceza yerine destek gördüğünde, ne olduğunu kabul etmek ve incelemek daha güvenli gelir. Breines ve Chen’in bulgularının arkasındaki düşünce budur. Bu yüzden bu kursta kendine nazik davranmayı sorumluluk almakla birlikte ele alıyoruz."],visual:{kind:"table",title:"Öz şefkat hakkında yaygın inançlar",columns:["Yaygın inanç","Araştırmalar ve tanımlar ne söylüyor?"],rows:[["Beni tembelleştirir.","Laboratuvar deneylerinde gelişme çabasını artırdı. Örneğin başarısız bir sınavın ardından çalışma süresi uzadı."],["Bu sadece benlik saygısı.","Benlik saygısı, başkalarıyla kıyaslandığında kendini iyi ya da özel hissetmeye bağlıdır. Öz şefkati kazanman gerekmez."],["Bu kendine acımak.","Kendine acımak, neden ben sorusuna takılı kalır. Öz şefkat, herkesin zorlandığını hatırlatır."],["Beni sorumluluktan kurtarır.","Koruyucu yönü, sınır koymayı ve hedefler için harekete geçmeyi de kapsar."]],note:"Breines & Chen (2012) çalışması ve Kristin Neff’in tanımlarından özetlendi."}},{heading:"Araştırma ne söylüyor, ne söylemiyor",paragraphs:["56 randomize çalışmayı birleştiren analizde öz şefkat programları, stres, kaygı ve depresif belirtilerde kısa vadede küçük ile orta düzey arasında azalma sağladı. Ancak çalışmaların genel yanlılık riski yüksekti. 27 randomize çalışmayı inceleyen ayrı bir meta-analizde, olumsuz düşüncelere tekrar tekrar takılma, kendini eleştirme, stres ve depresyon gibi sonuçlarda iyileşme bulundu. Etkiler gerçekti ama sınırlıydı. Çoğu haftalar ya da aylar içinde ölçüldü.","Breines ve Chen çoğunlukla üniversite öğrencileriyle çalıştı ve motivasyonu kısa vadede ölçtü. Bu nedenle öz şefkatin başarıyı garanti ettiğini söyleyemeyiz. Söyleyebileceğimiz şu: Kendine nazik davranırken yüksek standartlarını da koruyabilirsin."]}],example:{title:"Daniel, 34, proje yöneticisi",text:"Daniel, veri temizliğinin süresini yanlış hesapladığı için müşteri raporunu zamanında teslim edemedi. Eve dönerken trende içindeki tanıdık ses başladı: Özensizsin, işini iyi yapmıyorsun, hep böyle yapıyorsun. Bir yandan da patronuna göndermek için bahaneler hazırladığını fark etti. Kendine başka bir soru sordu: Aynı durumdaki bir iş arkadaşına ne derdi? Bunun gerçek bir hata olduğunu, iyi insanların da hata yapabildiğini söylerdi. Şimdi gerekenin yeni bir teslim tarihi ve bir dahaki sefere daha gerçekçi bir tahmin olduğunu eklerdi. Bunları telefonuna yazdı. Ertesi sabah patronuna olanları açıkça anlattı ve gerçekçi bir tarih verdi. Planlama şablonuna beklenmedik gecikmeler için ek süre koydu. Rapor iki gün geç gönderildi. Şablondaki değişikliği ise kullanmaya devam etti."},practice:["Bir hatadan sonra kendine söylediğin son sert sözü kelimesi kelimesine yaz.","Bu sözü, aynı durumdaki yakın bir arkadaşına söyleyeceğin gibi yeniden yaz. Gerçekleri koru, küçümseyen ifadeleri çıkar.","Sonraki somut adımını anlatan bir cümle ekle. Kendine nazik davranırken gelişmek için de bir yol belirle."],reflection:"Kendine sert davranmayı bırakırsan ne olacağından korkuyorsun?",question:"Breines ve Chen’in deneylerinde, insanlar başarısızlığa öz şefkatle yaklaştığında ne oldu?",options:["Gelişme istekleri arttı. Örneğin başarısız bir sınavdan sonra daha uzun çalıştılar.","Sonucu umursamayı bıraktılar.","Kendilerini daha iyi hissettiler ama kimseden daha fazla çaba göstermediler."],correct:0,feedback:"Öz şefkat, benlik saygısını yükselten ya da nötr koşullara göre gelişme ve hatayı telafi etme isteğini artırdı. Kendine nazik davranmak, hatayla yüzleşme korkusunu azalttı.",takeaway:"Kendine destek olurken yüksek standartlarını da koruyabilirsin.",sources:["state-self-compassion-motivation","compassion-neff-definition","compassion-neff-exercises","self-compassion","compassion-ferrari"],visual:{kind:"compare",title:"Bir hatadan sonra: iç eleştirmen mi, iç koç mu?",left:{label:"İç eleştirmen",items:["Kendine saldırırsın: Hiçbir işe yaramıyorum.","Hatayla yüzleşmek canını yaktığı için ondan kaçarsın.","Bir sonraki denemede daha çok korkarsın."]},right:{label:"Şefkatli koç",items:["Davranışı söylersin: Süreyi yanlış tahmin ettim.","Ne olduğunu daha rahat inceleyebilirsin.","Sonraki adımını belirlersin."]},note:"Kendini yargılamak ile kendine nazik davranmak arasındaki farkı kendi sözlerimizle özetledik."},technique:{name:"Bir arkadaşına nasıl davranırdın?",origin:"Kristin Neff · Self-Compassion (2011)",steps:["Yakın bir arkadaşının bir hata ya da zorlanma yüzünden kötü hissettiği bir anı düşün ve ona nasıl karşılık verdiğini, sözlerini ve tonunu hatırla.","Şimdi kendini kötü hissettiğin bir anı düşün ve kendine nasıl karşılık verdiğini hatırla.","İki yanıtı karşılaştır ve aradaki farkın nedenini düşün.","Kendine o arkadaşına davrandığın gibi davransan ne söylerdin? Yaz.","Bir dahaki zor anında bu yanıtı dene ve neyin değiştiğine bak."],evidence:"Bu düşünme alıştırması tek başına sınanmadı. Neff’in öz şefkat tanımının temelini ele alır. Benzer alıştırmalar içeren öz şefkat programları, randomize çalışmalarda kısa vadede küçük ile orta düzey arasında fayda gösteriyor.",sourceId:"compassion-neff-exercises"},photo:{id:"1474418397713-7ede21d49118",alt:"Bir kayanın üzerinde oturup dağların ardından doğan güneşi izleyen biri"}},{id:"compassion-2",title:"Üç bileşen",minutes:9,goal:"Neff’in öz şefkat için tanımladığı üç bileşeni öğren. Hangisini en sık ihmal ettiğini fark et.",reading:["Neff’e göre öz şefkat, birlikte çalışan üç bileşenden oluşur. İlki kendini yargılamak yerine kendine nazik davranmaktır. Zorlandığında kendine soğuk ve kırıcı değil, anlayışlı ve destekleyici yaklaşırsın. İkincisi insanlığın ortak deneyimini hatırlamaktır. Acı çekmek ve kusurlu olmak insan olmanın bir parçasıdır; yalnızca sende bir sorun olduğunun kanıtı değildir. Üçüncüsü farkındalıktır. Acı veren duyguyu açıkça görürsün. Onu ne bastırırsın ne de diğer her şeyi kaplamasına izin verirsin. Her bileşenin çoğumuzun tanıdığı bir karşıtı vardır. Her biri diğer ikisini destekler.","Bir bileşen eksik olduğunda ne işe yaradığını daha kolay görürsün. Farkındalık olmadan kendine nazik davranmaya çalışırsan, canını neyin yaktığını kabul etmeden rahatlamaya koşabilirsin. Ortak insanlık duygusu olmadan acını açıkça görsen bile kendini yapayalnız hissedebilirsin. Nezaket olmadan ortak insanlık düşüncesi ise küçümseyici duyulabilir: Herkes başarısız olur, ne olmuş? Üçü bir araya geldiğinde şöyle diyebilirsin: Bu canımı yakıyor. Başkaları da bunu yaşadı. Bununla uğraşırken kendime iyi davranabilirim. Üçünü de yoğun biçimde hissetmen gerekmez. En çok hangisinde zorlandığını fark etmek iyi bir başlangıçtır."],deeper:[{heading:"Öz şefkat ne değildir",paragraphs:["Neff, öz şefkati ona benzeyen üç kavramdan ayırır. Benlik saygısı kendini olumlu değerlendirmeye dayanır. Çoğu zaman özel ya da ortalamanın üzerinde hissetmeyi gerektirir. Bu yüzden tam da başarısız olduğunda zayıflayabilir. Kendine acımak, kendi dertlerine odaklanıp başkalarının da zorlandığını unutmaktır. Kendine fazla göz yummak ise kısa süreli haz için uzun vadede sana iyi gelecek şeylerden vazgeçmektir. Neff’e göre öz şefkat, kazanmak zorunda olmadığın daha sağlam bir değerlilik duygusu sağlar."],visual:{kind:"compare",title:"İki farklı soru",left:{label:"Benlik saygısı sorar",items:["Başkalarından daha iyi miyim?","Bu sefer başarılı oldum mu?","Saygıyı hak edecek kadar iyi miyim?"]},right:{label:"Öz şefkat sorar",items:["Şu an neye ihtiyacım var?","Bu deneyimden öğrenmeme ne yardımcı olur?","Bunu düzeltirken kendime nasıl bakabilirim?"]},note:"Kristin Neff’in yaptığı ayrımı kendi örneklerimizle anlattık."}},{heading:"Sık yapılan hatalar",paragraphs:["İlk hata, öz şefkati mutlaka hissetmen gereken bir duygu sanmaktır. İçinden sıcaklık gelmese de nazik davranmayı seçebilirsin. İkinci hata, üç bileşeni sorumluluktan kaçmak için kullanmaktır. Örneğin herkesin hata yaptığını söyleyip kendi hatanı düzeltmemek. Ortak insanlık duygusu yalnızlığı azaltır; sorumluluğu ortadan kaldırmaz.","Üçüncü hata, kendine nazik davranmanın hemen doğal gelmesini beklemektir. Yıllardır kendine sert konuşuyorsan bu yaklaşım başta tuhaf, hatta rahatsız edici gelebilir. Alıştırmayı kısa tut ve kendini zorlama. Bu tuhaflığı yeni bir şey öğrenmenin parçası olarak gör."]}],example:{title:"Aisha, 27, asistan doktor",text:"Uzun bir vardiyanın ardından Aisha defterini açtı. O gün bir ilaç etkileşimini gözden kaçırmış, eczacı bunu fark etmişti. İlk yazdığı cümle kendine yönelik sert bir yargıydı: Tehlikeliyim, hiç doktor olmamalıydım. Altına üç bileşeni yazdı. Farkındalık: Korkuyorum, utanıyorum ve göğsüm sıkışıyor. Ortak insanlık: İlaç etkileşimlerini gözden kaçırmak bilinen bir risk. Eczacıların ikinci kez kontrol yapmasının nedeni de bu. Saygı duyduğu meslektaşları, son anda fark ettikleri kendi hatalarını anlatmıştı. Nezaket: Yorgunum. Hastalarımı önemsediğim için bu canımı yakıyor. Sonra ne yapacağını yazdı: O ilaç grubunu inceleyecek ve sorumlu doktoruna ekibin bu etkileşimleri nasıl işaretlediğini soracaktı. Kendini çok iyi hissetmedi. Ama uyuyabildi ve ertesi gün ikisini de yaptı."},practice:["Yakın zamanda yaşadığın zor bir anı hatırla. Her bileşen için bir cümle yaz: Ne hissediyorsun, kimler benzer bir şey yaşadı, kendine hangi nazik sözü söyleyebilirsin?","Yazmakta en çok zorlandığın cümleyi işaretle. Bu hafta o bileşen üzerinde çalış.","Gün bitmeden, küçük bir stres anında en zor gelen o parçayı bir kez daha kullan."],reflection:"Hangisi sana daha tanıdık: Kendini yargılamak, yalnız hissetmek ya da duygunun içinde kaybolmak?",question:"Hangi seçenek Neff’in öz şefkat için tanımladığı üç bileşeni sıralar?",options:["Kendine nazik davranmak, ortak insanlık ve farkındalık.","Benlik saygısı, olumlu düşünme ve özgüven.","Öz disiplin, mükemmeliyetçilik ve dayanıklılık."],correct:0,feedback:"Neff her bileşenin karşıtını da tanımlar. Kendine nazik davranmanın karşıtı kendini yargılamak, ortak insanlığın karşıtı yalnız hissetmek, farkındalığın karşıtı ise duyguyla bütünüyle özdeşleşmektir.",takeaway:"Bu canımı yakıyor. Yalnız değilim. Bununla uğraşırken kendime nazik davranabilirim.",sources:["compassion-neff-definition","compassion-neff-exercises","self-compassion"],visual:{kind:"table",title:"Üç bileşen ve zıtları",columns:["Bileşen","Zıddı","Örnek cümle"],rows:[["Kendine nazik davranmak","Kendini yargılamak","Bu zor ve elimden gelenin en iyisini yapıyorum."],["Ortak insanlık","Yalnız hissetmek","Başkaları da bu konuda zorlanıyor."],["Farkındalık","Duyguyla bütünüyle özdeşleşmek","Şu an utandığımı fark ediyorum."]],note:"Bileşenler Kristin Neff’ten; örnek cümleler bize ait."},technique:{name:"Öz şefkat günlüğü",origin:"Kristin Neff · Self-Compassion (2011)",steps:["Günün sonunda seni kötü hissettiren olayları, kendini yargıladığın konuları ya da zor deneyimleri yaz.","Farkındalık için duygularını olduğu gibi yaz. Ne büyüt ne de önemsiz say.","Ortak insanlık için, benzer duyguları yaşayan insanlarla paylaştığın deneyimi yaz.","Kendine nazik davranmak için, bir arkadaşına söyleyeceğin birkaç anlayışlı ve destekleyici sözü kendine yaz.","Kısa tut; her akşam birkaç satır yeter."],evidence:"Günlük tek başına sınanmadı. Araştırmalar öz şefkat programlarının bütününü ele alıyor. Bu programlar randomize çalışmalarda kısa vadede küçük ile orta düzey arasında fayda gösteriyor.",sourceId:"compassion-neff-exercises"},photo:{id:"1529156069898-49953e39b3ac",alt:"Kol kola oturan arkadaşlar, arkadan görünüyor"}},{id:"compassion-3",title:"Öz şefkat molası",minutes:8,goal:"Bir şey canını yaktığı anda uygulayabileceğin iki dakikalık bir alıştırma öğren.",reading:["Öz şefkat molası, canın yandığı anda kullanabileceğin kısa bir uygulamadır. Gönderdiğine pişman olduğun bir e-postanın, kötü bir haberin ya da tartışmanın ardından deneyebilirsin. Neff’in üç bileşenini sırayla uygularsın. Önce acıyı sade bir cümleyle kabul edersin: Bu canımı yakıyor ya da çok stresliyim. Sonra zorlanmanın hayatın bir parçası olduğunu ve başkalarının da böyle hissettiğini hatırlarsın. Son olarak kendine nazik davranırsın. Elini göğsüne koyabilir ya da rahatlatıcı başka bir dokunuş deneyebilirsin. Ardından kendine sorarsın: Şu an ne duymaya ihtiyacım var?","Seçtiğin sözlerden çok, nasıl yaklaştığın önemlidir. Acı çekiyorum ifadesi fazla ağır geliyorsa, of, bu zor diyebilirsin. Elini göğsüne koymak hoşuna gitmiyorsa koluna koyabilir ya da yalnızca yavaşça nefes verebilirsin. Amaç acıdan kaçmak yerine onu fark etmek, yalnızlık duygusunu hafifletmek ve kendine anlayış göstermektir. Uygulama yaklaşık iki dakika sürer. Sorunu çözmez ama onunla yüzleşebilmek için biraz sakinleşmene yardımcı olabilir."],deeper:[{heading:"Neden destekleyici dokunuş?",paragraphs:["Neff rahatlatıcı bir dokunuş önerir. Çünkü bebeklikten itibaren, sıcak ve nazik temas insanı yatıştırmanın en temel yollarından biridir. Denemek için mutlaka işe yarayacağına inanman gerekmez. Pek çok kişi elini göğsüne koyduğunda ya da kolunu hafifçe kavradığında, nazik sözleri daha somut hisseder.","Dokunmak sana güvenli ya da hoş gelmiyorsa bu adımı geç. Bu uygulamada asıl önemli olan dikkatini nasıl yönelttiğin ve kendine nasıl konuştuğundur."],visual:{kind:"compare",title:"Canın yandığında nasıl karşılık verirsin?",left:{label:"Sırt çevirmek",items:["Dikkatini dağıtmak, telefonda gezinmek ya da duyguyu fark etmeden devam etmek.","Kendine böyle hissetmemen gerektiğini söylemek.","Yaptığın hatayı zihninde tekrar tekrar yaşamak."]},right:{label:"Yüzünü dönmek",items:["Adını koymak: Bu zor.","Başkalarının da böyle hissettiğini hatırlamak.","Kendine nazik bir söz söylemek ya da rahatlatıcı bir hareket yapmak."]},note:"Öz şefkat molasının yaklaşımını kendi sözlerimizle özetledik."}},{heading:"Araştırma ne söylüyor",paragraphs:["Öz şefkat molası, Neff ve psikolog Christopher Germer’in geliştirdiği sekiz haftalık Farkındalıklı Öz Şefkat programının bir parçasıdır. Yetişkinlerle yaptıkları randomize çalışmada programa katılanlar bekleme listesindekilerle karşılaştırıldı. Katılanlarda öz şefkat, farkındalık, başkalarına şefkat ve yaşam doyumu daha fazla arttı. Depresyon, kaygı ve stres daha fazla azaldı. Kazanımlar altı ay ve bir yıl sonraki takiplerde de sürdü.","Çalışma küçüktü ve programı geliştirenler tarafından yürütüldü. Karşılaştırma grubu başka bir kursa katılmıyor, bekleme listesinde duruyordu. İki dakikalık mola tek başına sınanmadı. Bu nedenle onu, umut veren ama kesinleşmemiş bulgulara sahip bir programın kullanışlı bir parçası olarak görebiliriz."]},{heading:"Eski acılar canlanırsa",paragraphs:["Bazen kendine nazik davranmak eski acıları canlandırır. Soğuk ellerin ısınırken önce sızlaması gibi. Bu, uygulamayı yanlış yaptığın anlamına gelmez. Süreyi kısalt, gözlerini aç, ayaklarının yere temasını hisset. İstersen durup gündelik bir şey yap. Acı veren anılar yoğun biçimde gelmeye devam ediyorsa ya da travma veya istismarla bağlantılıysa, tek başına devam etmek için kendini zorlama. Bu alanda yetkin bir terapistten destek al."]}],example:{title:"Tomás, 45, otobüs şoförü",text:"Bir yolcu, Tomás’ın kapıları üzerine kapattığını söyleyerek resmî şikâyette bulundu. Tomás yolcuyu görmemişti. Mola boyunca bunu düşündükçe midesi bulandı. Garaj kantininde otururken ilk kez öz şefkat molasını denedi. İçinden, bu çok stresli, dedi. Sonra tanıdığı her şoförün bir noktada şikâyet aldığını hatırladı. Elini önkoluna koydu. Bu, göğsüne koymaktan daha doğal geldi. Neyi duymaya ihtiyacı olduğunu sordu. Yanıt basitti: Dikkatlisin ve kontrol alışkanlığını daha sağlam hâle getirebilirsin. İçindeki düğüm kaybolmadı ama gevşedi. Amirine sakin bir yanıt yazdı. Bir değişiklik de ekledi: Kalabalık duraklarda kapıları kapatmadan önce aynayı bir kez daha kontrol edecekti."},practice:["Bugün seni biraz strese sokan bir durumu hatırla. Bedenindeki etkisini hafifçe hisset.","İçinden üç cümle söyle. İlki acını anlatsın, ikincisi başkalarının da böyle hissettiğini hatırlatsın, üçüncüsü kendin için nazik bir dilek olsun.","İyi geliyorsa rahatlatıcı bir dokunuş ekle. Ardından şimdi neye ihtiyacın olduğunu bir satırla yaz."],reflection:"Zor bir anda hangi sözcükler sana hem nazik hem inandırıcı gelir?",question:"Öz şefkat molasının sırası nedir?",options:["Acıyı kabul et, başkalarının da benzer şeyler yaşadığını hatırla, kendine nazik davran.","Önce sorunu çöz, sonra kendini daha iyi hissetmeye çalış.","His geçene kadar başarılarını say."],correct:0,feedback:"Mola, Neff’in üç bileşenini izler: Acıyı fark etmek, ortak insanlığı hatırlamak, kendine nazik davranmak. Sorunla yüzleşmek için sakinleşmene yardımcı olur. Sorunu ele almanın yerini tutmaz.",takeaway:"Acını fark etmek için ayırdığın iki dakika, onunla başa çıkmanı kolaylaştırabilir.",sources:["compassion-neff-exercises","compassion-mindful-self-compassion-rct","compassion-neff-definition"],visual:{kind:"steps",title:"Öz şefkat molası",steps:[{label:"Adını koy",text:"Canım yanıyor. Bu çok stresli. Of, zor."},{label:"Başkalarını hatırla",text:"Başkaları da böyle hissediyor. Yalnız değilim."},{label:"Nazik davran",text:"Elini göğsüne ya da koluna koy ve kendine nazik davranmayı dile."},{label:"Sor",text:"Şu an neyi duymaya ya da yapmaya ihtiyacım var?"}],note:"Kristin Neff’in uygulamasından kendi sözlerimizle aktarıldı; sana doğal gelen ifadeleri seç."},technique:{name:"Öz şefkat molası",origin:"Kristin Neff · Self-Compassion (2011); Christopher Germer ile Farkındalıklı Öz Şefkat programı",steps:["Şu anda sana stres ya da acı veren bir durumu aklına getir. Duygunu hafifçe hisset.","Acını sade sözlerle kabul et: Canım yanıyor ya da bu zor.","Zorlanmanın insan olmanın bir parçası olduğunu, başkalarının da böyle hissettiğini hatırla.","Elini kalbine ya da teselli edici başka bir yere koy ve sıcaklığını hisset.","Kendin için nazik bir dilek söyle. Ya da ne duymaya ihtiyacın olduğunu sor ve o sözü kendine söyle."],evidence:"Mola, Farkındalıklı Öz Şefkat programının bir parçasıdır. Program, küçük bir randomize çalışmada bekleme listesine göre fayda gösterdi. Katılımcılar bir yıla kadar takip edildi. Kısa mola tek başına bir araştırmada sınanmadı.",sourceId:"compassion-neff-exercises"},photo:{id:"1499209974431-9dddcece7f88",alt:"Batan güneşe doğru kollarını açan biri"}},{id:"compassion-4",title:"Tehdit, başarma isteği ve yatışma",minutes:10,goal:"Paul Gilbert’in üç sistem modeliyle hangi sistemin baskın olduğunu fark et. Yatışma sistemini nasıl devreye sokabileceğini öğren.",reading:["İngiliz psikolog Paul Gilbert, yoğun utanç yaşayan ve kendini çok eleştiren pek çok kişinin terapinin mantığını anladığını gördü. Ama bu kişiler yine de rahatlamakta ve güvende hissetmekte zorlanıyordu. Bunun üzerine şefkat odaklı terapiyi (ŞOT) geliştirdi. Modelinde üç duygu sistemi vardır. Tehdit sistemi tehlikeyi algılar. Kaygı, öfke ya da tiksintiyle karşılık verir; seni savaşmaya, kaçmaya ya da donup kalmaya yöneltir. Başarma isteği sistemi ödül ve başarı arar. Heyecan ve istek uyandırır. Yatışma sistemi ise tehdit altında olmadığında ve bir şeyin peşinden koşmadığında güven, hoşnutluk ve bağ kurma duygusu sağlar.","Üç sistem de yararlıdır. Sorun, aralarındaki denge bozulduğunda başlar. Sert bir iç eleştiri, tehdit sistemini sürekli açık tutar. Pek çok insan bundan daha çok çalışarak kaçmaya uğraşır: Yeterince başarılı olursam sonunda güvende hissederim. Ama bu rahatlık genellikle uzun sürmez. Tehdit sisteminin aradığı şey başarı değildir. Gilbert’e göre kendine ve başkalarına şefkat göstermek, yatışma sistemini güçlendirerek tehdit duygusunu içeriden sakinleştirebilir. Nefesi yavaşlatmak, kendine sıcak bir sesle konuşmak, nazik bir yüzü gözünde canlandırmak ve önemsendiğini hissetmek bu sisteme ulaşmanın yollarıdır."],deeper:[{heading:"Her sistem nasıl hissettirir",paragraphs:["Her sistemin bedeninde ve düşüncelerinde nasıl kendini gösterdiğini öğrenmek yardımcı olur. Bir sistemi yalnızca mantık yürüterek kapatamazsın. Ama hangisinin baskın olduğunu fark edip hangi sistemi destekleyeceğini seçebilirsin."],visual:{kind:"table",title:"Üç sisteme bir bakış",columns:["Sistem","Nasıl hissettirir","Tipik düşünce","Ne yardımcı olur"],rows:[["Tehdit","Göğüste sıkışma, hızlı kalp atışı, öfke ya da korku","Bir şey ters gidiyor. Güvende değilim.","Yavaşlamak, güvende olduğunu hatırlatan işaretler, nazik bir ses"],["Başarma isteği","Heyecan, istek, huzursuzluk","Daha fazlasını almam ya da başarmam gerek.","Keyfini çıkarmak, sonra bilinçli olarak ara vermek"],["Yatışma","Yavaşlayan nefes, sıcaklık, rahatlık","Şu an iyiyim.","Bağ kurmak, dinlenmek, şefkat alıştırmaları"]],note:"Paul Gilbert’in modelini temel aldık. Örnekleri biz sadeleştirdik."}},{heading:"Araştırma ne söylüyor",paragraphs:["Üç sistem modeli, evrim ve beyin araştırmalarından yararlanan bir klinik çerçevedir. Beyin devrelerinin tam bir haritası değildir. Gilbert de bunu basitleştirilmiş bir model olarak sunar. ŞOT’un tedavi olarak etkililiğine ilişkin bulgular artıyor, ancak araştırmalar hâlâ erken aşamada.","Şefkat uygulamalarına ilişkin araştırmalar, etkinin büyüklüğü hakkında fikir verir. Sevgi-şefkat ve şefkat meditasyonlarını inceleyen bir meta-analizde, randomize çalışmalarda bu uygulamaların günlük olumlu duyguları bekleme listelerine göre artırdığı bulundu. Sevgi-şefkate odaklanan uygulamalarda etki daha belirgindi. Şefkate odaklananların etki tahmini daha küçüktü ve istatistiksel olarak kesin değildi."],visual:{kind:"bars",title:"Şefkat meditasyonu ve günlük olumlu duygular",bars:[{label:"Sevgi-şefkat odaklı",value:.424,display:"g = 0,424"},{label:"Şefkat odaklı",value:.286,display:"g = 0,286"}],note:"1.759 kişilik 24 çalışmanın meta-analizinden standartlaştırılmış etki büyüklükleri. Şefkat odaklı tahminin güven aralığı sıfırı içeriyordu ve çalışmaların %38,9’unda yanlılık riski yüksekti. Bu, ŞOT’un ya da bu dersin bir sınaması değildir.",sourceId:"meditation-lovingkindness"}}],example:{title:"Mei, 38, muhasebeci",text:"Yılın çeyreği sona ererken Mei, üç gece üst üste gece yarısında e-postalara yanıt verdiğini fark etti. Gilbert’in modelinden yola çıkarak kendine sordu: Şu an hangi sistem beni yönlendiriyor? Başarma isteği açıkça baskındı. Ama altında bir tehdit duygusu vardı: Bir hatayı gözden kaçırırsa herkesin onun yetersiz olduğunu anlayacağı korkusu. Daha fazla çalışmak yanlış sistemi besliyordu. O akşam beş dakikalık bir zamanlayıcı kurdu. Her nefes verişi alışından biraz uzun olacak şekilde nefesini yavaşlattı. Kendine, eskiden birlikte çalıştığı anlayışlı yöneticinin tonuyla konuştu. İlk dakika saçma geldi. Ama sonunda omuzları gevşemişti. Bilgisayarını saat onda kapattı. Sabah için üç işi not etti ve o hafta ilk kez bu kadar iyi uyudu."},practice:["Bugün üç kez dur. Şu an hangi sistemin baskın olduğunu sor: Tehdit, başarma isteği ya da yatışma?","Tehditse, bir dakika boyunca nefesini yavaşlat; her verişin alışından biraz uzun olsun.","Gerçek ya da hayalî, sıcak ve bilge birini gözünde canlandır. Onun sana söyleyebileceği nazik bir cümle düşün."],reflection:"Tehdit sistemin devreye girdiğinde genellikle onu sakinleştirmeye mi yoksa daha çok başarıyla ondan kaçmaya mı çalışırsın?",question:"Gilbert’in modelinde hangi sistem tehdit sistemini içeriden sakinleştirmeye yardımcı olur?",options:["Güven, bağ ve şefkatle beslenen yatışma sistemi.","Daha çok başarıya ulaşarak başarma isteği sistemi.","Her tehlikeye karşı plan yaparak tehdit sisteminin kendisi."],correct:0,feedback:"Başarı bir süre dikkatini tehdit duygusundan uzaklaştırabilir. Ama Gilbert’in modelinde güven hissini sağlayan, sıcaklık ve bağ kurmayla desteklenen yatışma sistemidir.",takeaway:"Daha çok başarmak, güvensizlik hissini her zaman gidermez. Kendini yatıştırmayı öğrenebilirsin.",sources:["compassion-gilbert-cft","compassion-gilbert-mind","meditation-lovingkindness"],visual:{kind:"cycle",title:"Üç duygu sistemi",center:"Denge",nodes:[{label:"Tehdit",text:"Tehlikeyi algılar: kaygı, öfke, öz eleştiri. Seni korur ama dikkati daraltır."},{label:"Başarma isteği",text:"Ödül ve hedeflerin peşinden gider: İstek, heyecan, başarı."},{label:"Yatışma",text:"Güven, hoşnutluk ve bağ kurma sağlar. Tehdit duygusunu sakinleştirir, başarma isteğini dengeler."}],note:"Paul Gilbert’in şefkat odaklı terapisine göre. Sistemler birbirini etkiler ve hiçbiri kötü değildir."},technique:{name:"Yatıştırıcı ritimli nefes ve şefkatli benlik",origin:"Paul Gilbert · The Compassionate Mind (2009)",steps:["Ayakların yerde, rahat otur ve zorlamadan nefesinin biraz yavaşlamasına izin ver.","Her verişin alışından biraz uzun olsun ve nazik, dengeli bir ritim bul.","Yüz kaslarını gevşet. İyi geliyorsa yüzüne hafif, dostça bir ifade ver.","Kendini en bilge ve en nazik hâlinde hayal et: sakin, güçlü ve şefkatli. O hâlinin nasıl oturup konuşacağına dikkat et.","Bu hâlinle, zorlanan yanına bir cümle söyle."],evidence:"Bunlar şefkat odaklı terapinin temel alıştırmalarıdır. ŞOT, henüz erken ama umut veren bulgulara sahip bir yaklaşımdır. Bu alıştırmalar burada tek başına bir kişisel çalışma olarak sınanmadı. Terapinin yerini tutmazlar.",sourceId:"compassion-gilbert-mind"},photo:{id:"1441974231531-c6227db76b6e",alt:"Dingin bir ormanın içinden süzülen gün ışığı"}},{id:"compassion-5",title:"Utanç ve suçluluk",minutes:10,goal:"Utancı suçluluktan ayır. Utanç duyduğunda saklanmak yerine onunla başa çıkmak için dört adımı kullan.",reading:["Araştırmacı Brené Brown, utanç ile suçluluğu basitçe ayırır. Suçluluk yaptığın şeyle ilgilidir: Kötü bir şey yaptım. Utanç kendinle ilgilidir: Ben kötüyüm. Bu ayrım, psikolog June Tangney ve arkadaşlarının araştırmalarına dayanır. Suçluluk belirli bir davranışa odaklanır. Seni özür dilemeye, yaptığını kabul etmeye ve zararı telafi etmeye yöneltebilir. Utanç ise kişiliğinin tamamını hedef alır. Saklanma, inkâr etme ya da öfkeyle karşılık verme isteği doğurur. Araştırmalarda gelişme çabasından çok öfke, savunmaya geçme ve sıkıntıyla ilişkilidir. Suçluluk rahatsız edici olsa da yararlı olabilir. Utanç ise çoğunlukla seni değersiz hissettirir.","Brown, görüşmelere dayanan araştırmasından utançla başa çıkma becerileri geliştirdi. Amaç hiç utanç duymamak değildir; bunu kimse başaramaz. Amaç, utancı yaşarken kendini kaybetmemektir. Dört bileşen önerir. Önce utancı ve onu tetikleyen durumları fark et. Bedeninde nasıl hissedildiğine de bak. Sonra utancın arkasındaki mesajları ve beklentileri sorgula: Gerçeğe uyuyorlar mı? Güvendiğin biriyle iletişim kur ve olanları anlat. Son olarak utancı açıkça dile getir. Sessizce seni etkilemesine izin verme. Öz şefkat her adımı destekler. Kendin hakkında genel bir hüküm vermek yerine, ele alabileceğin belirli bir olaya bakmanı sağlar."],deeper:[{heading:"Dört beceriyi uygulamak",paragraphs:["Brown’ın çalışması utançla başa çıkmayı değişmez bir özellik değil, geliştirilebilen beceriler olarak ele alır. Aşağıdaki adımlarda dört bileşeni kendi sözlerimizle anlatıyoruz. Bunları kusursuz bir sırayla uygulaman gerekmez. Utancı fark etmek genellikle en zor ve en önemli adımdır."],visual:{kind:"steps",title:"Utançla başa çıkmak için dört beceri",steps:[{label:"Fark et",text:"Utanç duyduğunda bedeninde olanları ve utancı tetikleyen durumları fark et."},{label:"Sorgula",text:"Bunların kimin beklentileri olduğunu ve gerçekçi olup olmadığını sor."},{label:"İletişim kur",text:"Olanı saklamak yerine güvendiğin birine anlat."},{label:"Utancı dile getir",text:"Duyguyu yüksek sesle adlandır: bundan utanıyorum."}],note:"Brené Brown’ın utançla başa çıkma kuramını temel aldık. İfadeler bize ait."}},{heading:"Suçluluk ne zaman yardımcı olur?",paragraphs:["Tangney’nin araştırmasında suçluluğa yatkın kişiler daha çok empati gösterme ve zararı telafi etme eğilimindeydi. Utanca yatkın kişiler ise daha çok saklanıyor, savunmaya geçerek öfkeleniyor ve başkalarını suçluyordu. Suçluluk yine de hoş bir duygu değildir. Sebep olmadığın şeyler için yoğun suçluluk duymak da ayrı bir sorundur. Ama yaptığın hatayla orantılı, açık bir suçluluk duygusu vicdanının çalıştığını gösterebilir.","Öz şefkat, utançtan sağlıklı bir suçluluk duygusuna geçmene yardımcı olabilir. Kendini bütünüyle savunmak zorunda hissetmediğinde, yaptığın davranışa bakıp nasıl telafi edebileceğini düşünebilirsin."]},{heading:"Ne zaman daha fazla destek almalı?",paragraphs:["Utanç geçmiyorsa, farklı durumlarda sürekli karşına çıkıyorsa ya da travma veya istismarla bağlantılıysa dört adım yeterli olmayabilir. Bu alanda yetkin bir terapistten destek al. Şefkat odaklı terapi, yoğun utanç yaşayan kişiler düşünülerek geliştirildi. Utanca kendine zarar verme düşünceleri eşlik ediyorsa hemen 112’yi ya da bir kriz hattını ara."]}],example:{title:"Jonas, 31, öğretmen",text:"Jonas, sınıfın önünde bir öğrencisine ters çıktı. Çocuk dersin geri kalanında hiç konuşmadı. Öğleye doğru Jonas’ın aklındaki, bunu kötü yönettim, düşüncesi değişmişti: Berbat bir öğretmenim, bu işi yapmamalıyım. Yüzünün kızardığını ve öğretmenler odasına gitmek istemediğini fark etti. Sonra düşüncesini sorguladı. Az uyuduğu bir günde yaşanan tek bir sert çıkış, altı yıllık meslek hayatını geçersiz kılmıyordu. Güvendiği bir meslektaşına olanları anlattı. Sesli anlatınca iki şeyi ayırabildi: Kötü bir öğretmen değildi ama telafi etmesi gereken bir şey yapmıştı. Ertesi sabah öğrenciyle yalnız konuşup özür diledi ve nasıl olduğunu sordu."},practice:["Yakın zamanda kendini kötü hissettiğin bir anı hatırla. Aklından geçen cümleyi aynen yaz.","Cümle belirli bir davranıştan duyduğun suçluluğu mu, yoksa kendine yönelik utancı mı anlatıyor? Utanç içeren cümleyi yalnızca davranışı anlatacak şekilde yeniden yaz.","Bu davranışı telafi etmen gerekip gerekmediğini düşün. Gerekiyorsa özür dilemek ya da bir şeyi düzeltmek gibi, atabileceğin en küçük dürüst adımı belirle."],reflection:"Utanç yüzünden saklanmak istediğinde kiminle konuşabilirsin?",question:"Hangi ifade utanç değil, suçluluktur?",options:["Ona kaba davrandım ve özür dilemem gerekiyor.","Korkunç bir insanım.","Her şeyi hep mahvediyorum."],correct:0,feedback:"Suçluluk belirli bir davranışa odaklanır ve onu telafi etmeye yöneltir. Diğer iki cümle kişiliğin tamamını yargılar. Utanç böyle konuşur.",takeaway:"Kendine bir etiket koymak yerine ne yaptığını söyle. Telafi edebildiğini telafi et.",sources:["compassion-brown-shame-resilience","compassion-brown-practice","compassion-tangney-moral-emotions","compassion-gilbert-cft"],visual:{kind:"compare",title:"Utanç mı, suçluluk mu?",left:{label:"Utanç",items:["Ben kötüyüm.","Kişiliğin tamamına odaklanır.","Seni saklanmaya, inkâr etmeye ya da başkalarını suçlamaya iter.","Savunmaya geçerek öfkelenme ve sıkıntıyla ilişkilidir."]},right:{label:"Suçluluk",items:["Kötü bir şey yaptım.","Belirli bir eyleme odaklanır.","Özür dilemeye ve zararı telafi etmeye yöneltir.","Empatiyle ilişkili."]},note:"June Tangney’nin araştırmasına ve Brené Brown’ın ayrımına göre. Aşırı suçluluk da zararlı olabilir."},technique:{name:"Utançla başa çıkma",origin:"Brené Brown · I Thought It Was Just Me (2007)",steps:["Savunmasız, küçük ya da değersiz hissettiğinde duygunun adını koy: Utanç.","Bedeninde nerede hissettiğini ve hangi durumun utancı tetiklediğini fark et.","Düşünceyi sorgula: Bu kimin beklentisi? Gerçekçi mi?","Güvendiğin birine ne olduğunu anlat.","Utanç hakkında açıkça konuş ve ihtiyacın olanı iste."],evidence:"Utançla başa çıkma kuramı, nitel görüşmelere dayanan araştırmadan gelir. Bu araştırma bir müdahaleyi sınamak yerine tekrarlanan deneyimleri anlatır. Kuramın dayandığı utanç ve suçluluk ayrımı, ahlaki duygular üzerine araştırmalarla güçlü biçimde desteklenir.",sourceId:"compassion-brown-practice"},photo:{id:"1544027993-37dbfe43562a",alt:"Birbirine uzanan iki el"}},{id:"compassion-6",title:"Kendine mektup yaz, sorumluluğunu al",minutes:12,goal:"Pişman olduğun ya da kendinde sevmediğin bir şey için şefkatli bir mektup yaz. Sonunda sorumluluğunu alacağın bir adım belirle.",reading:["Neff’in mektup alıştırmasında, seni koşulsuz seven hayalî bir arkadaşın gözünden kendine yazarsın. Konu, kendinle ilgili kötü hissettiğin bir şeydir: Bir hata, alışkanlık ya da özellik. Bu arkadaş, zorlandığın şey dahil bütün güçlü ve zayıf yanlarını bilir. Geçmişinin ve koşullarının seni nasıl etkilediğini anlar. Hatalarını görmezden gelmeden sana nazik davranır. Onun sesiyle yazmak, içindeki eleştirel sesten biraz uzaklaşmanı sağlar. Olanları tehdit sisteminin anlattığından daha dengeli görmene de yardımcı olabilir.","Şefkatli bir mektup bahane üretmez. Seni seven arkadaşın, sana ya da başkalarına zarar veren davranışını değiştirmeni de isterdi. Sorumluluk burada devreye girer. Neff bunu öz şefkatin güçlü, koruyucu yönü olarak tanımlar. Kendini reddettiğin için değil, iyiliğini önemsediğin için kendini korur, sınır koyar ve hedeflerine yönelirsin. Öz şefkatin yatıştırıcı yönü teselli eder ve kabul eder. Koruyucu yönü harekete geçer. Bu yüzden mektubun sonunda arkadaşın sana somut bir soru sorsun: Bütün bunları düşününce neyi farklı yapabilirsin? Hangi destek bunu yapmanı kolaylaştırır?"],deeper:[{heading:"Mektup nasıl yazılır",paragraphs:["Kimsenin seni bölmeyeceği bir yerde on beş dakika ayır. Mümkünse elle yaz. Cümleleri güzelleştirmek için düzeltme yapma. Sonra mektubu bir kenara bırak. Daha sonra tekrar okuyup sözlerin sende yarattığı etkiye dikkat et."],visual:{kind:"steps",title:"Şefkatli bir mektup yazmak",steps:[{label:"Seç",text:"Kendini kötü hissettiğin tek bir konuyu seç. Bütün hayat hikâyeni ele alman gerekmez."},{label:"Hayal et",text:"Seni koşulsuz seven ve yaşadığın koşulları bilen bir arkadaş hayal et."},{label:"Yaz",text:"Arkadaşın seni nasıl anlıyor, senin için ne hissediyor, neler diliyor? Onun ağzından yaz."},{label:"Sor",text:"Tek bir pratik değişiklik ve ihtiyaç duyacağın destekle bitir."},{label:"Tekrar oku",text:"Mektubu bir kenara bırak. Sonra tekrar oku ve sende nasıl bir etki yarattığına bak."}],note:"Kristin Neff’in mektup alıştırmasından kendi sözlerimizle aktarıldı."}},{heading:"Yatıştırmak ve korumak",paragraphs:["Çoğumuz bu yönlerden birine daha çok başvurur. Bazıları kendini iyi teselli eder ama hiç sınır koymaz. Bazıları değişmek için kendini çok zorlar ama hiç dinlenmez. Neff’e göre ikisi de kendini gözetmenin bir yoludur. Yalnızca yatıştıran bir ebeveyn de yalnızca zorlayan bir ebeveyn de çocuğun ihtiyacının ancak yarısını karşılar.","Şefkatle sorumluluk almak, iki yönü de kullanmaktır. Verdiğin zararı dürüstçe kabul eder, rahatsızlığı utanca kapılmadan hissedersin. Telafi edebildiğini telafi eder ve bir değişiklik planlarsın. Breines ve Chen’in bulguları da buna uyuyor. Ahlaki bir hatalarına öz şefkatle bakan kişiler, hatayı telafi etmeye ve tekrarlamamaya daha istekliydi."]},{heading:"Araştırma ne söylüyor",paragraphs:["Mektup, Farkındalıklı Öz Şefkat programının uygulamalarından biridir. Programın randomize çalışmasında, bekleme listesine göre faydaların bir yıllık takibe kadar sürdüğü bulundu. Öz şefkat müdahalelerine ilişkin 27 randomize çalışmanın meta-analizinde, olumsuz düşüncelere tekrar tekrar takılma, kendini eleştirme, depresyon ve kaygı gibi sonuçlarda iyileşme görüldü. Mektup tek başına sınanmadı. Araştırmaların çoğu hâlâ küçük çalışmalardan oluşuyor. Bu nedenle mektubu kanıtlanmış bir tedavi olarak değil, umut veren bir uygulama olarak ele alabiliriz."]}],example:{title:"Rosa, 52, dükkân sahibi",text:"Rosa yıllardır para işlerini yönetme biçiminden nefret ediyordu. Bankadan gelen mektupları açmıyor, birikmelerine izin veriyordu. Onu iyi tanıyan hayalî bir arkadaşın ağzından kendine mektup yazdı. Arkadaşı, faturaların evde bağrışmaya yol açtığı bir çocukluk geçirdiğini anlıyordu. Mektuplardan kaçınmak bir zamanlar onu korumuştu. Ama arkadaşı nazikçe ve açıkça şunu da söyledi: Biriken mektuplar artık ona zarar veriyordu. Sürekli korku içinde yaşamaktan daha iyisini hak ediyordu. Mektubun sonunda bir değişiklik önerdi. Rosa her cumartesi saat dokuzda, kahvesini alıp o hafta gelen bütün mektupları açmayı seçti. İlk seferinde oğlundan yanında oturmasını istedi. Mektubu bir hafta sonra tekrar okudu. Mektup yığını azalmış, korkusu da biraz hafiflemişti."},practice:["Kendinle ilgili kötü hissettiğin bir şey seç ve on beş dakikalık bir zamanlayıcı kur.","Seni koşulsuz seven ve yaşadığın koşulları bilen bir arkadaşın gözünden kendine mektup yaz.","Mektubun sonunda sorumluluğunu alacağın somut bir değişiklik ve isteyeceğin desteği yaz. Sonra bu değişiklik için takviminde zaman ayır."],reflection:"Öz şefkatin yatıştırıcı yönüne mi, koruyucu yönüne mi daha çok başvuruyorsun? Diğeri sana ne katabilir?",question:"Bu derste öz şefkatin sorumluluk almayı desteklemesini sağlayan nedir?",options:["Tesellinin, verilen zararı dürüstçe kabul etmek, telafi etmek ve somut bir değişiklik yapmakla birleşmesi.","Yaptığın hiçbir şey için kötü hissetmemek.","Hatayı bir daha yapmayacak kadar kendini cezalandırmak."],correct:0,feedback:"Öz şefkatin yatıştırıcı ve koruyucu yönleri birlikte çalışır. Teselli, utanca kapılmanı önler. Koruyucu yön ise öğrendiklerini telafiye ve değişime dönüştürür.",takeaway:"Kendine şefkat göstermek, doğruyu söyleyip gereken adımı atmana yardım etmektir.",sources:["compassion-neff-exercises","compassion-neff-definition","compassion-mindful-self-compassion-rct","compassion-ferrari","state-self-compassion-motivation","self-compassion"],visual:{kind:"table",title:"Öz şefkatin yatıştırıcı ve koruyucu yönleri",columns:["Soru","Yatıştırıcı","Koruyucu"],rows:[["Ne yapar","Teselli eder, yatıştırır, kabul eder","Korur, sınır koyar, hedefler için harekete geçer"],["Örnek cümle","Bu zor ve senin yanındayım.","Bu kabul edilemez. Bunun için bir şey yapacağım."],["Ne zaman gerekebilir?","Canın yanıyor ya da yas tutuyorsun.","Sınırın aşıldığında ya da bir hedef senin için önemli olduğunda."],["Diğeri olmadan","Sorundan kaçınmaya dönüşebilir.","Sertliğe dönüşebilir."]],note:"Öz şefkatin yatıştırıcı ve koruyucu yönleri, Kristin Neff’in tanımına dayanır. Son satır bizim yorumumuzdur."},technique:{name:"Şefkatli mektup",origin:"Kristin Neff · Self-Compassion (2011)",steps:["Kendinle ilgili seni yetersiz hissettiren ya da utandıran bir konu seç.","Seni koşulsuz seven ve kabul eden bir arkadaş hayal et. Güçlü ve zayıf yanlarını bilsin, geçmişini anlasın.","O arkadaşın bakış açısından, zorlandığın şey hakkında kendine bir mektup yaz.","Arkadaşın acını kabul etsin, herkesin kusurlu olduğunu hatırlatsın ve nazikçe değişmene neyin yardımcı olabileceğini önersin.","Mektubu bir kenara koy, sonra geri dön ve yavaşça tekrar oku."],evidence:"Mektup, küçük bir randomize çalışmada bekleme listesine göre fayda gösteren Farkındalıklı Öz Şefkat programının bir parçasıdır. Mektup tek başına sınanmadı.",sourceId:"compassion-neff-exercises"},photo:{id:"1455390582262-044cdead277a",alt:"Kalemle bir deftere yazan bir el"}}]},Ne=Object.freeze(Object.defineProperty({__proto__:null,COURSE:Re,SOURCES:qe},Symbol.toStringTag,{value:"Module"})),p=[xe,De,Oe,Ee,Ye,Ne],je=p.map(e=>e.COURSE).filter(e=>e.lessons.length>0),Ge=p.flatMap(e=>e.SOURCES),Fe=[{id:"turning-day-commitment-contract",title:"Giné, Karlan & Zinman · 2010 · Sigarayı bırakmak için taahhüt sözleşmesi",url:"https://www.aeaweb.org/articles?id=10.1257%2Fapp.2.4.213",type:"research",finding:"Sigara içenlere bir tasarruf hesabı önerildi: altı ay boyunca para yatırıyor, ardından nikotin ve kotinin için idrar testine giriyorlardı. Testi geçenlerin parası geri veriliyor, geçemeyenlerinki bir hayır kurumuna gidiyordu. Hesap önerilenlerin %11’i katıldı. Hesap açma seçeneği rastgele sunulan sigara içenlerin altı aylık testi geçme olasılığı 3 yüzde puan daha yüksekti ve fark 12. aydaki sürpriz testlerde de sürdü.",limitation:"Yalnızca özet okundu. Tek bir davranış (sigara) için yapılan bir saha deneyidir; katılım düşüktü ve ortalama etki küçüktü. Bir taahhüt aracının bazı insanlara yardımcı olabileceğini gösterir, herkese uyduğunu değil."}],Ue={"turning-day-1":{deeper:[{heading:"Yeni bir başlangıç neden işe yarar?",paragraphs:["Dai, Milkman ve Riis etkiyi şöyle açıklıyor: yeni bir hafta, yıl ya da başlangıç saydığın bir gün, geçmişle bugün arasına bir sınır koyar. “Eski sen”in hataları biraz daha uzakta görünür. Yeniden denemek, aynı başarısızlığı tekrarlamak yerine yeni bir sayfa açmak gibi gelir. Deneylerinde aynı tarih, bir başlangıç olarak sunulduğunda daha fazla kişi o gün için hedef hatırlatıcısı seçti.","Aynı araştırma bu etkinin sınırını da gösteriyor: başlama isteği gerçekten artıyor ama kısa sürüyor. Bu isteği seni sürekli taşıyacak bir güçten çok, ilk adımı kolaylaştıran bir destek gibi düşün. Bu yüzden bugün enerjini küçük ve somut bir şeye ayırmanı, yarın da tekrarlamanı öneriyoruz."],visual:{kind:"compare",title:"Başlangıç gününü beklemek ya da seçmek",left:{label:"Pazartesiyi beklemek",items:["“Haftaya düzgünce başlayacağım.”","İstek birikir, kullanılmadan sönüp gider.","Bir günü kaçırmak, bir sonraki pazartesiyi beklemek demektir."]},right:{label:"Bugünü işaretlemek",items:["“Bugün başlangıç günüm.”","Başlama isteği, küçük ve gerçek bir adıma dönüşür.","Bir günü kaçırmak, yarın sabah yeniden başlamak demektir."]},note:"Deneylerde bir günü yeni başlangıç olarak sunmak başlama isteğini artırdı; ne kadar süreceği bundan sonra ne yaptığına bağlı."}},{heading:"Başlangıç gününde sık yapılan hatalar",paragraphs:["İlk hata, her şeyi aynı anda değiştirmeye çalışmak: aynı sabah yeni bir diyet, spor planı ve iş düzenine başlamak. Hepsi sınırlı enerjine ihtiyaç duyar. Biri aksayınca hepsi boşa gitmiş gibi gelebilir. Bir gün için tek alan yeter.","İkinci hata, sana önemli gelen yerine kulağa etkileyici gelen bir alan seçmek. Kendi nedenin, yorgun bir öğleden sonra seni daha iyi destekleyebilir: “Çocuklarımla yürüyüşte onlara yetişmek istiyorum.” Başkalarının beklentisinden gelen bir neden daha çabuk etkisini kaybedebilir: “Herkes yapmam gerektiğini söylüyor.” Nedenini sesli söylediğinde içine sinmiyorsa, biraz daha düşün."]}],example:{title:"Dana, 34, vardiyalı hemşire",text:"Dana aylardır “pazartesi başlıyorum” diyordu ama vardiyaları yüzünden pazartesi çoğu zaman gece nöbetine denk geliyordu. İzinli bir çarşamba günü defterine tarihi yazdı, yanına da “Başlangıç günüm” notunu düştü. Biraz tuhaf hissetti. Kafasındaki uzun listeden (uyku, yemek yapmak, para, kız kardeşini aramak) yalnızca birini seçti: hareket. Nedenini bulması birkaç deneme aldı: “Çünkü on iki saatlik vardiyadan sonra sırtımın ağrımasını istemiyorum.” Bu neden içine sindi. Bunu telefonuna günün tek kararı olarak ekledi ve başka büyük bir değişiklik yapmadı. Gün henüz bir dönüm noktası gibi hissettirmedi. Ama bir iş arkadaşı planlarını sorduğunda tek cümlede bir alan ve bir neden söyleyebildi; bu yeniydi."}},"turning-day-2":{deeper:[{heading:"Önceden plan yapmak neden yardımcı olur?",paragraphs:["Eğer-öyleyse planında, zor an gelmeden önce karar verirsin. Öğlen, sakin ve zihnin açıkken, akşam altıda yorgun olduğunda ne yapacağını belirlersin. Saat altı geldiğinde kendinle pazarlık etmen gerekmez. İşaret (“Yorgunum”), küçük bir eyleme (“Yalnızca on dakika”) önceden bağlanmıştır. Bu yüzden “eğer” kısmının somut olması işe yarar: belli bir saat, yer ya da fark edebileceğin bir duygu.","İyi bir plan, zor bir günde de yapabileceğin kadar küçüktür. “Yorgunsam yine de bütün antrenmanı yapacağım” sözü, yorgun hâlini pek hesaba katmaz. “Yorgunsam iki dakikalık hâlini yapacağım” ise o an gerçekten yapabileceğin bir plandır."]},{heading:"Sözünü tutmana yardımcı olacak düzenlemeler",paragraphs:["Taahhüt aracı, bugün yaptığın ve ileride vazgeçmeni zorlaştıran bir düzenlemedir. Bir arkadaşına söylemek kadar hafif olabilir. Para kaybetme ihtimali içermek gibi daha bağlayıcı da olabilir. Bir saha deneyinde sigara içenlere tasarruf hesabı açma seçeneği sunuldu. Altı ay para yatırıyor, sonra nikotin testine giriyorlardı. Testi geçenlere paraları geri veriliyor, geçemeyenlerin parası bir hayır kurumuna gidiyordu. Bu seçenek sunulanların yalnızca %11’i katıldı. Ama seçeneğin sunulduğu grupta testi geçme olasılığı 3 yüzde puan daha yüksekti. Fark, bir yıl sonraki sürpriz testlerde de sürdü.","Katılım düşük ve ortalama etki küçüktü. Sonuçları buna göre değerlendirmek gerekir: bu tür düzenlemeler bazı insanlara, bazı zamanlarda yardımcı olabilir. Yeni başlangıç araştırmasında, insanların bu tür sözleşmeler yaptığı stickK sitesindeki yeni taahhütler hafta başlarında arttı. Yıl başında artış daha da büyüktü. Bu fikir hoşuna gidiyorsa, sözünü tutmana yardımcı olacağını düşündüğün en hafif düzenlemeyle başla."],visual:{kind:"table",title:"Daha hafiften daha bağlayıcı düzenlemelere",columns:["Tür","Örnek","Vazgeçmenin bedeli"],rows:[["Söz","Destekleyici bir kişiye ne yapacağını ve ne zaman yapacağını söyle","Biraz mahcup edici bir konuşma"],["Erişimi zorlaştırma","Dikkatini dağıtan uygulamayı bir hafta boyunca telefonunun son ekranında bir klasöre koy","Birkaç fazladan dokunuş"],["Peşin ödeme","Bir derse önceden kaydolup ücretini öde","Ücreti kaybetmek"],["Sözleşme","Sözünü tutmazsan kaybedeceğin bir para","Depozitoyu kaybetmek"]],note:"Daha bağlayıcı olması, daha iyi olduğu anlamına gelmez. Seçtiğin düzenleme içine sinsin; sana ya da başka birine zarar vermesin."}}],example:{title:"Marcus, 41, depo sorumlusu",text:"Marcus o sabah sağlığı seçmişti: işten sonra kısa bir yürüyüş. Öğle arasında sandviççiye yürürken kendine onu gerçekten neyin durduracağını sordu. Dürüst cevap yağmur ya da zaman değildi. Kanepeydi ve “dinlenmeyi hak ettim” düşüncesiydi. Telefonuna şunu yazdı: “Yürüyüşten önce kanepeye oturursam, kalkıp yalnızca köşeye kadar gidip döneceğim.” Bir adım sayılmayacak kadar küçük geliyordu. Saat 6.15’te gerçekten oturdu ve düşünce tam zamanında geldi. Notu hatırladı, söylenerek köşeye kadar yürüdü. Sonra devam etti ve on iki dakika yürüdü. Ertesi gün köşeyi geçmedi ve bunu da bir adım olarak kabul etti."},sources:["turning-day-commitment-contract","fresh-start-effect"]},"turning-day-3":{deeper:[{heading:"Küçük başarılar neden önemlidir?",paragraphs:["İki dakikalık bir adımı “Bu sayılmaz, bunu herkes yapar” diyerek küçümsemek kolay. Ama öz yeterlik, adımın ne kadar etkileyici göründüğünden doğmaz. Bir şeye karar verip onu yapmış olmandan güç alır. Her seferinde, “Ben başladığım işi sürdürmem” düşüncesine karşı küçük ve somut bir kanıtın olur.","Yaptığın adımı yazmak önemli, çünkü hafızan her şeyi aynı ölçüde hatırlamaz. Zor bir akşamda kötü gidenleri kolay hatırlar, iyi gidenleri unutabilirsin. Yazılı bir “Bugün … yaptım” cümlesini yok saymak daha zordur. Zamanla bu notlar, yapabileceğine dair inancını destekleyen bir kayıt oluşturur."],visual:{kind:"cycle",title:"Küçük kanıt döngüsü",center:"Öz yeterlik",nodes:[{label:"Küçük adım",text:"Bitirebileceğin iki dakikalık bir eylem."},{label:"Kanıt",text:"Ne yaptığını yazarsın."},{label:"İnanç",text:"“Bunu yapabilirim” inancı biraz büyür."},{label:"Sonraki adım",text:"Yarınki adım biraz daha hafif gelir."}],note:"Bandura’nın başarı deneyimi fikrini anlatır; ölçülmüş bir etkiyi göstermez."}},{heading:"Sık yapılan hatalar",paragraphs:["En yaygın hata, ilk adımı fazla büyük tutmaktır. Adım iyi bir ruh hâli, boş bir saat ya da mükemmel koşullar gerektiriyorsa henüz bir ilk adım değildir. Vazgeçmek zor gelecek kadar küçült.","Bir başka hata, iki dakika sınırını mutlaka durman gereken bir kural ya da mutlaka aşman gereken bir hedef sanmaktır. İkisi de sorun değil: devam etmek istiyorsan devam et, durmak istiyorsan dur. Tek görev başlamak ve başladığını fark etmek."]}],example:{title:"Priya, 27, genç grafik tasarımcı",text:"Priya öğrenmeyi seçmişti: elle harf çizimini geliştirmek istiyordu ama her düşündüğünde bitmiş bir afiş hayal edip kendini geride hissediyordu. Öğleden sonra üçte, müşteri dosyalarıyla ilgilenirken verdiği arada iki dakikalık bir zamanlayıcı kurdu ve bir kâğıt parçasına tek satır harf yazdı. Titrek çıkmışlardı. Zamanlayıcı çaldığında durdu ve not uygulamasına şunu yazdı: “Bugün iki dakika harf çizimi çalıştım.” Ekranda biraz komik göründü. Ama o akşam her zamanki düşünce geldiğinde (“sen hiçbir hobiyi sürdüremezsin”), ona verecek küçük ve somut bir cevabı vardı. Ertesi öğleden sonra başlamak biraz daha kolay geldi ve beş dakika çalıştı."}},"turning-day-4":{deeper:[{heading:"Çevren adımı nasıl kolaylaştırır?",paragraphs:["Uzun bir günün sonunda, aç, yorgun ya da keyifsizken iradene güvenmek zor olabilir. Çevren ise hep oradadır. Kapının yanındaki ayakkabılar gibi gözünün önündeki bir işaret, yapacağın şeyi sana hatırlatır. Hazırlığın bir kısmını önceden yaptıysan, başlamak için daha az enerji gerekir.","Aynı mantık tersine de işler. Çoğumuz bir saat boyunca telefonda gezinmeyi seçmeyiz; telefon yalnızca kitaptan daha yakındır. Bunu değiştirmek için başka biri olman gerekmez. Bu gece tek bir eşyayı yerinden oynatmak, yarın büyük bir karar vermekten çoğu zaman daha kolaydır."],visual:{kind:"steps",title:"Yarınki adımı bu gece hazırla",steps:[{label:"Anı seç",text:"Yarınki adım tam olarak ne zaman olacak? Kahveden sonra, işten sonra, yatmadan önce."},{label:"İşareti koy",text:"İhtiyacın olan eşyayı o anda gözünün önüne gelecek yere bırak."},{label:"Bir engeli kaldır",text:"Kıyafetleri hazırla, dosyayı aç, su şişesini doldur."},{label:"Dikkat dağıtanı uzaklaştır",text:"Seni genellikle işten uzaklaştıran şeyi bir oda öteye taşı."}],note:"Bu gece birkaç dakika ayırıp dört küçük hazırlık yapabilirsin. Böylece yarın başlamak daha kolay olur."}},{heading:"Kime söyleyeceğini seçmek",paragraphs:["Araştırma bulgusu ilerlemeyi bildirmekle ilgili, övgü beklemekle değil. En yararlı kişi, “Nasıl geçti?” diye soran ve sonuç ne olursa olsun dinleyen kişidir. Seninle dalga geçecek, seninle yarışacak ya da planını kendi projesine çevirecek bir arkadaş bu adım için uygun değildir.","Mesajı kısa ve net tut: ne yapıyorsun, ne zaman ve ne zaman haber vereceksin. “Bu hafta işten sonra on dakika yürüyorum; pazar günü nasıl geçtiğini sana anlatabilir miyim?” yeter. Şu anda gerçekten kimse yoksa, kendine yazdığın haftalık bir not de yazılı bir kayıt olur."]}],example:{title:"Tomás, 52, lise öğretmeni",text:"Tomás yatmadan önce telefonda gezinmek yerine kitap okumak istiyordu. Akşam beşte, ödev okumaya başlamadan önce romanı oturma odasındaki raftan alıp yastığının üzerine koydu. Telefon şarj aletini mutfağa taşıdı; bu ona beklenmedik ölçüde büyük bir değişiklik gibi geldi. Sonra planını bir yapışkan nota yazdı: “Dişlerimi fırçaladıktan sonra bir sayfa okuyacağım.” Son olarak, aynı kitabı bir zamanlar okumuş olan ağabeyine mesaj attı: “Bu hafta her gece bir sayfa okumaya çalışıyorum. Pazar günü nereye kadar geldiğimi sana söylerim.” Ağabeyi bir başparmak emojisiyle karşılık verdi ve başka bir şey yazmadı; tam olması gerektiği gibi. O gece kitap oradaydı, telefon değildi."}},"turning-day-5":{deeper:[{heading:"Yarın için gerçekçi bir ideal gün planlamak",paragraphs:["Franklin yalnızca sabah ve akşam sorularını sormuyordu. İş, yemek, okuma ve dinlenme için zaman ayırıp gününü saat saat planlıyordu. Bu kadar ayrıntılı bir programa ihtiyacın yok. Ama bu gece bir dakika ayırıp yarın için gerçekçi bir ideal gün hayal edebilirsin. Bu, adımına ne zaman yer açacağını ve neyin ona engel olabileceğini görmene yardım eder.","İşe yarar bir ideal günün birkaç sabit noktası yeterlidir: seçtiğin alanda bir adım, bir dinlenme anı ve biriyle bağ kuracağın kısa bir zaman. Geri kalanı esnek bırakabilirsin. Planın yalnızca hiçbir şey ters gitmediğinde işliyorsa, uygulamak zor olacaktır. Beklenmedik şeyler için yer bırak."],visual:{kind:"table",title:"Gerçekçi bir ideal gün: üç sabit nokta",columns:["Sabit nokta","Ne zaman","Örnek"],rows:[["Tek adımın","Zaten yaptığın bir şeye bağlı","Sabah kahvesinden sonra: 10 dakikalık yürüyüş"],["Dinlenme","Zaman ayırdığın bir mola","Öğle yemeğini ekrandan uzakta yemek"],["Bağ","Kısa ama gerçek bir temas","Akşam bir kişiye mesaj at ya da onu ara"]],note:"Üç sabit nokta ve bol esneklik. Bu bir planlama yardımcısı; gününün nasıl geçmesi gerektiğine dair bir kural değil."}},{heading:"Şefkat ve sorumluluk birlikte olabilir",paragraphs:["Bazı insanlar kendilerine şefkatli davranınca tembelleşeceklerinden korkar. Bu dersteki araştırma, temkinli yorumlamak kaydıyla, tersine işaret ediyor. Wohl’un çalışmasında kendini daha çok affeden öğrenciler, sonraki sefer daha az erteledi. Bu bağlantıyı, işe karşı olumsuz duyguların azalması açıklıyordu. Kendini eleştirmek işi daha itici hâle getirebilir. İtici gelen bir işten kaçınmak da daha kolaydır.","Şefkatli bir değerlendirmede ne olduğunu dürüstçe söylersin: “İşte geç saatlere kadar kaldığım için yürüyüşü atladım.” Sonra kendine anlayış gösterir ve bir adım seçersin: “Bu anlaşılır; yarın yalnızca köşeye kadar gidip döneceğim.” İlk kısmı söylemezsen olanı görmezden gelirsin. İkinciyi söylemezsen kendine sert davranmış olursun."]}],example:{title:"Aisha, 38, muhasebeci ve iki çocuk annesi",text:"Aisha öğle yemeğinden sonra on dakikalık bir esneme planlamıştı ama bir müşteri görüşmesi uzadı ve yatma saatine kadar unuttu. Dişlerini fırçalarken ilk düşüncesi “İlk gün ve şimdiden başarısız oldum” oldu. Bunun yerine defteriyle yatağın kenarına oturdu. “Bugün hangi iyiliği yaptım?” başlığının altına şunu yazdı: “Yoga matını masanın yanına koydum. Sam’e planımı anlattım.” “Ne zorlaştırdı?” başlığının altına: “Görüşme uzadı; öğleden sonra esneme takvime bağlı.” Nazik cümlesi: “Yoğun bir günde aksaması çok normal; yine de hazırlığı yapmıştım.” Yarının adımı: “Sabah 7.30, çocuklar uyanmadan önce, matın üstünde üç dakika.” Defteri kapattı ve ışığı söndürdü."}},"turning-day-6":{deeper:[{heading:"Yeniden başlayabilirsin",paragraphs:["Yeni başlangıç araştırması, önündeki hafta için yararlı bir fikir sunuyor: başlangıç yapmak için takvimde özel bir gün beklemen gerekmez. 2015 deneylerinde sıradan bir güne başlangıç demek bile başlama isteğini artırdı. Bunu bilinçli kullanabilirsin. Bir günü kaçırırsan ertesi sabahı yeni başlangıç sayabilirsin. Yeni haftanın başı ya da zor bir projeyi bitirdiğin gün de olabilir.","Ama bir sonraki başlangıç gününü beklemek için gerekçe yapma. Çarşamba günü “pazartesi yeniden başlarım” dediğinde dört günü bekleyerek geçirirsin. “Yarın haftamın ikinci yarısının ilk günü” diyebilirsin. Eski ile yeni arasındaki sınırı, ihtiyacın olan yerde koyabilirsin."]},{heading:"7. gün değerlendirmesi",paragraphs:["7. günde kutulara kendine not vermeden bak. Dördünü işaretlediğin ve üçünü boş bıraktığın bir hafta, başarısız olduğun anlamına gelmez. Adımının hayatına ne zaman uyduğunu, ne zaman zor geldiğini gösterir. Aşağıdaki sorular için yaklaşık on dakika ayır. Mümkünse yanıtlarını yaz. İlerleme takibi araştırmasında, yazılı kayıt tutmak daha büyük yararla ilişkiliydi.","Sonra üç seçenekten birini seç: adımı olduğu gibi sürdür, küçült ya da onu bağladığın günlük alışkanlığı veya saati değiştir. Adımı büyütebilirsin de, ama ancak artık kolay geliyorsa. İkinci haftada da amaç aynı: tekrar edebileceğin kadar küçük bir adım."],visual:{kind:"table",title:"7. gün soruları",columns:["Soru","Sana ne söyler?"],rows:[["Hangi günlerde kolayca gerçekleşti?","Adımını destekleyen koşullar"],["Hangi günlerde aksadı ve neden?","Bir sonraki eğer-öyleyse planının hedef alması gereken engel"],["Kaçırılan günden sonra geri döndüm mü?","En küçük hâlinin yeterince kolay olup olmadığı"],["Sürdür, küçült ya da değiştir?","Önümüzdeki yedi gün için planın"]],note:"Bu değerlendirmeden öğrenebilirsin. Boş kalan günler de sana bilgi verir."}}],example:{title:"Jonah, 23, kurye ve yarı zamanlı öğrenci",text:"Jonah’ın adımı akşam yemeğinden sonra yirmi dakika muhasebe tekrarıydı. Bir zarfın arkasına yedi kutu çizdi ve buzdolabına yapıştırdı. Pazartesi ve salı işaretlendi. Çarşamba geç saatlere kadar çalıştı ve zarf boş kaldı; tanıdık “haftaya sıfırdan başlarım” dürtüsünü hissetti. Bunun yerine birinci gün yazdığı cümleye baktı: “Kaçırırsam beş bilgi kartıyla tekrar yaparım.” Perşembe günü beş kart çalıştı, sonra sekiz. Pazara kadar yedi kutunun beşi işaretliydi. Değerlendirmesinde iki boşluğun da geç vardiya günleri olduğunu fark etti; ikinci hafta için o günlerde adımı öğle molasına taşıdı."},sources:["fresh-start-framing"]}},Le=Object.freeze(Object.defineProperty({__proto__:null,EXTRAS:Ue,SOURCES:Fe},Symbol.toStringTag,{value:"Module"})),_e=[{id:"procrastination-pychyl-start",title:"Timothy A. Pychyl · 2008 · “Sadece başla” (Psychology Today, Don’t Delay blogu)",url:"https://www.psychologytoday.com/us/blog/dont-delay/200803/just-get-started",type:"guidance",finding:"Erteleme araştırmacısı Tim Pychyl, laboratuvarının deneyim örnekleme yöntemiyle topladığı verileri anlatıyor. İnsanların kaçınırken çok stresli ve rahatsız edici bulduğu işler, başladıktan sonra daha az itici geliyordu. İşin bir kısmına bile başlayanlar, ertesi gün kendilerini daha fazla kontrol sahibi ve daha umutlu hissetti. Pychyl, “Yarın daha çok canım isteyecek” düşüncesinin de nadiren gerçeğe dönüştüğünü belirtiyor.",limitation:"Yazarın kendi araştırmasını genel okuyucu için özetleyen bir blog yazısıdır, hakemli bir makale değildir; Pychyl de başlamayı tam bir çözüm olarak değil, ilk adım olarak sunar."},{id:"procrastination-pomodoro",title:"Francesco Cirillo · Pomodoro tekniği (resmî site)",url:"https://www.pomodorotechnique.com/francesco-cirillo/",type:"technique",finding:"Cirillo tekniği 1980’lerde üniversite derslerine odaklanmakta zorlanırken, domates şeklinde bir mutfak zamanlayıcısıyla geliştirdi (“pomodoro” İtalyanca domates demektir); ilk deneyi, yalnızca iki dakika kesintisiz çalışıp çalışamayacağını görmekti. Teknik yaygın olarak, kısa molalarla ayrılmış 25 dakikalık odaklanarak çalışma dönemleri olarak öğretilir. Cirillo, amacın pomodoro biriktirmek değil, çalışırken zihninde neler olduğunun farkına varmak olduğunu vurgular.",limitation:"Yaratıcısının kendi sitesidir, bağımsız bir değerlendirme değildir; teknik bir bütün olarak kontrollü denemelerde sınanmamıştır. Çalışma ve mola süreleri araştırma bulgusu değil, geleneksel uygulamadır."},{id:"procrastination-pomodoro-breaks",title:"Biwer ve ark. · 2023 · “Pomodoro” molaları ile kendi seçtiği molalar",url:"https://cris.maastrichtuniversity.nl/en/publications/understanding-effort-regulation-comparing-pomodoro-breaks-and-sel/",type:"research",finding:"87 Hollandalı üniversite öğrencisi ya kendi seçtikleri molalarla (n = 35), ya her 24 dakikadan sonra 6 dakikalık molalarla (“Pomodoro”, n = 25), ya da her 12 dakikadan sonra 3 dakikalık molalarla (n = 27) çalıştı. Kendi molasını seçen öğrenciler daha uzun aralıklarla çalışıp dinlendi ama daha çok yorgunluk ve dikkat dağınıklığı, daha az konsantrasyon ve motivasyon bildirdi. Görevin tamamlanması ve zihinsel çaba anlamlı biçimde farklılaşmadı; yazarlar sabit molaların ruh hâli açısından yararlı olduğu ve daha verimli göründüğü sonucuna varır.",limitation:"Yalnızca özet okundu. Üniversite öğrencileriyle tek oturumluk kendi kendine çalışmayı inceleyen küçük bir çalışmadır; erteleme değil mola düzenlerini sınadı ve gruplar küçüktü."}],Ze={"procrastination-1":{deeper:[{heading:"Tim Pychyl’in bakışı: ertelemenin ardındaki duygu",paragraphs:["Uzun yıllardır erteleme üzerine çalışan psikolog Tim Pychyl, bunu bir duygu düzenleme yolu olarak tanımlıyor. Ancak bu yol ters tepiyor. Bir iş seni kaygılandırabilir, sıkabilir, bunaltabilir ya da belirsizlik hissettirebilir. Erteleyince hızla rahatlarsın ve kaçınmak çözüm gibi görünmeye başlar. Ama iş ortadan kalkmaz. Daha sonra, çoğu zaman büyümüş hâlde, ek stres ve kendini suçlama duygusuyla geri döner.","Fuschia Sirois ile yazdığı derlemede Pychyl, şimdiki sen ile gelecekteki sen arasında bir bedel aktarımından söz ediyor: bugün rahatlarsın, bedelini sonra ödersin. Böyle bakınca yapılacaklar uygulaması ya da sıkı bir program ancak bir yere kadar yardımcı olur. Duyguyu fark etmeyi, bir süre ona katlanmayı ve yine de küçük bir adım atmayı öğrenmek daha çok işe yarar."],visual:{kind:"cycle",title:"Erteleme döngüsü",center:"Kısa vadeli rahatlama, uzun vadeli bedel",nodes:[{label:"İş",text:"Belirsiz, sıkıcı ya da gözünü korkutan bir iş."},{label:"Duygu",text:"Korku, kaygı ya da sıkıntı yükselir."},{label:"Kaçınma",text:"Daha kolay bir şeye geçersin."},{label:"Rahatlama",text:"Rahatsız edici duygu şimdilik hafifler."},{label:"Dönüş",text:"İş, artık ek baskı ve kendini suçlamayla geri gelir."}],note:"Sirois ve Pychyl’in, ertelemenin anlık rahatlama sağladığı görüşünü anlatıyor. Ölçümlerle sınanmış bir model değil. Döngüyü kırmanın ilk adımı çoğunlukla duyguyu fark etmektir."}},{heading:"Rakamlar ne söylüyor, ne söylemiyor?",paragraphs:["Piers Steel’in kapsamlı derlemesinde, erteleme bir işi itici bulmakla ve dürtüsellikle güçlü biçimde ilişkiliydi. Çalışma niyetiyle ise neredeyse hiçbir ilişkisi yoktu. Steel, yetişkinlerin yaklaşık %15–20’sinde ertelemenin sürekli bir sorun olduğunu tahmin ediyor. Bunlar bağlantıları gösterir; itici işlerin ertelemeye yol açtığını kanıtlamaz. Yine de hangi etkenlere bakabileceğimizi gösterir.","Bu bulgularda umut veren bir yan var. Sorun çalışmak istememek değil; “daha çok istemen” gerekmiyor. İşin uyandırdığı duyguyu ele alabilir, ilk adımı küçültebilir ve zorlandığın an için plan yapabilirsin. Sonraki derslerde bunları deneyeceğiz."]}],example:{title:"Sofia, 31, pazarlama koordinatörü",text:"Sofia masraf raporundan üç haftadır kaçıyordu. Genellikle kendine “idari işlerde kötüyüm” diyordu. Bir kahve molasında bunun yerine alıştırmayı denedi: rapor şablonunun bulunduğu e-postayı açtı ve ne olduğunu fark etmek için durdu. Aklına “korku” kelimesi geldi. Bunun altında da utanç vardı. Tetikleyen şey tablo değildi; çantasındaki buruşuk fişlerdi, bir kısmı büyük ihtimalle kaybolmuştu. Yapışkan bir nota şunu yazdı: “Kayıp fişler yüzünden korku + utanç.” O gün rapora başlamadı. Ama “idari işlerde kötüyüm” cümlesi, işin belli bir kısmıyla ilgili somut bir duyguya dönüşmüştü ve bu, üzerinde çalışılabilecek bir şey gibi geldi."},sources:["procrastination-pychyl-start"]},"procrastination-2":{deeper:[{heading:"Başlamak hissi neden değiştirir?",paragraphs:["Tim Pychyl, laboratuvarındaki araştırmalarda görülen bir durumu anlatıyor. İnsanların kaçınırken çok stresli ve rahatsız edici bulduğu işler, başladıktan sonra daha az rahatsız edici geliyordu. İşin bir kısmına bile başlayanlar, ertesi gün kendilerini daha fazla kontrol sahibi ve daha umutlu hissetti. Korku çoğu zaman başlamadan önceki bekleyişte büyüyor.","Pychyl yaygın bir tuzağa da dikkat çekiyor: “Yarın daha çok canım isteyecek.” Ertesi gün çoğu zaman daha istekli olmuyoruz. Küçük bir ilk adım atmak için doğru ruh hâlini beklemen gerekmez. Başlamak, işle ilgili başka bir deneyim sunarak ruh hâlini değiştirebilir."]},{heading:"Süre tutarak kısa aralıklarla çalışmak",paragraphs:["Francesco Cirillo, Pomodoro tekniğini 1980’lerde, odaklanmakta zorlanan bir öğrenciyken geliştirdi. İlk deneyi küçüktü: yalnızca iki dakika kesintisiz ders çalışabilir miydi? Bu denemeden, süre tutarak çalıştığı ve aralarda kısa molalar verdiği bir yöntem doğdu. Bugün genellikle 25 dakikalık çalışma süreleriyle öğretiliyor.","Küçük bir çalışma, 87 üniversite öğrencisinde mola düzenlerini karşılaştırdı. Sabit mola veren öğrenciler (her 24 dakikadan sonra 6, ya da her 12 dakikadan sonra 3 dakika) kendi molasını seçenlere göre daha az yorgunluk ve dikkat dağınıklığı, daha çok konsantrasyon ve motivasyon bildirdi ve benzer miktarda iş çıkardı. Tek oturumluk, küçük örneklemli bir çalışmaydı; bu yüzden bir kural değil, bir ipucu olarak al. Başlangıçta sana daha kısa bir çalışma süresi uygun olabilir."],visual:{kind:"table",title:"Mola vermenin üç yolu (Biwer ve ark. 2023)",columns:["Mola düzeni","Öğrenci","Bildirdikleri"],rows:[["Kendi seçtiği molalar","35","Daha uzun aralıklar; daha çok yorgunluk ve dikkat dağınıklığı, daha az konsantrasyon ve motivasyon"],["Her 24 dakikada 6 dakika","25","Ruh hâlinde daha iyi sonuçlar; benzer miktarda iş tamamlama"],["Her 12 dakikada 3 dakika","27","Ruh hâlinde daha iyi sonuçlar; benzer miktarda iş tamamlama"]],note:"Tek bir kendi kendine çalışma oturumunu inceleyen küçük bir çalışma. Doğrudan erteleme değil, mola düzenlerini sınadı."}}],example:{title:"Kevin, 45, serbest çevirmen",text:"Kevin’in çevirmesi gereken 20 sayfalık bir sözleşme vardı ve iki sabahını e-postalara yanıt vererek “hazırlanmakla” geçirmişti. Üçüncü sabah işi “sözleşmeyi çevir” diye yazdı, sonra parçalara böldü: baştan sona oku, bir sözlük oluştur, birinci bölümü çevir. “Baştan sona oku” bile ağır geldi, o yüzden küçülttü: dosyayı aç ve ilk sayfayı oku. 25 dakika fazla geldiği için mutfak zamanlayıcısını on dakikaya kurdu. Çaldığında üç sayfa okumuş ve dört zor terimi not etmişti. Beş dakika mola verdi, çay yaptı ve zamanlayıcıyı yeniden kurdu. Sözleşme hâlâ uzundu ama artık bir duvar değildi; sayfa sayfa ele alabileceği bir işti ve bir kısmına başlamıştı."},sources:["procrastination-pychyl-start","procrastination-pomodoro","procrastination-pomodoro-breaks"]},"procrastination-3":{deeper:[{heading:"Piers Steel’in zamansal motivasyon kuramı",paragraphs:["Piers Steel, erteleme araştırmalarını zamansal motivasyon kuramında bir araya getiriyor. Başarabileceğine inanıyorsan (beklenti) ve sonuç senin için önemliyse ya da ödül getiriyorsa (değer), işe daha çok yönelirsin. Ödül uzaktaysa (gecikme) ve anlık cazibelere kolay kapılıyorsan (dürtüsellik), işe yönelmen zorlaşır. Üç hafta sonra teslim edilecek bir rapor, hemen keyif veren bir video karşısında geri planda kalabilir.","Bu kuramın yararlı yanı, her etken için deneyebileceğin bir şey göstermesi. İşi küçülterek başarabileceğine dair beklentini artırabilirsin. Önemsediğin bir şeyle bağ kurarak işi daha değerli hâle getirebilirsin. Daha yakın kontrol tarihleri ve küçük ödüller, bekleme süresini kısaltabilir. Dikkat dağıtıcıları erişemeyeceğin yere koymak da anlık dürtülere kapılmanı azaltabilir. WOOP ve eğer-öyleyse planları özellikle son noktaya yardımcı olur: cazip bir şeyle karşılaştığında ne yapacağını önceden belirlersin."],visual:{kind:"table",title:"Zamansal motivasyon kuramında değiştirebileceğin dört etken",columns:["Etken","Ne demek?","Denenecek bir şey"],rows:[["Beklenti","Yapabileceğinden ne kadar emin hissettiğin","Başarabileceğine inanacağın kadar işi küçült"],["Değer","Senin için ne kadar önemli ya da ödüllendirici olduğu","Neden önemli olduğunu tek satırla yaz"],["Gecikme","Karşılığın ne kadar uzakta olduğu","Daha yakın bir kontrol tarihi ve küçük bir ödül belirle"],["Dürtüsellik","Anlık cazibelere ne kadar kolay kapıldığın","Bir eğer-öyleyse planı yap ve dikkat dağıtıcıyı uzaklaştır"]],note:"Korelasyonel bulgulara uyan Steel’in modeline dayanır; bir düşünme biçimidir, sınanmış bir tedavi değildir."}},{heading:"Eğer-öyleyse planlarında sık yapılan hatalar",paragraphs:["“Eğer” kısmı çoğu zaman fazla belirsizdir. “Canım istemezse” neredeyse her zaman doğrudur, bu yüzden net bir işaret olamaz. “Masama oturduktan sonra telefonumu elime alırsam” ise gerçekleştiğinde tanıyacağın bir andır.","“O zaman” kısmı çoğu zaman fazla büyüktür. “O zaman iki saat çalışacağım”, zaten zorlandığın kadar büyük bir çaba ister. “O zaman önce tek bir cümle yazacağım” ise duygu yoğunken bile yapabileceğin kadar küçüktür. En sık karşılaştığın engel için tek bir plan, hatırlamayacağın beş plandan iyidir."]}],example:{title:"Grace, 26, yüksek lisans öğrencisi",text:"Grace tezinin literatür taramasını bu hafta bitirmek istiyordu; bitirirse her hafta sonu suçluluk duymayı bırakabilirdi. Engeli ararken bunun zaman olmadığını gördü. Engel, belgeyi açtıktan sonra yeterince bilmediğini hissedip telefona uzandığı andı. Planı şuydu: “Belgeyi açtıktan sonra telefona uzanırsam, o zaman telefonu çekmeceye koyup ilk makale hakkında tek bir cümle yazacağım.” Bunu otobüste bir kez prova etti. Salı günü kendini telefon zaten elindeyken yakaladı, biraz güldü ve telefonu çekmeceye koydu. Yazdığı cümle pek düzgün değildi. Yine de bir tane daha yazdı."},sources:["task-aversiveness","oettingen-woop-method"]},"procrastination-4":{deeper:[{heading:"Kendini affetme çalışması ne buldu?",paragraphs:["Michael Wohl, Tim Pychyl ve Shannon Bennett, birinci sınıf öğrencilerini iki ara sınav boyunca izledi. İlk sınavdan sonra öğrenciler ne kadar ertelediklerini ve bu konuda kendilerini ne kadar affettiklerini bildirdi. Kendini daha çok affedenler, ikinci sınavdan önce daha az erteledi. Bu bağlantıyı, derse karşı olumsuz duyguların azalması açıklıyordu.","Çalışmanın önemli sınırları var: yalnızca ilişkileri inceledi, tek bir derste yapıldı ve başlayan 312 öğrenciden yalnızca 119’u son analize girdi. Bu yüzden affetmenin daha az ertelemeye yol açtığını kanıtlayamaz. Ama ertelemenin anlık rahatlama sağladığı görüşüyle uyuşuyor: erteleme kötü duygulardan kaçmanın bir yoluysa, kendini daha kötü hissettirmek pek yardımcı olmayabilir. Daha genel olarak öz şefkat araştırmaları stres ve kaygı için küçük ile orta düzeyde kısa vadeli yararlar gösteriyor."]},{heading:"Üç parçalı bir affetme metni",paragraphs:["Kendini affetmenin ne demek olduğunu anlamak zor olabilir. Bu yüzden hazır birkaç cümle işe yarar. Aşağıdaki üç bölüm, dürüst ve şefkatli kalmana yardım eder. İçinden söyle ya da yaz. Cümleleri kendi sözlerinle kurabilirsin.","Bunu yaparken sert ses geri gelirse bu normal. Onunla tartışman ya da onu susturman gerekmez. Sadece fark et (“işte eleştirmen yine geldi”) ve metne dön."],visual:{kind:"steps",title:"Affet, sonra geri dön",steps:[{label:"Adını koy",text:"“Raporu bu hafta yine erteledim.”"},{label:"İnsani olduğunu hatırla",text:"“Belirsiz ve stresli geldi; birçok insan böyle işlerden kaçınır.”"},{label:"Sorumluluğu al",text:"“Yine de benim için önemli ve bir kısmını düzeltebilirim.”"},{label:"Sonraki adımı seç",text:"“Yarın saat 9’da dosyayı açıp ilk başlığı yazacağım.”"}],note:"Burada affetmek, kendine yüklenmeyi bırakıp işe geri dönebilmek demek."}}],example:{title:"Daniel, 36, proje yöneticisi",text:"Daniel ekibine cuma gününe kadar bir bütçe taslağı sözü vermişti ve cuma öğleden sonra önündeki sayfa hâlâ boştu. Eve dönerken her zamanki sesi duydu: “Hep böyle yapıyorsun. Herkes hiçbir şeyi yönetemediğini görecek.” Arabayı park ettiğinde bilgisayarını açacak gücü bile bulamıyordu. Arabada otururken metni denedi. “Taslağı yapmadım. Belirsiz geldi ve kaçınmaya devam ettim; insanların başına gelir. Yine de önemli ve bir kısmını düzeltebilirim.” Sonra adım: ekibine taslağın pazartesi öğlene kadar geleceğini yazan bir e-posta ve dosyayı 8.30’da açması için bir not. Pazartesi günü başlamak, kendisi hakkında verilecek bir hükümle yüzleşmek gibi gelmiyordu."}},"procrastination-5":{deeper:[{heading:"Zorlandığın yere uygun yöntemi seçmek",paragraphs:["Ertelemenin nedeni her seferinde aynı olmayabilir. Bu kurstaki yöntemler farklı durumlarda işe yarayabilir. Nereden başlayacağını bilemiyorsan işi küçültmeyi dene. Belli bir anda hep işten uzaklaşıyorsan, o an için bir eğer-öyleyse planı yap. Sonuç çok uzaktaysa daha yakın bir kontrol tarihi belirle. Steel’in modeli de bekleme süresini kısaltmanın yardımcı olabileceğini öngörüyor.","Bütün yöntemleri aynı anda kullanman gerekmez. Zorlandığın yere uyan bir ya da iki tanesini seç, bir hafta dene ve sonucu gözden geçir. Geniş bir meta-analizde, yapılanları basit bir işaretle bile olsa takip etmek hedeflerde daha iyi ilerlemeyle ilişkiliydi. Kayıt tutmak, haftalık değerlendirmende somut olarak neye bakacağını da gösterir."],visual:{kind:"table",title:"Hangi zorluk için hangi yöntem?",columns:["İş şöyle geliyorsa…","Dene","Hangi dersten"],rows:[["Ağır ve korkutucu","Hissin adını koy, sonra iki dakikalık bir ilk adım","1 ve 2"],["Belirsiz ya da çok büyük","Parçalara böl; ilk adımı somut bir fiille yaz","2"],["Belli bir ana kadar sorun yok","O an için bir eğer-öyleyse planı","3"],["Uzak ve göz ardı etmesi kolay","Küçük ödüllü, daha yakın bir kontrol noktası","5"],["Erteledikten sonra artık düzelmez gibi","Affetme metni, sonra tek bir adım","4"]],note:"Buradan sana uygun yöntemleri seçebilirsin. Bir hafta için bir ya da iki yöntem yeter."}},{heading:"Ne zaman daha fazla destek almalısın?",paragraphs:["Ertelemeye yönelik araştırmalarda en güçlü sonuçlar, eğitimli bir uzmanla yapılan bilişsel davranışçı terapiden geldi. Bazı erteleme sorunları, kısa bir kursun ele alamayacağı durumlarla iç içe olabilir. Uzun süren kaygı, depresyon ya da DEHB gibi dikkat güçlükleri bunlar arasında. Bu kurs eğitim ve kişisel çalışma içindir; tanı ya da tedavi sunmaz.","Erteleme işini, okul başarını, ilişkilerini ya da sağlığını olumsuz etkiliyorsa bir doktora ya da terapiste danışabilirsin. İşlerin uyandırdığı duygular çok yoğunsa veya sürekli devam ediyorsa da destek almak iyi olabilir. Birkaç yöntem denediğin hâlde değişim görmüyorsan yardım isteyebilirsin. Bu, iradenin zayıf olduğu anlamına gelmez. Daha zor bir sorun için daha güçlü bir destek seçmiş olursun."]}],example:{title:"Nadia, 29, okula başvuran veteriner teknisyeni",text:"Nadia’nın başvuru yazısı üç hafta sonra teslim edilecekti ve kendini tanıyordu: bir gece öncesinde başlayacaktı. Pazar günü planı doldurdu. İlk adım: bir belge açıp onu bu mesleği istemeye götüren üç anı sıralamak. Zaman ve yer: salı akşam 7, akşam yemeğinden sonra mutfak masası. Eğer-öyleyse: “Eski e-postaları yeniden okumaya başlarsam, önce tek bir cümle yazacağım.” Deneme olarak iki ara tarih koydu: bir sonraki pazara kadar ilk taslak ve ondan sonraki çarşamba günü bir arkadaşının okuması. Salı gayet iyi geçti. Perşembe günü hiç yapmadı. Pazar günkü iki dakikalık gözden geçirmede arkadaşının okuyacağı tarihin, kendi koyduğu tarihten daha çok harekete geçirdiğini not etti ve arkadaşının okumasını üç gün öne aldı."},sources:["task-aversiveness"]}},Je=Object.freeze(Object.defineProperty({__proto__:null,EXTRAS:Ze,SOURCES:_e},Symbol.toStringTag,{value:"Module"})),Ve=[{id:"confidence-fear-ladder",title:"Psychology Tools · Korku merdiveni (aşamalı yüzleşme hiyerarşisi)",url:"https://www.psychologytools.com/resource/fear-ladder",type:"guidance",finding:"Ruh sağlığı uzmanlarına yönelik bu kaynak, kaygı için bilişsel davranışçı terapide kullanılan korku merdivenini anlatıyor. Önce korkuyu belirle, korktuğun durumları listele ve her birine tahmini bir korku puanı ver. Sonra en az korkutucudan en çok korkutucuya sırala. Alt basamaklardan başlayıp zamanla yukarı çık. Rehber, kişi çok zorlanırsa hızın ayarlanmasını öneriyor ve sürece genellikle bir terapistin eşlik ettiğini belirtiyor.",limitation:"Ruh sağlığı uzmanları için hazırlanmış pratik bir rehber. Yüzleşmenin terapide nasıl uygulandığını anlatır; kendi kendine uygulanan bir biçimini sınayan araştırma değildir. Bu kursta yöntem yalnızca gündelik ve güvenli adımlar için kullanılıyor."},{id:"confidence-five-second-rule",title:"Mel Robbins · 5 saniye kuralı (2017) · “Motivasyon çöptür” podcast bölümü",url:"https://www.melrobbins.com/episode/episode-3/",type:"technique",finding:"Robbins, “5, 4, 3, 2, 1” diye geriye sayıp hemen harekete geçmeni öneriyor. Amaç, harekete geçme isteğiyle korku, bahane ve kendinden şüphe duymanın seni vazgeçirdiği an arasındaki kısa süreyi kullanmak. Robbins önce eylemin, ardından motivasyonun geldiğini savunuyor.",limitation:"Yazarın kendi podcast sayfası. 5 saniye kuralının kendisini sınayan kontrollü bir çalışma bulamadık. Destek çoğunlukla kişisel hikâyelerden geliyor. Küçük, planlı bir eylemi net bir işaretle başlatma fikri, eğer-öyleyse planlarıyla örtüşüyor."}],$e={"confidence-1":{deeper:[{heading:"Etiketlerden kurtulmak neden zor?",paragraphs:["Kendine bir etiket koymak işini kolaylaştırır. “Söz almakta kötüyüm” dediğinde her duruma ayrı ayrı bakman gerekmez. Seni koruyor gibi de görünür: zaten başarısızlık bekliyorsan şaşırmazsın. Ama böyle bir etiket, neyi değiştirebileceğini göstermez. “İşe yaramaz olmamayı” çalışamazsın. “Pazartesi toplantısında bir cümle söylemeyi” ise çalışabilirsin.","Kendinle bir arkadaşınla konuşur gibi konuşmanın amacı yalnızca iyi hissetmek değil. Öz şefkat uygulamaları, rastgele gruplara atamanın yapıldığı 56 çalışmada stres ve kaygıyı kısa vadede küçük ile orta düzeyde azalttı. Ancak çalışmaların genel yanlılık riski yüksekti. Daha sakin ve adil bir iç ses, yaşadıklarına daha açık bakmanı sağlayabilir."],visual:{kind:"table",title:"Etiketi somut bir duruma çevirmek",columns:["Etiket","Durum + his","Olası sonraki adım"],rows:[["İnsanlarla iletişimde beceriksizim.","Tanımadığım insanlarla bir araya gelince tedirgin oluyorum.","Birine soracağım bir soru hazırla"],["Ben korkağım.","Yöneticim benimle aynı fikirde olmayınca geri çekildim.","Söylemek istediğim noktayı yaz"],["Bu işte çaresizim.","İlk sunum denememde nerede kaldığımı unuttum.","Girişi yüksek sesle iki kez çalış"]],note:"Ortadaki sütun duyguyu açıkça anlatır. Sağdaki sütun atabileceğin bir adımı gösterir."}},{heading:"Bedenin de bu deneyimin parçası",paragraphs:["Albert Bandura, bir şeyi yapabileceğine olan inancına öz yeterlik adını verdi. Bunun dört kaynağından biri de bedeninin durumu. Kalbin hızla atınca, ağzın kuruyunca ya da sesin titreyince “Gördün mü, yapamıyorum” diye düşünebilirsin. Oysa kalbinin hızlanması, bu konunun senin için önemli olduğunu da gösterebilir. Bu, o an hakkında bir bilgi; yeteneğin hakkında kesin bir yargı değil.","Bu yüzden durumu anlatırken bedeninde olanları da söyleyebilirsin. Ama ne yapacağına onlar karar vermesin: “Kalbim çarpıyordu ve yine de cümlemi söyledim.” İkisi de doğru. Birlikte, “Heyecandan mahvoldum” demekten çok farklı bir tablo çiziyorlar."]}],example:{title:"Olivia, 33, laboratuvar teknisyeni",text:"Olivia ekip toplantılarında pek konuşmazdı. Sonrasında da “Ben zaten özgüvenli biri değilim” diye düşünürdü. Salı akşamı alıştırmayı denedi. Güvenli durum olarak amirinin görüş istediği haftalık laboratuvar toplantısını seçti. Kendine koyduğu etiket şuydu: “Grup içinde hiç beceremiyorum.” Cümleyi değiştirdi: “Haftalık toplantıda herkes bana bakınca yüzümün ısındığını hissediyorum ve donup kalıyorum.” Sonra aynı şeyi yaşayan arkadaşı Mei’ye ne söyleyeceğini düşündü: “Herkesin gözü üzerindeyken pek çok insan donup kalır. Sen işini biliyorsun.” Bir sonraki toplantıda dışarıdan bakınca hiçbir şey değişmedi. Ama yüzü ısınınca “İşte yapamadığımın kanıtı” yerine “Yüzüm yine ısınıyor” diye düşündü. Bu ona biraz daha hafif geldi."},sources:["bandura-self-efficacy"]},"confidence-2":{deeper:[{heading:"Üç adımdan bir korku merdivenine",paragraphs:["Kolay, orta ve zor adımlar belirlemek, terapistlerin kullandığı korku merdiveninin küçük bir uyarlaması. Buna yüzleşme hiyerarşisi de denir. Aynı korkuyla ilgili durumları listeler, ne kadar korkutucu olacaklarını tahmin eder ve en azdan en çoğa sıralarsın. Alt basamaklardan başlarsın. Ancak bulunduğun adımla başa çıkabildiğini hissettiğinde yukarı çıkarsın. Bu aşamalı yaklaşım, kaygı için bilişsel davranışçı terapinin temel araçlarından biridir.","Gündelik özgüven için de bu yaklaşımı daha küçük ölçekte kullanabilirsin. Korkuna 0 (hiç korku yok) ile 10 (hayal edebileceğin en yoğun korku) arasında puan ver. İlk denemelerin için 3 ya da 4 düzeyindeki adımları seç: biraz rahatsız edici ama yapılabilir olsun. Bir adımın puanı 9 çıkarsa başarısız olmadın. Altına daha kolay bir basamak eklemen gerekiyor."],visual:{kind:"steps",title:"Örnek bir özgüven merdiveni: işte söz almak",steps:[{label:"Korku 2",text:"Toplantıdan önce tek bir yorum yaz."},{label:"Korku 4",text:"Yorumu toplantıdan sonra bir meslektaşınla paylaş."},{label:"Korku 5",text:"Küçük bir toplantıda bir soru sor."},{label:"Korku 7",text:"Tüm ekibin katıldığı toplantıda görüşünü söyle."},{label:"Korku 9",text:"Bütün bölüme kısa bir bilgilendirme sun."}],note:"Bulunduğun basamakla başa çıkabildiğinde bir üsttekine geç. Kaygın yoğunsa ya da travmayla bağlantılıysa, bu adımları eğitimli bir terapistle belirle ve onun desteğiyle dene."}},{heading:"Yapmak neden beklemekten iyi?",paragraphs:["Albert Bandura’ya göre bir şeyi yapabileceğine olan inancının en güçlü kaynağı, o işi gerçekten yapmış olman. Buna ustalık deneyimi adını verdi. Başkalarını izlemek, cesaret veren sözler duymak ve bedenen sakin olmak da yardımcı olur. Ama kendi deneyimin kadar etkili değildir. Korkunun geçmesini beklerken onu azaltabilecek deneyimi de kaçırabilirsin.","Bu yüzden adımı sen seçmelisin. Birinin zoruyla ya da başa çıkabileceğinden çok daha zor bir şeyi denersen, öğrenmek yerine ortamdan kaçmak isteyebilirsin. Kendi seçtiğin ve tamamlayabileceğin bir adım ise güvenebileceğin bir kanıt bırakır."]}],example:{title:"Ben, 24, mağaza satış elemanı",text:"Ben, yöneticisinden daha fazla çalışma saati istemek istiyordu ama her seferinde donup kalıyordu. Üç kutu çizdi. Zor: mağazada yüz yüze sormak. Orta: beş dakika konuşmak için kısa bir mesaj göndermek. Kolay: ne istediğini ve nedenini yazmak. Kolay adım neredeyse işi fazla kolaylaştırmak gibi geldi. Yine de öğle molasında personel odasında oturup yazdı: “Haftada dört saat daha çalışmak istiyorum, mümkünse cumartesileri. Bu ay iki kez başka birinin vardiyasını üstlendim.” Orta adımın korku puanı 6’ydı. Bir gün beklemeye karar verdi. Perşembe günü mesajı gönderdi. Gönder tuşuna basarken elleri soğuktu. Yöneticisi “Tabii, cuma günü kapanıştan sonra” diye yanıtladı. Asıl konuşma henüz yapılmamıştı ama Ben şimdiden iki adım atmıştı."},sources:["confidence-fear-ladder","bandura-self-efficacy"]},"confidence-3":{deeper:[{heading:"Denemende Bandura’nın dört kaynağını kullan",paragraphs:["Bandura öz yeterliği besleyen dört kaynak tanımladı: ustalık deneyimleri, başkalarını izlemek, cesaret veren sözler ve bedeninin durumu. Her denemende bunlardan yararlanabilirsin. Önce onları fark etmen gerekir. Bir kameranın görebileceklerini yazmak, ilk ve en güçlü kaynağı destekler. Belirsiz bir anıyı net bir “Bunu yaptım” cümlesine çevirir.","Bandura’ya göre tekrar eden başarılarla güçlenen bir inanç, ara sıra yaşanan aksaklıklardan daha az etkilenir. Bu yüzden kayıt tutmak tek bir sonuçtan daha önemli. Yolunda giden beş konuşmanın kaydı yanında, bir konuşmada bocalamak yalnızca tek bir deneyim olarak görünür."],visual:{kind:"table",title:"Bir cesaret denemesinde öz yeterliğin dört kaynağı",columns:["Kaynak","Denemenden sonra nelere bakmalı?"],rows:[["Ustalık deneyimi","Gerçekte ne yaptım? Kendine not vermeden davranışı yaz."],["Başkalarını izlemek","Başka birinin benzer bir işi kusursuz yapmasa da tamamladığını gördüm mü?"],["Cesaret verici sözler","Biri nazikçe karşılık verdi mi, ya da kendime adil bir cümle söyleyebilir miyim?"],["Bedenin durumu","Heyecan zirve yapıp sonra yatıştı mı? Ne zaman?"]],note:"Bandura ustalık deneyimini en güçlü kaynak olarak gördü. Bu tablo yaşadıkların üzerine düşünmene yardımcı olur. Bir tedavi planı değildir."}},{heading:"Tekrar oynatma tuzağı",paragraphs:["Pek çok insan, bir konuşmadan sonra yaşananları zihninde tekrar tekrar oynatır. Özellikle bocaladığı tek bir ana takılır. Bu tekrarlar bir şey öğreniyormuşsun gibi gelir ama çoğunlukla baştaki olumsuz tahminini güçlendirir. “Bir kamera ne görürdü?” sorusu bu döngüyü keser. İki gözlemini yazıp durabilirsin.","Geniş bir meta-analizde, ilerlemeyi yazılı izlemek hedeflere daha iyi ulaşmayla ilişkiliydi. İlerlemeyi somut olarak kaydetmek daha büyük yarar sağlıyordu. Bir anı zihninde tekrar etmekle kaydını tutmak farklı şeyler. Kayıt kısa olur, olanı anlatır ve bir yerde biter. Sonra defteri kapatabilirsin."]}],example:{title:"Lucas, 30, yazılım geliştirici",text:"Lucas bir konferansın soru–cevap bölümünde soru sormuştu; haftalık denemesi buydu. Salondan çıkarken zihni bunu çoktan yeniden oynatıyordu: sesi çatallanmıştı ve herkes kesin fark etmişti. O gece notlarını açtı ve öncesindeki tahminini yazdı: “Kekeleyeceğim, konuşmacı küçümseyecek, insanlar dik dik bakacak.” Sonra iki kamera gözlemi: “Geçiş takvimini sordum. Konuşmacı iyi bir soru olduğunu söyledi ve yaklaşık bir dakika yanıtladı.” Ekledi: “Sesim ilk kelimede çatallandı.” Üç satırı birlikte okuyunca çatallanma diğerlerinin yanında küçük göründü. Bir dahaki sefer için bir satır daha yazdı: “Aynı türden bir soru, daha küçük bir oturumda.”"},sources:["bandura-self-efficacy"]},"confidence-4":{deeper:[{heading:"Öz şefkat araştırması ne gösteriyor?",paragraphs:["Rastgele gruplara atamanın yapıldığı 56 çalışmada, öz şefkat uygulamaları stres, kaygı ve depresif belirtileri kısa vadede küçük ile orta düzeyde azalttı. Etki vardı ama sınırlıydı. Çalışmaların genel yanlılık riski de yüksekti; bu yüzden bulguyu temkinli değerlendirmek gerekir. Bir erteleme çalışması da benzer bir sonuç verdi: sınava çalışmayı ertelediği için kendini daha çok affeden öğrenciler, sonraki sınavdan önce daha az erteledi.","Kendine sert davranırken de nazik davranırken de amacın bir sonraki denemede daha iyisini yapmak olabilir. Ama sertlik korkuyu artırır. Bu da yeniden denemeyi daha riskli hissettirir. Adil ve sıcak bir cümle, hatadan öğrenmeni sağlar ve bu fazladan korkuyu azaltır."]},{heading:"Abartılı olumlamalar neden ters tepebilir?",paragraphs:["Bandura cesaret verici sözleri öz yeterliğin kaynakları arasında saydı ama onları kendi deneyiminden daha zayıf gördü. Bir tökezlemenin hemen ardından kendine “Her şeyde harikayım” demek, az önce yaşadıklarınla çatışır ve buna inanmayı zorlaştırabilir.","Gerçekçi destek kanıta karşı değil, kanıtla birlikte çalışır. Ne olduğunu adlandırır, emeği fark eder ve bir sonraki adımı gösterir. Aşağıdaki iki sütunu karşılaştır ve kötü bir günde hangilerine gerçekten inanabileceğine bak."],visual:{kind:"compare",title:"Abartı mı, gerçekçi destek mi?",left:{label:"Abartı",items:["“Mükemmelim ve hiçbir şey ters gitmedi.”","“O hatayı bir daha asla yapmayacağım.”","“Herkes bayıldı.”"]},right:{label:"Gerçekçi destek",items:["“Bu zordu ve yine de yaptım.”","“Bir dahaki sefer hangi kısmı düzelteceğimi biliyorum.”","“Bir kişi ilgili görünüyordu; bu bir başlangıç.”"]},note:"Cesaret veren bir söz, yaşananlarla uyuşuyorsa daha inandırıcı olur."}}],example:{title:"Fatima, 42, okul idarecisi",text:"Fatima velilere gönderdiği e-postada okul gezisinin tarihini yanlış yazmıştı. Bir veli yanıtlayıp bunu belirttiğinde içi bir anda sıkıştı ve tanıdık ses başladı: “Nasıl bu kadar dikkatsiz olabilirsin? Herkes işini yapamadığını düşünecek.” Cümleyi fark etti ve onunla tartışmadı. Usulca dedi ki: “Bu zordu. Tarihte bir hata yaptım.” Sonra adil kısmı: “Bir saat içinde düzeltebilirim.” Tüm velilere kısa bir düzeltme gönderdi, fark eden veliye teşekkür etti ve e-posta şablonuna bir tarih kontrolü ekledi. Mahcubiyet öğleden sonra boyunca sürdü. Ama enerjisini kendini yargılamak yerine hatayı düzeltmeye harcamıştı."},sources:["bandura-self-efficacy","self-forgiveness"]},"confidence-5":{deeper:[{heading:"5 saniye kuralının dayanağı",paragraphs:["Mel Robbins, tereddüt ettiğin anlar için basit bir yöntem öneriyor: beşten geriye say ve bire geldiğinde ilk hareketi yap. Ona göre harekete geçme isteğinle seni vazgeçiren gerekçelerin aklına gelmesi arasında kısa bir süre var. Geri sayım bu süreyi kullanmana yardımcı oluyor. Pek çok insan bunu yararlı buluyor.","5 saniye kuralının kendisini sınayan kontrollü bir çalışma bulamadık. Destek çoğunlukla kişisel hikâyelerden geliyor. Yöntemin temel fikri, içinde bir başlangıç işareti bulunan eğer-öyleyse planına benziyor: “Tereddüt ettiğimi fark edersem geriye sayıp ilk küçük adımı atacağım.” Önceden seçtiğin güvenli bir adım için bu şekilde kullanırsan, kolayca deneyebileceğin bir yöntem olabilir."]},{heading:"Merdivende ilerlemeye devam etmek",paragraphs:["Özgüven her hafta aynı hızla gelişmez. Bazen bir basamak çıkarsın. Bazen hayat zorlaşır; bulunduğun yerde kalır ya da bir basamak inersin. Kısa bir haftalık gözden geçirme, kendine not vermeden olanı görmeni sağlar. İlerlemeyi izleme araştırmalarında yazılı kayıtlar daha büyük yararla ilişkiliydi. Kâğıda birkaç satır yazmak için ayırdığın iki dakika bu yüzden işe yarayabilir.","Gözden geçirirken bir sonraki basamağı seçmeye odaklan. Bir adımdaki korkuna üst üste iki kez 3 puan verdiysen, bir üsttekine geçme zamanı gelmiş olabilir. Puanın 8 ise altına daha küçük bir adım ekle. Her iki durumda da sana neyin cesaret verdiğini öğreniyorsun."],visual:{kind:"table",title:"İki dakikalık haftalık gözden geçirme",columns:["Soru","Örnek cevap"],rows:[["Ne denedim?","Küçük toplantıda bir soru sordum."],["0–10 arası ne kadar korkutucuydu?","Önce: 6. Sonra: 3."],["Bir kamera ne görürdü?","Sordum; yöneticim not aldı."],["Sonraki basamak?","Aynı adımı bir kez daha, sonra tüm ekibin olduğu toplantıda bir yorum."]],note:"Puanlar bir sonraki adımı seçmek içindir, kendine not vermek için değil."}}],example:{title:"Rosa, 57, evde geçen yılların ardından çalışmaya dönen",text:"Rosa kütüphanedeki diğer gönüllülere kendini tanıtmak istiyordu ama her hafta sessizce içeri giriyor, kitapları ayırıyor ve çıkıyordu. Planı: cumartesi günü bir gönüllüye merhaba deyip adını söylemek. Başlangıç planı: “Kaçıp gitmek istersem, önce beşten geriye sayıp ‘Merhaba, ben Rosa’ diyeceğim.” Destek: cumartesi akşamı arayacak olan kızı. Cumartesi günü kendini arka odaya doğru giderken yakaladı. Saydı, döndü ve iade masasındaki kadına söyledi. Kadın gülümsedi, kendi adını söyledi ve işine döndü. Hepsi buydu. Rosa iki dakikalık gözden geçirmesinde şunu yazdı: “Önce korku: 7. Sonra: 3. Sıradaki: birine ne zamandır gönüllü olduğunu sormak.”"},sources:["confidence-five-second-rule","confidence-fear-ladder"]}},Qe=Object.freeze(Object.defineProperty({__proto__:null,EXTRAS:$e,SOURCES:Ve},Symbol.toStringTag,{value:"Module"})),Xe=[{id:"adhd-cbt-meta",title:"Young, Moghaddam & Tickle · 2020 · Yetişkinlerde ADHD için BDT meta-analizi",url:"https://journals.sagepub.com/doi/abs/10.1177/1087054716664413",type:"research",finding:"Dokuz randomize çalışma bulundu, sekizi analizde birleştirildi. BDT, bekleme listesiyle karşılaştırıldığında ADHD belirtilerini orta ile büyük düzey arasında etkiyle azalttı (4 çalışma, 160 kişi; SMD = 0,76). Başka bir etkin uygulama alan kontrol gruplarıyla karşılaştırıldığında etki küçük ile orta düzey arasındaydı (3 çalışma, 191 kişi; SMD = 0,43).",limitation:"Az sayıda çalışma ve sınırlı katılımcı grupları var. Bu yüzden sonuçları kesinleşmiş kabul edemeyiz. Araştırmalar, kendi başına ders okumayı değil terapist eşliğindeki programları sınar. Yalnızca özet okundu."},{id:"adhd-cbt-program",title:"Sprich, Knouse, Cooper-Vince, Burbridge & Safren · Yetişkinlerde ADHD için BDT: tanım ve gösterim (Cognitive and Behavioral Practice)",url:"https://pmc.ncbi.nlm.nih.gov/articles/PMC3874265",type:"guidance",finding:"BDT programının modüllerini anlatır. Her gün kontrol edilen tek bir takvim ve yapılacaklar listesi kullanılır. İşlere öncelik verilir, sorun çözme çalışılır ve büyük işler yapılabilir adımlara bölünür. Dikkati dağıtan düşünceleri erteleme tekniğinde, yaklaşık olarak ölçtüğün dikkat süren kadar çalışırsın. Dikkatini dağıtanları not alır, süre bitince ele alırsın. Dikkat dağıtıcılardan arınmış bir çalışma alanı hazırlanır; malzemeler el altında tutulur. Hem aşırı olumsuz hem aşırı iyimser düşüncelere daha gerçekçi karşılıklar geliştirilir.",limitation:"Programı geliştirenlerin terapistler için yazdığı bir klinik açıklamadır. Her tekniği ayrı ayrı sınamaz. PubMed Central’daki tam metin okundu."},{id:"adhd-safren-workbook",title:"Steven A. Safren, Susan E. Sprich, Carol A. Perlman & Michael W. Otto · Mastering Your Adult ADHD, Client Workbook (2. baskı, 2017)",url:"https://global.oup.com/academic/product/mastering-your-adult-adhd-9780190235567",type:"technique",finding:"İlaç tedavisinin yanında beceri desteğine ihtiyaç duyan yetişkinler için BDT programının danışan çalışma kitabıdır. Düzenleme ve planlama, randevuları ve işleri takip etme, sorun çözme ele alınır. Dikkat süresini ölçme ve çevreyi değiştirme yoluyla dikkat dağınıklığı azaltılmaya çalışılır. Daha gerçekçi düşünme üzerinde çalışılır. Erteleme ve sorunların tekrarlamasını önleme için isteğe bağlı modüller de vardır.",limitation:"Çalışma kitabı bir terapistle birlikte kullanılmak üzere tasarlanmıştır. Yayıncının tanıtımı okundu; teknikler burada ODA’nın kendi sözleriyle yeniden anlatılıyor."},{id:"adhd-barkley",title:"Russell A. Barkley · ADHD’de yürütücü işlevlerin ve öz düzenlemenin önemli rolü (bilgi formu)",url:"https://www.russellbarkley.org/factsheets/ADHD_EF_and_SR.pdf",type:"technique",finding:"Barkley’ye göre ADHD’de asıl zorluk, ne yapacağını bilmekten çok bildiğini uygulamaktır. İnsanlar çoğu zaman ne yapacaklarını bilir ama yapmakta zorlanır. Desteğin, harekete geçmek gereken yerde ve anda bulunmasını önerir. Bilgiyi orada somut ve görünür kılmak, uzun projeleri hızlı geri bildirim veren günlük adımlara bölmek yararlı olabilir. Küçük ödüller ve yaptığını birine bildirmek gibi dış desteklerle motivasyonu artırmayı da önerir.",limitation:"Bir klinisyenin kurama dayanan bilgi notudur. Deneysel bir çalışma değildir; öneriler tek tek sınanmadı. Çocukları ve okulları da ele alır. Buradaki yetişkin uygulamaları ODA’nın uyarlamasıdır."},{id:"adhd-body-doubling",title:"Eagle, Baltaxe-Admony & Ringland · 2024 · Nörofarklı katılımcılarla eşlikçi çalışma (ACM TACCESS)",url:"https://leyabreanna.com/papers/body_double_taccess.pdf",type:"research",finding:"220 kişiyle çevrim içi anket yapıldı. 193’ü nörofarklıydı, çoğunda ADHD vardı. %75’i eşlikçi çalışma (body doubling) kullandığını söyledi. Bu, bir işe başlarken ya da çalışırken odada, çevrim içi görüşmede veya medya aracılığıyla birinin bulunmasıdır. Çoğunlukla arkadaşlar, aile ya da iş arkadaşlarıyla; ev işleri, okul işleri ve iş görevleri için kullanılıyordu. Katılımcılar bunu başlamak, odaklanmak, daha az kaygılanmak ve motivasyon bulmak için kullandıklarını bildirdi.",limitation:"Gönüllülerin katıldığı, çevrim içi deneyim anketidir. Kontrollü bir çalışma değildir. Eşlikçi çalışmanın nasıl kullanıldığını gösterir, ne kadar etkili olduğunu değil. Katılımcılar çoğunlukla ABD ve AB’den, kendini kadın olarak tanımlayan kişilerdi."}],l={"adhd-1":{deeper:[{heading:"Hatırlatıcıyı işin yapılacağı yere koy",paragraphs:["Barkley’nin temel düşüncesi, desteği harekete geçmen gereken yerde ve anda sunmaktır. Yalnızca zihnindeki hatırlatıcılar o anda yeterli olmayabilir. Bu yüzden bilgiyi tam o noktada somut ve görünür kılmayı önerir. Buzdolabındaki liste, bilgisayar kapağındaki not ya da ne yapacağını söyleyen bir alarm hatırlama yükünü üstlenir. Böylece çalışma belleğinin yükü azalır.","Bu yüzden bu derste her şeyi daha iyi hatırlamaya değil, tek bir liste oluşturmaya çalışıyoruz. Listenin güzel olması gerekmez. Gerektiğinde görebileceğin bir yerde olması yeterlidir."],visual:{kind:"compare",title:"Zihninde tutmak ya da görünür kılmak",left:{label:"Zihninde tutulan",items:["Gece 2’de hatırlanır, öğleden sonra 2’de unutulur","Aklından geçen her şeyle yarışır","Tam ihtiyacın olduğunda görünmez"]},right:{label:"Görünür kayıt",items:["Baktığın tek bir yere yazılır","İşin yapıldığı yere konur","Dikkatini işin kendisine ayırmanı sağlar"]},note:"Barkley’nin, bilgiyi harekete geçmen gereken yerde görünür kılma düşüncesine dayanır."}},{heading:"BDT programı bunu nasıl yapıyor?",paragraphs:["Steven Safren ve arkadaşlarının programında ilk seanslarda iki araç hazırlanır. Tarihi ya da saati olan işler tek bir takvime, geri kalanlar tek bir yapılacaklar listesine yazılır. İkisi de her gün kontrol edilir. İşlere basit bir öncelik derecesi verilir. Büyük işler yapılabilir adımlara bölünür.","Önemli bir nokta var: Listeye bakmak, her şeyi hemen yapmak zorunda olduğun anlamına gelmez. Liste seçeneklerini açıkça görmeni sağlar. Bakmaktan kaçındığında ise işler beklenmedik anda karşına çıkabilir. Bu, listenin kendisinden daha çok stres yaratabilir."],visual:{kind:"table",title:"İki araç, iki iş",columns:["Araç","Ne yazılır?","Ne zaman bakarsın?"],rows:[["Takvim","Randevular, son tarihler, saati olan her şey","Her gün belirlediğin bir anda"],["Yapılacaklar listesi","Yapman gereken diğer her şey","Takvime baktığın anda"],["Başka hiçbir yer","Ayrı notları ve hatırlatıcıları bu iki yere taşı","Birini bulduğunda"]],note:"Yetişkinlerde ADHD için BDT programının düzenleme modülünden uyarlanmıştır. Programın bütünü terapist eşliğinde yürütülür."}}],example:{title:"Elif, 34, diş hijyeni uzmanı",text:"Elif yapacaklarını dört yerde tutuyordu: İki uygulama, bir defter ve elinin üzerine yazdığı notlar. Pazar akşamı tek bir yer seçti. Telefonunun ana ekranındaki sade bir nota beş iş yazdı: Araç kaydını yenilemek, ev sahibini aramak, kız kardeşine doğum günü kartı almak, kütüphane kitabını iade etmek ve göz muayenesi için randevu almak. Göz muayenesini ve ev sahibiyle görüşmeyi saatleriyle takvimine yazdı. Her sabah kahvesi hazırlanırken nota bakmaya karar verdi. Pazartesi yalnızca doğum günü kartını alabildi. Diğer dört iş salı günü hâlâ listede duruyordu; aklında taşımak zorunda değildi. Cumaya kadar üç işi tamamladı. Liste bütün hafta kullanıldı. Bu onun için bir ilkti."}},"adhd-2":{deeper:[{heading:"Küçük adımlar neden yardımcı olur?",paragraphs:["Barkley’ye göre ADHD’de uzak gelecek silik kalabilir. Hemen önündeki şeyler ise çok daha baskın hissedilir. Bir ay sonra teslim edilecek proje, acil hâle gelene kadar dikkatini çekmeyebilir. Uzun işleri kısa adımlara bölmeyi ve her adımın ardından hızlı geri bildirim almayı önerir. Böylece ilerlemeyi belirsiz bir gelecekte değil, bugün görürsün.","Yetişkinlerde ADHD için BDT programı da bunaltıcı işleri yapılabilir adımlara böler. Her adım, listeye ayrı bir iş olarak yazılır."],visual:{kind:"steps",title:"İlk hareketi belirle",steps:[{label:"Adını koy",text:"İşi genelde düşündüğün gibi yaz: “vergileri hallet.”"},{label:"Sor",text:"Ellerim önce ne yapacak?"},{label:"Fiil + nesne",text:"“Vergi klasörünü aç ve geçen yılın beyannamesini bul.”"},{label:"Küçült",text:"Hâlâ takılıyor musun? Daha da küçült: “Klasörü raftan indir.”"}],note:"Önümüzdeki bir dakika içinde başlayabiliyorsan, ilk adım yeterince küçüktür."}},{heading:"Başlamayı daha cazip hâle getir",paragraphs:["Barkley, hatırlatıcıların tek başına çoğu zaman yetmediğini söyler. Uzak bir ödül, o anda yeterince çekici gelmeyebilir. Bu yüzden harekete geçeceğin ana motivasyon eklemeyi önerir. Adımın ardından küçük bir ödül, senden haber bekleyen biri ya da başkasıyla paylaştığın bir son tarih olabilir.","Sana uygun biçimleri deneyebilirsin. Evrak işleri yaparken sevdiğin bir çalma listesi açmak, ilk e-postadan sonra kahve içmek ya da başlayınca bir arkadaşına iki kelimelik mesaj göndermek gibi. Bunlar kişisel denemelerdir; tek tek kanıtlanmış yöntemler değildir. Sana yardımcı olanları kullanmaya devam et."]},{heading:"Sık yapılan hatalar",paragraphs:["En yaygın hata, adımı küçültürken ne yapılacağını belirsiz bırakmaktır. Rapor üzerinde biraz çalışmak hâlâ belirsizdir. Raporu açıp son paragrafı okumak ise açıktır. Bir başka hata, adımı sayılmayacak kadar küçük bulmaktır. Gerçekten yaptığın küçük bir başlangıç, uygulamadığın büyük bir plandan daha yararlıdır."]}],example:{title:"Murat, 41, depo sorumlusu",text:"Murat’ın listesinin başında üç haftadır sigorta hasar dosyasını halletmek vardı. Sürekli bu işi geçiyordu. Perşembe günü kendine sordu: Ellerim önce ne yapacak? Yanıt neredeyse komik derecede basitti: Sigorta şirketinin e-postasını bulmak. İşini şöyle yazdı: Gelen kutusunda hasar numarası diye ara ve e-postayı yıldızla. Kırk saniye sürdü. E-posta açılınca formu da indirdi. Orada durdu; bu ona yeterli geldi. Cuma günkü adım açıktı: İlk sayfayı doldurmak. Kardeşine dosyaya başladım diye mesaj gönderdi. Gelen başparmak emojisi, beklemediği kadar iyi bir ödül oldu. Dosyayı sonraki salı gönderdi."}},"adhd-3":{deeper:[{heading:"Zamanın geçtiğini neden fark etmeyebilirsin?",paragraphs:["Barkley, ADHD’de zaman miyopluğu dediği bir durumdan söz eder. Davranışını daha çok o anda olanlar yönlendirir. Uzak gelecekteki sonuçlar daha az etkili olur. Gelecek cuma teslim edilecek bir iş, perşembe gecesine kadar gerçek gibi gelmeyebilir. Bu bir karakter kusuru değildir. Araçlarını bu güçlüğü hesaba katarak düzenleyebilirsin.","Zamanı yakınına getir. İşini yaptığın yerde somut ve görünür kıl. Uzun süreleri, sonunda nasıl ilerlediğini kontrol edeceğin kısa aralıklara böl. Görünür bir geri sayım, sonra düşüncesini sekiz dakika sonra gibi somut bir bilgiye dönüştürür."],visual:{kind:"table",title:"Zamanı görünür kılmanın yolları",columns:["Araç","Ne yapar","Ne zaman deneyebilirsin?"],rows:[["Görüş alanındaki saat","Telefona bakmadan zamanı gözünün önünde tutar","Öğleden sonranın nasıl geçtiğini fark etmediğinde"],["Görünür geri sayım sayacı","Azalan zamanı bir şekil veya sayı olarak gösterir","İşlere geç başladığında ya da süreyi aştığında"],["Etiketli alarm","Ne yapacağını hatırlatır: Şimdi çocuğu almaya çık","Bir işten diğerine geçmeyi unuttuğunda"],["Tahmin ve kontrol kaydı","Tahminini gerçek süreyle karşılaştırır","Planların hep fazla dolu olduğunda"]],note:"Zamanı görünür kılmanın günlük hayatta kullanılabilecek yolları. Tek bir aracın en iyi olduğu kanıtlanmadı. Sana yardımcı olanı seç."}},{heading:"Beceri programları hakkında araştırma ne diyor?",paragraphs:["Yetişkinlerde ADHD için yapılandırılmış BDT, randomize çalışmalarda sınandı. Programlar planlama ve zamanla ilgili becerileri de içerir. 2020 tarihli bir meta-analizde, belirtiler üzerindeki etki bekleme listelerine göre orta ile büyük düzey arasındaydı. Başka bir etkin uygulama alan kontrol gruplarına göre ise küçük ile orta düzey arasındaydı.","Bu programlar eğitimli terapistler tarafından birkaç hafta boyunca yürütülür. Bu kısa kurs becerileri tanıtabilir. Ama aynı program değildir ve kendisi araştırmayla sınanmadı."],visual:{kind:"bars",title:"Yetişkinlerde ADHD için BDT: belirtiler üzerindeki ortalama etki",bars:[{label:"Bekleme listesiyle karşılaştırma (4 çalışma)",value:.76,display:"SMD 0,76"},{label:"Etkin kontrolle karşılaştırma (3 çalışma)",value:.43,display:"SMD 0,43"}],note:"Young, Moghaddam & Tickle 2020: Az sayıda çalışma, sınırlı katılımcı grupları. Bulgular terapist eşliğindeki programlara aittir. Kendi başına okumaya ait değildir; bu kurs sınanmadı.",sourceId:"adhd-cbt-meta"}}],example:{title:"Ayşe, 27, yüksek lisans öğrencisi",text:"Ayşe, danışmanına e-posta yanıtı yazmanın iki dakika süreceğini sanıyordu. Araya sıkıştıracağını düşünüp sürekli erteliyordu. Çarşamba günü tahminini bir nota yazdı: 5 dakika. Sonra görebileceği bir telefon zamanlayıcısı başlattı. Alarm çaldığında ancak yarıya gelmişti. İş toplam 17 dakika sürdü. Üzülmedi; bu bilgi işine yarıyordu. Sonraki iş, bir makalenin bölümünü okumaktı. 20 dakika tahmin etti, 26 dakika sürdü. Cumaya doğru tahminlerinin yaklaşık üçte bir kısa olduğunu fark etti. Takvimine bu ek süreyi koymaya başladı. Öğleden sonraları daha az telaşlı geçiyordu. Daha hızlı çalışmıyordu; planladığı süre artık gerçeğe uyuyordu."}},"adhd-4":{deeper:[{heading:"Dikkatini dağıtan düşünceyi ertelemek",paragraphs:["Yetişkinlerde ADHD için BDT programında, dikkati dağıtan düşünceleri erteleme tekniği vardır. Önce pek ilgini çekmeyen bir işte, dikkatin dağılmadan ne kadar çalışabildiğini ölçersin. Sonra yaklaşık bu uzunlukta aralıklarla çalışırsın. Yanında bir not defteri bulunur. Başka bir düşünce gelince hemen peşinden gitmek yerine not alırsın. Süre bitince notlara bakar, hangilerini yapman gerektiğine karar verirsin.","Not almak, düşünceyi ertelemeyi kolaylaştırır. Düşünceyi yok saymazsın. Ona daha sonra bakacağın bir zaman ayırırsın."],visual:{kind:"cycle",title:"Düşünceyi not al, işe dön",center:"Bir çalışma aralığı",nodes:[{label:"Çalış",text:"Genelde odaklanabildiğin süreye yakın bir çalışma aralığı başlat."},{label:"Düşünce belirir",text:"Başka bir iş aklına gelir."},{label:"Yaz",text:"“Sonra” yazan kâğıda birkaç kelime yaz."},{label:"Geri dön",text:"Kaldığın yeri bul ve bir adım daha at."},{label:"Zamanlayıcı biter",text:"Kâğıda bak ve neyin yapılması gerektiğine karar ver."}],note:"Yetişkinlerde ADHD için BDT programının dikkat dağınıklığı modülünden uyarlanmıştır."}},{heading:"Eşlikçi çalışma: birinin yanında çalışmak",paragraphs:["ADHD’li pek çok kişi eşlikçi çalışma (body doubling) kullandığını anlatır. Bir işe başlarken ya da çalışırken başka biri yanında bulunur. Aynı odada, görüntülü görüşmede, hatta birlikte çalışma videosunda olabilir. 2024’te çoğu ADHD’li 220 kişiyle yapılan ankette, her dört kişiden üçü bu yöntemi kullandığını söyledi. Daha çok ev işleri, okul işleri ve iş görevlerinde başlamak, odaklanmak ve daha az kaygılanmak için kullanıyorlardı.","Bu anket kişilerin deneyimlerini anlatır. Eşlikçi çalışmanın herkes için işe yaradığını kanıtlamaz. Yine de deneyebilirsin. Bir arkadaşından yanında 25 dakika e-postalarını yanıtlamasını iste. Ya da sessiz bir çevrim içi ortak çalışma odasına katıl."]},{heading:"Çalışma alanını düzenle",paragraphs:["Programda çalışma alanı da düzenlenir. Sık dikkatini dağıtan şeylerden uzak bir yer seçilir. Gereken malzemeler el altında, telefon gözden uzakta tutulur. Molalar önceden planlanır. Başta kaldırdığın her dikkat dağıtıcı, çalışırken karşı koyman gereken bir şeyi azaltır."]}],example:{title:"Cem, 38, serbest grafik tasarımcı",text:"Cem faturayı bitirmek için oturdu. Bir dakika içinde diş hekimi, müşterinin yazı tipi sorusu ve bulaşık makinesi aklına geldi. Genelde her düşünce onu başka bir işe götürürdü. Bu kez klavyenin yanında Sonra yazan küçük bir kart vardı. İdari işlerde genelde odaklanabildiği süre olan 12 dakika için zamanlayıcı kurdu. Diş hekimi, yazı tipi sorusu ve bulaşık makinesini birkaç kelimeyle yazdı. Sonra parmağıyla faturada kaldığı satırı buldu. Alarm çalınca fatura tamamlanmıştı. Karta baktı. Yazı tipi sorusuna yanıt vermeliydi, diğer ikisi akşama kalabilirdi. Ertesi gün aynı yöntemi, bir arkadaşıyla görüntülü görüşmede sessizce çalışarak denedi. Beklediğinden fazla yardımcı oldu."}},"adhd-5":{deeper:[{heading:"Kullandığın yöntemi gözden geçir",paragraphs:["Yetişkinlerde ADHD için BDT programı iki düşünce tuzağını ele alır. Biri aşırı olumsuzdur: Bunu asla beceremem, neden deneyeyim? Diğeri aşırı iyimserdir: Bugün on işi de yaparım. Gün bittiğinde işler tamamlanmazsa hayal kırıklığı ve kendini eleştirme başlayabilir. İki düşünce de listeden tamamen kaçınmana yol açabilir.","Programda bu düşünceleri fark edip yaşadıklarına dayanan daha gerçekçi düşüncelerle değiştirmeyi öğrenirsin. Kullandığın aracı gözden geçirmek de bunu sağlar. Kendin hakkında hüküm vermek yerine, sistemde neyi değiştirebileceğini sorarsın."],visual:{kind:"compare",title:"İki düşünce tuzağı ve gerçekçi bir yanıt",left:{label:"Tuzak",items:["Listeleri hiç kullanamıyorum. (fazla olumsuz)","Bugün on işin hepsini bitireceğim. (fazla iyimser)","Bir kez işe yaramadı, demek ki hiç yaramıyor."]},right:{label:"Gerçekçi yanıt",items:["Listeyi görmüyordum. Buzdolabına asacağım.","İki iş seçeceğim. Sonra günün nasıl gittiğine bakacağım.","Bir şeyi değiştirip üç kez daha deneyeceğim."]},note:"Yetişkinlerde ADHD için BDT programının daha gerçekçi düşünme modülünden uyarlanmıştır."}},{heading:"Ne zaman ve nasıl profesyonel destek almalı?",paragraphs:["ABD Ulusal Ruh Sağlığı Enstitüsü’ne (NIMH) göre ADHD tanısını bir sağlık uzmanı koyar. Yetişkinleri değerlendirirken belirtilerin çocuklukta başlayıp başlamadığına da bakılır. En yaygın tedaviler, genellikle uyarıcı türündeki ilaçlar ve davranışçı ya da bilişsel davranışçı terapidir. Bazı yetişkinler ADHD koçuyla çalışır ya da işyerinde ihtiyaçlarına uygun düzenlemeler ister.","Randevu almak için yaşadıklarını kusursuz anlatman gerekmez. Birkaç somut örnek, denediğin yöntemler ve sorularınla gidebilirsin. İlaç kullanıyorsan kendi başına bırakma ya da değiştirme. İlacı yazan doktorunla konuş."],visual:{kind:"steps",title:"Randevuya hazırlanmak",steps:[{label:"Örnekler",text:"Yakın zamanda dikkat ya da düzenleme güçlüğünün soruna yol açtığı üç durum yaz."},{label:"Nerede ve ne zaman",text:"İşte, evde ya da ilişkilerinde mi oluyor? Ne zamandan beri? Not al."},{label:"Ne denedin",text:"Bu kurstaki araçları ve neyin işe yarayıp yaramadığını listele."},{label:"Sorular",text:"Değerlendirme ve tedavi seçenekleriyle ilgili sorularını götür."}],note:"Hazırlık görüşmeye yardımcı olur; değerlendirmenin kendisini bir uzman yapar."}}],example:{title:"Hülya, 45, okul yöneticisi",text:"Hülya’nın listesi iki hafta işe yaradı. Sonra bir posta yığınının altında kayboldu. İlk düşüncesi “Ben hep sistemleri bozarım” oldu. Başka bir açıdan bakmayı denedi: Tam olarak ne ters gitti? Liste masasındaydı ama sabahları mutfakta başlıyordu. Tek bir şeyi değiştirdi. Kahve makinesinin yanına beyaz tahta koydu ve sonraki üç denemede onu kullandı. İşe yaradı. Aynı zamanda yaşadığı güçlüklerin listelerle sınırlı olmadığını kabul etti. Ödenmesi unutulan faturalar, yarım kalan projeler ve hayatı boyunca duyduğu “Yeterince çabalamıyorsun” sözü vardı. Üç somut örnek yazıp doktoruna götürdü. Hızlı bir yanıt beklemiyordu. Ama ilk kez sorunu doğru anlatabildiğini hissetti."},sources:["adhd-cbt-program"]}};l["adhd-1"].sources=["adhd-barkley","adhd-cbt-program","adhd-safren-workbook"];l["adhd-2"].sources=["adhd-cbt-program","adhd-barkley"];l["adhd-3"].sources=["adhd-barkley","adhd-cbt-meta"];l["adhd-4"].sources=["adhd-cbt-program","adhd-safren-workbook","adhd-body-doubling"];const ea=Object.freeze(Object.defineProperty({__proto__:null,EXTRAS:l,SOURCES:Xe},Symbol.toStringTag,{value:"Module"})),aa=[{id:"motivation-lally",title:"Surrey Üniversitesi · “Bir alışkanlık edinmek gerçekten 66 gün mü sürer?” Dr. Pippa Lally ile söyleşi",url:"https://www.surrey.ac.uk/news/does-it-really-take-66-days-form-habit-we-asked-expert-dr-pippa-lally",type:"guidance",finding:"Lally, 2010 tarihli çalışmasında günlük bir alışkanlığın ortalama 66 günde oluştuğunu anlatıyor. Ancak süre 18 ile 254 gün arasında değişiyordu. Alışkanlık edinme süresinin çok değişken olduğunu vurguluyor. Bilmenin tek başına davranışı değiştirmediğini belirtiyor ve neyi, ne zaman, nerede yapacağını belirleyen net bir plan öneriyor.",limitation:"Çalışmayı özetleyen bir üniversite haber söyleşisidir, makalenin kendisi değildir. Rakamlar tek bir örneklemi ve günlük davranışları anlatır; senin süren farklı olabilir."},{id:"motivation-fogg",title:"BJ Fogg · Tiny Habits (2020), Forbes söyleşisi, “Stanford’lı davranış bilimci değişimin anahtarının bu olduğunu söylüyor”",url:"https://www.forbes.com/sites/alisacohn/2020/02/25/stanford-behavior-scientist-says-this-one-thing-is-the-key-to-change/",type:"technique",finding:"Fogg’un yöntemi üç parçadan oluşuyor. İlki bir çıpa: diş fırçalamak gibi her gün yaptığın ve yeni davranışı hatırlatan bir şey. İkincisi küçük bir davranış: örneğin yirmi dakika yerine bir dakika meditasyon yapmak ya da yalnızca bir dişin arasını diş ipiyle temizlemek. Üçüncüsü, hemen ardından kutlamak. Fogg’a göre alışkanlığı oluşturan, davranışla birlikte yaşanan olumlu duygu.",limitation:"Kitabı anlatan bir söyleşi. Kitap Fogg’un kendi çalışmalarına ve koçluk deneyimine dayanıyor. Bulabildiğimiz kadarıyla yöntemin tamamını ve özellikle kutlama adımını destekleyen bağımsız kontrollü araştırmalar az."},{id:"motivation-fogg-model",title:"BJ Fogg · Fogg davranış modeli (behaviormodel.org)",url:"https://behaviormodel.org/",type:"guidance",finding:"Modelin formülü B = MAP. Buna göre motivasyon, yapabilme ve bir hatırlatıcı aynı anda bulunduğunda davranış gerçekleşir. Davranış gerçekleşmiyorsa bu üçünden en az biri eksiktir.",limitation:"Yazarın kendi sitesinde sunduğu açıklayıcı bir model; bir deney sonucu değil. Aksayan bir alışkanlıkta neyin eksik olduğunu anlamaya yardımcı olabilir. Ölçümlere dayanan bir öngörü sunmaz."},{id:"motivation-woop",title:"Gabriele Oettingen · WOOP: Dilek, Sonuç, Engel, Plan (woopmylife.org)",url:"https://woopmylife.org/",type:"technique",finding:"Psikolog Gabriele Oettingen’in geliştirdiği WOOP’un dört adımı var: bir isteğini belirle, en iyi sonucu hayal et, seni engelleyen duygu, düşünce ya da alışkanlığı fark et. Sonra bu engelle karşılaşınca ne yapacağını belirleyen bir eğer-öyleyse planı yaz. Site, yöntemi istekleri gerçekleştirmek ve alışkanlıkları değiştirmek için bilime dayalı bir zihinsel strateji olarak tanımlıyor.",limitation:"Yöntemin resmî sitesidir. Zihinsel karşılaştırmayı eğer-öyleyse planlarıyla birleştiren araştırmalar küçük ile orta arası ortalama etkiler gösterir (bkz. Wang ve ark. meta-analizi); sitenin kendisi okundu, her çalışma okunmadı."},{id:"motivation-milkman",title:"Katy Milkman · Keyifli bir şeyle eşleştirme (Character Lab önerisi; bkz. ayrıca How to Change, 2021)",url:"https://characterlab.org/tips-of-the-week/temptation-bundling/",type:"technique",finding:"Wharton profesörü Milkman, zevk aldığın bir şeyi yararlı ama angarya gibi gelen bir işle eşleştirmeyi öneriyor. Örneğin sürükleyici bir romanı yalnızca egzersiz yaparken okumak ya da sevdiğin diziyi yalnızca ev işi yaparken izlemek. Böylece hedefin için çalışmak daha keyifli hâle geliyor.",limitation:"Araştırmacının kısa bir pratik önerisi. Saha çalışmalarında egzersiz için sınırlı bir ortalama yarar görüldü. Diğer yaşam alanlarındaki etkisi daha az incelendi."},{id:"motivation-bundling-gym",title:"Milkman, Minson & Volpp · 2014 · Spor salonunda keyifli bir şeyle eşleştirme (Knowledge at Wharton özeti)",url:"https://knowledge.wharton.upenn.edu/article/researchers-used-hunger-games-encourage-healthier-choices/",type:"research",finding:"Üniversitenin spor salonuna üye 226 kişiyle dokuz haftalık bir deney yapıldı. Sürükleyici sesli kitapları yalnızca salonda dinleyebilenler, başlangıçta kontrol grubuna göre salona %51 daha sık gitti. Etki Şükran Günü tatilinden sonra zayıfladı. Deneyin sonunda katılımcıların %61’i, sesli kitapları yalnızca salonda dinlemeye devam etmek için ödeme yapmayı seçti.",limitation:"Tek bir üniversite örneklemi ve kısa bir çalışma; etki de zamanla geçti. Makalenin bir üniversite haber özeti okundu, makalenin tamamı değil."},{id:"motivation-bundling-teaching",title:"Kirgios ve ark. · 2020 · Egzersizi artırmak için keyifli bir şeyle eşleştirmeyi öğretmek: bir saha deneyi",url:"https://www.sciencedirect.com/science/article/pii/S074959782030385X",type:"research",finding:"6.792 spor salonu üyesiyle yapılan geniş bir saha deneyinde, bir gruba sesli kitap verildi ve kitabı egzersizle eşleştirmeleri önerildi. Bu grubun herhangi bir haftada antrenman yapma olasılığı kontrol grubuna göre %10–14 daha yüksekti. Haftalık antrenman sayısı da %10–12 daha fazlaydı. Yararlar 17 hafta sonrasına kadar görüldü.",limitation:"Spor salonu üyelerinde egzersiz için mütevazı bir ortalama etki; başka hedefler için sınanmadı. Yalnızca özet okundu."}],ia={"motivation-1":{deeper:[{heading:"Kalıcı motivasyonun ardındaki üç ihtiyaç",paragraphs:["Psikologlar Edward Deci ve Richard Ryan’ın geliştirdiği öz belirleme kuramına göre, üç temel ihtiyaç karşılandığında motivasyon daha uzun sürer. Özerklik, başkasının zoruyla değil, kendi seçiminle hareket ettiğini hissetmektir. Yeterlik, bunu yapabileceğine inanmaktır. İlişki kurma ise bu süreçte başkalarıyla bağının olmasıdır.","Kuram iki tür motivasyonu ayırır. Özerk motivasyon, ilginden ya da değerlerinden doğar. Kontrollü motivasyonun kaynağı baskı, ödül ya da başkalarının beklentileridir. İkisi de seni harekete geçirebilir. Ama ilki genellikle daha kalıcıdır."],visual:{kind:"table",title:"Üç ihtiyaç, üç soru",columns:["İhtiyaç","Ne demek","Kendine sor"],rows:[["Özerklik","Kendi seçiminle hareket etmek","Bunu ben mi seçiyorum, yoksa yapmam gerektiğini mi düşünüyorum?"],["Yeterlik","Bunu yapabileceğini hissetmek","İlk adım başarabileceğim kadar küçük mü?"],["İlişki kurma","Başkalarıyla bağ hissetmek","Bunu kim benimle paylaşabilir ya da beni destekleyebilir?"]],note:"Öz belirleme kuramına (Deci ve Ryan) dayanır. Sorular ODA’nın uyarlamasıdır."}},{heading:"Araştırma ne diyor?",paragraphs:["2021 tarihli bir meta-analiz, öz belirleme kuramına dayanan 73 sağlık uygulaması çalışmasını bir araya getirdi. Bu uygulamalar, özerk motivasyonda ve ilgili ölçümlerde ortalama küçük ile orta düzeyde artış sağladı. Fiziksel ve psikolojik sağlıkta küçük iyileşmeler görüldü. Özerk motivasyon arttığında sağlıkla ilgili davranışlar da genellikle iyileşiyordu.","Etkiler sınırlıydı ve çalışmadan çalışmaya değişiyordu. Üstelik araştırmalar yalnızca sağlık alışkanlıklarıyla ilgiliydi. Yine de şu fikir işe yarayabilir: gerçekten benimsediğin bir hedefle başlamak, sırf bir hedefin olmalı diye düşündüğün bir şeyi seçmekten daha iyi olabilir."]}],example:{title:"Serkan, 31, müşteri hizmetleri temsilcisi",text:"Serkan’ın hedef listesinde üç yıldır “maraton koşmak” vardı; çoğunlukla iki iş arkadaşı kendi hedeflerinden bahsettiği için. Gününde neyi değiştirmek istediğini kendine sorduğunda dürüst cevap farklıydı: işten sonra bedenindeki tutulmayı azaltmak ve hava kararmadan biraz dışarıda zaman geçirmek istiyordu. İkisi için de maraton gerekmiyordu. Hedefi “mesaimden sonra parkta 20 dakikalık yürüyüş, haftada üç gün” diye yeniden yazdı. Aynı saatte köpeğini gezdiren komşusuna da salı günleri ona katılıp katılamayacağını sordu. İlk hafta iki kez yürüdü. Maratondan küçük bir hedefti ama kendi isteğiydi. Üstelik yürüyüş saatini iple çekiyordu."},sources:["motivation-sdt","motivation-sdt-meta"]},"motivation-2":{deeper:[{heading:"Davranış için istek, yapabilme ve hatırlatıcı gerekir",paragraphs:["Stanford’da çalışan davranış bilimci BJ Fogg, modelini B = MAP formülüyle anlatır. Buna göre motivasyon, yapabilme ve bir hatırlatıcı aynı anda bulunduğunda davranış gerçekleşir. Davranış gerçekleşmiyorsa bu üçünden en az biri eksiktir.","Motivasyonun artıp azalır; ona her zaman güvenemezsin. Yapabilme ise davranışın senin için ne kadar kolay olduğuyla ilgilidir. Bunu kolaylaştırabilirsin. Başlangıcı küçültmek bu yüzden işe yarar: ilk adım kolay olunca, motivasyonunun düşük olduğu bir anda da başlayabilirsin."],visual:{kind:"table",title:"B = MAP: eksik parçayı bul",columns:["Öğe","Soru","Örnek çözüm"],rows:[["Motivasyon","Bunu gerçekten istiyor muyum?","Senin için neden önemli olduğunu hatırla (1. ders)"],["Yapabilme","Şu an yeterince kolay mı?","Bir bölüm yerine bir sayfa"],["Hatırlatıcı","Doğru anda bunu bana ne hatırlatır?","Yastığın üstünde kitap (3. ders)"]],note:"Fogg davranış modeli’ne dayanır. Bir davranış aksadığında hangi parçanın eksik olduğuna bak."}},{heading:"Fogg neden küçük bir kutlama ekliyor?",paragraphs:["Fogg, Tiny Habits yöntemine birçok kişinin atladığı bir adım ekler: küçük davranışı yapar yapmaz kutlamak. Sessizce “Evet!” diyebilir ya da gülümseyebilirsin. Ona göre davranışla birlikte yaşanan olumlu duygu, alışkanlığın yerleşmesine yardımcı olur.","Yöntemin bu kısmı, kontrollü çalışmalardan çok Fogg’un deneyimine ve koçluk çalışmalarına dayanıyor. Bu yüzden deneyip sana uyup uymadığına bak. Küçük bir sevinç anı yarın yeniden yapmanı kolaylaştırıyorsa devam et. Zorlama geliyorsa, yaptığını bir tik işaretiyle kaydetmek de aynı işe yarayabilir."]}],example:{title:"Nurten, 52, eczacı",text:"Nurten akşamları esneme hareketleri yapmak istiyordu. Ama sofrayı topladığında 20 dakikalık bir rutin imkânsız geliyordu. Tek bir hareketle başlamaya karar verdi: üç nefes boyunca ayak parmaklarına dokunacak kadar öne eğilmek. Yoga minderini koltuğun yanına serip bıraktı. Pazartesi günü bu hareketi yaptı. Sonra kendisi de şaşırarak iki hareket daha ekledi. Salı günü bitkindi ve yalnızca ilkini yaptı. Ardından yüksek sesle “Tamam” deyince güldü. Hafta sonuna doğru minder salonun bir parçası olmuştu. Tek hareket, çoğu akşam beş altı harekete dönüşmüştü. Bazı akşamlar yine yalnızca birini yapıyordu. Bunun da sayılmasına karar verdi."},sources:["motivation-fogg","motivation-fogg-model"]},"motivation-3":{deeper:[{heading:"Çıpayı davranışa bağla",paragraphs:["BJ Fogg, hatırlatıcı olarak kullandığın günlük davranışa çıpa der. Bağlantıyı şöyle kurar: “[Çıpa]dan sonra [küçük davranış]ı yapacağım.” Çıpa, her gün düşünmeden yaptığın bir şey olmalı. Yeni davranış da aynı yerde kolayca yapılabilmeli. Örneğin diş ipi kullanmak, işe giderken yaptığın yolculuktan çok diş fırçalamaya bağlanır.","Aynı koşullarda tekrar ettikçe, hatırlatıcı davranışı daha kolay aklına getirir. Zamanla daha az düşünerek yaparsın. Araştırmacıların alışkanlık dediği şey bu giderek artan otomatikleşmedir."],visual:{kind:"cycle",title:"Bir hatırlatıcı nasıl alışkanlığa dönüşür?",center:"Aynı koşullar, tekrar tekrar",nodes:[{label:"Hatırlatıcı",text:"Zaten yaptığın bir çıpa: “Çayımı doldurduktan sonra…”"},{label:"Küçük davranış",text:"“…kitabımı açacağım.”"},{label:"İyi his",text:"Küçük bir memnuniyet anı."},{label:"Tekrar",text:"Her gün aynı hatırlatıcı, aynı yer."}],note:"Alışkanlık araştırmalarına ve Fogg’un yöntemine dayanan basit bir şema. Sürecin nasıl işlediğini anlatır; ne kadar süreceğini söylemez."}},{heading:"Ne kadar sürer?",paragraphs:["Bir alışkanlığın 21 ya da 66 günde oluştuğunu duymuş olabilirsin. Pippa Lally’nin 2010 tarihli çalışmasında günlük bir alışkanlığın oluşması ortalama 66 gün sürmüştü. Ama süre 18 ile 254 gün arasında değişiyordu. Lally, asıl bulgunun bu büyük farklar olduğunu vurguluyor.","Yetişmen gereken bir tarih yok. Bir ay sonra alışkanlığını sürdürmek için hâlâ çabalıyorsan bu normal. Yanlış yaptığını göstermez."],visual:{kind:"bars",title:"Günlük bir alışkanlığın otomatikleşmesi için geçen gün sayısı",bars:[{label:"En hızlı",value:18,display:"18 gün"},{label:"Ortalama",value:66,display:"66 gün"},{label:"En yavaş",value:254,display:"254 gün"}],note:"Lally 2010, Lally’nin Surrey Üniversitesi söyleşisindeki anlatımıyla: tek bir örneklem ve yalnızca günlük davranışlar; senin süren farklı olabilir.",sourceId:"motivation-lally"}},{heading:"Sık yapılan hatalar",paragraphs:["En yaygın hatırlatıcı aynı zamanda en belirsizi: “Vaktim olduğunda.” Bunun belli bir zamanı yok. Her gün farklı saatte ya da yerde gerçekleşen bir çıpa seçmek de işi zorlaştırır. Düzenli yaptığın bir şey seç. Birkaç denemeden sonra işe yaramazsa, kendini suçlamadan önce hatırlatıcıyı değiştir."]}],example:{title:"Berk, 24, kurye",text:"Berk İspanyolca çalışmak istiyordu ama hep “sonra vakit bulurum” diyordu ve o vakit hiç gelmiyordu. Her gün aşağı yukarı aynı saatte olan bir şey aradı. Cevap öğle yemeğiydi: hep öğlen civarı minibüste yerdi. Tarifi şöyle oldu: “Yemeğimi açtıktan sonra dil uygulamamda bir ders yapacağım.” İlk iki gün unuttu, çünkü telefonu torpido gözündeydi. Onu bardaklığa taşıdı. Çarşamba günü işe yaradı, perşembe günü de. Cuma günü öğle yemeğini tamamen atladı, yani hatırlatıcı da olmadı. Dersi evde yaptı ve bunu dert etmedi. Üç hafta sonra, canı istemeyen günlerde bile yemeğini açmak ona dersi hatırlatıyordu."},sources:["motivation-fogg","motivation-lally"]},"motivation-4":{deeper:[{heading:"Yalnızca hayal etmek neden yetmez?",paragraphs:["Psikolog Gabriele Oettingen, zihinsel karşılaştırma denen bir yaklaşım geliştirdi. Önemsediğin isteği hayal eder, sonra seni neyin engellediğine açıkça bakarsın. Buna bir eğer-öyleyse planı eklenince dört adımlı WOOP yöntemi ortaya çıktı: Dilek, Sonuç, Engel, Plan (Wish, Outcome, Obstacle, Plan).","21 çalışmanın meta-analizinde, zihinsel karşılaştırmayı eğer-öyleyse planlarıyla birleştirmek hedeflere ulaşmayı ortalama küçük ile orta düzeyde artırdı. Etki var ama sınırlı. Yararlı bir araç olabilir; sonucu garanti etmez."],visual:{kind:"compare",title:"Olumlu hayal ya da zihinsel karşılaştırma",left:{label:"Yalnızca mutlu son",items:["Hedefe çoktan ulaşmış gibi hayal et","Şimdi iyi hisset","Engelle hazırlıksız karşılaş"]},right:{label:"Zihinsel karşılaştırma (WOOP)",items:["En iyi sonucu hayal et","İçindeki engeli adlandır","Onu bir eğer-öyleyse planına bağla"]},note:"Gabriele Oettingen’in WOOP yöntemine dayanır. Hayal kurmak yararlı olabilir. Önündeki engeli de açıkça görürsen daha çok işe yarar."}},{heading:"İçindeki engeller ve dış koşullar",paragraphs:["WOOP, seni engelleyen bir alışkanlığa, duyguya ya da düşünceye odaklanır. Çünkü bunlarla karşılaşınca ne yapacağını planlayabilirsin. Çocuğunun hasta olması, gece vardiyasında çalışmak ya da bütçenin dar olması da gerçek engellerdir. Ama bunlar için başka çözümler gerekir: hedefi küçültmek, zamanını ya da biçimini değiştirmek veya yardım istemek.","Bunları ayırt etmek seni iki tuzaktan korur: kontrol edemediğin şeyler için kendini suçlamak ve kontrol edebildiklerini görmezden gelmek."]}],example:{title:"Gamze, 36, banka gişe görevlisi",text:"Gamze haftada üç akşam gitar çalışmak istiyordu. Eve dönerken otobüste WOOP’u denedi. Dilek: yaza kadar üç şarkıyı iyi çalmak. En iyi sonuç: yeğeninin doğum gününde çalmak. Engel, açıkça bakınca: eve gelince “bir dakikalığına” kanepeye oturuyor ve akşam bitiyordu. Plan: “Kanepeye oturmak istersem, oturmadan önce gitarı kılıfından çıkaracağım.” İlk akşam planı unuttu. İkinci akşam hatırladı, gitarı çıkardı ve kanepenin üstünde on dakika çaldı. Perşembe günü mesaisi uzadı. Bu dışarıdan gelen bir engeldi. O yüzden suçluluk duymadan bıraktı ve cumartesi çaldı."},sources:["motivation-woop"]},"motivation-5":{deeper:[{heading:"Kaçırılan bir gün alışkanlığı silmez",paragraphs:["Lally’nin alışkanlık çalışmasında, davranışı bir kez yapmamak otomatikleşme sürecini belirgin biçimde aksatmadı. Daha önemli olan, yeniden yapmak gibi görünüyor. Bir günün aksamasından çok, ardından kendine söylediğin cümle sorun çıkarabilir: “Düzenimi bozdum, artık neden uğraşayım?”","Bir sonraki hatırlatıcıyı yeni bir fırsat saymak daha nazik ve yararlı bir yaklaşım. Büyük bir çabayla telafi etmek yerine davranışın küçük hâliyle yeniden başla."]},{heading:"Yeniden başlamayı daha keyifli yap",paragraphs:["Wharton profesörü Katy Milkman, yapmaktan kaçındığın bir işi keyifli bir şeyle eşleştirmenin etkisini inceliyor. İlk çalışmasında, sürükleyici sesli kitapları yalnızca spor salonunda dinleyebilenler başlangıçta salona kontrol grubundan %51 daha sık gitti. Ancak tatil arasından sonra etki zayıfladı.","6.792 spor salonu üyesiyle yapılan sonraki saha deneyinde daha küçük ama uzun süren bir etki görüldü. İnsanlara sesli kitabı egzersizle eşleştirmeyi öğretmek, herhangi bir haftada antrenman yapma olasılığını %10–14 artırdı. Yararlar 17 hafta sonrasına kadar görüldü. Etkisi sınırlı ama denemesi kolay."],visual:{kind:"table",title:"İki çalışmada keyifli bir şeyle eşleştirme",columns:["Çalışma","Kim","Ne oldu"],rows:[["Milkman ve ark. 2014","226 üniversite spor salonu üyesi","Yalnızca salona özel sesli kitaplarla başlangıçta %51 daha fazla ziyaret; etki bir aradan sonra zayıfladı"],["Kirgios ve ark. 2020","6.792 spor salonu üyesi","Eşleştirmeyi öğrenenlerde belirli bir haftada antrenman yapma olasılığı %10–14 daha yüksek, 17 haftaya kadar"]],note:"İki çalışma da egzersizle ilgilidir. Etki ortalama olarak mütevazıdır ve başka hedefler için farklı olabilir."}}],example:{title:"Kemal, 47, otobüs tamircisi",text:"Kemal, on bir gün boyunca akşam yürüyüşünü aksatmadı. Sonra bir aile ziyareti yüzünden beş gün yürüyemedi. İlk düşüncesi düzenini “mahvettiği” oldu. Telafi için iki kat mesafe yürümesi gerektiğini sandı. Sonra kısa haftalık notuna baktı. Ne işe yaramıştı? Yemekten hemen sonra yürümek ve podcast dinlemek. Ne ters gitmişti? Planında bir sorun yoktu; sadece yoğun bir haftaydı. Pazartesi günü küçük adımla yeniden başladı: yemekten sonra mahallede bir tur. Yürüyüşü daha keyifli yapmak için sevdiği futbol podcast’ini yalnızca yürürken dinlemeye karar verdi. O hafta dört kez yürüdü. Aksayan beş gün artık her şeyin bittiği anlamına gelmiyordu."},sources:["motivation-milkman","motivation-bundling-gym","motivation-bundling-teaching"]}},na=Object.freeze(Object.defineProperty({__proto__:null,EXTRAS:ia,SOURCES:aa},Symbol.toStringTag,{value:"Module"})),ta=[{id:"faith-hadith-good-intention",title:"Sahîh-i Buhârî 6491 · İyi bir işe niyet etmek",url:"https://sunnah.com/bukhari:6491",type:"religious",finding:"İbn Abbâs’tan rivayet edilmiştir: Peygamber (s.a.v.), bir kimse iyi bir işe niyet edip de onu yapamazsa Allah’ın bunu ona tam bir iyilik olarak yazdığını, niyet edip yaparsa kat kat yazdığını; niyet edilip de yapılmayan bir kötülüğün de bir iyilik olarak yazıldığını söylemiştir.",limitation:"Niyet konusundaki anlamıyla anılmıştır. Derste bunu planlamaya uyarlayan ODA’dır; dinî hüküm değildir."},{id:"faith-hadith-camel",title:"Câmiu’t-Tirmizî 2517 · “Önce bağla, sonra tevekkül et”",url:"https://sunnah.com/tirmidhi:2517",type:"religious",finding:"Enes b. Mâlik’ten rivayet edilmiştir. Bir adam, devesini bağlayıp mı yoksa serbest bırakıp mı Allah’a tevekkül etmesi gerektiğini sormuştur. Peygamber (s.a.v.) önce bağlamasını, sonra Allah’a tevekkül etmesini söylemiştir. Hasen (Darussalam) olarak derecelendirilmiştir.",limitation:"Tirmizî bu rivayeti garîb, yani alışılmadık, olarak nitelemiştir. Yalnızca bu senetle bildiğini, Amr b. Ümeyye’den benzer bir rivayet bulunduğunu da belirtmiştir. Ders bunu dinî hüküm olarak değil, yaygın kullanılan bir örnek olarak ele alır."},{id:"faith-quran-sufficient",title:"Kur’an-ı Kerim · Talâk 65:3",url:"https://quran.com/65/3",type:"religious",finding:"Ayet, kim Allah’a tevekkül ederse Allah’ın ona yeteceğini ve Allah’ın her şey için bir ölçü koyduğunu bildirir.",limitation:"Burada özetlenmiştir. Ders belirli bir dünyevî sonucu vaat etmez."},{id:"faith-quran-gratitude",title:"Kur’an-ı Kerim · İbrâhîm 14:7",url:"https://quran.com/14/7",type:"religious",finding:"Ayet, şükredenlere Allah’ın daha fazlasını vereceğini bildirir ve nankörlükten sakındırır.",limitation:"Burada özetlenmiştir. Bu dinî bir öğretidir, psikolojik bir bulgu değildir; ders bundan belirli bir maddî kazanç vaadi çıkarmaz."},{id:"faith-hadith-thank-people",title:"Sünen-i Ebû Dâvûd 4811 · İnsanlara teşekkür etmek",url:"https://sunnah.com/abudawud:4811",type:"religious",finding:"Ebû Hüreyre’den rivayet edilmiştir: Peygamber (s.a.v.), insanlara teşekkür etmeyenin Allah’a da şükretmiş olmayacağını söylemiştir. Elbânî tarafından sahih olarak derecelendirilmiştir.",limitation:"Anlamı için anılmıştır; teşekkür notu alıştırması ODA’nın uyarlamasıdır."},{id:"faith-hadith-believer",title:"Sahîh-i Müslim 2999 · Müminin hâli",url:"https://sunnah.com/muslim:2999",type:"religious",finding:"Süheyb’den rivayet edilmiştir. Peygamber (s.a.v.), müminin her hâlinde hayır bulunmasının dikkat çekici olduğunu söylemiştir. Hoşuna giden bir şey olduğunda şükreder; bu onun için hayırdır. Sıkıntıyla karşılaştığında sabreder; bu da onun için hayırdır.",limitation:"Sabır, derste çaba göstererek dayanmak olarak ele alınır. Bu ODA’nın yorumudur, dinî hüküm değildir. Zorluğu gizlemek ya da yardım almadan katlanmak gerektiği anlamına gelmez."},{id:"faith-quran-patience",title:"Kur’an-ı Kerim · Bakara 2:153",url:"https://quran.com/2/153",type:"religious",finding:"Ayet, müminleri sabır ve namazla yardım aramaya çağırır ve Allah’ın sabredenlerle beraber olduğunu bildirir.",limitation:"Burada anlamı özetlenmiştir. Psikolojik bir tedavi değildir. Tıbbi bakımın ya da ruh sağlığı desteğinin yerini tutmaz."},{id:"faith-religious-coping",title:"Ano & Vasconcelles · 2005 · Dinî başa çıkma ve stresle uyum üzerine meta-analiz",url:"https://mhwbf.org/wp-content/uploads/2019/02/Ano-2005-Religious-coping-and-psychological-ad.pdf",type:"research",finding:"49 çalışma, 13.512 kişi. Pargament’ın olumlu dinî başa çıkma dediği yaklaşımlar arasında manevi bağ kurmak, sorunlarla Allah’a güvenerek birlikte başa çıkmak, din görevlilerinden destek almak ve yaşananı iyilik yönünden yeniden değerlendirmek vardır. Bu yaklaşımlar, olumlu sonuçlarla orta düzeyde (r = 0,33), olumsuz sonuçların azlığıyla ise daha sınırlı düzeyde ilişkiliydi. Manevi hoşnutsuzluk ya da zorluğu Tanrı’dan gelen bir ceza olarak görme gibi olumsuz dinî başa çıkma biçimleri, daha fazla sıkıntı ve diğer olumsuz sonuçlarla ilişkiliydi (r = 0,22).",limitation:"Çalışmaların çoğu tek bir zaman noktasındaki ölçümlere ve kişilerin kendi bildirimlerine dayanır. Bu yüzden ilişkileri gösterir, nedenleri değil. Katılımcıların yaklaşık %85’i Protestan ya da Katolikti. Bulgular Müslümanlar için doğrudan geçerli olmayabilir. Tam metin okundu."},{id:"faith-hadith-consistent",title:"Sahîh-i Buhârî 6464 · Devamlı işler",url:"https://sunnah.com/bukhari:6464",type:"religious",finding:"Âişe’den rivayet edilmiştir: Peygamber (s.a.v.), iyi işleri doğru, samimi ve ölçülü yapmayı öğütlemiş ve Allah’a en sevimli işin, az da olsa en düzenli ve devamlı olanı olduğunu söylemiştir.",limitation:"Anlamı için anılmıştır; iyilik planı ODA’nın uygulamasıdır."},{id:"faith-hadith-smile",title:"Câmiu’t-Tirmizî 1956 · Gündelik sadaka örnekleri",url:"https://sunnah.com/tirmidhi:1956",type:"religious",finding:"Ebû Zer’den rivayet edilmiştir: Peygamber (s.a.v.), kardeşine gülümsemeyi, yolunu şaşırana yol göstermeyi, görmesi zayıf olana yardım etmeyi, yoldan taş, diken ya da kemik kaldırmayı ve kovandan başkasının kovasına su boşaltmayı sadaka saymıştır. Hasen (Darussalam) olarak derecelendirilmiştir.",limitation:"Özetlenmiştir; dersteki çağdaş örnekler ODA’nın uyarlamasıdır."}],ra={"faith-1":{deeper:[{heading:"Niyet ne demek?",paragraphs:["Niyet, bir davranışı neden yaptığını anlatan, kalbindeki amaçtır. Yemek pişirmek, işe gitmek ya da komşuna yardım etmek gibi aynı davranışlar, yapılış nedenine göre farklı anlamlar taşıyabilir.","Buhârî’de İbn Abbâs’tan rivayet edilen başka bir hadis umut verir. Bir kişi iyi bir işe niyet edip onu yapamazsa, yine de ona iyilik olarak yazılır. Samimi niyet, davranış tamamlanmadan da değerlidir. Bu, yalnızca niyet etmekle yetinmek için gerekçe değildir. Ama planın yarım kaldığında umutsuzluğa kapılmamanı hatırlatır."],visual:{kind:"table",title:"Niyet üzerine iki hadis",columns:["Kaynak","Anlamı (özetlenmiştir)","Dersteki yorum"],rows:[["Buhârî 1","Ameller niyetlere göre değerlendirilir","Sıradan bir işin ardındaki “neden”e bak"],["Buhârî 6491","Niyet edilen iyilik, yapılamasa da yazılır","Bir plan yarım kaldığında umutsuzluğa kapılma"]],note:"sunnah.com’dan özetlenmiştir. Sağ sütun ODA’nın yorumudur, dinî hüküm değildir."}},{heading:"Niyet mükemmeliyetçilik değildir",paragraphs:["Bazı insanlar iyi bir işi erteler, çünkü onu yapma nedenlerinin tamamen saf olmadığından endişelenir. Kendine dürüstçe bakmak değerlidir. Ama kusursuz bir niyet beklemek, başlamaktan kaçınmanın yoluna dönüşebilir. İçindeki farklı nedenleri fark edebilirsin. Güçlendirmek istediğin iyi nedeni seçip onun için küçük bir adım atabilirsin.","Basit bir plan burada da yardımcı olur. Niyetini ne zaman ve nerede uygulayacağını belirlemek, planlama araştırmalarının desteklediği bir yaklaşımdır. Psikolojiye ait bu bulgu dersin kaynaklarında ayrıca gösterilir. Alıştırmayı destekler; dinî bir öğretiyi kanıtlamaz ya da çürütmez."]}],example:{title:"Yusuf, 29, bilgi işlem teknisyeni",text:"Yusuf, yaşlı komşusunun yeni telefonunu kurmasına yardım edeceğine söz vermişti ama sürekli erteliyordu. Salı günü durup kendine bunu neden yapmak istediğini sordu. Bir nedeni suçluluk duyması, bir nedeni de iyi bir komşu olarak görünmek istemesiydi. Ama altında önemsediği başka bir şey vardı: Komşusunun torunlarından kopuk hissetmesini istemiyordu. Bu amacı seçti. Telefonu şarj etmek ve Wi-Fi şifresini yazmak gibi küçük bir hazırlık yaptı. Perşembe günü işten sonra komşusunun kapısını çaldı. İş kırk dakika sürdü. Dönerken suçluluğunun geçtiğini fark etti. Seçtiği niyet ise hâlâ anlamlıydı."},sources:["faith-hadith-good-intention"]},"faith-2":{deeper:[{heading:"Tevekkül: emek ve güven birlikte",paragraphs:["Tirmizî’nin derlemesindeki tanınmış bir hadiste bir adam, devesini bağlayıp mı yoksa serbest bırakıp mı Allah’a tevekkül etmesi gerektiğini sorar. Peygamber (s.a.v.) önce bağlamasını, sonra Allah’a tevekkül etmesini söyler. Tirmizî, rivayetin senedinin alışılmadık olduğunu belirtir. Yine de emek ve güvenin birlikte oluşunu açıkça anlattığı için bu hadis sık anılır.","Talâk 65:3, Allah’a tevekkül edene Allah’ın yeteceğini bildirir. Bu derste ayeti, elinde olmayan şeyler için bir dinginlik kaynağı olarak ele alıyoruz. Her sonucun istediğin gibi olacağını vaat ettiğini söylemiyoruz."],visual:{kind:"steps",title:"Âl-i İmrân 3:159’dan günlük hayata bir sıralama",steps:[{label:"İstişare et",text:"Güvendiğin biriyle konuş."},{label:"Karar ver",text:"Nasıl hareket edeceğini seç."},{label:"Hazırlan",text:"Elinde olan hazırlığı yap. Hadisteki örnekle, deveyi bağla."},{label:"Tevekkül et",text:"Sonucu Allah’a bırak. Elinde olmayanları bırakmayı dene."}],note:"ODA’nın 3:159 ve Tirmizî 2517 üzerine yorumudur; belirli bir sonuç vaat etmez."}},{heading:"Kaygı ağırlaştığında",paragraphs:["Belirsiz bir sonuç için endişelenmek insana özgüdür. İmanının zayıf olduğunu göstermez. Kaygı sürekli hâle gelirse, uykunu bozarsa ya da günlük yaşamını aksatırsa destek almayı hak edersin. Güvendiğin biriyle, bilgili bir imamla ya da ruh sağlığı uzmanıyla konuşmak da deveyi bağlamanın bir parçası olabilir."]}],example:{title:"Fatma, 22, hemşirelik öğrencisi",text:"Fatma’nın mesleki yeterlilik sınavına iki hafta vardı. Her gece uyanık kalıyor, başarısız olursa neler olacağını düşünüyordu. Pazar günü kâğıdı bir çizgiyle ikiye ayırdı. Sola yapabileceklerini yazdı: Kalp ilaçlarını tekrar etmek, günde bir deneme sınavı çözmek, sürekli yanlış yaptığı soruları hocasına sormak. Sağa kontrol edemeyeceklerini yazdı: Hangi soruların çıkacağı, ne kadar heyecanlanacağı, sonuç. O akşam hocasına e-posta gönderdi. Yatsı namazından sonra kendi sözleriyle kısa bir dua etti. Sağ sütundakileri bilinçli olarak Allah’a bıraktı. Kaygısı geçmedi ama artık zihninde daha az yer tutuyordu."},sources:["faith-hadith-camel","faith-quran-sufficient"]},"faith-3":{deeper:[{heading:"İslam geleneğinde şükür",paragraphs:["Şükür, Kur’an’ın temel konularından biridir. İbrâhîm 14:7, şükredenlere Allah’ın daha fazlasını vereceğini bildirir ve nankörlükten sakındırır. Burada şükür öncelikle her iyiliğin kaynağı olan Allah’a yöneliktir.","Ebû Dâvûd’un derlemesinde, Elbânî’nin sahih olarak derecelendirdiği bir hadis bunu günlük hayata bağlar. Peygamber (s.a.v.), insanlara teşekkür etmeyenin Allah’a da şükretmiş olmayacağını söylemiştir. Sana yardım eden kişiye teşekkür etmek de şükrün bir parçasıdır."]},{heading:"Psikoloji araştırmaları ne buldu?",paragraphs:["2023 tarihli bir meta-analiz, 6.745 kişinin katıldığı 25 randomize çalışmayı birleştirdi. Minnettarlığı ifade etmek, nötr etkinliklere göre iyi oluş üzerinde küçük bir olumlu etki gösterdi. Yerleşik terapi yaklaşımlarıyla karşılaştırıldığında ise belirgin bir fark bulunmadı.","Bu çalışmalar çoğunlukla klinik olmayan gruplarda ruh hâlini ve yaşam doyumunu ölçer. Şükre ilişkin dinî öğretiyi doğrulamaz ya da sorgulamaz. Üzüntünü gizleyip minnettar görünmek zorunda olduğun anlamına da gelmez."],visual:{kind:"bars",title:"Minnettarlığı ifade etmek: ortalama etkiler",bars:[{label:"Mutluluk",value:.16,display:"g = 0,16"},{label:"Yaşam doyumu",value:.22,display:"g = 0,22"},{label:"Olumlu duygulanım",value:.21,display:"g = 0,21"}],note:"Kirca, Malouff & Meynadier 2023, nötr etkinliklerle karşılaştırıldığında: çalışmalar arasında değişen küçük etkiler. Psikoloji araştırması; kutsal metinden ayrı gösterilir.",sourceId:"gratitude"}}],example:{title:"Ömer, 58, taksi şoförü",text:"Ömer zor bir ay geçiriyordu. Dizi ağrıyor, müşteri az geliyordu. Derste kendisine yardım eden bir davranışı düşünmesi istendiğinde genç tamirciyi hatırladı. Bir cuma geç saate kadar kalıp arabasını onarmış, böylece hafta sonu çalışabilmesini sağlamıştı. Ömer parasını ödeyip kısaca teşekkür etmişti. O akşam bir karta üç cümle yazdı: Geçen cuma geç saate kadar kaldığın için hafta sonu çalışabildim. Kiramı zamanında ödedim. Bunu unutmadım. Biraz tereddüt etti ama pazartesi kartı tamirhaneye bıraktı. Tamirci gülümsedi ve kartı tezgâhının üstüne astı. Ömer’in dizi hâlâ ağrıyordu ama eve daha hafiflemiş döndü."},sources:["faith-quran-gratitude","faith-hadith-thank-people"]},"faith-4":{deeper:[{heading:"Sabır: çabayı sürdürmek",paragraphs:["Sabır çoğu zaman sessizce beklemek gibi anlaşılır. Ama anlamı daha geniştir. Bakara 2:153, müminleri sabır ve namazla yardım aramaya çağırır. Allah’ın sabredenlerle beraber olduğunu bildirir. Burada sabrı, yardım ararken çabayı ve dayanmayı sürdürmek olarak ele alıyoruz.","Sahîh-i Müslim’deki bir hadis, müminin her hâlinde hayır bulunmasını dikkat çekici olarak anlatır. Hoşuna giden bir şey olduğunda şükreder, sıkıntı geldiğinde sabreder. Şükür ve sabır, aynı hayatın iki yüzü olarak sunulur."],visual:{kind:"compare",title:"Tek bir hayatın iki yüzü (Sahîh-i Müslim 2999)",left:{label:"Hoşuna giden bir şey olduğunda",items:["Fark et","Şükret","İyiliği paylaş"]},right:{label:"Sıkıntı geldiğinde",items:["Zorluğu dürüstçe dile getir","Sabırla dayan","Dua et, insanlardan da yardım iste"]},note:"Hadis sunnah.com’dan özetlenmiştir; maddeler ODA’nın yorumudur, hüküm değildir."}},{heading:"Dinî başa çıkma hakkında araştırma ne diyor?",paragraphs:["Psikolog Kenneth Pargament, dinî başa çıkmanın olumlu ve olumsuz biçimlerini ayırır. Manevi bağ aramak, sorunlarla Allah’a güvenerek birlikte başa çıkmak ve din görevlilerinden destek almak olumlu biçimlere örnektir. Tanrı’dan hoşnutsuz olmak ya da zorluğu ceza olarak görmek ise olumsuz biçimlere örnektir. 49 çalışmayı kapsayan 2005 tarihli bir meta-analizde olumlu dinî başa çıkma, daha iyi sonuçlarla orta düzeyde ilişkiliydi. Olumsuz dinî başa çıkma ise daha fazla sıkıntıyla ilişkiliydi.","Bu çalışmalar ilişkileri gösterir, nedenleri değil. Katılımcıların çoğu Hristiyandı. Kendini cezalandırılmış ya da Allah’tan uzak hissediyorsan bu imanının kusurlu olduğunu göstermez. Ağır bir deneyim olabilir. Bilgili bir imamla ve ruh sağlığı uzmanıyla paylaşabilirsin."],visual:{kind:"bars",title:"Dinî başa çıkma ve uyum: ortalama korelasyonlar",bars:[{label:"Olumlu başa çıkma ↔ olumlu sonuçlar",value:.33,display:"r = 0,33"},{label:"Olumsuz başa çıkma ↔ sıkıntı",value:.22,display:"r = 0,22"}],note:"Ano & Vasconcelles 2005, 49 çalışma, 13.512 kişi. Çalışmalar çoğunlukla tek bir zaman noktasında ölçüm yaptı. Katılımcıların yaklaşık %85’i Hristiyandı. Bulgular ilişki gösterir, nedenini kanıtlamaz. Psikoloji araştırması kutsal metinden ayrı gösterilir.",sourceId:"faith-religious-coping"}}],example:{title:"Leyla, 39, eczane kasiyeri",text:"Babası hastalandığından beri Leyla işten sonra her akşam hastaneye gidiyor, herkese iyi olduğunu söylüyordu. Bir gece aklından şu geçti: İmanım daha güçlü olsa bu kadar yorgun olmazdım. Durup bu düşünceyi fark etti. Bugün neye ihtiyacı olduğunu sordu ve bir cümle yazdı: Bugün uyuyabilmem için babamın yanında oturacak birine ihtiyacım var. Kuzenine mesaj gönderdi. Kuzeni hemen kabul etti. Leyla o gece kendi sözleriyle dua etti, yedi saat uyudu ve sonraki hafta için hastanenin danışmanından randevu aldı. Babasının hastalığı değişmemişti. Ama artık bütün yükü tek başına taşımıyordu."},sources:["faith-quran-patience","faith-hadith-believer","faith-religious-coping"]},"faith-5":{deeper:[{heading:"Küçük ama devamlı işler",paragraphs:["Sahîh-i Buhârî’de Âişe’den rivayet edilen bir hadis, Allah’a en sevimli işin az da olsa en düzenli yapılan olduğunu söyler. İyiliği samimiyetle ve ölçülü yapmayı öğütler. Tirmizî’nin derlemesindeki bir başka hadis, kardeşine gülümsemeyi, yolunu kaybedene yol göstermeyi ve yoldan diken ya da taş kaldırmayı sadaka sayar.","Bu iki hadis, günlük hayata sığan iyilikleri hatırlatır: Küçük, düzenli ve iyi niyetle yapılan işler. Böylece ilk dersteki niyet konusuna da dönmüş olursun."],visual:{kind:"table",title:"Gündelik sadaka, o zaman ve şimdi",columns:["Hadisten (özetlenmiştir)","Çağdaş bir karşılığı"],rows:[["Kardeşine gülümsemek","Bir iş arkadaşını sıcak bir selamla karşılamak"],["Yolunu şaşırana yol göstermek","Birinin doğru formu ya da otobüsü bulmasına yardım etmek"],["Yoldan zararı kaldırmak","Ortak kullanılan merdivenden tehlike yaratan bir şeyi kaldırmak"],["Kovandaki sudan başkasının kovasına dökmek","Elindeki fazlayı paylaşmak"]],note:"Tirmizî 1956 ve Buhârî 6464, sunnah.com’dan özetlenmiştir. Çağdaş karşılıklar ODA’nın örnekleridir."}},{heading:"İyilik üzerine psikoloji araştırmaları",paragraphs:["Psikologlar iyiliğin, onu yapan kişiye etkisini de araştırdı. 2018 tarihli bir meta-analiz, 4.045 kişinin katıldığı 27 çalışmayı birleştirdi. İyilik yapmak, yapan kişinin iyi oluşunda küçük ile orta düzey arasında olumlu etki gösterdi.","Bu bulgu, kısa sürelerde ölçülen ruh hâli ve iyi oluşla ilgilidir. Dinî anlamda ödül hakkında bir şey söylemez. Yalnızca sana iyi hissettirdiği zaman iyilik yapman gerektiği anlamına da gelmez."]}],example:{title:"Nadire, 44, ofis müdürü",text:"Nadire’nin ilk fikri büyüktü: Her hafta sonu gıda bankasında gönüllü olmak. İki çocuğunu, uzun işe gidiş gelişini ve yaşlanan annesini düşününce bunun bir ay bile sürmeyeceğini gördü. Daha küçük bir iş seçti. Her çarşamba annesinin yalnız yaşayan yaşlı komşusunu arayıp nasıl olduğunu soracaktı. Akşam yemeğinden sonra, 18.30’da aramak için takvimine not koydu. İlk görüşme sekiz dakika sürdü; çoğunlukla havadan konuştular. Üçüncü görüşme yirmi dakika sürdü. Komşu, bütün hafta başka kimseyle konuşmadığını söyledi. Nadire teşekkür beklemiyordu. Ama çarşambaları beklemeye başladığını fark etti. Arama takviminde kaldı."},sources:["faith-hadith-consistent","faith-hadith-smile","faith-kindness"]}},la=Object.freeze(Object.defineProperty({__proto__:null,EXTRAS:ra,SOURCES:ta},Symbol.toStringTag,{value:"Module"})),oa=[{id:"manifest-positive-fantasies",title:"Kappes & Oettingen · 2011 · İdealleştirilmiş gelecek hayalleri enerjiyi tüketir",url:"https://www.sciencedirect.com/science/article/abs/pii/S002210311100031X",type:"research",finding:"Dört deneyde katılımcılardan kusursuzlaştırılmış bir gelecek hakkında olumlu hayaller kurmaları istendi. Bu grubun bedensel ve davranışsal göstergelerle ölçülen enerjisi daha düşüktü. Karşılaştırılan gruplar, istenen geleceği sorgulayan, olumsuz ya da nötr hayaller kurmuştu. Hayal daha acil bir ihtiyaçla ilgili olduğunda enerji daha çok düştü. Yazarlar, kendiliğinden kurulan olumlu hayallerin daha az başarıyla ilişkili olmasını kısmen bu enerji düşüşüne bağlar.",limitation:"Küçük katılımcı gruplarıyla yapılmış laboratuvar deneyleridir. Hayal kurmanın her zaman zararlı olduğunu göstermez. Engel ve plan içermeyen kusursuzlaştırılmış bir hayalin, harekete geçme enerjisini azaltabileceğini gösterir. Yalnızca özet okundu."},{id:"manifest-belief-study",title:"Dixon, Hornsey & Hartley · Personality and Social Psychology Bulletin · Manifestasyon inancının psikolojisi (Queensland Üniversitesi özeti, 2023)",url:"https://news.uq.edu.au/2023-09-20-manifesting-your-way-bankruptcy",type:"research",finding:"1.023 katılımcıyla üç çalışma yapıldı. Katılımcıların yaklaşık üçte biri manifestasyon inançlarını benimsiyordu. İnananlar kendilerini daha başarılı görüyor ve daha yüksek hedefler koyuyordu. Ama riskli yatırımlara da daha çok ilgi duyuyorlardı. İflas yaşamış olma ihtimalleri ve hızla zengin olmaya dair gerçekçi olmayan beklentileri daha yüksekti. Araştırmacılar manifestasyonun işe yaradığına dair nesnel kanıt bulamadı.",limitation:"Anket araştırmasıdır; ilişkileri gösterir, nedenleri değil. Makalenin tam metni değil, üniversitenin haber özeti okundu. Bu yüzden ölçümlerin ayrıntıları kontrol edilmedi."},{id:"manifest-murphy",title:"Joseph Murphy · The Power of Your Subconscious Mind (1963; Tarcher baskısı 2008)",url:"https://www.penguinrandomhouse.com/books/296695/the-power-of-your-subconscious-mind-by-joseph-murphy-phd-dd/",type:"technique",finding:"Murphy’ye göre uykuya dalmadan önceki mahmur hâl, telkine en açık zamandır. Dileği kısa bir cümleye indirmeyi ve ninni gibi sakince tekrarlamayı önerir. Ardından sonuç gerçekleşmiş gibi kısa bir sahne hayal edilir. Örneğin bir arkadaşın seni tebrik eder. Sahne bir teşekkür duygusuyla biter. Yayıncı, kitabın temel fikrini çekincesiz inanmak ve içindeki engelleri aşacak biçimde sonucu canlandırmak olarak tanımlar.",limitation:"Yayıncının sayfası okundu. Uykudan önce zihinsel prova yapmak ve net bir niyet belirlemek hazırlanmana yardımcı olabilir. Ancak kitabın, bilinçaltının zenginlik, başarı ya da bedensel iyileşme getirdiği iddiaları araştırmayla desteklenmiyor. Bu iddialar nedeniyle tıbbi tedavini değiştirme."}],sa={"manifest-1":{deeper:[{heading:"Hangi uygulamalar araştırmayla destekleniyor?",paragraphs:["Manifest kitapları ve videoları çoğu zaman iki farklı şeyi birbirine karıştırır. İlki günlük hayatta yararlı olabilecek alışkanlıklardır: Ne istediğini belirlemek, gözünde canlandırmak, aklında tutmak ve harekete geçmek. İkincisi ise dünyanın nasıl işlediğine dair bir iddiadır. Buna çoğunlukla çekim yasası denir. Benzerin benzeri çektiği, düşüncelerinin sinyal yaydığı ve evrenin olayları buna göre düzenlediği söylenir. Bazen kuantum fiziğinin de bunu kanıtladığı iddia edilir.","İlk kısmı kullanıp ikinci kısmı bir kenara bırakabilirsin. Yararlı bir şey kaybetmezsin. Fizikçiler dünyayı böyle açıklamaz. Para, bir partner ya da iş hakkında düşünmenin, bunları kendiliğinden getirdiğini gösteren bir çalışma yok. Alışkanlıklar ise sınanmış yöntemlerle örtüşür: Net hedef koymak, zihinsel prova yapmak, engeller için plan hazırlamak ve ilerlemeyi takip etmek. Kurs bunlara dayanır."],visual:{kind:"compare",title:"Yararlı uygulamalar ve kanıtsız iddialar",left:{label:"Kullan: yararlı uygulamalar",items:["Net ve belirli bir niyet","Adımları zihninde prova etmek","Engeli fark edip ona karşı plan hazırlamak","Harekete geçmek, sonra dürüstçe gözden geçirmek"]},right:{label:"Kenara koy: kanıtı yok",items:["Düşünceleri olayları çeken bir mıknatıs saymak","Evrenin odaklandığın şeyi sana getirmesi","Kuantum fiziğinin senin gerçekliğini yeniden şekillendirmesi","Bir aksiliği olumsuz düşünmenin kanıtı saymak"]},note:"Sağ sütundaki iddiaları bırakırken umudunu koruyabilirsin. Umudunu bir planla destekle."}},{heading:"Manifestasyon inancı üzerine araştırma",paragraphs:["Queensland Üniversitesi’nden araştırmacılar manifestasyona inanan insanları inceledi. 1.023 kişinin katıldığı üç çalışmada, yaklaşık üçte biri bu inançları benimsiyordu. İnananlar kendilerini daha başarılı görüyor ve daha yüksek hedefler koyuyordu. Ancak riskli yatırımlara daha çok ilgi duyuyorlardı. İflas yaşamış olma ve hızla zengin olmayı bekleme ihtimalleri de daha yüksekti. Araştırmacılar manifestasyonun işe yaradığına dair nesnel kanıt bulamadı.","Bunlar anketlerdi. Bir ilişki gösterirler ama nedenini açıklamazlar. Yine de bulgular bu kursun yaklaşımıyla uyumlu. Bir şeyi istemekte sorun yok. Risk, kesinlik duygusu gerçekleri kontrol etmenin, tavsiye almanın ve küçük, sınanabilir adımlar atmanın yerini aldığında başlar. Yapacağın davranışı belirlemek, planını gerçekle karşılaştırmanı sağlar."]}],example:{title:"Daniel, 31, depo vardiya amiri",text:"Daniel, lojistik planlama işine geçmek istiyordu. Aylardır telefonunun duvar kâğıdında bir ofis masası vardı. Doğru işin kendisini bulacağını söylüyordu. Pazar günü alıştırmayı denedi. Dileği bir planlama işiydi. Yapacağı davranışı şöyle belirledi: Perşembeye kadar özgeçmişimin ilk üç satırını, hazırladığım vardiya çizelgelerinden söz edecek şekilde yeniden yazacağım. Çarşamba akşamı yemekten sonra bunu yaklaşık yirmi dakikada yaptı. Bir satır hâlâ tuhaf görünüyordu, o hafta kimse aramadı. Ama artık gönderebileceği bir sayfası vardı. Sonraki adım da açıktı: Karşılaştırmak için iki iş ilanı bulmak. Duvar kâğıdını değiştirmedi. Ama artık hayaline bağlı bir işi vardı."},sources:["manifest-belief-study"]},"manifest-2":{deeper:[{heading:"Zihinsel prova hakkında araştırmalar",paragraphs:["2021 tarihli bir meta-analiz, zihinsel canlandırmaya ilişkin 94 randomize çalışmayı birleştirdi. Bu, gelecekteki bir davranışı ya da olayı bilerek hayal etmektir. Sonraki davranış üzerinde genel olarak orta düzeyde etki görüldü. Canlandırmanın türü önemliydi. Kendini işi yaparken, özellikle iyi yaparken görmek en güçlü etkiyi gösterdi. Yalnızca istenen sonucu hayal etmenin etkisi küçüktü. Yalnızca süreç adımlarını hayal etmenin etkisi güvenilir değildi. Ancak bu tahmin sadece beş etkiye dayanıyordu. Sonuç ile süreci birleştiren sekiz çalışmada daha büyük etki bulundu.","Beceri ve spor alanındaki zihinsel provayı inceleyen ayrı bir derleme, küçük ama gerçek bir fayda buldu. Fiziksel uygulama ise yalnızca zihinsel provadan daha etkiliydi. Kendini işi yaparken görmek küçük ile orta düzey arasında yardımcı olabilir. İşi gerçekten yapmak daha fazla yardımcı olur."],visual:{kind:"bars",title:"Zihinsel canlandırma ve sonraki davranış (ortalama etki, Hedges g)",bars:[{label:"Kendini işi iyi yaparken canlandırmak",value:.67,display:"g = 0,67"},{label:"Standart performans provası",value:.48,display:"g = 0,48"},{label:"İstenen sonucu canlandırmak",value:.23,display:"g = 0,23"},{label:"Yalnızca süreç adımlarını canlandırmak (5 etki)",value:.17,display:"g = 0,17"}],note:"Cole ve ark. (2021), 94 randomize çalışma. Yaklaşık 0,2 küçük, 0,5 orta etki sayılır. Katılımcıların çoğu öğrenciydi. Bazı canlandırma türleri az sayıda çalışmaya dayanıyor. Yalnızca süreç adımlarına ait tahmin istatistiksel olarak güvenilir değildi.",sourceId:"identity-cole"}},{heading:"Joseph Murphy ve Dr. Joe Dispenza’nın yöntemleri",paragraphs:["İki tanınmış öğretmen, yöntemlerinde zihinsel provaya yer verir. Joseph Murphy, The Power of Your Subconscious Mind kitabında uykuya dalmadan önceki mahmur dakikaları önerir. Dileğini kısa bir cümleye indirir, sakince tekrarlarsın. Sonuç gerçekleşmiş gibi kısa bir sahne hayal eder, teşekkür duygusuyla bitirirsin. Dr. Joe Dispenza ise Breaking the Habit of Being Yourself kitabında sabah meditasyonu önerir. Bu çalışmada, olmak istediğin kişinin nasıl düşündüğünü, davrandığını ve hissettiğini ayrıntılı biçimde prova edersin.","İki yöntemde de yararlı olabilecek uygulamalar var. Ama ikisi de araştırmaların desteklediğinden çok fazlasını iddia eder. Murphy, bilinçaltının zenginlik ve iyileşme getirebileceğini yazar. Dispenza, uygulamasını kuantum alanıyla ve genlerini değiştirmekle ilişkilendirir. Zihinsel provayı kullanıp diğer iddiaları bir kenara bırakabilirsin."],visual:{kind:"table",title:"İki yöntemde ne var, ne desteklenmiyor?",columns:["Öğretmen","Ne yapıyorsun","Tut","Kenara koy"],rows:[["Joseph Murphy","Uykudan önce kısa bir cümle ve sonuç gerçekleşmiş gibi bir sahne","Sakin, net bir niyet; bir sahneyi prova etmek","Bilinçaltının para ya da iyileşme getirmesi"],["Dr. Joe Dispenza","Olmak istediğin kişiyi prova ettiğin sabah meditasyonu","Nasıl davranıp yanıt vereceğini prova etmek","Kuantum alanı ve gen değiştirme iddiaları"],["Bu kurs","Önce sonuç, sonra ilk somut hareket","Adımı yaparken kendini görmek","Hayali, eylemin yerine koymak"]],note:"Yöntemlerin tamamını değil, ana noktalarını özetledik. İkisi de bütün hâliyle kontrollü araştırmalarda sınanmadı."}}],example:{title:"Priya, 27, çocuk hemşiresi",text:"Priya bir uzmanlık eğitimine başvurmak istiyordu. Yeni rozetini takacağı günü sık sık hayal ediyordu. Bu ona iyi geliyordu ama hiçbir şeyi değiştirmiyordu. Bir gece yatakta başka bir sahne düşündü. Rozetin ardından ertesi sabahı canlandırdı: Kahvaltıdan sonra mutfak masasında, bilgisayarı açık. Ekranda başvuru sitesi ve kendisini anlatması gereken metin alanı var. Giriş bilgilerini bilmediğini, metne de ilk cümleyle başlaması gerektiğini fark etti. Sabah şifresini yeniledi. Çocuk hemşireliğini neden seçtiğini anlatan ilk cümleyi yazdı. On dakika sonra bilgisayarı kapattı. Rozeti almasına hâlâ aylar vardı. Ama başvuru sonunda başlamıştı."},sources:["manifest-murphy","identity-cole","identity-toth","identity-dispenza-habit"]},"manifest-3":{deeper:[{heading:"Hoş bir hayal neden enerjini azaltabilir?",paragraphs:["Oettingen’in ekibinin önceki araştırmasında, gelecek hakkında kendiliğinden pembe hayaller kuran kişiler daha az başarı gösterme eğilimindeydi. Nedenini araştırmak için Heather Barry Kappes ve Gabriele Oettingen dört deney yaptı. Katılımcılardan kusursuzlaştırılmış bir geleceği hayal etmelerini istediler. Bu grubun hem bedensel hem davranışsal göstergelerle ölçülen enerjisi daha düşük çıktı. Karşılaştırma grupları geleceği sorgulayan, olumsuz ya da nötr hayaller kurmuştu. İhtiyaç daha acil hissedildiğinde enerji daha çok düştü.","Bunu şöyle düşünebilirsin: Kusursuz bir hayal, çabalamadan sonuca ulaşmanın tadını verir. Beden, iş bitmiş gibi gevşeyebilir. Bu, hayal kurmanın kötü olduğu anlamına gelmez. Hayali, son durak yerine başlangıç olarak kullanmak daha yararlı olabilir."],visual:{kind:"cycle",title:"Hayal döngüsü",center:"Yalnızca hayal",nodes:[{label:"Kusursuz hayal",text:"Sonuca ulaşmışsın gibi hayal edersin. Hiç engel yoktur."},{label:"Varmış gibi hissettirir",text:"Zihnin, sanki gerçekleşmiş gibi bu sonucu yaşar."},{label:"Enerji düşer",text:"Harekete geçmek daha az acil gelir. Beden gevşer."},{label:"Az adım",text:"Gün somut bir adım atılmadan geçer."},{label:"Dilek hâlâ uzakta",text:"Gerçekle hayal arasındaki fark canını yakar. Yeniden hayale dönersin."}],note:"Kappes & Oettingen (2011) çalışmasına dayanan basitleştirilmiş bir anlatım. Döngüden çıkmak için hayali, gerçek bir engel ve planla birleştir."}},{heading:"WOOP: hayali gerçekle karşılaştırmak",paragraphs:["Oettingen, zihinsel karşılaştırmayı WOOP adlı dört adımlı bir yönteme dönüştürdü: Wish (Dilek), Outcome (Sonuç), Obstacle (Engel), Plan. Önce hoş kısma bakarsın. Dileğini belirler, en iyi sonucu hayal edersin. Sonra içindeki asıl engeli ele alırsın. Bu bir alışkanlık, duygu ya da inanç olabilir. Son adım olan planı bir sonraki derste işleyeceğiz.","15.907 kişinin katıldığı 21 çalışmayı birleştiren 2021 tarihli meta-analizde, zihinsel karşılaştırma ve eğer-öyleyse planları hedeflere ulaşmada küçük ile orta düzey arasında ortalama etki gösterdi. Bu gerçek bir etkiydi ama garanti değildi. WOOP, dileğin sana uymadığında da bilgi verir. Engele dürüstçe bakınca dilek gerçekçi gelmiyorsa, onu yeniden şekillendirebilirsin. Bu bir başarısızlık değildir."]}],example:{title:"Lena, 38, ortaokul öğretmeni",text:"Lena, veri becerileriyle ilgili çevrim içi kursunu bitirmek istiyordu. Genellikle sertifikasını ve ilçe müdürlüğünde yeni bir görevi hayal ediyordu. Bu kez WOOP kullandı. Dilek: Bu ay üçüncü modülü bitirmek. Sonuç: İşte elektronik tabloları rahatça kullanabilmek. Sonra engele baktı. Asıl sorun tembellik değildi. Sınav kâğıtlarını okuyup iki çocuğunu yatırınca saat 21.30 oluyordu. Bitkin düşüyor, telefonuna uzanıyordu. Bunun bir kısmı değiştiremediği dış koşullardı. Bu yüzden planı değiştirdi. Eşi çocukları parka götürürken cumartesi sabahı kırk beş dakika çalışacaktı. İlk cumartesi bir ders bitirdi. Umduğundan azdı ama önceki üç haftada yaptığından fazlaydı."},sources:["oettingen-woop-method","manifest-positive-fantasies"]},"manifest-4":{deeper:[{heading:"Eğer-öyleyse planları neden işe yarar?",paragraphs:["Psikologlar bunlara uygulama niyetleri der. Peter Gollwitzer ve Paschal Sheeran 94 bağımsız testi birleştirdi. Ne zaman, nerede ve nasıl davranacağını önceden belirleyen planların hedefe ulaşmada orta ile büyük düzey arasında ortalama etkisi vardı. Yayın yanlılığını hesaba katan daha yeni analizlerde gerçek etki daha düşük çıkabilir. Ama genel yön aynı kalır.","Muhtemel neden basittir. Bir durumu önceden bir davranışa bağladığında, durumun kendisi hatırlatıcı olur. Yorgun ya da huzursuz olduğun anda yeniden karar vermen gerekmez. Telefonda gezinmek kolay gelse de, ne yapacağını önceden belirlemişsindir."],visual:{kind:"compare",title:"Belirsiz niyetler ve kullanılabilir planlar",left:{label:"Belirsiz",items:["Bu hafta üzerinde çalışırım.","Daha disiplinli olmaya çalışırım.","Ne olursa olsun pozitif kalırım."]},right:{label:"Eğer-öyleyse",items:["Salı akşamı saat 8 olduğunda mutfak masasında dosyayı açacağım.","Telefonuma uzanırsam onu 15 dakikalığına diğer odaya bırakacağım.","Cesaretim kırılırsa işe yarayan bir şeyi yazacağım."]},note:"Eğer kısmı kolayca fark edeceğin bir durumu anlatır. Öyleyse kısmı, kötü bir günde bile yapabileceğin kadar küçük bir davranıştır."}},{heading:"Sık yapılan hatalar",paragraphs:["En yaygın hata, zamanı belirsiz bırakmaktır. Vaktim olursa çoğu zaman işe yaramaz. Planı bir saate, yere ya da öğle yemeğinin bitmesi gibi tanıdık bir ana bağla. İkinci hata, çok büyük bir iş seçmektir. Bütün bölümü yazacağım demek, yine başlamaktan kaçınmana yol açabilir. Üçüncü hata, aynı anda çok fazla plan yapmaktır. Gerçekten kullandığın bir ya da iki plan, bir sayfa kuraldan daha yararlıdır.","Planı uygulayamadığında bunu kendin hakkında bir yargı değil, bilgi olarak gör. Belki işareti fark etmedin ya da seçtiğin davranış hâlâ çok büyüktü. Bir parçayı değiştirip yeniden dene."]}],example:{title:"Tomás, 35, serbest grafik tasarımcı",text:"Tomás bir yıldır portfolyo sitesini manifest etmeye çalışıyordu. Siteyi açıkça hayal edebiliyordu. Ama site oluşturma aracını her açtığında boş sayfayı görüyor, e-postalarına geçiyordu. Ekranının yanındaki bir nota iki plan yazdı. Aracı açıp tıkanırsam yalnızca sayfa başlığını ve iki projenin adını yazacağım. Salı sabahı saat 9’da başlamamışsam on dakikalık bir zamanlayıcı kuracağım. Salı günü ikinci planı 9.05’te uyguladı. Başlığı ve üç projenin adını yazdı, on iki dakika sonra durdu. Henüz bir sitesi yoktu. Ama ilk kez zihnindeki resimden daha fazlası vardı."},sources:["if-then-plans"]},"manifest-5":{deeper:[{heading:"Neyi takip etmeli, neden yazmalı?",paragraphs:["Yaklaşık 20.000 kişiyle yapılan 138 deneyin meta-analizinde, ilerlemeyi takip etmeyi artıran uygulamalar hedefe ulaşmaya yardımcı oldu. Ortalama etki küçük ile orta düzey arasındaydı. İlerleme kâğıda ya da uygulamaya kaydedildiğinde ve bir başkasına bildirildiğinde fayda daha büyüktü. Notlarını paylaşmak zorunda değilsin. Ama kısa bir satır yazmak, işlerin nasıl gittiğini belirsizce hatırlamaktan daha yararlı görünüyor.","Daha çok elinde olanı takip et: Adımı attın mı? Ne zaman? Hangi koşullarda? Sonuç da önemlidir ama çoğu zaman çabadan daha geç görünür. Başkalarına da bağlıdır. Yalnızca sonucu takip edersen, düzenli çalıştığın hâlde yavaş geçen bir ayı başarısızlık sanabilirsin."],visual:{kind:"cycle",title:"Gözden geçirme döngüsü",center:"Gözden geçirme günü",nodes:[{label:"Dene",text:"Planladığın küçük adımı at."},{label:"Kaydet",text:"Bir satır yaz: ne yaptın, ne zaman, hangi koşullarda."},{label:"Bak",text:"Gözden geçirme gününde notları birlikte oku."},{label:"Öğren",text:"Ne yardımcı oldu? Ne engel oldu?"},{label:"Yeniden seç",text:"Sürdür, küçült, destek al ya da hedefi değiştir."}],note:"Bu döngü, işe yaramayanlar dahil her denemeden sonraki deneme için bilgi çıkarmanı sağlar."}},{heading:"Sonuç gelmediğinde",paragraphs:["Popüler manifest anlayışı burada bir yük getirebilir. Düşüncelerin gerçekliği yarattığını kabul edersen, sonuç gelmediğinde düşüncelerinin yanlış olduğuna inanabilirsin. Tek çözümün daha çok inanmak olduğunu sanabilirsin. Bu, aynı yerde kalmana ya da riskli adımlar atmana yol açabilir. Manifestasyona güçlü biçimde inananları inceleyen anket araştırmasında da riskli yatırımlar ve iflasla ilişki bulundu. Ancak bu araştırma nedenini gösteremez.","Kendine daha nazik ve yararlı bir soru sorabilirsin: Denemelerim bana ne söylüyor? Bazen sürdürmek gerekir; çaba ile sonuç henüz aynı hızda ilerlemiyordur. Bazen planı değiştirmek, yardım istemek ya da hedefi bırakmak gerekir. Bunların her biri geçerli bir seçimdir."],visual:{kind:"table",title:"Notlarından sonraki adımı seçmek",columns:["Ne görüyorsun?","Makul bir sonraki seçim"],rows:[["Adımları attın; sonuç yavaş","Sürdür ve bir sonraki değerlendirme tarihini belirle"],["Adımı nadiren attın","Adımı küçült ya da eğer kısmındaki işareti değiştir"],["Bir dış koşul seni sürekli engelledi","Zamanlamayı değiştir ya da destek iste"],["Hedef artık senin için önemli değil","Bırak ya da yeni bir dilek seç"]],note:"Bu seçimlerin hiçbiri başarısızlık değildir. Her biri yaşananlara bakarak verilmiş bir karardır."}}],example:{title:"Aisha, 45, küçük bir ev pastanesi işletiyor",text:"Aisha, çeyrek sonuna kadar haftada on düzenli sipariş almak istiyordu. Altı hafta boyunca her pazartesi fotoğraf paylaştı ve iki yerel kafede numune dağıttı. Her denemeden sonra defterine bir satır yazdı. Değerlendirme günü notlarına baktı. Dokuz paylaşım, altı numune günü ve on yerine dört düzenli sipariş vardı. Yeterince inanmadığını düşünmek yerine olanları inceledi. Dört düzenli müşterinin üçü aynı kafeden gelmişti. Orada müşterilerle yüz yüze konuşmuştu. Ayda iki paylaşımı bırakıp o zamanı ikinci bir kafeye ayırmayı seçti. Hedef tarihini bir ay erteledi. Bu ona yenilgi değil, verilmiş bir karar gibi geldi."},sources:["manifest-belief-study"]}},da=Object.freeze(Object.defineProperty({__proto__:null,EXTRAS:sa,SOURCES:oa},Symbol.toStringTag,{value:"Module"})),ua=[{id:"focus-attention-residue",title:"Leroy · 2009 · İşler arasında geçişte dikkat kalıntısı",url:"https://www.sciencedirect.com/science/article/abs/pii/S0749597809000399",type:"research",finding:"Sophie Leroy iki deneyde, insanların ikinci bir işe geçtikten sonra ilk işi düşünmeye devam ettiklerini buldu. “Dikkat kalıntısı” denen bu durum ikinci işteki performansı düşürüyordu. İlk işi yarım bırakmak bu etkiyi artırdı. İşi bitirmek de her zaman zihnen bırakmaya yetmedi. İlk işi bir miktar zaman baskısı altında bitirmek ise insanların o işten kopmasına yardımcı oldu.",limitation:"Yalnızca özet okundu; örneklem ve etki büyüklükleri kontrol edilmedi. Deneylerde laboratuvar görevleri kullanıldı. Zaman baskısı ilk işi zihnen kapatmaya yardımcı oldu; bu bulgu genel olarak baskı altında çalışmayı desteklemez."},{id:"focus-ready-to-resume",title:"Leroy & Glomb · 2018 · “İşe dönüş planı” (Washington Üniversitesi haber bülteni)",url:"https://www.washington.edu/news/2018/01/16/task-interrupted-a-plan-for-returning-helps-you-move-on/",type:"technique",finding:"Üniversitenin Organization Science’ta yayımlanan makale özetine göre, dört deneyde “işe dönüş planı” sınandı. Bunlardan biri çalışan 202 kişiyle, diğerleri laboratuvarda öğrencilerle yapıldı. İşleri bölündüğünde katılımcılar yaklaşık bir dakika ayırıp nerede kaldıklarını, hangi konuların açık kaldığını ve sonra ne yapacaklarını yazdı. Plan dikkat kalıntısını azalttı. Ara verdikleri sırada üstlendikleri yeni işte daha iyi kararlar vermelerine ve bilgileri daha iyi hatırlamalarına yardımcı oldu.",limitation:"Makalenin kendisi değil, bir üniversite haber bülteni; etki büyüklükleri verilmedi. Planın, bölünen asıl işteki sonraki performansı iyileştirip iyileştirmediği sınanmadı."},{id:"focus-newport-time-blocking",title:"Cal Newport · 2013 · “Deep Habits: The Importance of Planning Every Minute of Your Work Day” (calnewport.com)",url:"https://calnewport.com/deep-habits-the-importance-of-planning-every-minute-of-your-work-day/",type:"technique",finding:"Yazar ve bilgisayar bilimcisi Cal Newport, zaman bloklama yöntemini anlatıyor. Her akşam 10–20 dakika görev listelerini ve takvimini gözden geçiriyor. Ertesi iş gününü kâğıt üzerinde zaman dilimlerine ayırıp her birine yapacağı işi yazıyor. Beklenmedik bir şey olduğunda planı değiştirebilmek için yanlarında boşluk bırakıyor. Gelen taleplerle ilgilenmek için de ayrı zaman ayırıyor. Yöntemin stresini azalttığını ve verimini çok artırdığını söylüyor.",limitation:"Kişisel bir blog yazısı (ilk yayım 2013, güncelleme 2023); ne kadar daha verimli olduğuna dair tahmini kişisel bir izlenim, bir çalışma değil. Zaman bloklamaya ilişkin kontrollü bir deneme bulunamadı."}],ha={"focus-1":{deeper:[{heading:"Dikkat kalıntısı: aklın önceki işte kalır",paragraphs:["Yönetim araştırmacısı Sophie Leroy, tanıdık bir duruma ad verdi. İki deneyde, insanlar yeni bir işe geçince dikkatlerinin bir kısmının önceki işte kaldığını buldu. Buna dikkat kalıntısı dedi. Aklın bıraktığın işe takılır; yeni işe sandığın kadar dikkat veremezsin. Bu da o işteki performansını düşürür.","Çalışmanın iki ayrıntısı önemli. İlk iş yarım kaldığında dikkat kalıntısı daha fazlaydı. İşi bitirmek de her zaman zihnen bırakmaya yetmiyordu. İnsanlar ilk işi biraz zaman baskısı altında tamamladığında o işten daha kolay kopuyordu. Yalnızca araştırmanın özeti okundu. Bu nedenle burada bütün ayrıntılar yerine ana bulgular yer alıyor."],visual:{kind:"cycle",title:"Geçiş döngüsü",center:"Yarım kalan iş aklında kalır",nodes:[{label:"Geçiş",text:"Son işi kapatmadan yeni bir şeye geçersin."},{label:"Dikkat kalıntısı",text:"Zihnin bir kısmı eski iş üzerinde çalışmayı sürdürür."},{label:"Yavaş başlangıç",text:"Yeni işe odaklanman daha uzun sürer ve hata yapabilirsin."},{label:"Eski işe dönüş",text:"Eski işe “bir dakikalığına” bakarsın ve yine geçersin."}],note:"Monsell’in işler arasında geçişin etkilerine ve Leroy’un dikkat kalıntısına ilişkin araştırmalarından yararlanılarak hazırlandı. Ölçülmüş bir model değildir."}},{heading:"İş değiştirmeden önce bir dakikalık not",paragraphs:["Leroy, daha sonra Theresa Glomb’la yaptığı çalışmada basit bir yöntemi sınadı. İşleri bölündüğünde katılımcılar yaklaşık bir dakika ayırıp nerede kaldıklarını, hangi konuların açık kaldığını ve döndüklerinde ilk ne yapacaklarını yazdı. Üniversitenin özetine göre bu “işe dönüş planı” dikkat kalıntısını azalttı. Ara verdikleri sırada üstlendikleri yeni işte daha iyi kararlar vermelerini sağladı. Çalışan kişilerle yapılan deney de benzer sonuç verdi.","Planın sonrasında asıl işe dönünce de yardımcı olup olmadığı sınanmadı. Üstelik bilgimiz makalenin tamamından değil, üniversitenin özetinden geliyor. Yine de bu not yaklaşık bir dakika sürüyor. Bugünkü alıştırmada kullandığın hazırlık cümlesini biraz genişletiyor: yeni işe geçmeden önce önceki işi kısa bir notla zihnen kapatıyorsun."]}],example:{title:"Leila, 34, proje yöneticisi",text:"Leila salı sabahı bir saat boyunca klavyesinin yanında yapışkan bir not tuttu. Başka bir işe geçtiği her sefer bir çizgi çekti. Saat onda on dokuz çizgi vardı. Bunları ayırınca on ikisinin sohbet bildirimleri ve yanına gelen iş arkadaşları yüzünden olduğunu gördü. Yalnızca yedisinde kendisi iş değiştirmeyi seçmişti. O gün başka bir değişiklik yapmadı. Kendi seçtiği geçişlerden önce sessizce “Şimdi bütçe tablosuna geçiyorum” demeyi denedi. Bir iş arkadaşı iki kez işini böldüğünde de önce tek satır yazdı: “40. satırda kaldım, sırada seyahat masrafları var.” Geri dönmek belirgin biçimde kolaylaştı. Gün bütünüyle değişmedi, ama işten her zamankinden biraz daha az dağınık çıktı."},sources:["focus-attention-residue","focus-ready-to-resume"]},"focus-2":{deeper:[{heading:"Küçük bir etkiyi nasıl okumalı?",paragraphs:["Bu çalışmadaki d = 0,44, standartlaştırılmış bir etki büyüklüğüdür. İki hafta arasındaki farkı, katılımcıların puanlarının ne kadar değişken olduğuyla karşılaştırır. Anket puanlarındaki fark ise yalnızca yaklaşık 0,1’di. Yani fark hem ölçülebiliyordu hem de günlük hayattaki karşılığı küçüktü. Katılımcılar hangi haftada olduklarını biliyordu. Beklentileri de sonuçta rol oynamış olabilir.","Bu yüzden bildirimleri susturmayı küçük bir deneme olarak düşünebilirsin. Birkaç ayarı değiştirmek huzursuzluğunu biraz azaltıyorsa buna değebilir. Hiç fark görmezsen de yalnızca birkaç ayar değiştirerek kendin hakkında bir şey öğrenmiş olursun. Bu uygulama bir tedavi değildir."]},{heading:"Önemli bildirimleri kaçırmadan",paragraphs:["Telefonunu sustururken en çok önemli bir şeyi kaçırmaktan endişe edebilirsin. Çoğu telefonda “Rahatsız Etme” modunda sana kimlerin ulaşabileceğini seçebilirsin. Önce bu kişileri belirleyip sonra diğer bildirimleri sustur. Bildirimleri aşağıdaki gibi birkaç gruba ayırmak da yardımcı olabilir. Böylece her yeni uygulamada aynı kararı yeniden vermen gerekmez."],visual:{kind:"table",title:"Odaklı çalışırken hangi bildirimler açık kalmalı?",columns:["Bildirim türü","Örnek","Odak bloğu sırasında"],rows:[["Sana acil ihtiyacı olabilecek kişiler","Aile, bakımından sorumlu olduğun kişiler, nöbet işi","Açık bırakılır"],["Zamana bağlı iş araçları","Son teslim gününde ekip sohbeti","Belirli saatlerde bakılır"],["Geri kalan her şey","Sosyal medya, alışveriş, haberler","Susturulur"]],note:"Sınanmış bir kural değil, bir öneri. İşine ve sorumluluklarına göre ayarla; acil durum ya da bakım için gereken aramaları asla susturma."}}],example:{title:"Daniel, 27, yüksek lisans öğrencisi",text:"Daniel bildirim geçmişine bakınca şaşırdı. Bir saat içinde bir alışveriş uygulaması, iki haber uygulaması ve bir oyun telefonu titretmişti. Dördünün bildirimlerini de kapattı. Saat dokuzda tezinin bir bölümünü yazmaya oturmadan önce iki saatliğine Rahatsız Etme modunu açtı. İki kişiyi istisna olarak ekledi: bebek bekleyen ablası ve danışmanı. İlk yirmi dakikada alışkanlıkla üç kez telefona uzandı; ekranda hiçbir şey yoktu. Saat on birde mesajlarına baktı. Dikkatini gerektiren bir şey gelmemişti. Her zamankinden fazla yazıp yazmadığından emin değildi. Ama daha az paragrafı yeniden okuduğunu fark etti. Ertesi gün aynı ayarlarla çalışmaya karar verdi."}},"focus-3":{deeper:[{heading:"Yaygın bir bulgu yeniden sınanınca",paragraphs:["İlk deneyler özenle yapılmıştı ve bulunan etki küçüktü. Fikir çarpıcıydı, gözünde canlandırmak da kolaydı. Bu yüzden hızla yayıldı. Başka bir ekip ikinci deneyi 380’den fazla öğrenciyle tekrarladı. Planlarını önceden kaydetmişlerdi. Bu kez telefonun nerede durduğu çalışma belleğinde fark yaratmadı.","Meta-analiz daha geniş bir tablo sundu. 33 çalışma birlikte değerlendirildiğinde genel bir etki yoktu. Çalışma belleğindeki küçük etki de yayın yanlılığı düzeltildikten sonra kayboldu. Yayın yanlılığı, olumlu sonuç veren çalışmaların daha sık yayımlanmasıdır. Burada bilim kendi bulgusunu yeniden sınayıp düzeltiyor. Bu da tek bir çarpıcı sonucu hemen kesin kabul etmemek için iyi bir neden."],visual:{kind:"steps",title:"Bir iddia zaman içinde nasıl sınandı?",steps:[{label:"İlk çalışma",text:"İki deney, masadaki telefonun küçük bir etkisini buluyor."},{label:"Geniş ilgi",text:"Fikir, gözünde canlandırması kolay olduğu için hızla yayılıyor."},{label:"Tekrarlama",text:"Deneyin önceden kaydedilmiş bir tekrarı etki bulamıyor."},{label:"Meta-analiz",text:"33 çalışma birlikte genel bir etki göstermiyor."}],note:"Bu dersin kaynaklarındaki üç çalışmanın özeti."}},{heading:"Telefonun yakında durması ve eline alman",paragraphs:["Burada iki ayrı soru var. Sessiz bir telefonun yakında durması zihinsel performansını değiştiriyor mu? Bugünkü kanıtlar genel olarak hayır diyor. Peki bildirimler seni böldüğünde ya da telefonu sürekli eline aldığında ne oluyor? Önceki dersteki bildirim deneyi bu ikinci soruyu ele alıyor. Orada küçük de olsa bir etki bulundu.","Telefonun başka odadayken daha iyi çalışıyorsan böyle devam edebilirsin. Fayda büyük olasılıkla telefonun yakınında durmasından çok, onu kolayca eline alabilmenle ilgili. İki günlük kendi karşılaştırman, herhangi bir haber başlığından daha çok işine yarayabilir."],visual:{kind:"compare",title:"İki farklı soru",left:{label:"Telefon yalnızca yakında",items:["Birçok laboratuvar çalışmasında sınandı","Performansa genel bir etkisi yok","Çalışma belleği üzerindeki küçük bir etki yanlılık düzeltmesinden sonra kayboldu"]},right:{label:"Telefon kullanımda ya da uyarılar açık",items:["Ayrı bir soru","Bildirimler açık, telefon görünür: katılımcılar biraz daha fazla dikkatsizlik bildiriyor","Telefonu ne sıklıkla eline aldığın daha önemli olabilir"]},note:"Sağ taraf 2. dersteki bildirim çalışmasına dayanıyor. Telefonu eline almanın etkisine dair açıklama bizim çıkarımımız."}}],example:{title:"Marcus, 41, muhasebeci",text:"Marcus, masadaki telefonun “beynini tükettiğini” okumuştu. Telefonunu her gördüğünde suçluluk duyuyordu. Bu iddiayı denemeye karar verdi. Pazartesi iki saat çalışırken telefonu koridordaki paltosunda bıraktı. Almak istediği her sefer bir deftere çizgi çekti. Çoğu ilk yarım saatte olmak üzere altı çizgi vardı. Çarşamba telefonu masada, ekranı aşağı dönük ve sessizde tuttu. Dokuz kez eline aldı. İki seferinde ancak ekranda gezinmeye başladıktan sonra farkına vardı. Vardığı sonuç basitti: sorun telefonun orada durmasından çok, kolayca eline alabilmesiydi. Şimdi yoğun günlerde telefonu koridorda tutuyor. Daha hafif günlerde masada durduğu için suçluluk duymuyor."}},"focus-4":{deeper:[{heading:"Sabit molalar mı, canın istediğinde mola mı?",paragraphs:["Hollanda’da yapılan küçük bir çalışma, ders çalışırken mola vermenin üç yolunu karşılaştırdı. Mola zamanını kendileri seçen öğrenciler daha uzun süre çalışıp daha uzun dinlendi. Ama sabit bir programa uyan öğrencilere göre daha fazla yorgunluk ve dikkat dağınıklığı bildirdiler. Odakları ve motivasyonları da daha düşüktü. Yaptıkları iş miktarında anlamlı bir fark yoktu.","Bu sonuç, yukarıdaki meta-analizle uyumlu. Molalar, yaptığın işin miktarından çok nasıl hissettiğini etkiliyor gibi görünüyor. Molaya ihtiyaç duyduğunu fark edene kadar beklersen ara vermek için sana iyi gelecek zamanı kaçırabilirsin. Bu yüzden önceden planladığın kısa bir molayı denemeye değer."],visual:{kind:"table",title:"Bir çalışmadaki üç mola programı",columns:["Program","Nasıl işledi","Öğrencilerin bildirdiği"],rows:[["Kendi seçtikleri","İstedikleri zaman mola","Daha fazla yorgunluk ve dikkat dağınıklığı, daha az odak ve motivasyon"],["Sabit, Pomodoro tarzı","Her 24 dakikada 6 dakikalık mola","Daha iyi ruh hâli; benzer miktarda iş"],["Sabit, daha kısa","Her 12 dakikada 3 dakikalık mola","Daha iyi ruh hâli; benzer miktarda iş"]],note:"Biwer ve ark. 2023: tek bir seansta 87 üniversite öğrencisi. Yalnızca özet okundu. Bulgular belli bir dakika sayısını değil, bir mola programı denemeyi destekliyor."}},{heading:"Molayı nasıl hissettiğine göre değerlendir",paragraphs:["Molaların performansa etkisi için kanıtlar zayıf. Bu yüzden bugünkü alıştırmada nasıl hissettiğine bakıyoruz. Moladan önce ve sonra yorgunluğunu puanla. Puanın 4’ten 2’ye düşüyorsa yapılacaklar listen aynı kalsa bile mola sana yardımcı olmuş demektir.","Yazı yazmak, kod yazmak ya da zor bir konuyu çalışmak zihnini çok yorabilir. Birkaç dakika toparlanmana yetmeyebilir. Daha uzun bir ara ya da başka bir işe geçmek daha iyi gelebilir. Bir hafta boyunca farklı süreleri dene ve sana iyi gelenlerle devam et."]}],example:{title:"Grace, 45, müşteri destek ekibi yöneticisi",text:"Grace genellikle öğleden sonra hiç ara vermeden çalışır, saat dörtte bitkin düşerdi. Perşembe günü saat 14.00’te başladığı çalışmanın sonunda yedi dakika mola vermek için sayaç kurdu. Öncesinde yorgunluğuna 5 üzerinden 4 puan verdi. Kulaklığını masada bıraktı, koridorun sonuna yürüyüp döndü ve su şişesini doldurdu. Sonra yorgunluğuna 2 puan verdi. Talepleri daha hızlı yanıtlayıp yanıtlamadığından emin değildi. Ama günün son saati artık ona daha az yorucu geliyordu. Öğleden sonraki yürüyüşünü sürdürüyor. Şimdi saat on birde de bir mola deniyor."},sources:["procrastination-pomodoro-breaks"]},"focus-5":{deeper:[{heading:"Cal Newport gününü nasıl planlıyor?",paragraphs:["Bilgisayar bilimcisi ve yazar Cal Newport, dikkatini bölmeden çalışmak üzerine yazıyor. Blogunda zaman bloklama yöntemini de anlatıyor. Her akşam on ile yirmi dakika görevlerine ve takvimine bakıyor. Sonra ertesi günün çalışma saatlerini kâğıt üzerinde zaman dilimlerine ayırıyor. Her birine yapacağı işi yazıyor.","İki ayrıntı yöntemi esnek kılıyor. Beklenmedik bir şey olduğunda günün kalanını yeniden planlayabilmek için zaman dilimlerinin yanında boşluk bırakıyor. E-posta gibi gelen işlere de ayrı zaman ayırıyor. Bu yaklaşımın stresini azalttığını ve yaptığı iş miktarını çok artırdığını söylüyor. Bu ölçülmüş bir sonuç değil, kendi izlenimi."]},{heading:"Pomodoro: kısa bir çalışma dilimi",paragraphs:["Francesco Cirillo’nun Pomodoro Tekniği de zamanı bölerek çalışmayı önerir. Genellikle 25 dakika odaklı çalışıp kısa bir mola vermek ve bunu tekrarlamak şeklinde öğretilir. Cirillo, amacın olabildiğince çok tur tamamlamak olmadığını vurgular. Asıl amaç, çalışırken zihninin ne yaptığını fark etmektir.","Önceki dersteki Hollanda çalışması buna sınırlı bir destek veriyor. Sabit aralıklarla mola veren öğrenciler kendilerini daha iyi hissetti. Üstelik mola zamanını kendileri seçenlerden daha az iş yapmadılar. Bir sabahı bütünüyle planlamak büyük geliyorsa 25 dakikalık tek bir turla başlayabilirsin."]},{heading:"Planla, dene, ayarla",paragraphs:["Odak planını bir kez yapıp bırakmak yerine düzenli olarak gözden geçir. İlerleme takibi araştırmasında, nasıl gittiğini takip edenlerin hedeflerine ulaşma olasılığı daha yüksekti. Özellikle bunu yazanlarda sonuç daha iyiydi. Her çalışma diliminden sonra iki satır not almak bu yüzden önemli. Kötü geçen bir günü bile planını düzeltmek için kullanabilirsin."],visual:{kind:"cycle",title:"Planla, dene, ayarla",center:"Her tur sana bir şey öğretir",nodes:[{label:"Planla",text:"Tek bir iş, bir süre ve bir eğer-öyleyse cümlesi."},{label:"Koru",text:"Bildirimler susturulmuş, telefon kolay erişimin dışında."},{label:"Çalış",text:"İşine devam et. Aklına başka bir şey gelirse not alıp işine dön."},{label:"Dinlen",text:"Ekrandan uzakta kısa bir mola."},{label:"Değerlendir",text:"Neyin işe yaradığını yaz ve bir dahaki sefere bir şeyi değiştir."}],note:"Önerilen bir rutin, sınanmış bir teknik değil. Değerlendirme adımı, ilerleme takibini hedefe ulaşmaya bağlayan araştırmaya dayanıyor."}}],example:{title:"Priya, 38, serbest çevirmen",text:"Priya, sürekli öğleden sonraya ertelediği sözleşme çevirisi için sabah 9’da 45 dakika ayırdı. Bir gece önce planını kâğıda yazdı. Bir cümle de ekledi: “E-postama bakmak istersem aklıma geleni deftere yazıp devam edeceğim.” Sabah Rahatsız Etme modunu açtı. Tek istisna kızının okuluydu. İki kez dikkati dağıldı; deftere “fatura” ve “bankayı ara” yazdı. 30 dakika sonra bir müşteri acil bir iş için aradı. Çalışma erken bitti. Priya bunu başarısızlık saymadı. Şöyle not aldı: “30 dakika, 4 sayfa. Bir dahaki sefere 8.30’da, müşteriler uyanmadan başla.”"},sources:["if-then-plans","focus-newport-time-blocking","procrastination-pomodoro","procrastination-pomodoro-breaks"]}},ma=Object.freeze(Object.defineProperty({__proto__:null,EXTRAS:ha,SOURCES:ua},Symbol.toStringTag,{value:"Module"})),ya=[{id:"sleep-cbti-overview",title:"Sleep Foundation · Newsom (Dimitriu, MD tarafından gözden geçirildi) · 2026 · Uykusuzluk için bilişsel davranışçı terapi (BDT-U) nasıl işler?",url:"https://www.sleepfoundation.org/insomnia/treatment/cognitive-behavioral-therapy-insomnia",type:"guidance",finding:"BDT-U’nun temel bölümlerini anlatır. Uyaran kontrolü, yatağı yalnızca uyku ve cinsellik için kullanmayı ve uyuyamadığında yataktan kalkmayı içerir. Bu sayfada yaklaşık 10 dakika önerilir. Amaç, yatak odasıyla uyanıklık arasındaki bağı azaltmaktır. Uyku kısıtlaması, uyku ihtiyacını artırmak için yatakta geçen süreyi sınırlar. Bipolar bozukluk ya da nöbet gibi uykusuzluğun ağırlaştırabileceği durumlarda önerilmez. Diğer bölümler uyku hijyeni, nefes egzersizleri ve aşamalı kas gevşetme gibi gevşeme yöntemleri ve bilişsel yeniden yapılandırmadır. Sayfa bir döngüyü de anlatır: kötü geçen geceler uyuyamama endişesi yaratır. Kişi uyumaya çalışarak yatakta daha uzun kalır ve uykuya dalmak daha da zorlaşır. BDT-U genellikle altı ila sekiz seans sürer. Dijital sürümleri de vardır.",limitation:"Bir araştırma değil, sağlık bilgi sitesinde tıbbi açıdan gözden geçirilmiş bir açıklamadır. Buradaki 10 dakika önerisi AASM’nin 20 dakika önerisinden farklıdır. Bu süreler kesin eşikler yerine uygulama önerileri olarak görülmelidir. Sayfadaki etkililik yüzdeleri adı verilen bir araştırmaya bağlanmadığı için bu kursta kullanılmaz."}],ka={"sleep-1":{deeper:[{heading:"Önce neden kalkış saatini belirliyoruz?",paragraphs:["CDC ve AASM her gün aynı saatte kalkmanı önerir. AASM hafta sonlarını da özellikle belirtir. Ne zaman kalkacağını belirlemek, ne zaman uykuya dalacağını belirlemekten daha kolaydır. Bu yüzden sabit bir kalkış saati iyi bir başlangıçtır. Yatış saatini de buna göre planlayınca her gece farklı bir saatte yatmaktan kaçınabilirsin.","Yatağa girdiğin saatle kalktığın saat arasında kalan süre, uyumak için ayırdığın zamandır. Buna uyku penceresi denir. Kalkış saatinden geriye sayınca bu süreyi görebilirsin. 7 saatlik uykuya gerçekten yer ayırıp ayırmadığın da ortaya çıkar."],visual:{kind:"steps",title:"Kalkış saatinden geriye say",steps:[{label:"Kalkış saatini belirle",text:"Örneğin sabah 6.30; hafta içi ve hafta sonu aynı."},{label:"7 saat geriye say",text:"En geç 23.30’da uyumuş olman gerekir."},{label:"Uykuya dalma payı ekle",text:"Uykuya dalmak için de zaman ayır. Örneğin ışıkları 23.15 civarında kapat."},{label:"Bir hafta kontrol et",text:"Ne zaman yattığını ve kalktığını not et; gerekirse ayarla."}],note:"Bu bir planlama örneği, reçete değildir. En az 7 saat önerisi CDC ve AASM uzlaşısına dayanır. Uykuya dalma süresi kişiden kişiye değişir."}},{heading:"Bu sayılar neyi anlatıyor?",paragraphs:["7 saat önerisi, çok sayıda araştırmayı inceleyen uzmanların uzlaşısına dayanır. Araştırmaların büyük bölümü gözlemseldir. Bu, bir öneri için makul bir temeldir. Ama 6 saat 50 dakika uyumanın zararlı olduğunu ya da herkesin aynı miktarda uykuya ihtiyaç duyduğunu göstermez. CDC’nin önerdiği süreler de yaşa göre biraz değişir.","En çok haftalar boyunca nasıl uyuduğun önemlidir. Tek bir geceden sonuç çıkarma. Düzenli olarak önerilen sürenin epey altında kaldığını fark edersen bu bilgi işine yarar. Bu kurstaki adımlar, uyku düzeninin böyle yönlerini ele almana yardımcı olur."]}],example:{title:"Daniel, 41, depo amiri",text:"Daniel’in alarmı iş günlerinde 5.45’te çalıyordu. Hafta sonları ise 9’a kadar uyuyor, pazar gecesi geç saate kadar uyuyamıyordu. Vardiyası 7’de başladığı için her gün kalkabileceği saat olarak 6.15’i seçti. 7 saat geriye sayınca 23.15 çıktı. Uykuya dalmak için de zaman bırakıp ışıkları 23’te kapatmayı hedefledi. Bu iki saati dolap kapağının içine yapıştırdığı nota yazdı. Telefonunda da kısa bir kayıt tuttu. İlk cumartesi 6.15’te isteksizce kalktı, öğleden sonra kanepede kestirdi. İkinci hafta sonu daha kolay geçti. Pazar geceleri uyumak için artık o kadar uğraşmıyordu. Büyük bir değişiklik olmadı, ama haftaya başlamak biraz kolaylaştı."}},"sleep-2":{deeper:[{heading:"Rehberler ne öneriyor?",paragraphs:["Saygın üç kuruluşun önerdiği süreler biraz farklı. Bu fark, sürelerin kesin eşikler olmadığını hatırlatıyor. Ekranı 29 dakika önce kapatmak işe yaramaz, 31 dakika önce kapatmak işe yarar demiyorlar. Hepsinin önerisi aynı yönde: gündüz daha çok ışık almak, akşamın son bölümünde ışığı ve zihnini uyaran şeyleri azaltmak.","Ekrandan bir saat uzak kalmak zor geliyorsa 30 dakikayla başlayabilirsin. Bu süre de CDC ve AASM önerileriyle uyumlu. Fark görürsen daha sonra uzatabilirsin."],visual:{kind:"table",title:"Her rehberin önerisi",columns:["Rehber","Gündüz","Akşam"],rows:[["NSF","Sabah ya da öğleden sonra en az bir saat dışarıda","Işıkları kıs; ekranları yatmadan en az bir saat önce kapat"],["CDC","Belirtilmemiş","Ekranları yatmadan en az 30 dakika önce kapat"],["AASM","Belirtilmemiş","Ekranları yatmadan en az 30 dakika önce kapat"]],note:"NSF, CDC ve AASM’nin kamuya açık sayfalarından alındı. Bunlar uygulama önerileridir; araştırmada sınanmış kesin süre sınırları değildir."}},{heading:"Sık yapılan hatalar",paragraphs:["En yaygın hata, ya hep ya hiç diye düşünmek. İlk günden bir saat dışarı çıkmaya, bütün ekranları kapatmaya ve tüm akşam düzenini değiştirmeye çalışıp iki gün sonra vazgeçebilirsin. Sürdürebildiğin küçük bir değişiklik, yarım kalan kusursuz bir plandan daha yararlıdır.","Bir başka hata, telefonun yerine yapacak bir şey koymamak. Ekran çoğu zaman gerçek bir ihtiyacı karşılar: gevşemek, biriyle konuşmak ya da kaygılarından uzaklaşmak. Loş ışıkta kitap okumak, hafifçe esnemek ya da müzik dinlemek akşamını boş bırakmadan yeni bir düzen kurmana yardımcı olur."]}],example:{title:"Ana, 29, müşteri hizmetleri temsilcisi",text:"Ana bütün gün kapalı bir yerde çalışıyordu. Yatakta uykusu gelene kadar telefonunda gezinir, çoğu zaman gece yarısını geçirirdi. Her şeyi birden değiştirmedi. Hafta içi öğle molasının yaklaşık yirmi dakikasını ofisin dışındaki bir bankta geçirmeye başladı. Otobüs durağına kısa bir yürüyüş de ekledi. Akşam için 22.30’a, alıştığı yatış saatinden yarım saat öncesine bir hatırlatıcı kurdu. Telefonunu mutfakta şarja taktı. İlk birkaç gece huzursuz olduğu için komodinine bir roman ve küçük bir lamba koydu. Bazı akşamlar yine mesajlara baktı. İki hafta sonra telefon çoğu gece mutfakta kalıyordu. Uykuya dalmayı beklerken geçirdiği süre de biraz daha kolay geliyordu."}},"sleep-3":{deeper:[{heading:"Akşamını planla",paragraphs:["NHS, AASM ve CDC, bazı alışkanlıkları yatmadan ne kadar önce bırakmanı ve gevşemeye ne zaman başlamanı önerdiklerini belirtir. Bu önerileri tek bir çizelgede birleştirebilirsin. Birinci derste kalkış saatinden geriye saymıştın. Burada da yatış saatinden geriye sayarak akşamını planlıyorsun.","Aşağıdaki örnekte yatış saati 23.00. Sen başka saatte yatıyorsan bütün satırları aynı süre kadar kaydır. Her öneriyi aynı anda uygulaman gerekmez. Tek bir alışkanlık için net bir saat belirlemek iyi bir başlangıçtır."],visual:{kind:"table",title:"23.00’te yatacaksan akşam planın",columns:["Alışkanlık","Rehber","Saat"],rows:[["Çay, kahve, alkol, sigara","En az 6 saat önce (NHS)","17.00"],["Egzersiz","En az 4 saat önce (NHS)","19.00"],["Gevşemeye başlamak","En az 1 saat önce (NHS)","22.00"],["Ekranları kapatmak","En az 30 dakika önce (CDC, AASM)","22.30"]],note:"Süreler NHS uykusuzluk rehberiyle AASM ve CDC sayfalarından alındı. Saatler, bu önerilere göre hazırlanmış bir örnektir. Önerilen süreler araştırmada sınanmış kesin eşikler değildir."}},{heading:"Kendi izlenimin neden yanıltabilir?",paragraphs:["Drake çalışmasında insanların uykularına dair değerlendirmeleri ölçümlerle tam örtüşmedi. Öğleden sonra kahve içip rahatça uykuya dalabilirsin. Yine de kahve içmediğin bir geceye göre daha az uyumuş olabilirsin. Bu yüzden yalnızca izlenimine güvenmek yerine küçük bir deney yap. Bir hafta boyunca son kahveni daha erken iç ve sabah nasıl hissettiğine bak.","Kafein yalnızca kahvede bulunmaz. Siyah çay, yeşil çay, kola ve enerji içeceklerinde de farklı miktarlarda vardır. Bir gün boyunca içtiklerini yazmak şaşırtıcı olabilir. Birkaç küçük içecek, tek bir sert kahveden daha fazla kafein içerebilir."]}],example:{title:"Tom, 38, lise öğretmeni",text:"Tom, kafeinin kendisini etkilemediğini düşünüyordu. Kahvaltıda ve öğle yemeğinde kahve içiyordu. Saat 19.00 civarında sınav kâğıtlarını okurken de kola içiyordu. Bir gün boyunca kafein içeren bütün içeceklerini yazdı. Akşam içtiği kola onu şaşırttı. Yatış saati 23’tü. 6 saat geriye sayıp son kafein saatini 17.00 olarak belirledi. Akşam kolası yerine gazlı su içmeye başladı. Koşusunu da 20.00’den okul çıkışına aldı. İlk akşamlar kâğıt okurken kolanın verdiği kısa süreli canlılığı özledi. Yaklaşık on gün sonra biraz daha erken uykuya daldığını fark etti. Bazı geceler hâlâ huzursuzdu, ama değişikliği sürdürmeye değer buldu."},sources:["sleep-habits","cdc-sleep"]},"sleep-4":{deeper:[{heading:"Endişe–uyanıklık döngüsü",paragraphs:["Uykusuzluk için bilişsel davranışçı terapiyi (BDT-U) anlatan kaynaklar, tanıdık bir döngüden söz eder. Birkaç kötü gecenin ardından uyuyamamaktan endişelenirsin. Telafi etmek için yatakta daha uzun kalır, uykuya dalmaya daha çok çalışırsın. Ama bu çaba ve endişe seni uyanık tutar. Yatak da zamanla dinlendiğin bir yerden çok sıkıntı çektiğin bir yer hâline gelir. Sonraki gece uyumak daha da zorlaşır.","Yataktan kalkmak bu döngüden çıkmanın bir yoludur. Böylece uyumaya çalışırken yaşadığın sıkıntı yatakla eşleşmez. Zamanla yatak yeniden uykuyu hatırlatan bir yer olabilir. BDT-U’nun bu bölümüne uyaran kontrolü denir."],visual:{kind:"cycle",title:"Endişe–uyanıklık döngüsü",center:"Uyumak için daha çok çabalamak",nodes:[{label:"Kötü bir gece",text:"Bir kez ya da birkaç kez kötü uyursun."},{label:"Endişe",text:"“Bu gece uyuyamazsam yarın felaket olur.”"},{label:"Yatakta daha çok zaman",text:"Uykuyu zorlamak için erken yatar ya da yatakta daha uzun kalırsın."},{label:"Uyanık kalırsın",text:"Çaba ve hayal kırıklığı zihnini uyanık tutar."},{label:"Yatakla sıkıntı eşleşir",text:"Yatağı, uyanık kalıp uyumaya çalıştığın bir yer olarak görmeye başlarsın."}],note:"BDT-U kaynaklarında anlatılan döngüye dayanır. Uyuyamadığında yataktan kalkmak ve her gün aynı saatte kalkmak bu döngüyü kırmaya yardımcı olabilir."}},{heading:"Sakin köşende ne yapabilirsin?",paragraphs:["Amaç zamanını verimli geçirmek değil, uykunun yeniden gelmesini beklemek. İstediğin an bırakabileceğin sakin bir uğraş seç. BDT-U programlarında yavaş nefes alma ve aşamalı kas gevşetme gibi yöntemler de öğretilir. Kas gevşetmede kas gruplarını tek tek gerip bırakırsın. Bu yöntemler de burada uygun olabilir.","Farklı rehberler yaklaşık 10, 15 ya da 20 dakika sonra kalkmayı öneriyor. Sana uygun bir süre seç. Saati izlemek yerine ne kadar zaman geçtiğini yaklaşık olarak tahmin et."],visual:{kind:"compare",title:"Gece yataktan kalktığında",left:{label:"Yardımcı olabilecekler",items:["Loş ışık, sessiz bir yer","Sıkıcı bir kitap ya da dergi","Yavaş nefes ya da hafif esneme"]},right:{label:"Seni uyanık tutabilecekler",items:["Telefon, dizüstü ya da TV","Sürekli saate bakmak","Çalışmak ya da yarını ayrıntılı planlamak"]},note:"AASM önerileriyle BDT-U kaynaklarında anlatılan gevşeme yöntemlerine dayanır."}}],example:{title:"Nadia, 52, muhasebeci",text:"Vergi döneminde Nadia bir saat boyunca yatakta uyuyamıyordu. Aklı işteydi, sürekli saate bakıyordu. Oturma odasında sakin bir köşe hazırladı. Küçük bir lamba, battaniye ve biraz sıkıcı bulduğu eski bir gezi kitabı koydu. Salı gecesi uzun süredir uyanık olduğunu fark edince saate bakmadan kalktı. Birkaç sayfa okudu, yavaşça nefes aldı. Gözleri ağırlaşınca yatağa döndü. Uykuya dalmadan önce bir kez daha kalkması gerekti. Sabah yorgun olsa da planladığı gibi 6.45’te kalktı. Haftanın sonunda yatakta uyanık geçirdiği uzun süreler tamamen bitmemişti, ama kısalmıştı."},sources:["sleep-cbti-overview"]},"sleep-5":{deeper:[{heading:"BDT-U neleri içerir?",paragraphs:["BDT-U, genellikle bu alanda eğitimli bir uzmanla yaklaşık altı ila sekiz seans süren yapılandırılmış bir programdır. Dijital sürümleri de vardır. Birkaç bölümden oluşur. Uyaran kontrolü gibi bazı bölümleriyle bu kursta basitleştirilmiş biçimde karşılaştın.","Uyku kısıtlaması denen bölümde, uyku ihtiyacını artırmak için yatakta geçen süre bir süreliğine azaltılır. Uykusuzluğun ağırlaştırabileceği bipolar bozukluk ya da nöbet gibi durumlarda önerilmez. Bu nedenle uyku kısıtlaması bir kendi kendine yardım kursunda uygulanacak bir yöntem değildir; bir uzmanla ele alınmalıdır."],visual:{kind:"table",title:"BDT-U’nun ana bölümleri",columns:["Bölüm","Neleri içerir"],rows:[["Uyaran kontrolü","Yatak yalnızca uyku ve cinsellik için; uyuyamadığında kalk"],["Uyku kısıtlaması","Yatakta geçen süreyi geçici olarak sınırlamak; en iyisi bir uzmanla yapılır"],["Gevşeme","Nefes egzersizleri, aşamalı kas gevşetme ve benzeri yöntemler"],["Bilişsel çalışma","Uykuya dair kaygıları ve gerçekçi olmayan beklentileri incelemek"],["Uyku hijyeni","Alışkanlıkların, beslenmenin, egzersizin ve yatak odasının uykuyu nasıl etkilediği"]],note:"Tıbbi açıdan gözden geçirilmiş bir BDT-U açıklamasından özetlendi. Bu kurs BDT-U değildir. Yalnızca kendi başına deneyebileceğin birkaç basit fikrinden yararlanır."}},{heading:"Ne zaman doktora başvurmalısın?",paragraphs:["Bazı uyku sorunları alışkanlıklarla ilgilidir. Bu kurstaki adımlar yardımcı olabilir. Bazıları ise uzman değerlendirmesi gerektirir. Uykusuzluğun uzun sürmesi, uyku apnesi işaretleri ya da günlük hayatı zorlaştıran gündüz uykululuğu varsa randevu al. Böyle bir durumda tek başına daha çok çabalamak yeterli olmayabilir.","Araba kullanırken uyanık kalmakta zorlanacak kadar uykuluysan araba kullanma. Kısa süre içinde doktora başvur. Yatış ve kalkış saatlerinle gece uyanmalarını iki hafta kaydetmen görüşmeyi kolaylaştırır. Doktorunun da durumunu daha iyi anlamasına yardımcı olur."],visual:{kind:"compare",title:"Ne zaman kendi başına deneyebilirsin, ne zaman yardım almalısın?",left:{label:"Kendi başına denemeye değer",items:["Düzensiz program ya da geç saatte ekran","Günün geç saatinde kafein","Stresli bir günün ardından ara sıra kötü geceler"]},right:{label:"Doktora başvur",items:["3 aydan uzun süredir haftada en az 3 gece uykusuzluk","Yüksek sesli horlama ve nefes duraklamaları, nefes nefese kalma ya da boğulma hissi","İşi, günlük yaşamı ya da araba kullanmayı etkileyen gündüz uykululuğu"]},note:"ACP rehberinden ve NHS uykusuzluk ile uyku apnesi sayfalarından. Bu bir tanı kontrol listesi değildir."}}],example:{title:"Karen, 58, okul kütüphanecisi",text:"Karen yılın büyük bölümünde iyi uyuyamamıştı. Öğleden sonranın başında bile bitkin hissediyordu. Kalkış saatini sabitlemiş, geç saatte çay içmeyi bırakmıştı. Bunlar biraz yardımcı oldu, ama yetmedi. Bir sabah eşi, bazen nefesinin bir an durduğunu, ardından horlama sesi çıkardığını söyledi. Karen bunu bilmiyordu. O hafta yatış ve kalkış saatleriyle kaç kez uyandığını kaydetti. Eşinden de fark ettiklerini yazmasını istedi. Doktorundan randevu aldı. İki notu da ilaçlarının listesiyle birlikte götürdü. Kendi başına hiçbir şeyi değiştirmedi. Doktor onu uyku değerlendirmesine yönlendirdi. Sırada ne yapacağını bildiği için görüşmeden rahatlamış çıktı."},sources:["sleep-cbti-overview"]}},ca=Object.freeze(Object.defineProperty({__proto__:null,EXTRAS:ka,SOURCES:ya},Symbol.toStringTag,{value:"Module"})),ga=[{id:"calm-nhs-anxiety",title:"NHS Every Mind Matters · Kaygı",url:"https://www.nhs.uk/every-mind-matters/mental-health-issues/anxiety/",type:"guidance",finding:"Kaygının beden ve zihinde görülen işaretlerini sıralar: yorgunluk, huzursuzluk, baş dönmesi, odaklanma güçlüğü, geçmiş ya da gelecek için endişelenme, en kötü sonucu bekleme, baş ağrısı, mide ağrısı, kas gerginliği, çarpıntı ve nefes darlığı. Kaygı veren durumlardan kaçınmanın ya da güvende hissettiren alışkanlıklara dayanmanın kaygıyı artırabileceğini belirtir. Korkulan durumlarla adım adım yüzleşmeyi önerir. Nefes egzersizleri, kaygıyı tetikleyen durumları kaydetmek, endişelenmek için her gün belli bir zaman ayırmak ve duruma farklı açılardan bakmak da önerileri arasındadır. Kaygı günlük hayatı ciddi biçimde etkiliyorsa NHS 111’e ya da aile hekimine başvurmayı önerir. Baş edemiyorsan ya da kendini güvende tutamıyorsan acil yardım almanı söyler.",limitation:"İngiltere için hazırlanmış genel bir kendi kendine yardım rehberidir; kanıtların ayrıntılarını vermez. Hizmetler ve telefon numaraları ülkeye göre değişir. Türkiye’de acil durumlarda 112 aranır."}],ba={"calm-1":{deeper:[{heading:"Stres kendini nerede gösterir?",paragraphs:["Stresli olduğunu her zaman hemen anlamayabilirsin. Önce çenen sıkılır, midene bir düğüm oturur, çabuk sinirlenirsin ya da zihnin sürekli bir işten diğerine atlar. NHS, stresin hem bedende hem zihinde görülen işaretlerini sıralar. Kaygıyla ilgili sayfalarında çarpıntı, nefes darlığı, huzursuzluk ve hemen en kötü sonucu düşünmek de yer alır.","Stresin sende nasıl ortaya çıktığı genellikle sandığından daha az değişir. Kimi insanın omuzları gerilir, kiminin uykusu bozulur, kimi de çabuk sinirlenir. İlk iki üç işareti tanırsan gerginlik henüz hafifken fark edip bir şey yapabilirsin."],visual:{kind:"table",title:"Stres ve kaygının yaygın işaretleri",columns:["Nerede","Neler fark edebilirsin"],rows:[["Beden","Baş ağrısı, kas gerginliği, mide ağrısı, çarpıntı"],["Zihin","Odaklanma güçlüğü, bunalma, en kötüsünü beklemek"],["Duygu durumu","Sinirlilik, huzursuzluk"],["Dinlenme","Uyku değişiklikleri, yorgunluk"]],note:"NHS’in stres ve kaygı sayfalarından. Bu işaretlerin birçok olası nedeni vardır; sürüyorsa ya da seni endişelendiriyorsa bir hekime başvur."}},{heading:"Tek bir kelime neden işe yarayabilir",paragraphs:["Torre ve Lieberman’a göre duyguna bir ad vermek, duygularını düzenlemenin sessiz bir yoludur. Bazı tekniklerde nasıl hissettiğini bilerek değiştirmeye çalışırsın. Adlandırırken ise hiçbir şey yapmıyormuş gibi gelebilir. Bu da işini kolaylaştırır: doğru uygulaman gereken bir yöntem yoktur.","Duyguna verdiğin ad, o ana özgü ve somut olsun. “Her şey berbat” bütün hayatın hakkında bir yargıdır. “Yarınki sunum yüzünden gerginim” ise şu anı anlatır. İkinci cümle yapabileceğin bir şeyi de gösterir: bir slaytı hazırlamak ya da bir iş arkadaşından görüş istemek gibi. Duygunu adlandırmak sorunu çözmez. Ama onu daha net görmene yardımcı olabilir."]}],example:{title:"Elif, 34, proje koordinatörü",text:"Elif’in çenesi öğleden sonra sık sık ağrırdı. Akşamları da hayat arkadaşına küçük şeyler yüzünden çıkışırdı. Buna hep “Yoğun bir hafta işte” derdi. Salı günü gergin bir toplantının ardından masasında durup ne hissettiğini düşündü. Önce “sinirliyim” dedi. Sonra daha uygun kelimeyi buldu: “endişeliyim”. Not uygulamasına tek satır yazdı: “Müşteri teslim tarihini değiştirdiği için endişeliyim.” Bunu yazınca teslim tarihi değişmedi. Ama omuzlarının biraz gevşediğini fark etti. Yöneticisine hangi işin bekleyebileceğini soran kısa bir mesaj gönderdi. O akşam bulaşık yüzünden tartışmak yerine işten dolayı stresli olduğunu anlattı. Bu küçük değişiklik akşamının daha rahat geçmesini sağladı."},sources:["calm-nhs-anxiety"]},"calm-2":{deeper:[{heading:"Çalışma aslında neyi karşılaştırdı",paragraphs:["Gönüllüler dört uygulama grubuna rastgele ayrıldı. Döngüsel iç çekme grubundakiler burundan yavaşça nefes aldı. Akciğerleri tamamen doldurmak için bir kez daha kısa bir nefes alıp ağızdan yavaşça ve tamamen verdi. Kutu nefesinde nefes alma, tutma ve verme süreleri eşitti. Üçüncü grup birkaç tur hızlı ve derin nefes aldı, ardından nefesini tuttu. Dördüncü grup farkındalık meditasyonu yaptı: dikkatini tek bir noktaya verdi, zihni dağıldığında yavaşça o noktaya döndü.","Araştırmacılara göre uzun süre nefes vermek, sinir sisteminin sakinleşmeyi sağlayan bölümünü devreye sokarak yardımcı olabilir. Bu makul bir açıklama, ama çalışma bunu kanıtlamıyor. Grafik, üç nefes grubunun ortak ortalamasıyla meditasyon grubunu karşılaştırıyor. Gösterilen değer, olumlu duygulardaki ortalama günlük artış."],visual:{kind:"bars",title:"Olumlu duyguda ortalama günlük artış",bars:[{label:"Nefes egzersizleri (üç grup birlikte)",value:1.91,display:"1,91"},{label:"Farkındalık meditasyonu",value:1.22,display:"1,22"}],note:"Balban ve ark. 2023: çoğu sağlıklı öğrenci olan 108 kişide, 28 gün boyunca kişi başına ortalama günlük değişim. Nefes grupları içinde en büyük artış döngüsel iç çekmede görüldü. O anda hissedilen kaygı tüm gruplarda azaldı. Azalma meditasyonda biraz daha fazlaydı (−3,95’e karşı −3,03).",sourceId:"cyclic-sighing"}},{heading:"Ne zaman durmalısın, ne zaman yardım almalısın?",paragraphs:["NHS inform, bir nefes egzersizinde rahatsızlık ya da ağrı hissedersen durmanı öneriyor. Sonrasında başın dönmesin diye bir süre oturmaya devam et. Solunum sorunu gibi bir sağlık durumun varsa önce doktorunla konuş. Yavaş ve rahat nefes al; kendini zorlaman gerekmiyor.","Panik atak, ani ve yoğun bir korku dalgasıdır. NHS, atak sırasında yavaş nefes almayı önerir. Ataklar korkutucudur ama tehlikeli değildir. Tekrarlıyorlarsa bir nefes egzersizi tek başına yetmez; doktora başvur. Bilişsel davranışçı terapi gibi konuşma terapileri, panik bozukluğunun başlıca tedavileri arasındadır."]}],example:{title:"Murat, 45, otobüs şoförü",text:"Murat geç vardiyadan çoğu zaman gergin çıkardı. Trafikte kazadan kıl payı kurtulduğu anlar aklından çıkmaz, geceleri uyuyamazdı. Eve gitmeden önce park hâlindeki arabasında döngüsel iç çekmeyi denemeye karar verdi. 5 dakikalık bir sayaç kurdu. Burnundan nefes aldı, ardından bir kez daha kısa bir nefes alıp ağzından yavaşça verdi. İlk akşam bir dakika sonra başı biraz döndü. Bunun üzerine yavaşladı ve kendini zorlamadan nefes aldı. Bazı günler daha sakin hissetti. Bazı günler pek bir değişiklik olmadı; bunu da not etti. İki hafta sonra bu uygulama işten eve geçişinin bir parçası olmuştu. Vardiyaları aynı derecede stresliydi, ama eve biraz daha az gergin giriyordu."},sources:["state-nhs-breathing-tips","state-nhs-panic"]},"calm-3":{deeper:[{heading:"Ceza değil, mola olsun",paragraphs:["Egzersiz planları bazen ceza gibi olduğu için yürümüyor: çok uzun, çok zor ya da günün en elverişsiz saatinde. DSÖ, stresle baş etmek için düzenli egzersiz öneriyor. Kısa bir hareket molasını zaten yaptığın bir şeye bağlarsan düzenli sürdürmen kolaylaşır.","Hareketten önce ve sonra gerginliğine 0’dan 10’a kadar bir puan ver. Böylece küçük bir deney yapmış olursun. Bir hafta içinde hangi hareketin sana gerçekten iyi geldiğini görebilirsin. Seçimini yalnızca ne yapman gerektiğine dair düşüncelerine göre yapmamış olursun."],visual:{kind:"compare",title:"Hareketi planlamanın iki yolu",left:{label:"Ceza gibi",items:["Spor salonunda bir saat çalışamayacaksam hiç yapmayayım","İlk günden kendini sonuna kadar zorlamak","Bir gün aksatınca vazgeçmek"]},right:{label:"Mola gibi",items:["Öğle yemeğinden sonra on dakika tempolu yürüyüş","Dans ya da bisiklet gibi keyif aldığın bir şey","Kaçırdığın günü telafi etmeden ertesi gün yeniden başlamak"]},note:"Bunlar uygulama önerileri; sınanmış kurallar değil. Bir sağlık sorunun varsa sana uygun tempoyu doktorunla konuş."}},{heading:"Sayıları nasıl okumalı?",paragraphs:["Grafikteki sayılar standartlaştırılmış etki büyüklükleridir. Bu ölçü, farklı anketler kullanan çalışmaların sonuçlarını karşılaştırmayı sağlar. Buradaki değerler kabaca orta düzeydedir. Çok sayıda kişide görülen ortalama değişimi gösterirler. Senin nasıl etkileneceğini bu sayılardan bilemeyiz.","Araştırmaların kalitesiyle ilgili uyarıyı dikkate almak gerekir. Bir şemsiye derlemede incelenen derlemelerin çoğu kritik düzeyde düşük kalitedeyse, etkinin tam büyüklüğünden çok hangi yönde olduğuna güvenebiliriz. Hareket, diğer desteklerin yanında stres için denenebilecek makul ve düşük riskli bir seçenektir."]}],example:{title:"Leyla, 52, diş kliniği sekreteri",text:"Leyla bütün gün telefonlara ve bekleme salonundaki şikâyetlere yetişiyordu. Saat dörde doğru hem gergin hem bitkin hissediyordu. Kendine spor salonunda bir saat geçireceğine söz verir, sonra vazgeçerdi. Bu kez öğle yemeğinden sonra çevrede 12 dakikalık tempolu bir yürüyüş yapmayı seçti. Düzenli olarak ayırabildiği tek mola buydu. Çıkmadan önce gerginliğine 7 puan verdi, döndüğünde puanı 5’ti. Bazı günler yalnızca bir puan düştü. Yağmurlu bir gün yürümek yerine binanın merdivenlerini çıktı. Üç hafta sonra yürüyüşe alışmıştı. İşin sakin olduğu günlerde ikinci bir tur ekledi. İşi hâlâ yoğundu, ama öğleden sonraları artık onu eskisi kadar bunaltmıyordu."},sources:[]},"calm-4":{deeper:[{heading:"Kaçınmak kaygıyı nasıl sürdürür?",paragraphs:["Bir düşünceyi bastırmakla kaygı veren durumdan tamamen kaçınmak birbirine benzer. NHS, bu durumlardan uzak durmanın ya da güvende hissettiren alışkanlıklara dayanmanın kaygıyı artırabileceğini belirtir. Kaçınmak o anda rahatlatır. Bu yüzden bir dahaki sefere de kaçınmak istersin. Ama böylece o durumla baş edebileceğini görme fırsatını kaçırırsın.","Bu döngüden çıkmak genellikle zaman alır. NHS, korktuğun durumlarla adım adım yüzleşmeyi öneriyor. Böylece baş etmenin mümkün olduğunu hissedebilirsin. Duruma farklı açılardan bakmak da yardımcı olabilir. Düşünceni yeniden değerlendirmekle duruma yaklaşan küçük bir adım atmak birbirini destekler. Kaygı günlük hayatını aksatıyorsa bu çalışmayı bir uzmanla yapmak en iyisidir."],visual:{kind:"cycle",title:"Kaygı–kaçınma döngüsü",center:"Hızlı rahatlama, kalıcı korku",nodes:[{label:"Tetikleyici",text:"Zor bir telefon görüşmesi gibi tehdit olarak algıladığın bir durum."},{label:"Kaygılı düşünce",text:"“Bu kötü geçecek ve baş edemeyeceğim.”"},{label:"Kaçınma",text:"Aramayı ertelersin ya da bir çıkış yolu bulursun."},{label:"Rahatlama",text:"Gerginlik şimdilik düşer."},{label:"Korku büyür",text:"Baş edebileceğini görme fırsatın olmaz. Bir sonraki benzer durum daha korkutucu gelir."}],note:"Döngünün basitleştirilmiş hâli. NHS, kaygı veren durumlardan kaçınmanın kaygıyı artırabileceğini belirtir ve adım adım yüzleşmeyi önerir. Kaygı günlük hayatını aksatıyorsa bir uzmana başvur."}},{heading:"Yeniden değerlendirmek kendini kandırmak değildir",paragraphs:["Yeniden değerlendirmek, kendini olumlu düşünmeye zorlamakla karıştırılabilir: “Yöneticimin beni eleştirmesi aslında harika.” Bu cümle genellikle inandırıcı gelmez. İşe yarayan bir değerlendirme ise gerçeklere bağlı kalır ve ilk anda gözden kaçırdıklarını da hesaba katar.","Aşağıdaki sorular durumu daha bütünlüklü görmene yardımcı olabilir. Hepsini yanıtlaman gerekmez. Dürüstçe vereceğin tek bir cevap bile ilk yorumuna daha az takılı kalmanı sağlayabilir."],visual:{kind:"table",title:"Duruma daha geniş açıdan bakmak",columns:["Soru","Örnek cevap"],rows:[["Yorum katmadan anlatırsam ne oldu?","Yöneticim raporumdaki iki hatayı gösterdi."],["Bu başka ne anlama gelebilir?","Rapor önemli olduğu için yazdıklarımı dikkatle okuyor."],["Dışarıdan bir gözlemci nasıl görürdü?","Uzun bir raporda iki hata yaygındır ve düzeltilebilir."],["Hangi kısmı değiştirebilirim?","Hataları bugün düzeltebilirim. Bir dahaki sefere raporu birinin daha kontrol etmesini isteyebilirim."]],note:"Webb ve ark. 2012’deki yeniden değerlendirme ve başka birinin bakış açısından bakma yöntemlerine dayanır. Sorular uygulamayı kolaylaştıran ipuçlarıdır; araştırmada sınanmış soru kalıpları değildir."}}],example:{title:"Kaan, 27, yeni başlayan web geliştirici",text:"Kaan’a ekip liderinden kısa bir mesaj geldi: “Yarın konuşabilir miyiz?” Aklına ilk gelen şey işten çıkarılacağı oldu. Akşam boyunca bunu düşünmemeye çalıştı, ama düşünce aklından çıkmadı. Dokuz sularında durumu tek cümleyle yazıp mesajın başka ne anlama gelebileceğini düşündü. İki olasılık buldu: yeni bir proje ya da geçen haftaki hatayla ilgili geri bildirim. Sonra bir arkadaşının bu mesaja nasıl bakacağını düşündü. Ortada yalnızca ne demek istediği belli olmayan bir mesaj vardı. Hâlâ gergindi. Yine de her ihtimale karşı çalıştığı işlerin kısa bir listesini yaptı ve beklediğinden iyi uyudu. Toplantıda teslim tarihindeki bir değişiklik konuşuldu. Bir dahaki sefere düşüncelerini daha erken yazmaya karar verdi."},sources:["calm-nhs-anxiety"]},"calm-5":{deeper:[{heading:"Destek listeni hazırla",paragraphs:["Destek listeni sakin bir günde hazırlamak daha kolaydır. Zor bir günün ortasında, stresin yüksekken kimi arayacağını düşünemeyebilirsin. Üstelik başkalarına yük olacağın düşüncesine daha kolay kapılabilirsin.","Listene farklı kişiler ve kurumlar ekle: konuşabileceğin biri, günlük işlerde yardım edebilecek biri ve başvurabileceğin uzmanlar. İletişim bilgilerini kolayca bulabileceğin bir yerde tut. Telefonunun not uygulaması olabilir."],visual:{kind:"steps",title:"Destek listen için dört satır",steps:[{label:"Konuşacak biri",text:"Zor bir günde arayabileceğin ya da yazabileceğin bir arkadaş veya aile üyesi."},{label:"Günlük işlerde yardım",text:"İşlerinden birini üstlenebilecek bir iş arkadaşı, komşu ya da akraba."},{label:"Doktorun",text:"Stresle baş etmek zorlaştığında başvuracağın aile sağlığı merkezi ya da klinik."},{label:"Acil durum",text:"Kendine zarar verme düşüncesi ya da acil tehlike için 112."}],note:"DSÖ ve NHS’in insanlarla iletişimi sürdürme ve ne zaman yardım almak gerektiğine dair önerilerine dayanır. Ülkende varsa bir kriz destek hattını da ekle."}},{heading:"Panik ataklar ve günlük hayatı aksatan kaygı",paragraphs:["Panik atak, bedende güçlü biçimde hissedilebilen ani ve yoğun bir korku dalgasıdır. NHS’e göre ataklar korkutucudur ama tehlikeli değildir; atak sırasında yavaş nefes almak yardımcı olabilir. Ataklar düzenli olarak tekrarlıyorsa panik bozukluk söz konusu olabilir. Bu durumda doktora başvur. Bilişsel davranışçı terapi (BDT) gibi konuşma terapileri başlıca tedaviler arasındadır. İlaç da bazı kişilere yardımcı olur.","NHS, kaygı günlük hayatını ciddi biçimde etkiliyorsa yardım almanı öneriyor. Baş edemiyorsan ya da kendini güvende tutamıyorsan acil yardım al. Eğitimli bir terapistle BDT genellikle 5 ila 15 seans sürer. Bu kurstaki kısa alıştırmalar terapiye eşlik edebilir, ama onun yerini tutmaz."]}],example:{title:"Rukiye, 61, emekli hemşire",text:"Eşinin ameliyatından beri Rukiye hem onun randevularıyla hem ev işleriyle tek başına ilgileniyordu. Kendi kaygılarıyla da yalnız baş etmeye çalışıyordu. Kimseyi rahatsız etmek istemediğini söyleyip duruyordu. Sakin bir sabah bu dersteki destek tablosunu açıp dört satır yazdı: konuşmak için kız kardeşi, hastaneye ulaşmak için komşusu, aile hekimi ve 112. O hafta kız kardeşini aradı. İlk kez yorgun ve korkmuş olduğunu açıkça söyledi. Kız kardeşi perşembe günleri yanına gelmeyi önerdi. Rukiye bir aydan uzun süredir iyi uyuyamadığı için doktorundan da randevu aldı. Hiçbir şey bir gecede düzelmedi, ama artık bütün yükün yalnızca kendisinde olduğunu hissetmiyordu."},sources:["calm-nhs-anxiety","state-nhs-panic","optimism-nhs-cbt"]}},pa=Object.freeze(Object.defineProperty({__proto__:null,EXTRAS:ba,SOURCES:ga},Symbol.toStringTag,{value:"Module"})),fa=[{id:"meditation-mind-wandering-cycle",title:"Hasenkamp ve ark. · 2012 · Odaklı meditasyonda zihin dağılması ve dikkat (NeuroImage)",url:"https://www.sciencedirect.com/science/article/abs/pii/S1053811911007695",type:"research",finding:"Deneyimli on dört kişi, fMRI cihazında nefese odaklanarak meditasyon yaptı. Zihinlerinin dağıldığını her fark ettiklerinde bir düğmeye basıp dikkatlerini nefese geri verdiler. Araştırmacılar tekrarlanan dört aşamalı bir döngü tanımladı: zihnin dağılması, bunu fark etme, dikkati geri verme ve odağı sürdürme. Her aşamada farklı beyin ağları daha etkindi. Zihin dağılırken varsayılan mod ağı, fark etme sırasında belirginlik ağı, geri dönme ve odaklanma sırasında yürütücü bölgeler öne çıktı. Bazı etkinlik örüntüleri, kişilerin yaşamları boyunca edindikleri meditasyon deneyimiyle ilişkiliydi.",limitation:"Deneyimli 14 kişiyle yapılan küçük bir beyin görüntüleme çalışmasıdır. Meditasyon sırasında olanları anlatır; sağlık yararı göstermez. Beyindeki farklara meditasyonun yol açtığını da kanıtlamaz. Yayıncı sayfasındaki özet okundu."},{id:"meditation-trauma-sensitive",title:"David Treleaven · Travmaya duyarlı farkındalık (davidtreleaven.com)",url:"https://davidtreleaven.com/",type:"guidance",finding:"Farkındalık eğitmenleri yetiştiren David Treleaven, uygulamanın istemeden travmatik stres belirtilerini tetikleyebileceğini belirtir. Travma yaşamış kişiler, dikkatlerini içe çevirdiklerinde geçmişteki olayı yeniden yaşıyormuş gibi hissedebilir (flashback), duygularını düzenlemekte zorlanabilir ya da kendilerinden veya çevrelerinden kopmuş hissedebilir. Sitesinde eğitmenlere ve uygulayan kişilere bu durumları önlemek için eğitim ve kaynaklar sunar.",limitation:"Bir eğitmenin web sitesidir, araştırma değildir. Yalnızca ana sayfa okundu; burada belirli uyarlamalar sıralanmıyor. Bu kurstaki gözleri açık tutma, süreyi kısaltma, dışarıdaki bir şeye odaklanma ve eğitimli bir eğitmenle çalışma önerileri yaygın güvenlik uygulamalarıdır. Bu sayfadan elde edilmiş araştırma bulguları değildir."}],va={"meditation-1":{deeper:[{heading:"Dikkatin dağılması neden uygulamanın parçası?",paragraphs:["Küçük bir beyin görüntüleme çalışması, meditasyon sırasında olanları gösteriyor. Deneyimli on dört kişi nefeslerine odaklandı. Zihinlerinin dağıldığını her fark ettiklerinde bir düğmeye bastılar. Araştırmacılar sürekli tekrarlanan bir döngü tanımladı: zihnin dağılır, fark edersin, dikkatini geri verirsin. Bir süre nefesini izlersin, sonra zihnin yeniden dağılır.","Deneyimli kişiler bile bu döngüyü tekrar tekrar yaşadı. Huzursuz bir günde bunu hatırla. Dikkatinin çok dağılması meditasyonun başarısız olduğu anlamına gelmez. Her fark edip geri döndüğünde uygulamanın en önemli iki adımını tekrarlamış olursun. Çalışma küçüktü ve sağlık üzerindeki etkileri göstermiyor. Ama anlatılan döngü, çoğu insanın deneyimiyle örtüşüyor."],visual:{kind:"cycle",title:"Meditasyon sırasında tekrarlanan döngü",center:"Odak noktası: nefes",nodes:[{label:"Dikkatin dağılır",text:"Dikkat bir plana, bir anıya ya da bir endişeye kayar."},{label:"Fark et",text:"Artık nefesini izlemediğini fark edersin."},{label:"Geri dön",text:"Kendini azarlamadan dikkatini yeniden nefesine verirsin."},{label:"Kal",text:"Dikkatin yeniden dağılana kadar bir süre nefesini izlersin."}],note:"Hasenkamp ve ark. (2012), deneyimli 14 kişide bu dört aşamayı tanımladı. Döngü olağandır. Fark etmek ve geri dönmek uygulamanın kendisidir."}},{heading:"Sık yapılan hatalar",paragraphs:["En sık yapılan hata, nefesi kontrol etmeye çalışmak. Daha derin, daha yavaş ya da daha “doğru” nefes almaya uğraşabilirsin. Bu alıştırmada yalnızca izlemen yeterli. İzlemek nefes alışını yapaylaştırıyorsa dikkatini daha rahat hissettiğin bir yere ver. Burnundaki hava akışı ya da karnının yükselmesi olabilir.","İkinci hata, dikkatin her dağıldığında kendini azarlamak. İçinden sessizce “düşünce” deyip sakin biçimde geri dönmeyi dene. Kendine kızmaktan daha yararlıdır. Beş dakikayla başlamak yeterli. Düzenli yaptığın kısa bir uygulama, gözünü korkutan uzun bir uygulamadan daha iyidir."]}],example:{title:"Leyla, 31, eczacı",text:"Leyla sabah vardiyasından önce beş dakikalık sayaç kurdu. Mutfak sandalyesine oturup ayaklarını yere bastı. Karnının yükselip alçalmasını izlemeyi seçti. Daha ilk dakikada aklında sevkiyat programını düzenlemeye başlamıştı. Bunu fark etti, içinden “düşünce” deyip dikkatini karnına verdi. Sonra yanıtlaması gereken bir mesajı düşündü. Ardından aklına bir şarkı geldi. Sonunda kaç kez geri döndüğünü sayamaz olmuştu. Zihninin bu kadar meşgul olmasına biraz kızdı. Otobüste dersteki döngüyü hatırladı: dağıl, fark et, geri dön, kal. Az önce alıştırmayı onlarca kez yapmıştı. Ertesi sabah yeniden denedi. Bu kez biraz daha az kızıyordu. Kızgınlığını da fark edebileceği bir duygu olarak gördü."},sources:["meditation-mind-wandering-cycle"]},"meditation-2":{deeper:[{heading:"Beden taraması nasıl ilerler?",paragraphs:["Basit bir sıra belirlemek, nereden devam edeceğini düşünme ihtiyacını azaltır. Genellikle kolayca bir şey hissettiğin bir yerden, örneğin ayak tabanlarından başla. Dikkatini yavaşça yukarı taşı. Her bölgede birkaç nefes boyunca kalıp ne hissettiğine bak. Sonra nefes verirken o bölgeyi bırakıp bir sonrakine geç.","Bedeninin her santimini taraman gerekmez. Beş altı bölgeye dikkatle bakmak, bütün bedeni aceleyle taramaktan daha yararlıdır."],visual:{kind:"steps",title:"Kısa bir beden taramasında izlenecek sıra",steps:[{label:"Ayaklar",text:"Parmaklar, tabanlar, topuklar: basınç, sıcaklık, zeminle ya da yatakla temas."},{label:"Bacaklar",text:"Baldırlar, dizler, uyluklar: ağırlık, gerginlik ya da belirgin bir duyum olmaması."},{label:"Gövde",text:"Karın ve sırt: nefesin hareketi, yüzeyle temas."},{label:"Kollar ve eller",text:"Parmaklar, avuç içleri, ön kollar: karıncalanma, sıcaklık, durgunluk."},{label:"Omuzlar ve yüz",text:"Boyun, çene, gözler, alın. Sonra bedeninin tamamını bir bütün olarak hisset."}],note:"MBSR beden taramasına dayanan basitleştirilmiş bir sıra. Ağrı ya da sıkıntı hissettiğin bir bölgeyi atlayabilir veya üzerinde kısa süre durup geçebilirsin."}},{heading:"Bedenine odaklanmak zor geliyorsa",paragraphs:["Bedenine uzun süre dikkat vermek bazı insanları sakinleştirmek yerine sıkıntıya sokabilir. Özellikle travma geçmişin ya da kronik ağrın varsa bu yaşanabilir. Travma alanında çalışan eğitmenler, içe odaklanmanın bazen geçmişteki olayı yeniden yaşıyormuş gibi hissettirebileceğini ya da kopukluk hissini tetikleyebileceğini belirtir.","Nasıl uygulayacağına sen karar verirsin. Gözlerini açık tutabilir, uzanmak yerine oturabilirsin. Taramayı birkaç dakikaya indirebilir ya da yalnızca ellerine ve ayaklarına bakabilirsin. Hâlâ zor geliyorsa odadaki sesler gibi dışarıdaki bir şeye odaklan. Bu alanda eğitimli bir eğitmenle çalışmayı da düşünebilirsin."]}],example:{title:"Tolga, 46, kurye",text:"Tolga uzun bir vardiyadan sonra yatağa uzanıp beden taramasını denedi. Dizlerine gelmeden uyuyakaldı. Ertesi akşam koltuğa oturdu. Gözlerini yarı açık tutup sekiz dakikalık sayaç kurdu. Ayaklarında sıcaklık ve ağırlık hissediyordu. Baldırlarında belirgin bir şey yoktu. Bunun doğru mu yanlış mı olduğunu düşünmeye başladığını fark etti. Yalnızca adını koydu: “Burada belirgin bir duyum yok.” Belinin alt kısmına gelince tanıdık ağrıyı hissetti. Onu gidermeye çalışmadı. İki nefes boyunca orada kalıp devam etti. Sonunda telefonuna üç kelime yazdı: ağır, ağrı, sıcak. Derin bir gevşeme yaşamadı. Ama haftalardır ilk kez bedeni ağrıyla dikkatini çekmeden önce onu fark etmişti."},sources:["meditation-trauma-sensitive"]},"meditation-3":{deeper:[{heading:"Zorlamamak neden önemli?",paragraphs:["Meditasyonu da iyi yapman gereken bir işe çevirebilirsin. Düşüncelerle savaşır, nasıl gittiğini kontrol eder, gevşeyemediğin için gerilirsin. Benson’un yöntemi bu baskıyı azaltmayı amaçlar. Tekrarladığın kelime, dikkatini verebileceğin basit bir şeydir. Düşüncelere karşı pasif tutum ise onları çözmen gereken sorunlar olarak görmemektir. Geldiklerinde yalnızca kelimeye dönersin.","Nefes alıştırmasında da aynı şeyi yapmıştın. Yalnızca odaklandığın şey değişiyor. Bazı insanlar kelime tekrarlamayı daha kolay bulur. Çünkü nefes gibi bir şeyi izlemek yerine bir şey yaparlar. Bazılarına da fazla mekanik gelir. Sana uygun olanı ararken iki tepki de olağandır."],visual:{kind:"compare",title:"Çaba mı, rahatlık mı?",left:{label:"Zorlamak",items:["Düşünceleri uzaklaştırmaya çalışmak","Artık gevşedim mi diye yoklamak","Dikkatim dağılınca kelimeyi daha hızlı tekrarlamak"]},right:{label:"Zorlamamak",items:["Düşüncelerin gelip geçmesine izin vermek","Uygulamayı iyi ya da kötü diye puanlamamak","Kelimeye aynı rahat hızla dönmek"]},note:"Harvard Health açıklamasında anlatılan Benson yöntemindeki pasif tutumun özeti."}},{heading:"Kelimeni seç",paragraphs:["Kısa, nefes verirken içinden kolayca söyleyebildiğin bir kelime seç. Sana hoş ya da nötr gelsin. İnancından bir dua ya da zikir sözü olabilir. “Sakin”, “burada” ya da “bir” gibi gündelik bir kelime de seçebilirsin. Benson yöntemi ikisiyle de aynı şekilde uygulanır.","En az bir hafta aynı kelimeyi kullanmayı dene. Her gün değiştirmek, uygulamayı kusursuz kelimeyi aramaya çevirebilir. Bu da kendini zorlamanın başka bir yoludur."]}],example:{title:"Mehmet, 58, emekli öğretmen",text:"Mehmet nefesini izlemenin kendisini huzursuz ettiğini fark etti. Öğleden sonra çayının ardından Benson yöntemini denedi. Çocukluğundan beri bildiği kısa bir zikir sözü seçti. Koltuğuna oturup kaslarını ayaklarından yüzüne doğru gevşetti. Her nefes verişinde sözü içinden tekrarladı. Torununun sınavıyla ilgili düşünceler aklına geliyordu. Her seferinde “Sorun değil” deyip aynı yavaş tempoyla söze döndü. On dakika sonra kalkmadan önce bir dakika daha sessizce oturdu. Büyük bir değişiklik hissetmedi. Ama on bir dakikadır telefonuna bakmamıştı; bu onun için yeniydi. Haftanın kalanında aynı sözü kullanıp aynı koltukta oturmaya karar verdi."},sources:[]},"meditation-4":{deeper:[{heading:"Gündelik hayatta",paragraphs:["Özel bir yola ihtiyacın yok. Yürüyüş meditasyonunu zaten yaptığın yürüyüşlerden birine ekleyebilirsin. Durağa giderken yolun son kısmı, iş yerindeki bir koridor ya da arabadan kapıya yürüyüş olabilir. Bir dakika boyunca adımlarını fark ederek yürümek bile bir uygulamadır.","Yavaş yürümeyi sakin ve güvenli bir yerde dene. Kalabalık sokakta normal hızında yürü. Ayaklarını ve yüzüne değen havayı hissederken çevreni dikkatle izle."],visual:{kind:"table",title:"Nerede, nasıl yürüyebilirsin?",columns:["Yer","Hız","Odak noktası"],rows:[["Evde koridor ya da oda","Çok yavaş","Her ayağın kalkışı, ilerleyişi, yere basışı"],["Park ya da sakin bir yol","Yavaş","Nefese uydurulmuş adımlar"],["İşe ya da durağa yürüyüş","Normal","Ayaklar ve çevrendeki sesler, gözler açık"]],note:"Plum Village rehberine dayanarak hazırladığımız öneriler. Trafikte, merdivenlerde ve kalabalıkta önce güvenlik gelir."}},{heading:"Hareket sırasında odaklanmak neden kolay gelebilir?",paragraphs:["Gözlerin kapalı otururken huzursuz, uykulu ya da tedirgin olabilirsin. Yürümek, dikkatini düşüncelerinin dışında somut bir şeye vermeni sağlar: ayak tabanının yere değdiği ana. Gözlerin açık kalır, bedenin de hareket eder.","Oturmak zor geldiğinde yürüyüş meditasyonunu deneyebilirsin. Dikkatini içe çevirmek seni rahatsız ediyorsa bu uygulama daha rahat bir başlangıç olabilir."]}],example:{title:"Ada, 27, hemşire",text:"Ada gece vardiyalarından sonra hareketsiz oturamayacak kadar gergindi. Hastanenin yanındaki küçük parkta yürüyüş meditasyonunu denedi. Yaklaşık on beş adımlık sakin bir patika seçti. Önce nefes alırken iki, verirken üç adım saydı. Rahat gelmeyince nefes verirken de iki adıma geçti. Aklı, zor geçen bir hasta devir teslimindeydi. Bunu her fark ettiğinde topuğunun çakıla değdiği ana dikkatini verdi. Son iki dakika saymayı bırakıp çevresini dinledi: fren yapan bir otobüs, serçeler, ağaçlardaki rüzgâr. Toplam yedi dakika sürdü. Eve yine yorgun döndü, ama tramvayda devir teslimi artık tekrar tekrar düşünmüyordu."},sources:[]},"meditation-5":{deeper:[{heading:"Araştırma ne diyor?",paragraphs:["Meta-analiz iki tür olumlu duyguyu inceledi. Coşku ve neşe gibi canlı duygularla hoşnutluk ve huzur gibi sakin duygulara baktı. Sevgi-şefkat meditasyonu yapanlarda, bekleme listesindeki gruplara göre her iki tür de benzer ve sınırlı miktarda arttı.","Sonuçlar umut verici, ama sınırlı. Çoğu çalışma meditasyonu hiçbir uygulama yapmamayla karşılaştırdı. Birçoğunda yanlılık riski yüksekti. Üstelik şefkat meditasyonu araştırmasına katılanlar zaten daha iyi hissedeceklerini bekliyor olabilir. Bulgular olumlu duygularda küçük ile orta düzey arasında bir artış gösteriyor. Kişiliğin değiştiği sonucunu vermiyor."],visual:{kind:"bars",title:"Sevgi-şefkat meditasyonu ve günlük olumlu duygular",bars:[{label:"Canlı olumlu duygular (coşku, neşe)",value:.395,display:"g = 0,395"},{label:"Sakin olumlu duygular (hoşnutluk, huzur)",value:.392,display:"g = 0,392"}],note:"Zeng ve ark. (2015): 1.759 kişinin katıldığı 24 çalışmanın meta-analizi. Değerler, rastgele gruplara ayrılan katılımcılarla yapılan çalışmalarda bekleme listesiyle karşılaştırmanın standartlaştırılmış etki büyüklükleridir. Çalışmaların %38,9’unda yanlılık riski yüksekti.",sourceId:"meditation-lovingkindness"}},{heading:"Sık yapılan hatalar",paragraphs:["İlk hata, sıcak bir duygu hissetmeye çalışmak. Cümleleri iyi niyetle tekrarlaman uygulama için yeterli. Duygu sonra ya da başka bir gün gelebilir. İkinci hata, en zorlandığın kişiyle başlamak. Önce haftalarca kendine, sevdiğin birine ve hakkında güçlü bir duygu beslemediğin birine iyi dileklerde bulunabilirsin.","Üçüncü hata, iyi dilekte bulunmayı boyun eğmekle karıştırmak. Birinin acısının sona ermesini dilemek, yaptıklarını mazur görmek, onunla barışmak ya da sınırlarından vazgeçmek değildir. Kendine iyi dilekte bulunmak canını acıtıyorsa sevdiğin biriyle başla. Kendine daha sonra dönebilirsin."]}],example:{title:"Zeynep, 38, grafik tasarımcı",text:"Zeynep sevgi-şefkat meditasyonunu fazla duygusal buluyordu. Yine de bir müşteriyle gergin geçen haftanın ardından denedi. E-postasını açmadan önce masasında içinden şöyle dedi: “Güvende olayım, huzurlu olayım, kendime nazik davranayım.” Tebrik kartı okuyormuş gibi geldi. Buna rağmen devam etti. Aynı dilekleri önce kız kardeşi, sonra adını bilmediği köşedeki bakkal için tekrarladı. Neredeyse hiçbir şey hissetmedi. Derse göre bu da olağandı. Zorlandığı müşteriyi atladı; hazır değildi. O gün müşteri yine sert bir mesaj gönderdi. Zeynep’in cevabı hâlâ netti, ama her zamankinden biraz daha az sertti. Bu küçük değişikliği fark edip ertesi sabah yeniden denemeye karar verdi."},sources:[]},"meditation-6":{deeper:[{heading:"Uygulanabilir adımlar ve desteklenmeyen iddialar",paragraphs:["Dispenza’nın meditasyonunda uygulanabilir adımlarla büyük iddialar bir arada. Bunları ayırmak yararlı olabilir. Uygulanabilir kısmın üç parçası var. Dikkat: alıştığın tepkiyi olup bittikten sonra değil, o sırada fark etmek. Prova: belirli bir sahnede yeni tepkini zihninde canlandırmak. Duygu: prova sırasında sakinlik ya da özgüven gibi bir duyguyu da hissetmek. Bu, provayı daha canlı ve akılda kalıcı kılar.","Bu adımlar, alışkanlıkları fark etme, zihinsel pratik ve planlama araştırmalarıyla uyumlu. Meditasyonun kuantum alanıyla gerçekliği değiştirdiği, genleri açıp kapattığı ya da hastalıkları düşünceyle iyileştirdiği iddialarının ise bilimsel desteği yok. İddiaları kabul etmeden uygulanabilir adımları deneyebilirsin. Bu iddialar yüzünden tedavini asla değiştirme."],visual:{kind:"compare",title:"Dispenza’nın meditasyonunda hangi adımları deneyebilirsin?",left:{label:"Uygulanabilir adımlar",items:["Alıştığın tepkiyi ve onu tetikleyen durumları fark etmek","Yeni bir tepkiyi belirli bir sahnede prova etmek","Prova sırasında yeni tepkiye eşlik eden duyguyu hissetmek","Sonrasında gerçek hayatta küçük bir adım atmak"]},right:{label:"Kanıtla desteklenmeyenler",items:["Kuantum alanı aracılığıyla gerçekliği değiştirmek","Düşünerek genleri açıp kapatmak","Tedavi yerine düşünceyle hastalığı iyileştirmek"]},note:"Kitaptaki anlatımla zihinsel pratik ve eğer-öyleyse planları araştırmalarına dayanan özetimiz."}},{heading:"Dispenza’nın yöntemini günlük hayata uyarlamak",paragraphs:["Kitapta meditasyon dört hafta boyunca aşama aşama ilerler. Önce dikkatini bedenine verirsin. Sonra eski hâlini tanıyıp kabul eder, bırakmayı denersin. Ne zaman devreye girdiğini fark eder ve olmak istediğin kişiyi zihninde prova edersin. Bu ders, yöntemi dokuz dakikalık tek bir uygulamaya indiriyor. Bu nedenle burada basitleştirilmiş biçimini deniyorsun.","Zihinsel pratik araştırmaları, provayı daha yararlı kılmanın bir yolunu gösteriyor: somut ve gerçekçi bir sahneyi canlandır, sonra uygula. “Yöneticim işimi eleştirirse durup nefes vereceğim ve bir soru soracağım” diye planlayabilirsin. Böyle bir eğer-öyleyse planı, provanı aynı gün deneyebileceğin bir davranışa bağlar."]}],example:{title:"Kerem, 42, satış müdürü",text:"Kerem raporlar geciktiğinde ekibine çıkışmayı bırakmak istiyordu. Dokuz dakikalık meditasyonda önce alıştığı tepkiyi ayrıntılı olarak canlandırdı: raporun gelişi, göğsündeki sıcaklık, kimsenin işi ciddiye almadığı düşüncesi, gönderdiği sert mesaj. Bu tepkisini açıkça kabul etti. Onu bırakmayı hayal etti. Sonra pazartesi toplantısını, olmak istediği yönetici gibi üç kez prova etti. Duruyor, nefes veriyor, raporun neden geciktiğini soruyordu. Canlandırırken sakinliği hissetmeyi denedi. Gözlerini açmadan önce bir plan yaptı: “Rapor gecikirse başka bir şey söylemeden bir soru soracağım.” Pazartesi bir rapor gecikti. Göğsündeki sıcaklığı hissetti, planını hatırladı ve soruyu sordu. Toplantı biraz daha iyi geçti."},sources:[]},"meditation-7":{deeper:[{heading:"Düzenini kur",paragraphs:["Düzenli uygulama için üç şey belirle: her gün zaten yaptığın bir şey, zor bir günde bile ayırabileceğin süre ve plan işlemezse kullanacağın yedek. Bir eğer-öyleyse planı bunları birbirine bağlayabilir: “Sabah çayımı koyduktan sonra on dakika meditasyon yapacağım.” Bu biçimdeki planlar, birçok araştırmada insanların niyetlerini uygulamasına yardımcı oldu.","İlk haftayı sade tut: tek teknik, tek zaman, tek yer. Haftanın sonunda neyin işe yaradığına bak. Her şeyi baştan kurmak yerine süreyi ya da tekniği değiştir."],visual:{kind:"steps",title:"Bir haftalık başlangıç düzeni",steps:[{label:"Bir hatırlatıcı seç",text:"Çay koymak ya da arabayı park etmek gibi her gün zaten yaptığın bir şey."},{label:"Bir teknik seç",text:"Nefes, beden taraması, kelime, yürüyüş, metta ya da prova."},{label:"Bir süre belirle",text:"Normal günlerde on dakika, en az üç dakika."},{label:"Bir yedek yaz",text:"“Oturamazsam üç dakika adımlarımı fark ederek yürüyeceğim.”"},{label:"Gözden geçir",text:"Yedi gün sonra neyin yardımcı olduğunu not et ve bir şeyi ayarla."}],note:"Aynı koşullarda tekrarlanan alışkanlıklarla eğer-öyleyse planları araştırmalarına dayanan şablonumuz."}},{heading:"Meditasyon zor duygular ortaya çıkardığında",paragraphs:["Sessizce meditasyon yaparken bazen zor duygular, anılar ya da bedensel hisler ortaya çıkar. Bu, yanlış yaptığın anlamına gelmez. Kendini zorlayıp sürdürmen de gerekmez. Travma alanında çalışan eğitmenler, içe odaklanmanın bazı kişilerde geçmişteki olayı yeniden yaşama hissini, duyguları düzenlemekte belirgin güçlüğü ya da kopukluk hissini tetikleyebileceğini belirtir. Özellikle travma geçmişi olanlarda bu yaşanabilir.","Uygulamayı değiştirmek yardımcı olabilir. Gözlerini açık tut, süreyi kısa tut. Sesler ya da ayaklarının yere teması gibi bir şeye odaklan. İhtiyaç duyduğunda dur. Travma geçmişin varsa eğitimli bir eğitmenle ya da bir terapistin desteğiyle çalışmak uygun olabilir. Bazı kişiler uygulamadan önce veya sonra birkaç kez yavaşça nefes alıp uzun süre vermenin sakinleşmelerine yardımcı olduğunu fark eder."]}],example:{title:"Elif, 35, öğretmen",text:"Elif beden taramasını seçti. İşten sonra arabasını park edince uygulamaya başladı. Dört gün iyi gitti. Beşinci gün taramanın ortasında göğsünde bir sıkışma hissetti. Bu his yıllar önceki acı bir anıyı getirdi; kendini sarsılmış hissetti. Dersteki öneriyi hatırladı. Gözlerini açtı, ayaklarını arabanın zeminine bastırdı. Dışarıdaki ağaçlara bakıp birkaç kez uzun nefes verdi. O gün uygulamayı bıraktı. Ertesi gün yazdığı yedek planı denedi: gözleri açık, üç dakikalık yürüyüş meditasyonu. Anı o hafta yeniden gelince terapistine anlattı. Terapisti şimdilik süreyi kısa tutmasını ve gözlerini açık bırakmasını önerdi. Elif, durmanın da uygulamanın parçası olduğunu fark etti."},sources:["meditation-trauma-sensitive"]}},wa=Object.freeze(Object.defineProperty({__proto__:null,EXTRAS:va,SOURCES:fa},Symbol.toStringTag,{value:"Module"})),za=[],Sa={"suggestion-1":{deeper:[{heading:"Beklenti gerçektir ve sınırları vardır",paragraphs:["Grafikteki etki hayalî değil. Güvendiğin biri bir işlemin daha az acıtacağını söylediğinde, gerçekten daha az ağrı hissedebilirsin. Beklenti, dikkatini nereye verdiğini, bedeninin ne kadar gerildiğini ve bir duyumu nasıl yorumladığını etkiler. Bu gerçek bir etkidir ve yararlı olabilir.","Yine de çalışmaların neyi ölçtüğüne dikkat et: ağrıyı, yani kişinin hissettiği ve bildirdiği bir deneyimi. Beklentinin tümörü küçülttüğünü, kan şekerini düşürdüğünü ya da enfeksiyonu iyileştirdiğini göstermiyorlar. Coué’nin bedensel hastalıkları iyileştirme iddiaları da desteklenmiyor. Telkin, zor bir anı nasıl yaşadığını ve sonrasında ne yaptığını etkileyebilir. Ama tıbbi bakımın yerini tutmaz."],visual:{kind:"compare",title:"Telkin nerede yardımcı olabilir, nerede olamaz",left:{label:"Etkileyebilir",items:["Zor bir andan önce ne kadar gergin hissettiğini","Ağrı gibi bir duyumun ne kadar güçlü hissedildiğini","Dikkatinin nereye gittiğini","Bir sonraki küçük adımın ne olduğunu"]},right:{label:"Yerine geçemez",items:["İlacın ya da tıbbi tedavinin","Bir belirtinin tanısının","Başkalarının kararlarının","Alıştırma ve hazırlığın"]},note:"Ağrı çalışmalarında telkinleri araştırmacılar ya da klinisyenler verdi. Kendi kendine telkin ayrıca sınanmadı."}},{heading:"Coué’nin fark ettiği döngü",paragraphs:["Coué hastalarında bir döngü fark etti: gergin olmamak için kendilerini ne kadar zorlarlarsa o kadar geriliyorlardı. Uyumaya ya da yüzünün kızarmasını engellemeye çalışırken benzerini yaşamış olabilirsin. Çabaladıkça dikkatin, kurtulmak istediğin şeye yönelir. Bu dikkat de onu güçlendirebilir.","Coué bunu bir yasa saydı. Oysa sık karşılaşılan bir durumu anlatan gözlem olarak düşünmek daha doğru. Kanıtlanmış bir kural değil. Yine de cümleni kendini zorlamadan, sakince söyleyip sonra bırakmanı neden önerdiğimizi açıklıyor."],visual:{kind:"cycle",title:"Zorlama döngüsü",center:"Çok fazla çaba",nodes:[{label:"Gerilme",text:"Kendine sertçe “Gergin olma” dersin."},{label:"Gözleme",text:"Gerginlik belirtilerini aramaya başlarsın."},{label:"Bulma",text:"Kalbinin hızlı atması ya da ağzının kuruması bütün dikkatini çeker."},{label:"Endişe",text:"Bu işaretleri, çabanın işe yaramadığının kanıtı gibi görürsün."},{label:"Daha çok zorlama",text:"Daha da çok zorlarsın ve döngü yeniden başlar."}],note:"Coué’nin gözlemi, bizim sözlerimizle yeniden anlatıldı; deneysel olarak kanıtlanmış bir yasa değildir."}}],example:{title:"Leyla, 34, diş hijyenisti",text:"Leyla pazartesi ekip toplantılarından önce kendine sertçe “Bu sefer telaşlanma” derdi. Konuşma sırası geldiğinde yüzü ısınır, sözlerini aceleyle söylerdi. Pazar günü dersi denedi. Kendini zorladığı cümleyi yazıp yanına daha yumuşak bir cümle ekledi: “Acele etmeden konuşabilirim.” Toplantıdan önce omuzlarını gevşetti, üç yavaş nefes aldı. Yeni cümleyi sessizce söylerken söze başlamadan önce durduğunu hayal etti. Yüzü yine biraz ısındı. Ama konuşurken bir kez durduğunu ve sözlerini sırayla söylediğini fark etti. Sonra telefonuna tek satır yazdı: “Çenemi daha az sıktım.” Büyük bir değişim olmadı, ama toplantı biraz daha rahat geçti."}},"suggestion-2":{deeper:[{heading:"Sade bir cümle neden yine de işe yarayabilir",paragraphs:["Bu cümle bilerek sade tutulmuş. Sakin bir ses ve birkaç dakika dışında senden bir şey istemiyor. Bu yüzden tekrarlaması kolay. Lally ve arkadaşlarının alışkanlık çalışmasında, aynı ortamda tekrarlanan davranışlar giderek daha az düşünerek yapılır hâle geldi. Bunun süresi kişiden kişiye çok değişti. Arada bir günü kaçırmak ise süreci bozmadı.","Cümleyi uyanmaya ve yatmaya bağlayarak küçük, düzenli bir alışkanlık oluşturabilirsin. Ruh hâlini nasıl etkilediğini sen gözlemleyeceksin; araştırma bunun için bir sonuç vaat etmiyor. Bazı insanlar sakinleştirici bulur. Bazıları başta tuhaf bulur, birkaç gece sonra alışır."],visual:{kind:"cycle",title:"Aynı ana bağlanmış bir ritüel",center:"Aynı zaman, aynı yer",nodes:[{label:"İpucu",text:"Uyanırsın ya da gece yatağa uzanırsın."},{label:"Rutin",text:"Düğümler ya da boncuklarla sayılan yirmi sakin tekrar."},{label:"An",text:"Güne başlamadan ya da uykuya dalmadan kısa bir sakinlik molası."},{label:"Tekrar",text:"Yarın aynı ipucu, başlamayı kolaylaştırır."}],note:"Aynı bağlamda tekrar, bir davranışı zamanla daha otomatik hâle getirir (Lally ve ark., 2010). Formülün kendi etkisi sınanmadı."}},{heading:"Sık yapılan hatalar",paragraphs:["İnsanlar bu cümleyi bir sınav gibi görürse uygulama zorlaşabilir. Yüksek sesle söyler, her tekrardan sonra bir şey değişti mi diye kontrol eder ya da dikkati dağılınca kendine kızar. Coué bunların her birinin tersini önerdi."],visual:{kind:"table",title:"Sık yapılan hatalar ve daha nazik alternatifler",columns:["Hata","Daha nazik alternatif"],rows:[["Yüksek sesle ve zorlayarak söylemek","Alçak, aynı tonda bir ses, neredeyse mırıltı"],["Her tekrarda bir şey değişti mi diye bakmak","Sayımı düğümlere bırak; bir hafta sonra gözden geçir"],["Zihni dağılınca kendini azarlamak","Fark et ve cümleye geri dön"],["Hekime gitmek yerine kullanmak","İhtiyaç duyduğun tıbbi bakımın yanında uygula"]]}}],example:{title:"Sami, 42, otobüs şoförü",text:"Sami erken vardiya günlerinde sabah 4.30’da uyanıyor, hemen trafiği düşünmeye başlıyordu. Tespih çeken kız kardeşi ona yirmi boncuklu kısa bir tespih ödünç verdi. Salı gecesi yatağa uzandı. Cümleyi yirmi kez mırıldanırken her sefer bir boncuk ilerletti. İki kez sayıyı karıştırdı, ama devam etti. Çarşamba sabahı yataktan kalkmadan yine denedi. Yaklaşık iki dakika sürdü. Büyük bir değişim hissetmedi. Ama aklına ilk gelen şey çevre yolu yerine sakin bir cümleydi. Yapışkan bir nota “Güne daha az telaşla başlamak” yazdı. Cuma bunu düşünmeden yapıyordu. Cumartesi ise tamamen unuttu ve bunu sorun etmemeye karar verdi."}},"suggestion-3":{deeper:[{heading:"İnanmadığın bir cümle neden ters tepebilir?",paragraphs:["Popüler öğütlerde sık sık, olumlu cümleyi inanana kadar tekrarlaman söylenir. Wood’un deneyleri bunun bir sınırı olabileceğini gösteriyor. Kendileri hakkında zaten iyi hissedenlere cümle uydu ve biraz iyi geldi. Böyle hissetmeyenlerde ise her tekrar, içten gelen bir “Bu doğru değil” itirazını uyandırmış gibiydi. Cümleyle kişinin kendini nasıl gördüğü arasındaki fark daha belirgin oldu.","Bu tek bir cümleydi ve öğrencilerle birkaç dakika boyunca denendi; yani tüm olumlamaların zararlı olduğunu göstermez. Ama basit bir kontrol öneriyor: bir cümle seni rahatsız ediyorsa, inanabileceğin kadar ölçülü hâle getir."],visual:{kind:"cycle",title:"İnanmadığın bir cümle nasıl ters tepebilir",center:"Aradaki fark",nodes:[{label:"İddialı cümle",text:"“Kendime tamamen güveniyorum.”"},{label:"İç itiraz",text:"İçinden “Bu doğru değil” diye geçirirsin."},{label:"Karşı kanıt",text:"Tersine dair anılar akla gelir."},{label:"Daha kötü ruh hâli",text:"Cümleyle kendin hakkındaki düşüncen arasındaki fark daha büyük gelir."}],note:"Araştırmacıların sunduğu olası bir açıklama; adım adım ölçtükleri bir şey değil. Etki, özsaygısı düşük kişilerde görüldü."}},{heading:"Değerler üzerine araştırma ne diyor",paragraphs:["Öz-onaylama, kendin hakkında güzel şeyler söylemekten farklıdır. Sende olmadığını düşündüğün bir özelliğe sahip olduğunu iddia etmezsin. Aile, dürüstlük ya da inanç gibi önemsediğin bir değer üzerine yazarsın. Neden önemli olduğunu anlatırsın. Amaç, eleştiri ya da korkutan bir sağlık mesajıyla karşılaştığında kendini yalnızca o tehditle tanımlamamak. Böylece kendine daha geniş açıdan bakabilirsin.","Etkiler küçük. Birçok deneyde, değerleri üzerine yazan kişiler sağlık mesajlarına biraz daha açık oldu. Sonrasında davranışlarını değiştirme olasılıkları da arttı; bu etki biraz daha belirgindi. Zamanlama önemliydi. Okullardaki bazı büyük denemelerde önceki sonuçlar tekrarlanmadı."],visual:{kind:"bars",title:"Öz-onaylama ve sağlık davranışı",bars:[{label:"Mesajı kabul etme (34 test)",value:.17,display:"d = 0,17"},{label:"Değişim niyeti (64 test)",value:.14,display:"d = 0,14"},{label:"Sonraki davranış (46 test)",value:.32,display:"d = 0,32"}],note:"Epton ve ark. (2015), 144 deneysel test. Küçük etkiler, çoğunlukla bir sağlık mesajıyla birlikte ölçüldü; tek başına değer yazısı ve bu kurs sınanmadı.",sourceId:"self-affirmation-health"}}],example:{title:"Pınar, 27, genç muhasebeci",text:"Pınar aynasına “İşimde harikayım” yazan bir not yapıştırmıştı. Her sabah okuduğunda içi biraz burkuluyordu. Çünkü geçen hafta bir raporda hata yapmıştı. Perşembe günü cümleye ne kadar inandığını puanladı: on üzerinden üç. Notu değiştirdi: “Bu işi öğreniyorum ve işimi kontrol ediyorum.” Yeni cümleye yedi puan verdi. En çok önemsediği değer olan dürüstlük üzerine de on dakika yazdı. Yakın zamanda yöneticisine bir hatasını açıkça anlattığı anı düşündü. Ertesi sabah yeni not ona kendini harika hissettirmedi. Ama artık içini burkmuyordu. Bir değerlendirme toplantısından önce dürüstlük üzerine yazısını yeniden okudu. Toplantıya kendinden biraz daha emin girdi."}},"suggestion-4":{deeper:[{heading:"Adını kullanmak neden mesafe sağlar?",paragraphs:["“Ben” diyerek düşündüğünde durumu içeriden yaşarsın. Duyumların ve korkuların sana çok yakındır. Adını kullandığında ise başkasına seslenirken kullandığın dili kullanırsın. Bir arkadaşının sorununa çoğu zaman daha geniş açıdan bakabiliriz. Kendi adını kullanmak, kendine de bu açıdan bakmanın kısa bir yoludur.","Kross bunu ve ilişkili birkaç aracı Chatter kitabında anlatıyor: olayı bir yıl sonra nasıl göreceğini hayal etmek, onun hakkında yazmak ya da güvendiğin biriyle konuşmak. Hepsinde, olaydan bir adım geri çekilip bakarsın. Farklı anlarda farklı yöntemler işe yarayabilir."],visual:{kind:"steps",title:"İki dakika ayırıp dışarıdan bak",steps:[{label:"Ad",text:"Kendine seslen: “Ali, şu an neler oluyor?”"},{label:"Betimle",text:"Olanı “ben” değil “sen” diyerek söyle."},{label:"Öğüt ver",text:"Aynı durumdaki bir arkadaşına ne söylerdin, onu söyle."},{label:"Uzaklaş",text:"Bunun bir yıl sonra sana nasıl görüneceğini sor."},{label:"Sonraki adım",text:"Bir sonraki dakika için tek bir somut eylemle bitir."}],note:"Ethan Kross’un araçlarından uyarlandı. Laboratuvar çalışmaları ad ya da “sen” kullanmayı sınadı; diğer adımlar birlikte sınanmadı."}},{heading:"Sert değil, şefkatli",paragraphs:["Kendine dışarıdan bakarken şefkatli olmak da yardımcı olur. “Ali, aptalın tekisin” demek adını içerir, ama kendini eleştirmeyi sürdürürsün. Onlarca denemeyi inceleyen bir derlemede, öz şefkat uygulamaları kısa vadede stresi ve kaygıyı küçük ile orta düzeyde azalttı. Öz şefkat, kendine bir arkadaşına göstereceğin nezaketle davranmaktır. Yine de denemelerin çoğunda zayıf yönler vardı.","Basit bir kontrol yapabilirsin: bu cümleyi, bu tonla, sevdiğin birine söyler miydin? Söylemezsen, sözcükleri değiştirmeden önce tonu değiştir."]}],example:{title:"Metin, 38, hemşire",text:"Metin, gözünü korkutan yeni sorumlu hemşireye kısa bir devir teslim yapacaktı. Servise yürürken aklından şu geçiyordu: “Bunu berbat edeceğim. Hep bir şeyi unutuyorum.” Malzeme odasında iki dakika durup dersi fısıltıyla denedi: “Metin, bunu doğru yapmak istediğin için gerginsin. Yüz kez devir teslim yaptın.” Sonra genç bir meslektaşına ne söyleyeceğini düşündü: “En ağır hastayla başla, sırayla git.” Bunu kendine de söyledi. Devir teslim kusursuz değildi. Bir tahlil sonucunu unutup sonunda ekledi. Genellikle sonrasında bir saat boyunca olanları tekrar tekrar düşünürdü. Bu kez böyle yapmadığını fark etti."}},"suggestion-5":{deeper:[{heading:"Yönlendirici mi, motive edici mi?",paragraphs:["İkisinin de yeri var. Yönlendirici ipuçları dikkatini tek bir ayrıntıya çeker. İş yeni ya da hassas olduğunda, dikkatin dağıldığında veya gerildiğinde işe yarayabilir. Motive edici ipuçlarıysa çabanı sürdürmene daha çok yardımcı olur. Koşunun son kısmında ya da öğleden sonra onuncu e-postanı yazarken bunları deneyebilirsin.","Şöyle seçebilirsin: işi öğreniyorsan ya da dikkatle yapman gerekiyorsa kısa bir talimat kullan. Ne yapacağını biliyor ama isteğin azalıyorsa cesaret veren bir cümle seç. Her iki durumda da ipucun tek nefeste söyleyebileceğin kadar kısa olsun."],visual:{kind:"table",title:"Gündelik işler için ipucu kelimeleri",columns:["İş","Yönlendirici ipucu","Motive edici ipucu"],rows:[["Rapor yazmak","Önce taslak","Devam et"],["Toplantıda konuşmak","Yavaş ve net","Hazırsın"],["Araba kullanmayı öğrenmek","Ayna, sinyal","Sakin"],["Yeni bir yemek tarifi denemek","Tadına bak","Keyfini çıkar"]],note:"Bunlar yalnızca örnek. Spor ve hareket gerektiren görevleri kapsayan meta-analizde sınanmadılar."}},{heading:"Gallwey bunu nasıl yapıyor",paragraphs:["Tenis antrenörü Tim Gallwey, oyuncuların kendilerine uzun uzun öğüt verdiklerinde çoğu zaman daha kötü oynadığını fark etti. Yargılayan sese Benlik 1, öğrenen bedene Benlik 2 adını verdi. Daha fazla talimat yerine dikkati basit bir şeye yöneltmeyi önerdi: top yere değdiğinde “sekme”, raketle buluştuğunda “vuruş” demek. Sonra olanı iyi ya da kötü diye yargılamadan izlemek.","Araştırmalar Gallwey’nin yöntemini tek başına sınamadı. Ama yöntem, meta-analizde dikkati yönlendiren kısa ipuçlarına ilişkin bulgularla uyumlu. Hatalara da kendini azarlamadan bakmanı sağlar. Kendin hakkında bir yargıya varmak yerine bir dahaki sefere dikkat edeceğin tek bir şey seçersin."],visual:{kind:"compare",title:"Benlik 1 mi, basit bir ipucu mu?",left:{label:"Yargılayan ses (Benlik 1)",items:["“Bu berbattı.”","Aynı anda yapılacak beş düzeltme listesi","Gerginlik ve fazla düşünme"]},right:{label:"Basit ipucu",items:["Tek bir ana bağlanmış tek bir kelime","Olanı izlemek","Bir dahaki sefere fark edilecek tek şey"]},note:"Gallwey’nin anlatımı, bizim sözlerimizle. Yöntemin kendisi meta-analizlerde ayrıca sınanmadı."}},{heading:"İpucunu ihtiyaç duymadan önce dene",paragraphs:["Meta-analizde en açık sonuçlardan biri şuydu: iç konuşmayı önceden deneyen programlar, denemeyenlerden daha iyi işledi. İhtiyaç duyduğunda ipucu zaten tanıdıksa kullanman kolaylaşır. Önce kolay bir işte dene, sonra zorlandığın yerde kullan."]}],example:{title:"Aylin, 45, okul idari görevlisi",text:"Aylin işte yeni bir elektronik tablo sistemini öğreniyordu. Veri girerken küçük hatalar yapıyor, sonra kendini azarlıyordu. İki ipucu seçti: dikkatini yönlendirmek için “Sütunu kontrol et”, devam etmek için “Her seferinde bir satır”. Pazartesi gerçek işe başlamadan önce on kolay satırla denedi. Her yazışında önce “Sütunu kontrol et” dedi. Sonra asıl işe geçti. Elli satırda yine iki hata yaptı. Bu, her zamankinden azdı. Hataları görünce kendine dikkatsiz demedi. Defterine yalnızca “Tarihlere dikkat” yazdı. Çarşamba bunu yeni ipucu olarak ekledi. Küçük bir değişiklikti, ama öğleden sonra kendini sınavdaymış gibi daha az hissetti."}},"suggestion-6":{deeper:[{heading:"Uyku ne yapar, ne yapmaz",paragraphs:["Uyurken belleğin çalışmaya devam eder. Paller ve arkadaşlarının derlemesine göre, gün içinde oluşan anılar gece yeniden etkinleşir ve pekişir. Bu, sorun çözmeye ve duyguları düzenlemeye yardımcı olabilir. Yatmadan önceki kısa, sakin bir prova da gün içinde alıştırdığın son şeylerden biri olabilir.","Uyku sırasında gerçekten yeni bilgi öğrenmek, çok basit öğrenme türleriyle sınırlıdır. Derlemede, endişeleri tekrar tekrar düşünmenin zararlı olabileceği de belirtiliyor. Murphy’nin kitabında bilinçaltı, verilen her isteği yerine getiriyormuş gibi anlatılır. Araştırmalarda desteklenen ise alıştırmayla değişen alışkanlıklar, dikkat ve bellektir."],visual:{kind:"compare",title:"Uyku ve telkin: kanıtlarla uyumlu olanlar",left:{label:"Kanıtlarla uyumlu",items:["Yatmadan önce ilk adımı prova etmek","Kısa bir cümleyi sakince tekrarlamak","Gündüz alıştırdıklarının uykuda pekişmesi"]},right:{label:"Desteklenmiyor",items:["Bilinçaltının para ya da sağlık getirmesi","Uykuda karmaşık yeni beceriler öğrenmek","Düşüncenin hastalığı iyileştirmesi"]},note:"Uyku öncesi telkini doğrudan sınamayan Paller, Creery ve Schechtman (2021) derlemesine dayanır."}},{heading:"Engeli neden plana eklemelisin?",paragraphs:["Hoş bir hayal kurmak ilerleme gibi gelebilir. Kappes ve Oettingen’in deneylerinde, kusursuz bir geleceği hayal edenlerin sonrasında enerjisi daha düşüktü. Bir çalışmada sonraki hafta daha az iş yaptılar. Zihin, hedefe zaten ulaşılmış gibi rahatlıyor olabilir.","Çözüm hayal etmeyi bırakmak değil, iki adım eklemek. Sonucu gördükten sonra, sana engel olabilecek temel düşünce veya duyguyu belirle ve onu bir eğer-öyleyse planına bağla. 21 çalışmada bu birleşim, hedeflere ulaşmada küçük–orta bir ortalama etki gösterdi."],visual:{kind:"steps",title:"Akşam sahnesinden sabah planına",steps:[{label:"Dilek",text:"Uykun gelirken yavaşça tekrarlanan kısa bir cümle."},{label:"Sahne",text:"Bir arkadaşının seni tebrik etmesi gibi sonucun kısa bir görüntüsü."},{label:"Engel",text:"Sabah: hangi düşünce veya duygu sana engel olabilir?"},{label:"Plan",text:"“Eğer … olursa, … yapacağım.”"}],note:"İstenen geleceği engel ve bir eğer-öyleyse planıyla eşleştirmek, 21 çalışmada g = 0,336’lık bir ortalama etki gösterdi (Wang, Wang & Gai, 2021)."}},{heading:"Zihnin endişeye kayarsa",paragraphs:["Bazı geceler cümle, ters gidebilecek her şeyin listesine kayar. Bu, tekniğin başarısız olduğu anlamına gelmez. Sahneyi bırak, gerekirse endişeyi yatağın yanındaki bir not defterine yaz ve yavaş nefese dön. Uyku, alıştırmadan daha önemli. Endişe çoğu gece seni uyanık tutuyorsa, bir hekimle konuşabilirsin."]}],example:{title:"Tuna, 33, genç mimar",text:"Tuna’nın cuma günü bir tasarım değerlendirmesi vardı ve geceleri felaket senaryolarını prova edip duruyordu. Çarşamba günü dersi denedi. Dileğini “Değerlendirme sorunsuz geçti” cümlesine indirdi ve bir karta yazdı. Yatakta, uykusu gelirken bunu yavaşça tekrarladı ve meslektaşı İnci’nin “Vaziyet planında iyi iş çıkarmışsın” dediğini canlandırdı. Sahne bitmeden uyudu. Perşembe sabahı gerçek engeli yazdı: “Biri bana soru sorunca acele ediyorum.” Ve planı: “Biri bir ayrıntıya itiraz ederse durup soruyu tekrarlayacak ve bildiğim kısmı cevaplayacağım.” Cuma günü ortaklardan biri otopark yerleşimine gerçekten itiraz etti. Tuna biraz beceriksizce duraksadı ve cevap verdi. Değerlendirme kusursuz değildi, ama prova ettiği felaket de değildi."}},"suggestion-7":{deeper:[{heading:"Kartın parçaları birlikte nasıl çalışır?",paragraphs:["Kartın her parçasının ayrı bir görevi var. Cümle, kendine nasıl seslendiğini belirler. Görüntü ilk adımını gösterir. Plan, zorlandığın an için ne yapacağını hatırlatır. Belirlediğin saat de uygulamayı alışkanlık hâline getirmene yardım eder. Bunları bir hafta boyunca birlikte deneyip sonra ihtiyacına göre ayarlayabilirsin.","Araştırmalar bu döngünün her parçasını aynı ölçüde desteklemiyor. En açık destek, eğer-öyleyse planlarıyla ilerlemeyi izlemeye ait. Zihinsel provanın etkisi küçük. Cümle ise çoğunlukla kendi önüne engel koymanı azaltarak yardımcı oluyor."],visual:{kind:"cycle",title:"Haftalık bir döngü olarak telkin kartı",center:"Kartın",nodes:[{label:"Cümle",text:"İnanabileceğin, belki adınla başlayan bir cümle."},{label:"Görüntü",text:"İlk adımının kısa bir sahnesi."},{label:"Plan",text:"Engel çıkarsa ne yapacağını bilirsin."},{label:"Eylem",text:"O gün gerçekten attığın küçük adım."},{label:"Gözden geçirme",text:"7 gün sonra: tut, değiştir ya da küçült."}],note:"Döngü önceki derslerdeki araçları birleştirir; kartın bütünü tek bir yöntem olarak sınanmadı."}},{heading:"Ayna çalışması, nazikçe",paragraphs:["Louise Hay ayna çalışmasını yaygınlaştırdı. Aynada kendine bakıp nazik bir cümle söylersin. Bazı insanlar duygulanır, bazıları ise bunu dayanılmaz bulur. Her iki tepki de olağandır. Kimlere yardımcı olduğunu gösteren kontrollü bir araştırma yok.","Wood’un deneylerini düşünerek aynayı zorunlu bir görev yerine bir deneme olarak kullan. Kendi gözlerine bakınca cümle daha inandırıcı geliyorsa devam et. İçinden daha güçlü bir “Hayır” geliyorsa kâğıttan oku ya da önce cümleyi yumuşat."]},{heading:"Suçlamadan gözden geçirmek",paragraphs:["Gözden geçirme, uygulamayı kendine göre ayarlamana yardım eder. İnsanların ilerlemelerini daha sık kontrol etmesini sağlayan çalışmalarda, hedeflere ulaşmada ortalama olarak orta düzeyde yarar görüldü. İlerlemeyi kâğıda ya da ekrana kaydetmek, yalnızca akılda tutmaktan daha çok yardımcı oldu. Yanıtlarını kısa da olsa yaz."],visual:{kind:"table",title:"7 günlük gözden geçirme için sorular",columns:["Soru","Evetse","Hayırsa"],rows:[["Kartı günlerin çoğunda okudum mu?","Saati olduğu gibi tut","Diş fırçalamak gibi daha sağlam bir ipucuna bağla"],["Cümleye inandım mı?","Tut","Daha küçük ve süreç odaklı yap"],["Engel geldiğinde plan devreye girdi mi?","Planı tut","“Eğer” kısmını daha belirgin yap"]],note:"İlerlemeyi izlemek, Harkin ve ark. (2016) çalışmasında ortalama olarak hedefe ulaşmayı destekledi (d = 0,40); bu belirli sorular sınanmadı."}}],example:{title:"Hande, 51, eczane teknisyeni",text:"Hande akşamları yürümek istiyor, ama kendini hep kanepede buluyordu. Küçük bir kartın önüne “Hande, on dakika yapabilirsin” yazdı. Altına kapının yanında ayakkabılarını bağladığı sahneyi ekledi. Arkasına bir plan yazdı: “Akşam yemeğinden sonra oturursam karar vermeden önce kalkıp ayakkabılarımı giyeceğim.” Kartı saat akşam 7’de, sofrayı topladıktan sonra okuyacaktı. Bir kez aynada denedi, kendini aptal gibi hissetti. Bu yüzden kartı eline alıp okumayı seçti. Yedi günde dört kez yürüdü. İkisinde yalnızca on dakika yürüdü. Gözden geçirirken cümleyi korudu. Hayal ettiği sahneyi, yemekten önce ayakkabılarını hazırlamak olarak değiştirdi. Okuma saatini de erkene aldı. Yedi günde dört kez yürümek, hiç yürümemekten iyiydi."}}},Ba=Object.freeze(Object.defineProperty({__proto__:null,EXTRAS:Sa,SOURCES:za},Symbol.toStringTag,{value:"Module"})),f=[Le,Je,Qe,ea,na,la,da,ma,ca,pa,wa,Ba],Ta=Object.assign({},...f.map(e=>e.EXTRAS)),xa=f.flatMap(e=>e.SOURCES),Aa=[{id:"procrastination-interventions",title:"van Eerde & Klingsieck · 2018 · Erteleme müdahaleleri meta-analizi",url:"https://www.sciencedirect.com/science/article/abs/pii/S1747938X18300472",type:"research",finding:"24 çalışmayı (N=1.173) birleştiren meta-analizde müdahalelerden sonra ertelemede büyük bir azalma görüldü (öncesi–sonrası ortalama etki −1,07), azalma izleme ölçümlerinde de sürdü ve en güçlü sonuç bilişsel davranışçı terapiden geldi.",limitation:"Değer kontrol grubuyla değil öncesi–sonrası farkla hesaplandığı için etki olduğundan büyük görünebilir; yalnızca yayın özeti incelendi ve bu ODA kursunun etkililiği sınanmadı."},{id:"task-aversiveness",title:"Steel · 2007 · Ertelemenin nedenleri meta-analizi",url:"https://studypedia.au.dk/fileadmin/www.studiemetro.au.dk/Procrastination_2.pdf",type:"research",finding:"691 korelasyona dayanan meta-analizde erteleme; görevin itici gelmesiyle (r=0,40), düşük öz denetimle (r=−0,58) ve düşük öz yeterlikle (r=−0,38) ilişkiliydi, çalışma niyetiyle ise neredeyse hiç ilişkili değildi (r=0,03).",limitation:"Bulgular korelasyoneldir ve neden-sonuç göstermez; okunan PDF’te eksi işaretleri kaybolduğu için ilişkilerin yönü metindeki ifadelerden çıkarıldı."},{id:"mood-repair",title:"Sirois & Pychyl · 2013 · Erteleme ve ruh hâli onarımı",url:"https://eprints.whiterose.ac.uk/91793/1/Compass%20Paper%20revision%20FINAL.pdf",type:"research",finding:"Bu kuramsal derleme ertelemeyi, itici bir görevin yarattığı kötü hissi o an hafifletme çabası olarak açıklar ve bedelin gelecekteki benliğe kaldığını savunur; aktarılan küçük bir analizde erteleme düşük öz şefkatle ilişkili bulunmuştur (r=−0,31).",limitation:"Yeni veri içermeyen bir anlatı derlemesidir ve r=−0,31 değeri o sırada henüz yayımlanmamış bir çalışmadan aktarılır; kabul edilmiş yazar sürümü okundu."},{id:"self-forgiveness",title:"Wohl, Pychyl & Bennett · 2010 · Kendini affetme ve erteleme",url:"https://www.sciencedirect.com/science/article/abs/pii/S0191886910000474",type:"research",finding:"İki ara sınav boyunca izlenen 119 birinci sınıf öğrencisinde, ilk sınav için ertelediği için kendini daha çok affedenler ikinci sınava daha az erteleyerek hazırlandı ve bu ilişkiyi olumsuz duygudaki azalma açıklıyordu.",limitation:"Çalışma deneysel değil korelasyoneldir, tek bir ders ve öğrenci grubunda yürütüldü ve ilk ölçüme katılan 312 kişiden analize yalnızca 119’u kaldı."},{id:"mcii-procrastination",title:"Zhou ve ark. · 2026 · WOOP (MCII) ile erteleme deneyi",url:"https://www.sciencedirect.com/science/article/pii/S0001691825014829",type:"research",finding:"81 üniversite öğrencisiyle yapılan randomize çalışmada WOOP (dilek, sonuç, engel, plan) uygulayan grup görevleri daha az itici buldu ve günlerin %58,8’inde göreve başladı; yalnızca olumlu düşünen kontrol grubunda bu oran %47,3’tü.",limitation:"Tek bir üniversitede, bir haftalık izlemle ve ön kayıt olmadan yürütülen küçük bir çalışmadır (kayıp oranı %19,8); bu ODA kursunun etkililiği sınanmadı."},{id:"if-then-plans",title:"Gollwitzer & Sheeran · 2006 · Eğer/o zaman planları meta-analizi",url:"https://www.sciencedirect.com/science/chapter/bookseries/abs/pii/S0065260106380021",type:"research",finding:"94 bağımsız testte, ne zaman, nerede ve nasıl sorularını önceden yanıtlayan “Eğer … olursa, … yapacağım” planları hedefe ulaşmada orta–büyük olumlu bir etki gösterdi (d=0,65).",limitation:"Yalnızca yayın özeti incelendi, yayın yanlılığını düzelten daha yeni analizlere bakılmadığı için gerçek etki daha küçük olabilir ve çalışma ertelemeye özgü değildir."}],Ia={id:"procrastination",title:"Erteleme",subtitle:"Tembellik değil, bir his.",description:"Ertelemenin ardındaki hissi fark et, işi küçült, gerçek engeline bir plan bağla ve erteledikten sonra kendine yüklenmeden geri dön.",scope:"Gündelik erteleme için beceri eğitimi; terapi değildir. Erteleme yoğun kaygı, uzun süren çökkünlük veya dikkat güçlükleriyle birlikte sürüyor ve hayatını belirgin biçimde etkiliyorsa bir uzmandan destek alabilirsin.",outcome:"Küçültülmüş bir görev, eğer/o zaman planı ve erteledikten sonra geri dönüş cümlesi.",lessons:[{id:"procrastination-1",title:"Ertelemenin ardındaki his",minutes:7,goal:"Ertelediğin bir işin sende uyandırdığı hissi adlandır.",reading:["Ertelemek çoğu zaman tembellik değildir. Büyük bir derlemede erteleyen kişilerin çalışma niyeti başkalarından düşük çıkmadı; zorlandıkları yer, niyeti eyleme dökmekti. Aynı derlemeye göre üniversite öğrencilerinin %80–95’i bir ölçüde erteliyor. Bunu yaşayan tek kişi sen değilsin.","Görev sıkıcı, belirsiz veya kaygı verici geldikçe erteleme artma eğiliminde. Bir açıklamaya göre ertelediğimizde kaçtığımız şey işin kendisi değil, işin bizde uyandırdığı his: o an rahatlarız, bedelini sonraki hâlimiz öder. Bugün bu hissi yargılamadan fark etmeye çalışacağız."],practice:["Bir süredir ertelediğin tek bir işi seç.","İşi düşündüğünde ne hissettiğini bir iki kelimeyle adlandır: sıkıntı, kaygı, belirsizlik veya başka bir şey.","Bu hissi işin hangi kısmının uyandırdığını düşün; çözmeye çalışmadan yalnızca not et."],reflection:"Ertelediğin işte seni asıl zorlayan his ne?",question:"Bu derse göre ertelemeyi hangisi daha iyi açıklar?",options:["Erteleyenler aslında çalışmak istemez.","Görevin uyandırdığı hoş olmayan histen o an uzaklaşmak.","Ertelemek hiç değişmeyen bir karakter özelliğidir."],correct:1,feedback:"Görevin itici gelmesi ertelemeyle ilişkili bulundu; niyet eksikliği ise neredeyse hiç ilişkili çıkmadı. Bunlar neden-sonuç kanıtı değildir ama kendine bakışını yumuşatabilir.",takeaway:"Ertelediğin şey çoğu zaman bir histir; tembelliğinin kanıtı değil.",sources:["task-aversiveness","mood-repair"],visual:{kind:"bars",title:"Ertelemeyle ilişki gücü",sourceId:"task-aversiveness",bars:[{label:"Öz denetim (ters yönde)",value:.58,display:"r = −0,58"},{label:"Görevin itici gelmesi",value:.4,display:"r = 0,40"},{label:"Öz yeterlik (ters yönde)",value:.38,display:"r = −0,38"},{label:"Çalışma niyeti",value:.03,display:"r = 0,03"}],note:"Çubuklar ertelemeyle ilişkinin gücünü gösterir; eksi işaret, öz denetim veya öz yeterlik azaldıkça ertelemenin arttığı anlamına gelir. Bunlar korelasyondur, neden-sonuç göstermez."}},{id:"procrastination-2",title:"İşi küçült, ilk hareketi bul",minutes:6,goal:"Ertelediğin işi, ağır gelmeyecek kadar küçük ve somut bir ilk harekete çevir.",reading:["“Sunumu hazırla” veya “evi topla” nereden başlayacağını söylemez. Belirsizlik, işi olduğundan daha ağır hissettirebilir. “Belgeyi aç ve üç başlık yaz” ise gözünle görebileceğin bir başlangıçtır. Küçük olması önemsiz olduğu anlamına gelmez.","“Bunu yapabilirim” duygusu ertelemeyle ters yönde ilişkili bulundu. Küçük ve başarılabilir ilk adımların bu duyguyu besleyebileceğini düşünüyoruz; bu bir çıkarım, doğrudan bir bulgu değil. İlk hareketi yaptıktan sonra devam etmek zorunda değilsin; durmak da bir seçenek."],practice:["Önceki derste seçtiğin işi tek cümleyle yaz veya söyle.","İşi üç küçük parçaya böl; ilkine aç, yaz, ara veya seç gibi açık bir fiille başla.","İlk parça hâlâ ağır geliyorsa onu iki dakikalık bir sürüme küçült ve şimdi dene."],reflection:"İşinin en küçük ilk hareketi ne oldu?",question:"Hangisi somut bir ilk hareket?",options:["Bu hafta daha disiplinli olmak.","Projeyi bir an önce halletmek.","Rapor dosyasını açıp ilk başlığı yazmak."],correct:2,feedback:"Somut bir fiil ve nesne, başlayacağın yeri gösterir. Büyük işi tek seferde çözmen gerekmiyor.",takeaway:"Başlamak için işin tamamını değil, ilk hareketini görmen yeter.",sources:["task-aversiveness"],visual:{kind:"steps",title:"Büyük işten ilk harekete",steps:[{label:"Büyük iş",text:"Sunumu hazırla."},{label:"Parçalar",text:"Konu seç, kaynak bul, slaytları yaz."},{label:"İlk parça",text:"Sunumun konusunu seç."},{label:"İlk hareket",text:"Boş bir belge aç, üç konu adayı yaz."}],note:"İlk hareket hâlâ ağır geliyorsa bir basamak daha küçült."}},{id:"procrastination-3",title:"Gerçek engeline bir plan bağla",minutes:8,goal:"Dilek, engel ve eğer/o zaman planını ertelediğin işe uygula.",reading:["Yalnızca olumlu hayal kurmak başlamaya yetmeyebilir. WOOP adlı yöntemde önce ne istediğini ve bunun sana ne kazandıracağını düşünürsün, sonra seni içeriden durduran gerçek engele bakarsın. Son adımda engele bir yanıt bağlarsın: “Eğer … olursa, o zaman … yapacağım.”","81 öğrenciyle yapılan küçük bir deneyde WOOP uygulayanlar görevleri daha az itici buldu ve günlerin daha büyük bir kısmında işe başladı. Bu, tek üniversitede bir hafta süren bir çalışma; kesin bir sonuç değil. Yine de denemesi kolay ve maliyeti düşük bir yöntem."],practice:["Dilek ve sonuç: ertelediğin işle ilgili bu hafta ne istediğini ve olursa sana ne kazandıracağını düşün.","Engel: seni en çok durduran içsel engeli adlandır; örneğin “telefonu elime almak” veya “yetersiz hissetmek”.","Plan: “Eğer [engel] olursa, o zaman [küçük davranış] yapacağım” cümlesini tamamla ve bir kez zihninde prova et."],reflection:"Senin eğer/o zaman cümlen ne?",question:"WOOP’u yalnızca olumlu düşünmekten ayıran nedir?",options:["Gerçek engeli görüp ona somut bir yanıt bağlamak.","Başarıyı olabildiğince canlı hayal etmek.","Engelleri hiç düşünmemeye çalışmak."],correct:0,feedback:"Bu yaklaşımda engel görmezden gelinmez; plana dönüştürülür. Araştırmalardaki etkiler ortalama sonuçlardır ve kişiden kişiye değişebilir.",takeaway:"Engelini gör, ona küçük bir yanıt hazırla.",sources:["mcii-procrastination","if-then-plans","mcii"],visual:{kind:"bars",title:"Göreve başlanan günlerin oranı",sourceId:"mcii-procrastination",bars:[{label:"WOOP (dilek, sonuç, engel, plan)",value:58.8,display:"%58,8"},{label:"Yalnızca olumlu düşünme",value:47.3,display:"%47,3"}],note:"81 üniversite öğrencisi, bir haftalık izlem. Tek ve küçük bir çalışmadır; sana aynı sonucu garanti etmez."}},{id:"procrastination-4",title:"Erteledikten sonra: kendini affet",minutes:7,goal:"Erteledikten sonra kendine saldırmak yerine hem affedici hem sorumlu bir cümle kur.",reading:["Erteledikten sonra kendine “Yine yaptın, hiç düzelmeyeceksin” demek kolaydır. Bu sert ses sonraki başlangıcı kolaylaştırmayabilir; işi daha da itici hâle getirebilir. Öğrencilerle yapılan bir çalışmada, ilk sınav için ertelediği için kendini daha çok affedenler ikinci sınava daha az erteleyerek hazırlandı.","Bu çalışma deneysel değildi; affetmenin ertelemeyi azalttığını kesin olarak göstermez. İlişkiyi olumsuz duygudaki azalmanın açıkladığı görüldü. Kendini affetmek olanı yok saymak değildir: “Erteledim, bu insanca. Bir dahakine şunu farklı yapacağım” demektir."],practice:["Yakın zamanda ertelediğin bir anı kısaca hatırla ve kendine ne söylediğini fark et.","Aynı durumu yaşayan bir arkadaşına söyleyeceğin anlayışlı cümleyi kendine söyle.","Ardından bir dahaki sefere farklı yapacağın tek somut adımı belirle."],reflection:"Kendine söylemek istediğin affedici ama sorumlu cümle ne?",question:"Kendini affetmek bu derste ne anlama geliyor?",options:["Olanı önemsiz sayıp hiçbir şeyi değiştirmemek.","Ertelemeye devam etmek için kendine izin vermek.","Olanı kabul edip bir sonraki adımı seçmek."],correct:2,feedback:"Affetmek sorumluluğu bırakmak değildir. Kendine yüklenmek yerine düzeltebileceğin kısma dönmeni kolaylaştırabilir.",takeaway:"Erteledin; bu seni tanımlamaz. Bir sonraki adım hâlâ senin.",sources:["self-forgiveness","mood-repair","self-compassion"],visual:{kind:"compare",title:"Erteledikten sonra iç ses",left:{label:"Kendine saldırmak",items:["“Ben tembelin tekiyim.”","Tek bir anı bütün kimliğe çevirir.","İşi daha da itici hissettirebilir."]},right:{label:"Kendini affetmek",items:["“Erteledim, bu insanca.”","Olanı kabul eder, sorumluluğu korur.","Bir sonraki küçük adıma yer açar."]},note:"Affetmek, olanı yok saymak veya aynı şekilde sürdürmek demek değildir."}},{id:"procrastination-5",title:"Kendi erteleme planın",minutes:8,goal:"Önümüzdeki hafta için ilk hareket, plan, gözden geçirme ve istersen ara tarihlerle bir deneme kur.",reading:["Erteleme üzerine yapılan müdahale çalışmalarında, müdahaleden sonra ertelemenin belirgin biçimde azaldığı ve bu azalmanın izleme ölçümlerinde de sürdüğü görüldü. Bu değer kontrol grubuyla değil, öncesi–sonrası farkla hesaplandı; etki olduğundan büyük görünebilir. En güçlü sonuçlar uzmanla yürütülen bilişsel davranışçı terapiden geldi ve bu kurs bir terapi değil.","Büyük işi takvimde birkaç ara teslime bölmek, yani kendine nazik ara tarihler koymak, denemeye değer bir fikir. Ancak bu konuda sık anılan bir çalışma geri çekildi ve yerine koyabileceğimiz güçlü bir kanıt incelemedik. Bu yüzden ara tarihleri kanıtlanmış bir yöntem olarak değil, kendi üzerinde gözleyeceğin bir deneme olarak düşün."],practice:["İşini tablodaki satırlara göre yaz: ilk hareket, zaman ve yer, eğer/o zaman planı.","İstersen büyük işe birkaç ara tarih koy; bunları katı kurallar değil, kendine nazik hatırlatmalar olarak düşün.","Hafta sonunda neyin işe yaradığını ve neyi değiştireceğini iki dakikada gözden geçir."],reflection:"Planında hangi parçayı koruyacak, hangisini değiştireceksin?",question:"Kendi koyduğun ara tarihler için en dürüst yaklaşım hangisi?",options:["Kesin işe yarayan, kanıtlanmış bir yöntemdir.","Denemeye değer ama kanıtı sınırlı; sende nasıl çalıştığını gözle.","Hiçbir işe yaramaz, hiç denememek gerekir."],correct:1,feedback:"Kanıtı sınırlı bir yöntemi denemek sorun değildir; önemli olan sende nasıl çalıştığını dürüstçe gözlemek. Erteleme hayatını belirgin biçimde etkiliyorsa bir uzmandan destek alabilirsin.",takeaway:"Planını küçük tut, dene, gözden geçir; gerektiğinde destek iste.",sources:["procrastination-interventions","if-then-plans","monitoring"],visual:{kind:"table",title:"Haftalık erteleme planı",columns:["Adım","Örnek","Senin planın"],rows:[["İlk hareket","Belgeyi açıp üç başlık yazmak","…"],["Zaman ve yer","Salı 9.00, mutfak masası","…"],["Eğer/o zaman","Telefonu alırsam önce bir cümle yazarım","…"],["Ara tarih (deneme)","Perşembe: ilk taslak","…"],["Gözden geçirme","Pazar akşamı, iki dakika","…"]],note:"Ara tarihler kanıtı sınırlı bir denemedir; işe yaramazsa değiştir veya bırak."}}]},Da=[{id:"task-switching",title:"Monsell · 2003 · Görev değiştirmenin bedeli",url:"https://pubmed.ncbi.nlm.nih.gov/12639695/",type:"research",finding:"Bu derlemeye göre insanlar bir görevden ötekine geçtikten hemen sonra yavaşlıyor ve genellikle daha çok hata yapıyor; bu geçiş bedeli hazırlıkla azalıyor ama tamamen kaybolmuyor.",limitation:"Yalnızca yayın özeti incelendi ve özette sayısal değer yok; laboratuvardaki basit görevlerden gelen kısa gecikmeler gerçek işteki kayıplara doğrudan çevrilemez."},{id:"interruptions",title:"Mark, Gudith & Klocke · 2008 · Bölünen işin bedeli: hız ve stres",url:"https://ics.uci.edu/~gmark/chi08-mark.pdf",type:"research",finding:"48 kişilik laboratuvar deneyinde işi bölünen katılımcılar görevi biraz daha kısa sürede ve kaliteyi düşürmeden bitirdi, ama daha yüksek stres, hayal kırıklığı, zaman baskısı ve çaba bildirdi.",limitation:"Çoğunluğu üniversite öğrencisi olan küçük bir örneklemde yapay bir e-posta yanıtlama görevi kullanıldı; sonuçlar gerçek iş yaşamına doğrudan aktarılamaz."},{id:"notifications",title:"Kushlev, Proulx & Dunn · 2016 · Bildirimler ve dikkatsizlik deneyi",url:"https://interruptions.net/literature/Kushlev-CHI16.pdf",type:"research",finding:"221 üniversite öğrencisi bir hafta bildirimleri açık ve telefonu görünür, bir hafta bildirimleri kapalı ve telefonu uzakta tuttu; bildirimli haftada daha fazla dikkatsizlik (d=0,44) ve hareketlilik (d=0,45) bildirdi.",limitation:"Ölçümler öz bildirime dayanıyor, katılımcılar hangi koşulda olduklarını biliyordu ve ham farklar yaklaşık 0,1 puan kadar küçüktü; yazarlar bunun klinik ADHD’ye yol açtığı anlamına gelmediğini vurguluyor."},{id:"phone-presence",title:"Hartanto ve ark. · 2024 · Telefonun yalnızca yanında olması meta-analizi",url:"https://assets.pubpub.org/mgkf17za/tmb_tmb0000123-41706626995650.pdf",type:"research",finding:"33 çalışmayı ve 4.368 katılımcıyı birleştiren meta-analizde telefonun yalnızca yakında durmasının bilişsel performansa genel bir etkisi bulunmadı (d=−0,02) ve çalışma belleğinde görülen küçük etki yayın yanlılığı düzeltmesinden sonra kayboldu.",limitation:"Laboratuvar görevlerine dayanır ve telefonu kullanmayı ya da bildirim almayı değil, yalnızca yakında durmasını inceler; yazarlar yayımlanmış çalışmalarda yayın yanlılığı işareti buldu."},{id:"brain-drain",title:"Ward, Duke, Gneezy & Bos · 2017 · “Beyin boşalması” deneyi (tekrarlanamadı)",url:"https://www.journals.uchicago.edu/doi/full/10.1086/691462",type:"research",finding:"İki deneyde (N=520 ve N=275) telefonu masada olanlar, telefonu başka odada olanlara göre çalışma belleği görevinde biraz daha düşük puan aldı ve etkiler küçüktü (kısmi η²=0,014–0,026).",limitation:"Ön kayıtlı doğrudan tekrarında etki bulunmadı ve 33 çalışmalık meta-analiz genel bir etki göstermedi; bu bulgu tek başına kanıt olarak kullanılmamalı."},{id:"brain-drain-replication",title:"Ruiz Pardo & Minda · 2022 · “Beyin boşalması” tekrar çalışması",url:"https://www.sciencedirect.com/science/article/pii/S0001691822002323",type:"research",finding:"Ward ve arkadaşlarının ikinci deneyinin ön kayıtlı doğrudan tekrarında (N=383) telefonun konumu çalışma belleği performansını etkilemedi (p=0,91).",limitation:"Örneklem genç üniversite öğrencilerinden oluşuyor ve çalışma tek bir laboratuvarda yapıldı."},{id:"microbreaks",title:"Albulescu ve ark. · 2022 · Mikro molalar meta-analizi",url:"https://journals.plos.org/plosone/article?id=10.1371/journal.pone.0272460",type:"research",finding:"22 örneklemi (N=2.335) birleştiren meta-analizde en fazla 10 dakikalık mikro molalar zindeliği artırdı (d=0,36) ve yorgunluğu azalttı (d=0,35), genel performans üzerindeki etki ise anlamlı değildi (d=0,16).",limitation:"Çalışma sayısı az, iyi oluş ölçümleri öz bildirime dayanıyor, performans için yayın yanlılığı işareti var ve zihinsel olarak yoğun işlerde molanın performansa etkisi görülmedi."}],Ca={id:"focus",title:"Odak",subtitle:"Dikkatin sınırlı; ona iyi bak.",description:"Görev değiştirmenin bedelini gör, bildirimlerini düzenle, telefon hakkındaki iddiaları kanıtla karşılaştır, kısa molaları dene ve kendi odak planını kur.",scope:"Gündelik çalışma düzeni için öneriler; dikkat bozukluğu tanısı veya tedavisi değildir. Dikkat güçlükleri kalıcıysa ve günlük yaşamını etkiliyorsa bir sağlık uzmanına danış. Acil durum, bakım veya iş için gereken aramaları sessize alma.",outcome:"Düzenlenmiş bildirimler, denenmiş bir odak bloğu ve mola planı.",lessons:[{id:"focus-1",title:"Dikkat sınırlı, geçişin bir bedeli var",minutes:7,goal:"Gün içinde işler arasında ne sıklıkla geçtiğini ve bunun sana nasıl hissettirdiğini fark et.",reading:["Bir işten ötekine geçtiğinde zihnin kısa bir “vites değiştirme” yapar. Laboratuvar çalışmalarını özetleyen bir derlemeye göre insanlar geçişten hemen sonra yavaşlıyor ve genellikle daha çok hata yapıyor. Hazırlık bu bedeli azaltıyor ama tamamen silmiyor.","Bölünmek her zaman yavaşlatmaz. Küçük bir deneyde işi bölünen kişiler görevi biraz daha hızlı bitirdi, ama daha fazla stres, hayal kırıklığı ve zaman baskısı bildirdi. Tek işte kalmanın faydası yalnızca verim değil, daha sakin çalışmak da olabilir. “Çoklu görev şu kadar verim kaybettirir” gibi popüler sayılara dayanmıyoruz."],practice:["Önümüzdeki bir saat boyunca başka bir işe veya uygulamaya her geçtiğinde bir çizgi çek.","Geçişlerin kaçının senin seçimin, kaçının bir bildirimden ya da başkasından geldiğini ayır.","Bir sonraki geçişten önce “Şimdi … işine geçiyorum” diye kısa bir hazırlık cümlesi dene."],reflection:"Geçişler sana en çok nasıl hissettirdi?",question:"Bu derse göre bölünerek çalışmanın bedeli ne olabilir?",options:["Her zaman işi çok daha yavaş bitirmek.","Bölünmenin hiçbir bedeli yoktur.","Hız korunsa bile daha fazla stres ve baskı hissetmek."],correct:2,feedback:"Küçük bir deneyde bölünenler biraz hızlandı ama daha çok stres bildirdi. Bedel bazen zamanda değil, nasıl hissettiğinde görülür.",takeaway:"Her geçiş küçük bir yük; gerekmeyenleri azaltabilirsin.",sources:["task-switching","interruptions"],visual:{kind:"compare",title:"İki çalışma biçimi",left:{label:"Sık bölünerek",items:["Sık sık vites değiştirmek","Geçişten sonra kısa yavaşlama ve hata riski","Daha fazla stres ve zaman baskısı"]},right:{label:"Tek işte kalarak",items:["Daha az geçiş","Geçişe hazırlanmak için zaman","Daha sakin bir tempo olasılığı"]},note:"Laboratuvar bulgularından çıkarılmış genel bir karşılaştırmadır; kesin bir kazanç veya kayıp sayısı vermez."}},{id:"focus-2",title:"Bildirimler dikkatini nasıl çeker?",minutes:7,goal:"Bildirimlerini gözden geçir ve bir çalışma süresi için sessize al.",reading:["Bir deneyde 221 üniversite öğrencisi bir hafta bildirimleri açık ve telefonu görünür tuttu, bir hafta da bildirimleri kapalı ve telefonu uzakta. Bildirimli haftada biraz daha fazla dikkatsizlik ve hareketlilik bildirdiler. Fark küçüktü ama ölçülebilirdi.","Bu, bildirimlerin bir dikkat bozukluğuna yol açtığı anlamına gelmez; yazarlar da bunu vurguluyor. Dürüst mesaj şu: sessize almak tek başına her şeyi çözmez ama maliyeti düşük bir adım. Önemli kişiler ve acil durumlar için istisna bırakabilirsin. Mesajlarına gün içinde birkaç sabit saatte bakmayı da deneyebilirsin."],practice:["Son bir saatte hangi uygulamaların sana bildirim gönderdiğine bak.","Beklemesi sorun olmayan en az iki uygulamanın bildirimini kapat veya sessize al.","Bir çalışma süresi için “Rahatsız Etme” modunu aç ve acil kişiler için istisna ekle."],reflection:"Hangi bildirimi kapatmak kolay geldi, hangisi zor?",question:"Bu çalışmanın sonucu için en dürüst özet hangisi?",options:["Bildirimleri azaltmak küçük ama ölçülebilir bir fark gösterdi.","Bildirimler ADHD’ye yol açar.","Bildirimleri kapatmak bütün dikkat sorunlarını çözer."],correct:0,feedback:"Fark yaklaşık 0,1 puanlıktı ve öz bildirimle ölçüldü. Sessize almayı mucize beklemeden, maliyeti düşük bir deneme olarak düşünebilirsin.",takeaway:"Sessize almak küçük bir adım; küçük adımlar da sayılır.",sources:["notifications"],visual:{kind:"bars",title:"Dikkatsizlik ortalaması (öz bildirim)",sourceId:"notifications",bars:[{label:"Bildirimler açık, telefon görünür",value:2.38,display:"2,38"},{label:"Bildirimler kapalı, telefon uzakta",value:2.27,display:"2,27"}],note:"221 öğrenci, her koşulda birer hafta. Fark küçük (d=0,44), öz bildirime dayanıyor ve katılımcılar hangi haftada olduklarını biliyordu."}},{id:"focus-3",title:"Masadaki telefon: iddia ve kanıt",minutes:8,goal:"Telefonun yalnızca yanında durmasıyla onu kullanmayı birbirinden ayır.",reading:["“Telefon masada dursa bile zihnini boşaltır” iddiası çok paylaşıldı. Bunu ilk öne süren 2017 tarihli deneylerde küçük bir etki bulunmuştu. Ancak ön kayıtlı doğrudan tekrarında etki görülmedi. 33 çalışmayı birleştiren bir meta-analiz de telefonun yalnızca yakında durmasının bilişsel performansa genel bir etkisini bulmadı.","Bu, telefonun dikkati hiç etkilemediği anlamına gelmez. İncelenen şey telefonun yalnızca orada durmasıydı; onu kullanmak ve bildirim almak ayrı konular. Telefonu başka odaya koymak sana yine de iyi gelebilir; nedeni muhtemelen eline alma isteğini azaltmasıdır. Bu bir çıkarım, sınanmış bir bulgu değil."],practice:["Çalışırken telefonu genelde nerede tuttuğunu ve kaç kez eline aldığını fark et.","Bir çalışma süresi için telefonu uzanamayacağın bir yere koy ve eline alma isteği geldiğinde not et.","Başka bir gün telefonu masada ama sessiz tutarak dene; iki günü kendi gözleminle karşılaştır."],reflection:"Seni asıl zorlayan telefonun orada olması mı, onu eline alma isteği mi?",question:"Güncel kanıtlar telefonun yalnızca masada durması hakkında ne söylüyor?",options:["Zihni kesin olarak boşaltır.","Genel bir etkisi bulunmadı; kullanmak ve bildirimler ayrı bir konu.","Telefonu başka odaya koymanın hiçbir anlamı yoktur."],correct:1,feedback:"Tek bir ilk çalışma yerine tekrar çalışmalarına ve meta-analize bakmak daha güvenilir bir tablo verir. Bilimde ilk bulgular her zaman tekrarlanmaz. Telefonu uzakta tutmak yine de kişisel bir deneme olarak işine yarayabilir.",takeaway:"Telefonun orada olmasından çok, ona ne sıklıkla uzandığın önemli olabilir.",sources:["phone-presence","brain-drain","brain-drain-replication","notifications"],visual:{kind:"table",title:"“Telefon masada” iddiasının izi",columns:["Çalışma","Tür","Sonuç"],rows:[["Ward ve ark. 2017","İlk deneyler (N=520 ve 275)","Küçük etki"],["Ruiz Pardo & Minda 2022","Ön kayıtlı doğrudan tekrar (N=383)","Etki yok"],["Hartanto ve ark. 2024","Meta-analiz, 33 çalışma (N=4.368)","Genel etki yok (d=−0,02)"]],note:"Tek bir çalışma değil, zaman içinde biriken kanıt daha güvenilir bir tablo verir."}},{id:"focus-4",title:"Kısa molalar: ne vaat eder, ne etmez?",minutes:6,goal:"Kısa bir molayı dene ve sana nasıl geldiğini gözle.",reading:["22 örneklemi birleştiren bir meta-analizde en fazla 10 dakikalık molalar zindeliği artırdı ve yorgunluğu azalttı. Genel performans üzerindeki etki ise istatistiksel olarak anlamlı değildi. Yani mola seni daha iyi hissettirebilir; işini mutlaka hızlandıracağı söylenemez.","Zihinsel olarak çok yoğun işlerde kısa molaların performansa etkisi görülmedi; bu tür işlerde daha uzun molalar gerekebilir. Molada ne yapacağına dair kesin bir reçete yok. İşten zihnen uzaklaşmanı sağlayan bir şey, örneğin ekrandan kalkmak ya da kısa bir yürüyüş, denemeye değer."],practice:["Bir çalışma süresinin sonuna beş ila on dakikalık bir mola koy.","Molada ekrandan uzaklaşan bir şey seç: kalkıp su içmek, pencereden bakmak veya kısa bir yürüyüş.","Moladan önce ve sonra ne kadar yorgun hissettiğini 1–5 arasında kendine not et."],reflection:"Molan sende neyi değiştirdi, neyi değiştirmedi?",question:"Kısa molalar için hangi ifade kanıta daha uygun?",options:["Performansı her işte kesin artırır.","Mola vermek yalnızca zaman kaybıdır.","Zindelik ve yorgunluk için umut verici; performans etkisi belirsiz."],correct:2,feedback:"Kanıt, iyi hissetme konusunda performanstan daha tutarlı. Molayı işi hızlandırma aracı değil, kendine bakımın bir parçası olarak düşünebilirsin.",takeaway:"Kısa mola daha zinde hissettirebilir; mucize beklemeden dene.",sources:["microbreaks"],visual:{kind:"bars",title:"Mikro molaların ortalama etkisi",sourceId:"microbreaks",bars:[{label:"Zindelikte artış",value:.36,display:"d = 0,36"},{label:"Yorgunlukta azalma",value:.35,display:"d = 0,35"},{label:"Genel performans (anlamlı değil)",value:.16,display:"d = 0,16"}],note:"d değeri etkinin büyüklüğünü gösterir; 0,36 küçük–orta bir etkidir. Performans etkisi istatistiksel olarak anlamlı değildi ve çalışma sayısı az."}},{id:"focus-5",title:"Kendi odak planın",minutes:8,goal:"Bildirim, telefon, çalışma bloğu ve mola kararlarını tek bir kişisel denemede birleştir.",reading:["Zaman blokları, yani belirli bir süreyi tek bir işe ayırmak, birçok kişinin kullandığı bir yöntem. Bu yöntemi doğrudan sınayan sağlam bir çalışma incelemedik. Yine de görev değiştirmenin bedeli ve bölünmelerin stresi düşünüldüğünde, denemeye değer makul bir kişisel deney.","Planına dikkatin dağıldığında ne yapacağını da ekle: “Eğer telefonu elime almak istersem, o zaman önce cümlemi bitireceğim.” Blok bitince kısa bir mola ver ve nasıl gittiğine bak. Blok kısa kaldıysa veya hiç yapamadıysan bu bir başarısızlık değil, planını ayarlamak için bir bilgi."],practice:["Yarın için tek bir iş ve sana uygun bir blok süresi seç; kısa başlamak da olur.","“Eğer dikkatim dağılırsa, o zaman …” cümlesini tamamla ve bildirim ayarını bloktan önce yap.","Blok ve moladan sonra neyin işe yaradığını, neyi değiştireceğini kısaca not et."],reflection:"Odak planında seni en çok destekleyen parça hangisi?",question:"Zaman blokları için en dürüst yaklaşım hangisi?",options:["Herkes için kanıtlanmış en iyi yöntemdir.","Makul bir kişisel deney; sonuca bakıp ayarlanır.","Blok bozulursa bütün gün boşa gitmiş demektir."],correct:1,feedback:"Zaman blokları mantıklı bir deneme ama kanıtlanmış bir teknik değil. Sende nasıl çalıştığını gözlemek ve ayarlamak planın parçası. Dikkat güçlüklerin kalıcıysa bir sağlık uzmanıyla konuşabilirsin.",takeaway:"Odak planın bir deney: dene, bak, ayarla.",sources:["interruptions","mcii","monitoring"],visual:{kind:"steps",title:"Bir odak bloğu",steps:[{label:"Seç",text:"Tek bir iş ve sana uygun bir süre seç."},{label:"Hazırla",text:"Bildirimleri sustur, acil kişilere istisna bırak."},{label:"Çalış",text:"Dağılırsan aklına geleni not et ve işe dön."},{label:"Mola ver",text:"Ekrandan kalk, birkaç dakika uzaklaş."},{label:"Değerlendir",text:"Neyin işe yaradığını not et, planı ayarla."}],note:"Bu akış kanıtlanmış bir teknik değil, kendi üzerinde deneyeceğin bir öneridir."}}]},Ha=[{id:"sleep-duration",title:"Watson ve ark. · 2015 · Yetişkin uyku süresi uzlaşı bildirgesi",url:"https://doi.org/10.5664/jcsm.4758",type:"guidance",finding:"AASM ve Uyku Araştırmaları Derneği’nin 15 uzmanı, yetişkinlerin sağlık için düzenli olarak gecede en az 7 saat uyuması gerektiği sonucuna vardı; düzenli kısa uyku pek çok sağlık sorunuyla ilişkili bulundu.",limitation:"Büyük ölçüde gözlemsel çalışmalara dayanan bir uzman uzlaşısıdır ve kısa uykunun bu sorunlara tek başına yol açtığını kanıtlamaz; tam metin okunamadı, yalnızca özet ve AASM halk sayfaları incelendi."},{id:"cdc-sleep",title:"CDC · Yaşa göre önerilen uyku süreleri",url:"https://www.cdc.gov/sleep/about/index.html",type:"guidance",finding:"CDC, 18–60 yaş için gecede 7 saat veya daha fazla, 61–64 yaş için 7–9 saat, 65 yaş ve üzeri için 7–8 saat uyku önerir; her gün aynı saatlerde yatıp kalkmayı ve ekranları yatmadan en az 30 dakika önce kapatmayı tavsiye eder.",limitation:"Genel halk rehberidir, kişisel tıbbi değerlendirmenin yerini tutmaz ve dayandığı kanıtı sayfada ayrıntılandırmaz."},{id:"sleep-light",title:"National Sleep Foundation · 2025 · Işık ve uyku önerileri",url:"https://www.thensf.org/good-light-bad-light-and-better-sleep/",type:"guidance",finding:"NSF, sabah ya da öğleden sonra en az bir saat dışarıda vakit geçirmeyi, akşam ışıkları kısmayı ve ekranları yatmadan en az bir saat önce kapatmayı önerir.",limitation:"Bir vakfın halk yazısıdır; bir saatlik değerler test edilmiş eşikler değil pratik önerilerdir ve sayfada birincil çalışma verisi yoktur."},{id:"sleep-habits",title:"AASM · Sağlıklı uyku alışkanlıkları",url:"https://sleepeducation.org/healthy-sleep/healthy-sleep-habits/",type:"guidance",finding:"AASM, yaklaşık 20 dakika içinde uykuya dalamayınca yataktan kalkıp az ışıklı, sakin bir etkinlik yapmayı, hafta sonu dahil her gün aynı saatte kalkmayı ve ekranları yatmadan en az 30 dakika önce kapatmayı önerir.",limitation:"Halk eğitimi sayfasıdır ve kanıt düzeyi belirtmez; 20 dakika kesin bir bilimsel eşik değil, pratik bir yönergedir."},{id:"caffeine-timing",title:"Drake ve ark. · 2013 · Yatmadan 0, 3 ve 6 saat önce kafein deneyi",url:"https://doi.org/10.5664/jcsm.3170",type:"research",finding:"12 sağlıklı kişide yatmadan hemen önce, 3 veya 6 saat önce alınan 400 mg kafein uykuyu plaseboya göre bozdu; 6 saat önce alındığında bile ölçülen toplam uyku bir saatten fazla kısaldı.",limitation:"Yalnızca özet ve AASM basın bülteni okundu; örneklem çok küçük ve tek, yüksek bir doz denendiği için sonuç daha düşük dozlara ve farklı kişilere doğrudan genellenemez."},{id:"caffeine-amounts",title:"FDA · 2024 · Ne kadar kafein fazla?",url:"https://www.fda.gov/consumers/consumer-updates/spilling-beans-how-much-caffeine-too-much",type:"guidance",finding:"FDA, çoğu sağlıklı yetişkin için günde 400 mg kafeinin genellikle olumsuz etkiyle ilişkilendirilmediğini, ancak kişisel duyarlılığın değiştiğini belirtir ve içecek başına yaklaşık miktarları verir.",limitation:"Değerler ABD içecek boyutlarına göredir ve Türk kahvesi ya da çay bardağı için değer içermez; hamilelik, emzirme ve çocukluk–gençlik döneminde ayrıca dikkat gerekir."},{id:"nhs-insomnia",title:"NHS · Uykusuzluk rehberi",url:"https://www.nhs.uk/conditions/insomnia/",type:"guidance",finding:"NHS, 3 ay veya daha uzun süren uykusuzluğu uzun süreli sayar; yatmadan en az 6 saat önce çay, kahve, alkol ve sigarayı, en az 4 saat önce egzersizi bırakmayı ve en az 1 saat önce gevşemeye başlamayı önerir.",limitation:"Genel bilgilendirme sayfasıdır; önerilerin çoğu tek tek test edilmiş sayısal eşikler değil, pratik alışkanlık önerileridir."},{id:"insomnia-self-help",title:"NHS Greater Glasgow and Clyde · Uykusuzluk öz-yardım sayfası",url:"https://www.nhsggc.scot/your-health/heads-up-mental-health-support/mental-health-conditions/insomnia/",type:"guidance",finding:"Uzun süredir uyku sorunu yaşayanlara uykuya dalmak için yaklaşık çeyrek saat tanımayı, hâlâ uyanıksa kalkıp rahatlatıcı bir şey yapmayı önerir.",limitation:"Bölgesel bir öz-yardım sayfasıdır, kanıt ayrıntısı içermez ve yalnızca ilgili bölümleri incelendi."},{id:"insomnia-guideline",title:"Qaseem ve ark. (ACP) · 2016 · Kronik uykusuzluk kılavuzu",url:"https://www.acpjournals.org/doi/10.7326/M15-2175",type:"guidance",finding:"Amerikan Hekimler Koleji, kronik uykusuzluk bozukluğu olan yetişkinlere ilk tedavi olarak uykusuzluk için bilişsel davranışçı terapiyi (BDT-U) önerir (güçlü öneri, orta kaliteli kanıt).",limitation:"Kılavuz en az 3 aydır haftada en az 3 gece belirti yaşayan yetişkinler içindir ve kısa bir öz-yardım kursuna doğrudan uygulanamaz; özet ve öneri metni incelendi."},{id:"cbti-insomnia",title:"Trauer ve ark. · 2015 · Kronik uykusuzlukta BDT-U meta-analizi",url:"https://pubmed.ncbi.nlm.nih.gov/26054060/",type:"research",finding:"20 randomize çalışma, 1.162 katılımcı: BDT-U tedavi sonunda uykuya dalma süresini 19,03 dakika, gece uyanık kalınan süreyi 26,00 dakika kısalttı; toplam uyku süresindeki 7,61 dakikalık artış istatistiksel olarak anlamlı değildi.",limitation:"Yalnızca özet okundu; dar dahil etme ölçütleri genellemeyi sınırlar ve sonuçlar uzmanların uyguladığı BDT-U içindir, bu kısa kurs için değildir."},{id:"sleep-apnea",title:"NHS · Uyku apnesi rehberi",url:"https://www.nhs.uk/conditions/sleep-apnoea/",type:"guidance",finding:"NHS, uyurken nefesin durup yeniden başlaması, boğulma veya soluk soluğa kalma sesleri, yüksek sesli horlama, gündüz aşırı yorgunluk ve sabah baş ağrısını uyku apnesi işaretleri arasında sayar.",limitation:"Belirti listesi tanı koymaz; bu işaretler varsa bir hekime başvurmak gerekir."}],Oa={id:"sleep",title:"Uyku ve enerji",subtitle:"Dinlenmeye bir ritim ver.",description:"Uyku ihtiyacını tanı, ışığı ve kafeini zamanla, uyuyamadığında ne yapacağını bil ve ne zaman yardım isteyeceğini öğren.",scope:"Yetişkinler için uyku alışkanlıkları eğitimi; tanı veya tedavi değildir. Uykusuzluk haftada en az 3 gece ve 3 aydan uzun sürüyorsa, uyurken nefesinin durduğu fark ediliyorsa ya da gündüz yaşamın zorlaşıyorsa bir hekime başvur. Uyku ilacını veya kullandığın başka bir ilacı hekimine danışmadan başlatma, bırakma ya da değiştirme.",outcome:"Sabit bir kalkış saati, akşam için kafein ve ekran sınırı, uyuyamadığında uygulayacağın bir plan ve yardım işaretleri listesi.",lessons:[{id:"sleep-1",title:"Ne kadar uykuya ihtiyacın var?",minutes:7,goal:"Uyku fırsatını sabit bir kalkış saatinden geriye sayarak planla.",reading:["CDC, 18–60 yaş arası yetişkinler için gecede en az 7 saat uyku önerir. AASM ve Uyku Araştırmaları Derneği’nden 15 uzman da aynı alt sınıra vardı. Bu tek bir sihirli sayı değil; altına düşmemeye çalıştığın bir taban.","Düzenli kısa uyku; kalp hastalığı, diyabet ve depresyon gibi sorunlarla ilişkili bulundu. Bu bulguların çoğu gözlemsel çalışmalardan gelir ve kısa uykunun tek başına neden olduğunu kanıtlamaz. Ara sıra kötü geçen bir gece de panik sebebi değildir. Bugün bir başlangıç noktası seçeceğiz: hafta sonu dahil her gün aynı saatte kalkmak."],practice:["Hafta içi ve hafta sonu tutabileceğin tek bir kalkış saati seç.","Bu saatten en az 7 saat geriye say; uykuya dalma payını da ekleyerek yatağa gireceğin saati belirle.","Önümüzdeki yedi gün yatış ve kalkış saatini kısa bir not olarak kaydet."],reflection:"Seçtiğin kalkış saatini korumayı ne zorlaştırabilir?",question:"Yetişkinler için uyku önerisi nasıl okunmalı?",options:["Herkes tam 8 saat uyumak zorundadır.","En az 7 saat, çoğu gece ulaşmaya çalıştığın bir tabandır.","Bir gece kötü uyursan sağlığın kesin bozulur."],correct:1,feedback:"Öneri bir alt sınırdır ve düzenli alışkanlıkla ilgilidir. Tek bir kötü gece, uzun süren bir örüntüyle aynı şey değildir.",takeaway:"Sabit bir kalkış saati, uykunun geri kalanına çerçeve verir.",sources:["cdc-sleep","sleep-duration","sleep-habits"],visual:{kind:"table",title:"Yaşa göre önerilen uyku (CDC)",columns:["Yaş","Önerilen uyku"],rows:[["18–60","Gecede 7 saat veya daha fazla"],["61–64","7–9 saat"],["65 ve üzeri","7–8 saat"]],note:"NHS yetişkinler için 7–9 saat der. Kişisel ihtiyaç değişebilir; bu tablo tıbbi değerlendirme değildir."}},{id:"sleep-2",title:"Işığı güne, loşluğu akşama ver",minutes:6,goal:"Gündüz ışığı ve akşam ekran kullanımında tek bir değişiklik seç.",reading:["National Sleep Foundation, sabah ya da öğleden sonra en az bir saat dışarıda vakit geçirmeyi ve akşam gevşerken ışıkları kısmayı önerir. Bu bir vakfın pratik önerisidir; sabah ışığı için burada sayısal bir araştırma sonucu vermiyoruz.","CDC ve AASM, elektronik cihazları yatmadan en az 30 dakika önce kapatmayı önerir; NSF bu süreyi bir saat olarak verir. Hepsini birden yapmak zorunda değilsin. Ekranı bırakacağın saati belirleyip yerine sakin bir etkinlik koymak iyi bir başlangıç olabilir."],practice:["Gününde dışarıda ya da pencere kenarında vakit geçirebileceğin bir anı belirle.","Bu akşam ekranları bırakacağın saati yatıştan en az 30 dakika önceye koy.","Ekranın yerine yapacağın loş ışıklı, sakin bir etkinlik seç: kitap, hafif esneme veya müzik."],reflection:"Akşam ekranı bırakmak sana en çok hangi saatte zor geliyor?",question:"Akşam ekranları için hangisi resmî önerilere uygun bir başlangıç?",options:["Ekranı yatağa girene kadar kullanmak.","Işıkları sonuna kadar açıp ekranla gevşemek.","Yatmadan en az 30 dakika önce ekranları bırakmak."],correct:2,feedback:"CDC ve AASM en az 30 dakikayı, NSF bir saati önerir. Sana uygun olan süreyle başlayıp nasıl hissettiğini gözlemleyebilirsin.",takeaway:"Gündüz ışığa çık, akşam ışığı kıs.",sources:["sleep-light","cdc-sleep","sleep-habits"],visual:{kind:"compare",title:"Gün içinde ışık",left:{label:"Gündüz",items:["Sabah ya da öğleden sonra dışarıda vakit geçir","Kahveni pencere kenarında veya dışarıda iç","Kısa bir yürüyüşü günlük işine bağla"]},right:{label:"Akşam",items:["Gevşerken ışıkları kıs","Ekranı yatmadan en az 30 dakika önce bırak","Mümkünse bu süreyi bir saate çıkar"]},note:"Öneriler NSF, CDC ve AASM halk rehberlerinden gelir; test edilmiş kesin eşikler değildir."}},{id:"sleep-3",title:"Kafein ve akşam alışkanlıkları",minutes:8,goal:"Son kafein saatini ve akşam için bir alışkanlık sınırını belirle.",reading:["Drake ve arkadaşlarının 12 kişiyle yaptığı deneyde, yatmadan 6 saat önce alınan 400 mg kafein bile ölçülen toplam uykuyu bir saatten fazla kısalttı. Kişilerin kendi uyku değerlendirmesiyle ölçülen uyku arasında da fark bildirildi. Örneklem küçüktü ve tek, yüksek bir doz denendi; yine de “kahve bana dokunmuyor” hissi her zaman güvenilir olmayabilir.","FDA, çoğu sağlıklı yetişkin için günde toplam 400 mg kafeinin genellikle olumsuz etkiyle ilişkilendirilmediğini söyler; deneydeki doz bunun tamamını tek seferde veriyordu. NHS, yatmadan en az 6 saat önce çay, kahve, alkol ve sigarayı, en az 4 saat önce de egzersizi bırakmayı önerir. Örneğin 23.00’te yatıyorsan son çay ya da kahve saatin en geç 17.00 olabilir."],practice:["Yatış saatinden 6 saat geriye sayarak son çay veya kahve saatini belirle.","Bir gün boyunca içtiğin kafeinli içecekleri kısaca not et.","Akşam için tek bir sınır seç: geç kahveyi bırakmak, ağır öğünü öne almak ya da egzersizi erkene çekmek."],reflection:"Akşam alışkanlıklarından hangisini değiştirmek sana en kolay geliyor?",question:"Drake 2013 deneyinden hangi sonuç çıkarılabilir?",options:["Yatmadan 6 saat önce alınan yüksek doz kafein de uykuyu kısaltabilir.","Kafein yalnızca yatmadan hemen önce alınırsa uykuyu etkiler.","Kafein kimsenin uykusunu etkilemez."],correct:0,feedback:"Küçük bir deneyde 6 saat önce bile bir saatten fazla kayıp ölçüldü. Daha düşük dozlarda sonuç farklı olabilir; kendi gözlemin de önemlidir.",takeaway:"Son kafein saatini yatış saatinden geriye say.",sources:["caffeine-timing","caffeine-amounts","nhs-insomnia"],visual:{kind:"table",title:"Yaklaşık kafein miktarı (FDA)",columns:["İçecek (~355 ml)","Kafein"],rows:[["Yeşil çay","37 mg"],["Siyah çay","71 mg"],["Kafeinli gazlı içecek","23–83 mg"],["Enerji içeceği","41–246 mg"],["Demleme kahve","113–247 mg"]],note:"ABD’deki 12 onsluk içecek boyutudur; Türk kahvesi ve çay bardağı için değer yok. Hamilelik, emzirme ve gençlik döneminde ayrıca dikkat gerekir."}},{id:"sleep-4",title:"Uyuyamadığında yatakta boğuşma",minutes:7,goal:"Uyku gelmediğinde uygulayacağın sakin bir planı hazırla.",reading:["AASM, yaklaşık 20 dakika içinde uykuya dalamazsan yataktan kalkıp loş ışıkta sakin bir şey yapmayı, uykun gelince geri dönmeyi önerir. Yatağı yalnızca uyku ve cinsellik için kullanmayı da tavsiye eder; buradaki fikir, yatağı uyanık boğuşmayla değil uykuyla eşleştirmektir. NHS Glasgow bölgesi aynı öneriyi yaklaşık çeyrek saat olarak verir; yani bu kesin bir eşik değil, pratik bir yönergedir.","Saati sürekli kontrol etmene gerek yok; “uzun süredir uyanığım” hissi yeterli bir işaret. NHS, yatmadan en az bir saat önce gevşemeye başlamayı, yalnızca uykun geldiğinde yatmayı ve gündüz uyumamayı önerir. Gece nasıl geçerse geçsin, ertesi sabah yine aynı saatte kalkmaya çalış."],practice:["Uyuyamadığında gideceğin loş ışıklı, sakin bir köşe belirle.","Orada yapacağın ekransız bir etkinlik seç: sıkıcı bir kitap, hafif esneme veya yavaş nefes.","Yatmadan bir saat önce başlayacak kısa bir gevşeme rutini yaz ve bu akşam dene."],reflection:"Uyuyamadığın bir gecede kendine ne söylemek istersin?",question:"Yaklaşık 20 dakikadır uyuyamıyorsan AASM ne önerir?",options:["Uyumak için daha çok zorlamak.","Yatakta telefonda gezinmeye başlamak.","Kalkıp loş ışıkta sakin bir şey yapmak, uykun gelince dönmek."],correct:2,feedback:"Yataktan kalkmak, yatakta boğuşmanın yerini alır. Uykun geldiğinde dönersin; sabah yine aynı saatte kalkarsın.",takeaway:"Uyku zorlanmaz; ona yer açılır.",sources:["sleep-habits","insomnia-self-help","nhs-insomnia"],visual:{kind:"steps",title:"Yaklaşık 20 dakika kuralı",steps:[{label:"Fark et",text:"Uzun süredir uyanık olduğunu fark et; saati izleme."},{label:"Kalk",text:"Yataktan kalk, loş ışıklı sakin köşene geç."},{label:"Sakin bir şey yap",text:"Ekransız, hafif ve sıkıcı bir etkinlik seç."},{label:"Uykun gelince dön",text:"Uyku hissi gelince yatağa dön; gerekirse tekrarla."},{label:"Aynı saatte kalk",text:"Gece nasıl geçerse geçsin sabah aynı saatte kalk."}],note:"AASM 20 dakika, NHS Glasgow yaklaşık 15 dakika der; ikisi de pratik yönergedir."}},{id:"sleep-5",title:"Ne zaman yardım istemeli?",minutes:8,goal:"Uzman desteği gerektirebilecek uyku işaretlerini tanı ve bir sonraki adımını seç.",reading:["Uykusuzluk haftada en az 3 gece ve 3 aydan uzun sürüyorsa, bu kronik uykusuzluk olabilir. Amerikan Hekimler Koleji, kronik uykusuzlukta ilk tedavi olarak ilacı değil, uykusuzluk için bilişsel davranışçı terapiyi (BDT-U) önerir. 20 randomize çalışmayı birleştiren bir meta-analizde BDT-U uykuya dalma süresini yaklaşık 19 dakika, gece uyanık kalınan süreyi 26 dakika kısalttı; toplam uyku süresindeki artış ise istatistiksel olarak anlamlı değildi.","Uyku apnesi başka bir durumdur ve bu kursun konusu değildir. NHS; uyurken nefesin durup yeniden başlaması, boğulma ya da soluk soluğa kalma sesleri, yüksek sesli horlama, gündüz aşırı yorgunluk ve sabah baş ağrısını işaret olarak sayar. Bunları fark eden biri varsa hekime birlikte gitmek yardımcı olabilir. Uyku ilacını ya da kullandığın başka bir ilacı hekimine danışmadan başlatma, bırakma veya değiştirme."],practice:["Son üç ayda haftada kaç gece uyumakta zorlandığını dürüstçe düşün.","Uyku apnesi işaretlerinden birini fark edip etmediğini birlikte kaldığın kişiye sor.","Gerekirse hekime götürmek için iki haftalık kısa bir uyku notu tut: yatış, kalkış ve gece uyanmaları."],reflection:"Uykun için bir uzmana danışmak sana ne kazandırabilir?",question:"Haftada en az 3 gece, 3 aydan uzun süren uykusuzlukta önerilen ilk adım nedir?",options:["Kendi başına uyku ilacına başlamak.","Bir uzmana başvurup BDT-U gibi seçenekleri konuşmak.","Bu kursu tekrar etmenin yeterli olduğunu düşünmek."],correct:1,feedback:"ACP kılavuzu kronik uykusuzlukta ilk tedavi olarak BDT-U’yu önerir; bu, bir uzmanla yürütülen yapılandırılmış bir terapidir. Bu kurs onun yerine geçmez.",takeaway:"Uzun süren bir uyku sorunu, yardım istemek için yeterli bir nedendir.",sources:["insomnia-guideline","cbti-insomnia","sleep-apnea","nhs-insomnia"],visual:{kind:"bars",title:"BDT-U sonrası değişim (tedavi sonu)",bars:[{label:"Uykuya dalma süresi",value:19.03,display:"19 dk daha hızlı"},{label:"Gece uyanık kalınan süre",value:26,display:"26 dk daha az"},{label:"Toplam uyku süresi",value:7.61,display:"+7,6 dk · anlamlı değil"}],note:"20 randomize çalışma, 1.162 kişi; uzmanların uyguladığı BDT-U ile ortalama dakika azalması ve toplam uykudaki küçük, istatistiksel olarak anlamsız artış. Bu kısa kurs BDT-U değildir.",sourceId:"cbti-insomnia"}}]},Pa=[{id:"cyclic-sighing",title:"Balban ve ark. · 2023 · Döngüsel iç çekme randomize çalışması",url:"https://pmc.ncbi.nlm.nih.gov/articles/PMC9873947/",type:"research",finding:"108 kişinin 28 gün boyunca günde 5 dakika nefes alıştırması ya da farkındalık meditasyonu yaptığı bu uzaktan randomize çalışmada nefes grupları, özellikle nefes vermeyi uzatan döngüsel iç çekme, meditasyona göre olumlu duyguda daha fazla artış (kişi başı günlük ortalama değişim 1,91’e karşı 1,22) ve solunum hızında daha fazla düşüş gösterdi.",limitation:"Katılımcıların çoğu Stanford’daki bir lisans psikoloji dersinden gelen sağlıklı gençlerdi, alt grup örneklemleri küçüktü, uyum öz bildirime dayanıyordu ve çalışma başta keşif amaçlı olduğu için önceden kaydedilmemişti; kalp hızı değişkenliği ve uyku ölçümlerinde anlamlı değişiklik bulunmadı."},{id:"slow-breathing",title:"Zaccaro ve ark. · 2018 · Yavaş nefes sistematik derlemesi",url:"https://www.frontiersin.org/journals/human-neuroscience/articles/10.3389/fnhum.2018.00353/full",type:"research",finding:"Dakikada 10’dan az nefesle yapılan teknikleri inceleyen bu derlemede, taranan 2.461 özetten dahil edilen 15 makalede yavaş nefes; kalp hızı değişkenliğinde artış, rahatlama ve huzurda artış, kaygı, uyarılmışlık, depresif belirti ve öfkede azalma ile ilişkili bulundu.",limitation:"Yalnızca sağlıklı kişilerle yapılmış, tasarımları ve teknikleri çok farklı 15 küçük çalışmayı kapsar; derlemeye göre hiçbiri boylamsal veya randomize kontrollü tasarım kullanmamıştı ve etki büyüklüğü hesaplanmadı."},{id:"activity-mood",title:"Singh ve ark. · 2023 · Fiziksel aktivite ve ruh sağlığı şemsiye derlemesi",url:"https://bjsm.bmj.com/content/57/18/1203",type:"research",finding:"97 sistematik derleme (1.039 randomize çalışma, 128.119 katılımcı) birleştirildiğinde fiziksel aktivite depresyon (medyan etki büyüklüğü −0,43), kaygı (−0,42) ve psikolojik sıkıntı (−0,60) belirtilerinde azalma gösterdi; daha yüksek yoğunluk daha fazla iyileşmeyle, 12 hafta veya daha kısa müdahaleler en büyük etkiyle ilişkiliydi.",limitation:"Dahil edilen derlemelerin 97’sinden 77’si AMSTAR ölçütüne göre kritik düzeyde düşük kalitedeydi, bu yüzden kesin sayılar temkinle yorumlanmalı ve hareket, ağır depresyon ya da kaygı bozukluğunda profesyonel tedavinin yerine geçmez."},{id:"emotion-regulation",title:"Webb, Miles & Sheeran · 2012 · Duygu düzenleme stratejileri meta-analizi",url:"https://eric.ed.gov/?id=EJ971301",type:"research",finding:"306 deneysel karşılaştırmada perspektif almak (d+ = 0,45) ve durumu yeniden değerlendirmek (d+ = 0,36) duyguyu etkilemede küçük–orta düzeyde etkiliyken düşünceleri bastırmak etkili değildi (d+ = −0,12).",limitation:"Yalnızca özet okundu ve çalışmaların çoğu laboratuvarda kısa süreli uyandırılan duygularla yapıldığı için sonuçlar gündelik hayattaki uzun süreli strese veya klinik gruplara doğrudan genellenemez."},{id:"affect-labeling",title:"Torre & Lieberman · 2018 · Duyguları adlandırma derlemesi",url:"https://journals.sagepub.com/doi/10.1177/1754073917742706",type:"research",finding:"Bu anlatısal derleme, duyguları kelimelere dökmenin duygusal deneyimi hafifletebileceğini ve açık düzenleme tekniklerinin aksine bir düzenleme süreci gibi hissettirmeyebileceğini öne sürer.",limitation:"Sistematik derleme veya meta-analiz değildir, sayısal etki büyüklüğü vermez ve yalnızca özetin bir kısmı okunabildi."},{id:"who-stress",title:"WHO · Stres: soru-cevap",url:"https://www.who.int/news-room/questions-and-answers/item/stress",type:"guidance",finding:"DSÖ stresi zor bir durumun yol açtığı endişe veya zihinsel gerginlik hâli olarak tanımlar ve baş etmek için düzenli günlük rutin, düzenli uyku, düzenli egzersiz, güvenilen kişilerle bağlantıda kalıp duyguları paylaşmayı ve haber ile sosyal medya tüketimini azaltmayı önerir.",limitation:"Genel halk rehberidir ve sayısal etki bilgisi içermez."},{id:"nhs-stress",title:"NHS · Stresle baş etmede yardım",url:"https://www.nhs.uk/mental-health/feelings-symptoms-behaviours/feelings-and-symptoms/stress/",type:"guidance",finding:"NHS stresin baş ağrısı, kas gerginliği, konsantrasyon güçlüğü, bunalmışlık, sinirlilik ve uyku değişiklikleriyle görülebileceğini belirtir, duyguları bir arkadaş, aile üyesi veya sağlık profesyoneliyle konuşmayı önerir ve stresle baş edilemiyorsa ya da öz-yardım işe yaramıyorsa hekime başvurmayı söyler.",limitation:"Birleşik Krallık hizmetlerine göre yazılmıştır; Türkiye’de acil durumlar için 112 aranır."},{id:"nhs-stress-tips",title:"NHS · 10 stres azaltma önerisi",url:"https://www.nhs.uk/mental-health/self-help/guides-tools-and-activities/tips-to-reduce-stress/",type:"guidance",finding:"NHS, aktif olmayı, insanlarla bağ kurmayı ve başkalarına yardım etmeyi de içeren 10 öneri sıralar ve egzersizin stresi yok etmeyeceğini ama hissedilen duygusal yoğunluğu bir miktar azaltabileceğini belirtir.",limitation:"Kanıt düzeyi belirtilmeyen genel bir öneri listesidir."}],Wa={id:"calm",title:"Stres ve sakinlik",subtitle:"Gerginliğe alan aç.",description:"Stresi fark edip adlandır, nefes verişini uzat, bedenini hareket ettir, duruma başka bir açıdan bak ve ne zaman yardım isteyeceğini bil.",scope:"Yetişkinler için gündelik stresle baş etme eğitimi; tanı veya tedavi değildir. Nefes alıştırmasında başın döner ya da kendini kötü hissedersen dur ve normal nefesine dön. Stresle baş edemiyorsan ya da öz-yardım işe yaramıyorsa bir sağlık profesyoneline başvur; sürdürdüğün tedaviyi veya ilacı hekimine danışmadan bırakma. Kendine zarar verme düşüncen ya da acil bir tehlike varsa 112’yi ara.",outcome:"Kendi stres işaretlerin, denenmiş bir nefes alıştırması, kısa bir hareket planı, bir bakış açısı sorusu ve destek listesi.",lessons:[{id:"calm-1",title:"Stresi fark et, adını koy",minutes:6,goal:"Stresin bedeninde ve zihninde nasıl göründüğünü fark edip ona bir ad ver.",reading:["DSÖ stresi, zor bir durumun yol açtığı endişe veya zihinsel gerginlik hâli olarak tanımlar. Bir sınav, yoğun bir iş haftası ya da bir tartışma karşısında gerilmek insanın olağan bir tepkisidir; stres tek başına zayıflık işareti değildir. Güçlük çoğu zaman gerginlik aşırı ve süreğen hâle geldiğinde başlar.","NHS, stresin baş ağrısı, kas gerginliği, konsantrasyon güçlüğü, bunalmışlık, sinirlilik ve uyku değişiklikleriyle görülebileceğini söyler. Bu işaretleri fark ettiğinde “Şu an ne hissediyorum?” diye sorup tek kelimeyle ad verebilirsin: gergin, kırgın, bunalmış. Torre ve Lieberman’ın derlemesi, duyguyu kelimelere dökmenin deneyimi hafifletebileceğini öne sürer; sayı vermeyen bir derleme olduğu için bunu bir deneme olarak düşün."],practice:["Bedeninde şu an fark ettiğin bir gerginlik işaretini bul: çene, omuz, mide ya da nefes.","Hissettiğin duyguya tek kelimelik bir ad ver; en doğru kelimeyi bulmak zorunda değilsin.","Bu duyguya eşlik eden durumu “Şu durumda … hissediyorum” diye tek cümleyle tarif et."],reflection:"Stres sende en çok hangi işaretle kendini gösteriyor?",question:"Hangisi bu dersin strese bakışına uygun?",options:["Stres hissediyorsam bir şeyler kesin ters gidiyordur; hemen yok etmeliyim.","Stres zor durumlara olağan bir tepkidir; fark edip adlandırmak ilk adım olabilir.","Duyguma ad verirsem onu büyütürüm; görmezden gelmeliyim."],correct:1,feedback:"Stres zor bir duruma verilen olağan bir tepkidir. Onu fark edip adlandırmak, ne yapabileceğini seçmene yer açar; aşırı ve süreğen hâle geldiğinde destek almak önemlidir.",takeaway:"Önce fark et, sonra adını koy.",sources:["who-stress","nhs-stress","affect-labeling"],visual:{kind:"compare",title:"Hüküm mü, adlandırma mı?",left:{label:"Genel hüküm",items:["Her şey berbat gidiyor.","Ben bu işi kaldıramam.","Hiç sakin olamıyorum."]},right:{label:"Adlandırma",items:["Yarınki sunum yüzünden gerginim.","Omuzlarım sıkı, biraz bunalmış hissediyorum.","Az önceki konuşma yüzünden sinirliyim."]},note:"Adlandırmak sorunu çözmez; ne yaşadığını daha açık görmeni kolaylaştırabilir."}},{id:"calm-2",title:"Nefes verişini uzat",minutes:7,goal:"Döngüsel iç çekmeyi yaklaşık 5 dakika boyunca, kendi sınırlarını gözeterek dene.",reading:["Balban ve arkadaşlarının çalışmasında 108 kişi 28 gün boyunca günde 5 dakika ya bir nefes alıştırması ya da farkındalık meditasyonu yaptı. Nefes gruplarında, özellikle nefes vermeyi uzatan döngüsel iç çekmede, olumlu duygudaki artış meditasyona göre biraz daha fazlaydı ve solunum hızı daha çok düştü. Meditasyon grubunda da kaygı ve olumsuz duygu azaldı; yani tek doğru yöntem yok.","Katılımcıların çoğu sağlıklı üniversite öğrencileriydi, gruplar küçüktü ve çalışma önceden kaydedilmemişti; bu bir tedavi değil, denemeye değer bir alıştırmadır. Zaccaro ve arkadaşlarının derlemesi de dakikada 10’dan az nefesle yapılan yavaş nefesi rahatlama ve daha düşük kaygıyla ilişkili buldu, ama incelenen 15 küçük çalışmanın hiçbiri randomize kontrollü değildi. Başın döner, göğsünde baskı ya da rahatsızlık hissedersen dur ve normal nefesine dön."],practice:["Rahat bir yerde otur, omuzlarını bırak ve yaklaşık 5 dakikalık bir zamanlayıcı kur.","Burundan yavaşça nefes al, akciğerlerin dolunca kısa bir nefes daha ekle, sonra ağızdan yavaşça ve tamamen ver.","Bitince bedeninde ya da duygunda fark ettiğin tek bir değişikliği not et; değişiklik olmaması da bir gözlemdir."],reflection:"Nefes verişini uzattığında bedeninde ne fark ettin?",question:"Döngüsel iç çekmede vurgu hangisindedir?",options:["Nefesi olabildiğince uzun süre tutmak.","Hızlı ve derin nefesleri art arda almak.","Nefes vermeyi yavaş ve uzun tutmak."],correct:2,feedback:"Bu alıştırmada iki alıştan sonra yavaş ve uzun bir nefes verme gelir. Baş dönmesi ya da rahatsızlık olursa durmak her zaman doğru seçimdir.",takeaway:"Uzun bir nefes verişi, kısa bir mola olabilir.",sources:["cyclic-sighing","slow-breathing"],visual:{kind:"steps",title:"Döngüsel iç çekme (yaklaşık 5 dakika)",steps:[{label:"Yerleş",text:"Rahat otur; omuzlarını ve çeneni gevşet."},{label:"Burundan al",text:"Burundan yavaşça nefes al."},{label:"Kısa bir alış daha",text:"Akciğerlerin dolunca kısa bir nefes daha ekle."},{label:"Ağızdan uzun ver",text:"Ağızdan yavaşça ve tamamen nefes ver."},{label:"Sürdür",text:"Kendi hızında yaklaşık 5 dakika tekrarla."}],note:"Baş dönmesi, nefes darlığı ya da rahatsızlık olursa dur ve normal nefesine dön. Bu bir tedavi değildir."}},{id:"calm-3",title:"Bedenini harekete geçir",minutes:7,goal:"Gününe sana uygun, kısa bir hareket molası yerleştir.",reading:["Singh ve arkadaşları 97 sistematik derlemeyi, toplam 1.039 randomize çalışmayı ve 128.119 katılımcıyı bir araya getirdi. Fiziksel aktivite depresyon, kaygı ve psikolojik sıkıntı belirtilerinde azalma gösterdi; biraz daha tempolu aktivite daha fazla iyileşmeyle, 12 hafta ya da daha kısa programlar en büyük etkiyle ilişkiliydi. Yani maraton koşman gerekmiyor.","Bu derlemelerin 97’sinden 77’si kalite ölçütüne göre kritik düzeyde düşük kalitedeydi; sayıları kesin sonuç değil, yön gösteren bulgular olarak oku. NHS de egzersizin stresi yok etmeyeceğini ama duygusal yoğunluğu bir miktar azaltabileceğini söyler. Hareket, depresyon ya da kaygı bozukluğunda profesyonel tedavinin yerine geçmez; bir sağlık sorunun varsa temponu hekiminle konuş."],practice:["Bugün yapabileceğin bir hareket seç: tempolu yürüyüş, merdiven çıkmak ya da birkaç dakika dans.","Bu hareketi gününde zaten olan bir ana bağla; örneğin öğle yemeğinden sonra kısa bir yürüyüş.","Hareketten önce ve sonra gerginliğini 0’dan 10’a kadar puanla ve farkı not et."],reflection:"Hangi hareket sana ceza gibi değil, mola gibi geliyor?",question:"Singh 2023 şemsiye derlemesi nasıl okunmalı?",options:["Hareket belirtilerde azalmayla ilişkili, ama derlemelerin çoğunun kalitesi düşük.","Egzersiz yapan herkesin kaygısı kesin olarak geçer.","Egzersiz yapıyorsam ilaca ya da terapiye gerek kalmaz."],correct:0,feedback:"Bulgular hareketin yardımcı olabileceğini gösteriyor; ancak derlemelerin çoğu kritik düzeyde düşük kalitedeydi ve hareket, gerektiğinde alınan profesyonel tedavinin yerine geçmez.",takeaway:"Kısa ve düzenli bir hareket, zor bir günde sana alan açabilir.",sources:["activity-mood","nhs-stress-tips","who-stress"],visual:{kind:"bars",title:"Fiziksel aktivite sonrası belirtilerde azalma",bars:[{label:"Depresyon belirtileri",value:.43,display:"0,43 azalma"},{label:"Kaygı belirtileri",value:.42,display:"0,42 azalma"},{label:"Psikolojik sıkıntı",value:.6,display:"0,60 azalma"}],note:"97 derleme, 1.039 randomize çalışma; medyan standart etki büyüklüğü (kaynakta eksi işaretli, azalmayı gösterir). Derlemelerin 97’sinden 77’si kritik düzeyde düşük kalitede; bu kısa kurs sınanmadı.",sourceId:"activity-mood"}},{id:"calm-4",title:"Açıyı değiştir",minutes:8,goal:"Zorlayan bir durumu bastırmak yerine farklı bir açıdan okumayı dene.",reading:["Webb, Miles ve Sheeran 306 deneysel karşılaştırmayı birleştirdi. Durumu yeniden değerlendirmek (“Bu başka ne anlama gelebilir?”) ve dışarıdan bir gözlemcinin bakış açısını almak, en etkili stratejiler arasındaydı. Olayı hiç düşünmemeye çalışmak ise işe yaramadı; ortalama etkisi sıfırın biraz altındaydı.","Bu çalışmaların çoğu laboratuvarda, kısa süreli uyandırılan duygularla yapıldı; gündelik hayattaki uzun süreli strese veya klinik gruplara doğrudan genellenemez. Yeniden değerlendirmek, durumu güzelmiş gibi göstermek ya da bir haksızlığı kabullenmek değildir. NHS’in önerdiği gibi değiştirebileceğin kısmı seçip değiştiremeyeceğini kabul etmek de bu yeni açının parçası olabilir."],practice:["Son günlerde seni geren bir durumu tek cümleyle yaz.","“Bu durum başka ne anlama gelebilir?” diye sor ve en az iki farklı açıklama bul.","Durumun tarafsız bir gözlemciye nasıl görüneceğini düşün ve aynı şeyi yaşayan bir arkadaşına söyleyeceğin cümleyi kendine söyle."],reflection:"Durumu başka bir açıdan okuyunca ne değişti, ne aynı kaldı?",question:"Webb 2012 meta-analizinde hangisi daha etkili bir strateji olarak öne çıktı?",options:["Olayı hiç düşünmemeye çalışmak.","Durumu dışarıdan bir gözlemcinin gözüyle görmeye çalışmak.","Olumsuz duyguya takılıp sürekli üzerine düşünmek."],correct:1,feedback:"Perspektif almak ve durumu yeniden değerlendirmek en etkili stratejiler arasındaydı; düşünceleri bastırmak ise işe yaramadı. Bu bulgular çoğunlukla kısa laboratuvar deneylerinden gelir.",takeaway:"Duyguyu itmek yerine duruma başka bir açıdan bak.",sources:["emotion-regulation","nhs-stress-tips"],visual:{kind:"bars",title:"Duygu düzenleme stratejilerinin ortalama etkisi",bars:[{label:"Perspektif almak",value:.45,display:"d+ = 0,45"},{label:"Durumu yeniden değerlendirmek",value:.36,display:"d+ = 0,36"},{label:"Düşünceleri bastırmak",value:.12,display:"d+ = −0,12 · ters yönde"}],note:"306 deneysel karşılaştırma, çoğu kısa süreli laboratuvar çalışması. Düşünceleri bastırmanın etkisi sıfırın altındaydı; çubuk yalnızca büyüklüğü gösterir.",sourceId:"emotion-regulation"}},{id:"calm-5",title:"Destek ve yardım zamanı",minutes:8,goal:"Güvendiğin destekleri belirle ve profesyonel yardım gerektiren durumları tanı.",reading:["DSÖ, stresle baş etmek için düzenli bir günlük rutin, düzenli uyku ve egzersiz, güvendiğin kişilerle bağlantıda kalıp duygularını paylaşmayı ve haber ile sosyal medya tüketimini azaltmayı önerir. NHS de arkadaş, aile ve iş arkadaşlarından oluşan bir destek ağının sorunları hafifletebileceğini, konuşmanın çözüm bulmaya yardım edebileceğini söyler. Stresi alkol, sigara, kumar ya da maddeyle atmaya çalışmak ise önerilmez.","Stresle baş edemiyorsan ya da denediğin öz-yardım yolları işe yaramıyorsa bir hekime veya sağlık profesyoneline başvurabilirsin; bu kurs tanı ya da tedavi değildir. Yardım istemek bir zayıflık değil, kendine gösterdiğin özendir. Kendine zarar verme düşüncen varsa ya da acil bir tehlike varsa 112’yi ara."],practice:["Zor bir günde arayabileceğin ya da yazabileceğin iki güvendiğin kişiyi belirle.","Bu hafta birine nasıl olduğunu anlatacağın ya da küçük bir destek isteyeceğin bir an seç.","Yardım tablosuna bakarak hangi durumda kime başvuracağını kendi notuna yaz."],reflection:"Zor bir günde ilk kime ulaşmak istersin?",question:"Kendine zarar verme düşüncesi ya da acil bir tehlike varsa ne yapmalısın?",options:["Kursun kalan alıştırmalarını bitirip beklemek.","Kimseye yük olmamak için kendi başıma idare etmek.","112’yi aramak ve mümkünse yanımda birinin olmasını istemek."],correct:2,feedback:"Acil bir tehlike varsa 112’yi ara. Nefes, hareket ve bakış açısı alıştırmaları gündelik stres içindir; acil durumda ya da stres baş edilemez hâle geldiğinde profesyonel yardımın yerini tutmaz.",takeaway:"Destek istemek de bir baş etme becerisidir.",sources:["who-stress","nhs-stress","nhs-stress-tips"],visual:{kind:"table",title:"Hangi durumda hangi destek?",columns:["Durum","Olası adım"],rows:[["Gündelik gerginlik, zor bir gün","Nefes, hareket, güvendiğin biriyle konuşmak"],["Stresle baş edemiyorsun","Hekime ya da sağlık profesyoneline başvur"],["Öz-yardım işe yaramıyor","Bir sağlık profesyoneliyle seçenekleri konuş"],["Kendine zarar verme düşüncesi ya da acil tehlike","112’yi ara"]],note:"NHS ve DSÖ önerilerine dayanır; Türkiye’de acil durumlarda 112 aranır. Bu tablo tıbbi değerlendirme değildir."}}]},Ea=[{id:"fresh-start-effect",title:"Dai, Milkman & Riis · 2014 · Yeni başlangıç etkisi",url:"https://faculty.wharton.upenn.edu/wp-content/uploads/2014/06/Dai_Fresh_Start_2014_Mgmt_Sci.pdf",type:"research",finding:"Üç alan verisinde yeni bir dönemin başında hedefe yönelik davranışlar arttı: “diyet” için Google aramaları hafta başında %14,4, yıl başında %82,1; 11.912 üniversite öğrencisinin spor salonu ziyaretleri hafta başında %33,4, dönem başında %47,1; stickK sitesinde hedef taahhüdü oluşturma hafta başında %62,9, yıl başında %145,3 arttı.",limitation:"Gözlemsel alan verileridir ve mekanizmayı doğrudan sınamaz; çoğunlukla toplumsal takvim işaretlerine bakar ve artan isteğin ne kadar sürdüğünü göstermez. Yazarlar, resmî tatil sonrasındaki artışın hızla söndüğünü belirtir."},{id:"fresh-start-framing",title:"Dai, Milkman & Riis · 2015 · Zaman işaretleri ve hedefe başlama deneyleri",url:"https://anderson-review.ucla.edu/wp-content/uploads/2021/03/Dai-Milkman-Riis_2015_TemporalLandmarks_APS_0956797615605818.pdf",type:"research",finding:"Beş deneyde bir günü yeni başlangıç gibi sunmak hedefe başlama isteğini artırdı: 165 katılımcıda 20 Mart “Baharın ilk günü” diye sunulduğunda o gün için hedef hatırlatıcısı seçenlerin oranı %25,6, “Mart’ın üçüncü perşembesi” diye sunulduğunda %7,2 idi. Etki, geçmişteki kusurlu benlikten psikolojik olarak uzaklaşmayla açıklandı.",limitation:"Çevrim içi katılımcılarla yapılan kısa deneylerdir; ölçümler çoğunlukla niyet, hatırlatıcı seçimi ve varsayımsal senaryolardır. Gerçek ve kalıcı davranış değişimini göstermez."},{id:"bandura-self-efficacy",title:"Bandura · 1977 · Öz yeterlik kuramı",url:"https://eric.ed.gov/?id=EJ161632",type:"research",finding:"Bandura, psikolojik değişimin öz yeterlik, yani bir davranışı yapabileceğine dair beklenti üzerinden işlediğini öne sürer; bu beklentinin dört kaynağı başarı deneyimleri, başkalarını izlemek, sözel ikna ve bedensel durumdur. Başarı deneyimlerini kişisel ustalığa dayandığı için en etkili kaynak sayar ve tekrarlanan başarılarla güçlenen bir inancın ara sıra yaşanan başarısızlıklardan daha az etkilendiğini yazar.",limitation:"Psychological Review’da yayımlanmış kuramsal bir makaledir; yeni bir deney ya da etki büyüklüğü sunmaz ve büyük ölçüde o dönemin korku tedavisi çalışmalarına dayanır."},{id:"self-efficacy-work-meta",title:"Stajkovic & Luthans · 1998 · Öz yeterlik ve iş performansı meta-analizi",url:"https://doi.org/10.1037/0033-2909.124.2.240",type:"research",finding:"114 çalışmayı (157 etki büyüklüğü, 21.616 kişi) birleştiren meta-analizde öz yeterlik ile iş performansı arasında anlamlı ve orta düzeyde bir ilişki bulundu (ağırlıklı ortalama r = 0,38).",limitation:"Yalnızca özet okundu. İlişkisel bir bulgudur; öz yeterliğin performansı ne ölçüde doğurduğunu tek başına göstermez ve iş ortamındaki görevlerden gelir."},{id:"todo-list-bedtime",title:"Scullin ve ark. · 2018 · Yatmadan önce yapılacaklar listesi ve uykuya dalma",url:"https://pmc.ncbi.nlm.nih.gov/articles/PMC5758411/",type:"research",finding:"18–30 yaş arası 57 sağlıklı genç yetişkin, uyku laboratuvarında yatmadan önce 5 dakika ya önümüzdeki günlerde yapacaklarını ya da son günlerde tamamladıklarını yazdı. Yapılacaklar listesi yazanlar daha hızlı uykuya daldı ve liste ne kadar ayrıntılıysa uykuya dalma o kadar hızlıydı.",limitation:"Tek bir laboratuvar gecesinde küçük ve genç bir örneklemle yapıldı; uykusuzluk yaşayanlarda ya da uzun vadede aynı etkinin görülüp görülmeyeceğini göstermez. Yalnızca özet okundu."},{id:"franklin-daily-questions",title:"Benjamin Franklin · Otobiyografi · Sabah ve akşam soruları",url:"https://www.gutenberg.org/ebooks/20203",type:"technique",finding:"Franklin, erdemlerini izlediği planın parçası olarak gününü saat saat düzenlediği bir çizelge anlatır: sabah kalkıp günün işini planlarken “Bugün hangi iyiliği yapacağım?”, akşam günü gözden geçirirken “Bugün hangi iyiliği yaptım?” diye sorar.",limitation:"Kamu malı, tarihî bir öz anlatımdır; bilimsel olarak sınanmış bir yöntem değildir. Sorular burada Türkçeye uyarlanmıştır."},{id:"oettingen-woop-method",title:"Gabriele Oettingen · WOOP · Rethinking Positive Thinking (2014)",url:"https://woopmylife.org/en/home",type:"technique",finding:"Oettingen’in WOOP yöntemi dört adımdır: dilek, en iyi sonuç, iç engel ve plan. Yalnızca olumlu hayal kurmak yerine istenen sonucu önündeki gerçek engelle karşılaştırmayı ve engel için eğer/o zaman planı yapmayı önerir.",limitation:"Yöntemin dayandığı zihinsel karşılaştırma ve eğer/o zaman planı araştırmalarda küçük–orta ortalama etki gösterdi; resmî site yöntemi geliştirenlere aittir, bağımsız bir değerlendirme değildir."},{id:"clear-two-minute-rule",title:"James Clear · İki dakika kuralı · Atomic Habits (2018)",url:"https://jamesclear.com/how-to-stop-procrastinating",type:"technique",finding:"Kural iki parçadır: David Allen’ın iki dakikadan kısa sürecek işi hemen yapma önerisi ve Clear’ın yeni bir alışkanlığa başlarken ilk adımın iki dakikadan kısa sürmesi gerektiği uyarlaması; örneğin bir saat okumak yerine bir sayfa okumak.",limitation:"Pratik bir öneridir; kuralın kendisi kontrollü çalışmalarla doğrudan sınanmamıştır."},{id:"fogg-anchor-recipe",title:"BJ Fogg · Tiny Habits (2019)",url:"https://tinyhabits.com/",type:"technique",finding:"Stanford’daki Davranış Tasarımı Laboratuvarı’nı yöneten Fogg, yeni davranışı çok küçültmeyi, onu her gün zaten yapılan bir “çapa” eylemin hemen arkasına bağlamayı ve yaptıktan hemen sonra kısa bir kutlama yapmayı önerir.",limitation:"Aynı bağlamda tekrarın alışkanlığı güçlendirdiği bulgularla uyumludur; ancak yöntemin kendisi, özellikle kutlama adımı, bağımsız randomize çalışmalarla sınırlı ölçüde sınanmıştır."},{id:"seinfeld-chain-story",title:"Jerry Seinfeld’e atfedilen “Zinciri koparma” · James Clear’ın aktarımı",url:"https://jamesclear.com/stop-procrastinating-seinfeld-strategy",type:"technique",finding:"Hikâyeye göre her gün yapılan iş için duvar takvimine bir çarpı konur ve amaç oluşan zinciri koparmamaktır; böylece odak tek günün sonucundan sürekliliğe kayar.",limitation:"Komedyen Brad Isaac’in Lifehacker’a anlattığı bir anekdottur; Clear’ın notuna göre Seinfeld fikrin kendisine ait olmadığını ve yöntemi kullandığını iddia etmediğini söylemiştir. Yöntem doğrudan sınanmamıştır."}],Ka={id:"turning-day",title:"Dönüm Noktası Günü",subtitle:"Bir gün, ilk kanıt.",description:"Tek bir günü beş kısa oturumla gerçek bir başlangıca çevir: yön seç, engeli planla, ilk küçük adımı at ve sonraki 7 günde bunu kanıta dönüştür. Özgüven, bu küçük kanıtlarla büyür.",scope:"Yetişkinler için kişisel gelişim eğitimi; terapi, tanı veya tedavi değildir ve tek bir günde hayatının değişeceğine dair söz vermez. Sürdürdüğün tedaviyi veya ilacı hekimine danışmadan bırakma. Yoğun kaygı, çökkünlük ya da günlük işlerini zorlaştıran bir sıkıntı yaşıyorsan bir sağlık profesyoneline başvur; kendine zarar verme düşüncen ya da acil bir tehlike varsa 112’yi ara.",outcome:"Seçtiğin bir alan ve nedeni, bir eğer/o zaman planı, bugün atılmış ilk küçük adım, hazırlanmış bir ortam, bir destekçi, yazılı bir kanıt notu ve 7 günlük takip planı.",photo:{id:"1570821805833-1103c43f9c1d",alt:"Ağaçlar arasındaki patikaya süzülen güneş ışınları"},lessons:[{id:"turning-day-1",title:"Sabah · Yön: bugünü başlangıç olarak işaretle",minutes:7,goal:"Sabah bugünü yeni bir başlangıç olarak işaretle; tek bir alan ve o alan için sana önemli gelen bir neden seç.",reading:["Dai, Milkman ve Riis 2014’te yeni bir dönemin başında insanların hedeflere daha çok yöneldiğini gösterdi. Örneğin “diyet” için Google aramaları hafta başında %14,4, yıl başında %82,1 arttı; üniversite spor salonu ziyaretleri hafta başında %33,4, dönem başında %47,1 arttı. Araştırmacılar buna yeni başlangıç etkisi dedi. Ama bu veriler gözlemseldir ve bu isteğin ne kadar sürdüğünü göstermez; resmî tatil sonrasındaki artışın hızla söndüğü de görüldü.","Aynı ekip 2015’te bir günün nasıl adlandırıldığının da önemli olduğunu buldu: 20 Mart “Baharın ilk günü” diye sunulduğunda katılımcıların %25,6’sı o gün için hedef hatırlatıcısı seçti, “Mart’ın üçüncü perşembesi” denince bu oran %7,2’de kaldı. Yani başlamak için takvimin sana özel bir gün vermesini beklemek zorunda değilsin; bugünü sen işaretleyebilirsin. Yine de bu deneyler çoğunlukla niyeti ölçtü; tek bir gün hayatını değiştirmez, onu sonraki günlerde tekrarlanan küçük adımlar kanıta çevirir. Bu yüzden sabahın işi büyük bir söz değil, tek bir alan ve güçlü bir “neden”."],practice:["Bugünün tarihini yaz ve yanına “Başlangıç günüm” diye not düş.","Sağlık, ilişkiler, iş ya da öğrenme gibi alanlardan bugün için yalnızca birini seç.","Bu alanın neden önemli olduğunu “Çünkü benim için … değerli” diye tek cümleyle yaz ve uygulamadaki Bugün ekranına günün tek kararı olarak ekle."],reflection:"Bugünü başlangıç olarak işaretlediğinde içinde ne değişti, ne aynı kaldı?",question:"Yeni başlangıç etkisi araştırmaları neyi gösteriyor?",options:["Yeni bir dönemin başında hedefe yönelme isteği artabiliyor; kalıcı olup olmayacağı sonraki adımlara bağlı.","Bir pazartesi ya da yeni yıl, hedefe ulaşmayı tek başına garanti eder.","Başlamak için mutlaka takvimde özel bir gün beklemek gerekir."],correct:0,feedback:"Zaman işaretleri başlama isteğini artırabiliyor ve bugünü sen de başlangıç olarak işaretleyebilirsin. Ama bu isteğin hızla sönebildiği de görüldü; kalıcılığı sonraki günlerin küçük tekrarları belirler.",takeaway:"Bugün bir başlangıç olabilir; kanıtı sonraki günler getirir.",sources:["fresh-start-effect","fresh-start-framing","franklin-daily-questions","dispenza-breaking-habit","mental-practice"],visual:{kind:"bars",title:"Aynı gün, farklı ad: hatırlatıcı seçenler",bars:[{label:"“Baharın ilk günü” diye sunulunca",value:25.61,display:"%25,6"},{label:"“Mart’ın üçüncü perşembesi” diye sunulunca",value:7.23,display:"%7,2"}],note:"165 çevrim içi katılımcıda 20 Mart için hedef hatırlatıcısı seçenlerin oranı (Dai, Milkman ve Riis 2015, 1a. çalışma). Niyet ve hatırlatıcı seçimini ölçer; kalıcı davranış değişimini göstermez.",sourceId:"fresh-start-framing"},technique:{name:"Sabah sorusu ve “bugün kim olmayı seçiyorum?” provası",origin:"Dr. Joe Dispenza · Breaking the Habit of Being Yourself (2012); sabah sorusu: Benjamin Franklin’ın günlük planı",steps:["Uyanınca telefona bakmadan önce 3–5 dakika sessizce otur ve birkaç yavaş nefes al.","Franklin’ın sabah sorusunu kendine sor: “Bugün hangi iyiliği yapacağım?”","Bugün bırakmak istediğin tek bir eski tepkini adıyla fark et; örneğin “erteleyen ben”.","“Bugün kim olmayı seçiyorum?” diye sor ve cevabı tek bir özellikle ver: sakin, cesur ya da düzenli.","Bu hâlde günün tek bir anını zihninde canlandır: nerede olduğunu, ne yaptığını ve nasıl hissettiğini gör.","Gözlerini açınca bu provadan bugün yapacağın tek bir küçük davranışı seç ve yaz."],evidence:"Zihinsel prova, özellikle gerçek bir planla birleştiğinde bir davranışa hazırlanmada yardımcı olabilir. Kitaptaki kuantum fiziğiyle açıklanan gerçeklik değişimi ya da düşünceyle hastalık iyileştirme iddiaları ise bilimsel olarak desteklenmiyor; provayı eylemin yerine değil, öncesine koy.",sourceId:"dispenza-breaking-habit"},photo:{id:"1676475382103-54041209cf6c",alt:"Kahve fincanının yanında deftere not alan kadın"}},{id:"turning-day-2",title:"Öğle · Engeli gör, eğer/o zaman planını kur",minutes:8,goal:"Öğle arasında sabah seçtiğin alan için gerçekçi bir iç engel bul ve ona karşı bir eğer/o zaman planı yaz.",reading:["Psikolog Gabriele Oettingen, yalnızca güzel sonucu hayal etmenin insanı rahatlatıp harekete geçme enerjisini azaltabileceğini savunur. Önerisi, istenen sonucu düşündükten hemen sonra önündeki gerçek engele de bakmaktır; buna zihinsel karşılaştırma denir. Wang, Wang ve Gai’nin 21 çalışmayı ve 15.907 katılımcıyı kapsayan meta-analizinde bu karşılaştırma, eğer/o zaman planıyla birleştiğinde hedefe ulaşmada küçük–orta bir ortalama etki gösterdi. Yayın yanlılığı olası ve sonuçlar kişiye göre değişiyor.","Eğer/o zaman planı, engelin ne zaman ve nerede çıkacağını önceden yazıp cevabını da hazırlamaktır: “Eğer öğleden sonra yorgun hissedersem, o zaman yalnızca iki dakikalık kısmı yapacağım.” Gollwitzer ve Sheeran’ın 94 testi birleştiren meta-analizinde bu tür planlar hedefe ulaşmada orta–büyük bir etki gösterdi (d = 0,65); yayın yanlılığını düzelten analizlerde bu sayı küçülebilir. Engel çoğu zaman dışarıda değil içeridedir: yorgunluk, utanç ya da “sonra yaparım” düşüncesi. Onu önceden adlandırmak, anı geldiğinde seni hazırlıksız bırakmaz."],practice:["Kısa bir yürüyüşte ya da öğle molasında sabah seçtiğin alan için dileğini tek cümleyle söyle.","Bugün seni en çok durdurabilecek iç engeli adıyla yaz: yorgunluk, utanç ya da erteleme düşüncesi gibi.","“Eğer … olursa, o zaman … yapacağım” cümlesini tamamla ve telefonunda kolay bulacağın bir yere kaydet."],reflection:"Bugün seni en çok hangi iç ses durdurabilir ve ona hazır cevabın ne?",question:"WOOP’ta en iyi sonucu hayal ettikten sonra hangi adım gelir?",options:["Sonucu daha da ayrıntılı hayal edip engelleri hiç düşünmemek.","Önündeki gerçek iç engeli bulmak ve ona karşı bir plan yazmak.","Engel çıkmaması için hedefi hiç kimseye söylememek."],correct:1,feedback:"WOOP’ta hayal edilen sonucun ardından asıl iç engel bulunur ve ona bir eğer/o zaman planı yazılır. Bu ikisi birlikte meta-analizde küçük–orta bir ortalama etki gösterdi; bir garanti değil, hazırlıklı olmanın yoludur.",takeaway:"Hayal yön verir; engel planı yol açar.",sources:["mcii","if-then-plans","oettingen-woop-method"],visual:{kind:"compare",title:"Yalnızca hayal mi, hayal ve plan mı?",left:{label:"Yalnızca olumlu hayal",items:["Her şey kendiliğinden yoluna girecek.","Yarın bambaşka biri olacağım.","Engel mi? Düşünmeme gerek yok."]},right:{label:"Hayal + engel + plan",items:["Dileğim: bu hafta her gün kısa bir yürüyüş.","Engelim: akşam yorgunluğu ve “yarın yaparım” düşüncesi.","Eğer yorgunsam, o zaman yalnızca 10 dakika yürüyeceğim."]},note:"Zihinsel karşılaştırma ve eğer/o zaman planı birlikte küçük–orta bir ortalama etki gösterdi; bu kısa ders ayrıca sınanmadı."},technique:{name:"WOOP",origin:"Gabriele Oettingen · Rethinking Positive Thinking (2014)",steps:["Birkaç dakikalık sakin bir an ayır ve telefonunu sessize al.","Dilek: Bugün ya da bu hafta için zor ama ulaşılabilir bir dileğini birkaç kelimeyle yaz.","Sonuç: Bu dilek gerçekleşince yaşayacağın en güzel sonucu zihninde canlı biçimde gör.","Engel: Seni durdurabilecek, sende olan asıl engeli bul ve onu da aynı canlılıkla düşün.","Plan: “Eğer [engel] olursa, o zaman [davranış] yapacağım” cümlesini yaz.","Planı engelin çıkabileceği saatten biraz önce bir kez daha oku."],evidence:"Zihinsel karşılaştırma ve eğer/o zaman planının birlikte kullanımı meta-analizde hedefe ulaşmada küçük–orta bir ortalama etki gösterdi. Etki kişiye ve hedefe göre değişiyor; WOOP bir sonuç garantisi değil, engeli önceden görmeyi kolaylaştıran bir düşünme aracıdır.",sourceId:"oettingen-woop-method"},photo:{id:"1740815897057-a93a8cf98a70",alt:"Parkta ağaçlı yolda yürüyen kadın"}},{id:"turning-day-3",title:"Öğleden sonra · İlk kanıt: özgüven adımdan sonra gelir",minutes:8,goal:"Öğleden sonra seçtiğin alanda iki dakikalık ilk adımı at ve bunu özgüveninin ilk kanıtı olarak kaydet.",reading:["Psikolog Albert Bandura 1977’de öz yeterlik kavramını ortaya koydu: bir işi yapabileceğine dair inancın. Bandura’ya göre bu inancın dört kaynağı var: kendi başarı deneyimlerin, başkalarını izlemek, cesaretlendirici sözler ve bedenindeki durum. Bunların en etkilisi kendi başarı deneyimlerindir, çünkü doğrudan senin yaşadığına dayanır. Yani özgüvenin gelmesini beklemek yerine küçük bir başarıyı bugün kendin üretebilirsin.","Stajkovic ve Luthans’ın 114 çalışmayı ve 21.616 kişiyi kapsayan meta-analizinde öz yeterlik ile iş performansı arasında orta düzeyde bir ilişki bulundu (r = 0,38). Bu bir ilişkidir; hangisinin hangisini ne ölçüde doğurduğunu tek başına göstermez ve iş ortamlarından gelir. Bandura da tekrarlanan başarılarla güçlenen bir inancın ara sıra yaşanan aksiliklerden daha az sarsıldığını yazar. Bu yüzden bugünün amacı büyük bir başarı değil, küçük ama gerçek bir “yaptım” kanıtıdır."],practice:["Seçtiğin alanda iki dakikada bitebilecek en küçük ilk adımı belirle.","Zamanlayıcıyı iki dakikaya kur ve bu adımı şimdi, mükemmel olmasını beklemeden yap.","Bitince “Bugün … yaptım” cümlesini yaz ve bunu özgüven kanıtın olarak sakla."],reflection:"İlk adımı attıktan sonra kendine bakışında küçük de olsa ne değişti?",question:"Bandura’ya göre öz yeterliği en güçlü biçimde ne besler?",options:["Kendini tamamen hazır hissedene kadar beklemek.","Kendi yaşadığın küçük başarı deneyimleri.","Yalnızca başkalarından övgü duymak."],correct:1,feedback:"Bandura başarı deneyimlerini en etkili kaynak olarak görür. Övgü ve başkalarını izlemek de yardımcı olabilir, ama kendi yaptığın küçük şey en sağlam kanıttır.",takeaway:"Özgüven, atılmış adımın ardından gelir.",sources:["bandura-self-efficacy","self-efficacy-work-meta","clear-two-minute-rule"],visual:{kind:"table",title:"Öz yeterliğin dört kaynağı ve bugünkü karşılığı",columns:["Kaynak","Bugün nasıl kullanabilirsin?"],rows:[["Başarı deneyimi","İki dakikalık ilk adımı yap ve yazıya geçir"],["Başkalarını izlemek","Sana benzeyen ve bu yolu yürümüş birinin hikâyesine bak"],["Cesaretlendirici söz","Güvendiğin birinden ya da kendinden kısa bir destek cümlesi"],["Bedensel durum","Başlamadan önce birkaç yavaş nefes al; heyecanı olağan bir tepki olarak fark et"]],note:"Bandura başarı deneyimini en etkili kaynak sayar. Tablo bir tedavi planı değildir."},technique:{name:"İki dakika kuralı",origin:"David Allen · Getting Things Done; James Clear · Atomic Habits (2018)",steps:["Seçtiğin alanda yapmak istediğin davranışı yaz; örneğin düzenli yürümek.","Onu iki dakikada bitecek bir başlangıca küçült: ayakkabılarını giyip kapıdan çıkmak gibi.","Zamanlayıcıyı iki dakikaya kur ve yalnızca bu küçük başlangıcı yap.","Süre bitince devam etmek istersen et; bırakmak da kurala uygundur.","Yaptığını kanıt olarak not et; önemli olan miktar değil, başlamış olmak."],evidence:"İki dakika kuralının kendisi doğrudan sınanmış bir yöntem değil, pratik bir öneridir. Küçük ve başarılabilir adımların öz yeterliği besleyebileceği fikri Bandura’nın başarı deneyimi görüşüyle uyumludur; yine de tek başına büyük bir hedefe ulaşmayı garanti etmez.",sourceId:"clear-two-minute-rule"},photo:{id:"1758854486305-eb7621f1e2e4",alt:"Büyük kemerli pencerenin yanında masada çalışan kişi"}},{id:"turning-day-4",title:"Akşamüstü · Ortamı hazırla, bir kişiye söyle",minutes:7,goal:"Akşamüstü yarınki adımı ortamında kolaylaştır ve seni destekleyecek bir kişiye kararını anlat.",reading:["Lally ve arkadaşlarının 96 gönüllüyü 12 hafta izlediği çalışmada, bir davranışı her gün aynı bağlamda tekrarlamak onu giderek daha otomatik hâle getirdi. Bağlam; aynı saat, aynı yer ya da hemen önceki aynı eylem demek. Bu yüzden yarınki adımı hatırlamak için iradene değil ortamına güvenebilirsin: spor ayakkabısını kapının önüne koymak, kitabı yastığın üstüne bırakmak gibi. Adım ne kadar görünür ve kolaysa, yorgun bir anda başlamak o kadar az çaba ister.","Harkin ve arkadaşlarının 138 deneysel çalışmayı birleştiren meta-analizinde ilerlemeyi takip etmek hedefe ulaşmada ortalama bir fayda gösterdi (d = 0,40). Bu fayda, sonuçlar bir başkasına bildirildiğinde ya da paylaşıldığında ve yazılı olarak kaydedildiğinde daha büyüktü. Bu herkese ilan etmen gerektiği anlamına gelmez; seni yargılamayacak, destekleyici tek bir kişiye kısaca söylemek yeterli olabilir. Özel notlarını paylaşmak zorunda değilsin ve farklı hedefleri birleştiren bu sonuç senin durumunda farklı olabilir."],practice:["Yarınki ilk adım için gereken bir eşyayı şimdi görünür bir yere hazırla.","Yeni adımını her gün zaten yaptığın bir eylemin hemen arkasına bağla ve bunu tek cümle olarak yaz.","Destekleyici bir kişiye kararını anlat ve bir hafta sonra nasıl gittiğini ona söyleyeceğini belirt."],reflection:"Yarın bu adımı kolaylaştıracak en küçük ortam değişikliği ne olurdu?",question:"Harkin 2016 meta-analizinde ilerleme takibinin etkisi ne zaman daha büyüktü?",options:["Sonuçlar kimseye söylenmeden yalnızca akılda tutulduğunda.","Sonuçlar bildirildiğinde ya da paylaşıldığında ve yazılı olarak kaydedildiğinde.","Takip hiç yapılmayıp yalnızca hedef konduğunda."],correct:1,feedback:"Etki, sonuçlar bildirildiğinde ya da paylaşıldığında ve fiziksel olarak kaydedildiğinde daha büyüktü. Yine de paylaşmak zorunlu değil; seni destekleyen tek bir kişi yeterli olabilir.",takeaway:"Kolay bir ortam ve bir destekçi, iradene düşen yükü hafifletir.",sources:["habits","monitoring","fogg-anchor-recipe"],visual:{kind:"compare",title:"Zor ortam mı, kolay ortam mı?",left:{label:"Adımı zorlaştıran",items:["Ayakkabılar dolabın dibinde","Kitap rafta, telefon yastığın yanında","Kararını kimse bilmiyor"]},right:{label:"Adımı kolaylaştıran",items:["Ayakkabılar kapının önünde hazır","Kitap yastığın üstünde, telefon başka odada","Destekleyici bir kişi bir hafta sonra soracak"]},note:"Paylaşmak isteğe bağlıdır; seni yargılayacağını düşündüğün birine anlatmak zorunda değilsin."},technique:{name:"Çapa ve küçük davranış tarifi",origin:"BJ Fogg · Tiny Habits (2019)",steps:["Her gün zaten güvenilir biçimde yaptığın bir eylem seç; bu senin çapan olsun.","Yeni davranışını 30 saniyede yapılabilecek kadar küçült.","Tarifini yaz: “[Çapa] yaptıktan sonra [küçük davranış] yapacağım.”","Küçük davranışı yapar yapmaz kendine içten ve kısa bir kutlama yap; gülümsemek ya da “Güzel!” demek gibi.","Tarifi yarın aynı çapayla tekrarla; tutmazsa çapayı ya da davranışın boyutunu değiştir."],evidence:"Davranışı aynı bağlamda tekrarlamanın otomatikliği artırdığı fikri Lally ve arkadaşlarının bulgularıyla uyumludur. Tiny Habits yönteminin kendisi, özellikle kutlama adımı, bağımsız çalışmalarla sınırlı ölçüde sınanmıştır; bir öneri olarak dene.",sourceId:"fogg-anchor-recipe"},photo:{id:"1756312177615-e153c9db507d",alt:"Mutfakta telefonla konuşan kadın"}},{id:"turning-day-5",title:"Gece · Kanıtı yaz, yarını hazırla",minutes:8,goal:"Gece günün kanıtını yaz, aksayan yere nazik bir dille bak ve yarının ilk adımını netleştir.",reading:["Benjamin Franklin otobiyografisinde anlattığı günlük planında sabahı “Bugün hangi iyiliği yapacağım?” sorusuyla açar, akşamı “Bugün hangi iyiliği yaptım?” sorusuyla kapatır. Bu akşam sorusu, günü kusurlarınla değil kanıtlarınla kapatmanın basit bir yoludur. Bugün attığın küçük adımı, hazırladığın ortamı ya da konuştuğun kişiyi yazmak, özgüveninin dayanacağı somut bir kayıt olur. Bir şey aksadıysa onu da yargılamadan bir bilgi olarak not edebilirsin.","Wohl ve arkadaşlarının 119 öğrenciyle yaptığı çalışmada, ilk sınava erteleyerek hazırlandığı için kendini daha çok affedenler ikinci sınava daha az erteledi; bu bulgu deneysel değil, ilişkiseldir. Öz şefkat müdahaleleri de 56 randomize çalışmada stres ve kaygı belirtilerinde küçük–orta düzeyde azalma gösterdi. Scullin ve arkadaşlarının 57 genç yetişkinle yaptığı laboratuvar çalışmasında, yatmadan önce 5 dakika ayrıntılı bir yapılacaklar listesi yazanlar, tamamladıklarını yazanlardan daha hızlı uykuya daldı. Bu yüzden gecenin sırası şöyle: nazik bir değerlendirme, yarının tek ilk adımı ve sonra dinlenme."],practice:["Franklin’ın akşam sorusunu yanıtla ve bugünün kanıtını “Bugün … yaptım” diye yaz.","Aksayan bir şey olduysa, aynı durumdaki bir arkadaşına söyleyeceğin nazik cümleyi kendine yaz.","Yarının ilk adımını saat ve yer vererek tek satırda yaz ve uygulamadaki kanıt sayfana ekle."],reflection:"Bugün kendin hakkında hangi küçük kanıtı topladın?",question:"Bir aksaklıktan sonra hangi iç konuşma bu derse daha uygun?",options:["“Yine beceremedim, ben zaten böyleyim.”","“Bugün aksadı; neyin zorladığını gördüm, yarın adımı küçültüp yeniden deneyeceğim.”","“Hiç olmamış gibi davranıp bunu düşünmeyeceğim.”"],correct:1,feedback:"Kendini affetmek aksaklığı yok saymak değil, onu yargılamadan görüp yeniden denemektir. Wohl ve arkadaşlarının ilişkisel bulgusu, bu tutumun sonraki denemede daha az ertelemeyle birlikte görüldüğünü düşündürüyor.",takeaway:"Günü kanıtla kapat, yarını tek adımla aç.",sources:["franklin-daily-questions","self-forgiveness","self-compassion","todo-list-bedtime","murphy-subconscious"],visual:{kind:"table",title:"Gece kapanışı: dört kısa soru",columns:["Soru","Örnek cevap"],rows:[["Bugün hangi iyiliği yaptım?","İki dakika yürüdüm, ayakkabılarımı kapının önüne koydum."],["Ne zorladı?","Öğleden sonraki yorgunluk; eğer/o zaman planım işe yaradı."],["Kendime nazik cümlem","Başladım; bu küçük ama gerçek bir adım."],["Yarının ilk adımı","Sabah kahveden sonra, kapının önünden 10 dakikalık yürüyüş."]],note:"Ayrıntılı bir yapılacaklar listesi tek bir küçük laboratuvar çalışmasında daha hızlı uykuya dalmayla ilişkiliydi. Düşüncelerin hızlanırsa yazmayı bırak ve dinlenmeye dön."},technique:{name:"Uyku öncesi sakin telkin",origin:"Joseph Murphy · The Power of Your Subconscious Mind (1963)",steps:["Yatağa uzan, ışığı kıs ve birkaç yavaş nefesle bedenini gevşet.","Yarın için tek bir niyeti kısa, olumlu ve yapılabilir bir cümleye dönüştür; örneğin “Yarın kahveden sonra yürüyüşe çıkıyorum.”","Uyku ağırlaşırken bu cümleyi zorlamadan, bir ninni gibi içinden yavaşça birkaç kez tekrarla.","Bu adımı yaptığını kısa bir sahne olarak zihninde gör ve sakinliği fark et.","Zihnin kaygıya kayarsa cümleyi bırak ve yalnızca nefesine dön."],evidence:"Yatmadan önce yarının adımını net bir cümleye dökmek ve sakince prova etmek hazırlığa yardımcı olabilir; ayrıntılı bir yapılacaklar listesi yazmak küçük bir çalışmada daha hızlı uykuya dalmayla ilişkiliydi. Bilinçaltının istenen sonucu, parayı ya da iyileşmeyi kendiliğinden getireceği iddiası ise bilimsel olarak desteklenmiyor; sonucu ertesi gün atılan adım belirler.",sourceId:"murphy-subconscious"},photo:{id:"1768219565623-501f93ae384b",alt:"Akşam masa lambasının aydınlattığı çalışma masası"}},{id:"turning-day-6",title:"Sonraki 7 gün · Başlangıcı kanıta çevir",minutes:9,goal:"Önümüzdeki 7 gün aynı küçük adımı her gün tekrarla, takip et, kaçırılan günden hemen dön ve 7. gün geriye bak.",reading:["Tek bir gün hayatını değiştirmez; ama bir başlangıcı tekrar edilen bir davranışa çevirebilir. Lally ve arkadaşlarının çalışmasında bir davranışın yüksek bir otomatiklik düzeyine ulaşması kişiden kişiye 18 ile 254 gün arasında değişti; yani 7 gün bir alışkanlık için değil, ilk kanıt dizisi için makul bir süredir. Aynı çalışmada tek bir fırsatı kaçırmak alışkanlık oluşumunu belirgin biçimde bozmadı. Bu yüzden bir günü kaçırırsan her şey bitmiş sayılmaz.","Harkin ve arkadaşlarının meta-analizinde ilerlemeyi takip etmek hedefe ulaşmada ortalama bir fayda gösterdi ve bilgi yazılı olarak kaydedildiğinde etki daha büyüktü. Bu hafta her gün aynı küçük adımı yap ve bir işaret koy; uygulamadaki Bugün ekranında bunu günün tek kararı olarak yazabilirsin. Kaçırdığın bir gün olursa ertesi gün yalnızca en küçük hâlini yap: kural “asla iki gün üst üste kaçırma”. 7. gün haftalık geriye bakışta neyin işe yaradığını ve neyi küçülteceğini seç."],practice:["Bir takvime ya da kâğıda yedi kutu çiz ve adımı yaptığın her gün birini işaretle.","Bir günü kaçırırsan ertesi gün yapacağın en küçük hâlini şimdiden tek cümleyle yaz.","7. gün için on dakikalık bir geriye bakış zamanını şimdiden takvimine ekle."],reflection:"7 gün sonra kendin hakkında hangi cümleyi kanıtla söyleyebilmek isterdin?",question:"Bir günü kaçırdığında bu derse göre ne yapmalısın?",options:["Zincir koptu; baştan ve daha büyük bir hedefle başlamalıyım.","Ertesi gün adımın en küçük hâlini yapıp iki gün üst üste kaçırmamaya odaklanmalıyım.","Yeniden başlamak için bir sonraki pazartesiyi ya da ayın ilk gününü beklemeliyim."],correct:1,feedback:"Lally ve arkadaşlarının çalışmasında tek bir fırsatı kaçırmak alışkanlık oluşumunu belirgin biçimde bozmadı. Önemli olan hemen geri dönmek; yeniden başlamak için takvimde özel bir gün beklemen gerekmez, yarın da bir başlangıç olabilir.",takeaway:"Bir gün başlatır; tekrar eden günler kanıtlar.",sources:["habits","monitoring","seinfeld-chain-story"],visual:{kind:"steps",title:"Bir haftalık kanıt döngüsü",steps:[{label:"Yap",text:"Aynı küçük adımı aynı çapa ya da saatle yap."},{label:"İşaretle",text:"Takvimde ya da uygulamada o günün kutusunu işaretle."},{label:"Zorlanırsan",text:"Eğer/o zaman planına dön ya da adımı küçült."},{label:"Kaçırırsan",text:"Ertesi gün en küçük hâlini yap; iki gün üst üste kaçırma."},{label:"7. gün",text:"Geriye bak: ne işe yaradı, neyi değiştireceksin, devam mı?"}],note:"7 gün bir alışkanlığın oturması için değil, ilk kanıt dizisi için bir süredir; Lally ve arkadaşlarının çalışmasında bu süre kişiden kişiye 18 ile 254 gün arasında değişti."},technique:{name:"Zinciri koparma, asla iki kez kaçırma",origin:"Jerry Seinfeld’e atfedilen hikâye (Brad Isaac’in anlatımı) · James Clear’ın aktarımı ve Atomic Habits (2018)",steps:["Duvara ya da masaya her gün göreceğin bir takvim as veya kâğıda yedi kutu çiz.","Küçük adımını yaptığın her gün o günün üzerine büyük bir çarpı ya da tik koy.","Birkaç gün sonra oluşan zinciri gör ve onu sürdürmeyi günlük hedefin yap.","Bir gün kaçırırsan kendini cezalandırma; ertesi gün adımın en küçük hâlini yap.","Kuralını “asla iki gün üst üste kaçırma” olarak koy ve 7. gün zincire bakıp planını güncelle."],evidence:"Hikâye bir anekdottur; James Clear’ın notuna göre Seinfeld fikrin kendisine ait olmadığını ve kullandığını iddia etmediğini söylemiştir. İlerlemeyi yazılı takip etmek meta-analizde ortalama bir fayda gösterdi ve tek bir günü kaçırmak alışkanlık oluşumunu belirgin biçimde bozmadı; zincir bir araçtır, kusursuzluk şartı değildir.",sourceId:"seinfeld-chain-story"},photo:{id:"1529651737248-dad5e287768e",alt:"Takvim defterinin üzerinde duran kalem"}}]},Ma=[{id:"meditation-goyal",title:"Goyal ve ark. · 2014 · Meditasyon programları meta-analizi",url:"https://jamanetwork.com/journals/jamainternalmedicine/fullarticle/1809754",type:"research",finding:"18.753 kayıt taranıp 47 randomize çalışma (3.515 kişi) dahil edildi. Farkındalık meditasyonu programları kaygıda (8. haftada 0,38; 3–6 ayda 0,22), depresyonda (0,30; 0,23) ve ağrıda (0,33) orta düzey kanıtla küçük iyileşmeler gösterdi; stres/sıkıntı ve ruh sağlığına bağlı yaşam kalitesi için kanıt düşüktü. Meditasyon programlarının ilaç, egzersiz veya diğer davranışsal tedaviler gibi etkin tedavilerden daha iyi olduğuna dair kanıt bulunmadı.",limitation:"Olumlu duygu, dikkat, uyku ve kilo gibi sonuçlarda kanıt yetersizdi ya da etki görülmedi. Programların süresi ve içeriği çok farklıydı; bu kısa kursun etkisi sınanmadı. Makale sayfasındaki özet ve temel bulgular okundu."},{id:"meditation-body-scan",title:"Gan, Zhang & Chen · 2022 · Beden taraması meta-analizi",url:"https://doi.org/10.1111/aphw.12366",type:"research",finding:"Tek başına uygulanan beden taramasını inceleyen 14 çalışmada beden taraması, pasif kontrole göre farkındalıkta yalnızca küçük bir artış gösterdi (g = 0,268). Yazarlar tek başına beden taramasının sağlıkla ilgili sonuçları iyileştirmek için yeterince etkili olmadığı sonucuna vardı; uzun süreli uygulamalarda bırakma oranı düşüktü.",limitation:"Çalışmaların kalitesi düşük, sonuçlar arasındaki farklılık yüksekti. Yalnızca özet okundu."},{id:"meditation-lovingkindness",title:"Zeng ve ark. · 2015 · Sevgi-şefkat meditasyonu meta-analizi",url:"https://www.frontiersin.org/journals/psychology/articles/10.3389/fpsyg.2015.01693/full",type:"research",finding:"24 çalışma (1.759 kişi): randomize çalışmalarda sevgi-şefkat meditasyonu, bekleme listesine göre günlük olumlu duyguları artırdı (yüksek uyarılmışlıklı olumlu duygular g = 0,395; düşük uyarılmışlıklı olumlu duygular g = 0,392). Sevgi-şefkat odaklı uygulamalar (g = 0,424), şefkat odaklı uygulamalardan (g = 0,286; güven aralığı sıfırı içeriyordu) daha net sonuç verdi.",limitation:"İncelenen çalışmaların %38,9’unda yanlılık riski yüksekti; beklenti etkisi ve gönüllülerin kendini seçmesi sonuçları şişirebilir. Yalnızca dört çalışma başka bir etkin yöntemle karşılaştırma yaptı ve analiz yalnızca olumlu duygulara odaklandı."},{id:"mental-practice",title:"Toth ve ark. · 2020 · Zihinsel pratik meta-analizi, 24 yıl sonra",url:"https://www.sciencedirect.com/science/article/abs/pii/S1469029219301530",type:"research",finding:"Driskell, Copper ve Moran’ın 1994 meta-analizini yöntemce tekrarlayan bu çalışma, 1995–2018 arasında yayımlanan 37 çalışmadan 115 etkiyi inceledi. Yayın yanlılığı analizlerinden sonra zihinsel pratiğin (bir görevi hareket etmeden zihinde prova etmek) performans üzerinde küçük ama anlamlı olumlu etkisi vardı (r = 0,131; 1994 analizinde r = 0,255). Etkiyi uygulama süresi, görev türü ve imgeleme türü değiştirdi.",limitation:"Çalışmalar çoğunlukla hareket ve beceri performansıyla ilgilidir; kişilik değişimi, duygu durumu ya da hastalık sonuçlarını sınamaz. Yayıncı sayfasındaki özet okundu."},{id:"meditation-adverse",title:"Farias ve ark. · 2020 · Meditasyonda olumsuz etkiler sistematik derlemesi",url:"https://pubmed.ncbi.nlm.nih.gov/32820538/",type:"research",finding:"6.742 kayıttan 83 çalışma (6.703 kişi) incelendi; olumsuz etkilerin toplam sıklığı %8,3’tü (deneysel çalışmalarda %3,7, gözlemsel çalışmalarda %33,2). En sık bildirilenler kaygı, depresyon ve bilişsel anormalliklerdi; olumsuz etkiler daha önce ruhsal sorunu olmayan kişilerde de görülebildi.",limitation:"Çalışmalar olumsuz etkileri farklı ve çoğu zaman eksik biçimde ölçtü; sıklık tahmini belirsizdir ve etkilerin ne kadarının doğrudan meditasyondan kaynaklandığı kesin değildir. Yalnızca özet okundu."},{id:"meditation-nccih",title:"NCCIH · Meditasyon ve farkındalık: etkililik ve güvenlik",url:"https://www.nccih.nih.gov/health/meditation-and-mindfulness-effectiveness-and-safety",type:"guidance",finding:"ABD Ulusal Tamamlayıcı ve Bütünleyici Sağlık Merkezi, meditasyonun genellikle az riskli kabul edildiğini ama zararlarla ilgili araştırmaların sınırlı olduğunu belirtir; 2020 tarihli bir derlemede katılımcıların yaklaşık %8’inin olumsuz etki yaşadığını aktarır. Meditasyonun olağan tıbbi bakımın yerine kullanılmamasını ve bir sağlık sorunu için hekime gitmeyi ertelemek için gerekçe yapılmamasını vurgular.",limitation:"ABD kaynaklı genel halk rehberidir; Türkiye’de acil durumlarda 112 aranır."},{id:"meditation-kabat-zinn",title:"Jon Kabat-Zinn · Full Catastrophe Living (gözden geçirilmiş baskı, 2013)",url:"https://www.penguinrandomhouse.com/books/89149/full-catastrophe-living-revised-edition-by-jon-kabat-zinn-preface-by-thich-nhat-hanh-foreword-by-joan-borysenko/",type:"technique",finding:"Kabat-Zinn, Massachusetts Üniversitesi Tıp Fakültesi’nde geliştirdiği farkındalığa dayalı stres azaltma (MBSR) programını anlatır: nefes farkındalığı, beden taraması, oturarak meditasyon, farkındalıkla yoga ve günlük etkinliklere dikkat getirme.",limitation:"Farkındalık programları araştırmalarda küçük–orta faydalar gösterdi, ama kitabı okumak eğitmenli sekiz haftalık programla aynı şey değildir. Kitap ve programlar tanı ya da tedavinin yerine geçmez."},{id:"meditation-benson",title:"Herbert Benson · Gevşeme tepkisi (Harvard Health özeti)",url:"https://www.health.harvard.edu/blog/a-once-and-future-meditator-tries-the-relaxation-response-for-stress-201110143598",type:"technique",finding:"Benson’ın yöntemi: gözler kapalı sessizce oturmak, kasları gevşetmek, seçilen bir kelime, ses, ifade ya da duayı içinden tekrar etmek ve araya giren düşünceleri geçip gitmeye bırakarak odak noktasına dönmek; her gün 10–20 dakika düzenli uygulamak.",limitation:"Bu sayfa bir blog yazısıdır ve sayısal araştırma verisi sunmaz. Yöntem bir tedavi değildir; tansiyon, kalp ya da sindirim sorunlarında hekim önerilerinin yerine geçmez."},{id:"meditation-thich-nhat-hanh",title:"Thich Nhat Hanh · Plum Village · Yürüyüş meditasyonu",url:"https://plumvillage.org/mindfulness/mindfulness-practice/walking-meditation",type:"technique",finding:"Plum Village, adımları nefesle eşleştirmeyi (nefes alırken iki üç, verirken üç dört adım), ayağın yere değdiği anı hissetmeyi, omuzları ve kolları gevşetmeyi ve dikkati çevredeki seslere ve görüntülere açmayı öğretir; bu yürüyüşün her yerde yapılabileceğini söyler.",limitation:"Geleneksel bir uygulama rehberidir; yürüyüş meditasyonuna özgü büyük ve kaliteli çalışmalar sınırlıdır. Trafikte ve kalabalıkta güvenlik önce gelir."},{id:"meditation-salzberg",title:"Sharon Salzberg · Lovingkindness (1995; 25. yıl baskısı 2020)",url:"https://www.sharonsalzberg.com/lovingkindness",type:"technique",finding:"Salzberg, Budist geleneğin dört niteliğini, yani sevgi dolu iyiliği, merhameti, başkasının sevincine sevinmeyi ve dinginliği; kısa iyi dilek cümlelerini önce kendine, sonra sırayla başkalarına yönelten meditasyonlarla anlatır.",limitation:"Sevgi-şefkat meditasyonu olumlu duygularda küçük–orta artışlarla ilişkilendirildi, ama çalışmaların önemli bir kısmında yanlılık riski yüksek. Zorlandığın birine iyi dilek göndermek, sınırlarından vazgeçmek anlamına gelmez."},{id:"dispenza-breaking-habit",title:"Dr. Joe Dispenza · Breaking the Habit of Being Yourself (2012)",url:"https://www.penguinrandomhouse.com/books/603255/breaking-the-habit-of-being-yourself-by-dr-joe-dispenza/",type:"technique",finding:"Dispenza, dört hafta boyunca adım adım genişleyen bir meditasyon önerir: bedene ve şimdiye yerleşmek, değiştirmek istenen eski duygu ve düşünce kalıbını fark edip kabul etmek, onu bırakmak, gün içinde devreye girdiği anları tanıyıp durdurmak ve olmak istenen yeni benliği duygusuyla birlikte zihinde prova etmek.",limitation:"Zihinsel prova ve alışkanlıkları fark etmek araştırmalarla uyumludur. Kitabın kuantum fiziğine dayanarak gerçekliği değiştirme, genleri etkileme ve hastalıkları düşünceyle iyileştirme iddiaları ise bilimsel olarak desteklenmez; tedavini bu yöntem nedeniyle değiştirme."}],Ya={id:"meditation",title:"Meditasyon nasıl yapılır",subtitle:"Nefesle başlayan dikkat.",description:"Nefes, beden taraması, kelime tekrarı, yürüyüş, sevgi-şefkat ve Dr. Joe Dispenza’nın zihinsel provasını adım adım dene. Her tekniğin araştırmada neyle desteklendiğini de dürüstçe öğren.",scope:"Yetişkinler için meditasyon eğitimi; tanı ya da tedavi değildir ve terapinin ya da ilacın yerine geçmez. Tedavini veya ilacını hekimine danışmadan bırakma. Travma, psikoz ya da ağır ruhsal sıkıntı geçmişin varsa meditasyonu bir ruh sağlığı uzmanıyla birlikte uygula. Uygulama sırasında sıkıntın artarsa, başın dönerse ya da kendini gerçeklikten kopuk hissedersen dur, gözlerini aç ve normal nefesine dön; gerekirse destek al. Kendine zarar verme düşüncen ya da acil bir durum varsa 112’yi ara.",outcome:"Denenmiş altı meditasyon tekniği, sana uyan günlük 10 dakikalık bir düzen, zor günler için yedek bir plan ve ne zaman durup yardım isteyeceğini gösteren bir liste.",photo:{id:"1522075782449-e45a34f1ddfb",alt:"Dağ manzarasına bakan bir bankta sessizce oturan kadın"},lessons:[{id:"meditation-1",title:"İlk oturuş: nefese dikkat",minutes:7,goal:"Beş dakika oturup nefesini izle; dikkatin dağıldığında bunu fark edip nazikçe geri dön.",reading:["Meditasyon zihni boşaltmak değildir. Bu kursta meditasyonu, dikkatini bilerek bir yere koymak ve kaçtığında fark edip geri getirmek olarak ele alacağız. Jon Kabat-Zinn’in geliştirdiği farkındalığa dayalı stres azaltma programında (MBSR) ilk adım çoğu zaman nefestir, çünkü nefes her an seninledir ve onu değiştirmeden izleyebilirsin. Zihnin bir dakikada on kez dağılabilir; her fark ediş alıştırmanın ta kendisidir.","Goyal ve arkadaşları 18.753 kaydı tarayıp 47 randomize çalışmayı (3.515 kişi) inceledi. Farkındalık meditasyonu programları kaygı, depresyon ve ağrıda küçük ama anlamlı iyileşmelerle ilişkiliydi ve bu bulguların kanıt düzeyi orta olarak değerlendirildi. Stres için kanıt düşüktü ve meditasyonun egzersiz, ilaç ya da diğer davranışsal tedavilerden daha iyi olduğuna dair bir bulgu yoktu. Yani meditasyon öğrenilebilen, işe yarayabilecek bir beceridir; mucize ya da tedavinin yerini tutan bir yol değildir."],practice:["Bir sandalyeye dik ama gerilmeden otur, ayaklarını yere bas ve 5 dakikalık bir zamanlayıcı kur.","Nefesin en belirgin hissedildiği yeri seç: burun ucu, göğüs ya da karın; nefesi değiştirmeden orada izle.","Dikkatin her kaçtığında içinden “düşünce” deyip nefese dön; kaç kez döndüğünü saymana gerek yok."],reflection:"Dikkatin en çok nereye kaçtı ve geri dönmek nasıl hissettirdi?",question:"Oturuş sırasında dikkatin sürekli dağılıyorsa bu ne anlama gelir?",options:["Meditasyon bana göre değil; bırakmalıyım.","Dağıldığını fark edip geri dönmek zaten alıştırmanın kendisidir.","Zihnimi tamamen boşaltana kadar kendimi daha çok zorlamalıyım."],correct:1,feedback:"Dağılmak olağandır. Farkındalık meditasyonunda amaç düşüncesiz bir zihin değil; fark etme ve nazikçe geri dönme becerisidir.",takeaway:"Fark edip geri dönmek, meditasyonun kendisidir.",sources:["meditation-goyal","meditation-kabat-zinn"],visual:{kind:"bars",title:"Farkındalık meditasyonu programlarının ortalama etkisi",bars:[{label:"Kaygı (8. hafta)",value:.38,display:"0,38"},{label:"Depresyon (8. hafta)",value:.3,display:"0,30"},{label:"Ağrı",value:.33,display:"0,33"}],note:"47 randomize çalışma, 3.515 kişi; standart etki büyüklüğü (küçük–orta). Kanıt düzeyi orta; stres için kanıt düşük ve etkin tedavilerden üstünlük gösterilmedi. Bu kısa kurs ayrıca sınanmadı.",sourceId:"meditation-goyal"},technique:{name:"Nefes farkındalığı",origin:"Jon Kabat-Zinn · Full Catastrophe Living (1990; gözden geçirilmiş baskı 2013)",steps:["Dik ama rahat bir duruş seç; gözlerini kapat ya da bakışını yere indir.","Nefesin bedeninde en belirgin hissedildiği yeri bul.","Nefesi kontrol etmeden gelişini ve gidişini merakla izle.","Dikkatin bir düşünceye kaydığında bunu yargılamadan fark et.","Nazikçe nefese dön; bunu gerektiği kadar tekrarla.","Bitirirken birkaç nefes boyunca bütün bedenini hisset, sonra gözlerini aç."],evidence:"Farkındalık programları kaygı, depresyon ve ağrıda orta düzey kanıtla küçük–orta faydalar gösterdi. Tek başına kısa nefes oturuşlarının etkisi daha az çalışıldı ve meditasyon etkin tedavilerden üstün bulunmadı.",sourceId:"meditation-kabat-zinn"},photo:{id:"1758273240112-c7724c9bb4a5",alt:"Evde yerde gözleri kapalı meditasyon yapan genç kadın"}},{id:"meditation-2",title:"Beden taraması",minutes:8,goal:"Dikkatini ayaklarından başına doğru bedeninde gezdir ve duyumları değiştirmeye çalışmadan fark et.",reading:["Beden taraması, MBSR programının ilk haftalarında öğretilen temel uygulamalardan biridir. Sırt üstü uzanır ya da oturur, dikkatini sırayla bedeninin bölgelerine taşırsın: ayak parmakları, bacaklar, karın, sırt, eller, omuzlar ve yüz. Amaç illa gevşemek değil; sıcaklık, basınç, karıncalanma ya da hiçbir şey hissetmemek dahil, orada ne varsa fark etmektir. Ağrılı ya da hassas bir bölgeye gelirsen oradan hızlıca geçebilir, dikkatini nefesine verebilirsin.","Gan ve arkadaşlarının 2022 meta-analizi, beden taramasını tek başına uygulayan 14 çalışmayı inceledi. Beden taraması pasif kontrole göre farkındalıkta yalnızca küçük bir artış gösterdi ve yazarlar, tek başına beden taramasının sağlıkla ilgili sonuçları iyileştirmek için yeterince etkili olmadığı sonucuna vardı. Çalışmaların kalitesi düşüktü ve sonuçlar birbirinden çok farklıydı. Bu yüzden beden taramasını mucizevi bir rahatlama tekniği olarak değil, daha geniş bir meditasyon düzeninin bir parçası olarak düşün."],practice:["Uzanabileceğin ya da rahat oturabileceğin bir yer seç ve 8–10 dakikalık bir zamanlayıcı kur.","Sol ayak parmaklarından başla; her bölgede birkaç nefes kal, sonra yavaşça yukarı doğru ilerle.","Bitince bedeninde en belirgin fark ettiğin üç duyumu tek kelimeyle adlandır."],reflection:"Bedeninin hangi bölgesini fark etmek sana yeni ya da şaşırtıcı geldi?",question:"Beden taramasında bir bölgede hiçbir şey hissetmiyorsan ne yaparsın?",options:["Hissedene kadar orayı sıkar ya da hareket ettiririm.","“Burada belirgin bir his yok” diye fark eder ve devam ederim.","Taramayı yanlış yaptığımı düşünüp en baştan başlarım."],correct:1,feedback:"Hissizlik ya da nötr bir duyum da bir gözlemdir. Beden taraması bir şey üretmeyi değil, olanı fark etmeyi çalıştırır.",takeaway:"Bedenini değiştirmeye çalışmadan dinle.",sources:["meditation-body-scan","meditation-kabat-zinn"],visual:{kind:"compare",title:"Beden taraması: beklenti ve uygulama",left:{label:"Sık görülen beklenti",items:["Her seferinde derin bir gevşeme olmalı.","Ağrıyı yok etmeliyim.","Uykuya dalarsam başarısız oldum."]},right:{label:"Uygulamada",items:["Ne hissediliyorsa onu fark ederim.","Zorlayan bir bölgeden nazikçe geçebilirim.","Uyuyakalırsam bir dahaki sefere oturarak denerim."]},note:"Uzanmak uykuya çekebilir; uyanık kalmak istiyorsan oturarak ya da gözlerin hafif açık dene."},technique:{name:"Beden taraması",origin:"Jon Kabat-Zinn · MBSR programı, Full Catastrophe Living",steps:["Sırt üstü uzan ya da rahat otur; birkaç nefes boyunca bedeninin yere değdiği noktaları hisset.","Dikkatini sol ayak parmaklarına götür ve oradaki duyumları merakla incele.","Nefes verirken o bölgeyi bırak ve dikkatini bir sonraki bölgeye taşı.","Ayaklardan bacaklara, gövdeye, kollara, boyuna ve başa doğru yavaşça ilerle.","Aklın dağıldığında nerede kaldığını hatırla ve oraya geri dön.","Sonda bütün bedenini tek bir bütün olarak birkaç nefes boyunca hisset."],evidence:"Tek başına beden taraması farkındalıkta küçük bir artış gösterdi, ama sağlık sonuçlarında belirgin bir etki bulunmadı; çoğunlukla daha geniş programların parçası olarak çalışılmıştır. Travma geçmişi olan bazı kişiler için bedene uzun süre odaklanmak zorlayıcı olabilir; gözlerini açık ve süreyi kısa tutabilirsin.",sourceId:"meditation-kabat-zinn"},photo:{id:"1535987271305-c26a8935f74a",alt:"Gün ışığında çimenlerin üzerinde uzanıp dinlenen kadın"}},{id:"meditation-3",title:"Gevşeme tepkisi: bir kelimeyle otur",minutes:7,goal:"Herbert Benson’ın yöntemiyle, seçtiğin bir kelimeyi tekrarlayarak 10 dakika otur.",reading:["Kardiyolog Herbert Benson 1970’lerde farklı meditasyon geleneklerindeki ortak öğeleri sade bir yönteme dönüştürdü ve buna gevşeme tepkisi adını verdi. Yöntemin iki temel öğesi var: bir kelime, ses, ifade ya da kısa bir duanın tekrarı ve araya giren düşüncelere karşı zorlamayan, edilgen bir tutum. Kelimeyi sen seçersin: “sakin” gibi nötr bir sözcük ya da sana anlamlı gelen kısa bir dua veya zikir olabilir. Benson her gün 10–20 dakika uygulamayı önerir.","Benson’ın vurguladığı nokta, tekniğin kendisinden çok düzenli uygulamadır. Kelimeyi doğru söyleyip söylemediğini ya da yeterince gevşeyip gevşemediğini denetlemen gerekmez; düşünce gelince kelimeye dönmek yeterlidir. Goyal meta-analizindeki orta düzey kanıtlı sayısal bulgular farkındalık programları içindi, bu yüzden bu kursta Benson yöntemine özgü kesin bir etki rakamı vermiyoruz. Yöntem bir tedavi değildir ve tansiyon ya da kalp sorunlarında hekim önerilerinin yerini tutmaz."],practice:["Sana iyi gelen kısa bir kelime, ifade ya da kısa bir dua seç.","Rahat otur, gözlerini kapat, kaslarını ayaklarından yüzüne doğru gevşet ve 10 dakikalık zamanlayıcı kur.","Her nefes verişte kelimeni içinden söyle; bir düşünce gelince “Olsun” deyip kelimene dön."],reflection:"Seçtiğin kelime sana ne hissettirdi, yarın aynı kelimeyi mi kullanacaksın?",question:"Benson’ın yönteminde araya düşünceler girerse ne yaparsın?",options:["Düşünceyi zorla bastırır, kafamı boşaltırım.","Oturuşu yarıda keserim; odaklanamıyorum demektir.","Zorlamadan “Olsun” der ve kelimeme dönerim."],correct:2,feedback:"Edilgen tutum yöntemin temelidir. Düşünceleri kovalamak ya da bastırmak yerine onları fark edip kelimeye dönmek yeterlidir.",takeaway:"Bir kelime, bir nefes, yeniden dönüş.",sources:["meditation-benson","meditation-goyal"],visual:{kind:"table",title:"Gevşeme tepkisinin dört öğesi",columns:["Öğe","Nasıl uygularsın?"],rows:[["Sessiz bir ortam","Kısa süre rahatsız edilmeyeceğin bir köşe"],["Odak kelime","“Sakin” gibi bir sözcük ya da sana anlamlı kısa bir dua veya zikir"],["Edilgen tutum","Düşünceleri kovalamadan kelimeye geri dön"],["Rahat duruş","Uykuya dalmayacağın, dik ve rahat bir oturuş"]],note:"Benson’ın önerisi her gün 10–20 dakikadır; sen daha kısa bir süreyle başlayabilirsin."},technique:{name:"Gevşeme tepkisi",origin:"Herbert Benson · The Relaxation Response (1975)",steps:["Sana anlamlı gelen kısa bir kelime, ses, ifade ya da dua seç.","Sessiz bir yerde rahat otur ve gözlerini kapat.","Kaslarını ayaklarından başlayarak yüzüne kadar sırayla gevşet.","Burnundan doğal nefes al; her nefes verişte seçtiğin kelimeyi içinden tekrarla.","Düşünceler geldiğinde onlarla uğraşmadan kelimene dön.","10–20 dakika sonra bir iki dakika gözlerin kapalı sessizce otur, sonra yavaşça kalk."],evidence:"Meditasyon programları genel olarak kaygı ve depresyonda küçük–orta faydalar gösterdi; Benson yöntemine özgü güçlü bir etki rakamını burada veremiyoruz. Yöntem bir tedavi değildir ve ilacın yerini tutmaz.",sourceId:"meditation-benson"},photo:{id:"1513097847644-f00cfe868607",alt:"Gün ışığında ahşap iskelede sessizce oturan kadın"}},{id:"meditation-4",title:"Yürüyüş meditasyonu",minutes:7,goal:"Adımlarını nefesinle eşleştirerek birkaç dakika yavaş ve farkında yürü.",reading:["Oturmak herkese kolay gelmez; bazen beden hareket etmek ister. Vietnamlı Zen öğretmeni Thich Nhat Hanh yürümeyi de bir meditasyon olarak öğretti: bir yere yetişmek için değil, attığın adımın içinde olmak için yürümek. Plum Village topluluğunun anlattığı biçimde nefes alırken iki üç, verirken üç dört adım atabilirsin; sayıyı nefesin ve temponu belirler. Ayağının yere değdiği anı hissetmek, dikkatini şimdiye bağlayan bir çapa olur.","Yürüyüş meditasyonu evde bir koridorda, parkta ya da işe giderken birkaç dakika uygulanabilir. Hareketin kendisi de iyi gelebilir: Singh ve arkadaşlarının şemsiye derlemesi fiziksel aktivitenin depresyon, kaygı ve sıkıntı belirtilerinde azalmayla ilişkili olduğunu gösterdi, ancak dahil edilen derlemelerin çoğunun kalitesi düşüktü. Yürüyüş meditasyonuna özgü güçlü bir meta-analize ulaşamadık; bu yüzden onu kanıtlanmış bir tedavi değil, denemeye değer bir uygulama olarak gör. Trafikte ya da kalabalıkta gözlerin açık olsun; güvenliğin her zaman önce gelir."],practice:["Evde ya da açık havada 10–15 adımlık sakin ve güvenli bir yol seç.","Nefes alırken iki üç, verirken üç dört adım at; sayıyı kendi ritmine göre ayarla.","Son iki dakikada adım saymayı bırak ve çevrendeki sesleri, ışığı ve havayı fark et."],reflection:"Yavaş yürürken çevrende daha önce fark etmediğin ne gördün ya da duydun?",question:"Yürüyüş meditasyonunda adım sayısı nasıl belirlenir?",options:["Herkes için sabittir: her nefeste dört adım.","Kendi nefes ritmine ve tempona göre ayarlanır.","Olabildiğince çok adım atmak hedeflenir."],correct:1,feedback:"Adım sayısı kişiden kişiye değişir. Önemli olan nefesle adım arasındaki uyumu ve ayağının yere değdiği anı fark etmektir.",takeaway:"Her adım, şimdiye dönmek için bir fırsat.",sources:["meditation-thich-nhat-hanh","activity-mood"],visual:{kind:"compare",title:"Sıradan yürüyüş ve yürüyüş meditasyonu",left:{label:"Sıradan yürüyüş",items:["Bir yere yetişmek için","Zihin planlarda ya da telefonda","Adımlar fark edilmeden atılır"]},right:{label:"Yürüyüş meditasyonu",items:["Adımın kendisi için","Dikkat ayakta ve nefeste","Her adım yere bilerek basılır"]},note:"Trafikte, merdivende ve kalabalıkta gözlerin açık olsun; güvenlik önce gelir."},technique:{name:"Nefesle yürüyüş",origin:"Thich Nhat Hanh · Plum Village geleneği",steps:["Acelen olmayan, güvenli ve kısa bir yol seç.","Durup birkaç nefes boyunca ayaklarının yere bastığını hisset.","Normalden biraz daha yavaş yürümeye başla; omuzlarını ve kollarını gevşet.","Nefes alırken attığın adımları, sonra nefes verirken attığın adımları say.","Aklın geçmişe ya da geleceğe gittiğinde dikkatini ayağının yere değdiği ana geri getir.","Bitirirken dur ve birkaç nefes boyunca çevrendeki sesleri ve renkleri fark et."],evidence:"Hareket, ruh sağlığı belirtilerinde azalmayla ilişkilidir; ancak yürüyüş meditasyonunun kendine özgü etkisi büyük ve kaliteli çalışmalarla yeterince sınanmamıştır. Onu, oturmakta zorlandığın günler için bir seçenek olarak gör.",sourceId:"meditation-thich-nhat-hanh"},photo:{id:"1477332552946-cfb384aeaf1c",alt:"Güneşli bir yolda yavaşça yürüyen kadın"}},{id:"meditation-5",title:"Sevgi-şefkat (metta)",minutes:8,goal:"Kısa iyi dilek cümlelerini önce kendine, sonra başkalarına yönelterek birkaç dakika uygula.",reading:["Metta, Budist gelenekte sevgi dolu iyilik anlamına gelir. Sharon Salzberg’in Lovingkindness kitabında anlattığı biçimde, birkaç kısa iyi dilek cümlesini sessizce tekrarlarsın; örneğin “Güvende olayım, huzurlu olayım, sağlıklı olayım.” Sonra aynı dilekleri sırayla sevdiğin birine, nötr bir tanıdığa, zorlandığın birine ve en sonunda bütün canlılara yöneltirsin. Sıcak bir his gelmezse sorun değil; bu uygulamada niyet, hissetmekten önce gelir.","Zeng ve arkadaşlarının 2015 meta-analizi 24 çalışmayı (1.759 kişi) inceledi. Randomize çalışmalarda sevgi-şefkat meditasyonu, bekleme listesine göre günlük olumlu duygularda küçük–orta bir artış gösterdi. Ancak incelenen çalışmaların %38,9’unda yanlılık riski yüksekti ve yalnızca dört çalışma başka bir etkin yöntemle karşılaştırma yaptı. Kendine iyi dilek göndermek başta yapay gelebilir; öz şefkat de ayrı araştırmalarda desteklenen bir beceridir."],practice:["Kendin için üç kısa iyi dilek cümlesi seç ya da dersteki cümleleri kullan.","Cümleleri önce kendine, sonra sevdiğin birine, sonra nötr bir kişiye içinden tekrarla.","Hazır hissedersen seni hafifçe zorlayan birine tek bir iyi dilek gönder; hazır değilsen bu adımı atla."],reflection:"Dilekleri kime yöneltmek en kolay, kime yöneltmek en zor geldi?",question:"Metta sırasında hiçbir sıcak duygu hissetmezsen ne yaparsın?",options:["Yöntemin bende işe yaramadığını düşünüp bırakırım.","Duyguyu zorla üretmeye çalışırım.","Niyetle tekrarlamaya devam ederim; his gelmese de alıştırma sürer."],correct:2,feedback:"Metta bir duygu üretme yarışı değildir. Cümleleri niyetle tekrarlamak alıştırmanın kendisidir; his bazen gelir, bazen gelmez.",takeaway:"İyi dilek, önce niyettir; his sonra gelebilir.",sources:["meditation-lovingkindness","meditation-salzberg","self-compassion"],visual:{kind:"table",title:"Metta sırası",columns:["Kime","Örnek dilek"],rows:[["Kendine","Güvende ve huzurlu olayım."],["Sevdiğin biri","Sağlıklı ve mutlu ol."],["Nötr bir tanıdık","Günün kolay geçsin."],["Zorlandığın biri","Sen de acıdan uzak ol."],["Bütün canlılar","Herkes güvende ve huzurlu olsun."]],note:"Kendinle başlamak zor gelirse sevdiğin biriyle başlayabilirsin. Zorlandığın birine iyi dilek göndermek, barışmak ya da sınırlarını kaldırmak zorunda olduğun anlamına gelmez."},technique:{name:"Sevgi-şefkat meditasyonu (metta)",origin:"Budist gelenek · Sharon Salzberg, Lovingkindness (1995)",steps:["Rahat otur ve birkaç nefes boyunca göğsünün ortasını fark et.","Kendin için üç dört kısa iyi dilek cümlesi seç.","Cümleleri ağır ağır, içinden kendine tekrarla.","Sevdiğin birini gözünün önüne getir ve aynı dilekleri ona gönder.","Nötr bir kişiye, ardından hazırsan zorlandığın birine geç.","Son olarak dilekleri bütün canlılara genişlet ve birkaç nefesle bitir."],evidence:"Meta-analizler sevgi-şefkat meditasyonunun olumlu duyguları küçük–orta düzeyde artırabildiğini gösteriyor. Ancak birçok çalışmada yanlılık riski yüksek ve etkin yöntemlerle karşılaştırma az.",sourceId:"meditation-salzberg"},photo:{id:"1604881991720-f91add269bed",alt:"Masada birbirinin elini şefkatle tutan iki kişi"}},{id:"meditation-6",title:"Yeni benliğini prova et",minutes:9,goal:"Dr. Joe Dispenza’nın meditasyonuyla eski otomatik hâlini fark et, bırak ve olmak istediğin kişiyi duygusuyla birlikte zihninde prova et.",reading:["Dr. Joe Dispenza, Breaking the Habit of Being Yourself kitabında çoğumuzun günün büyük kısmını aynı düşünceler, aynı duygular ve aynı tepkilerle otomatik geçirdiğini anlatır. Önerdiği meditasyonda önce bu eski hâli, örneğin sık yaşadığın bir kaygıyı ya da öfkeyi ve ona eşlik eden düşünce ve davranışları ayrıntısıyla fark edersin. Sonra onu dürüstçe kabul edip bırakmaya niyet eder ve gün içinde devreye girdiği anları tanırsın. En sonda olmak istediğin kişiyi, nasıl düşüneceğini, konuşacağını ve davranacağını zihninde canlandırır ve o hâlin duygusunu şimdiden yaşamaya çalışırsın.","Zihinsel provanın araştırma desteği var: Toth ve arkadaşlarının 2020 meta-analizi, 1995–2018 arasındaki 37 çalışmada zihinsel pratiğin performansı küçük ama anlamlı biçimde iyileştirdiğini gösterdi. Aynı çalışma, etkinin 1994’teki öncü meta-analize göre daha küçük çıktığını bildiriyor ve bu çalışmalar çoğunlukla hareket ve beceri görevleriyle ilgili. Kitabın kuantum alanıyla gerçekliği değiştirme, genleri etkileme ya da hastalıkları düşünceyle iyileştirme gibi iddiaları ise bilimsel araştırmalarla desteklenmiyor. Bu dersi bir tedavi ya da gerçeği şekillendirme yöntemi olarak değil, değişmek istediğin davranışın provası olarak kullan."],practice:["Değiştirmek istediğin bir otomatik hâli seç; onu tetikleyen anı, eşlik eden düşünceyi ve davranışı yaz.","Dokuz dakikalık bir oturuşta tekniğin adımlarını izle ve olmak istediğin hâli bir sahne içinde en az üç kez canlandır.","Bugün bu yeni hâlle yapacağın tek bir küçük davranışı seç ve “Eğer … olursa, … yapacağım” diye bir plana bağla."],reflection:"Olmak istediğin kişi, eski hâlinin tetiklendiği o anda neyi farklı yapardı?",question:"Bu tekniğin araştırmayla en iyi desteklenen kısmı hangisi?",options:["Kuantum alanı aracılığıyla olayları ve gerçekliği değiştirmek.","Olmak istediğin davranışı zihinde prova edip sonra gerçek hayatta denemek.","Düşünceyle hastalıkları iyileştirip ilaca gerek bırakmamak."],correct:1,feedback:"Zihinsel prova, özellikle ardından gerçek bir deneme geldiğinde küçük ama anlamlı fayda gösteriyor. Kuantum ve hastalık iyileştirme iddiaları desteklenmiyor; tedavini asla bu gerekçeyle bırakma.",takeaway:"Yeni hâlini zihninde prova et, sonra bir adımla hayata taşı.",sources:["dispenza-breaking-habit","mental-practice","if-then-plans"],visual:{kind:"bars",title:"Zihinsel pratiğin performansa ortalama etkisi",bars:[{label:"Driskell ve ark. · 1994",value:.255,display:"r = 0,255"},{label:"Toth ve ark. · 2020",value:.131,display:"r = 0,131"}],note:"Değerler Toth ve ark. 2020’den; yeni analiz 1995–2018 arasındaki 37 çalışmayı kapsar ve yayın yanlılığı için düzeltilmiştir. Çalışmalar çoğunlukla hareket ve beceri görevleriyle ilgilidir; kişilik değişimi ya da hastalık iyileşmesi ölçülmedi.",sourceId:"mental-practice"},technique:{name:"Eski benliği bırak, yenisini prova et",origin:"Dr. Joe Dispenza · Breaking the Habit of Being Yourself (2012)",steps:["Rahat otur, gözlerini kapat ve bedeninin çevresindeki boşluğu hissederek dikkatini düşüncelerden bedenine ve şimdiye indir.","Değiştirmek istediğin eski bir hâli seç: sık yaşadığın bir duygu ve ona eşlik eden düşünceler ile davranışlar.","Bu hâli kendine dürüstçe kabul et, bırakmaya niyet ettiğini içinden söyle ve onu teslim ettiğini düşünerek gevşe.","Eski hâlinin gün içinde hangi anlarda devreye girdiğini ayrıntısıyla gör ve o an kendine “Dur, değiştir” diyeceğin işareti belirle.","“En iyi hâlimde nasıl biri olurdum?” diye sor; o kişinin nasıl düşündüğünü, konuştuğunu ve davrandığını canlandır.","Bu yeni hâlin duygusunu, örneğin sakinlik, güven ya da şükranı, şu an bedeninde hissetmeye çalış ve sahneyi birkaç kez prova et.","Gözlerini açmadan önce bugün bu yeni hâlle yapacağın tek bir küçük davranışı seç."],evidence:"Zihinsel prova, beceri performansında küçük ama anlamlı fayda gösteriyor; eski alışkanlığı fark edip yeni davranışı somut bir plana bağlamak da desteklenen yollardır. Kuantum alanıyla gerçekliği değiştirme, genleri etkileme ya da hastalıkları düşünceyle iyileştirme iddiaları bilimsel olarak desteklenmiyor.",sourceId:"dispenza-breaking-habit"},photo:{id:"1631832293782-2eda7804489b",alt:"Sabah güneşinin pencereden süzüldüğü, önünde saksı bitkisi olan sessiz bir oda"}},{id:"meditation-7",title:"Kendi düzenin ve dikkat edilecekler",minutes:8,goal:"Sana uygun, günlük bir meditasyon düzeni kur ve ne zaman durup yardım isteyeceğini bil.",reading:["Uzun ve seyrek oturuşlar yerine kısa ve düzenli oturuşlar çoğu kişi için daha sürdürülebilirdir. Her gün aynı ipucuna bağlı 10 dakika, örneğin sabah çayını koyduktan sonra, iyi bir başlangıç olabilir. Lally ve arkadaşlarının çalışması, aynı bağlamda tekrarlanan davranışların zamanla daha otomatik hâle geldiğini ama bu sürenin kişiden kişiye çok değiştiğini gösterdi. Zor geldiği günlerde süreyi kısalt, oturmak yerine yürü ya da birkaç uzun nefes verişle yetin; bir günü kaçırmak düzenini bozmaz.","Meditasyon çoğu kişi için güvenlidir ama risksiz değildir. Farias ve arkadaşlarının 2020 sistematik derlemesi 83 çalışmada (6.703 kişi) olumsuz etkilerin toplam sıklığını %8,3 olarak buldu; en sık bildirilenler kaygı ve depresif belirtilerdi ve bu etkiler daha önce ruhsal sorunu olmayan kişilerde de görülebildi. Travma ya da psikoz geçmişin varsa meditasyonu bir uzmanla birlikte uygula; sıkıntın artıyorsa, eski anılar seni sarsıyorsa ya da kendini gerçeklikten kopuk hissediyorsan dur ve destek al. Meditasyon terapinin ya da ilacın yerine geçmez; kendine zarar verme düşüncen ya da acil bir durum varsa 112’yi ara."],practice:["Meditasyonu bağlayacağın günlük bir ipucu ve saat seç; örneğin sabah kahvaltısından hemen sonra.","Bu kurstan en sevdiğin tekniği seç ve bir hafta boyunca her gün 10 dakika uygula.","Zor bir gün için yedek planını yaz: “Eğer oturamazsam 3 dakika yürüyüş meditasyonu yapacağım.”"],reflection:"Bu kurstaki tekniklerden hangisi sana en çok iyi geldi ve neden?",question:"Meditasyon sırasında sıkıntın belirgin biçimde artıyor ve eski anılar seni sarsıyorsa ne yapmalısın?",options:["Durur, gözlerimi açıp ayaklarımı hisseder ve bir uzmandan destek alırım.","Daha uzun oturup bu duyguların kendiliğinden geçmesini beklerim.","Bunu meditasyonun iyi gittiğinin işareti sayıp zorlamaya devam ederim."],correct:0,feedback:"Olumsuz etkiler nadir değildir ve durmak uygulamanın bir parçasıdır. Travma ya da psikoz geçmişi varsa bir uzmanla çalışmak, acil durumda 112’yi aramak doğru adımdır.",takeaway:"Kısa ve düzenli uygula; zorlandığında durmak da bir beceridir.",sources:["meditation-adverse","meditation-nccih","habits","if-then-plans","cyclic-sighing","meditation-kabat-zinn"],visual:{kind:"table",title:"Ne zaman ne yapabilirsin?",columns:["Durum","Olası adım"],rows:[["Sıkıldım, aklım çok dağınık","Süreyi kısalt ya da yürüyüş meditasyonuna geç"],["Hafif huzursuzluk ya da gerginlik","Gözlerini aç, ayaklarını hisset, birkaç uzun nefes ver"],["Sıkıntı artıyor, eski anılar sarsıyor","Dur ve bir ruh sağlığı uzmanıyla konuş"],["Travma ya da psikoz geçmişi","Meditasyonu bir uzmanla birlikte planla"],["Kendine zarar verme düşüncesi ya da acil durum","112’yi ara"]],note:"Farias ve ark. 2020 ile NCCIH önerilerine dayanır. Bu tablo tıbbi bir değerlendirme değildir."},technique:{name:"Resmî ve gündelik uygulama",origin:"Jon Kabat-Zinn · MBSR’de resmî ve resmî olmayan uygulama",steps:["Her gün aynı ipucundan sonra 10 dakikalık bir resmî oturuş planla.","Kurstaki tekniklerden birini seç: nefes, beden taraması, kelime, yürüyüş, metta ya da prova.","Bir de gündelik bir işi farkındalıkla yapmayı seç: diş fırçalamak, bulaşık yıkamak ya da çay içmek.","O iş sırasında duyularına dikkat et; aklın dağılınca nazikçe geri dön.","Hafta sonunda hangi tekniğin sana iyi geldiğini ve süreyi değiştirmek isteyip istemediğini gözden geçir."],evidence:"Aynı bağlamda düzenli tekrar alışkanlık oluşumunu destekler; eğer–o zaman planları niyeti davranışa çevirmeye yardım eder. Meditasyonun olumsuz etkileri de olabilir; sıkıntı artarsa durmak ve destek almak uygulamanın parçasıdır.",sourceId:"meditation-kabat-zinn"},photo:{id:"1781255575628-d645cc39160f",alt:"Ahşap zeminde renkli minderler ve hasır pufların olduğu sade bir köşe"}}]},qa=[{id:"expectation-suggestion",title:"Peerdeman ve ark. · 2016 · Beklenti müdahaleleri ve ağrı meta-analizi",url:"https://cris.maastrichtuniversity.nl/en/publications/relieving-patients-pain-with-expectation-interventions-a-meta-ana/",type:"research",finding:"Taranan 15.955 kayıttan 30 çalışma dahil edildi, 27’si sayısal analize girdi. Kısa beklenti müdahaleleri hastalarda ağrıyı orta düzeyde azalttı (Hedges g = 0,61): sözel telkin (18 çalışma) g = 0,75, sözel telkinle birlikte koşullama (3 çalışma) g = 0,65, imgeleme (6 çalışma) g = 0,27. Etki deneysel ve işlem sırasındaki ağrıda orta–büyük, kronik ağrıda küçüktü.",limitation:"Telkinleri kişinin kendisi değil, araştırmacı ya da sağlık çalışanı verdi; kendi kendine telkin ayrıca sınanmadı. Çalışmalar arasında farklılık yüksekti (I² = %73). Yalnızca özet okundu."},{id:"positive-self-statements",title:"Wood, Perunovic & Lee · 2009 · Olumlu kendilik cümleleri deneyleri",url:"https://journals.sagepub.com/doi/10.1111/j.1467-9280.2009.02370.x",type:"research",finding:"249 öğrenciyle yapılan ankette insanlar olumlu kendilik cümlelerini sık kullandığını ve işe yaradığına inandığını bildirdi. 68 kişilik deneyde “Sevilecek biriyim” cümlesini 16 kez tekrarlayan özgüveni düşük katılımcılar, tekrarlamayanlara göre kendini daha kötü hissetti; özgüveni yüksek olanlar ise biraz daha iyi hissetti. 116 kişilik üçüncü çalışma benzer bir örüntü gösterdi.",limitation:"Katılımcılar Kanadalı üniversite öğrencileriydi, ölçümler kısa süreli ruh hâliydi ve tek bir cümle sınandı; bulgu, tüm olumlu cümlelerin zararlı olduğu anlamına gelmez."},{id:"self-affirmation-health",title:"Epton ve ark. · 2015 · Öz-onaylama ve sağlık davranışı meta-analizi",url:"https://research.manchester.ac.uk/en/publications/the-impact-of-self-affirmation-on-health-behavior-change-a-meta-a/",type:"research",finding:"144 deneysel testte önemli değerler, özellikler ya da ilişkiler üzerine düşünmek (öz-onaylama), sağlık mesajını kabul etmeyi (34 test, N = 3.433, d = 0,17), değişme niyetini (64 test, N = 5.564, d = 0,14) ve sonraki davranışı (46 test, N = 2.715, d = 0,32) küçük ama güvenilir biçimde artırdı.",limitation:"Etkiler küçüktür ve çoğunlukla bir sağlık mesajıyla birlikte ölçüldü; değer yazısının tek başına ruh hâlini iyileştirdiği anlamına gelmez. Yalnızca özet okundu."},{id:"self-affirmation-review",title:"Cohen & Sherman · 2014 · Öz-onaylama müdahaleleri derlemesi",url:"https://www.annualreviews.org/content/journals/10.1146/annurev-psych-010213-115137",type:"research",finding:"Derleme, öz-onaylama müdahalelerinde insanların genellikle temel kişisel değerleri hakkında yazdığını, bunun benliğe daha geniş bakmayı sağlayarak tehdidin etkisini azalttığını ve doğru zamanda yapıldığında eğitim, sağlık ve ilişki sonuçlarında bazen aylarca süren yararlar gösterdiğini aktarır.",limitation:"Anlatısal bir derlemedir, tek bir ortalama etki vermez; yazarlar etkinin zamanlamaya ve bağlama bağlı olduğunu vurgular. Yalnızca özet okundu."},{id:"distanced-self-talk",title:"Kross ve ark. · 2014 · Kendine mesafeli konuşma deneyleri",url:"https://pubmed.ncbi.nlm.nih.gov/24467424/",type:"research",finding:"Toplam 585 kişiyle yapılan yedi çalışmada, düşünürken “ben” yerine kendi adını ya da “sen”i kullanmak kendine mesafeyi artırdı. İlk izlenim ve topluluk önünde konuşma görevlerinde bu grup, bağımsız değerlendiricilere göre daha iyi performans gösterdi, daha az sıkıntı yaşadı ve konuşmadan sonra daha az olumsuz geviş getirdi; gelecek stres kaynaklarını tehdit yerine daha çok meydan okuma olarak değerlendirdi. Sonuçlar sosyal kaygı düzeyine göre değişmedi.",limitation:"Laboratuvarda, kısa görevlerle ve çoğunlukla üniversite öğrencileriyle yapıldı; klinik bir tedavi değildir ve uzun süreli etkiler ölçülmedi."},{id:"sport-self-talk",title:"Hatzigeorgiadis ve ark. · 2011 · İç konuşma ve spor performansı meta-analizi",url:"https://journals.sagepub.com/doi/abs/10.1177/1745691611413136",type:"research",finding:"32 çalışmadan elde edilen 62 etki büyüklüğünde iç konuşma müdahaleleri spor görevlerinde performansı orta düzeyde artırdı (ES = 0,48). Etki ince beceri gerektiren ve yeni öğrenilen görevlerde daha büyüktü; eğitsel iç konuşma (d = 0,55) motive edici iç konuşmaya (d = 0,37) göre, özellikle ince görevlerde (d = 0,83) daha etkiliydi. Önceden iç konuşma alıştırması içeren programlar (d = 0,80) içermeyenlerden (d = 0,37) daha etkiliydi.",limitation:"Çalışmalar spor ve motor görevlerle sınırlıdır, çoğu küçük örneklemlidir; ofis işi ya da duygusal zorluklar için aynı büyüklükte etki beklenmemeli. Alt grup sayıları tam metin özetinden aktarıldı."},{id:"positive-fantasies",title:"Kappes & Oettingen · 2011 · Olumlu hayaller ve enerji deneyleri",url:"https://www.sciencedirect.com/science/article/abs/pii/S002210311100031X",type:"research",finding:"Dört deneyde istenen geleceği idealize eden olumlu hayaller; bu geleceği sorgulayan, olumsuz ya da nötr hayallere göre daha az enerjiyle (sistolik kan basıncı ve öz bildirim) ilişkiliydi. Bir deneyde bu durum bir hafta sonra gündelik zorluklarda daha az başarıya yansıdı; ihtiyaç ne kadar acilse enerjideki düşüş o kadar büyüktü.",limitation:"Küçük örneklemli laboratuvar deneyleridir; hayal kurmanın her zaman zararlı olduğunu göstermez, yalnızca eylemsiz ve engelsiz hayalin riskine işaret eder. Yalnızca özet okundu."},{id:"sleep-memory-reactivation",title:"Paller, Creery & Schechtman · 2021 · Uyku ve bellek derlemesi",url:"https://www.annualreviews.org/content/journals/10.1146/annurev-psych-010419-050815",type:"research",finding:"Derleme, uyanıkken öğrenilen anıların uyku sırasında yeniden etkinleşerek pekiştiğini ve bunun problem çözme, yaratıcılık ve duygu düzenlemeyi destekleyebileceğini anlatır. Uyku sırasında yeni bilgi öğrenmenin ise basit çağrışımsal ve algısal öğrenme türleriyle sınırlı kaldığını belirtir.",limitation:"Anlatısal bir derlemedir, sayısal etki vermez; uyku öncesi telkini doğrudan sınamaz. Uyku sırasında endişelerin fazla tekrarlanmasının zararlı olabileceğini de not eder."},{id:"coue-autosuggestion",title:"Émile Coué · Self Mastery Through Conscious Autosuggestion · 1920",url:"https://www.gutenberg.org/ebooks/27203",type:"technique",finding:"Coué, hayal gücü ile irade çatıştığında hayal gücünün kazandığını, bu yüzden istenen hâlin zorlamadan, sakince hayal edilmesi gerektiğini öğretir. Sabah uyanınca ve akşam yatakta, gözler kapalı ve alçak, tek düze bir sesle genel bir iyileşme cümlesini yirmi kez tekrarlamayı, saymak için yirmi düğümlü bir ip kullanmayı önerir; rahatsızlık anında “geçiyor” cümlesini hızlıca tekrarlamayı da anlatır. Hekim tedavisinin sürdürülmesini ve telkinin buna eklenmesini söyler.",limitation:"Kitap kamu malıdır ve kanıtları çoğunlukla Coué’nin kendi gözlemleridir. Formülü doğrudan sınayan modern kontrollü çalışma bulamadık. Kitaptaki organik hastalıkları iyileştirme iddiaları araştırmalarla desteklenmez."},{id:"murphy-subconscious",title:"Joseph Murphy · The Power of Your Subconscious Mind · 1963",url:"https://www.penguinrandomhouse.com/books/296695/the-power-of-your-subconscious-mind-by-joseph-murphy-phd-dd/",type:"technique",finding:"Murphy, uykuya dalmadan önceki mahmur hâlin telkine en açık an olduğunu söyler. Dileği kısa bir cümleye indirip ninni gibi tekrarlamayı, sonucu şimdi oluyormuş gibi kısa bir sahnede canlandırmayı (örneğin bir arkadaşın seni tebrik etmesi) ve sahneyi içten bir teşekkür duygusuyla bitirmeyi önerir.",limitation:"Uyku öncesi prova ve niyet hazırlığa yardım edebilir; ancak bilinçaltının para, sağlık ya da fırsat “çektiği” ve düşüncenin hastalıkları iyileştirdiği iddiaları araştırmalarla desteklenmez. Tıbbi tedavi asla bırakılmamalıdır."},{id:"hill-autosuggestion",title:"Napoleon Hill · Think and Grow Rich · 1937",url:"https://www.naphill.org/shop/books/paperback/think-and-grow-rich-the-1937-edition/",type:"technique",finding:"Hill, hedefi açıkça yazmayı (ne istendiğini, ne zamana kadar ve karşılığında ne verileceğini), bu yazıyı her gün iki kez, gece yatmadan ve sabah kalkınca sesli okumayı ve okurken hedefe ulaşmış olmayı duyguyla canlandırmayı önerir; bunu otosugesyon adımı olarak anlatır.",limitation:"Kitap aslen para kazanmaya odaklanır ve anekdotlara dayanır. Hedefi yazmak ve planla birleştirmek yararlı olabilir; ancak düşüncenin tek başına zenginlik çektiği iddiası sınanmamıştır."},{id:"hay-mirror-work",title:"Louise Hay · Olumlamalar ve ayna çalışması",url:"https://www.louisehay.com/affirmations/",type:"technique",finding:"Louise Hay, olumlu cümleleri aynada kendi gözlerine bakarak, sevecen bir sesle söylemeyi (ayna çalışması) yaygınlaştırdı; başta rahatsız edici gelebilen bu alıştırmanın düzenli yapılmasını önerir.",limitation:"Ayna çalışmasını sınayan kontrollü bir çalışma bulamadık. İnanılmayan cümleler özgüveni düşük kişilerde ters tepebildiği için cümlenin inanılabilir olması önemlidir; Hay’in düşüncelerin hastalığa yol açtığı ya da iyileştirdiği görüşleri desteklenmez."},{id:"kross-chatter",title:"Ethan Kross · Chatter · 2021",url:"https://www.penguinrandomhouse.com/books/575664/chatter-by-ethan-kross/",type:"technique",finding:"Kross, iç sesi bir eleştirmenden koça çevirmek için kendine adınla ya da “sen” diye seslenmeyi, kendine bir arkadaşa öğüt verir gibi konuşmayı, olaya zamanda uzaktan bakmayı ve yazmak ya da güvenilen biriyle konuşmak gibi araçları anlatır.",limitation:"Araçların çoğu kısa laboratuvar deneylerine dayanır; yoğun ve süreğen olumsuz düşüncelerde profesyonel desteğin yerine geçmez."},{id:"gallwey-inner-game",title:"W. Timothy Gallwey · The Inner Game of Tennis · 1974",url:"https://www.penguinrandomhouse.com/books/57757/the-inner-game-of-tennis-50th-anniversary-edition-by-w-timothy-gallwey/",type:"technique",finding:"Gallwey, yargılayan ve talimat yağdıran iç sesi (Benlik 1) susturup bedenin öğrenmesine (Benlik 2) alan açmak için dikkati somut bir işarete bağlamayı öğretir; örneğin top yere değince “zıpla”, rakete değince “vur” demek ve sonucu iyi–kötü diye yargılamadan gözlemek.",limitation:"Yöntemin kendisi meta-analizlerde ayrıca sınanmadı; dikkati yönlendiren kısa eğitsel iç konuşmanın yararı ise spor araştırmalarında destekleniyor."},{id:"cohen-belonging",title:"Geoffrey L. Cohen · Belonging · 2022",url:"https://www.geoffreylcohen.com/book",type:"technique",finding:"Cohen, kişinin temel değerlerini seçip bunların neden önemli olduğunu yaklaşık 10 dakika yazdığı değer onaylama alıştırmasını, zorlayıcı anlardan önce kullanılan kısa bir “akıllı müdahale” olarak anlatır.",limitation:"Etkiler genellikle küçüktür ve zamanlamaya, bağlama bağlıdır; bazı büyük okul denemelerinde sonuçlar tekrarlanamamıştır."}],Ra={id:"suggestion",title:"Telkin nasıl verilir",subtitle:"Kendinle nazik konuş.",description:"Coué’den Murphy’ye, Kross’tan Dispenza’ya ünlü telkin tekniklerini adım adım uygula ve araştırmaların bu teknikler hakkında ne dediğini öğren.",scope:"Yetişkinler için kendine telkin ve iç konuşma eğitimi; hipnoterapi, tanı ya da tedavi değildir. Telkin ilacın ya da sürdürdüğün tedavinin yerine geçmez; ilacını veya tedavini hekimine danışmadan bırakma. Kitaplarda geçen hastalığı iyileştirme ya da para çekme iddiaları araştırmalarla desteklenmez. İçinden gelen olumsuz, rahatsız edici cümleler çok yoğunsa ya da uzun süredir çökkün hissediyorsan bir ruh sağlığı profesyoneline başvur. Kendine zarar verme düşüncen ya da acil bir tehlike varsa 112’yi ara.",outcome:"İnanabileceğin bir telkin cümlesi, bir imge, bir eğer–o zaman planı ve 7 gün sonra gözden geçireceğin kişisel telkin kartın.",photo:{id:"1779922811108-245a9403ef44",alt:"Şafakta tepede duran bir insan silueti"},lessons:[{id:"suggestion-1",title:"Telkin nedir, ne değildir",minutes:7,goal:"Telkinin neyi değiştirebileceğini ve neyi değiştiremeyeceğini ayırt et.",reading:["Bu kursta telkin, seçtiğin bir cümleyi bir imge ve küçük bir eylemle birlikte düzenli olarak tekrar etmek demek. Fransız eczacı Émile Coué 1920’lerde bu fikri “bilinçli otosugesyon” adıyla yaydı. Ona göre bir şeyi dişini sıkarak istemek işe yaramıyordu; istenen hâli sakince hayal etmek davranışı daha çok etkiliyordu. Coué, bir hâli zorladıkça tersinin güçlendiğini gözlemlemişti.","Beklentinin deneyimi etkileyebildiğine dair araştırmalar var. Peerdeman ve arkadaşlarının 27 çalışmayı birleştiren meta-analizinde, hastalara verilen kısa sözel telkinler ağrıyı orta düzeyde azalttı; ama bu telkinleri araştırmacılar veriyordu ve kronik ağrıda etki küçüktü. Yani beklenti bir kapı aralar, ama hastalığı iyileştirmez, ilacın ya da tedavinin yerini tutmaz. Coué de hekim tedavisinin sürmesini ve telkinin buna eklenmesini isterdi."],practice:["Bu hafta biraz değişmesini istediğin küçük bir durumu tek cümleyle yaz.","Bu durum için dişini sıkarak söylediğin bir cümleyi ve daha sakin bir karşılığını yan yana yaz.","Tekniği bir kez dene ve sonra bedeninde fark ettiğin tek bir şeyi not et."],reflection:"Kendine en sık hangi cümleyi söylüyorsun ve bu cümle seni nasıl etkiliyor?",question:"Bu kursta telkin nasıl tanımlanıyor?",options:["Bilinçaltına gönderilen ve her şeyi kendiliğinden değiştiren gizli bir komut.","Seçilmiş bir cümle, bir imge ve küçük bir eylemin birlikte tekrarlanması.","İlacın ya da tedavinin yerine geçebilen bir düşünce tekniği."],correct:1,feedback:"Telkin; cümle, imge ve eylemin birleşimi olarak ele alınıyor. Beklenti deneyimi etkileyebilir, ama telkin tedavinin yerine geçmez ve sonuç garanti etmez.",takeaway:"Zorlamadan söyle, sakince hayal et, küçük bir adım at.",sources:["expectation-suggestion","coue-autosuggestion"],technique:{name:"Zorlamadan hayal et (bilinçli otosugesyon)",origin:"Émile Coué · Self Mastery Through Conscious Autosuggestion (1920)",steps:["Değişmesini istediğin küçük bir durumu seç; örneğin toplantıdan önceki gerginlik.","Omuzlarını bırak ve birkaç sakin nefes al; kendini zorlamaya çalışma.","Olmasını istediğin hâli kısa ve yumuşak bir cümleyle söyle: “Yavaş yavaş sakinleşiyorum.”","Cümleyi söylerken o hâli kısa bir sahne olarak zihninde canlandır.","“Yapamam” düşüncesi gelirse onunla kavga etme; fark et ve cümlene nazikçe dön.","Rahatsız bir an gelirse alçak sesle ve hızlıca “geçiyor, geçiyor” diye tekrarla."],evidence:"Beklentinin ağrı gibi deneyimleri etkileyebildiği araştırmalarla destekleniyor; ancak bu çalışmalarda telkini çoğunlukla bir sağlık çalışanı verdi. Coué’nin yöntemi modern çalışmalarla pek sınanmadı ve organik hastalıkları iyileştirdiği iddiası desteklenmez.",sourceId:"coue-autosuggestion"},visual:{kind:"bars",title:"Kısa beklenti müdahalelerinin ağrıya etkisi",bars:[{label:"Sözel telkin (18 çalışma)",value:.75,display:"g = 0,75"},{label:"Telkin + koşullama (3 çalışma)",value:.65,display:"g = 0,65"},{label:"İmgeleme (6 çalışma)",value:.27,display:"g = 0,27"}],note:"Hastalarda ağrı azalması, Hedges g; genel ortalama 0,61. Telkinleri araştırmacı ya da sağlık çalışanı verdi, kronik ağrıda etki küçüktü; kendi kendine telkin ve bu kurs ayrıca sınanmadı.",sourceId:"expectation-suggestion"},photo:{id:"1461468611824-46457c0e11fd",alt:"Denize bakarak oturan kadın"}},{id:"suggestion-2",title:"Coué formülü",minutes:7,goal:"Coué’nin günlük formülünü sabah ve akşam, zorlamadan uygula.",reading:["Coué’nin en bilinen önerisi, sabah uyanınca ve akşam yatakta, gözler kapalıyken “Her gün, her bakımdan, giderek daha iyi oluyorum” cümlesini yirmi kez tekrarlamaktı. Tekrarları saymak için yirmi düğümlü bir ip kullanmayı önerdi; bugün bir tesbih ya da parmakların da işini görür. Cümleyi tek düze, bir ninni gibi ve zorlamadan söylemek onun için önemliydi. “Her bakımdan” ifadesi bilerek geniş tutulmuştu, böylece sorunları tek tek düşünmek zorunda kalmıyordun.","Bu formülü doğrudan sınayan güncel, iyi tasarlanmış bir çalışma bulamadık; Coué döneminin başarı öyküleri çoğunlukla anekdottur. Yine de formülü sabah ve akşam aynı ana bağlamak, Lally ve arkadaşlarının alışkanlık çalışmasındaki gibi tekrarın zamanla otomatikleşmesine yardım edebilir. Bu alıştırmayı bir iyileşme vaadi değil, günü sakin açıp kapatan bir ritüel olarak düşün. Bir ağrın ya da hastalık belirtin varsa formül tıbbi değerlendirmenin yerine geçmez."],practice:["Yirmi düğümlü bir ip hazırla ya da tesbihinde yirmi taneyi ayır.","Bu akşam yatağa girince formülü alçak ve tek düze bir sesle yirmi kez söyle.","Yarın sabah kalkmadan tekrarla ve iki seferden sonra nasıl hissettiğini tek cümleyle yaz."],reflection:"Formülü zorlamadan söylemek sana nasıl geldi: rahatlatıcı mı, tuhaf mı, sıkıcı mı?",question:"Coué formülünde hangisi önerilen tutuma uyar?",options:["Cümleyi dişlerini sıkarak, olabildiğince güçlü söylemek.","Cümleyi gevşek ve alçak sesle söyleyip saymayı ipe ya da tesbihe bırakmak.","Her tekrardan sonra bir şeyin değişip değişmediğini kontrol etmek."],correct:1,feedback:"Coué, çabanın arttıkça ters etki yarattığını düşünürdü; bu yüzden gevşek, tek düze bir tekrar önerdi. Bu onun gözlemidir; formülün etkisi modern çalışmalarla pek sınanmadı.",takeaway:"Kısa bir cümle, sakin bir ses, her gün aynı an.",sources:["coue-autosuggestion","habits"],technique:{name:"Coué formülü (yirmi tekrar)",origin:"Émile Coué · Self Mastery Through Conscious Autosuggestion (1920)",steps:["Yirmi düğümlü bir ip hazırla ya da tesbihinde yirmi taneyi ayır.","Sabah uyanınca, henüz kalkmadan gözlerini kapat ve rahatça uzan.","“Her gün, her bakımdan, giderek daha iyi oluyorum” cümlesini alçak ve tek düze bir sesle söyle.","Her tekrarda bir düğüm ya da tane ilerlet; saymayı ipe bırak.","Anlamı zorla düşünmeye çalışma; cümle bir ninni gibi aksın.","Aynısını akşam yatağa girdiğinde, uyumadan önce tekrarla."],evidence:"Formülün kendisini sınayan modern kontrollü çalışma çok az; kanıt çoğunlukla Coué döneminin anlatılarıdır. Sakinleştirici bir ritüel olarak denenebilir, ama hastalık iyileştirdiği iddiası desteklenmez.",sourceId:"coue-autosuggestion"},visual:{kind:"compare",title:"Zorlayarak mı, Coué’nin yoluyla mı?",left:{label:"Zorlayarak",items:["Dişlerini sıkıp yüksek sesle söylemek","Her tekrarda sonucu kontrol etmek","Aklın dağılınca kendine kızmak"]},right:{label:"Coué’nin yoluyla",items:["Gevşek, alçak ve tek düze bir ses","Saymayı ipe ya da tesbihe bırakmak","Aklın dağılınca nazikçe cümleye dönmek"]},note:"Coué’ye göre çaba arttıkça ters etki artar; bu onun gözlemidir, deneysel olarak kanıtlanmış bir yasa değildir."},photo:{id:"1762328490563-9b9c300fba3e",alt:"Elinde boncuk dizisi tutan kişi"}},{id:"suggestion-3",title:"İnanabileceğin cümleler kur",minutes:8,goal:"Zorlayan olumlamaları inanabileceğin, süreci anlatan cümlelere çevir.",reading:["Wood, Perunovic ve Lee’nin 2009’daki deneylerinde katılımcılar “Sevilecek biriyim” cümlesini birkaç dakika içinde 16 kez tekrarladı. Özgüveni yüksek olanlar biraz daha iyi hissetti, ama özgüveni düşük olanlar cümleyi hiç tekrarlamayanlara göre kendini daha kötü hissetti. Olası açıklama şu: cümle inandığından çok uzaksa zihnin ona itiraz eder ve bu itiraz aklında kalır. Bu yüzden en iddialı cümle, en etkili cümle olmayabilir.","Daha inanılabilir bir yol, süreci ve öğrenmeyi anlatan cümleler kurmak: “Öğreniyorum”, “Bugün bir adım atabilirim” gibi. Bir diğer yol, kendin hakkında hüküm vermek yerine değerlerini hatırlamak. Cohen ve Sherman’ın derlediği öz-onaylama çalışmalarında insanlar kendileri için önemli bir değer hakkında kısa bir yazı yazıyor. Epton ve arkadaşlarının 144 testi birleştiren meta-analizinde bu tür yazılar, sağlık mesajlarını kabul etmeyi ve sonraki davranışı küçük ama güvenilir biçimde artırdı."],practice:["Kendine sık söylediğin ya da söylemek istediğin bir olumlu cümleyi yaz.","Bu cümleye ne kadar inandığını 0’dan 10’a puanla; 5’in altındaysa süreç ya da öğrenme diliyle yeniden yaz.","Değer yazısını 10 dakika yap ve en önemli değerini tek kelimeyle kartına ekle."],reflection:"Hangi cümleyi söylediğinde içinden “evet, bu doğru olabilir” diyorsun?",question:"Wood ve arkadaşlarının bulgusuna göre hangisi daha akıllıca bir seçim?",options:["İnanmasan da en iddialı cümleyi daha sık tekrarlamak.","İnanabileceğin ve süreci anlatan bir cümle seçmek.","Kendine hiçbir olumlu cümle söylememek."],correct:1,feedback:"İnanılmayan cümleler özellikle özgüveni düşük olanlarda ters tepebildi. İnanılabilir, süreç odaklı cümleler ve değerlerini hatırlamak daha güvenli bir başlangıçtır.",takeaway:"Cümlen iddialı olmak zorunda değil; inanılabilir olsun.",sources:["positive-self-statements","self-affirmation-review","self-affirmation-health","cohen-belonging"],technique:{name:"Değerlerini hatırla (değer yazısı)",origin:"Geoffrey L. Cohen · Belonging (2022); Cohen ve Sherman’ın öz-onaylama çalışmaları",steps:["Sana önemli gelen değerlerin bir listesini yap: aile, dürüstlük, merak, inanç, yardımseverlik gibi.","Bugün senin için en önemli olan bir ya da iki değeri seç.","Bu değerin neden önemli olduğunu yaklaşık 10 dakika serbestçe yaz.","Bu değeri yakın zamanda yaşadığın küçük bir anı da ekle.","Zor bir konuşma, sınav ya da geri bildirimden önce yazdığını yeniden oku."],evidence:"Değer yazısının savunmacılığı azaltıp sağlık davranışını küçük ama güvenilir biçimde desteklediği meta-analizle gösterildi. Etkiler küçüktür, zamanlamaya ve bağlama göre değişir ve her denemede tekrarlanmamıştır.",sourceId:"cohen-belonging"},visual:{kind:"table",title:"Zorlayan cümle mi, inanılabilir cümle mi?",columns:["Zorlayan cümle","İnanılabilir karşılığı"],rows:[["Ben mükemmelim.","Hata yapabilirim ve yine de öğrenmeye devam ediyorum."],["Hiç kaygılanmıyorum.","Kaygılıyım; yine de ilk cümlemi söyleyebilirim."],["Herkes beni seviyor.","Beni önemseyen insanlar var; bugün birine yazabilirim."],["Zengin ve başarılıyım.","Bu hafta bütçeme bir kez bakıp bir adım atıyorum."]],note:"Wood ve arkadaşlarının deneylerinde “Sevilecek biriyim” cümlesini tekrarlamak özgüveni düşük olanlarda ruh hâlini kötüleştirdi. Sağdaki cümleler bu çalışmada sınanmadı; amaç daha az iç itiraz uyandırmaktır."},photo:{id:"1616628188467-8fb29f49bbe8",alt:"Beyaz kâğıda not yazan el"}},{id:"suggestion-4",title:"Kendine adınla seslen",minutes:7,goal:"Zor bir andan önce kendine adınla ya da “sen” diye seslenerek mesafe al.",reading:["Kross ve arkadaşları toplam 585 kişiyle yedi çalışma yaptı. Zor bir durumu düşünürken “ben” yerine kendi adını ya da “sen”i kullananlar, olaya daha çok dışarıdan bakabildi. Kısa bir hazırlıktan sonra topluluk önünde konuşan bu grup, bağımsız değerlendiricilere göre daha iyi konuştu, daha az sıkıntı yaşadı ve sonrasında konuşmayı daha az evirip çevirdi. Gelecekteki zorlukları da tehditten çok meydan okuma olarak görmeye başladılar.","Bu küçük dil değişikliği, bir arkadaşına öğüt verirken sahip olduğun sakin bakışı kendine çevirmeni kolaylaştırıyor olabilir. Önemli olan tonun sert değil, şefkatli olması; adınla kendini azarlamak bu tekniğin amacı değil. Çalışmalar laboratuvarda, kısa görevlerle ve çoğunlukla öğrencilerle yapıldı; bu bir tedavi değil. İç sesin haftalardır çok sert ve durdurulamaz gibiyse bir ruh sağlığı profesyoneliyle konuşmak iyi bir adımdır."],practice:["Bu hafta seni zorlayacak bir anı seç ve saatini not et.","O andan önce iki dakika ayırıp durumu kendine adınla seslenerek anlat.","Sonra aynı durumdaki bir arkadaşına söyleyeceğin destek cümlesini kendine söyle."],reflection:"Kendine adınla seslendiğinde ses tonun nasıl değişti?",question:"Kross 2014 deneylerinde hangi iç konuşma biçimi sosyal streste daha yardımcı bulundu?",options:["Kendine adınla ya da “sen” diye seslenmek.","Yalnızca “ben” diyerek durumu uzun uzun düşünmek.","Kendini sert sözlerle eleştirerek motive etmek."],correct:0,feedback:"Adını ya da “sen”i kullanmak mesafeyi artırdı; bu grup daha az sıkıntı yaşadı ve daha iyi performans gösterdi. Bulgular kısa laboratuvar görevlerinden gelir.",takeaway:"Kendine bir arkadaşınla konuşur gibi, adınla seslen.",sources:["distanced-self-talk","kross-chatter","self-compassion"],technique:{name:"Mesafeli iç konuşma",origin:"Ethan Kross · Chatter (2021)",steps:["Zor bir andan önce iki dakika ayır: bir sunum, bir görüşme ya da zor bir konuşma.","Kendine içinden ya da fısıltıyla adınla seslen: “Ayşe, şu an ne oluyor?”","“Ben” yerine “sen” diyerek durumu anlat: “Heyecanlısın, çünkü bu senin için önemli.”","Aynı durumdaki bir arkadaşına ne söylerdiysen onu kendine söyle.","Gerekirse sor: “Bir yıl sonra buna nasıl bakacaksın?”","Konuşmayı somut bir sonraki adımla bitir: “İlk cümleni yavaşça söyle.”"],evidence:"Yedi deneyde adla ya da “sen” diye konuşmak, sosyal stres altında daha az sıkıntı ve daha iyi performansla ilişkiliydi. Çalışmalar laboratuvarda ve çoğunlukla öğrencilerle yapıldı; klinik bir tedavi değildir.",sourceId:"kross-chatter"},visual:{kind:"compare",title:"“Ben” mi, adınla mı?",left:{label:"Birinci şahıs",items:["Ben bunu beceremem.","Neden hep ben?","Kesin rezil olacağım."]},right:{label:"Adınla ya da “sen” diye",items:["Mehmet, zorlanıyorsun ama hazırlandın.","Bunu daha önce de atlattın.","İlk cümleni yavaşça söyle."]},note:"Amaç kendini azarlamak değil; bir arkadaşa konuşur gibi mesafe ve şefkatle konuşmak."},photo:{id:"1641907173006-6b8930ae1191",alt:"Gökyüzüne bakıp düşünen kadın"}},{id:"suggestion-5",title:"Kendine talimat ver",minutes:8,goal:"Bir iş için kısa eğitsel ve motive edici ipucu kelimeleri seç ve dene.",reading:["Hatzigeorgiadis ve arkadaşları sporda iç konuşmayı sınayan 32 çalışmayı birleştirdi ve performansta orta düzeyde bir artış buldu. İki tür iç konuşma var: eğitsel olan ne yapacağını söyler (“dirsek yukarıda”, “topu izle”), motive edici olan cesaret verir (“hadi”, “yapabilirsin”). Eğitsel iç konuşma özellikle ince, dikkat isteyen ve yeni öğrenilen işlerde daha güçlüydü. Önceden birkaç kez alıştırması yapılan programlar da daha etkiliydi.","Bu fikri gündelik hayata taşıyabilirsin: yazarken “önce taslak”, konuşurken “yavaş ve net”, yemek yaparken “tadına bak”. İpucu kısa olsun, bir–üç kelime yeter ve senin nasıl biri olduğunu değil, şimdi ne yapacağını anlatsın. Bu sayılar spor görevlerinden geliyor; ofis işi ya da duygusal zorluklar için aynı büyüklükte etki beklememek gerek. Yine de denemesi kolay ve ucuz bir araç."],practice:["Bu hafta öğrenmekte ya da iyi yapmakta zorlandığın bir işi seç.","Bu iş için bir eğitsel ve bir motive edici ipucu kelimesi yaz.","İşi yaparken ipucunu kısa ve sakin bir sesle tekrarla, sonucu yargılamadan not et."],reflection:"Hangi ipucu dikkatini gerçekten işe çekti?",question:"Meta-analize göre eğitsel iç konuşma hangi durumda özellikle işe yaradı?",options:["İnce beceri ve dikkat isteyen görevlerde.","Yalnızca çok iyi öğrenilmiş, otomatik görevlerde.","Hiç alıştırma yapmadan, yalnızca ilk denemede."],correct:0,feedback:"Eğitsel iç konuşma özellikle ince ve yeni becerilerde daha etkiliydi; önceden alıştırma yapılan programlar da daha büyük etki gösterdi.",takeaway:"Kendine kim olduğunu değil, şimdi ne yapacağını söyle.",sources:["sport-self-talk","gallwey-inner-game"],technique:{name:"Gözle ve söyle (“zıpla–vur”)",origin:"W. Timothy Gallwey · The Inner Game of Tennis (1974)",steps:["Yaptığın işte dikkatini bağlayacağın somut bir işaret seç: topun sekmesi, nefesin, kalemin ucu.","O an geldiğinde içinden kısa bir kelime söyle; tenis için top yere değince “zıpla”, rakete değince “vur”.","Sonucu iyi ya da kötü diye yargılamayı bırak; yalnızca ne olduğunu gözle.","Hata olursa kendini azarlamak yerine bir sonraki denemede neye bakacağını tek kelimeyle seç.","Birkaç dakika sonra bedeninin kendiliğinden nasıl uyum sağladığını fark et."],evidence:"Gallwey’in yöntemi meta-analizlerde ayrıca sınanmadı; ancak dikkati yönlendiren kısa eğitsel iç konuşmanın özellikle ince ve yeni becerilerde performansı artırdığı gösterildi. Etkiler spor görevlerinden gelir.",sourceId:"gallwey-inner-game"},visual:{kind:"bars",title:"Sporda iç konuşmanın performansa etkisi",bars:[{label:"Tüm çalışmaların ortalaması",value:.48,display:"ES = 0,48"},{label:"Eğitsel iç konuşma",value:.55,display:"d = 0,55"},{label:"Motive edici iç konuşma",value:.37,display:"d = 0,37"},{label:"Önceden alıştırma yapılan programlar",value:.8,display:"d = 0,80"},{label:"Alıştırma yapılmayan programlar",value:.37,display:"d = 0,37"}],note:"32 çalışma, 62 etki büyüklüğü; spor ve motor görevler. Eğitsel iç konuşmanın ince görevlerde etkisi 0,83’tü. Sayılar ortalamadır, gündelik işlere aynen taşınamaz ve bu kurs ayrıca sınanmadı.",sourceId:"sport-self-talk"},photo:{id:"1523497804259-88c4c134ca90",alt:"Pistte koşuya hazırlanan sporcu"}},{id:"suggestion-6",title:"Uykudan önce telkin",minutes:9,goal:"Murphy’nin uyku öncesi tekniğini engel ve planla birlikte uygula.",reading:["Joseph Murphy, 1963 tarihli kitabında uykuya dalmadan önceki mahmur anın telkine en açık an olduğunu anlatır. Dileğini kısa bir cümleye indirip ninni gibi tekrarlamayı, sonucu şimdi oluyormuş gibi kısa bir sahnede görmeyi, örneğin bir arkadaşının seni tebrik ettiğini duymayı ve sahneyi içten bir teşekkürle bitirmeyi önerir. Napoleon Hill de 1937’de hedefi açıkça yazıp bu yazıyı her gün iki kez, gece yatmadan ve sabah kalkınca sesli okumayı önermişti. İkisi de duygunun ve tekrarın önemini vurgular.","Araştırmalar bu tekniklerin bir kısmını destekliyor: 37 çalışmayı birleştiren bir meta-analize göre zihinde prova etmenin performansa küçük ama gerçek bir katkısı var. Paller ve arkadaşlarının derlemesi ise uykunun gün içinde öğrendiklerini pekiştirdiğini, uykuda yeni bilgi öğrenmenin ise çok sınırlı kaldığını gösteriyor. Kappes ve Oettingen’in deneylerinde yalnızca güzel sonucu hayal etmek enerjiyi düşürdü; bu yüzden sahneye gerçek engeli ve bir eğer–o zaman planını ekliyoruz. Bilinçaltının para ya da sağlık çektiği ve düşüncenin hastalığı iyileştirdiği iddiaları ise desteklenmez."],practice:["Bu akşam dileğini beş–altı kelimelik kısa bir cümleye indir ve kâğıda yaz.","Yatakta uykun gelirken cümleyi yavaşça tekrarla ve bir arkadaşının seni tebrik ettiği sahneyi kısa bir süre canlandır.","Sabah bu sonuca giden yoldaki asıl engeli ve “Eğer … olursa, … yapacağım” planını tek satırla yaz."],reflection:"Uykudan önce kurduğun sahne sabah sana neyi hatırlattı?",question:"Uyku öncesi telkin için araştırmalarla en uyumlu yaklaşım hangisi?",options:["Sonucu hayal edip gerçek engeli ve bir eğer–o zaman planını da eklemek.","Uykuda bilinçaltının parayı ve sağlığı kendiliğinden çekmesini beklemek.","Yalnızca güzel sonucu hayal edip hiçbir plan yapmamak."],correct:0,feedback:"Zihinsel prova küçük bir katkı sağlayabilir; ama yalnızca olumlu hayal enerjiyi düşürebilir. Hayali engel ve planla birleştirmek araştırmalarla daha uyumludur.",takeaway:"Akşam sonucu gör, sabah engeli ve ilk adımı yaz.",sources:["murphy-subconscious","hill-autosuggestion","mental-practice","sleep-memory-reactivation","positive-fantasies","mcii","if-then-plans"],technique:{name:"Uyku öncesi telkin",origin:"Joseph Murphy · The Power of Your Subconscious Mind (1963)",steps:["Yatağa uzan, bedenini gevşet ve uykunun getirdiği mahmurluğu bekle.","Dileğini birkaç kelimelik kısa bir cümleye indir: “Sunumum akıcı geçti” gibi.","Bu cümleyi bir ninni gibi, yavaşça ve tekrar tekrar söyle.","Sonucu şimdi oluyormuş gibi kısa bir sahnede gör: bir arkadaşın seni tebrik ediyor, sesini duy.","Sahneye içten bir teşekkür duygusu ekle ve kendini uykuya bırak."],evidence:"Uykudan önce kısa bir prova ve niyet hazırlığa yardım edebilir; zihinsel provanın performansa küçük bir katkısı var. Uykuda yeni bilgi öğrenmek sınırlıdır; bilinçaltının para ya da sağlık çektiği ve hastalığı iyileştirdiği iddiaları desteklenmez, yalnızca olumlu hayal kurmak da enerjiyi düşürebilir.",sourceId:"murphy-subconscious"},visual:{kind:"table",title:"Öğretiler ve araştırmalar",columns:["Yaklaşım","Ne önerir","Araştırmalar ne diyor"],rows:[["Murphy: uyku öncesi","Mahmurken kısa cümle, bitmiş sahne, teşekkür","Prova hazırlığa yardım edebilir; uykuda yeni öğrenme sınırlı"],["Hill: yazılı hedef","Hedefi yaz, sabah ve akşam sesli oku","Hedefi netleştirmek yararlı olabilir; zenginlik çekme iddiası sınanmadı"],["Yalnızca olumlu hayal","Güzel sonucu tekrar tekrar hayal etmek","Deneylerde enerjiyi düşürdü"],["Hayal + engel + plan","Sonucu gör, engeli adlandır, eğer–o zaman planı kur","Meta-analizde küçük–orta etki (g = 0,336)"]],note:"Bu tablo öğretileri küçümsemek için değil, hangi parçanın kanıtla desteklendiğini göstermek için. Telkin tedavinin yerine geçmez."},photo:{id:"1757796859729-270d1e3ad4d5",alt:"Lambanın yandığı komodinde açık kitap"}},{id:"suggestion-7",title:"Kendi telkin kartın",minutes:9,goal:"Cümle, imge, plan ve zamanı tek bir karta topla ve 7 gün sonra gözden geçir.",reading:["Şimdi öğrendiklerini birleştiriyoruz: inanabileceğin bir cümle, adınla seslenmek, kısa bir ipucu kelimesi, ilk adımın imgesi ve bir eğer–o zaman planı. Joe Dispenza, Breaking the Habit of Being Yourself kitabında sabah meditasyonunda eski alışkanlığı fark etmeyi, gün içinde onu yakalayınca kendine “Değiş” demeyi ve olmak istediğin hâli minnet duygusuyla zihninde prova etmeyi önerir. Zihinsel provanın küçük ama gerçek bir katkısı araştırmalarla destekleniyor. Düşüncenin kuantum alanı aracılığıyla olayları değiştirdiği ya da hastalığı iyileştirdiği iddiaları ise desteklenmez.","Louise Hay’in yaygınlaştırdığı ayna çalışmasını da seçenek olarak ekleyebilirsin: aynada kendi gözlerine bakıp cümleni sevecen bir sesle söylemek. Bu çalışmayı sınayan kontrollü bir araştırma bulamadık; başta tuhaf gelmesi olağan. Ama söylerken içindeki itiraz büyüyorsa, 3. dersteki gibi cümleni daha inanılabilir yap ya da kâğıttan okumayı seç. Yedi gün sonra kartını gözden geçir; ilerlemeyi izlemenin hedefe ulaşmayı desteklediği meta-analizlerle gösterildi."],practice:["Bir kartın ön yüzüne inanabileceğin cümleni ve ilk adımının kısa bir imgesini yaz.","Arka yüzüne bir eğer–o zaman planı ve kartı okuyacağın saati yaz.","Takvimine 7 gün sonrası için bir hatırlatma koy ve o gün kartını gözden geçir."],reflection:"Yedi gün sonra kartında neyi aynen tutmak, neyi değiştirmek istersin?",question:"Telkin kartını yedi gün sonra gözden geçirirken hangisi en yararlı?",options:["Hiçbir şey değişmediyse kendimi suçlamak.","Neyin işe yaradığına bakıp cümleyi, imgeyi ya da planı ayarlamak.","Daha iddialı bir cümleyi daha yüksek sesle söylemeye başlamak."],correct:1,feedback:"Gözden geçirme bir sınav değil, ayar zamanıdır. İşe yarayanı tut, zorlayanı daha inanılabilir ve daha küçük hâle getir.",takeaway:"Bir cümle, bir imge, bir plan, bir saat: sonra gözden geçir.",sources:["dispenza-breaking-habit","hay-mirror-work","mental-practice","positive-self-statements","if-then-plans","monitoring"],technique:{name:"Sabah provası",origin:"Joe Dispenza · Breaking the Habit of Being Yourself (2012)",steps:["Sabah güne başlamadan önce 10 dakika sessiz bir yere otur ve birkaç yavaş nefesle gevşe.","Bırakmak istediğin eski bir alışkanlığı fark et: hangi düşünce ve duyguyla başlıyor?","Olmak istediğin hâli tarif et: nasıl düşünür, nasıl davranır, ne hisseder?","Bugün bu hâlle yaşayacağın bir anı zihninde adım adım prova et.","Provayı, o an gerçekleşmiş gibi bir minnet duygusuyla bitir.","Gün içinde eski hâli yakaladığında kendine kısaca “Değiş” de ve provadaki ilk adıma dön."],evidence:"Zihinsel provanın performansı küçük ama anlamlı biçimde artırdığı meta-analizlerle gösterildi. Düşüncenin kuantum alanını etkileyerek olayları değiştirdiği ya da hastalıkları iyileştirdiği iddiaları desteklenmez.",sourceId:"dispenza-breaking-habit"},visual:{kind:"steps",title:"Telkin kartın",steps:[{label:"Cümle",text:"İnanabileceğin, süreci anlatan tek cümle; istersen adınla başlasın."},{label:"İmge",text:"İlk adımı attığın kısa bir sahne."},{label:"Plan",text:"“Eğer … olursa, … yapacağım.”"},{label:"Zaman",text:"Sabah uyanınca ya da akşam yatarken, her gün aynı anda."},{label:"Gözden geçir",text:"7 gün sonra: ne işe yaradı, neyi değiştireceksin?"}],note:"İstersen cümleni aynaya bakarak söyleyebilirsin; rahatsız ediyorsa kâğıttan okumak da yeterli. Kart bir tedavi değildir."},photo:{id:"1484480974693-6ca0a78fb36b",alt:"Deftere onay kutulu bir liste yazan el"}}]},Na={procrastination:{id:"1758598304525-c2bc7aada66d",alt:"Bitkilerle çevrili masada dizüstü bilgisayarla çalışan kadın"},confidence:{id:"1756244834590-b1a32e94df40",alt:"Gün doğarken dağ gölüne bakan kadın"},adhd:{id:"1759984782055-defe1abc0394",alt:"Kulaklıkla masada çalışan genç kadın"}},ja={"procrastination-1":{id:"1552360708-ebcdf76845ac",alt:"Pencere kenarında oturup düşünen kadın"},"procrastination-2":{id:"1448387473223-5c37445527e7",alt:"Merdivende ilk basamağa adım atan ayak"},"procrastination-3":{id:"1553044020-8c90843adf96",alt:"Sarı yapışkan notlar ve kalem"},"procrastination-4":{id:"1778958619388-b529cc4e78e8",alt:"Pencere kenarında çay içen genç kadın"},"procrastination-5":{id:"1506784983877-45594efa4cbe",alt:"Ajandanın üzerinde kahve fincanı"},"confidence-1":{id:"1579017308347-e53e0d2fc5e9",alt:"Açık deftere elle not yazan kişi"},"confidence-2":{id:"1635895752485-99ba511c07e1",alt:"Gün batımında suyun üzerinden geçen basamak taşları"},"confidence-3":{id:"1572020487535-31e268b25e21",alt:"Deftere not alan adam"},"confidence-4":{id:"1573497491208-6b1acb260507",alt:"Masada oturup sohbet eden iki kadın"},"confidence-5":{id:"1748609422318-7301636fb625",alt:"Onay kutulu deftere plan yazan el"},"adhd-1":{id:"1488190211105-8b0e65b80b4e",alt:"Deftere kalemle liste yazan el"},"adhd-2":{id:"1754548930574-6a995e5eb5a7",alt:"Tablette yapılacaklar listesini işaretleyen el"},"adhd-3":{id:"1604344797006-2e4e8b39b79d",alt:"Ahşap masada kum saati"},"adhd-4":{id:"1624207616909-8bc0ca58743b",alt:"Dizüstü bilgisayara yapıştırılmış sarı notlar"},"adhd-5":{id:"1549582100-d67ab35b3507",alt:"Beyaz masada ajanda ve renkli kalemler"}},Ga={motivation:{id:"1790004245013-b347139d5591",alt:"Güneşli orman yolunda koşan adam"},faith:{id:"1767396024869-756a346dc39d",alt:"Kemerli kapıları ve ağaçlarıyla cami avlusu"},manifest:{id:"1676782778930-11b311ec5134",alt:"Dağlara doğru çimenli tepeden yükselen toprak yol"}},Fa={"motivation-1":{id:"1517971129774-8a2b38fa128e",alt:"Pencere kenarında deftere yazan kadın"},"motivation-2":{id:"1581578731509-8ae9c5a3e7d3",alt:"Kapının yanında hazır duran bir çift ayakkabı"},"motivation-3":{id:"1499933374294-4584851497cc",alt:"Masada duran siyah çalar saat"},"motivation-4":{id:"1575478004055-999ebe26dab7",alt:"Yağmurda şemsiyeyle yürüyen kadın"},"motivation-5":{id:"1577950248429-7530424d9682",alt:"Panoya tutturulmuş aylık takvim"},"faith-1":{id:"1778616364918-34490657598f",alt:"Elinde tesbih tutan adam"},"faith-2":{id:"1590682680695-43b964a3ae17",alt:"Toprağa fide diken eller"},"faith-3":{id:"1634906346143-aacbc4c02fec",alt:"Masada gözlüğün yanında teşekkür notu"},"faith-4":{id:"1570739260082-39a84dae80c8",alt:"Ahşap masada yanan fener"},"faith-5":{id:"1710092784814-4a6f158913b8",alt:"Bir kadının diğerine bir tabak yemek uzatması"},"manifest-1":{id:"1768055104910-8c8d213835fb",alt:"Deftere yapılacaklar listesi yazan el"},"manifest-2":{id:"1517363898874-737b62a7db91",alt:"Sıcak ışıkta pencere önünde sessizce oturan kişi"},"manifest-3":{id:"1767134063671-322e6faf9206",alt:"Yapraklı orman yolunu kesen devrilmiş ağaç"},"manifest-4":{id:"1591462391971-9ffc57b382b9",alt:"Renkli yapışkan notlar ve kalemler"},"manifest-5":{id:"1762920738995-f393efe82205",alt:"Ormanda çok yönlü ahşap yön tabelası"}},Ua={focus:{id:"1505330622279-bf7d7fc918f4",alt:"Aydınlık, düzenli bir çalışma masası"},sleep:{id:"1606796913825-2b02883605e9",alt:"Yeşil bitkinin yanında beyaz nevresimli yatak"},calm:{id:"1557316655-8715fdecd2d1",alt:"Dağ eteğinde durgun göl"}},La={"focus-1":{id:"1745474633597-be94033b16d6",alt:"Dizüstü bilgisayarda çalışırken telefona bakan kişi"},"focus-2":{id:"1526045612212-70caf35c14df",alt:"Elinde akıllı telefon tutan kişi"},"focus-3":{id:"1635398235411-2c41ca32ffbc",alt:"Ahşap masanın üzerinde duran telefon"},"focus-4":{id:"1556833232-52da3e4bd5d8",alt:"Patikada yürüyüş yapan kadın"},"focus-5":{id:"1632772998001-cc9bf6f7c852",alt:"Üzerinde iki kalem duran ajanda"},"sleep-1":{id:"1767443522987-a83deb358199",alt:"Ahşap zeminde klasik çalar saat"},"sleep-2":{id:"1527377761-f99968ed8a7f",alt:"Pencereden yere vuran gün ışığı"},"sleep-3":{id:"1743689374053-be49ca407b7c",alt:"Pencere kenarında bir fincan kahve"},"sleep-4":{id:"1789930445611-3b13fd7d6de4",alt:"Küçük masa lambasının ışığında kitap okuyan kişi"},"sleep-5":{id:"1653656120968-accae8452c9e",alt:"Kanepede oturup başka bir kadınla konuşan kadın"},"calm-1":{id:"1758876019128-e76eebf402bd",alt:"Masada başını eline dayamış yorgun kişi"},"calm-2":{id:"1717691526463-975c4119505c",alt:"Ağacın önünde gözleri kapalı duran kadın"},"calm-3":{id:"1758272421829-7028296dee8f",alt:"Oturma odasında yerde esneme yapan kadın"},"calm-4":{id:"1658279366796-e0c28623cd27",alt:"Pencere pervazında oturup dışarı bakan kadın"},"calm-5":{id:"1747764925585-6c2df83b3fd2",alt:"Kahve içip sohbet eden iki kadın"}},_a=[{id:"mcii",title:"Wang, Wang & Gai · 2021 · Hedefe ulaşma meta-analizi",url:"https://www.frontiersin.org/journals/psychology/articles/10.3389/fpsyg.2021.565202/full",type:"research",finding:"21 çalışma, 15.907 katılımcı: hedefi gerçek engelle karşılaştırma ve eğer/o zaman planı birlikte küçük–orta ortalama etki gösterdi (g=0,336).",limitation:"Yayın yanlılığı olası; sonuçlar kişiye ve koşula göre değişir. Bu ODA kursunun etkililiği sınanmadı."},{id:"adhd-cbt",title:"Safren ve ark. · 2010 · Yetişkin ADHD randomize çalışması",url:"https://jamanetwork.com/journals/jama/fullarticle/186469",type:"research",finding:"İlaç kullanan ve belirtileri süren 86 yetişkinde, uzmanların yürüttüğü 12 seanslık BDT aktif karşılaştırmadan daha iyi sonuç verdi.",limitation:"Bu kısa eğitim, araştırmadaki terapi değildir. İlaç kullanmayan kişilere veya çocuklara aynı sonuç çıkarılamaz; takipteki ek tedaviler yorumu sınırlar."},{id:"self-compassion",title:"Han & Kim · 2023 · Öz şefkat meta-analizi",url:"https://pubmed.ncbi.nlm.nih.gov/37362192/",type:"research",finding:"56 randomize çalışmada öz şefkat müdahaleleri kısa vadede stres, kaygı ve depresif belirtilerde küçük–orta ortalama etkiler gösterdi.",limitation:"Genel yanlılık riski yüksek; aktif karşılaştırma ve çevrim içi uygulama verileri daha sınırlı. İncelenen yayın özeti bu alıştırmanın tedavi etkisini kanıtlamaz."},{id:"gratitude",title:"Kirca, Malouff & Meynadier · 2023 · Şükran meta-analizi",url:"https://link.springer.com/article/10.1007/s41042-023-00086-6",type:"research",finding:"25 randomize çalışma, 6.745 kişi: teşekkür ifade etmenin iyi oluş üzerindeki ortalama etkisi nötr karşılaştırmaya göre küçüktü (g=0,22).",limitation:"Zor duyguları bastırma önerisi değildir. Bu psikolojik araştırma dinî iddiaları veya ibadetin klinik etkisini sınamaz."},{id:"habits",title:"Lally ve ark. · 2010 · Günlük yaşamda alışkanlık oluşumu",url:"https://onlinelibrary.wiley.com/doi/10.1002/ejsp.674",type:"research",finding:"96 gönüllünün 12 haftalık takibinde aynı bağlamda tekrar ve otomatikleşme incelendi; süreler kişiler arasında belirgin farklılık gösterdi ve davranışı bir kez yapmamak alışkanlık sürecini belirgin biçimde etkilemedi.",limitation:"Öz bildirime dayalı gözlemsel çalışma; herkes için kesin bir gün sayısı vermez. Yayıncı özeti incelendi."},{id:"monitoring",title:"Harkin ve ark. · 2016 · İlerleme takibi meta-analizi",url:"https://pubmed.ncbi.nlm.nih.gov/26479070/",type:"research",finding:"138 deneysel çalışma, 19.951 kişi: ilerlemeyi izlemeyi artıran müdahaleler hedefe ulaşmada ortalama fayda gösterdi (d=0,40).",limitation:"Farklı hedefler ve takip yöntemleri birleştirildi. Özel notlarını paylaşman gerekmez; burada kullanılan takip ekranı ayrıca sınanmadı. Yayın özeti incelendi."},{id:"nimh",title:"NIMH · Yetişkinlerde ADHD rehberi",url:"https://www.nimh.nih.gov/health/publications/adhd-what-you-need-to-know",type:"guidance",finding:"ADHD günlük işlevleri etkileyen gelişimsel bir durumdur. Değerlendirme ve kişiye uygun tedavi, sağlık uzmanıyla yürütülür.",limitation:"Bir kurs ya da kısa soru tanı koyamaz. Zorlanma kalıcıysa ve günlük yaşamını etkiliyorsa uzman değerlendirmesi alabilirsin."},{id:"quran-trust",title:"Kur’an · Âl-i İmrân 3:159",url:"https://quran.com/3/159",type:"religious",finding:"Ayetin istişare, karar ve tevekkül vurgusu üzerine dinî düşünme.",limitation:"Ders metni ODA yorumudur; ayetin tamamının meali veya bilimsel kanıt değildir."},{id:"quran-ease",title:"Kur’an · İnşirâh 94:5–6",url:"https://quran.com/94/5",type:"religious",finding:"Zorlukla birlikte kolaylık vurgusu üzerine umut ve dayanışma düşüncesi.",limitation:"Belirli bir sıkıntının ne zaman biteceğine dair kişisel sonuç garantisi çıkarılmaz."},{id:"hadith-intention",title:"Sahîh-i Buhârî · 1 · Niyet hadisi",url:"https://sunnah.com/bukhari:1",type:"religious",finding:"Hz. Ömer’in rivayet ettiği, Peygamber’in niyetle ilgili hadisi.",limitation:"Hz. Ömer burada ravidir. Dersin güncel örnekleri hadisin sözleri değil, ODA eğitim uyarlamasıdır."}],Za=[{id:"confidence",title:"Özgüven",subtitle:"Korksan da bir adım.",description:"İçindeki eleştirmeni fark et, güvenli bir deneme seç ve kendi emeğine dayanarak ilerle.",scope:"Gündelik cesaret ve öz şefkat çalışması. Tehlikeli durumlar, travma veya yoğun kaygı için yüzleştirme tedavisi değildir.",outcome:"Sana uygun bir cesaret adımı ve yeniden deneme planı.",lessons:[{id:"confidence-1",title:"Korkuya isim ver, kendine etiket değil",minutes:6,goal:"Bir duyguyla kendin hakkında verdiğin hükmü ayır.",reading:["“Konuşurken heyecanlanıyorum” bir deneyimi anlatır. “Ben yetersizim” ise bütün hayatına yayılan bir hükümdür. Bugün ikinci cümleyi ispatlamaya veya çürütmeye çalışmadan, yaşadığın durumu daha somut tarif edeceğiz.","Bir toplantıda fikir söylemek gibi güvenli, küçük bir durum seç. Korkunun sıfırlanması bu dersin şartı değil. Durum gerçekten tehlikeliyse, sınır koymak ve yardım istemek de cesur bir karardır."],practice:["Yakın zamanda çekindiğin güvenli bir durumu tek cümleyle tarif et.","Kendine yapıştırdığın etiketi fark et; “Şu durumda … hissediyorum” biçiminde yeniden söyle.","Yakın bir arkadaşına vereceğin anlayışlı yanıtı kendin için de sesli veya içinden söyle."],reflection:"Kendine daha adil cümlen ne oldu?",question:"Hangisi durumu kimliğinden ayırır?",options:["Ben hep başarısızım.","Bu konuşmada gerildim; kısa bir cümle hazırlayabilirim.","Bir daha hiç gerilmemeliyim."],correct:1,feedback:"Belirli bir durumu adlandırmak, değiştirilebilir bir sonraki adıma yer açar. Bir duygu bütün kimliğinin özeti değildir.",takeaway:"Korku bir deneyimdir; senin tamamın değil.",sources:["self-compassion"]},{id:"confidence-2",title:"Cesaretin en küçük hâli",minutes:7,goal:"Zor gelen hedefi güvenli ve yapılabilir bir denemeye çevir.",reading:["“Herkesin önünde rahat konuşacağım” büyük ve belirsiz bir beklenti olabilir. Bugünün denemesi yalnızca bir soruyu hazırlamak veya güvendiğin bir kişiye fikrini anlatmak olabilir. Küçük olması, önemsiz olduğu anlamına gelmez.","Kendi seçtiğin adımın kontrolü sende kalsın. Rahatsızlık fazla yükselirse durabilir, daha küçük bir adım seçebilir veya destek isteyebilirsin. Kendini zorlamak için bu kursla yarışman gerekmiyor."],practice:["Çekindiğin işin kolay, orta ve zor üç sürümünü düşün.","Bugün güvenle deneyebileceğin en küçük sürümü seç; nerede yapacağını belirle.","Seçtiğin denemeyi yap veya uygun saat için somut hazırlığını tamamla."],reflection:"Hangi küçük deneme sana şu an uygun?",question:"İlk adım için hangi seçim daha kullanışlı?",options:["En zorunu yapmak zorundayım.","Korku tamamen geçene kadar belirsizce beklemek.","Kendi sınırlarım içinde küçük ve somut bir deneme seçmek."],correct:2,feedback:"Amaç en büyük korkuyu yenmek değil, sana uygun bir davranışı seçebilmektir. Tehlikeye girmen gerekmez.",takeaway:"Cesaret bazen yalnızca bir cümledir.",sources:["mcii","self-compassion"]},{id:"confidence-3",title:"Tahmin ile olanı ayır",minutes:8,goal:"Bir denemeyi yargı yerine gözlemle değerlendir.",reading:["Zihin bir konuşmadan önce pek çok senaryo üretebilir. Denemeden sonra yalnızca utandığın anı hatırlamak da kolaydır. Bu derste bir kamera ne görürdü diye düşün: söylediğin cümle, aldığın yanıt, istediğin yardım.","Örneğin “Sesim titredi ama sorumu sordum” iki gerçeği birlikte tutar. Kendine güven, her denemenin kusursuz olmasına bağlandığında kırılganlaşır; burada başarı ölçün seçtiğin davranışı denemendir."],practice:["Küçük denemenden önceki tahminini hatırla.","Gerçekte olan iki gözlemi yaz veya içinden adlandır; zihin okumayı gözlemden ayır.","Denemediysen bunu dürüstçe kaydet ve bir sonraki denemenin boyutunu küçült."],reflection:"Tahmininden farklı olan neydi?",question:"Hangisi gözlenebilir bir bilgi?",options:["Herkes benimle alay ettiğini düşündü.","Sorumu sordum ve bir kişi yanıt verdi.","Ben böyle bir insanım."],correct:1,feedback:"Kimin ne düşündüğünü varsaymak yerine görülen ve duyulanı kaydet. Bu kayıt bir performans notu değildir.",takeaway:"Bugünkü denemenden bir bilgi çıkar.",sources:["monitoring"]},{id:"confidence-4",title:"İç sesine bir destek cümlesi",minutes:6,goal:"Hata sonrasında kendine hem dürüst hem yardımcı konuş.",reading:["“Hiçbir şey olmadı” demek seni ikna etmeyebilir. “Bu zor geldi; yine de bir cümle kurmayı denedim” daha gerçekçi olabilir. Kendine iyi davranmak, sorumluluktan vazgeçmek anlamına gelmez.","Bir hata varsa düzeltilebilir kısmını seç. Birinden özür dilemek, bilgiyi yeniden kontrol etmek veya bir sonraki görüşme için not hazırlamak somut seçeneklerdir. Kendini aşağılamak bu adımların yerine geçmez."],practice:["Aklındaki sert cümleyi fark et; onu tekrar tekrar okumak zorunda değilsin.","“Bu benim için zordu” diyerek durumu kabul et.","Ardından tek bir destek veya düzeltme adımı ekle."],reflection:"Bir dahaki zor anda kendine hangi cümleyi söylemek istersin?",question:"Destekleyici iç ses nasıl olabilir?",options:["Hata yaptım; düzeltilecek kısmı belirleyebilirim.","Hata yapmışsam değersizim.","Her durumda mükemmelim."],correct:0,feedback:"İlk cümle hem sorumluluğu hem insanlığını korur. Gerçekçi destek, abartılı olumlamaya ihtiyaç duymaz.",takeaway:"Kendine adil olmak, yeniden denemeyi kolaylaştırabilir.",sources:["self-compassion"]},{id:"confidence-5",title:"Kendi cesaret planın",minutes:8,goal:"Önümüzdeki hafta için bir deneme, bir destek ve bir değerlendirme seç.",reading:["Bu kursu bitirmek korkuların biteceği anlamına gelmiyor. Artık duyguyu adlandırma, adımı küçültme ve denemeden bilgi toplama yollarını birlikte kullanabilirsin.","Planına dinlenmeyi ve destek almayı da kat. Bir gün hiçbir deneme yapmaman bütün ilerlemeyi silmez. İşine yaramayan adımı değiştirmek, kendi hayatını ciddiye almaktır."],practice:["Önümüzdeki günlerde deneyeceğin tek bir güvenli davranışı ve zamanını belirle.","“Çekinip ertelemek istersem, önce … yapacağım” diye bir başlangıç planı kur.","Denemenden sonra iki dakikalık değerlendirme ve gerektiğinde ulaşabileceğin bir destek seç."],reflection:"Korksan da atmayı seçtiğin adım ne?",question:"Plan işe yaramazsa?",options:["Kendimi daha sert eleştirmeliyim.","Adımı ve koşulları gözden geçirip gerekirse destek istemeliyim.","Bu, asla değişemeyeceğimi gösterir."],correct:1,feedback:"Bir planın işlemesi koşullara bağlıdır. Gözden geçirme, sürecin olağan bir parçasıdır.",takeaway:"Korksan da, sana uygun bir adım seçebilirsin.",sources:["mcii","monitoring","self-compassion"]}]},{id:"adhd",title:"ADHD ile günlük yaşam",subtitle:"Zihnine uygun bir düzen.",description:"Başlamayı, zamanı görünür kılmayı ve dikkat dağıldığında geri dönmeyi küçük araçlarla dene.",scope:"Yetişkinler için beceri eğitimi; tanı veya tedavi değildir. Kalıcı ve işlevlerini bozan güçlükler için bir sağlık uzmanına başvur. Tedavini uzmanına danışmadan değiştirme.",outcome:"Bir görev listesi, denenmiş bir çalışma aralığı ve geri dönüş planı.",lessons:[{id:"adhd-1",title:"Yükü zihninden kâğıda taşı",minutes:7,goal:"Hatırlamaya çalıştığın işleri tek bir yerde topla.",reading:["ADHD ile yaşarken planı bilmek ve o anda uygulayabilmek farklı güçlükler olabilir. Bu, tembellik veya inanç eksikliği açıklamasına indirgenemez. Birden fazla yerde tutulan işler de gün içinde görünmezleşebilir.","Bugün mükemmel bir sistem kurmayacağız. Bir kâğıt, telefon notu veya ODA defteri seç. Randevu gibi saatli işleri takvime, yapılacak işleri tek listeye koymak bu dersteki deneyimiz."],practice:["İşlerini toplayacağın tek bir liste yeri seç.","Aklındaki en fazla beş işi buraya aktar; hepsini bugün bitirmeyi taahhüt etme.","Saatli bir iş varsa takvimine ekle ve listeyi ne zaman kontrol edeceğini belirle."],reflection:"Listeni gün içinde nerede görebilirsin?",question:"Bu dersin hedefi nedir?",options:["Bütün işleri ezberlemek.","ADHD tanısı koymak.","Hatırlamayı destekleyecek tek bir dış kayıt oluşturmak."],correct:2,feedback:"Dış kayıt hafızanın yükünü azaltmak için bir araçtır. Bu sorular tanı değerlendirmesi değildir.",takeaway:"Her şeyi zihninde taşımak zorunda değilsin.",sources:["adhd-cbt","nimh"]},{id:"adhd-2",title:"İlk görünen hareket",minutes:6,goal:"Büyük işi başlayabileceğin fiziksel bir harekete çevir.",reading:["“Dosyaları hallet” nereden başlayacağını söylemez. “Mavi klasörü açıp ilk belgenin adını yaz” ise gözle görülebilen bir adımdır. Görevi tarif ederken elinin ilk ne yapacağını düşün.","Bu derste süreyi kısa tutabilirsin. Önerilen birkaç dakika bir tedavi dozu veya ideal odak süresi değildir; sana uygun başlangıcı bulmak için bir denemedir."],practice:["Listenden bugün önemli olan tek bir işi seç.","İşi üç küçük harekete ayır; ilkine açık bir fiille başla.","İlk hareketi şimdi dene; takılırsan onu daha da küçült."],reflection:"Senin işinde ilk görünen hareket hangisi?",question:"Hangisi daha açık bir başlangıç?",options:["Hayatımı düzene sokmak.","Ödeme belgesini açıp son tarihi kontrol etmek.","Daha disiplinli olmak."],correct:1,feedback:"Somut fiil ve nesne, başlayacağın yeri gösterir. Büyük hedefi tümden çözmen gerekmiyor.",takeaway:"İşe bir bütün olarak değil, ilk hareketten başlayabilirsin.",sources:["adhd-cbt"]},{id:"adhd-3",title:"Zamanı görünür kıl",minutes:8,goal:"Sana uygun kısa bir çalışma ve mola aralığını dene.",reading:["Bir işin ne kadar süreceğini tahmin etmek zor olabilir. Bugün hedefin uzun süre dayanmak değil; tahmininle gerçek süreni karşılaştırmak. İstersen iki, beş veya on dakikalık rahat bir başlangıç seç.","Zamanlayıcı çalınca devam etmek zorunda değilsin. Bulunduğun yeri işaretle, kısa bir mola ver ve yeniden başlamak isteyip istemediğine karar ver. Sabit bir yöntemin herkese uyması gerekmiyor."],practice:["Küçük iş için süre tahmini yap ve bir zamanlayıcı hazırla.","Kendine uygun aralık boyunca dene; erken bırakman gerekirse bunu da gözlem say.","Bittiğinde ne kadar ilerlediğini kontrol et ve bir sonraki aralığı ayarla."],reflection:"Hangi aralık sana daha uygun göründü?",question:"Zamanlayıcı çalınca hangi yaklaşım uygundur?",options:["Durumu kontrol edip mola veya devam kararı vermek.","Ne olursa olsun çalışmaya zorlamak.","Süre kısa geldiyse kendimi suçlamak."],correct:0,feedback:"Zamanlayıcı bir gözlem aracıdır. Çalışma aralığı, ihtiyaçlarına göre değişebilir.",takeaway:"Süreyi tahmin et, dene, kendine göre ayarla.",sources:["adhd-cbt","monitoring"]},{id:"adhd-4",title:"Dikkat dağıldığında geri dön",minutes:7,goal:"Dikkat dağıtan bir düşünceyi kaybedilmeden ertelemenin yolunu dene.",reading:["İşin ortasında aklına başka bir iş gelebilir. Onu unutma korkusuyla hemen peşinden gitmek, ilk işin yeniden başlamasını zorlaştırabilir. Yanına “sonra bakacağım” başlıklı küçük bir alan koy.","Acil ve güvenlikle ilgili ihtiyaçlar elbette bekletilmez. Geri kalan düşünceyi birkaç kelimeyle kaydet, sonra önündeki bir sonraki harekete dön. Kaç kere dağıldığını bir kusur listesine çevirmene gerek yok."],practice:["Çalışma alanından kaldırabileceğin tek bir dikkat dağıtıcı seç.","Aklına gelen acil olmayan işi “sonra” alanına not et.","Başladığın işin kaldığın yerini parmağınla veya bir işaretle bulup bir hareket daha dene."],reflection:"Geri dönmene hangi işaret yardımcı oldu?",question:"Aklına acil olmayan başka bir iş gelirse?",options:["Mutlaka hemen o işe geçmek.","Kısa bir not alıp seçtiğim işe dönmeyi denemek.","Dikkatim dağıldığı için denemeyi çöpe atmak."],correct:1,feedback:"Kayıt, düşünceyi tutmana ve önceliğe dönmene yardımcı olabilir. Acil ihtiyaçlarda planı değiştirmek uygundur.",takeaway:"Dikkatin dağılsa da geri dönüş için bir iz bırakabilirsin.",sources:["adhd-cbt"]},{id:"adhd-5",title:"Sistemi kendine uydur",minutes:8,goal:"İşe yarayan araçları seç ve destek ihtiyacını belirle.",reading:["Bir listeyi kullanmamak, liste kullanamayacağın anlamına gelmez. Liste görünür değildi, çok uzundu veya kontrol saati uygun değildi. Aracın hangi noktada zorlandığını incele.","Kalıcı dikkat, dürtüsellik veya düzenleme güçlükleri günlük yaşamını etkiliyorsa bir uzmana bunları somut örneklerle anlatabilirsin. Bu kursu bitirmiş olmak profesyonel desteğe gerek kalmadığı anlamına gelmez."],practice:["Son derslerden işine yarayan bir aracı ve zorlanan bir noktayı seç.","Gelecek üç deneme için yalnızca bir değişiklik yap: daha kısa liste, başka saat veya daha görünür kayıt.","Gerekliyse güvenilir bir destek kişisi ya da sağlık uzmanıyla konuşurken anlatacağın bir günlük yaşam örneği belirle."],reflection:"Hangi aracı koruyacak, hangisini değiştireceksin?",question:"Güçlükler yaşamımı belirgin etkiliyorsa?",options:["Kursu tekrar etmek her zaman tedavinin yerine geçer.","Bu yalnızca irade sorunudur.","Bir sağlık uzmanıyla değerlendirme ve destek seçeneklerini konuşabilirim."],correct:2,feedback:"Günlük araçlar destek olabilir; tanı ve tedavi için bireysel değerlendirme gerekir.",takeaway:"Sistem sana hizmet etsin; gerektiğinde yardım iste.",sources:["nimh","adhd-cbt","monitoring"]}]},{id:"motivation",title:"Motivasyon",subtitle:"Başlamayı kolaylaştır.",description:"İsteğini küçük bir davranışa bağla, engellere hazırlan ve ritmin bozulduğunda geri dön.",scope:"Gündelik hedefler için eğitim. Sürekli isteksizlik, bitkinlik veya işlev kaybı yalnızca motivasyon sorunu olmayabilir; destek almak uygundur.",outcome:"Bir başlangıç işareti, engel planı ve haftalık değerlendirme.",lessons:[{id:"motivation-1",title:"Bu hedef neden senin?",minutes:6,goal:"Başkalarının beklentisiyle kendi isteğini ayır.",reading:["Bir hedef kulağa iyi gelebilir ama hayatında karşılığı olmayabilir. Bugün “Bunu yaparsam günümde ne değişsin istiyorum?” sorusunu kullan. Daha çok kitap okumak; merakına, öğrenmeye veya sakin bir zamana hizmet edebilir.","İsteğinin sana ait olup olmadığını anlamak için kimse görmese de bunu isteyip istemediğini düşün. Şu an önemini kaybetmiş bir hedefi küçültmek veya bırakmak da bir seçimdir."],practice:["Aklındaki bir hedefi seç.","Bu hedefin günlük hayatında hizmet etmesini istediğin şeyi adlandır.","Önümüzdeki hafta denemeye değer bulduğun tek davranışı seç."],reflection:"Bu davranış hayatında neye yer açacak?",question:"Hedefi netleştiren soru hangisi?",options:["Herkes beni nasıl görür?","Bunu yapınca günümde ne değişmesini istiyorum?","En iddialı hedef hangisi?"],correct:1,feedback:"Kendi hayatındaki somut karşılık, hedefin büyüklüğünden daha kullanışlı bir başlangıçtır.",takeaway:"Önce senin için anlamını bul.",sources:["mcii"]},{id:"motivation-2",title:"Başlangıcı küçült",minutes:6,goal:"Davranışın az emek isteyen ilk sürümünü hazırla.",reading:["“Her akşam bir bölüm okuyacağım” yoğun bir günde ağır gelebilir. Bir sayfa, kitabı açmak veya önce okunacak yeri seçmek başlangıcı kolaylaştıran seçeneklerdir. Bu alt sınır bir tavan değildir; istersen devam edebilirsin.","Malzemenin nerede durduğu da başlangıcın parçasıdır. Kitabını görünür yere koymak, dosyanı önceden açmak veya ayakkabını hazırlamak bugün yapabileceğin küçük düzenlemelerdir."],practice:["Hedef davranışının çok kısa sürümünü yaz veya söyle.","Gerekli tek malzemeyi kolay ulaşılır yere koy.","Kısa sürümü bir kez dene; devam edip etmemeyi sonra seç."],reflection:"Başlamanın önündeki hangi sürtünmeyi kaldırdın?",question:"Küçük başlangıç ne işe yarar?",options:["Hedefe kesin ulaşmayı garanti eder.","Büyük hedefi sonsuza kadar yasaklar.","İlk hareketin gerektirdiği çabayı azaltmak için denenir."],correct:2,feedback:"Bu bir başlangıç tasarımıdır, sonuç garantisi değildir. Boyutu kendi koşullarına göre seç.",takeaway:"Başlamak için bütün yolu bitirmen gerekmiyor.",sources:["mcii","habits"]},{id:"motivation-3",title:"Bir işarete bağla",minutes:7,goal:"Davranışın başlayacağı zamanı veya durumu belirle.",reading:["“Daha sonra yaparım” gün içinde kaybolabilir. “Akşam çayını masaya koyunca kitabı açacağım” başlangıcın nerede olduğunu gösterir. Hayatında zaten olan, makul ölçüde düzenli bir an seç.","Aynı bağlamda tekrar alışkanlık araştırmalarında incelenir; oluşma süresi herkes için aynı değildir. Bugünün görevi alışkanlığı tamamlamak değil, kendi başlangıç işaretini sınamaktır."],practice:["Gününde zaten bulunan bir zaman veya olay seç.","“... olduğunda, ... yapacağım” cümlesini tamamla.","İşaretin gerçekleştiği ilk uygun anda kısa davranışı dene veya yerini hazırla."],reflection:"Senin başlangıç işaretin ne?",question:"Hangi plan daha somut?",options:["Bir ara çalışırım.","İlham gelirse başlarım.","Kahvaltıdan sonra masada iki dakika notlarıma bakarım."],correct:2,feedback:"Zaman, yer ve davranış belli olunca planı gerçekten deneyip değerlendirebilirsin.",takeaway:"Niyetine bir başlangıç anı ver.",sources:["mcii","habits"]},{id:"motivation-4",title:"Engeli hesaba kat",minutes:8,goal:"Öngörülebilir bir engel için uygulanabilir yedek plan kur.",reading:["Bir hedefi istemek, karşına çıkacak engelleri yok etmez. Eve yorgun gelmek, malzemeyi bulamamak veya telefona dalmak farklı engellerdir; hepsine aynı çözüm gerekmez.","Kontrolün dışındaki koşulları kendine yükleme. Değiştirebildiğin küçük kısmı seç. “Çok yorgunsam bir sayfa yerine bir paragraf okuyacağım” veya “Hastaysam dinlenip uygun olduğumda döneceğim” de geçerli bir plandır."],practice:["Planını en sık bozan bir durumu belirle.","Değiştirebildiğin kısmı seç; gerçek bir ihtiyaç varsa onu önceliklendir.","“Eğer ... olursa, o zaman ... yapacağım” diye küçük bir yedek yanıt oluştur."],reflection:"Engelin ve yedek yanıtın ne?",question:"İyi bir engel planı nasıl olur?",options:["Hiç engel çıkmayacağını varsayar.","Belirli bir duruma uygulanabilir bir yanıt bağlar.","Her koşulda aynı tempoyu zorunlu kılar."],correct:1,feedback:"Planın gerçek hayatına uyum sağlamalı. Gerektiğinde dinlenmek veya hedefi değiştirmek de uygulanabilir yanıttır.",takeaway:"Engeli görmek, vazgeçmek demek değildir.",sources:["mcii"]},{id:"motivation-5",title:"Kaçırınca geri dön",minutes:7,goal:"Suçluluk yerine bilgiyle bir sonraki denemeyi düzenle.",reading:["Ritmin bir gün bozulması, önceki denemelerin değersiz olduğu anlamına gelmez. Kaçırılan günleri telafi etmek için iş yükünü iki katına çıkarmak zorunda değilsin. Bir sonraki uygun başlangıç işaretine geri dönebilirsin.","Haftalık kısa kontrolünde yalnızca kaç kez yaptığını değil, neyin yardımcı olduğunu da düşün. Artık ihtiyaç duymadığın veya sana uygun olmayan bir hedef varsa değiştir."],practice:["Son denemeni yaptım, kısmen yaptım veya yapamadım diye dürüstçe değerlendir.","İşe yarayan bir koşulu veya değiştirebileceğin tek noktayı belirle.","Sonraki küçük denemeyi seç ve haftada bir bakacağın kısa bir kayıt oluştur."],reflection:"Bir sonraki uygun başlangıç anın ne zaman?",question:"Bir denemeyi kaçırdıktan sonra?",options:["Uygun bir sonraki anda küçük sürümle yeniden denemek.","Bütün ilerlemeyi silinmiş saymak.","Ertesi gün kendimi iki kat zorlamak."],correct:0,feedback:"Geri dönüş planı sürdürülebilirliği sınamak içindir. Kaçırılan deneme senin değerini ölçmez.",takeaway:"Yeniden başlamak da ilerlemenin bir parçası.",sources:["habits","monitoring"]}]},{id:"faith",title:"İnanç",subtitle:"Tevekkül, şükür ve emek.",description:"Niyetini dinle, şükrünü somutlaştır ve umuduna bugün yapılabilecek bir iyilik ekle.",scope:"İslami düşünme ve gönüllü günlük uygulamalar. Dinî kaynaklarla psikolojik araştırmalar ayrı gösterilir; kaygı veya zorlanma iman eksikliği sayılmaz.",outcome:"Kendine ait bir niyet, teşekkür ifadesi ve küçük iyilik planı.",lessons:[{id:"faith-1",title:"Niyetine dön",minutes:6,goal:"Bugünkü bir işin arkasındaki niyeti fark et.",reading:["Buhârî’nin ilk hadisinde niyet vurgulanır; rivayeti aktaran Hz. Ömer’dir, söz Peygamber’e aittir. Bu ders, o kaynaktan hareketle günlük bir işi neden yaptığını düşünmen için hazırlanmış özgün bir uygulamadır.","Birine gösterişsizce yardım etmek, öğrenmek veya verdiğin sözü tutmak gibi bir iş seçebilirsin. Niyetini kusursuzlaştırmaya çalışarak hareketsiz kalmana gerek yok; dürüstçe bakıp davranışını seç."],practice:["Bugün yapacağın sıradan bir işi seç.","Bu işin kime ve nasıl fayda sağlamasını istediğini düşün.","Niyetini davranışa bağlayan küçük bir hazırlık yap."],reflection:"Bugünkü niyetini kendi sözlerinle nasıl anlatırsın?",question:"Bu derste hadisle uygulamanın ilişkisi nedir?",options:["Güncel alıştırmanın her cümlesi hadistir.","Hadis kaynağı ile ODA’nın günlük uygulama yorumu ayrıdır.","Bilimsel çalışma hadisin doğruluğunu kanıtlamıştır."],correct:1,feedback:"Dinî kaynak açıkça belirtilir; güncel örnek ve alıştırmalar ODA’nın yorumudur.",takeaway:"Niyetini küçük bir emekle görünür kıl.",sources:["hadith-intention","mcii"]},{id:"faith-2",title:"Tevekküle hazırlık eşlik etsin",minutes:7,goal:"Yapabileceğin hazırlıkla kontrol edemediğin sonucu ayır.",reading:["Âl-i İmrân 3:159’da istişare, karar verme ve Allah’a tevekkül bir arada yer alır. Bu dersin düşünme sorusu şu: Elinden gelen hangi hazırlığı bugün yapabilirsin?","Bir sınavın sonucunu garanti edemezsin; bir konuyu çalışabilir ve anlamadığın yeri sorabilirsin. Belirsizlik hissetmek, emek vermediğin veya güvenmediğin anlamına gelmez."],practice:["Aklını meşgul eden bir işi seç.","Yapabileceğin hazırlığı ve kontrolün dışındaki kısmı ayrı ayrı adlandır.","Bir küçük hazırlık ya da güvendiğin birinden görüş alma adımı seç."],reflection:"Bugün sorumluluğunu alabileceğin bölüm hangisi?",question:"Bu dersin tevekkül uygulaması hangisi?",options:["Sonucu kesinmiş gibi kabul etmek.","Hazırlığı tamamen bırakmak.","Elimden geleni yapıp sonucu tümüyle kontrol edemediğimi kabul etmek."],correct:2,feedback:"Bu, ayetin günlük yaşama yönelik ODA yorumudur. Sonucun istediğin gibi olması vaat edilmez.",takeaway:"Bir adım emek, belirsizliğe biraz yer.",sources:["quran-trust","mcii"]},{id:"faith-3",title:"Şükrü bir insana ulaştır",minutes:7,goal:"İçten bir teşekkür ifadesi hazırla.",reading:["Bugün iyi gelen tek bir davranışı hatırla: dinleyen bir arkadaş, işini kolaylaştıran biri, küçük bir incelik. İstersen o kişiye neyin sana yardımcı olduğunu anlatan kısa bir teşekkür yaz. Göndermek senin seçimin.","Şükretmek, yaşadığın sıkıntıyı inkâr etmek değildir. Hem yorulmuş hem minnettar hissedebilirsin. Teşekkür araştırmaları psikolojik iyi oluşu inceler; inancın doğruluğunu veya belirli bir ibadetin etkisini kanıtlama amacı taşımaz."],practice:["Teşekkür etmek istediğin güvenli bir kişiyi veya küçük bir iyiliği hatırla.","“Şunu yaptığında bana şu konuda yardımcı oldun” diye somut bir cümle kur.","Cümleni kendine saklamayı veya uygun buluyorsan iletmeyi seç."],reflection:"Bu iyilikte seni etkileyen neydi?",question:"Şükran çalışması zor duygularla nasıl bir arada olabilir?",options:["Sıkıntıyı yok saymak gerekir.","İyi geleni fark ederken zorlanmayı da kabul edebilirim.","Teşekkür edersem hiçbir sorunum kalmaz."],correct:1,feedback:"İki duygu aynı anda bulunabilir. Teşekkür zorunlu bir olumlu his üretme görevi değildir.",takeaway:"İyi geleni fark et; acını susturmak zorunda değilsin.",sources:["gratitude","self-compassion"]},{id:"faith-4",title:"Zorlukta bir dayanak",minutes:6,goal:"Umudu bugünkü bir destek veya bakım adımıyla buluştur.",reading:["İnşirâh 94:5–6’daki zorlukla beraber kolaylık vurgusu üzerine düşünebilirsin. Bu ayetlerden, kişisel sıkıntının belirli bir tarihte biteceği sonucunu çıkarmıyoruz. Dersin odağı, bu günün içinde bir dayanak aramak.","Dua etmek, güvendiğin biriyle konuşmak, dinlenmek veya profesyonel destek istemek senin için anlamlı seçenekler olabilir. Yardıma ihtiyaç duyman, inancının değerini azaltmaz."],practice:["Bugün seni taşıyabilecek bir kişiyi, pratiği veya güvenli alanı belirle.","İhtiyacını tek bir açık cümleye çevir: “Bugün ... desteğine ihtiyacım var.”","Mümkünse bu desteğe yaklaşan küçük bir adım at; dua etmek istersen kendi sözlerini kullan."],reflection:"Bugün senin dayanağın ne olabilir?",question:"Yardım istemek için hangisi daha uygun?",options:["Zorlandığımı kabul edip güvenilir destek aramak.","İnançlıysam asla zorlanmamalıyım demek.","Her şeyi tek başıma çözmek zorundayım demek."],correct:0,feedback:"Desteğe ihtiyaç duymak insanîdir. Bu ders güçlüğü ahlaki veya dinî bir kusur olarak yorumlamaz.",takeaway:"Umuda yer açarken bir desteğe de uzanabilirsin.",sources:["quran-ease","self-compassion"]},{id:"faith-5",title:"Küçük iyiliğe devam",minutes:8,goal:"Niyet, teşekkür ve emeği sana uygun bir günlük davranışta birleştir.",reading:["Bir iyilik planının büyük, görünür veya masraflı olması gerekmez. Birini dikkatle dinlemek, ortak alanı düzenlemek veya verilen sözü takip etmek de seçebileceğin davranışlardır.","Kendi sınırlarını gözet. Bütün yükleri üstlenmek zorunda değilsin. Bugün bir küçük davranış seç, ne zaman yapacağını belirle ve sonrasında sende ne bıraktığına bak."],practice:["Sınırlarına uygun, ücretsiz ve küçük bir iyilik seç.","Ne zaman, nerede ve nasıl yapacağını belirle; karşılık beklemeyi şart hâline getirme.","Sonrasında niyetinle davranışının ilişkisini kısaca değerlendir; tekrarın sana uygun olup olmadığına karar ver."],reflection:"Günlük hayatına taşımak istediğin küçük iyilik ne?",question:"Sürdürülebilir iyilik planı hangisi?",options:["Herkesin bütün sorununu üstlenmek.","Karşılık almayı garanti etmek.","Sınırlarımı gözeten, somut ve gönüllü bir davranış seçmek."],correct:2,feedback:"Küçük, gönüllü ve sınırları belli bir davranış, gerçekten uygulanabilecek bir plan verir.",takeaway:"Niyetine bugün yapılabilir bir iyilik ekle.",sources:["hadith-intention","mcii","monitoring"]}]},{id:"manifest",title:"Manifest",subtitle:"Niyetten eyleme.",description:"Ne istediğini netleştir, süreci zihninde prova et, gerçek engeli gör ve ilk adımını planla.",scope:"Burada manifest; niyet, hazırlık ve eylem pratiğidir. Düşüncenin kuantum yoluyla olayları yönettiği veya dileklerin kesin gerçekleşeceği iddia edilmez.",outcome:"Bir hedef, zihinsel prova, engel yanıtı ve gözden geçirme tarihi.",lessons:[{id:"manifest-1",title:"Dileğini davranışa çevir",minutes:6,goal:"İstediğin sonuçla bugün yapabileceğin işi ayır.",reading:["“Daha iyi bir iş istiyorum” bir sonuç isteğidir. “Bu hafta özgeçmişimin ilk bölümünü düzenleyeceğim” ise kendi davranışına ilişkin bir hedeftir. Başkalarının kararını kontrol edemezsin; hazırlanacağın kısmı seçebilirsin.","Bu kursta hayal kurmaya yer var. Hayalin yanına koşullarını, kaynaklarını ve emeğini de koyacağız. Bir fırsatın gelmemesini yeterince olumlu düşünmediğinle açıklamayacağız."],practice:["Önem verdiğin bir dileği tek cümleyle yaz veya düşün.","Bu dileğe yaklaşırken kontrol edebileceğin bir davranışı seç.","Davranışı küçük bir bitiş ölçütüyle tarif et: örneğin üç satır taslak."],reflection:"Dileğinin bugünkü davranış karşılığı ne?",question:"Hangisi doğrudan seçebileceğin bir davranış?",options:["İşverenin beni kesin seçmesi.","Yarın özgeçmişimin üç satırını düzenlemek.","Hiç aksilik yaşanmaması."],correct:1,feedback:"Başkalarının kararını garanti edemezsin. Kendi hazırlığını somutlaştırabilirsin.",takeaway:"Niyetine dokunabileceğin bir iş ver.",sources:["mcii"]},{id:"manifest-2",title:"Sadece sonucu değil, yolu da gör",minutes:7,goal:"İlk hareketin kısa zihinsel provasını yap.",reading:["İstediğin sonuca ulaşmış olmanın senin için ne ifade edeceğini bir an düşün. Ardından sahneyi bugüne getir: nerede oturuyorsun, hangi dosyayı açıyorsun, ilk satırda ne yazıyorsun? Bu bir hazırlık alıştırmasıdır.","Gözlerini kapatmak zorunda değilsin. Canlı görüntüler oluşmuyorsa adımları kelimelerle tarif etmen yeterli. Prova, gerçek denemenin yerine geçmez; onu başlatacak ayrıntıyı seçmene yardımcı olmak için var."],practice:["Hedefin hayatında oluşturmasını istediğin bir farkı adlandır.","İlk iki hareketi zihninde veya kelimelerle sıraya koy.","Provanın ardından bir hazırlık hareketini gerçekten yap."],reflection:"Zihinsel provada hangi eksik hazırlığı fark ettin?",question:"Zihinsel prova bu kursta ne anlama gelir?",options:["Gerçek eyleme hazırlık için bir alıştırma.","Düşünceyle dış olayları kesin kontrol etmek.","Denemeye ihtiyaç bırakmamak."],correct:0,feedback:"Prova bir hazırlıktır. Eylem ve dış koşulların yerini almaz; bu tek alıştırmanın bağımsız etkisi kanıtlanmış sayılmaz.",takeaway:"Hayalin ardından ilk hareketi gör.",sources:["mcii"]},{id:"manifest-3",title:"Gerçek engelle karşılaş",minutes:8,goal:"İsteğinle mevcut durum arasındaki bir engeli açıkça tanımla.",reading:["İstenen geleceği düşünmekten sonra mevcut duruma bak: başlamakta çekinmek, planın çok büyük olması veya gereken bilgiye erişememek. Engel ne kadar somutsa vereceğin yanıt da o kadar açık olabilir.","Bütün engeller içsel değildir. Zaman, para, bakım sorumluluğu ve erişim gibi koşullar gerçektir. Kontrolün dışındaki bir engeli kişiliğinin kusuru olarak ele alma; hedefin boyutunu veya zamanını değiştirmek gerekebilir."],practice:["Hedefin önündeki en yakın engeli adlandır.","Engelin hangi kısmını etkileyebildiğini, hangi kısmı için destek veya zaman gerektiğini ayır.","Şimdi uygulanabilir değilse hedefi küçült veya uygun bir zamana ertele."],reflection:"Engeline daha gerçekçi bakınca planında ne değişti?",question:"Dış koşullar engel oluşturduğunda?",options:["Yeterince inanmadığım için olduğunu varsaymalıyım.","Koşulları yok saymalıyım.","Destek, zamanlama veya hedef boyutunu yeniden değerlendirebilirim."],correct:2,feedback:"Gerçekçi plan, dış koşulları hesaba katar. Sonuçlar yalnızca düşüncelerinle belirlenmez.",takeaway:"Engeli dürüstçe görmek, planına yön verir.",sources:["mcii"]},{id:"manifest-4",title:"Eğer olursa, o zaman",minutes:7,goal:"Bir engel işaretine küçük bir yanıt bağla.",reading:["Önceki derste seçtiğin engeli şimdi bir plana çevir. Örneğin “Dosyayı açınca nereden başlayacağımı bilemezsem, yalnızca başlığı yazacağım.” Tetikleyicisi belli, küçük ve uygulanabilir bir yanıt seç.","Olumlama kullanmak istersen gerçekçi olsun: “Her şeyi başarırım” yerine “İlk taslağı deneyebilirim.” Cümlenin değeri evreni yönetmesinde değil, sana seçtiğin davranışı hatırlatmasında."],practice:["Bir engel işaretini “Eğer ...” biçiminde tarif et.","“O zaman ...” kısmına tek bir küçük davranış yaz.","Planın elindeki zaman ve araçlarla yapılabilir olup olmadığını kontrol et; bir kez prova et."],reflection:"Senin eğer/o zaman cümlen ne?",question:"Hangi plan denenebilir?",options:["Her şey kendiliğinden düzelecek.","Dosyayı açınca takılırsam önce başlığı yazacağım.","İyi enerji gönderirsem bütün engeller kaybolur."],correct:1,feedback:"İkinci seçenek belirli bir duruma gözlenebilir bir davranış bağlar. Araştırmalarda incelenen yaklaşım buna benzer eylem planlamasıdır.",takeaway:"İsteğini bir başlangıç yanıtına bağla.",sources:["mcii"]},{id:"manifest-5",title:"Dene, bak, yeniden seç",minutes:8,goal:"Planını gerçek hayatta değerlendirip sonraki adımını seç.",reading:["Hedefe yaklaşırken yaptıklarına bakmak, planın hangi bölümünün işlediğini anlamana yardım edebilir. Sadece sonucu değil, denediğin davranışı, karşılaştığın koşulu ve öğrendiğin şeyi de kaydet.","İstenen sonuç oluşmazsa bunu kötü düşünce, düşük enerji veya inanç eksikliğiyle açıklamak zorunda değilsin. Bazen başka bir yol, daha fazla destek veya farklı bir hedef gerekir. Seçimini gözden geçirebilirsin."],practice:["İlk küçük denemeni yap veya ne zaman yapacağını kesinleştir.","Sonucu kontrol etmek için makul bir gün belirle; “Ne denedim, ne öğrendim?” sorularını kullan.","Devam etme, küçültme, destek alma veya hedefi değiştirme seçeneklerinden uygun olanı seç."],reflection:"Planını hangi gün ve hangi bilgiye bakarak gözden geçireceksin?",question:"İstenen sonuç gelmediğinde en yararlı değerlendirme?",options:["Düşüncelerim yeterince güçlü değildi.","Denediğim davranışları ve koşulları inceleyip sonraki seçimi yapmak.","Gerçeğe bakmadan aynı beklentiyi sürdürmek."],correct:1,feedback:"Planı gerçekle karşılaştırmak yeni bilgi sağlar. Hiçbir kurs sonucu garanti etmez; kendi payını ve dış koşulları birlikte değerlendirebilirsin.",takeaway:"Hayaline emek ver; gerçeğin öğrettiğine de yer aç.",sources:["monitoring","mcii"]}]}],Ja=[..._a,...Aa,...Da,...Ha,...Pa,...Ea,...Ma,...qa],Va={...Na,...Ga,...Ua},$a={...ja,...Fa,...La},k=e=>({...e,photo:e.photo??Va[e.id],lessons:e.lessons.map(a=>({...a,visual:a.visual??z[a.id],photo:a.photo??$a[a.id]}))}),Qa=[Ka,Ia,...Za,Ca,Oa,Wa,Ya,Ra,...je].map(e=>k({...e,lang:"tr",lessons:e.lessons.map(a=>{const i=Ta[a.id];return!i||a.deeper?a:{...a,deeper:i.deeper,example:i.example,sources:[...new Set([...a.sources??[],...i.sources??[]])]}})})),y=[...Ja,...Ge,...xa],g=["turning-day","procrastination","confidence","adhd","motivation","faith","manifest","focus","sleep","calm","meditation","suggestion","identity","state","optimism","meaning","stoic","compassion"],c=e=>new Map(e.map(a=>[a.id,a])),r=c(Qa),n=c(Se.map(e=>k({...e,lang:"en"}))),v={es:()=>s(()=>import("./index-XyNCE9F6.js"),[]).then(e=>({COURSES:e.ES_COURSES,SOURCES:e.ES_SOURCES})),fr:()=>s(()=>import("./index-Dz-K7B1C.js"),[]).then(e=>({COURSES:e.FR_COURSES,SOURCES:e.FR_SOURCES})),de:()=>s(()=>import("./index-LizD1FgP.js"),[]).then(e=>({COURSES:e.DE_COURSES,SOURCES:e.DE_SOURCES})),it:()=>s(()=>import("./index-DHDPLAyG.js"),[]).then(e=>({COURSES:e.IT_COURSES,SOURCES:e.IT_SOURCES}))},u